--
-- Name: action_intent_semantic_digest(text, text, text, text, boolean, boolean, boolean, text, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.action_intent_semantic_digest(p_action_intent_id text, p_resource_type text, p_operation_class text, p_risk_class text, p_maker_checker_required boolean, p_step_up_required boolean, p_idempotency_required boolean, p_existence_disclosure text, p_payload_disclosure text, p_evidence_class text) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT sha256(
    convert_to(p_action_intent_id, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_resource_type, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_operation_class, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_risk_class, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_maker_checker_required::text, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_step_up_required::text, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_idempotency_required::text, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_existence_disclosure, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_payload_disclosure, 'UTF8') || decode('00', 'hex') ||
    convert_to(p_evidence_class, 'UTF8')
  )
$$;


ALTER FUNCTION openpc.action_intent_semantic_digest(p_action_intent_id text, p_resource_type text, p_operation_class text, p_risk_class text, p_maker_checker_required boolean, p_step_up_required boolean, p_idempotency_required boolean, p_existence_disclosure text, p_payload_disclosure text, p_evidence_class text) OWNER TO openpc_control_owner;

--
-- Name: administration_resource_permits(text[], text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.administration_resource_permits(resources text[], target text, action text, participant uuid, principal uuid, authenticated_session uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(target=ANY(resources) OR '*'=ANY(resources) OR (
   action IN('ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-IDENTITY_DELETE_SESSION-V1')
   AND authenticated_session IS NOT NULL AND target=authenticated_session::text
   AND ('urn:openpc:self-session:'||principal::text)=ANY(resources)
   AND openpc.matches_participant(participant)
   AND EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=participant
     AND s.session_id=authenticated_session AND s.principal_id=principal AND s.state='ACTIVE'
     AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp()
     AND ((s.context_mode='PARTICIPANT' AND openpc.matches_privacy(s.privacy_domain_id))
       OR (s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL AND EXISTS(
         SELECT 1 FROM control.participant p WHERE p.participant_id=participant
           AND openpc.matches_privacy(p.root_privacy_domain_id)))))
 ),false)
$$;


ALTER FUNCTION openpc.administration_resource_permits(resources text[], target text, action text, participant uuid, principal uuid, authenticated_session uuid) OWNER TO openpc_control_owner;

--
-- Name: administration_resource_permits(text[], text, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.administration_resource_permits(resources text[], target text, action text, participant uuid, principal uuid, authenticated_session uuid, selected_envelope uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE selected control.authority_envelope;
BEGIN
 SELECT * INTO selected FROM control.authority_envelope e WHERE e.participant_id=participant AND e.authority_envelope_id=selected_envelope;
 IF NOT FOUND THEN RETURN false; END IF;
 IF selected.representation<>'RECOVERY_V1' THEN
  RETURN openpc.administration_resource_permits(resources,target,action,participant,principal,authenticated_session);
 END IF;
 IF selected.principal_id IS DISTINCT FROM principal OR NOT (action=ANY(selected.action_intent_ids))
  OR NOT (resources<@selected.resource_ids) OR NOT openpc.platform_recovery_envelope_current(selected_envelope) THEN RETURN false; END IF;
 IF openpc.administration_resource_permits(resources,target,action,participant,principal,authenticated_session) THEN RETURN true; END IF;
 -- The consumed preparation remains immutable provenance of this exact
 -- continuation. Its approval can be read, never resumed or decided again.
 IF action='ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1' AND EXISTS(
   SELECT 1 FROM control.platform_recovery_case fresh
   JOIN control.platform_recovery_enrollment source ON source.participant_id=fresh.participant_id
    AND source.privacy_domain_id=fresh.privacy_domain_id AND source.enrollment_id=fresh.enrollment_id
   JOIN control.platform_scope_replacement replacement ON replacement.participant_id=fresh.participant_id
    AND replacement.privacy_domain_id=fresh.privacy_domain_id
    AND replacement.replacement_id::text=fresh.intent#>>'{continuation,replacementId}'
   JOIN control.mutation_candidate prepared ON prepared.participant_id=replacement.participant_id
    AND prepared.privacy_domain_id=replacement.privacy_domain_id
    AND prepared.mutation_candidate_id=replacement.prepare_candidate_id
   JOIN control.authority_envelope issuing ON issuing.participant_id=prepared.participant_id
    AND issuing.authority_envelope_id=prepared.maker_authority_envelope_id
   JOIN control.approval_request approval ON approval.participant_id=prepared.participant_id
    AND approval.privacy_domain_id=prepared.privacy_domain_id
    AND approval.approval_request_id=replacement.prepare_approval_id
    AND approval.subject_type='CONFIGURATION_CANDIDATE' AND approval.subject_id=prepared.mutation_candidate_id
    AND approval.subject_digest=prepared.candidate_digest AND approval.subject_version=prepared.expected_revision
   WHERE fresh.participant_id=participant AND openpc.matches_privacy(fresh.privacy_domain_id)
    AND fresh.recovery_id=selected.recovery_case_id AND fresh.intent->>'schema'='pc.identity.platform-recovery-intent'
    AND fresh.intent ? 'continuation'
    AND source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' AND source.document->>'schemaVersion'='3'
    AND source.document->>'schema'='pc.identity.platform-recovery-enrollment'
    AND issuing.representation='RECOVERY_V1'
    AND issuing.recovery_case_id::text=fresh.intent#>>'{continuation,recoveryId}'
    AND principal::text IN(fresh.intent#>>'{preparation,administrators,0,principalId}',fresh.intent#>>'{preparation,administrators,1,principalId}')
    AND target=fresh.intent#>>'{continuation,preparationApprovalId}' AND approval.approval_request_id::text=target
    AND replacement.replacement_id::text=ANY(resources) AND replacement.state='WITHDRAWING' AND replacement.row_version=1
    AND prepared.mutation_candidate_id::text=fresh.intent#>>'{continuation,preparationCandidateId}'
    AND prepared.state='CONSUMED' AND prepared.consumed_operation_id=replacement.prepare_operation_id
    AND prepared.consumed_operation_id::text=fresh.intent#>>'{continuation,preparationOperationId}'
    AND prepared.catalog_operation_id='ID-OP-PLATFORM-SCOPE-PREPARE' AND prepared.expected_revision=0
    AND prepared.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' AND approval.action_intent_id=prepared.action_intent_id
    AND prepared.resource_id=replacement.replacement_id AND prepared.candidate_document=fresh.intent->'preparation'
    AND prepared.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(prepared.candidate_document),'UTF8'))
    AND approval.state='APPROVED' AND approval.maker_principal_id=prepared.maker_principal_id
    AND approval.maker_principal_id::text=fresh.intent#>>'{preparation,administrators,0,principalId}'
    AND approval.checker_principal_id::text=fresh.intent#>>'{preparation,administrators,1,principalId}'
    AND approval.maker_principal_id<>approval.checker_principal_id
 ) THEN RETURN true; END IF;
 IF action IN ('ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1')
  AND target ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  AND (openpc.discovery_approval_resume_subject_visible(participant,openpc.current_privacy_domain_id(),principal,selected_envelope,target::uuid)
    OR openpc.platform_recovery_approval_resume_subject_visible(participant,openpc.current_privacy_domain_id(),principal,selected_envelope,target::uuid))
 THEN RETURN EXISTS(SELECT 1 FROM control.approval_request approval JOIN control.mutation_candidate candidate
   ON candidate.participant_id=approval.participant_id AND candidate.privacy_domain_id=approval.privacy_domain_id
    AND candidate.mutation_candidate_id=approval.subject_id AND approval.subject_type='CONFIGURATION_CANDIDATE'
    AND approval.subject_digest=candidate.candidate_digest AND approval.subject_version=candidate.expected_revision
    AND approval.action_intent_id=candidate.action_intent_id AND approval.maker_principal_id=candidate.maker_principal_id
   WHERE approval.participant_id=participant AND openpc.matches_privacy(approval.privacy_domain_id)
    AND approval.approval_request_id=target::uuid AND candidate.maker_principal_id=principal
    AND candidate.resource_id::text=ANY(resources)); END IF;
 IF action IN ('ACT-POLICY_APPROVE_REQUEST-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-OPERATIONS_READ_OPERATION-V1') THEN
  RETURN EXISTS(SELECT 1 FROM control.mutation_candidate candidate
   JOIN control.authority_envelope maker ON maker.authority_envelope_id=candidate.maker_authority_envelope_id AND maker.participant_id=candidate.participant_id
   LEFT JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id AND approval.privacy_domain_id=candidate.privacy_domain_id
    AND approval.subject_type='CONFIGURATION_CANDIDATE' AND approval.subject_id=candidate.mutation_candidate_id
    AND approval.subject_digest=candidate.candidate_digest AND approval.subject_version=candidate.expected_revision
    AND approval.maker_principal_id=candidate.maker_principal_id
   WHERE candidate.participant_id=participant AND openpc.matches_privacy(candidate.privacy_domain_id)
    AND maker.representation='RECOVERY_V1' AND maker.recovery_case_id=selected.recovery_case_id
    AND ((candidate.catalog_operation_id IN ('ID-OP-PLATFORM-SCOPE-PREPARE','ID-OP-PLATFORM-SCOPE-COMMIT',
      'ID-OP-ENVELOPE-CREATE','ID-OP-ENVELOPE-ACTIVATE','ID-OP-ASSIGNMENT-CREATE')
      AND EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=selected.recovery_case_id
       AND c.participant_id=participant AND c.intent->>'schema'='pc.identity.platform-recovery-intent'))
     OR (candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
      AND EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=selected.recovery_case_id
       AND c.participant_id=participant AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
       AND candidate.resource_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
       AND candidate.expected_revision=(c.intent#>>'{certificateRecovery,predecessorRevision}')::numeric
       AND candidate.candidate_document=jsonb_build_object('replacedCredentialId',c.intent#>>'{certificateRecovery,predecessorCredentialId}',
        'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
        'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}'))))
    AND candidate.resource_id::text=ANY(resources)
    AND ((action='ACT-OPERATIONS_READ_OPERATION-V1' AND target=candidate.consumed_operation_id::text)
      OR (action<>'ACT-OPERATIONS_READ_OPERATION-V1' AND target=approval.approval_request_id::text)))
   OR EXISTS(SELECT 1 FROM control.identity_envelope_proposal proposal
    JOIN control.authority_envelope maker ON maker.authority_envelope_id::text=proposal.issuer_authority#>>'{binding,authorityEnvelopeId}'
     AND maker.participant_id=proposal.participant_id
     AND (maker.recovery_case_id=selected.recovery_case_id
       OR openpc.platform_recovery_proposal_history_current(participant,openpc.current_privacy_domain_id(),selected_envelope,proposal.envelope_id))
    JOIN control.platform_recovery_case c ON c.participant_id=maker.participant_id AND c.recovery_id=selected.recovery_case_id
     AND c.intent->>'schema'='pc.identity.platform-recovery-intent'
    WHERE proposal.participant_id=participant AND openpc.matches_privacy(proposal.privacy_domain_id)
     AND proposal.envelope_id::text=ANY(resources) AND action<>'ACT-OPERATIONS_READ_OPERATION-V1'
     AND proposal.submission_approval_id::text=target);
 END IF;
 RETURN false;
END $_$;


ALTER FUNCTION openpc.administration_resource_permits(resources text[], target text, action text, participant uuid, principal uuid, authenticated_session uuid, selected_envelope uuid) OWNER TO openpc_control_owner;

--
-- Name: admit_identity_envelope_recovery_trust(bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.admit_identity_envelope_recovery_trust(p_preimage bytea, p_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation; old_key control.business_signing_key;
 descriptor jsonb; issuer jsonb; key_row control.business_signing_key; admission bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND openpc.matches_participant(s.participant_id) AND openpc.matches_privacy(s.privacy_domain_id)
  AND s.from_revision=4 AND s.from_state='DISTRIBUTED' AND s.to_state='VERIFIED' AND s.state='COMMITTED';
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR p_digest<>sha256(p_preimage)
  OR step.result->>'trustDigest' IS DISTINCT FROM 'sha256:'||encode(p_digest,'hex') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-ADMISSION'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id
  AND r.privacy_domain_id=step.privacy_domain_id AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id
  AND r.state='VERIFIED' AND r.revision=5;
 SELECT * INTO STRICT old_key FROM control.business_signing_key k WHERE k.participant_id=step.participant_id
  AND k.privacy_domain_id=step.privacy_domain_id AND k.signer_id=rotation.old_signer_id;
 SELECT a.observation->'descriptor' INTO STRICT descriptor FROM control.identity_envelope_rotation_attempt a
  JOIN control.identity_envelope_rotation_step prepared USING(participant_id,privacy_domain_id,rotation_id,operation_id)
  WHERE prepared.participant_id=step.participant_id AND prepared.privacy_domain_id=step.privacy_domain_id
   AND prepared.rotation_id=step.rotation_id AND prepared.recovery_id=step.recovery_id
   AND prepared.from_revision=2 AND prepared.to_state='PREPARED' AND prepared.state='COMMITTED' AND a.slot='new' AND a.state='OBSERVED';
 issuer:=step.authority_binding#>'{lease,issuer}';
 admission:=sha256(convert_to('pc.identity.envelope-key-recovery-admission.v1','UTF8')||decode('00','hex')||
  convert_to(openpc.signing_canonical_json(step.authority_binding||jsonb_build_object('issuer',issuer,
    'newFingerprint',descriptor->>'fingerprint','newReference',descriptor->>'reference','newVersion',descriptor->>'version')),'UTF8'));
 key_row.participant_id:=step.participant_id;key_row.privacy_domain_id:=step.privacy_domain_id;key_row.signer_id:=descriptor->>'fingerprint';
 key_row.signing_purpose_code:=371;key_row.environment_id:=rotation.environment_id;key_row.public_key_spki_der:=decode(descriptor->>'publicKeySpkiHex','hex');
 key_row.workload_credential_id:=(issuer->>'workloadCredentialId')::uuid;key_row.workload_credential_epoch:=(issuer->>'workloadCredentialEpoch')::numeric;
 key_row.envelope_workload_participant_epoch:=(issuer->>'workloadParticipantEpoch')::numeric;key_row.envelope_workload_principal_epoch:=(issuer->>'workloadPrincipalEpoch')::numeric;
 key_row.key_epoch:=old_key.key_epoch+1;key_row.valid_from_ns:=(descriptor->>'validFromNs')::numeric;key_row.valid_until_ns:=(descriptor->>'validUntilNs')::numeric;
 key_row.admission_kind:='GOVERNED';key_row.admission_reference:='urn:openpc:resource:'||rotation.rotation_id::text;key_row.admission_digest:=admission;
 key_row.secret_class:='SECRET-SIGNING-KEY';key_row.secret_reference:=descriptor->>'reference';key_row.secret_version:=descriptor->>'version';
 key_row.trust_preimage:=p_preimage;key_row.trust_digest:=p_digest;
 PERFORM openpc.check_identity_envelope_recovery_trust_admission(key_row);
 INSERT INTO control.business_signing_key SELECT (key_row).*;
 INSERT INTO control.identity_envelope_signing_grant(participant_id,privacy_domain_id,signer_id,signing_purpose_code,profile_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,371,decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex'));
 INSERT INTO control.business_signing_key_state(participant_id,privacy_domain_id,signer_id,state,row_version,changed_at_ns,change_reference,change_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,'ADMITTED',1,
   floor(extract(epoch from clock_timestamp())*1000000)*1000,key_row.admission_reference,step.evidence_digest);
 RETURN jsonb_build_object('signerId',key_row.signer_id,'trustDigest','sha256:'||encode(key_row.trust_digest,'hex'),'state','ADMITTED');
END $$;


ALTER FUNCTION openpc.admit_identity_envelope_recovery_trust(p_preimage bytea, p_digest bytea) OWNER TO openpc_control_owner;

--
-- Name: admit_notification_completion_phase(bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.admit_notification_completion_phase(wire bytea, nonce bytea, mac bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_notification_completion_admission_owner();
 IF wire IS NULL OR octet_length(wire) NOT BETWEEN 1 AND 8192 OR nonce IS NULL OR octet_length(nonce)<>32
  OR mac IS NULL OR octet_length(mac)<>32 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.notification_completion_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_NOTIFICATION_COMPLETION_PHASE_ADMISSION_V1','UTF8')||sha256(wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(wire,'UTF8')::jsonb;
 PERFORM openpc.check_notification_completion_phase_proof(proof);
 INSERT INTO control.notification_completion_phase_admission(database_role,transaction_id,backend_pid,
  participant_id,privacy_domain_id,event_id,phase,proof,receipt_binding)
 VALUES(session_user,pg_current_xact_id()::text,pg_backend_pid(),openpc.current_participant_id(),
  openpc.current_privacy_domain_id(),(proof->>'eventId')::uuid,proof->>'phase',proof,nullif(proof->'receiptBinding','null'::jsonb))
 ON CONFLICT(database_role,transaction_id,event_id,phase) DO UPDATE SET proof=excluded.proof,receipt_binding=excluded.receipt_binding
 WHERE notification_completion_phase_admission.participant_id=excluded.participant_id
  AND notification_completion_phase_admission.privacy_domain_id=excluded.privacy_domain_id
  AND notification_completion_phase_admission.backend_pid=excluded.backend_pid
  AND notification_completion_phase_admission.proof->>'installationDigest'=excluded.proof->>'installationDigest'
  AND notification_completion_phase_admission.proof->>'authorityDigest'=excluded.proof->>'authorityDigest'
  AND (notification_completion_phase_admission.receipt_binding IS NULL
   OR notification_completion_phase_admission.receipt_binding=excluded.receipt_binding);
 IF NOT FOUND THEN RAISE EXCEPTION 'NOTIFICATION-COMPLETION-NATIVE-CONFLICT'; END IF;
END $$;


ALTER FUNCTION openpc.admit_notification_completion_phase(wire bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: notification; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    notification_id uuid NOT NULL,
    severity text NOT NULL,
    state text DEFAULT 'UNREAD'::text NOT NULL,
    resource_ref text,
    message_key text NOT NULL,
    candidate_digest text NOT NULL,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT notification_candidate_ck CHECK ((candidate_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT notification_message_ck CHECK ((message_key ~ '^[a-z][a-z0-9.]{2,127}$'::text)),
    CONSTRAINT notification_resource_ck CHECK ((resource_ref ~ '^urn:openpc:[a-z][a-z0-9-]{0,62}:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT notification_revision_ck CHECK (((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric))),
    CONSTRAINT notification_state_ck CHECK (((state = ANY (ARRAY['UNREAD'::text, 'READ'::text, 'ACKNOWLEDGED'::text])) AND (severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'ERROR'::text, 'CRITICAL'::text]))))
);

ALTER TABLE ONLY control.notification FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification OWNER TO openpc_control_owner;

--
-- Name: admit_notification_occurrence_metadata(control.notification); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.admit_notification_occurrence_metadata(item control.notification) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE bound_preparation_id uuid; dp control.notification_occurrence_preparation%ROWTYPE; op control.notification_occurrence_preparation%ROWTYPE;
BEGIN
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 bound_preparation_id:=openpc.notification_occurrence_metadata_preparation(item);
 SELECT p.* INTO STRICT dp FROM control.notification_occurrence_preparation p
 WHERE p.participant_id=item.participant_id AND p.privacy_domain_id=item.privacy_domain_id AND p.preparation_id=bound_preparation_id;
 SELECT p.* INTO STRICT op FROM control.notification_occurrence_preparation p
 WHERE p.participant_id=dp.participant_id AND p.privacy_domain_id=dp.privacy_domain_id AND p.key_preparation_id=dp.key_preparation_id AND p.family='NotificationOccurrenceReceiptV1';
 -- Fresh preparation checks bind ACTIVE installed profiles, roles, genuine source,
 -- route, original key/ciphertext/AAD digests and both immutable signed inputs.
 -- Actual peer and current key STATUS admission is held by the application owner
 -- on this same client; this SQL function grants no transferable capability.
 PERFORM openpc.check_notification_occurrence_preparation(op);
 PERFORM openpc.check_notification_occurrence_preparation(dp);
END $$;


ALTER FUNCTION openpc.admit_notification_occurrence_metadata(item control.notification) OWNER TO openpc_control_owner;

--
-- Name: advance_policy_set_generation_revision(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.advance_policy_set_generation_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NOT (NEW.active AND NEW.state='ACTIVE') THEN RETURN NEW; END IF;
 ELSIF (NEW.active AND NEW.state='ACTIVE') IS NOT DISTINCT FROM
       (OLD.active AND OLD.state='ACTIVE') AND NEW.policy_version_id=OLD.policy_version_id THEN
  RETURN NEW;
 END IF;
 UPDATE control.policy SET row_version=row_version+1,updated_at=clock_timestamp()
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
    AND policy_id IN (SELECT policy_id FROM control.policy_version
      WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
        AND (policy_version_id=NEW.policy_version_id OR
             (TG_OP='UPDATE' AND policy_version_id=OLD.policy_version_id)));
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.advance_policy_set_generation_revision() OWNER TO openpc_control_owner;

--
-- Name: append_rotation_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.append_rotation_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE previous_state text; previous_digest bytea; operation uuid; event uuid; receipt uuid; evidence uuid; preimage bytea; ordinal numeric;
BEGIN
 previous_state:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.state END;
 SELECT history_digest INTO previous_digest FROM control.signing_rotation_history
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.revision-1;
 IF NEW.revision>1 AND previous_digest IS NULL THEN RAISE EXCEPTION 'DATA-6021-ROTATION-HISTORY-GAP'; END IF;
 IF NEW.state='REQUESTED' THEN operation:=openpc.current_operation_id();
 ELSIF NEW.state='APPROVED' AND OLD.state='REQUESTED' THEN operation:=NEW.approved_operation_id;
 ELSE
  SELECT operation_id INTO STRICT operation FROM control.signing_rotation_command
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id
   AND operation_id=openpc.current_operation_id()
   AND (from_revision=OLD.revision OR (OLD.state='RECOVERING'
    AND openpc.current_action_intent_id()='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND from_revision=OLD.recovery_from_revision));
 END IF;
 IF NEW.state<>'REQUESTED' AND NOT (NEW.state='APPROVED' AND OLD.state='REQUESTED') THEN
  SELECT a.event_id,a.attempt_id,a.evidence_record_id,a.receipt_ordinal INTO STRICT event,receipt,evidence,ordinal
  FROM control.signing_rotation_attestation a JOIN control.signing_provider_attempt p USING(attempt_id)
  WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=operation
   AND a.rotation_id=NEW.rotation_id AND a.from_revision=OLD.revision AND a.to_state=NEW.state
   AND p.state IN ('OBSERVED','ACCEPTED') AND p.observation->>'outcome'='SUCCEEDED';
  IF ordinal<>1+coalesce((SELECT max(receipt_ordinal) FROM control.signing_rotation_history
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id),0)
  THEN RAISE EXCEPTION 'DATA-6021-ROTATION-RECEIPT-ORDINAL'; END IF;
 END IF;
 preimage:=openpc.rotation_history_preimage(NEW,previous_state,operation,event,receipt,evidence);
 INSERT INTO control.signing_rotation_history(participant_id,privacy_domain_id,rotation_id,revision,prior_state,state,operation_id,
  prior_digest,history_preimage,history_digest,event_id,receipt_id,evidence_id,receipt_namespace,receipt_ordinal)
 VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.rotation_id,NEW.revision,previous_state,NEW.state,operation,
  previous_digest,preimage,sha256(preimage),event,receipt,evidence,
  CASE WHEN receipt IS NULL THEN NULL ELSE 'CONTROL_SIGNING_LIFECYCLE_V1' END,ordinal);
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.append_rotation_history() OWNER TO openpc_control_owner;

--
-- Name: archive_cose_binding(bytea, bytea, text, integer, integer); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.archive_cose_binding(payload bytea, cose bytea, key_id text, schema_id integer, purpose integer) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE parsed jsonb; header jsonb;
BEGIN
 IF octet_length(payload) NOT BETWEEN 1 AND 65536 OR octet_length(cose) NOT BETWEEN 65 AND 66560
  OR get_byte(cose,0)<>210 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 parsed:=openpc.business_cbor_item(cose,1,0);
 IF (parsed->>'next')::integer IS DISTINCT FROM octet_length(cose) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 parsed:=parsed->'value';
 IF jsonb_typeof(parsed) IS DISTINCT FROM 'array' OR jsonb_array_length(parsed)<>4
  OR parsed->1 IS DISTINCT FROM '{}'::jsonb OR parsed->2 IS DISTINCT FROM openpc.business_bytes(payload)
  OR parsed->3 IS DISTINCT FROM jsonb_build_object('bytes',parsed->3->>'bytes')
  OR coalesce(parsed->3->>'bytes','')!~'^[0-9a-f]{128}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 header:=openpc.business_cbor(decode(parsed->0->>'bytes','hex'));
 IF header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),
  '3','application/pc+cbor','4',openpc.business_bytes(convert_to(key_id,'UTF8')),
  '100',schema_id,'101',1,'102',purpose,'103',2) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $_$;


ALTER FUNCTION openpc.archive_cose_binding(payload bytea, cose bytea, key_id text, schema_id integer, purpose integer) OWNER TO openpc_control_owner;

--
-- Name: mutation_candidate; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.mutation_candidate (
    mutation_candidate_id uuid DEFAULT uuidv7() NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    action_intent_id character varying(160) NOT NULL,
    catalog_operation_id character varying(160) NOT NULL,
    resource_type text NOT NULL,
    operation_class text NOT NULL,
    resource_id uuid NOT NULL,
    candidate_digest bytea NOT NULL,
    candidate_document jsonb NOT NULL,
    expected_revision bigint NOT NULL,
    idempotency_key character varying(256) NOT NULL,
    maker_principal_id uuid NOT NULL,
    maker_session_id uuid NOT NULL,
    maker_session_epoch bigint NOT NULL,
    maker_participant_epoch bigint NOT NULL,
    maker_principal_epoch bigint NOT NULL,
    maker_assignment_id uuid NOT NULL,
    maker_assignment_row_version bigint NOT NULL,
    maker_authority_envelope_id uuid NOT NULL,
    maker_authority_epoch bigint NOT NULL,
    maker_delegation_epoch bigint NOT NULL,
    state control.mutation_candidate_state DEFAULT 'PROPOSED'::control.mutation_candidate_state NOT NULL,
    consumed_operation_id uuid,
    expires_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    predecessor_candidate_id uuid,
    predecessor_approval_id uuid,
    resume_operation_id uuid,
    resume_request jsonb,
    attempt bigint DEFAULT 1 NOT NULL,
    CONSTRAINT mutation_candidate_attempt_ck CHECK ((((attempt = 1) AND (predecessor_candidate_id IS NULL) AND (predecessor_approval_id IS NULL) AND (resume_operation_id IS NULL)) OR ((attempt > 1) AND (predecessor_candidate_id IS NOT NULL) AND (((predecessor_approval_id IS NOT NULL) AND (resume_operation_id IS NOT NULL)) OR ((predecessor_approval_id IS NULL) AND (resume_operation_id IS NULL) AND ((catalog_operation_id)::text = 'ID-OP-WORKLOAD-ROTATE'::text) AND ((resume_request ->> 'command'::text) = 'DISCOVERY_PREAPPROVAL_CONTINUE'::text)))))),
    CONSTRAINT mutation_candidate_catalog_operation_ck CHECK ((((resource_type <> ALL (ARRAY['signing-key-rotation'::text, 'workload-signing-handover'::text])) AND ((catalog_operation_id)::text ~ '^CFG-OP-[A-Z0-9-]+$'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-TRANSFER'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-SHRINK'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-ARCHIVE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-RESTORE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-CREATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_CREATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-FIRST-ADMIN-ROTATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-FIRST-ADMIN-REVOKE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PARTICIPANT-ACTIVATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'ACTIVATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-ENVELOPE-CREATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-ENVELOPE-ACTIVATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'ACTIVATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-ENVELOPE-REVOKE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PLATFORM-SCOPE-PREPARE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PLATFORM-SCOPE-COMMIT'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-ASSIGNMENT-CREATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text) AND (resource_type = 'principal'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-ASSIGNMENT-REVOKE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DELEGATION-ISSUE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text) AND (resource_type = 'principal'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DELEGATION-REVOKE'::text) AND ((action_intent_i