E'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-MASS-RECONCILE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-CONNECTOR-CREATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-CONNECTOR-CONFIGURE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-CONNECTOR-SUSPEND'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-CONNECTOR-RESUME'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-DIRECTORY-CONNECTOR-RETIRE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PRINCIPAL-PROVISION'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text) AND (resource_type = 'principal'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PRINCIPAL-ACTIVATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'ID-OP-PRINCIPAL-SUSPEND'::text) AND ((action_intent_id)::text = 'ACT-PARTI