= 'participant'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'MOD-OP-REGISTER'::text) AND ((action_intent_id)::text = 'ACT-MODULES_CREATE_RESOURCE-V1'::text) AND (resource_type = 'modules'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'MOD-OP-INSTALL'::text) AND ((action_intent_id)::text = 'ACT-MODULE_CREATE_INSTALL-V1'::text) AND (resource_type = 'module'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'MOD-OP-ENABLE'::text) AND ((action_intent_id)::text = 'ACT-MODULE_ACTIVATE_RESOURCE-V1'::text) AND (resource_type = 'module'::text) AND (operation_class = 'ACTIVATE'::text)) OR (((catalog_operation_id)::text = 'MOD-OP-DISABLE'::text) AND ((action_intent_id)::text = 'ACT-MODULES_UPDATE_RESOURCE-V1'::text) AND (resource_type = 'modules'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'OPS-OP-CREATE-SIGNING-KEY-ROTATION'::text) AND ((action_intent_id)::text = 'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'::text) AND (resource_type = 'signing-key-rotation'::text) AND (operation_class = 'CREATE'::text)) OR (((catalog_operation_id)::text = 'OPS-OP-ADVANCE-SIGNING-KEY-ROTATION'::text) AND ((action_intent_id)::text = 'ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1'::text) AND (resource_type = 'signing-key-rotation'::text) AND (operation_class = 'UPDATE'::text)) OR (((catalog_operation_id)::text = 'OPS-OP-RECOVER-SIGNING-KEY-ROTATION'::text) AND ((action_intent_id)::text = 'ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1'::text) AND (resource_type = 'signing-key-rotation'::text) AND (operation_class = 'RECOVER'::text)) OR (((catalog_operation_id)::text = 'ID-OP-WORKLOAD-SIGNING-HANDOVER-ADMIT'::text) AND ((action_intent_id)::text = 'ACT-WORKLOAD_SIGNING_HANDOVERS_ACTIVATE_RESOURCE-V1'::text) AND (resource_type = 'workload-signing-handover'::text) AND (operation_class = 'ACTIVATE'::text)))),
