 WHERE p.oid=to_regprocedure('openpc.enforce_work_item_lifecycle()') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM NULL::text[]
 AND p.provolatile='v' AND p.prorettype='trigger'::regtype
