--
-- Name: assert_notification_delivery_start_atomic_guards(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_delivery_start_atomic_guards() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE table_name text; trigger_name text; function_name text;
BEGIN
 FOREACH table_name IN ARRAY ARRAY['notification_delivery_start','notification_delivery_attempt','notification_delivery_dispatch_intent'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=('control.'||table_name)::regclass AND relrowsecurity AND relforcerowsecurity)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
  trigger_name:=table_name||'_atomic_guard'; function_name:='openpc.guard_'||table_name||'_atomic()';
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=trigger_name AND tgtype=7 AND tgenabled IN ('O','A') AND tgfoid=function_name::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_atomic_immutable' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 42 ELSE 58 END AND tgenabled IN ('O','A') AND tgfoid='openpc.deny_notification_delivery_start_atomic_mutation()'::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_complete' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 21 ELSE 5 END AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_dispatch_intent'::regclass AND tgname='notification_delivery_dispatch_claim_guard' AND tgtype=19 AND tgenabled IN ('O','A') AND tgfoid='openpc.guard_notification_delivery_dispatch_claim()'::regprocedure) THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery'::regclass AND tgname='notification_delivery_start_complete' AND tgtype=17 AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
 THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
END $$;


ALTER FUNCTION openpc.assert_notification_delivery_start_atomic_guards() OWNER TO openpc_control_owner;

--
-- Name: assert_notification_delivery_start_atomic_owner(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_delivery_start_atomic_owner() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_signing_owner();
 PERFORM openpc.assert_notification_delivery_start_atomic_guards();
END $$;


ALTER FUNCTION openpc.assert_notification_delivery_start_atomic_owner() OWNER TO openpc_control_owner;

--
-- Name: assert_notification_endpoint_persistence(text, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_endpoint_persistence(p_operation text, p_profile bytea) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE required record; admitted control.business_transition_profile%ROWTYPE;
BEGIN
 IF p_operation NOT IN ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT','CFG-OP-VERIFY-NOTIFICATION-ENDPOINT')
  OR NOT pg_has_role(current_user,'openpc_control_runtime','MEMBER')
  OR has_table_privilege(current_user,'control.installed_notification_channel','INSERT,UPDATE,DELETE')
 THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 SELECT * INTO STRICT admitted FROM control.business_transition_profile WHERE catalog_operation_id=p_operation AND profile_version=1
  AND profile_digest=p_profile AND aggregate_type='notification-endpoint' AND action_intent_id=current_setting('openpc.action_intent_id');
 IF admitted.profile_digest<>sha256(admitted.definition_canonical_json) THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 FOR required IN SELECT * FROM (VALUES
  ('control.notification_endpoint','notification_endpoint_mutation_guard','openpc.guard_notification_endpoint_mutation()',false),
  ('control.notification_endpoint','notification_endpoint_effect_receipt','openpc.check_notification_endpoint_effect_receipt()',true),
  ('control.installed_notification_channel','notification_channel_installation_guard','openpc.guard_notification_channel_installation()',false),
  ('control.audit_occurrence','business_receipt_typed','openpc.guard_business_receipt()',false),
  ('control.audit_occurrence','business_receipt_complete','openpc.check_business_receipt_completion()',true),
  ('control.outbox_event','business_outbox_payload','openpc.guard_business_outbox()',false)
 ) v(table_name,trigger_name,function_name,deferred)
 LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc f ON f.oid=t.tgfoid
   WHERE c.oid=to_regclass(required.table_name) AND t.tgname=required.trigger_name AND t.tgenabled IN ('O','A')
    AND f.oid=to_regprocedure(required.function_name) AND t.tgdeferrable=required.deferred AND t.tginitdeferred=required.deferred
    AND c.relrowsecurity AND c.relforcerowsecurity AND NOT f.prosecdef)
  THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 END LOOP;
 IF p_operation='CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' AND NOT EXISTS (
  SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_endpoint_candidate'::regclass
    AND tgname='notification_candidate_guard' AND tgfoid='openpc.guard_notification_candidate()'::regprocedure AND tgenabled IN ('O','A'))
 THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 IF p_operation='CFG-OP-VERIFY-NOTIFICATION-ENDPOINT' THEN
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_verification_attempt'::regclass
      AND tgname='notification_verification_attempt_guard' AND tgfoid='openpc.guard_notification_verification_attempt()'::regprocedure AND tgenabled IN ('O','A'))
    OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_verification_attempt'::regclass
      AND tgname='notification_verification_attachment' AND tgfoid='openpc.check_notification_verification_attachment()'::regprocedure AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred)
    OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_endpoint_verification'::regclass
      AND tgname='notification_verification_row_guard' AND tgfoid='openpc.guard_notification_verification_row()'::regprocedure AND tgenabled IN ('O','A'))
    OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='control.notification_verification_attempt'::regclass
      AND conname='notification_verification_attachment_operation_fk' AND condeferrable AND condeferred AND convalidated)
  THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 END IF;
END $$;


ALTER FUNCTION openpc.assert_notification_endpoint_persistence(p_operation text, p_profile bytea) OWNER TO openpc_control_owner;

--
-- Name: assert_notification_endpoint_receipt(control.audit_occurrence); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_endpoint_receipt(receipt control.audit_occurrence) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item control.notification_endpoint%ROWTYPE; before_projection jsonb; after_projection jsonb; registration control.installed_notification_channel%ROWTYPE;
BEGIN
 IF receipt.profile_version<>1 OR receipt.aggregate_type<>'notification-endpoint' OR receipt.catalog_operation_id NOT IN
  ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT','CFG-OP-VERIFY-NOTIFICATION-ENDPOINT')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-PROFILE'; END IF;
 SELECT * INTO STRICT item FROM control.notification_endpoint WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND endpoint_id=receipt.aggregate_id;
 -- The repository retains this scope fence before its SERIALIZABLE snapshot.
 -- Reacquire nonblocking through COMMIT; do not request runtime UPDATE privilege.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT registration FROM control.installed_notification_channel n
   WHERE n.participant_id=item.participant_id AND n.privacy_domain_id=item.privacy_domain_id
    AND n.credential_ref=item.credential_ref AND n.channel=item.channel AND n.destination_ref=item.destination_ref
    AND n.channel_profile_digest=item.channel_profile_digest AND n.state='ACTIVE';
 IF (openpc.business_cbor(decode(registration.channel_signed->>'payloadHex','hex'))->>'6')::numeric>floor(extract(epoch from clock_timestamp())*1000)
   OR (openpc.business_cbor(decode(registration.channel_signed->>'payloadHex','hex'))->>'7')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
   OR registration.credential->>'state' IS DISTINCT FROM 'ACTIVE'
   OR (registration.credential->>'validFromMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)
   OR (registration.credential->>'validUntilMs')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
   OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
     WHERE c.participant_id=item.participant_id AND c.credential_id=registration.workload_credential_id
       AND c.principal_id=registration.principal_id AND c.credential_epoch=registration.workload_epoch
       AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.audience=registration.workload_id
       AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND p.state='ACTIVE' AND p.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-CURRENT-REGISTRATION'; END IF;
 before_projection:=openpc.business_cbor(receipt.before_state_preimage)->8;
 after_projection:=openpc.business_cbor(receipt.after_state_preimage)->8;
 IF receipt.after_existence<>1 OR receipt.after_revision<>item.revision OR item.arbitrary_egress
  OR after_projection IS DISTINCT FROM openpc.notification_endpoint_business_projection(item)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-ACTUAL-STATE'; END IF;
 IF receipt.catalog_operation_id='CFG-OP-CREATE-NOTIFICATION-ENDPOINT' THEN
  IF receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_revision<>1
    OR item.state<>'DISABLED' OR item.verification_id IS NOT NULL
    OR item.candidate_digest IS DISTINCT FROM 'sha256:'||encode(receipt.candidate_digest,'hex')
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-CREATE'; END IF;
 ELSE
  IF receipt.before_existence<>1 OR receipt.after_revision<>receipt.before_revision+1 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REVISION'; END IF;
  IF receipt.catalog_operation_id='CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' THEN
   IF before_projection->>'1'='RETIRED' OR item.verification_id IS NOT NULL
     OR item.state IS DISTINCT FROM (CASE WHEN before_projection->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REPLACEMENT'; END IF;
   IF NOT EXISTS(SELECT 1 FROM control.notification_endpoint_candidate c
     JOIN control.idempotency_record i ON i.participant_id=c.participant_id AND i.privacy_domain_id=c.privacy_domain_id AND i.principal_id=c.principal_id
     WHERE c.participant_id=item.participant_id AND c.privacy_domain_id=item.privacy_domain_id AND c.endpoint_id=item.endpoint_id
       AND c.replacement_digest=item.candidate_digest AND i.operation_id=receipt.operation_id
       AND c.expires_at_ms>floor(extract(epoch from clock_timestamp())*1000)
       AND (c.predecessor->>'revision')::numeric=receipt.before_revision
       AND c.predecessor->>'channel'=before_projection->>'0'
       AND c.predecessor->>'destinationRef'=before_projection->>'2'
       AND openpc.business_bytes(decode(substr(c.predecessor->>'channelProfileDigest',8),'hex'))=before_projection->'3'
       AND c.predecessor->>'credentialRef'=before_projection->>'4'
       AND c.construction->'credential'=registration.credential
       AND c.construction->'binding'=jsonb_build_object('participantId',item.participant_id,'privacyDomainId',item.privacy_domain_id,
         'endpointId',item.endpoint_id,'revision',item.revision::text,'channel',item.channel,'destinationRef',item.destination_ref,
         'channelProfileDigest',item.channel_profile_digest,'credentialRef',item.credential_ref))
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-REPLACEMENT-ADMISSION'; END IF;
  ELSE
   IF before_projection->>'1' NOT IN ('ACTIVE','DISABLED') OR item.state<>'ACTIVE'
     OR before_projection-ARRAY['1','7','8'] IS DISTINCT FROM after_projection-ARRAY['1','7','8']
     OR NOT EXISTS (SELECT 1 FROM control.notification_verification_attempt a
       JOIN control.notification_endpoint_verification v ON v.participant_id=a.participant_id AND v.privacy_domain_id=a.privacy_domain_id AND v.verification_id=a.attempt_id
       WHERE a.participant_id=receipt.participant_id AND a.privacy_domain_id=receipt.privacy_domain_id AND a.endpoint_id=item.endpoint_id
        AND a.attempt_id=item.verification_id AND a.state='ATTACHED' AND a.attached_operation_id=receipt.operation_id
        AND v.operation_id=receipt.operation_id AND v.endpoint_revision=item.revision)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-VERIFY'; END IF;
  END IF;
 END IF;
END $$;


ALTER FUNCTION openpc.assert_notification_endpoint_receipt(receipt control.audit_occurrence) OWNER TO openpc_control_owner;

--
-- Name: assert_notification_outcome_publication_owner(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_outcome_publication_owner() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_notification_outcome_signing_owner();
 PERFORM openpc.assert_notification_outcome_publication_shared_owners();
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_outcome'::regclass AND tgname='notification_outcome_publication_complete' AND tgfoid='openpc.guard_notification_outcome_publication_complete()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=5 AND tgdeferrable AND tginitdeferred)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_outcome'::regclass AND tgname='notification_outcome_publication_insert' AND tgfoid='openpc.guard_notification_outcome_publication_insert()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=7)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_observation'::regclass AND tgname='notification_outcome_observation_insert' AND tgfoid='openpc.guard_notification_outcome_observation_insert()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=7)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-OWNER'; END IF;
END $$;


ALTER FUNCTION openpc.assert_notification_outcome_publication_owner() OWNER TO openpc_control_owner;

--
-- Name: assert_notification_outcome_publication_shared_owners(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_notification_outcome_publication_shared_owners() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='guard_business_outbox' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
DECLARE receipt control.audit_occurrence%ROWTYPE; payload jsonb;
BEGIN
 IF NEW.proof_kind=''LEGACY'' THEN RETURN NEW; END IF;
 -- This distinct namespace is fail-closed until the Control export owner installs
 -- its exact receipt/source/outbox checker. It cannot enter command receipt admission.
 IF NEW.proof_kind=''EVIDENCE_EXPORT_COMPLETION_REFERENCE'' THEN
  PERFORM openpc.check_evidence_export_completion_event(NEW);
  RETURN NEW;
 END IF;
 -- A distinct registered family: the owning checker must exist and validate
 -- actual original receipts, source, occurrence, payload references and cursors.
 -- Any missing owner or denial propagates; there is no command-receipt fallback.
 IF NEW.proof_kind=''NOTIFICATION_DELIVERY_REQUEST_REFERENCE'' THEN
  PERFORM openpc.check_notification_delivery_requested_event(NEW);
  RETURN NEW;
 END IF;
 -- Terminal native outcomes have a separate source-owned proof. A request
 -- receipt cannot authorize completion; missing final publication stays closed.
 IF NEW.proof_kind=''NOTIFICATION_DELIVERY_COMPLETION_REFERENCE'' THEN
  PERFORM openpc.check_notification_delivery_completed_event(NEW);
  RETURN NEW;
 END IF;
 IF NEW.proof_kind<>''BUSINESS_RECEIPT_REFERENCE'' THEN RAISE EXCEPTION ''DATA-6021-UNADMITTED-OUTBOX-PROOF''; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 payload:=openpc.business_cbor(NEW.payload_cbor);
 IF receipt.aggregate_type=''signing-key-rotation'' THEN
  PERFORM openpc.check_signing_rotation_event(NEW,receipt);
  RETURN NEW;
 END IF;
 IF NEW.aggregate_type<>receipt.aggregate_type OR NEW.aggregate_id<>receipt.aggregate_id OR
    NEW.payload_digest<>sha256(NEW.payload_cbor) OR NEW.event_type<>''io.openpc.control.command.committed.v1'' OR
    NEW.data_schema_uri<>''https://schemas.openpc.local/event-payloads.schema.json#/$defs/CommandCommitted'' OR
    payload IS DISTINCT FROM jsonb_build_object(''0'',openpc.business_uuid(receipt.operation_id),
      ''1'',''urn:openpc:''||receipt.aggregate_type||'':''||receipt.aggregate_id::text,
      ''2'',receipt.action_intent_id,''3'',openpc.business_bytes(receipt.action_intent_digest)) THEN
   RAISE EXCEPTION ''DATA-6021-OUTBOX-RECEIPT-PAYLOAD''; END IF;
 RETURN NEW;
END '
 AND t.tgrelid='control.outbox_event'::regclass AND t.tgname='business_outbox_payload' AND t.tgtype=7
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='enforce_work_item_lifecycle' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
BEGIN
  IF TG_OP = ''DELETE'' THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item'';
  END IF;
  IF TG_OP = ''INSERT'' THEN
    IF NEW."state" <> ''OPEN'' OR NEW."row_version" <> 1
       OR NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item initial state'';
    END IF;
    -- Public remediation creation keeps its business receipt owner. Every
    -- internal remediation insert must instead prove native completion custody;
    -- context chooses the checker, never supplies its authorization.
    IF openpc.current_action_intent_id()=''ACT-POLICY_READ_EFFECTIVE_ACCESS-V1''
      OR (NEW.kind=''REMEDIATION'' AND openpc.current_action_intent_id() IS DISTINCT FROM ''ACT-WORK_ITEMS_CREATE_RESOURCE-V1'') THEN
      PERFORM openpc.check_notification_completion_remediation_effect(NEW);
    END IF;
    IF current_setting(''openpc.action_intent_id'',true)=''ACT-EVIDENCE_EXPORT_RECORDS-V1'' AND NEW.kind=''DELIVERY_FAILURE'' THEN
      PERFORM openpc.check_notification_delivery_failure_work(NEW);
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."work_item_id",NEW."participant_id",NEW."privacy_domain_id",NEW."kind",
         NEW."resource_ref",NEW."created_by_principal_id",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."work_item_id",OLD."participant_id",OLD."privacy_domain_id",OLD."kind",
         OLD."resource_ref",OLD."created_by_principal_id",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item identity'';
  END IF;
  IF NOT ((OLD."state" = ''OPEN'' AND NEW."state" = ''OPEN'')
          OR (OLD."state" = ''OPEN'' AND NEW."state" = ''CLAIMED'')
          OR (OLD."state" = ''CLAIMED'' AND NEW."state" = ''COMPLETED'')
          OR (OLD."state" IN (''OPEN'',''CLAIMED'') AND NEW."state" = ''CANCELLED'')) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6022-INVALID-STATE-TRANSITION'', DETAIL = ''control.work_item lifecycle'';
  END IF;
  IF NEW."assignee_principal_id" IS DISTINCT FROM OLD."assignee_principal_id"
     AND NOT (OLD."state" = ''OPEN'' AND NEW."state" = ''CLAIMED''
              AND OLD."assignee_principal_id" IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item assignee'';
  END IF;
  IF NEW."row_version" <> OLD."row_version" + 1 OR NEW."updated_at" <= OLD."updated_at" THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item revision'';
  END IF;
  IF NEW."state" = ''OPEN'' AND
     (NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item open actor'';
  ELSIF NEW."state" = ''CLAIMED'' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NOT NULL
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item claim actor'';
  ELSIF NEW."state" = ''COMPLETED'' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NULL
         OR NEW."completed_by_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id"
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."completed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item completion actor'';
  END IF;
  RETURN NEW;
END '
 AND t.tgrelid='control.work_item'::regclass AND t.tgname='work_item_lifecycle' AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='guard_notification_delivery_budget' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
DECLARE occurrence control.notification_occurrence%ROWTYPE; event control.outbox_event%ROWTYPE;
 proof control.notification_occurrence_observation%ROWTYPE; w control.installed_notification_worker%ROWTYPE;
 installed control.installed_notification_channel%ROWTYPE; ep control.notification_endpoint%ROWTYPE;
 actual record; m jsonb; wm jsonb; cm jsonb; now_ms numeric; lock_name text;
BEGIN
 PERFORM openpc.assert_notification_delivery_budget_owner();
 IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-EFFECT-CLOSED''; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION ''PC-AUTH-0005''; END IF;
 -- Restricting an existing request uses its signed historical endpoint cause,
 -- not a still-enabled endpoint or a currently effective send budget.
 IF TG_OP=''UPDATE'' AND NOT OLD.cancel_requested AND NEW.cancel_requested THEN
  PERFORM openpc.check_notification_delivery_cancellation_projection(OLD,NEW);
  RETURN NEW;
 END IF;
 -- Presence selects the immutable outcome family only. Its full checker binds
 -- the actual OLD/NEW rows and current publication authority.
 IF TG_OP=''UPDATE'' AND EXISTS(SELECT 1 FROM control.notification_delivery_outcome o
  WHERE o.participant_id=OLD.participant_id AND o.privacy_domain_id=OLD.privacy_domain_id
   AND o.notification_occurrence_id=OLD.notification_occurrence_id AND o.delivery_revision=OLD.revision) THEN
  PERFORM openpc.check_notification_delivery_outcome_projection(OLD,NEW);
  RETURN NEW;
 END IF;
 -- SQL admission requires the transaction-owned fences held by the real worker
 -- composition. Lock presence is a prerequisite, never a replacement TLS proof.
 FOREACH lock_name IN ARRAY ARRAY[''evidence-lifecycle:''||NEW.participant_id::text,
   ''notification-worker:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text,
   ''notification-installation:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype=''advisory'' AND l.granted
    AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
    AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid
    AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
