 document jsonb; challenge jsonb; pending jsonb; observation jsonb; root jsonb; difference integer:=0;
BEGIN
 s:=openpc.runtime_artifact_archive_owner(stream);
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND runtime_configuration_input_id=input_id;
 IF NOT openpc.runtime_artifact_new_use_allowed(input.participant_id,input.privacy_domain_id,input.configuration_digest)
 THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-DENIED''; END IF;
 IF coalesce(octet_length(current_setting(''openpc.runtime_source_archive_permit'',true)),0) NOT BETWEEN 2 AND 65536
 THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 permit:=current_setting(''openpc.runtime_source_archive_permit'',true)::jsonb;
 IF permit IS DISTINCT FROM jsonb_build_object(''wire'',permit->''wire'',''mac'',permit->''mac'')
  OR coalesce(permit->>''wire'','''') !~ ''^[0-9a-f]+$'' OR length(permit->>''wire'')%2<>0
  OR coalesce(permit->>''mac'','''') !~ ''^[0-9a-f]{64}$'' THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 wire:=decode(permit->>''wire'',''hex''); mac:=decode(permit->>''mac'',''hex'');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to(''OPENPC_RUNTIME_ARTIFACT_ARCHIVE_RESPONSE_V1'',''UTF8'')||wire,secret,''sha256'');
 FOR n IN 0..31 LOOP difference:=difference | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 document:=convert_from(wire,''UTF8'')::jsonb; challenge:=document->''challenge''; pending:=challenge->''archive'';
 observation:=document->''observation''->''claims''; root:=document->''root''->''claims'';
 IF document IS DISTINCT FROM jsonb_build_object(''challenge'',challenge,''observation'',document->''observation'',''root'',document->''root'',''original'',document->''original'')
  OR challenge IS DISTINCT FROM jsonb_build_object(''version'',1,''installation'',jsonb_build_object(''participant_id'',s.participant_id::text,
 ''privacy_domain_id'',s.privacy_domain_id::text,''source_owner_id'',s.source_owner_id::text,
 ''source_file_binding'',encode(s.source_file_binding,''hex'')),''binding'',s.custody_root,
   ''archive'',jsonb_build_object(''stream_id'',stream,''materialization'',jsonb_build_object(''input'',jsonb_build_object(''input_id'',input.runtime_configuration_input_id::text,
 ''module_installation_id'',input.module_installation_id::text,
 ''module_configuration_generation_id'',input.module_configuration_generation_id::text,
 ''configuration_digest'',encode(input.configuration_digest,''hex'')),''reader_role'',session_user::text,
    ''transaction_id'',pg_current_xact_id()::text,''backend_id'',pg_backend_pid()::text||'':''||extract(epoch FROM pg_postmaster_start_time())::text,''request_id'',pending->''materialization''->>''request_id'')))
  OR coalesce(pending->''materialization''->>''request_id'','''') !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$''
  OR document->''observation''->>''purpose'' IS DISTINCT FROM ''openpc:runtime-artifact-source-history:v1''
  OR observation->''version'' IS DISTINCT FROM ''1''::jsonb OR observation->''installation'' IS DISTINCT FROM jsonb_build_object(''participant_id'',s.participant_id::text,
 ''privacy_domain_id'',s.privacy_domain_id::text,''source_owner_id'',s.source_owner_id::text,
 ''source_file_binding'',encode(s.source_file_binding,''hex''))
  OR observation->''observation'' IS DISTINCT FROM jsonb_build_object(''ArchiveMaterializedOrUnknown'',pending)
  OR document->''root''->>''purpose'' IS DISTINCT FROM ''openpc:runtime-artifact-source-root:v1''
  OR root->''version'' IS DISTINCT FROM ''1''::jsonb OR root->''installation'' IS DISTINCT FROM jsonb_build_object(''participant_id'',s.participant_id::text,
 ''privacy_domain_id'',s.privacy_domain_id::text,''source_owner_id'',s.source_owner_id::text,
 ''source_file_binding'',encode(s.source_file_binding,''hex''))
  OR root->''binding'' IS DISTINCT FROM s.custody_root THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 IF coalesce(document->>''original'','''') !~ ''^[0-9a-f]+$'' OR length(document->>''original'') NOT BETWEEN 2 AND 16384 OR length(document->>''original'')%2<>0
  THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 IF convert_from(decode(document->>''original'',''hex''),''UTF8'')::jsonb IS DISTINCT FROM document->''observation''
  THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN''; END IF;
 RETURN jsonb_build_object(''original'',document->''original'',''observation'',document->''observation'');
END '),('openpc.runtime_artifact_archive_payload(uuid,text)','
DECLARE payload bytea;
BEGIN
 PERFORM openpc.runtime_artifact_archive_permit(input_id,stream);
 SELECT configuration_cbor INTO STRICT payload FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 RETURN payload;
END ')) expected(signature,body)
  WHERE NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   WHERE p.oid=to_regprocedure(expected.signature) AND r.rolname='openpc_control_owner'
    AND p.prosecdef AND p.provolatile='v' AND p.prokind='f' AND NOT p.proisstrict
    AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']::text[] AND p.prosrc=expected.body))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-FUNCTION-UNAVAILABLE'; END IF;
END $_$;


ALTER FUNCTION openpc.assert_runtime_artifact_materialization_boundary() OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_retirement; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.runtime_artifact_retirement (
    deletion_job_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    runtime_configuration_input_id uuid CONSTRAINT runtime_artifact_retirement_runtime_configuration_inpu_not_null NOT NULL,
    module_installation_id uuid NOT NULL,
    module_configuration_generation_id uuid CONSTRAINT runtime_artifact_retirement_module_configuration_gener_not_null NOT NULL,
    configuration_digest text NOT NULL,
    configuration_bytes integer NOT NULL,
    resource_bindings_digest text NOT NULL,
    source_created_at timestamp(6) with time zone NOT NULL,
    retirement_digest text NOT NULL,
    CONSTRAINT runtime_artifact_retirement_bytes_ck CHECK (((configuration_bytes >= 1) AND (configuration_bytes <= 4194304))),
    CONSTRAINT runtime_artifact_retirement_digest_ck CHECK (((configuration_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (resource_bindings_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (retirement_digest ~ '^sha256:[0-9a-f]{64}$'::text)))
);

ALTER TABLE ONLY control.runtime_artifact_retirement FORCE ROW LEVEL SECURITY;


ALTER TABLE control.runtime_artifact_retirement OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_retirement_committed(control.runtime_artifact_retirement); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_retirement_committed(r control.runtime_artifact_retirement) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE job control.deletion_job; receipt control.audit_occurrence;
BEGIN
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF (r).participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR (r).privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR (r).retirement_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_digest(r)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-SOURCE'; END IF;
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=(r).participant_id AND privacy_domain_id=(r).privacy_domain_id
  AND deletion_job_id=(r).deletion_job_id AND state='SUCCEEDED' AND revision=1 AND target_database='openpc_control'
  AND target_data_class='RUNTIME_ARTIFACT' AND external_attempt_state='NOT_STARTED' AND deleted_count=1
  AND deleted_bytes=(r).configuration_bytes AND before_used_bytes=(r).configuration_bytes AND after_used_bytes=0
  AND retained_alias_count=0 AND after_digest=openpc.runtime_artifact_retirement_after_digest(r);
 IF EXISTS(SELECT 1 FROM control.runtime_configuration_input WHERE participant_id=(r).participant_id AND privacy_domain_id=(r).privacy_domain_id
  AND runtime_configuration_input_id=(r).runtime_configuration_input_id)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-EFFECT'; END IF;
 PERFORM openpc.assert_runtime_artifact_retirement_owner('effect');
 PERFORM openpc.assert_runtime_artifact_retirement_effect(job,r);
 SELECT * INTO STRICT receipt FROM control.audit_occurrence a WHERE a.participant_id=job.participant_id AND a.privacy_domain_id=job.privacy_domain_id
  AND a.operation_id=job.operation_id AND a.aggregate_id=job.deletion_job_id AND a.aggregate_type='evidence-deletion'
  AND a.profile_id='pc.control.evidence-deletion.runtime-artifact' AND a.profile_version=1
  AND a.profile_digest=decode('d1f1c8ccfbd049063197e8511e1b0604888963b29cc40fec7ca8e72f539d85c5','hex')
  AND a.action_intent_id='ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1' AND a.catalog_operation_id='CFG-OP-DELETE-RUNTIME-ARTIFACT-BATCH'
  AND a.before_existence=0 AND a.before_revision=0 AND a.after_existence=1 AND a.after_revision=1
  AND a.receipt_digest=sha256(a.receipt_cbor);
 PERFORM openpc.assert_evidence_deletion_receipt(receipt);
 IF NOT EXISTS(SELECT 1 FROM control.idempotency_record i WHERE i.participant_id=receipt.participant_id AND i.privacy_domain_id=receipt.privacy_domain_id
  AND i.idempotency_record_id=receipt.idempotency_record_id AND i.operation_id=receipt.operation_id AND i.terminal_state='COMMITTED'
  AND i.input_digest=receipt.candidate_digest AND i.action_intent_id=receipt.action_intent_id AND i.catalog_operation_id=receipt.catalog_operation_id)
  OR (SELECT count(*) FROM control.outbox_event e WHERE e.participant_id=receipt.participant_id AND e.privacy_domain_id=receipt.privacy_domain_id
   AND e.receipt_id=receipt.receipt_id AND e.aggregate_id=receipt.aggregate_id AND e.aggregate_type=receipt.aggregate_type
   AND e.event_type='io.openpc.control.command.committed.v1' AND e.proof_kind='BUSINESS_RECEIPT_REFERENCE'
   AND e.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND e.payload_digest=sha256(e.payload_cbor))<>1
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-RECEIPT'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_retirement_committed(r control.runtime_artifact_retirement) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_retirement_context(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_retirement_context() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE k text:='evidence-lifecycle:'||openpc.current_participant_id()::text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
  OR NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ExclusiveLock'
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(k,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(k,0)&4294967295)::oid AND l.objsubid=1)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-CONTEXT'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_retirement_context() OWNER TO openpc_control_owner;

--
-- Name: deletion_job; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.deletion_job (
    deletion_job_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    retention_policy_id uuid NOT NULL,
    stream_id text,
    segment_id uuid,
    target_database text DEFAULT 'openpc_control'::text NOT NULL,
    target_data_class text DEFAULT 'AUDIT_EVIDENCE'::text NOT NULL,
    selection jsonb NOT NULL,
    target_selector_digest text NOT NULL,
    eligibility_digest text NOT NULL,
    before_digest text NOT NULL,
    after_digest text,
    approval_request_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    external_attempt_state text DEFAULT 'NOT_STARTED'::text NOT NULL,
    state text DEFAULT 'EXECUTING'::text NOT NULL,
    revision numeric(20,0) DEFAULT '0'::numeric NOT NULL,
    deleted_count integer DEFAULT 0 NOT NULL,
    deleted_bytes integer DEFAULT 0 NOT NULL,
    before_used_bytes integer DEFAULT 0 NOT NULL,
    after_used_bytes integer,
    retained_alias_count integer DEFAULT 0 NOT NULL,
    started_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    previous_deletion_job_id uuid,
    protected_object_id uuid,
    CONSTRAINT deletion_job_accounting_ck CHECK ((((before_used_bytes >= 1) AND (before_used_bytes <= 1073741824)) AND (((state = 'EXECUTING'::text) AND (after_used_bytes IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (after_used_bytes IS NOT NULL) AND (after_used_bytes >= 0) AND (after_used_bytes = (before_used_bytes - deleted_bytes)))))),
    CONSTRAINT deletion_job_digest_ck CHECK (((target_selector_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (eligibility_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (before_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT deletion_job_state_ck CHECK ((((state = 'EXECUTING'::text) AND (revision = (0)::numeric) AND (deleted_count = 0) AND (deleted_bytes = 0) AND (after_digest IS NULL) AND (completed_at IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (revision = (1)::numeric) AND (deleted_count = 1) AND ((deleted_bytes >= 1) AND (deleted_bytes <=
CASE
    WHEN (target_data_class = 'RUNTIME_ARTIFACT'::text) THEN 4194304
    ELSE 2097152
END)) AND (after_digest IS NOT NULL) AND (after_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (completed_at IS NOT NULL) AND (completed_at >= started_at)))),
    CONSTRAINT deletion_job_target_ck CHECK (((target_database = 'openpc_control'::text) AND (external_attempt_state = 'NOT_STARTED'::text) AND (retained_alias_count = 0) AND (((target_data_class = ANY (ARRAY['AUDIT_EVIDENCE'::text, 'NORMALIZED_JSON_PROJECTION'::text, 'SEARCH_PROJECTION'::text])) AND (stream_id IS NOT NULL) AND (segment_id IS NOT NULL) AND (protected_object_id IS NULL)) OR ((target_data_class = 'RUNTIME_ARTIFACT'::text) AND (stream_id IS NOT NULL) AND (segment_id IS NULL) AND (protected_object_id IS NULL)) OR ((target_data_class = 'RAW_SOURCE_BODY'::text) AND (stream_id IS NULL) AND (segment_id IS NULL) AND (protected_object_id IS NOT NULL)))))
);

ALTER TABLE ONLY control.deletion_job FORCE ROW LEVEL SECURITY;


ALTER TABLE control.deletion_job OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_retirement_effect(control.deletion_job, control.runtime_artifact_retirement); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_retirement_effect(job control.deletion_job, r control.runtime_artifact_retirement) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE admission control.runtime_artifact_source_disposition; denied control.runtime_artifact_source_denial; receipt control.audit_occurrence;
BEGIN
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF (job).participant_id IS DISTINCT FROM (r).participant_id OR (job).privacy_domain_id IS DISTINCT FROM (r).privacy_domain_id
  OR (job).deletion_job_id IS DISTINCT FROM (r).deletion_job_id OR (job).state<>'SUCCEEDED' OR (job).revision<>1
  OR (job).target_database<>'openpc_control' OR (job).target_data_class<>'RUNTIME_ARTIFACT'
  OR (job).external_attempt_state<>'NOT_STARTED' OR (job).deleted_count<>1 OR (job).retained_alias_count<>0
  OR (job).before_used_bytes IS DISTINCT FROM (r).configuration_bytes OR (job).deleted_bytes IS DISTINCT FROM (r).configuration_bytes
  OR (job).after_used_bytes IS DISTINCT FROM 0 OR (job).selection->'source' IS DISTINCT FROM openpc.runtime_artifact_retirement_source(r)
  OR (job).before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before((job).selection->'source')
  OR (job).after_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_after_digest(r)
  OR (r).retirement_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_digest(r)
  OR EXISTS(SELECT 1 FROM control.runtime_configuration_input WHERE participant_id=(r).participant_id
   AND privacy_domain_id=(r).privacy_domain_id AND (runtime_configuration_input_id=(r).runtime_configuration_input_id
    OR configuration_digest=decode(substring((r).configuration_digest from 8),'hex')))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-EFFECT'; END IF;
 -- Historical verification binds retained originals, never today's policy,
 -- selected generation, expiry or reference graph.
 SELECT * INTO STRICT admission FROM control.runtime_artifact_source_disposition WHERE participant_id=(r).participant_id
  AND privacy_domain_id=(r).privacy_domain_id AND disposition_id=((job).selection->'disposition'->>'dispositionId')::uuid
  AND runtime_configuration_input_id=(r).runtime_configuration_input_id
  AND configuration_digest=decode(substring((r).configuration_digest from 8),'hex');
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(admission);
 SELECT * INTO STRICT denied FROM control.runtime_artifact_source_denial WHERE participant_id=admission.participant_id
  AND privacy_domain_id=admission.privacy_domain_id AND disposition_id=admission.disposition_id AND source_owner_id=admission.source_owner_id;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=admission.participant_id
  AND privacy_domain_id=admission.privacy_domain_id AND operation_id=admission.operation_id
  AND aggregate_id=admission.disposition_id AND aggregate_type='runtime-artifact-disposition';
 IF (job).selection->'disposition' IS DISTINCT FROM jsonb_build_object('dispositionId',admission.disposition_id::text,
  'operationId',admission.operation_id::text,'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'),
  'nativeDenialDigest','sha256:'||encode(denied.denial_digest,'hex'),'sourceOwnerId',admission.source_owner_id::text,
  'sourceRootDigest',admission.selection->>'sourceRootDigest') OR denied.denial_digest IS DISTINCT FROM sha256(denied.signed_denial)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-EFFECT'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_retirement_effect(job control.deletion_job, r control.runtime_artifact_retirement) OWNER TO openpc_control_owner;

--
-- Name: runtime_configuration_input; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.runtime_configuration_input (
    runtime_configuration_input_id uuid DEFAULT uuidv7() CONSTRAINT runtime_configuration_input_runtime_configuration_inpu_not_null NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    module_installation_id uuid NOT NULL,
    module_configuration_generation_id uuid CONSTRAINT runtime_configuration_input_module_configuration_gener_not_null NOT NULL,
    configuration_cbor bytea NOT NULL,
    configuration_digest bytea NOT NULL,
    resource_bindings jsonb NOT NULL,
    selected boolean DEFAULT false NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT runtime_configuration_input_bindings_ck CHECK (((jsonb_typeof(resource_bindings) = 'array'::text) AND ((jsonb_array_length(resource_bindings) >= 1) AND (jsonb_array_length(resource_bindings) <= 1024)))),
    CONSTRAINT runtime_configuration_input_bytes_ck CHECK ((((octet_length(configuration_cbor) >= 1) AND (octet_length(configuration_cbor) <= 4194304)) AND (configuration_digest = sha256(configuration_cbor))))
);


ALTER TABLE control.runtime_configuration_input OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_retirement_eligible(control.deletion_job, control.runtime_configuration_input); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_retirement_eligible(job control.deletion_job, input control.runtime_configuration_input) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected jsonb;
BEGIN
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF (job).participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR (job).privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR (input).participant_id IS DISTINCT FROM (job).participant_id OR (input).privacy_domain_id IS DISTINCT FROM (job).privacy_domain_id
  OR (job).operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
  OR (job).state<>'EXECUTING' OR (job).revision<>0 OR (job).target_database<>'openpc_control'
  OR (job).target_data_class<>'RUNTIME_ARTIFACT' OR (job).external_attempt_state<>'NOT_STARTED'
  OR (input).selected OR (input).configuration_digest IS DISTINCT FROM sha256((input).configuration_cbor)
  OR octet_length((input).configuration_cbor) NOT BETWEEN 1 AND 4194304
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-SOURCE'; END IF;
 selected:=openpc.runtime_artifact_retirement_selection((job).retention_policy_id,(job).previous_deletion_job_id);
 IF selected IS DISTINCT FROM (job).selection
  OR selected->'source'->>'runtimeConfigurationInputId' IS DISTINCT FROM (input).runtime_configuration_input_id::text
  OR selected->'source'->>'configurationDigest' IS DISTINCT FROM 'sha256:'||encode((input).configuration_digest,'hex')
  OR (job).before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before(selected->'source')
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_retirement_eligible(job control.deletion_job, input control.runtime_configuration_input) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_retirement_owner(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_retirement_owner(owner_kind text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_signature text;
BEGIN
 owner_signature:=case owner_kind when 'eligibility' then 'openpc.assert_runtime_artifact_retirement_eligible(control.deletion_job,control.runtime_configuration_input)'
  when 'effect' then 'openpc.assert_runtime_artifact_retirement_effect(control.deletion_job,control.runtime_artifact_retirement)' else null end;
 IF owner_signature IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
   WHERE p.oid=to_regprocedure(owner_signature) AND r.rolname='openpc_control_owner' AND n.nspname='openpc'
    AND l.lanname='plpgsql' AND p.prokind='f' AND p.provolatile='v' AND NOT p.prosecdef AND NOT p.proisstrict
    AND NOT p.proretset AND NOT p.proleakproof AND p.proparallel='u' AND p.prosupport=0
    AND p.prorettype='pg_catalog.void'::regtype AND p.pronargs=2 AND p.pronargdefaults=0 AND p.provariadic=0
    AND p.proargmodes IS NULL AND p.proconfig=ARRAY['search_path=pg_catalog']::text[])
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-OWNER-UNAVAILABLE'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_retirement_owner(owner_kind text) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_disposition; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.runtime_artifact_source_disposition (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    source_owner_id uuid NOT NULL,
    disposition_id uuid NOT NULL,
    runtime_configuration_input_id uuid CONSTRAINT runtime_artifact_source_dis_runtime_configuration_inpu_not_null NOT NULL,
    configuration_digest bytea CONSTRAINT runtime_artifact_source_dispositi_configuration_digest_not_null NOT NULL,
    selection jsonb NOT NULL,
    selection_digest bytea NOT NULL,
    approval_request_id uuid CONSTRAINT runtime_artifact_source_dispositio_approval_request_id_not_null NOT NULL,
    operation_id uuid NOT NULL,
    admitted_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    CONSTRAINT runtime_artifact_source_disposition_binding_ck CHECK (((octet_length(configuration_digest) = 32) AND (octet_length(selection_digest) = 32) AND (jsonb_typeof(selection) = 'object'::text) AND ((octet_length((selection)::text) >= 1) AND (octet_length((selection)::text) <= 131072)) AND (revision = (1)::numeric)))
);

ALTER TABLE ONLY control.runtime_artifact_source_disposition FORCE ROW LEVEL SECURITY;


ALTER TABLE control.runtime_artifact_source_disposition OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_source_disposition_committed(control.runtime_artifact_source_disposition); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_source_disposition_committed(a control.runtime_artifact_source_disposition) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE matched integer; receipt control.audit_occurrence;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF a.participant_id IS DISTINCT FROM openpc.current_participant_id() OR a.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR a.revision<>1 OR a.selection_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(a.selection),'UTF8'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id
  AND aggregate_id=a.disposition_id AND aggregate_type='runtime-artifact-disposition' AND operation_id=a.operation_id;
 PERFORM openpc.assert_runtime_artifact_disposition_receipt(receipt);
 SELECT count(*) INTO matched FROM control.mutation_evidence e JOIN control.mutation_candidate c
  ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id AND c.resource_id=e.aggregate_id
   AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.idempotency_record i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
   AND i.operation_id=e.operation_id AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
 WHERE e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id AND e.operation_id=a.operation_id
  AND e.approval_request_id=a.approval_request_id AND e.aggregate_type='runtime-artifact-disposition' AND e.aggregate_id=a.disposition_id
  AND e.catalog_operation_id='CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE' AND e.action_intent_id='ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1'
  AND c.catalog_operation_id=e.catalog_operation_id AND c.action_intent_id=e.action_intent_id AND c.state='CONSUMED' AND c.expected_revision=0
  AND c.candidate_document->'selection'=a.selection AND i.terminal_state='COMMITTED' AND i.expected_aggregate_version=0
  AND receipt.candidate_digest=e.candidate_digest AND receipt.idempotency_record_id=i.idempotency_record_id
  AND receipt.receipt_digest=sha256(receipt.receipt_cbor)
  AND (SELECT count(*) FROM control.outbox_event event WHERE event.participant_id=receipt.participant_id
   AND event.privacy_domain_id=receipt.privacy_domain_id AND event.receipt_id=receipt.receipt_id
   AND event.aggregate_type=receipt.aggregate_type AND event.aggregate_id=receipt.aggregate_id
   AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
   AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND event.payload_digest=sha256(event.payload_cbor))=1;
 IF matched<>1 THEN RAISE EXCEPTION 'PC-AUTH-0002-RUNTIME-DISPOSITION-SIGNED-ADMISSION'; END IF;
END $$;


ALTER FUNCTION openpc.assert_runtime_artifact_source_disposition_committed(a control.runtime_artifact_source_disposition) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_source_import(control.runtime_configuration_input); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_source_import(input control.runtime_configuration_input) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE s control.runtime_artifact_source; secret bytea; wire bytea; nonce bytea; mac bytea;
 expected bytea; different integer:=0; document jsonb; pending jsonb; root jsonb; installation jsonb;
 wire_text text:=current_setting('openpc.runtime_source_import_wire',true);
 nonce_text text:=current_setting('openpc.runtime_source_import_nonce',true);
 mac_text text:=current_setting('openpc.runtime_source_import_mac',true);
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF input.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR input.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id AND custody_root IS NOT NULL) THEN RETURN; END IF;
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id;
 IF s.database_role<>session_user OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-PROVIDER_PROFILES_READ_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('session_replication_role')<>'origin'
  OR coalesce(length(wire_text),0) NOT BETWEEN 2 AND 16384
  OR coalesce(nonce_text,'') !~ '^[0-9a-f]{64}$' OR coalesce(mac_text,'') !~ '^[0-9a-f]{64}$'
  OR wire_text !~ '^[0-9a-f]+$' OR length(wire_text)%2<>0
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 wire:=decode(wire_text,'hex'); nonce:=decode(nonce_text,'hex'); mac:=decode(mac_text,'hex');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key
  WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_SOURCE_IMPORT_V1'||pg_current_xact_id()::text
  ||encode(sha256(wire),'hex'),'UTF8')||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 document:=convert_from(wire,'UTF8')::jsonb;
 pending:=document->'pending'->'claims'; root:=document->'root'->'claims';
 installation:=jsonb_build_object('participant_id',s.participant_id::text,'privacy_domain_id',s.privacy_domain_id::text,
  'source_owner_id',s.source_owner_id::text,'source_file_binding',encode(s.source_file_binding,'hex'));
 IF document IS DISTINCT FROM jsonb_build_object('pending',document->'pending','root',document->'root')
  OR document->'pending'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-history:v1'
  OR document->'root'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-root:v1'
  OR pending->'installation' IS DISTINCT FROM installation OR root->'installation' IS DISTINCT FROM installation
  OR pending->'version' IS DISTINCT FROM '1'::jsonb OR root->'version' IS DISTINCT FROM '1'::jsonb
  OR root->'binding' IS DISTINCT FROM s.custody_root
  OR pending->'observation' IS DISTINCT FROM jsonb_build_object('ImportPending',jsonb_build_object(
   'input_id',input.runtime_configuration_input_id::text,'module_installation_id',input.module_installation_id::text,
   'module_configuration_generation_id',input.module_configuration_generation_id::text,
   'configuration_digest',encode(input.configuration_digest,'hex')))
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $_$;


ALTER FUNCTION openpc.assert_runtime_artifact_source_import(input control.runtime_configuration_input) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_source_non_use(control.runtime_artifact_source_disposition, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_source_non_use(a control.runtime_artifact_source_disposition, proof jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE s control.runtime_artifact_source; input control.runtime_configuration_input; h text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND source_owner_id=a.source_owner_id;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND runtime_configuration_input_id=a.runtime_configuration_input_id;
 IF a.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR a.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR s.database_role IS DISTINCT FROM session_user OR s.custody_root IS NULL
  OR s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR input.configuration_digest IS DISTINCT FROM a.configuration_digest
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
  OR proof IS DISTINCT FROM jsonb_build_object('profile','openpc:runtime-artifact-source-non-use:v1',
   'binding',s.custody_root,'input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
    'module_installation_id',input.module_installation_id::text,
    'module_configuration_generation_id',input.module_configuration_generation_id::text,
    'configuration_digest',encode(input.configuration_digest,'hex')),
   'pending_digest',proof->'pending_digest','committed_digest',proof->'committed_digest',
   'history_sequence',proof->'history_sequence','history_head_digest',proof->'history_head_digest',
   'retained_head_digest',proof->'retained_head_digest','consumers',jsonb_build_array(
    'RuntimeTargetEffect','TargetDispositionIssuance','DispositionBootstrapRestore','CiglReconciliation',
    'SettledTransport','PriorBootstrapBinding','CiglInvalidation','NoEffectSuspension','TargetHandoff'))
  OR jsonb_typeof(proof->'history_sequence') IS DISTINCT FROM 'number'
  OR coalesce(proof->>'history_sequence','') !~ '^[0-9]{1,4}$'
  OR (proof->>'history_sequence')::integer NOT BETWEEN 2 AND 4096
  OR proof->>'pending_digest'=proof->>'committed_digest'
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-NON-USE-UNPROVEN'; END IF;
 FOREACH h IN ARRAY ARRAY['pending_digest','committed_digest','history_head_digest','retained_head_digest'] LOOP
  IF jsonb_typeof(proof->h) IS DISTINCT FROM 'string' OR coalesce(proof->>h,'') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-NON-USE-UNPROVEN'; END IF;
 END LOOP;
END $_$;


ALTER FUNCTION openpc.assert_runtime_artifact_source_non_use(a control.runtime_artifact_source_disposition, proof jsonb) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_artifact_unused_references(jsonb, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_artifact_unused_references(observed jsonb, input_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE related jsonb; node jsonb; reference jsonb; parent_configuration text; parent_installation text;
BEGIN
 IF observed->'runtimeProducerFencesObserved' IS DISTINCT FROM 'true'::jsonb
  OR observed->'dependencyProducerFencesObserved' IS DISTINCT FROM 'true'::jsonb
  OR observed->'root'->>'id' IS DISTINCT FROM input_id::text
  OR observed->'root'->>'kind' IS DISTINCT FROM 'INPUT'
  OR EXISTS(SELECT 1 FROM jsonb_each(observed->'owners') branch WHERE branch.value->'overflow' IS DISTINCT FROM 'false'::jsonb)
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 SELECT min(r->>'id') FILTER(WHERE r->>'kind'='MODULE_CONFIGURATION'),
   min(r->>'id') FILTER(WHERE r->>'kind'='MODULE_INSTALLATION')
 INTO parent_configuration,parent_installation FROM jsonb_array_elements(observed->'root'->'references') r;
 IF parent_configuration IS NULL OR parent_installation IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(observed->'root'->'references') r WHERE r->>'kind'='MODULE_CONFIGURATION')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(observed->'root'->'references') r WHERE r->>'kind'='MODULE_INSTALLATION')<>1
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 -- Consume the existing owner's typed graph, including downstream original
 -- references. Shared parents alone do not connect unrelated inputs.
 WITH RECURSIVE nodes AS (
  SELECT entry.value body,entry.value->>'kind'||':'||(entry.value->>'id') id
   FROM jsonb_each(observed->'owners') branch CROSS JOIN LATERAL jsonb_array_elements(branch.value->'rows') entry
 ), refs AS (
  SELECT n.id src,r.value->>'kind'||':'||(r.value->>'id') dst,r.value->>'kind' target_kind
   FROM nodes n CROSS JOIN LATERAL jsonb_array_elements(n.body->'references') r
 ), tokens AS (
  SELECT n.id,t.value->>'kind'||':'||(t.value->>'digest') token FROM nodes n
   CROSS JOIN LATERAL jsonb_array_elements(n.body->'tokens') t
 ), token_heads AS (SELECT token,min(id) head FROM tokens GROUP BY token),
 edges AS (
  SELECT src,dst FROM refs UNION SELECT dst,src FROM refs WHERE target_kind IN
   ('WORK','RUNTIME_GENERATION','TARGET','PROBE','POLICY_OCCURRENCE','POLICY_AUTHORIZATION','TARGET_DISPOSITION_ADMISSION','TARGET_DISPOSITION_DELIVERY')
  UNION SELECT t.id,h.head FROM tokens t JOIN token_heads h USING(token)
  UNION SELECT h.head,t.id FROM tokens t JOIN token_heads h USING(token)
 ), reached(id) AS (
  SELECT 'INPUT:'||input_id::text UNION SELECT e.dst FROM reached r JOIN edges e ON e.src=r.id
 ) SELECT coalesce(jsonb_agg(n.body ORDER BY n.id),'[]'::jsonb) INTO related FROM reached r JOIN nodes n USING(id);
 IF jsonb_array_length(related)=0 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(related) LOOP
  IF node->>'kind' NOT IN ('INPUT','MODULE_CONFIGURATION','MODULE_INSTALLATION','PROVIDER','INDEXER','PROJECTION','CIGL_SETTINGS')
   OR EXISTS(SELECT 1 FROM jsonb_each(node->'checks') c WHERE c.value='false'::jsonb)
   OR (node->>'kind'='INPUT' AND (node->>'id'<>input_id::text OR node->>'state'<>'RETAINED'
    OR node->'checks'->'bytesMatch' IS DISTINCT FROM 'true'::jsonb OR node->'checks'->'bindingsKnown' IS DISTINCT FROM 'true'::jsonb))
   -- Module parents record where import occurred. They do not themselves use
   -- every historical input imported under that generation. Keep their exact
   -- identities in the observation, and reject an actual retained copy of the
   -- same bytes. Incoming consumers/rollback history remain forbidden above.
   OR (node->>'kind'='MODULE_CONFIGURATION' AND (
    node->>'id' IS DISTINCT FROM parent_configuration
    OR coalesce(node->>'state','') NOT IN ('ACTIVE','INACTIVE')
    OR coalesce(node->'digests'->>'configuration','') !~ '^sha256:[0-9a-f]{64}$'
    OR node->'digests'->>'configuration'=observed->'root'->'digests'->>'configuration'
    OR node->'references' IS DISTINCT FROM jsonb_build_array(jsonb_build_object('kind','MODULE_INSTALLATION','id',parent_installation,'required',true))))
   OR (node->>'kind'='MODULE_INSTALLATION' AND (
    node->>'id' IS DISTINCT FROM parent_installation
    OR coalesce(node->>'state','') NOT IN ('ENABLED','INSTALLED_DISABLED')
    OR coalesce(node->'digests'->>'lifecycle','') !~ '^sha256:[0-9a-f]{64}$'
    OR coalesce(node->'details'->>'lifecycleOperationId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
  THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-REFERENCES'; END IF;
  FOR reference IN SELECT value FROM jsonb_array_elements(node->'references') LOOP
   IF reference->'required'='true'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(related) target
    WHERE target->>'kind'=reference->>'kind' AND target->>'id'=reference->>'id')
   THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
  END LOOP;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(related) c JOIN jsonb_array_elements(related) i
   ON i->>'kind'='MODULE_INSTALLATION' AND i->>'id'=parent_installation
   WHERE c->>'kind'='MODULE_CONFIGURATION' AND c->>'id'=parent_configuration
    AND ((c->>'state'='ACTIVE' AND i->>'state'='ENABLED' AND i->'digests'->>'manifest' ~ '^sha256:[0-9a-f]{64}$')
      OR (c->>'state'='INACTIVE' AND i->>'state'='INSTALLED_DISABLED' AND i->'digests'->'manifest'='null'::jsonb)))
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
END $_$;


ALTER FUNCTION openpc.assert_runtime_artifact_unused_references(observed jsonb, input_id uuid) OWNER TO openpc_control_owner;

--
-- Name: assert_runtime_target_disposition_owner(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.assert_runtime_target_disposition_owner() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF current_setting('session_replication_role')<>'origin' OR current_setting('row_security')<>'on'
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.runtime_unsigned_withdrawal_recoverable(uuid,bigint,text)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; abandoned control.runtime_target_disposition_admission;
 previous control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 failed control.configuration_work; generation control.runtime_configuration_generation; payload bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 IF target IS NULL OR wanted_revision IS NULL OR wanted_revision<2 OR wanted_digest IS NULL
  OR openpc.current_action_intent_id() NOT IN (''ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'',
   ''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'') THEN RETURN false; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 SELECT a.* INTO abandoned FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision AND a.admission_digest=wanted_digest FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->>''action'' IS DISTINCT FROM ''Withdraw''
  OR abandoned.activation_proof IS NOT NULL OR abandoned.restoration_proof IS NOT NULL
  OR abandoned.binding->''cause''->>''kind'' IS DISTINCT FROM ''Activation''
  OR abandoned.binding->''cause''->''execution_attempt_id'' IS DISTINCT FROM ''null''::jsonb
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=pid
   AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision)
 THEN RETURN false; END IF;
 SELECT a.* INTO previous FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision-1 FOR SHARE NOWAIT;
 IF NOT FOUND OR previous.binding->>''action'' IS DISTINCT FROM ''ConfirmActivation''
  OR previous.binding->''target'' IS DISTINCT FROM abandoned.binding->''target''
  OR previous.binding->''source'' IS DISTINCT FROM abandoned.binding->''source''
  OR abandoned.binding->''previous_revision'' IS DISTINCT FROM to_jsonb(previous.revision)
 THEN RETURN false; END IF;
 SELECT d.* INTO delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=previous.revision;
 IF NOT FOUND OR abandoned.binding->>''previous_delivery_digest'' IS DISTINCT FROM substring(delivery.delivery_digest from 8)
  OR NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement k
   WHERE k.participant_id=pid AND k.privacy_domain_id=privacy AND k.runtime_target_id=target
    AND k.delivery_digest=delivery.delivery_digest AND k.claims->>''installed_state''=''ActivationConfirmed'')
 THEN RETURN false; END IF;
 SELECT w.* INTO failed FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id::text=abandoned.binding->''cause''->>''work_id'' FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->''cause'' IS DISTINCT FROM jsonb_build_object(''kind'',''Activation'',
  ''work_id'',failed.configuration_work_id::text,''operation_id'',failed.operation_id::text,''execution_attempt_id'',NULL)
  OR failed.state IS DISTINCT FROM ''FAILED'' OR failed.work_kind IS DISTINCT FROM ''RUNTIME_ACTIVATION''
  OR failed.execution_started_at IS NOT NULL OR failed.execution_attempt_id IS NOT NULL
  OR failed.predecessor_digest IS DISTINCT FROM ''sha256:''||(abandoned.binding->''source''->>''capsule_digest'')
  OR failed.configuration_work_id::text=abandoned.binding->''source''->>''original_work_id''
 THEN RETURN false; END IF;
 SELECT g.* INTO generation FROM control.runtime_configuration_generation g
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND g.runtime_configuration_generation_id=failed.runtime_configuration_generation_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN false; END IF;
 payload:=openpc.runtime_generation_retry_failure_payload(generation,failed);
 IF NOT EXISTS(SELECT 1 FROM control.outbox_event e JOIN control.mutation_evidence a
  ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
   AND a.operation_id=failed.operation_id AND a.aggregate_id=target
   AND a.action_intent_id=''ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1''
   AND a.catalog_operation_id=''CFG-OP-UPDATE-RUNTIME-TARGET''
   AND a.evidence_role=''AUTHORIZATION_INPUT'' AND a.evidence_format=''IDENTITY_RUNTIME_ASSERTION_3002_2_13''
  JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
   AND i.operation_id=a.operation_id AND i.input_digest=a.candidate_digest AND i.terminal_state=''COMMITTED''
   AND i.result_payload->>''state''=''FAILED'' AND i.result_payload->>''truthState''=''FAILED''
  WHERE e.participant_id=pid AND e.privacy_domain_id=privacy AND e.event_id=failed.result_event_id
   AND e.aggregate_id=target AND e.aggregate_type=''runtime-targets'' AND e.event_type=''runtime-target.activation-failed.v1''
   AND e.payload_cbor=payload AND e.payload_digest=sha256(payload) AND e.cose_sign1=a.cose_sign1
   AND octet_length(a.cose_sign1)>0 AND a.evidence_digest=sha256(a.evidence_cbor))
  OR EXISTS(SELECT 1 FROM control.runtime_activation_observation o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.policy_activation_occurrence_target o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
   WHERE a.runtime_target_id=target AND (a.binding->''source''->>''original_work_id''=failed.configuration_work_id::text
    OR a.binding->''source''->>''runtime_configuration_generation_id''=generation.runtime_configuration_generation_id::text))
 THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.begin_platform_scope_target_withdrawal(uuid,uuid,text,text,bigint)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; principal uuid; identity record; current_target control.runtime_target;
 intent control.platform_scope_replacement; queued control.platform_scope_target_withdrawal;
 original control.configuration_work; observation control.runtime_activation_observation;
 input control.runtime_configuration_input; head control.runtime_target_disposition_admission;
 delivery control.runtime_target_disposition_delivery; original_inputs uuid[]; material jsonb; digest text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner(); PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
   OR target IS NULL OR replacement IS NULL OR coalesce(worker,'''')='''' OR wanted_previous IS NULL OR wanted_previous<0
   OR current_setting(''transaction_isolation'')<>''read committed''
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,certificate);
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 SELECT * INTO STRICT intent FROM control.platform_scope_replacement r WHERE r.replacement_id=replacement
   AND r.participant_id=pid AND r.privacy_domain_id=privacy AND r.state=''WITHDRAWING'' AND r.row_version=1;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=intent.platform_context_id
  AND p.owner_participant_id=pid AND p.state=''ACTIVE'' AND p.authority_epoch=intent.predecessor_epoch
  AND p.row_version=intent.expected_root_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 SELECT * INTO STRICT queued FROM control.platform_scope_target_withdrawal q
  WHERE q.replacement_id=replacement AND q.participant_id=pid AND q.privacy_domain_id=privacy AND q.runtime_target_id=target;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(''module-admission:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended(''openpc-policy-generations:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.runtime_target_id=target FOR SHARE;
 IF current_target.active_generation_digest IS DISTINCT FROM queued.source->>''capsuleDigest''
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
    AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN(''PENDING'',''LEASED'',''RECONCILING''))
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF FOUND AND head.binding->>''action''=''Withdraw'' AND head.binding->''cause''=jsonb_build_object(''kind'',''Dependency'',
   ''owner'',''Platform'',''resource_id'',intent.replacement_id::text,''operation_id'',intent.prepare_operation_id::text,''revision'',1)
 THEN
  IF wanted_previous<>head.revision-1 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAS''; END IF;
  RETURN QUERY SELECT head.binding,head.admission_digest; RETURN;
 END IF;
 IF coalesce(head.revision,0)<>wanted_previous THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAS''; END IF;
 IF head.revision IS NOT NULL THEN
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=pid
   AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a WHERE a.participant_id=pid
    AND a.privacy_domain_id=privacy AND a.runtime_target_id=target AND a.delivery_digest=delivery.delivery_digest)
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACK-PENDING''; END IF;
 END IF;
 SELECT * INTO STRICT observation FROM control.runtime_activation_observation o WHERE o.participant_id=pid
  AND o.privacy_domain_id=privacy AND o.runtime_target_id=target AND o.capsule_digest=current_target.active_generation_digest
  AND o.configuration_work_id=(queued.source->>''originalWorkId'')::uuid
  AND o.execution_attempt_id=(queued.source->>''originalAttemptId'')::uuid
  AND o.activation_receipt_digest=queued.source->>''activationReceiptDigest'';
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=observation.configuration_work_id AND w.runtime_target_id=target
  AND w.operation_id=observation.operation_id AND w.execution_attempt_id=observation.execution_attempt_id
  AND w.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
  AND w.generation_digest=observation.generation_digest AND w.xds_version_digest=observation.xds_version_digest
  AND w.state=''COMPLETED'' AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.execution_started_at IS NOT NULL
  AND w.result_receipt_digest=observation.activation_receipt_digest FOR SHARE;
 SELECT array_agg(i.runtime_configuration_input_id) INTO original_inputs FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy AND i.configuration_digest=decode(substring(original.configuration_digest from 8),''hex'');
 IF coalesce(cardinality(original_inputs),0)<>1 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-INPUT-CARDINALITY''; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
  AND i.runtime_configuration_input_id=original_inputs[1] FOR SHARE;
 material:=jsonb_build_object(''version'',1,''action'',''Withdraw'',''revision'',wanted_previous+1,
  ''previous_revision'',wanted_previous,''previous_delivery_digest'',substring(delivery.delivery_digest from 8),
  ''target'',jsonb_build_object(''participant_id'',pid::text,''privacy_domain_id'',privacy::text,''target_id'',target::text,
    ''credential_id'',identity.credential_id::text,''principal_id'',principal::text,''credential_epoch'',identity.credential_epoch,
    ''principal_epoch'',identity.principal_epoch,''certificate_digest'',substring(certificate from 8)),
  ''source'',jsonb_build_object(''runtime_configuration_input_id'',input.runtime_configuration_input_id::text,
    ''configuration_digest'',encode(input.configuration_digest,''hex''),''module_installation_id'',input.module_installation_id::text,
    ''module_configuration_generation_id'',input.module_configuration_generation_id::text,
    ''runtime_configuration_generation_id'',original.runtime_configuration_generation_id::text,
    ''capsule_digest'',substring(observation.capsule_digest from 8),''xds_version_digest'',substring(observation.xds_version_digest from 8),
    ''predecessor_capsule_digest'',substring(original.predecessor_digest from 8),
    ''original_work_id'',original.configuration_work_id::text,''original_operation_id'',original.operation_id::text,
    ''original_execution_attempt_id'',original.execution_attempt_id::text),
  ''cause'',jsonb_build_object(''kind'',''Dependency'',''owner'',''Platform'',''resource_id'',intent.replacement_id::text,
    ''operation_id'',intent.prepare_operation_id::text,''revision'',1));
 IF head.revision IS NOT NULL AND head.binding->''target'' IS DISTINCT FROM material->''target'' THEN
  IF openpc.runtime_discovery_credential_predecessor(target,certificate,material->''source'') IS DISTINCT FROM head.binding->''target''
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CREDENTIAL-SUCCESSOR''; END IF;
 END IF;
 digest:=''sha256:''||encode(sha256(convert_to(openpc.signing_canonical_json(material),''UTF8'')),''hex'');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,admission_digest)
 VALUES(pid,privacy,target,wanted_previous+1,material,digest);
 RETURN QUERY SELECT material,digest;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.lock_runtime_target_disposition_issuance(uuid,bigint,text,text)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; head control.runtime_target_disposition_admission; latest text;
 original control.configuration_work; cause control.configuration_work; current_target control.runtime_target;
 authority record; principal uuid; proof jsonb; action text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
  OR current_setting(''transaction_isolation'')<>''read committed'' OR target IS NULL
  OR wanted_revision IS NULL OR wanted_revision<1 OR wanted_digest IS NULL
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF head.revision IS DISTINCT FROM wanted_revision OR head.admission_digest IS DISTINCT FROM wanted_digest
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-HEAD''; END IF;
 action:=head.binding->>''action'';
 IF action IN (''ConfirmActivation'',''Restore'') THEN
  PERFORM 1 FROM control.platform_context root JOIN control.platform_scope_replacement replacement
    ON replacement.platform_context_id=root.platform_context_id
    WHERE replacement.participant_id=pid AND replacement.privacy_domain_id=privacy AND replacement.state=''WITHDRAWING''
    FOR SHARE OF root;
  IF FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-PLATFORM-WITHDRAWING''; END IF;
  IF worker IS NOT NULL THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
  proof:=CASE action WHEN ''ConfirmActivation'' THEN head.activation_proof ELSE head.restoration_proof END;
  PERFORM openpc.lock_runtime_target_current_sources(target,head.binding->''source'',proof,
   CASE action WHEN ''ConfirmActivation'' THEN ''CONFIRM'' ELSE ''RESTORE'' END);
 ELSIF action=''Withdraw'' THEN
  IF coalesce(worker,'''')='''' THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(''module-admission:''||pid::text||'':''||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock_shared(hashtextextended(''openpc-policy-generations:''||pid::text||'':''||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
  THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 ELSE RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-ACTION''; END IF;
 -- Re-read only after the original Control fences have been reacquired.
 SELECT admission_digest INTO STRICT latest FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF latest IS DISTINCT FROM wanted_digest THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-HEAD''; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,
  ''sha256:''||(head.binding->''target''->>''certificate_digest''));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF head.binding->''target'' IS DISTINCT FROM jsonb_build_object(''participant_id'',pid::text,''privacy_domain_id'',privacy::text,
  ''target_id'',target::text,''credential_id'',authority.credential_id::text,''principal_id'',principal::text,
  ''credential_epoch'',authority.credential_epoch,''principal_epoch'',authority.principal_epoch,
  ''certificate_digest'',head.binding->''target''->>''certificate_digest'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-IDENTITY''; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->''source''->>''original_work_id'')::uuid FOR SHARE NOWAIT;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF action=''ConfirmActivation'' THEN
  IF NOT coalesce(((original.state=''COMPLETED'' AND current_target.active_generation_digest=''sha256:''||(proof->>''capsuleDigest''))
   OR (original.state IN (''LEASED'',''RECONCILING'') AND openpc.runtime_work_predecessor_matches(original.configuration_work_id)
    AND current_target.desired_generation_digest=original.generation_digest)),false)
   OR head.binding->''cause'' IS DISTINCT FROM jsonb_build_object(''kind'',''Activation'',''work_id'',original.configuration_work_id::text,
    ''operation_id'',original.operation_id::text,''execution_attempt_id'',original.execution_attempt_id::text)
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-TARGET''; END IF;
 ELSIF action=''Withdraw'' AND (openpc.expired_denial_issuance_matches(target,wanted_revision,head.admission_digest,worker)
  OR openpc.expired_handover_issuance_matches(target,wanted_revision,head.admission_digest,worker)
  OR openpc.expired_credential_handover_issuance_matches(target,wanted_revision,head.admission_digest,worker)) THEN
  -- The separate native proof admits this exact negative source only.
  RETURN;
 ELSIF action=''Withdraw'' AND head.binding->''cause''->>''kind''=''Dependency''
   AND head.binding->''cause''->>''owner''=''Platform'' THEN
  IF original.state<>''COMPLETED'' OR original.work_kind<>''RUNTIME_ACTIVATION''
    OR original.operation_id::text IS DISTINCT FROM head.binding->''source''->>''original_operation_id''
    OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->''source''->>''original_execution_attempt_id''
    OR current_target.active_generation_digest IS DISTINCT FROM ''sha256:''||(head.binding->''source''->>''capsule_digest'')
    OR NOT EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q
      JOIN control.platform_scope_replacement r ON r.replacement_id=q.replacement_id
        AND r.participant_id=q.participant_id AND r.privacy_domain_id=q.privacy_domain_id
      JOIN control.platform_context p ON p.platform_context_id=r.platform_context_id
        AND p.owner_participant_id=r.participant_id AND p.authority_epoch=r.predecessor_epoch
        AND p.row_version=r.expected_root_revision AND p.state=''ACTIVE''
      WHERE q.participant_id=pid AND q.privacy_domain_id=privacy AND q.runtime_target_id=target
        AND q.replacement_id::text=head.binding->''cause''->>''resource_id''
        AND r.state=''WITHDRAWING'' AND r.row_version=1
        AND head.binding->''cause''=jsonb_build_object(''kind'',''Dependency'',''owner'',''Platform'',
          ''resource_id'',r.replacement_id::text,''operation_id'',r.prepare_operation_id::text,''revision'',1)
        AND q.source->>''originalWorkId''=original.configuration_work_id::text
        AND q.source->>''originalAttemptId''=original.execution_attempt_id::text
        AND q.source->>''capsuleDigest''=current_target.active_generation_digest
        AND q.source->>''activationReceiptDigest''=original.result_receipt_digest)
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
      AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN(''PENDING'',''LEASED'',''RECONCILING''))
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 ELSE
  IF head.binding->''cause''->>''kind''=''UnsignedWithdrawalRecovery'' AND (
   action IS DISTINCT FROM ''Withdraw''
   OR head.revision IS DISTINCT FROM (head.binding->''cause''->>''abandoned_revision'')::bigint+1
   OR head.binding->''previous_revision'' IS DISTINCT FROM to_jsonb(head.revision-2)
   OR NOT openpc.runtime_unsigned_withdrawal_recoverable(target,(head.revision-1)::bigint,
    ''sha256:''||(head.binding->''cause''->>''abandoned_admission_digest'')))
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RECOVERY-BINDING''; END IF;
  SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->''cause''->>''work_id'')::uuid FOR SHARE NOWAIT;
  IF cause.work_kind<>''RUNTIME_ACTIVATION'' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
   OR cause.operation_id::text IS DISTINCT FROM head.binding->''cause''->>''operation_id''
   OR (head.binding->''cause''->>''kind'' IN (''Activation'',''UnsignedWithdrawalRecovery'')) IS NOT TRUE
   OR (CASE WHEN head.binding->''cause''->>''kind''=''UnsignedWithdrawalRecovery''
    THEN head.binding->''cause'' ? ''execution_attempt_id''
    ELSE head.binding->''cause''->''execution_attempt_id'' IS DISTINCT FROM ''null''::jsonb END)
   OR (original.state<>''COMPLETED'' AND NOT coalesce((action=''Withdraw'' AND cause.denied_predecessor_work_id=original.configuration_work_id
    AND original.state=''FAILED'' AND original.result_receipt->>''outcome''=''EXPIRED_OBSERVED_DENIED''
    AND openpc.runtime_work_predecessor_matches(cause.configuration_work_id)),false)) OR original.work_kind<>''RUNTIME_ACTIVATION''
   OR original.operation_id::text IS DISTINCT FROM head.binding->''source''->>''original_operation_id''
   OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->''source''->>''original_execution_attempt_id''
   OR (current_target.active_generation_digest IS DISTINCT FROM ''sha256:''||(head.binding->''source''->>''capsule_digest'') AND NOT coalesce((action=''Withdraw'' AND cause.denied_predecessor_work_id=original.configuration_work_id
    AND original.state=''FAILED'' AND original.result_receipt->>''outcome''=''EXPIRED_OBSERVED_DENIED''
    AND openpc.runtime_work_predecessor_matches(cause.configuration_work_id)),false))
   OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CAUSE''; END IF;
  IF action=''Restore'' THEN
   IF cause.state<>''FAILED'' OR cause.completed_at IS NULL OR current_target.state<>''FAILED''
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
     AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN (''PENDING'',''LEASED'',''RECONCILING''))
   THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RESTORE-CAUSE''; END IF;
  ELSIF cause.state<>''LEASED'' OR cause.lease_owner IS DISTINCT FROM worker OR cause.lease_until<=clock_timestamp()
   OR NOT openpc.runtime_work_predecessor_matches(cause.configuration_work_id) OR current_target.state<>''STAGING''
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.check_runtime_target_fact_proof(jsonb)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=false
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
   AND p.prosrc='
DECLARE custody jsonb;
BEGIN
 IF proof->>''sourceMode''=''FACT_FREE'' THEN
  IF proof ? ''factCustody'' THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-PROOF''; END IF;
  RETURN;
 END IF;
 custody:=proof->''factCustody'';
 IF proof->>''sourceMode'' IS DISTINCT FROM ''FACT_BOUND''
  OR jsonb_typeof(custody) IS DISTINCT FROM ''object''
  OR custody IS DISTINCT FROM jsonb_build_object(''version'',1,''capsuleDigest'',custody->''capsuleDigest'',
   ''factStateDigest'',custody->''factStateDigest'',''dependencyDigest'',custody->''dependencyDigest'',
   ''originalRecordsDigest'',custody->''originalRecordsDigest'',''validUntilNs'',custody->''validUntilNs'')
  OR custody->''capsuleDigest'' IS DISTINCT FROM proof->''capsuleDigest''
  OR EXISTS(SELECT 1 FROM (VALUES(''capsuleDigest''),(''factStateDigest''),(''dependencyDigest''),(''originalRecordsDigest'')) f(name)
   WHERE jsonb_typeof(custody->f.name) IS DISTINCT FROM ''string'' OR coalesce(custody->>f.name,'''') !~ ''^[0-9a-f]{64}$'')
  OR jsonb_typeof(custody->''validUntilNs'') IS DISTINCT FROM ''string''
  OR coalesce(custody->>''validUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
  OR jsonb_typeof(proof->''capsuleValidUntilNs'') IS DISTINCT FROM ''string''
  OR coalesce(proof->>''capsuleValidUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-PROOF''; END IF;
 IF (custody->>''validUntilNs'')::numeric>18446744073709551615
  OR (proof->>''capsuleValidUntilNs'')::numeric>18446744073709551615
  OR (custody->>''validUntilNs'')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR (custody->>''validUntilNs'')::numeric>(proof->>''capsuleValidUntilNs'')::numeric
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-EXPIRY''; END IF;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.begin_runtime_target_activation_confirmation(bytea,bytea,bytea)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
