--
-- Name: check_notification_delivery_cancellation_complete(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_cancellation_complete(operation uuid) RETURNS void
    LANGUAGE plpgsql
