--
-- Name: notification_delivery_cancellation; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_delivery_cancellation (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    notification_occurrence_id uuid CONSTRAINT notification_delivery_cance_notification_occurrence_id_not_null NOT NULL,
    payload_digest text NOT NULL,
    source_operation_id uuid NOT NULL,
    cause_operation_id uuid NOT NULL,
    cause_receipt_id uuid NOT NULL,
    delivery_revision numeric(20,0) NOT NULL,
    worker_installation_digest text CONSTRAINT notification_delivery_cance_worker_installation_digest_not_null NOT NULL,
    transition jsonb NOT NULL,
    transition_bytes bytea NOT NULL,
    transition_digest text NOT NULL,
    receipt_payload bytea NOT NULL,
    receipt_digest text NOT NULL,
    cose_sign1 bytea NOT NULL,
    CONSTRAINT notification_cancellation_identity_ck CHECK (((operation_id <> source_operation_id) AND (operation_id <> cause_operation_id) AND (operation_id <> receipt_id) AND (receipt_id <> cause_receipt_id))),
    CONSTRAINT notification_cancellation_receipt_ck CHECK (((payload_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND ((octet_length(receipt_payload) >= 1) AND (octet_length(receipt_payload) <= 65536)) AND ((octet_length(cose_sign1) >= 65) AND (octet_length(cose_sign1) <= 131072)) AND (receipt_digest = ('sha256:'::text || encode(sha256(receipt_payload), 'hex'::text))))),
    CONSTRAINT notification_cancellation_revision_ck CHECK (((delivery_revision >= (1)::numeric) AND (delivery_revision <= '18446744073709551614'::numeric))),
    CONSTRAINT notification_cancellation_transition_ck CHECK ((((octet_length(transition_bytes) >= 1) AND (octet_length(transition_bytes) <= 1048576)) AND (transition_digest = ('sha256:'::text || encode(sha256(transition_bytes), 'hex'::text)))))
);

ALTER TABLE ONLY control.notification_delivery_cancellation FORCE ROW LEVEL SECURITY;


