 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-ORIGINAL'; END IF;
 IF openpc.business_cbor(item.receipt_payload) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('41e381d79d89ea82f47547ed9b1becfa84ef347dd77219f12ecfa950e45269cb','hex')),'1',r->>'environmentId','2',openpc.business_uuid((r->>'participantId')::uuid),'3',openpc.business_uuid((r->>'privacyDomainId')::uuid),'4',openpc.business_uuid((r->>'receiptId')::uuid),'5',openpc.business_uuid((r->>'operationId')::uuid),'6',openpc.business_uuid((r->>'notificationOccurrenceId')::uuid),'7',openpc.business_bytes(decode(substr(r->>'payloadDigest',8),'hex')),'8',openpc.business_uuid((r->>'sourceEventId')::uuid),'9',openpc.business_bytes(decode(substr(r->>'sourceReceiptDigest',8),'hex')),'10',openpc.business_bytes(decode(substr(r->>'workerProfileDigest',8),'hex')),'11',openpc.business_bytes(decode(substr(r->>'routingProfileDigest',8),'hex')),'12',openpc.business_bytes(decode(substr(r->>'authoritySnapshotDigest',8),'hex')),'13',openpc.business_uuid((r->>'endpointId')::uuid),'14',(r->>'endpointRevision')::numeric,'15',openpc.business_uuid((r->>'causeOperationId')::uuid),'16',CASE r->>'causeAction' WHEN 'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1' THEN 1 ELSE NULL END,'17',openpc.business_bytes(decode(substr(r->>'causeProfileDigest',8),'hex')),'18',openpc.business_bytes(decode(substr(r->>'causeReceiptDigest',8),'hex')),'19',openpc.business_bytes(decode(substr(r->>'causeBeforeStateDigest',8),'hex')),'20',openpc.business_bytes(decode(substr(r->>'causeAfterStateDigest',8),'hex')),'21',(r->>'causeEndpointRevision')::numeric,'22',(r->>'deliveryRevision')::numeric,'23',openpc.business_bytes(decode(substr(r->>'beforeStateDigest',8),'hex')),'24',openpc.business_bytes(decode(substr(r->>'afterStateDigest',8),'hex')),'25',CASE r->>'beforeDeliveryState' WHEN 'PENDING' THEN 1 WHEN 'RETRY_WAIT' THEN 2 WHEN 'STARTED' THEN 3 WHEN 'AMBIGUOUS' THEN 4 ELSE NULL END,'26',CASE r->>'afterDeliveryState' WHEN 'CANCELLED' THEN 1 WHEN 'STARTED' THEN 2 WHEN 'AMBIGUOUS' THEN 3 ELSE NULL END,'27',(r->>'attemptCount')::numeric,'28',CASE r->>'disposition' WHEN 'CANCELLED_BEFORE_START' THEN 1 WHEN 'PREVENT_LATER_ATTEMPTS' THEN 2 WHEN 'RECONCILE_ORIGINAL' THEN 3 ELSE NULL END,'29',(r->>'recordedAtMs')::numeric,'30',openpc.business_bytes(decode(substr(r->>'signerKeyId',8),'hex')))
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-WIRE'; END IF;
