 SELECT * INTO STRICT i FROM control.idempotency_record WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id AND idempotency_record_id=a.idempotency_record_id;
 before_projection:=openpc.business_cbor(a.before_state_preimage)->8;after_projection:=openpc.business_cbor(a.after_state_preimage)->8;
 IF a.catalog_operation_id<>'CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' OR a.action_intent_id<>'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1'
 OR a.aggregate_type<>'notification-endpoint' OR a.profile_digest<>decode('946fcea402d8a83d11bbc68f962729bbafcab59d70bb9c0184da7441f904ea0d','hex')
 OR a.before_existence<>1 OR a.after_existence<>1 OR a.after_revision<>a.before_revision+1
 OR a.aggregate_id::text IS DISTINCT FROM r->>'endpointId' OR a.before_revision::text IS DISTINCT FROM r->>'endpointRevision'
 OR a.after_revision::text IS DISTINCT FROM r->>'causeEndpointRevision' OR a.environment_id IS DISTINCT FROM r->>'environmentId'
 OR before_projection->>'1'='RETIRED' OR after_projection->>'1' IS DISTINCT FROM (CASE WHEN before_projection->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
 OR after_projection->'7' IS DISTINCT FROM '0'::jsonb OR after_projection ? '8'
 OR i.terminal_state<>'COMMITTED' OR i.action_intent_id<>a.action_intent_id OR i.catalog_operation_id<>a.catalog_operation_id OR i.input_digest<>a.candidate_digest
 OR i.result_payload->>'state' IS DISTINCT FROM 'SUCCEEDED' OR i.result_payload->>'truthState' IS DISTINCT FROM 'SUCCESS' OR i.result_payload->>'operationId' IS DISTINCT FROM a.operation_id::text
 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.after_state_digest<>sha256(a.after_state_preimage) OR a.pre_commit_authority_digest<>sha256(a.authority_snapshot)
 OR r->>'causeProfileDigest' IS DISTINCT FROM 'sha256:'||encode(a.profile_digest,'hex') OR a.after_revision::text IS DISTINCT FROM r->>'causeEndpointRevision' OR r->>'causeProfileDigest' IS DISTINCT FROM 'sha256:'||encode(a.profile_digest,'hex')
 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.after_state_digest<>sha256(a.after_state_preimage) OR a.pre_commit_authority_digest<>sha256(a.authority_snapshot)
 OR openpc.business_cbor(a.before_state_preimage)->8->>'1'='RETIRED'
 OR openpc.business_cbor(a.after_state_preimage)->8->>'1' IS DISTINCT FROM (CASE WHEN openpc.business_cbor(a.before_state_preimage)->8->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
 OR openpc.business_cbor(a.after_state_preimage)->8->'7' IS DISTINCT FROM '0'::jsonb OR (openpc.business_cbor(a.after_state_preimage)->8) ? '8'
 OR r->>'causeReceiptDigest' IS DISTINCT FROM 'sha256:'||encode(a.receipt_digest,'hex')
 OR r->>'causeBeforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.before_state_digest,'hex') OR r->>'causeAfterStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.after_state_digest,'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-CAUSE'; END IF;

 SELECT * INTO STRICT authorization_row FROM control.mutation_evidence e WHERE e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id
  AND e.operation_id=a.operation_id AND e.action_intent_id=a.action_intent_id AND e.catalog_operation_id=a.catalog_operation_id AND e.aggregate_id=a.aggregate_id
  AND e.candidate_digest=a.candidate_digest AND e.evidence_digest=sha256(e.evidence_cbor)
  AND e.evidence_role='AUTHORIZATION_INPUT' AND e.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13';
 IF openpc.business_cbor(a.receipt_cbor)->'20' IS DISTINCT FROM jsonb_build_array(
  jsonb_build_object('0',2,'1',authorization_row.mutation_evidence_id::text,'2',openpc.business_bytes(authorization_row.evidence_digest)),
  openpc.configuration_step_up_receipt_input(a,authorization_row))
 OR t->'cause' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,'privacyDomainId',a.privacy_domain_id::text,'environmentId',a.environment_id,
  'operationId',a.operation_id::text,'receiptId',a.receipt_id::text,'endpointId',a.aggregate_id::text,'endpointRevision',a.before_revision::text,'successorRevision',a.after_revision::text,
  'profileDigest','sha256:'||encode(a.profile_digest,'hex'),'receiptDigest','sha256:'||encode(a.receipt_digest,'hex'),
  'beforeStateDigest','sha256:'||encode(a.before_state_digest,'hex'),'afterStateDigest','sha256:'||encode(a.after_state_digest,'hex'),'recordedAtMs',floor(a.recorded_at_ns/1000000))
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-CAUSE-AUTHORITY'; END IF;

 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
 AND event_id=(r->>'sourceEventId')::uuid AND correlation_id=item.source_operation_id AND aggregate_id=item.notification_occurrence_id;
 PERFORM openpc.check_notification_delivery_requested_event(e);
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=item.worker_installation_digest;
 IF w.installation IS DISTINCT FROM t->'workerInstallation' OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR t->'selector'->'source'->'worker' IS DISTINCT FROM jsonb_build_object('participantId',item.participant_id::text,'privacyDomainId',item.privacy_domain_id::text,'installationDigest',item.worker_installation_digest)
 OR t->'selector'->'source'->>'eventId' IS DISTINCT FROM r->>'sourceEventId'
 OR t->'selector'->'source'->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-WORKER'; END IF;
  IF (b->>'state' IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')) IS DISTINCT FROM true OR b->'cancelRequested' IS DISTINCT FROM 'false'::jsonb
 OR b->>'revision' IS DISTINCT FROM (r->>'deliveryRevision')::numeric::text OR n->>'revision' IS DISTINCT FROM ((r->>'deliveryRevision')::numeric+1)::text
 OR b->>'deliveryRequestOperationId' IS DISTINCT FROM (t->>'sourceOperationId')::uuid::text OR b->>'payloadDigest' IS DISTINCT FROM (r->>'payloadDigest')
 OR b->>'participantId' IS DISTINCT FROM item.participant_id::text OR b->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR b->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR n-ARRAY['revision','state','cancelRequested','nextAttemptAtMs'] IS DISTINCT FROM b-ARRAY['revision','state','cancelRequested','nextAttemptAtMs']
 OR n->'cancelRequested' IS DISTINCT FROM 'true'::jsonb OR n->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
 OR n->>'state' IS DISTINCT FROM (CASE WHEN b->>'state' IN ('PENDING','RETRY_WAIT') THEN 'CANCELLED' ELSE b->>'state' END)
 OR r->>'beforeDeliveryState' IS DISTINCT FROM b->>'state' OR r->>'afterDeliveryState' IS DISTINCT FROM n->>'state' OR r->'attemptCount' IS DISTINCT FROM b->'attemptCount'
 OR r->>'disposition' IS DISTINCT FROM (CASE WHEN b->>'state'='PENDING' THEN 'CANCELLED_BEFORE_START' WHEN b->>'state'='RETRY_WAIT' THEN 'PREVENT_LATER_ATTEMPTS' ELSE 'RECONCILE_ORIGINAL' END)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-TRANSITION'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',b->>'revision','projection',b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',n->>'revision','projection',n-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 IF b->>'state'='PENDING' THEN
  IF b->'attemptCount' IS DISTINCT FROM '0'::jsonb OR t->'originalStart' IS DISTINCT FROM 'null'::jsonb OR t->'originalClaim' IS DISTINCT FROM 'null'::jsonb
   OR EXISTS(SELECT 1 FROM control.notification_delivery_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 ELSE
  SELECT * INTO STRICT s FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=(t->'originalStart'->'receipt'->>'operationId')::uuid;
  PERFORM openpc.check_notification_delivery_start_original(s);
  SELECT * INTO STRICT claim FROM control.notification_delivery_dispatch_intent WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND operation_id=s.operation_id;
  PERFORM openpc.check_notification_delivery_dispatch_intent_original(claim);
  IF t->'originalStart' IS DISTINCT FROM s.transition OR s.notification_occurrence_id<>item.notification_occurrence_id OR s.payload_digest<>(r->>'payloadDigest')
   OR t->'originalClaim' IS DISTINCT FROM jsonb_build_object('state',claim.state,'claimToken',claim.claim_token,'claimedAtMs',claim.claimed_at_ms)
   OR s.transition->'attempt'->'attemptNumber' IS DISTINCT FROM b->'attemptCount' OR s.transition->'attempt'->'startedAtMs' IS DISTINCT FROM b->'lastStartedAtMs'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 END IF;
 IF b->>'state'='RETRY_WAIT' THEN
  SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
   AND notification_occurrence_id=item.notification_occurrence_id AND start_operation_id=s.operation_id AND attempt_id=s.attempt_id;
  PERFORM openpc.check_notification_outcome_publication_original(o.operation_id);
  IF t->'originalOutcome' IS DISTINCT FROM o.transition OR o.transition->'receipt'->>'outcome' IS DISTINCT FROM 'RETRYABLE_NO_EFFECT'
   OR o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'RETRY_WAIT' OR claim.state<>'CLAIMED'
   OR (b->>'revision')::numeric<o.delivery_revision+1 OR (b->>'attemptLimit')::numeric>(o.transition->'receipt'->>'attemptLimit')::numeric
   OR (r->>'recordedAtMs')::numeric<(o.transition->'receipt'->>'recordedAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-LINEAGE'; END IF;
  expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',(o.delivery_revision+1)::text,
   'projection',(b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest'])||jsonb_build_object('attemptLimit',o.transition->'receipt'->'attemptLimit'));
  IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM o.transition->'receipt'->>'afterStateDigest'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-STATE'; END IF;
 ELSIF t ? 'originalOutcome' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-UNEXPECTED-OUTCOME'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_cancellation_original(item control.notification_delivery_cancellation) OWNER TO openpc_control_owner;

--
-- Name: notification_delivery; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_delivery (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    notification_occurrence_id uuid NOT NULL,
    payload_digest text NOT NULL,
    delivery_request_event_id uuid NOT NULL,
    delivery_request_operation_id uuid NOT NULL,
    budget_environment_id text NOT NULL,
    budget_generation_id uuid NOT NULL,
    budget_effective_digest text NOT NULL,
    budget_configured_limit integer NOT NULL,
    budget_worker_installation_digest text CONSTRAINT notification_delivery_budget_worker_installation_diges_not_null NOT NULL,
    state text DEFAULT 'PENDING'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    attempt_limit integer NOT NULL,
    next_attempt_at_ms numeric(20,0),
    last_started_at_ms numeric(20,0),
    cancel_requested boolean DEFAULT false NOT NULL,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    CONSTRAINT notification_delivery_budget_ck CHECK ((((attempt_count >= 0) AND (attempt_count <= 6)) AND ((attempt_limit >= 0) AND (attempt_limit <= 6)))),
    CONSTRAINT notification_delivery_budget_provenance_ck CHECK ((((budget_configured_limit >= 0) AND (budget_configured_limit <= 100)) AND (attempt_limit <= LEAST(budget_configured_limit, 6)) AND (budget_effective_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (budget_worker_installation_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (budget_environment_id ~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'::text))),
    CONSTRAINT notification_delivery_revision_ck CHECK (((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric))),
    CONSTRAINT notification_delivery_state_ck CHECK ((((state = 'PENDING'::text) AND (attempt_count = 0) AND (next_attempt_at_ms IS NOT NULL)) OR ((state = 'RETRY_WAIT'::text) AND ((attempt_count >= 1) AND (attempt_count <= 5)) AND (next_attempt_at_ms IS NOT NULL) AND (next_attempt_at_ms > last_started_at_ms)) OR ((state = ANY (ARRAY['STARTED'::text, 'AMBIGUOUS'::text, 'DELIVERED'::text])) AND (attempt_count > 0) AND (next_attempt_at_ms IS NULL)) OR ((state = ANY (ARRAY['FAILED'::text, 'CANCELLED'::text, 'QUARANTINED'::text])) AND (next_attempt_at_ms IS NULL)))),
    CONSTRAINT notification_delivery_time_ck CHECK ((((next_attempt_at_ms IS NULL) OR ((next_attempt_at_ms >= (0)::numeric) AND (next_attempt_at_ms <= ('9007199254740991'::bigint)::numeric))) AND ((last_started_at_ms IS NULL) OR ((last_started_at_ms >= (0)::numeric) AND (last_started_at_ms <= ('9007199254740991'::bigint)::numeric))) AND ((attempt_count = 0) = (last_started_at_ms IS NULL))))
);

ALTER TABLE ONLY control.notification_delivery FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification_delivery OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_cancellation_projection(control.notification_delivery, control.notification_delivery); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_cancellation_projection(before_row control.notification_delivery, after_row control.notification_delivery) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c control.notification_delivery_cancellation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 SELECT * INTO STRICT c FROM control.notification_delivery_cancellation WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_delivery_cancellation_original(c);
 IF jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested,'revision',before_row.revision::text,'deliveryRequestEventId',before_row.delivery_request_event_id::text,'deliveryRequestOperationId',before_row.delivery_request_operation_id::text,'budgetEnvironmentId',before_row.budget_environment_id,'budgetGenerationId',before_row.budget_generation_id::text,'budgetEffectiveDigest',before_row.budget_effective_digest,'budgetConfiguredLimit',before_row.budget_configured_limit,'budgetWorkerInstallationDigest',before_row.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'before' OR jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested,'revision',after_row.revision::text,'deliveryRequestEventId',after_row.delivery_request_event_id::text,'deliveryRequestOperationId',after_row.delivery_request_operation_id::text,'budgetEnvironmentId',after_row.budget_environment_id,'budgetGenerationId',after_row.budget_generation_id::text,'budgetEffectiveDigest',after_row.budget_effective_digest,'budgetConfiguredLimit',after_row.budget_configured_limit,'budgetWorkerInstallationDigest',after_row.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'after'
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-PROJECTION'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_cancellation_projection(before_row control.notification_delivery, after_row control.notification_delivery) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_cancellation_signer(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_cancellation_signer(operation uuid, transition_digest text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s control.notification_cancellation_signing%ROWTYPE;actual jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_cancellation_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_cancellation_signing_original(s);
 IF s.state<>'OBSERVED' OR s.observation->>'outcome' IS DISTINCT FROM 'SIGNED' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-UNBOUND'; END IF;
 actual:=(s.preparation->'input')||jsonb_build_object('coseHex',s.observation->'coseHex');
 IF transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(actual),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-ORIGINAL'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_cancellation_signer(operation uuid, transition_digest text) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_completed_event(control.outbox_event); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_completed_event(e control.outbox_event) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE o control.notification_delivery_outcome%ROWTYPE;r jsonb;data jsonb;
BEGIN
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=e.participant_id AND privacy_domain_id=e.privacy_domain_id AND operation_id=e.correlation_id;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);r:=o.transition->'receipt';
 data:=jsonb_build_object('0','urn:openpc:resource:'||o.notification_occurrence_id::text,'1',r->>'afterDeliveryState','2',(r->>'attemptCount')::numeric,'3',openpc.business_bytes(decode(substr(r->>'gatewayCoseDigest',8),'hex')));
 IF (r->>'afterDeliveryState' IN ('DELIVERED','FAILED')) IS DISTINCT FROM true
 OR e.event_id<>o.receipt_id OR e.event_type<>'io.openpc.notification.delivery.completed.v1' OR e.aggregate_type<>'notification-occurrence' OR e.aggregate_id<>o.notification_occurrence_id
 OR e.proof_kind<>'NOTIFICATION_DELIVERY_COMPLETION_REFERENCE' OR e.sequence_namespace<>'NOTIFICATION_DELIVERY_COMPLETED_V1' OR e.business_sequence IS DISTINCT FROM 1
 OR e.aggregate_sequence IS NOT NULL OR e.receipt_id IS NOT NULL OR e.cose_sign1 IS NOT NULL OR e.authority_generation IS NOT NULL OR e.webauthn_assertion_binding_digest IS NOT NULL
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION' OR e.subject IS DISTINCT FROM 'urn:openpc:resource:'||o.notification_occurrence_id::text
 OR e.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/NotificationDeliveryCompleted'
 OR e.causation_id::text IS DISTINCT FROM o.transition->'input'->'observation'->'original'->'source'->>'eventId'
 OR extract(epoch from e.occurred_at)*1000 IS DISTINCT FROM (r->>'recordedAtMs')::numeric
 OR e.payload_digest IS DISTINCT FROM sha256(e.payload_cbor) OR openpc.business_cbor(e.payload_cbor) IS DISTINCT FROM data
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-EVENT'; END IF;
END $_$;


ALTER FUNCTION openpc.check_notification_delivery_completed_event(e control.outbox_event) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_dispatch_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_dispatch_current(operation uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item control.notification_delivery_signing%ROWTYPE;start control.notification_delivery_start%ROWTYPE;p jsonb;d control.notification_delivery%ROWTYPE;
 w control.installed_notification_worker%ROWTYPE;
 i control.installed_notification_channel%ROWTYPE;ep control.notification_endpoint%ROWTYPE;o control.notification_occurrence%ROWTYPE;
 rt control.installed_notification_routing%ROWTYPE;wm jsonb;cm jsonb;actual record;now_ms numeric;lock_name text;after_state jsonb;k control.evidence_kms_attempt%ROWTYPE;ki control.evidence_kms_installation%ROWTYPE;status control.evidence_kms_exchange%ROWTYPE;km jsonb;
BEGIN
 PERFORM openpc.assert_notification_delivery_dispatch_owner();
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT item FROM control.notification_delivery_signing WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_signing_original(item);p:=item.preparation->'deliveryPreparation';
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=p->'source'->'worker'->>'installationDigest';
 SELECT * INTO STRICT o FROM control.notification_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=(p->'source'->>'notificationOccurrenceId')::uuid;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND endpoint_id=o.endpoint_id FOR SHARE;
 SELECT * INTO STRICT i FROM control.installed_notification_channel WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND credential_ref=o.credential_ref;
 SELECT * INTO STRICT rt FROM control.installed_notification_routing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND signed_profile_digest=w.routing_profile_digest;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||item.participant_id::text,'notification-worker:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-routing:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||rt.profile_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
   AND l.mode=CASE WHEN lock_name LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END)
  THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-FENCE'; END IF;
 END LOOP;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));cm:=openpc.business_cbor(decode(i.channel_signed->>'payloadHex','hex'));
 IF w.state<>'ACTIVE' OR i.state<>'ACTIVE' OR ep.state<>'ACTIVE' OR rt.state<>'ACTIVE'
 OR now_ms<(p->'attempt'->>'startedAtMs')::numeric OR now_ms>=(p->'attempt'->>'deadlineAtMs')::numeric OR now_ms>=(p->>'authorityValidUntilMs')::numeric
 OR now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric
 OR now_ms<(cm->>'6')::numeric OR now_ms>=(cm->>'7')::numeric
 OR now_ms<(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'6')::numeric
 OR now_ms>=(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'7')::numeric
 OR i.credential->>'state'<>'ACTIVE' OR now_ms<(i.credential->>'validFromMs')::numeric OR now_ms>=(i.credential->>'validUntilMs')::numeric
 OR ep.revision IS DISTINCT FROM o.endpoint_revision OR ep.verification_id IS DISTINCT FROM o.verification_id OR ep.credential_ref IS DISTINCT FROM o.credential_ref
 OR ep.channel IS DISTINCT FROM o.channel OR ep.destination_ref IS DISTINCT FROM o.destination_ref OR ep.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR i.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest OR i.channel IS DISTINCT FROM o.channel OR i.destination_ref IS DISTINCT FROM o.destination_ref
 OR rt.endpoint_id IS DISTINCT FROM o.endpoint_id OR p->'channel' IS DISTINCT FROM jsonb_build_object('claims',jsonb_build_object('environmentId',cm->'1','participantId',(cm->'2'->>'bytes')::uuid::text,'privacyDomainId',(cm->'3'->>'bytes')::uuid::text,'profileId',(cm->'4'->>'bytes')::uuid::text,'revision',cm->>'5','validFromMs',(cm->>'6')::numeric,'validUntilMs',(cm->>'7')::numeric,'transportProfileDigest','sha256:'||(cm->'8'->>'bytes'),'receiptSignerSpki',cm->'9'->>'bytes','issuerKeyId','sha256:'||(cm->'10'->>'bytes')),'transport',i.channel_signed->'transport','signedProfileDigest',i.channel_profile_digest)
 OR NOT EXISTS(SELECT 1 FROM control.notification_endpoint_verification v WHERE v.participant_id=ep.participant_id AND v.privacy_domain_id=ep.privacy_domain_id AND v.verification_id=ep.verification_id
  AND v.endpoint_id=ep.endpoint_id AND v.endpoint_revision=ep.revision AND v.channel=ep.channel AND v.destination_ref=ep.destination_ref AND v.channel_profile_digest=ep.channel_profile_digest AND v.credential_ref=ep.credential_ref)
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) JOIN control.participant t USING(participant_id) JOIN control.privacy_domain v USING(participant_id)
  WHERE c.participant_id=item.participant_id AND c.credential_id=w.workload_credential_id AND a.principal_id=w.principal_id AND v.privacy_domain_id=item.privacy_domain_id
  AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=p->>'workerEpoch' AND c.audience=w.installation->'pins'->>'workloadId'
  AND 'sha256:'||encode(c.public_key_digest,'hex')=w.installation->'pins'->>'workloadKeyDigest' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND a.state='ACTIVE' AND a.kind='WORKLOAD' AND t.state='ACTIVE' AND v.state='ACTIVE')
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) WHERE c.participant_id=item.participant_id AND c.credential_id=i.workload_credential_id
  AND a.principal_id=i.principal_id AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch=i.workload_epoch AND c.audience=i.workload_id
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND a.state='ACTIVE' AND a.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-CURRENT'; END IF;
 SELECT * INTO STRICT k FROM control.evidence_kms_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND attempt_id=(item.preparation->'sourceClaims'->>'keyPreparationId')::uuid FOR UPDATE;
 SELECT * INTO STRICT ki FROM control.evidence_kms_installation WHERE participant_id=k.participant_id AND privacy_domain_id=k.privacy_domain_id AND installation_digest=k.installation_digest;
 lock_name:='evidence-kms-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||(ki.pins->>'installationId');
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ShareLock' AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 OR k.state<>'PROVED' OR ki.state<>'ACTIVE' OR now_ms<(ki.pins->>'validFromMs')::numeric OR now_ms>=(ki.pins->>'validUntilMs')::numeric
 OR ki.installation_digest IS DISTINCT FROM 'sha256:'||(wm->'18'->>'bytes')
 OR NOT EXISTS(SELECT 1 FROM control.notification_key_preparation kp JOIN control.notification_key_ciphertext kc USING(participant_id,privacy_domain_id,preparation_id)
  WHERE kp.participant_id=k.participant_id AND kp.privacy_domain_id=k.privacy_domain_id AND kp.preparation_id=k.attempt_id
  AND kc.key_id=item.preparation->'sourceClaims'->>'keyId' AND kc.encrypted_object_digest=item.preparation->'sourceClaims'->>'encryptedObjectDigest')
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-CUSTODY'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=k.participant_id AND e.privacy_domain_id=k.privacy_domain_id AND e.attempt_id=k.attempt_id AND (
  (e.state IN ('PREPARED','DISPATCHED','UNKNOWN') AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange r WHERE r.participant_id=e.participant_id AND r.privacy_domain_id=e.privacy_domain_id AND r.attempt_id=e.attempt_id AND r.kind='READ_ATTEMPT' AND r.state='PROVED'
   AND openpc.evidence_kms_stored_outcome(r.receipt_bytes) IN ('1','2') AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readExchangeId'=e.exchange_id::text AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=e.request_digest))
  OR (e.receipt_bytes IS NOT NULL AND openpc.business_cbor(decode(convert_from(e.receipt_bytes,'UTF8')::jsonb->'receipt'->>'payloadHex','hex'))->>'24' IN ('3','4'))))
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-KMS-UNKNOWN'; END IF;
 SELECT * INTO STRICT status FROM control.evidence_kms_exchange WHERE participant_id=k.participant_id AND privacy_domain_id=k.privacy_domain_id AND attempt_id=k.attempt_id AND kind='STATUS' AND state='PROVED' ORDER BY provider_sequence DESC,exchange_id DESC LIMIT 1;
 km:=openpc.business_cbor(decode(convert_from(status.receipt_bytes,'UTF8')::jsonb->'receipt'->>'payloadHex','hex'));
 IF km->>'24' IS DISTINCT FROM '1' OR now_ms<(km->>'28')::numeric OR now_ms>=(km->>'29')::numeric OR now_ms-(km->>'28')::numeric>5000
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-KMS-STALE'; END IF;
 SELECT * INTO STRICT actual FROM openpc.current_notification_delivery_limit(item.preparation->'sourceClaims'->>'environmentId');
 IF actual.generation_id::text IS DISTINCT FROM p->>'generationId' OR actual.effective_digest IS DISTINCT FROM p->>'effectiveDigest' OR to_jsonb(actual.configured_limit) IS DISTINCT FROM p->'configuredLimit' OR actual.configured_limit<=0
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-GENERATION'; END IF;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=o.notification_occurrence_id FOR UPDATE;
 after_state:=jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,
 'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested);
 IF start.transition->'after' IS DISTINCT FROM after_state OR d.revision IS DISTINCT FROM start.delivery_revision+1
 OR d.cancel_requested OR d.state<>'STARTED' OR d.attempt_count>least(d.attempt_limit,actual.configured_limit,6)
 OR d.delivery_request_event_id::text IS DISTINCT FROM p->'before'->>'deliveryRequestEventId'
 OR d.delivery_request_operation_id IS DISTINCT FROM start.source_operation_id
 OR d.budget_environment_id IS DISTINCT FROM p->'before'->>'budgetEnvironmentId'
 OR d.budget_generation_id::text IS DISTINCT FROM p->'before'->>'budgetGenerationId'
 OR d.budget_effective_digest IS DISTINCT FROM p->'before'->>'budgetEffectiveDigest'
 OR to_jsonb(d.budget_configured_limit) IS DISTINCT FROM p->'before'->'budgetConfiguredLimit'
 OR d.budget_worker_installation_digest IS DISTINCT FROM start.worker_installation_digest
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-STATE'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_dispatch_current(operation uuid) OWNER TO openpc_control_owner;

--
-- Name: notification_delivery_dispatch_intent; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_delivery_dispatch_intent (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid CONSTRAINT notification_delivery_dispatch_inten_privacy_domain_id_not_null NOT NULL,
    operation_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    notification_occurrence_id uuid CONSTRAINT notification_delivery_dispa_notification_occurrence_id_not_null NOT NULL,
    payload_digest text NOT NULL,
    delivery_revision numeric(20,0) CONSTRAINT notification_delivery_dispatch_inten_delivery_revision_not_null NOT NULL,
    receipt_digest text NOT NULL,
    state text DEFAULT 'PENDING'::text NOT NULL,
    claim_token text,
    claimed_at_ms numeric(20,0),
    CONSTRAINT notification_dispatch_state_ck CHECK ((((delivery_revision >= (2)::numeric) AND (delivery_revision <= '18446744073709551615'::numeric)) AND (receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (((state = 'PENDING'::text) AND (claim_token IS NULL) AND (claimed_at_ms IS NULL)) OR ((state = 'CLAIMED'::text) AND (claim_token IS NOT NULL) AND (claim_token ~ '^[0-9a-f]{64}$'::text) AND (claimed_at_ms IS NOT NULL) AND ((claimed_at_ms >= (0)::numeric) AND (claimed_at_ms <= ('9007199254740991'::bigint)::numeric))))))
);

ALTER TABLE ONLY control.notification_delivery_dispatch_intent FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification_delivery_dispatch_intent OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_dispatch_intent_original(control.notification_delivery_dispatch_intent); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_dispatch_intent_original(item control.notification_delivery_dispatch_intent) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE start control.notification_delivery_start%ROWTYPE;
BEGIN
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.operation_id;
 PERFORM openpc.check_notification_delivery_start_original(start);
 IF item.attempt_id IS DISTINCT FROM start.attempt_id OR item.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR item.payload_digest IS DISTINCT FROM start.payload_digest
 OR item.delivery_revision IS DISTINCT FROM start.delivery_revision+1 OR item.receipt_digest IS DISTINCT FROM start.receipt_digest
 OR ((item.state='PENDING' AND item.claim_token IS NULL AND item.claimed_at_ms IS NULL)
  OR (item.state='CLAIMED' AND item.claim_token IS NOT NULL AND item.claim_token ~ '^[0-9a-f]{64}$' AND item.claimed_at_ms IS NOT NULL AND item.claimed_at_ms BETWEEN 0 AND 9007199254740991
   AND item.claimed_at_ms >= (start.transition->'attempt'->>'startedAtMs')::numeric AND item.claimed_at_ms < (start.transition->'attempt'->>'deadlineAtMs')::numeric)) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'NOTIFICATION-START-INTENT'; END IF;
END $_$;


ALTER FUNCTION openpc.check_notification_delivery_dispatch_intent_original(item control.notification_delivery_dispatch_intent) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_failure_work(control.work_item); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_failure_work(item control.work_item) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND receipt_id=item.work_item_id;
 IF item.row_version<>1 OR openpc.work_item_business_projection(item) IS DISTINCT FROM openpc.notification_failure_initial_projection(o)
 OR (SELECT count(*) FROM control.work_item WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND work_item_id=item.work_item_id)<>0
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-FAILURE-WORK'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_failure_work(item control.work_item) OWNER TO openpc_control_owner;

--
-- Name: notification_delivery_observation; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_delivery_observation (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    start_operation_id uuid NOT NULL,
    dispatch_claim_token text NOT NULL,
    outcome text NOT NULL,
    observed_at_ms numeric(20,0) NOT NULL,
    observation_bytes bytea NOT NULL,
    observation_digest text NOT NULL,
    operation_id uuid NOT NULL,
    CONSTRAINT notification_observation_bytes_ck CHECK (((octet_length(observation_bytes) > 0) AND (observation_digest = ('sha256:'::text || encode(sha256(observation_bytes), 'hex'::text))))),
    CONSTRAINT notification_observation_original_ck CHECK (((operation_id <> start_operation_id) AND (dispatch_claim_token ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT notification_observation_outcome_ck CHECK (((outcome = ANY (ARRAY['DELIVERED'::text, 'RETRYABLE_NO_EFFECT'::text, 'PERMANENT_FAILURE'::text, 'AMBIGUOUS'::text])) AND ((observed_at_ms >= (0)::numeric) AND (observed_at_ms <= ('9007199254740991'::bigint)::numeric))))
);

ALTER TABLE ONLY control.notification_delivery_observation FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification_delivery_observation OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_observation_original(control.notification_delivery_observation); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_observation_original(item control.notification_delivery_observation) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE start control.notification_delivery_start%ROWTYPE; intent control.notification_delivery_dispatch_intent%ROWTYPE;
 native jsonb; payload bytea; cose bytea; m jsonb; expected jsonb; signer text;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SCOPE'; END IF;
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.start_operation_id;
 SELECT * INTO STRICT intent FROM control.notification_delivery_dispatch_intent WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.start_operation_id;
 PERFORM openpc.check_notification_delivery_start_original(start);
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(intent);
 IF start.attempt_id IS DISTINCT FROM item.attempt_id OR intent.state IS DISTINCT FROM 'CLAIMED'
 OR intent.claim_token IS DISTINCT FROM item.dispatch_claim_token OR item.operation_id IN (item.start_operation_id,start.source_operation_id,start.attempt_id)
 OR item.observed_at_ms<intent.claimed_at_ms OR item.observed_at_ms NOT BETWEEN 0 AND 9007199254740991
 OR octet_length(item.observation_bytes) NOT BETWEEN 1 AND 262144 OR item.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(item.observation_bytes),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-ORIGINAL'; END IF;
 native:=convert_from(item.observation_bytes,'UTF8')::jsonb;
 IF item.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(native),'UTF8')
 OR jsonb_typeof(native) IS DISTINCT FROM 'object' OR jsonb_typeof(native->'signed') IS DISTINCT FROM 'object'
 OR (native->'signed'->>'payloadHex' ~ '^(?:[0-9a-f]{2})+$') IS DISTINCT FROM true
 OR length(native->'signed'->>'payloadHex') NOT BETWEEN 2 AND 131072
 OR (native->'signed'->>'coseHex' ~ '^(?:[0-9a-f]{2})+$') IS DISTINCT FROM true
 OR length(native->'signed'->>'coseHex') NOT BETWEEN 130 AND 262144
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-WIRE'; END IF;
 payload:=decode(native->'signed'->>'payloadHex','hex'); cose:=decode(native->'signed'->>'coseHex','hex');
 m:=openpc.business_cbor(payload);
 signer:='sha256:'||encode(sha256(decode(start.transition->'channel'->'claims'->>'receiptSignerSpki','hex')),'hex');
 expected:=jsonb_build_object(
 '0',openpc.business_bytes(decode('55390e54136620390bb65b020b4114343ecec829725416eb1eb5066292631e17','hex')),
 '1',start.transition->'receipt'->'environmentId',
 '2',openpc.business_bytes(uuid_send(item.participant_id)),
 '3',openpc.business_bytes(uuid_send(item.privacy_domain_id)),
 '4',openpc.business_bytes(uuid_send(item.observation_id)),
 '5',openpc.business_bytes(decode(substr(start.transition->'channel'->>'signedProfileDigest',8),'hex')),
 '6',openpc.business_bytes(decode(substr('sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(start.transition->'attempt'),'UTF8')),'hex'),8),'hex')),
 '7',openpc.business_bytes(decode(substr('sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(start.transition->'context'),'UTF8')),'hex'),8),'hex')),
 '8',CASE item.outcome WHEN 'DELIVERED' THEN 1 WHEN 'RETRYABLE_NO_EFFECT' THEN 2 WHEN 'PERMANENT_FAILURE' THEN 3 WHEN 'AMBIGUOUS' THEN 4 END,
 '9',item.observed_at_ms,
 '10',openpc.business_bytes(decode(substr(signer,8),'hex')));
 IF m IS DISTINCT FROM expected THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-NATIVE'; END IF;
 expected:=jsonb_build_object('signed',jsonb_build_object('payloadHex',encode(payload,'hex'),'coseHex',encode(cose,'hex')),
 'claims',jsonb_build_object('environmentId',start.transition->'receipt'->'environmentId','participantId',item.participant_id::text,'privacyDomainId',item.privacy_domain_id::text,
 'receiptId',item.observation_id::text,'signedProfileDigest',start.transition->'channel'->>'signedProfileDigest','attemptDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(start.transition->'attempt'),'UTF8')),'hex'),
 'contextDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(start.transition->'context'),'UTF8')),'hex'),'outcome',item.outcome,'observedAtMs',item.observed_at_ms,'signerKeyId',signer),
 'receiptDigest','sha256:'||encode(sha256(cose),'hex'));
 IF native IS DISTINCT FROM expected THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-CLAIMS'; END IF;
 PERFORM openpc.archive_cose_binding(payload,cose,signer,24010,347);
END $_$;


ALTER FUNCTION openpc.check_notification_delivery_observation_original(item control.notification_delivery_observation) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_outcome_projection(control.notification_delivery, control.notification_delivery); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_outcome_projection(before_row control.notification_delivery, after_row control.notification_delivery) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;r jsonb;expected jsonb;digest text;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);r:=o.transition->'receipt';
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',before_row.revision::text,'projection',jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested));digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex');
 IF digest IS DISTINCT FROM r->>'beforeStateDigest' OR after_row.revision<>before_row.revision+1
 OR to_jsonb(after_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision'] IS DISTINCT FROM to_jsonb(before_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision']
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-BEFORE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',after_row.revision::text,'projection',jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested));
 IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM r->>'afterStateDigest' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-AFTER'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_outcome_projection(before_row control.notification_delivery, after_row control.notification_delivery) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_requested_event(control.outbox_event); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_requested_event(event control.outbox_event) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE prep control.notification_occurrence_preparation%ROWTYPE;
 proof control.notification_occurrence_observation%ROWTYPE;
 original control.notification_occurrence_observation%ROWTYPE;
 occurrence control.notification_occurrence%ROWTYPE; metadata control.notification%ROWTYPE;
 payload control.notification_payload_object%ROWTYPE;
 reference control.notification_payload%ROWTYPE;
 source control.evidence_export_completion%ROWTYPE;
 key_prep control.notification_key_preparation%ROWTYPE; cipher control.notification_key_ciphertext%ROWTYPE; route control.installed_notification_routing%ROWTYPE;
 m jsonb; o jsonb; occurrence_id uuid; payload_id uuid; source_id uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR event.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR event.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()

 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT p.* INTO STRICT prep FROM control.notification_occurrence_preparation p
 JOIN control.notification_occurrence_observation r USING(participant_id,privacy_domain_id,preparation_id)
 WHERE p.participant_id=event.participant_id AND p.privacy_domain_id=event.privacy_domain_id
 AND p.family='NotificationDeliveryRequestedReceiptV1' AND p.state='OBSERVED'
 AND openpc.business_cbor(r.receipt_payload)->'26'=openpc.business_uuid(event.event_id);
 SELECT * INTO STRICT proof FROM control.notification_occurrence_observation
 WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND preparation_id=prep.preparation_id;
 SELECT r.* INTO STRICT original FROM control.notification_occurrence_preparation p
 JOIN control.notification_occurrence_observation r USING(participant_id,privacy_domain_id,preparation_id)
 WHERE p.participant_id=prep.participant_id AND p.privacy_domain_id=prep.privacy_domain_id
 AND p.key_preparation_id=prep.key_preparation_id AND p.family='NotificationOccurrenceReceiptV1' AND p.state='OBSERVED';
 m:=openpc.business_cbor(proof.receipt_payload);o:=openpc.business_cbor(original.receipt_payload);
 PERFORM openpc.archive_cose_binding(proof.receipt_payload,proof.cose_sign1,'sha256:'||(m->'24'->>'bytes'),24020,357);
 PERFORM openpc.archive_cose_binding(original.receipt_payload,original.cose_sign1,'sha256:'||(o->'24'->>'bytes'),24019,356);
 IF m->'25' IS DISTINCT FROM jsonb_build_object('bytes',encode(sha256(original.receipt_payload),'hex'))
 OR m->'1' IS DISTINCT FROM o->'1'
 OR m->'2' IS DISTINCT FROM o->'2'
 OR m->'3' IS DISTINCT FROM o->'3'
 OR m->'6' IS DISTINCT FROM o->'6'
 OR m->'7' IS DISTINCT FROM o->'7'
 OR m->'8' IS DISTINCT FROM o->'8'
 OR m->'9' IS DISTINCT FROM o->'9'
 OR m->'10' IS DISTINCT FROM o->'10'
 OR m->'11' IS DISTINCT FROM o->'11'
 OR m->'12' IS DISTINCT FROM o->'12'
 OR m->'13' IS DISTINCT FROM o->'13'
 OR m->'16' IS DISTINCT FROM o->'16'
 OR m->'17' IS DISTINCT FROM o->'17'
 OR m->'18' IS DISTINCT FROM o->'18'
 OR m->'19' IS DISTINCT FROM o->'19'
 OR m->'20' IS DISTINCT FROM o->'20'
 OR m->'21' IS DISTINCT FROM o->'21'
 OR m->'22' IS DISTINCT FROM o->'22'
 OR m->'4' IS NOT DISTINCT FROM o->'4' OR m->'5' IS NOT DISTINCT FROM o->'5'
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-PUBLICATION-PAIR'; END IF;
 occurrence_id:=(m->'7'->>'bytes')::uuid;payload_id:=(m->'8'->>'bytes')::uuid;source_id:=(m->'10'->>'bytes')::uuid;
 SELECT * INTO STRICT occurrence FROM control.notification_occurrence WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND notification_occurrence_id=occurrence_id;
 SELECT * INTO STRICT metadata FROM control.notification WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND notification_id=occurrence.notification_id;
 SELECT * INTO STRICT payload FROM control.notification_payload_object WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND payload_object_id=payload_id;
 SELECT * INTO STRICT reference FROM control.notification_payload WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND payload_object_id=payload_id;
 SELECT * INTO STRICT source FROM control.evidence_export_completion WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND event_id=source_id;
 SELECT * INTO STRICT key_prep FROM control.notification_key_preparation WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND preparation_id=prep.key_preparation_id;
 SELECT * INTO STRICT cipher FROM control.notification_key_ciphertext WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND preparation_id=prep.key_preparation_id;
 SELECT * INTO STRICT route FROM control.installed_notification_routing WHERE participant_id=prep.participant_id AND privacy_domain_id=prep.privacy_domain_id AND profile_id=key_prep.routing_profile_id;
 IF metadata.severity IS DISTINCT FROM 'INFO' OR metadata.message_key IS DISTINCT FROM 'evidence.export.completed'
 OR metadata.resource_ref IS DISTINCT FROM 'urn:openpc:resource:'||source.evidence_export_id::text
 OR metadata.candidate_digest IS DISTINCT FROM 'sha256:'||encode(sha256(original.receipt_payload),'hex')
 OR occurrence.notification_id IS DISTINCT FROM (m->'6'->>'bytes')::uuid
 OR occurrence.payload_object_id IS DISTINCT FROM payload_id
 OR occurrence.endpoint_id IS DISTINCT FROM (m->'17'->>'bytes')::uuid
 OR occurrence.endpoint_revision IS DISTINCT FROM (m->>'18')::numeric
 OR occurrence.source_event_id IS DISTINCT FROM source_id
 OR occurrence.source_data_digest IS DISTINCT FROM 'sha256:'||(m->'11'->>'bytes')
 OR occurrence.creation_operation_id IS DISTINCT FROM original.operation_id
 OR occurrence.subscription_id<>'SUB-EVIDENCEEXPORTCOMPLETED-NOTIFICATION-V1'
 OR occurrence.template_digest IS DISTINCT FROM 'sha256:'||(m->'19'->>'bytes')
 OR occurrence.payload_digest IS DISTINCT FROM 'sha256:'||(m->'20'->>'bytes')
 OR payload.template_digest IS DISTINCT FROM occurrence.template_digest
 OR payload.payload_digest IS DISTINCT FROM occurrence.payload_digest
 OR payload.encrypted_object_digest IS DISTINCT FROM 'sha256:'||(m->'21'->>'bytes')
 OR payload.key_id IS DISTINCT FROM 'sha256:'||(m->'22'->>'bytes')
 OR payload.object_version<>1 OR payload.key_id IS DISTINCT FROM cipher.key_id
 OR payload.encrypted_object_digest IS DISTINCT FROM cipher.encrypted_object_digest
 OR payload.encryption_context_digest IS DISTINCT FROM cipher.encryption_context_digest
 OR payload.encryption_profile_digest IS DISTINCT FROM 'sha256:'||(openpc.business_cbor(decode(route.installation->'signed'->>'payloadHex','hex'))->'16'->>'bytes')
 OR payload.creation_operation_id IS DISTINCT FROM original.operation_id
 OR reference.encrypted_object_digest IS DISTINCT FROM payload.encrypted_object_digest
 OR reference.key_preparation_id IS DISTINCT FROM prep.key_preparation_id
 OR source.state<>'PUBLISHED' OR source.receipt_payload_digest IS DISTINCT FROM 'sha256:'||(m->'12'->>'bytes')
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-PUBLICATION-EFFECT'; END IF;
 IF event.proof_kind<>'NOTIFICATION_DELIVERY_REQUEST_REFERENCE'
 OR event.sequence_namespace<>'NOTIFICATION_DELIVERY_REQUESTED_V1'
 OR event.aggregate_type<>'notification-occurrence' OR event.aggregate_id IS DISTINCT FROM occurrence_id
 OR event.aggregate_sequence IS NOT NULL OR event.business_sequence IS DISTINCT FROM 1::numeric
 OR event.receipt_id IS NOT NULL OR event.cose_sign1 IS NOT NULL OR event.authority_generation IS NOT NULL
 OR event.webauthn_assertion_binding_digest IS NOT NULL
 OR event.event_type<>'io.openpc.notification.delivery.requested.v1'
 OR event.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/NotificationDeliveryRequested'
 OR event.source IS DISTINCT FROM 'urn:openpc:service:'||(m->'27'->>'bytes')::uuid::text
 OR event.subject IS DISTINCT FROM 'urn:openpc:notification-occurrence:'||occurrence_id::text
 OR event.correlation_id IS DISTINCT FROM proof.operation_id OR event.causation_id IS DISTINCT FROM source_id
 OR floor(extract(epoch from event.occurred_at)*1000) IS DISTINCT FROM (m->>'23')::numeric
 OR event.payload_digest IS DISTINCT FROM sha256(event.payload_cbor)
 OR m->'29' IS DISTINCT FROM jsonb_build_object('bytes',encode(sha256(event.payload_cbor),'hex'))
 OR openpc.business_cbor(event.payload_cbor) IS DISTINCT FROM jsonb_build_object('0','urn:openpc:notification-occurrence:'||occurrence_id::text,'1','urn:openpc:resource:'||occurrence.endpoint_id::text,'2',m->'19','3',m->'20')
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-PUBLICATION-OUTBOX'; END IF;
 IF (SELECT count(*) FROM control.notification_source_inbox i
 JOIN control.notification_source_cursor cur USING(participant_id,privacy_domain_id,subscription_id,source,partition)
 WHERE i.participant_id=prep.participant_id AND i.privacy_domain_id=prep.privacy_domain_id AND i.event_id=source_id
 AND i.subscription_id IN ('SUB-EVIDENCEEXPORTCOMPLETED-NOTIFICATION-V1','SUB-EVIDENCEEXPORTCOMPLETED-CONTROL_WORK-V1')
 AND i.state='ADMITTED' AND i.source_sequence=1 AND cur.last_sequence=1 AND cur.last_event_id=i.event_id
 AND cur.last_data_digest=i.data_digest AND i.data_digest='sha256:'||(m->'11'->>'bytes')
 AND i.source='urn:openpc:service:'||(source.claims->>'sourceId')
 AND i.partition='urn:openpc:resource:'||source.evidence_export_id::text
 AND i.envelope=source.event_payload AND i.envelope_digest=source.event_payload_digest
 AND i.admission_operation_id=CASE WHEN i.subscription_id='SUB-EVIDENCEEXPORTCOMPLETED-NOTIFICATION-V1' THEN original.operation_id ELSE proof.operation_id END) <> 2
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-PUBLICATION-CURSOR'; END IF;
END $_$;


ALTER FUNCTION openpc.check_notification_delivery_requested_event(event control.outbox_event) OWNER TO openpc_control_owner;

--
-- Name: notification_delivery_signing; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_delivery_signing (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    signing_attempt_id uuid NOT NULL,
    signer_installation_digest text CONSTRAINT notification_delivery_signi_signer_installation_digest_not_null NOT NULL,
    request_digest text NOT NULL,
    preparation jsonb NOT NULL,
    preparation_bytes bytea NOT NULL,
    preparation_digest text NOT NULL,
    state text DEFAULT 'PREPARED'::text NOT NULL,
    dispatch_token uuid,
    dispatched_at_ms numeric(20,0),
    observation jsonb,
    observation_bytes bytea,
    observation_digest text,
    CONSTRAINT notification_delivery_signing_bytes_ck CHECK ((((octet_length(preparation_bytes) >= 1) AND (octet_length(preparation_bytes) <= 524288)) AND (preparation_digest = ('sha256:'::text || encode(sha256(preparation_bytes), 'hex'::text))))),
    CONSTRAINT notification_delivery_signing_state_ck CHECK ((((state = 'PREPARED'::text) AND (dispatch_token IS NULL) AND (dispatched_at_ms IS NULL) AND (observation IS NULL) AND (observation_bytes IS NULL) AND (observation_digest IS NULL)) OR ((state = 'DISPATCHED'::text) AND (dispatch_token IS NOT NULL) AND (dispatched_at_ms IS NOT NULL) AND ((dispatched_at_ms >= (0)::numeric) AND (dispatched_at_ms <= ('9007199254740991'::bigint)::numeric)) AND (observation IS NULL) AND (observation_bytes IS NULL) AND (observation_digest IS NULL)) OR ((state = 'OBSERVED'::text) AND (dispatch_token IS NOT NULL) AND (dispatched_at_ms IS NOT NULL) AND ((dispatched_at_ms >= (0)::numeric) AND (dispatched_at_ms <= ('9007199254740991'::bigint)::numeric)) AND (observation IS NOT NULL) AND (observation_bytes IS NOT NULL) AND (observation_digest IS NOT NULL) AND ((octet_length(observation_bytes) >= 1) AND (octet_length(observation_bytes) <= 196608)) AND (observation_digest = ('sha256:'::text || encode(sha256(observation_bytes), 'hex'::text))))))
);

ALTER TABLE ONLY control.notification_delivery_signing FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification_delivery_signing OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_signing_current(control.notification_delivery_signing); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_signing_current(item control.notification_delivery_signing) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p jsonb:=item.preparation->'deliveryPreparation';d control.notification_delivery%ROWTYPE;
 w control.installed_notification_worker%ROWTYPE;s control.notification_receipt_signer_installation%ROWTYPE;
 i control.installed_notification_channel%ROWTYPE;ep control.notification_endpoint%ROWTYPE;o control.notification_occurrence%ROWTYPE;
 rt control.installed_notification_routing%ROWTYPE;wm jsonb;cm jsonb;actual record;now_ms numeric;lock_name text;before jsonb;
BEGIN
 PERFORM openpc.check_notification_delivery_signing_original(item);
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=p->'source'->'worker'->>'installationDigest';
 SELECT * INTO STRICT s FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest;
 SELECT * INTO STRICT o FROM control.notification_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=(p->'source'->>'notificationOccurrenceId')::uuid;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND endpoint_id=o.endpoint_id FOR SHARE;
 SELECT * INTO STRICT i FROM control.installed_notification_channel WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND credential_ref=o.credential_ref;
 SELECT * INTO STRICT rt FROM control.installed_notification_routing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND signed_profile_digest=w.routing_profile_digest;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||item.participant_id::text,'notification-worker:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-receipt-signer:'||item.participant_id::text||':'||item.privacy_domain_id::text,'notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-routing:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||rt.profile_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
   AND l.mode=CASE WHEN lock_name LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END)
  THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-FENCE'; END IF;
 END LOOP;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));cm:=openpc.business_cbor(decode(i.channel_signed->>'payloadHex','hex'));
 IF w.state<>'ACTIVE' OR s.state<>'ACTIVE' OR i.state<>'ACTIVE' OR ep.state<>'ACTIVE' OR rt.state<>'ACTIVE'
 OR now_ms<(p->'attempt'->>'startedAtMs')::numeric OR now_ms>=(p->'attempt'->>'deadlineAtMs')::numeric OR now_ms>=(p->>'authorityValidUntilMs')::numeric
 OR now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric
 OR now_ms*1000000<(s.trust->>'validFromNs')::numeric OR now_ms*1000000>=(s.trust->>'validUntilNs')::numeric
 OR now_ms<(cm->>'6')::numeric OR now_ms>=(cm->>'7')::numeric
 OR now_ms<(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'6')::numeric
 OR now_ms>=(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'7')::numeric
 OR i.credential->>'state'<>'ACTIVE' OR now_ms<(i.credential->>'validFromMs')::numeric OR now_ms>=(i.credential->>'validUntilMs')::numeric
 OR ep.revision IS DISTINCT FROM o.endpoint_revision OR ep.verification_id IS DISTINCT FROM o.verification_id OR ep.credential_ref IS DISTINCT FROM o.credential_ref
 OR ep.channel IS DISTINCT FROM o.channel OR ep.destination_ref IS DISTINCT FROM o.destination_ref OR ep.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR i.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest OR i.channel IS DISTINCT FROM o.channel OR i.destination_ref IS DISTINCT FROM o.destination_ref
 OR rt.endpoint_id IS DISTINCT FROM o.endpoint_id OR p->'channel' IS DISTINCT FROM jsonb_build_object('claims',jsonb_build_object('environmentId',cm->'1','participantId',(cm->'2'->>'bytes')::uuid::text,'privacyDomainId',(cm->'3'->>'bytes')::uuid::text,'profileId',(cm->'4'->>'bytes')::uuid::text,'revision',cm->>'5','validFromMs',(cm->>'6')::numeric,'validUntilMs',(cm->>'7')::numeric,'transportProfileDigest','sha256:'||(cm->'8'->>'bytes'),'receiptSignerSpki',cm->'9'->>'bytes','issuerKeyId','sha256:'||(cm->'10'->>'bytes')),'transport',i.channel_signed->'transport','signedProfileDigest',i.channel_profile_digest)
 OR NOT EXISTS(SELECT 1 FROM control.notification_endpoint_verification v WHERE v.participant_id=ep.participant_id AND v.privacy_domain_id=ep.privacy_domain_id AND v.verification_id=ep.verification_id
  AND v.endpoint_id=ep.endpoint_id AND v.endpoint_revision=ep.revision AND v.channel=ep.channel AND v.destination_ref=ep.destination_ref AND v.channel_profile_digest=ep.channel_profile_digest AND v.credential_ref=ep.credential_ref)
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) JOIN control.participant t USING(participant_id) JOIN control.privacy_domain v USING(participant_id)
  WHERE c.participant_id=item.participant_id AND c.credential_id=w.workload_credential_id AND a.principal_id=w.principal_id AND v.privacy_domain_id=item.privacy_domain_id
  AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=p->>'workerEpoch' AND c.audience=w.installation->'pins'->>'workloadId'
  AND 'sha256:'||encode(c.public_key_digest,'hex')=w.installation->'pins'->>'workloadKeyDigest' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND a.state='ACTIVE' AND a.kind='WORKLOAD' AND t.state='ACTIVE' AND v.state='ACTIVE')
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) WHERE c.participant_id=item.participant_id AND c.credential_id=i.workload_credential_id
  AND a.principal_id=i.principal_id AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch=i.workload_epoch AND c.audience=i.workload_id
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND a.state='ACTIVE' AND a.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-CURRENT'; END IF;
 SELECT * INTO STRICT actual FROM openpc.current_notification_delivery_limit(item.preparation->'sourceClaims'->>'environmentId');
 IF actual.generation_id::text IS DISTINCT FROM p->>'generationId' OR actual.effective_digest IS DISTINCT FROM p->>'effectiveDigest' OR to_jsonb(actual.configured_limit) IS DISTINCT FROM p->'configuredLimit' OR actual.configured_limit<=0
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-GENERATION'; END IF;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=o.notification_occurrence_id FOR UPDATE;
 before:=jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,
 'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,
 'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,
 'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest);
 IF p->'before' IS DISTINCT FROM before OR d.cancel_requested OR d.state NOT IN ('PENDING','RETRY_WAIT') OR d.attempt_count>=least(d.attempt_limit,actual.configured_limit,6)
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-STATE'; END IF;
END $$;


ALTER FUNCTION openpc.check_notification_delivery_signing_current(item control.notification_delivery_signing) OWNER TO openpc_control_owner;

--
-- Name: check_notification_delivery_signing_original(control.notification_delivery_signing); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_delivery_signing_original(item control.notification_delivery_signing) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p jsonb:=item.preparation;r jsonb:=p->'request';m jsonb;sm jsonb;expected jsonb;
 d control.notification_delivery_preparation%ROWTYPE;s control.notification_receipt_signer_installation%ROWTYPE;
 w control.installed_notification_worker%ROWTYPE;event control.outbox_event%ROWTYPE;proof control.notification_occurrence_observation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_signing_owner();
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-SCOPE'; END IF;
 SELECT * INTO STRICT d FROM control.notification_delivery_preparation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.operation_id;
 SELECT * INTO STRICT s FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=d.worker_installation_digest;
 SELECT * INTO STRICT proof FROM control.notification_occurrence_observation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=d.source_operation_id;
 SELECT * INTO STRICT event FROM control.outbox_event WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND event_id=d.source_event_id;
 PERFORM openpc.check_notification_delivery_requested_event(event);
 sm:=openpc.business_cbor(proof.receipt_payload);
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR p-ARRAY['schema','deliveryPreparation','sourceClaims','trust','request','requestDigest'] IS DISTINCT FROM '{}'::jsonb
 OR (SELECT count(*) FROM jsonb_object_keys(p))<>6 OR p->>'schema' IS DISTINCT FROM 'pc.notification.delivery-signing.v1'
 OR item.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8') OR item.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
 OR p->'deliveryPreparation' IS DISTINCT FROM d.preparation OR p->'sourceClaims' IS DISTINCT FROM jsonb_build_object('environmentId',sm->'1','participantId',(sm->'2'->>'bytes')::uuid::text,'privacyDomainId',(sm->'3'->>'bytes')::uuid::text,'receiptId',(sm->'4'->>'bytes')::uuid::text,'operationId',(sm->'5'->>'bytes')::uuid::text,'notificationId',(sm->'6'->>'bytes')::uuid::text,'notificationOccurrenceId',(sm->'7'->>'bytes')::uuid::text,'payloadObjectId',(sm->'8'->>'bytes')::uuid::text,'keyPreparationId',(sm->'9'->>'bytes')::uuid::text,'sourceEventId',(sm->'10'->>'bytes')::uuid::text,'sourceDataDigest','sha256:'||(sm->'11'->>'bytes'),'sourceReceiptDigest','sha256:'||(sm->'12'->>'bytes'),'routingProfileDigest','sha256:'||(sm->'13'->>'bytes'),'workerProfileDigest','sha256:'||(sm->'14'->>'bytes'),'authoritySnapshotDigest','sha256:'||(sm->'15'->>'bytes'),'custodyDigest','sha256:'||(sm->'16'->>'bytes'),'endpointId',(sm->'17'->>'bytes')::uuid::text,'endpointRevision',sm->>'18','templateDigest','sha256:'||(sm->'19'->>'bytes'),'payloadDigest','sha256:'||(sm->'20'->>'bytes'),'encryptedObjectDigest','sha256:'||(sm->'21'->>'bytes'),'keyId','sha256:'||(sm->'22'->>'bytes'),'recordedAtMs',(sm->>'23')::numeric,'signerKeyId','sha256:'||(sm->'24'->>'bytes'),'occurrenceReceiptDigest','sha256:'||(sm->'25'->>'bytes'),'eventId',(sm->'26'->>'bytes')::uuid::text,'sourceId',(sm->'27'->>'bytes')::uuid::text,'sequence',sm->>'28','dataDigest','sha256:'||(sm->'29'->>'bytes'))
 OR p->'trust' IS DISTINCT FROM jsonb_build_object('signer',s.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId'],'worker',w.installation)
 OR s.worker_installation_digest IS DISTINCT FROM d.worker_installation_digest OR s.trust->>'workerProfileDigest' IS DISTINCT FROM w.signed_profile_digest
 OR s.trust->>'workerIssuerSpkiHex' IS DISTINCT FROM w.installation->'pins'->>'issuerSpkiHex'
 OR s.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-delivery-started-receipt.v1' OR s.trust->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
 OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
