--
-- Name: check_notification_verification_attachment(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_notification_verification_attachment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt control.audit_occurrence%ROWTYPE;
BEGIN
 IF NEW.state<>'ATTACHED' THEN RETURN NEW; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
   AND r.operation_id=NEW.attached_operation_id AND r.aggregate_id=NEW.endpoint_id AND r.catalog_operation_id='CFG-OP-VERIFY-NOTIFICATION-ENDPOINT';
 IF NOT EXISTS(SELECT 1 FROM control.notification_endpoint e WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.endpoint_id=NEW.endpoint_id AND e.verification_id=NEW.attempt_id AND e.state='ACTIVE' AND e.revision=NEW.predecessor_revision+1)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTACHMENT-EFFECT'; END IF;
 PERFORM openpc.assert_notification_endpoint_receipt(receipt);
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.check_notification_verification_attachment() OWNER TO openpc_control_owner;

--
-- Name: check_receipt_signing_attempt_completion(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_receipt_signing_attempt_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.reservation_kind='ORDINARY_ATOMIC' THEN
  IF NOT EXISTS(SELECT 1 FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.operation_id=NEW.operation_id
   AND r.receipt_id=NEW.attempt_id AND r.receipt_cbor=NEW.payload_cbor AND r.receipt_digest=NEW.payload_digest)
  THEN RAISE EXCEPTION 'DATA-6021-INCOMPLETE-ATOMIC-SIGNING-ATTEMPT'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM control.signing_rotation_attestation a JOIN control.signing_provider_attempt p USING(attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
    AND a.operation_id=NEW.operation_id AND a.attempt_id=NEW.attempt_id AND a.receipt_cbor=NEW.payload_cbor
    AND a.signer_id=NEW.signer_id AND a.signer_trust_digest=NEW.signer_trust_digest
    AND a.selection_version=NEW.selection_version AND p.request->>'method'='SIGN_RECEIPT'
    AND p.request->>'payloadHex'=encode(NEW.payload_cbor,'hex') AND p.request->>'attemptId'=NEW.attempt_id::text)
  THEN RAISE EXCEPTION 'DATA-6021-INCOMPLETE-LIFECYCLE-SIGNING-ATTEMPT'; END IF;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.check_receipt_signing_attempt_completion() OWNER TO openpc_control_owner;

--
-- Name: check_rotation_history_completion(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_rotation_history_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.state IN ('REQUESTED','APPROVED') AND NEW.revision<=2 THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.signing_rotation_attestation a
  JOIN control.signing_provider_attempt p USING(attempt_id)
  JOIN control.audit_occurrence r ON r.participant_id=a.participant_id AND r.privacy_domain_id=a.privacy_domain_id AND r.receipt_id=a.attempt_id
  JOIN control.evidence_record e ON e.participant_id=r.participant_id AND e.privacy_domain_id=r.privacy_domain_id AND e.receipt_id=r.receipt_id
  WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.rotation_id=NEW.rotation_id
   AND a.operation_id=NEW.operation_id AND a.attempt_id=NEW.receipt_id AND a.from_revision=NEW.revision-1 AND a.to_state=NEW.state
   AND a.history_preimage=NEW.history_preimage AND a.history_digest=NEW.history_digest AND a.receipt_ordinal=NEW.receipt_ordinal
   AND a.receipt_cbor=r.receipt_cbor AND a.event_id IS NOT DISTINCT FROM NEW.event_id AND a.evidence_record_id=NEW.evidence_id
   AND e.evidence_record_id=NEW.evidence_id AND r.before_revision=NEW.revision-1 AND r.after_revision=NEW.revision
   AND p.state='ACCEPTED' AND p.observation->>'outcome'='SUCCEEDED'
   AND p.observation->>'resultHex'=encode(r.cose_sign1,'hex'))
 THEN RAISE EXCEPTION 'DATA-6021-INCOMPLETE-SIGNED-ROTATION-HISTORY'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.check_rotation_history_completion() OWNER TO openpc_control_owner;

--
-- Name: check_rotation_trust_admission(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_rotation_trust_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rotation control.signing_key_rotation%ROWTYPE; old_key control.business_signing_key%ROWTYPE; proofs integer;
BEGIN
 IF NEW.admission_kind<>'GOVERNED' THEN RETURN NULL; END IF;
 IF NEW.signing_purpose_code=371 THEN
  PERFORM openpc.check_identity_envelope_recovery_trust_admission(NEW);
  RETURN NULL;
 END IF;
 SELECT r.* INTO STRICT rotation FROM control.signing_key_rotation r
 WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND NEW.admission_reference='urn:openpc:resource:'||r.rotation_id::text AND r.new_signer_id=NEW.signer_id
  AND r.state='VERIFIED' AND r.approval_request_id IS NOT NULL;
 SELECT * INTO STRICT old_key FROM control.business_signing_key
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND signer_id=rotation.old_signer_id;
 IF old_key.trust_digest<>rotation.old_trust_digest OR NEW.key_epoch<>old_key.key_epoch+1
  OR NEW.workload_credential_id<>old_key.workload_credential_id OR NEW.workload_credential_epoch<>old_key.workload_credential_epoch
  OR NEW.environment_id<>old_key.environment_id OR NEW.secret_reference<>rotation.request->>'newReference'
  OR NEW.environment_id<>rotation.environment_id OR NEW.workload_credential_id<>rotation.workload_credential_id
  OR NOT EXISTS(SELECT 1 FROM control.signing_provider_attempt a WHERE a.participant_id=NEW.participant_id
    AND a.privacy_domain_id=NEW.privacy_domain_id AND a.rotation_id=rotation.rotation_id AND a.to_state='PREPARED'
    AND a.state='ACCEPTED' AND a.observation->'descriptor'->>'fingerprint'=NEW.signer_id
    AND a.observation->'descriptor'->>'publicKeySpkiHex'=encode(NEW.public_key_spki_der,'hex')
    AND (a.observation->'descriptor'->>'validFromNs')::numeric=NEW.valid_from_ns
    AND (a.observation->'descriptor'->>'validUntilNs')::numeric=NEW.valid_until_ns)
 THEN RAISE EXCEPTION 'DATA-6021-GOVERNED-TRUST-BINDING'; END IF;
 SELECT count(*) INTO proofs FROM control.signing_provider_attempt a
 WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
  AND a.rotation_id=rotation.rotation_id AND a.to_state='VERIFIED' AND a.state='ACCEPTED'
  AND a.request->>'method'='PROVE' AND a.request->>'rotationId'=rotation.rotation_id::text
  AND a.request->>'participantId'=NEW.participant_id::text AND a.request->>'privacyDomainId'=NEW.privacy_domain_id::text
  AND a.request->>'workloadCredentialId'=NEW.workload_credential_id::text
  AND a.request->>'environmentId'=NEW.environment_id AND a.request->>'challengeHex'=encode(NEW.trust_digest,'hex')
  AND a.request->>'expectedFingerprint'=CASE a.slot WHEN 'old' THEN old_key.signer_id WHEN 'new' THEN NEW.signer_id END
  AND a.observation->>'outcome'='SUCCEEDED' AND a.observation->>'attemptId'=a.attempt_id::text
  AND a.observation->>'requestDigest'='sha256:'||encode(a.request_digest,'hex')
  AND a.observation->'descriptor'->>'publicKeySpkiHex'=CASE a.slot WHEN 'old' THEN encode(old_key.public_key_spki_der,'hex') WHEN 'new' THEN encode(NEW.public_key_spki_der,'hex') END;
 IF proofs<>2 THEN RAISE EXCEPTION 'DATA-6021-GOVERNED-DUAL-PROOF'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.check_rotation_trust_admission() OWNER TO openpc_control_owner;

--
-- Name: check_runtime_target_fact_proof(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_runtime_target_fact_proof(proof jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE custody jsonb;
BEGIN
 IF proof->>'sourceMode'='FACT_FREE' THEN
  IF proof ? 'factCustody' THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-PROOF'; END IF;
  RETURN;
 END IF;
 custody:=proof->'factCustody';
 IF proof->>'sourceMode' IS DISTINCT FROM 'FACT_BOUND'
  OR jsonb_typeof(custody) IS DISTINCT FROM 'object'
  OR custody IS DISTINCT FROM jsonb_build_object('version',1,'capsuleDigest',custody->'capsuleDigest',
   'factStateDigest',custody->'factStateDigest','dependencyDigest',custody->'dependencyDigest',
   'originalRecordsDigest',custody->'originalRecordsDigest','validUntilNs',custody->'validUntilNs')
  OR custody->'capsuleDigest' IS DISTINCT FROM proof->'capsuleDigest'
  OR EXISTS(SELECT 1 FROM (VALUES('capsuleDigest'),('factStateDigest'),('dependencyDigest'),('originalRecordsDigest')) f(name)
   WHERE jsonb_typeof(custody->f.name) IS DISTINCT FROM 'string' OR coalesce(custody->>f.name,'') !~ '^[0-9a-f]{64}$')
  OR jsonb_typeof(custody->'validUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(custody->>'validUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR jsonb_typeof(proof->'capsuleValidUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-PROOF'; END IF;
 IF (custody->>'validUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (custody->>'validUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR (custody->>'validUntilNs')::numeric>(proof->>'capsuleValidUntilNs')::numeric
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-EXPIRY'; END IF;
END $_$;


ALTER FUNCTION openpc.check_runtime_target_fact_proof(proof jsonb) OWNER TO openpc_control_owner;

--
-- Name: check_session_step_up_source(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_session_step_up_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE matches bigint;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.step_up_mfa_challenge_id,NEW.step_up_verified_at)
   IS NOT DISTINCT FROM (OLD.step_up_mfa_challenge_id,OLD.step_up_verified_at) THEN RETURN NEW; END IF;
 IF NEW.step_up_mfa_challenge_id IS NULL THEN RETURN NEW; END IF;
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-IDENTITY_UPDATE_STEP_UP-V1'
   OR NEW.step_up_verified_at IS NULL OR NEW.state<>'ACTIVE' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-SOURCE';
 END IF;
 SELECT count(*) INTO matches FROM control.mfa_challenge challenge
  JOIN control.credential credential ON credential.participant_id=challenge.participant_id
   AND credential.principal_id=challenge.principal_id AND credential.credential_id=challenge.signer_credential_id
   AND credential.credential_epoch=challenge.signer_credential_epoch
   AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE'
   AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  JOIN control.authentication_occurrence occurrence ON occurrence.participant_id=challenge.participant_id
   AND occurrence.principal_id=challenge.principal_id AND occurrence.session_id=challenge.session_id
   AND occurrence.source_id=challenge.mfa_challenge_id AND occurrence.method='WEBAUTHN_ASSERTION'
   AND occurrence.credential_id=credential.credential_id AND occurrence.occurred_at=challenge.consumed_at
   AND occurrence.operation_id=openpc.current_operation_id()
  JOIN control.mutation_evidence verification ON verification.participant_id=occurrence.participant_id
   AND verification.privacy_domain_id=occurrence.privacy_domain_id AND verification.principal_id=occurrence.principal_id
   AND verification.operation_id=occurrence.operation_id AND verification.mfa_challenge_id=challenge.mfa_challenge_id
   AND verification.aggregate_id=challenge.session_id AND verification.aggregate_type='webauthn-verification'
   AND verification.action_intent_id='ACT-IDENTITY_UPDATE_STEP_UP-V1'
   AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
   AND verification.signer_credential_id=credential.credential_id
   AND verification.webauthn_assertion_binding_digest=occurrence.proof_digest
   AND verification.evidence_digest=sha256(verification.evidence_cbor)
   AND verification.bound_participant_epoch=NEW.participant_epoch AND verification.bound_principal_epoch=NEW.authority_epoch
   AND verification.occurred_at>=challenge.consumed_at
  JOIN control.idempotency_record committed ON committed.participant_id=verification.participant_id
   AND committed.privacy_domain_id=verification.privacy_domain_id AND committed.principal_id=verification.principal_id
   AND committed.operation_id=verification.operation_id AND committed.catalog_operation_id=verification.catalog_operation_id
   AND committed.input_digest=verification.candidate_digest AND committed.terminal_state='COMMITTED'
   AND committed.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
  JOIN control.outbox_event event ON event.participant_id=verification.participant_id
   AND event.privacy_domain_id=verification.privacy_domain_id AND event.aggregate_type=verification.aggregate_type
   AND event.aggregate_id=verification.aggregate_id AND event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
   AND event.payload_cbor=verification.evidence_cbor AND event.payload_digest=verification.evidence_digest
   AND event.cose_sign1=verification.cose_sign1 AND event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
  WHERE challenge.participant_id=NEW.participant_id AND challenge.principal_id=NEW.principal_id
   AND challenge.session_id=NEW.session_id AND challenge.mfa_challenge_id=NEW.step_up_mfa_challenge_id
   AND challenge.consumed_at=NEW.step_up_verified_at AND challenge.created_at<=challenge.consumed_at
   AND challenge.consumed_at<=clock_timestamp() AND challenge.expires_at>clock_timestamp()
   AND NEW.idle_expires_at>clock_timestamp() AND NEW.absolute_expires_at>clock_timestamp()
   AND (challenge.verified_proof_max_age_ms=300000 OR
     (challenge.verified_proof_max_age_ms=3000000 AND NEW.duration_profile='LOCAL_QA_10X'));
 IF matches<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-SOURCE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.check_session_step_up_source() OWNER TO openpc_control_owner;

--
-- Name: check_signing_continuation_context(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_continuation_context(context jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE command control.signing_rotation_command%ROWTYPE; attempt control.signing_provider_attempt%ROWTYPE;
 rotation control.signing_key_rotation%ROWTYPE; workload control.credential%ROWTYPE; snapshot jsonb;
 authority jsonb; evidence control.mutation_evidence%ROWTYPE; expected jsonb;
BEGIN
 SELECT * INTO STRICT attempt FROM control.signing_provider_attempt WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND attempt_id=(context->>'providerAttemptId')::uuid
  AND state='OBSERVED' AND dispatched_at_ns IS NOT NULL AND request->>'method' IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE');
 authority:=openpc.signing_attempt_authority_status(attempt.attempt_id);
 SELECT * INTO STRICT command FROM control.signing_rotation_command WHERE participant_id=attempt.participant_id
  AND privacy_domain_id=attempt.privacy_domain_id AND operation_id=attempt.operation_id AND state IN ('ACCEPTED','WRITE_AMBIGUITY')
  AND action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1';
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=attempt.participant_id
  AND privacy_domain_id=attempt.privacy_domain_id AND rotation_id=attempt.rotation_id AND approval_request_id IS NOT NULL;
 SELECT * INTO STRICT workload FROM control.credential c WHERE c.participant_id=attempt.participant_id
  AND c.credential_id=rotation.workload_credential_id AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS'
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND EXISTS(SELECT 1 FROM control.principal p WHERE p.participant_id=c.participant_id AND p.principal_id=c.principal_id
   AND p.kind='WORKLOAD' AND p.state='ACTIVE');
 SELECT * INTO STRICT evidence FROM control.mutation_evidence WHERE participant_id=command.participant_id
  AND privacy_domain_id=command.privacy_domain_id AND mutation_evidence_id=command.authorization_evidence_id
  AND operation_id=command.operation_id;
 IF NOT ((rotation.revision=attempt.from_revision AND rotation.state=attempt.from_state) OR
  (rotation.state='RECOVERING' AND rotation.recovery_from_revision=attempt.from_revision AND rotation.recovery_from_state=attempt.from_state))
  OR command.from_revision<>attempt.from_revision OR command.to_state<>attempt.to_state
  OR attempt.observation->>'attemptId'<>attempt.attempt_id::text OR attempt.observation->>'operationId'<>attempt.operation_id::text
  OR attempt.observation->>'method'<>attempt.request->>'method'
  OR attempt.observation->>'requestDigest'<>'sha256:'||encode(attempt.request_digest,'hex')
  OR attempt.observation->>'outcome' NOT IN ('SUCCEEDED','REJECTED')
  OR command.to_state IS DISTINCT FROM (CASE attempt.request->>'method' WHEN 'PREPARE' THEN 'PREPARED'
   WHEN 'DISTRIBUTE' THEN 'DISTRIBUTED' WHEN 'REVOKE' THEN 'OLD_REVOKED' WHEN 'RETIRE' THEN 'OLD_RETIRED' END)
  OR EXISTS(SELECT 1 FROM control.signing_rotation_command recovery WHERE recovery.participant_id=command.participant_id
   AND recovery.privacy_domain_id=command.privacy_domain_id AND recovery.original_operation_id=command.operation_id AND recovery.state='ACCEPTED')
 THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-EXACT-DISPATCHED-ATTEMPT'; END IF;
 snapshot:=convert_from(command.authorization_snapshot,'UTF8')::jsonb;
 expected:=jsonb_build_object('version',1,'purpose','SIGNING_ROTATION_ATTEMPT_RECONCILE_V1',
  'effect','FINALIZE_EXISTING_SIGNING_ROTATION_ATTEMPT','participantId',attempt.participant_id::text,
  'privacyDomainId',attempt.privacy_domain_id::text,'rotationId',rotation.rotation_id::text,'rotationRevision',rotation.revision::text,
  'operationId',command.operation_id::text,'actionIntentId',command.action_intent_id,'targetState',command.to_state,
  'candidateDigest','sha256:'||encode(command.approval_candidate_digest,'hex'),'approvalRequestId',command.approval_request_id::text,
  'originalActorKeyDigest','sha256:'||(openpc.business_cbor(evidence.evidence_cbor)->'1'->>'bytes'),
  'originalAuthoritySnapshotDigest','sha256:'||encode(command.authorization_snapshot_digest,'hex'),
  'originalMakerSnapshotDigest','sha256:'||encode(sha256(convert_to((snapshot->'authorities'->1)::text,'UTF8')),'hex'),
  'originalCheckerSnapshotDigest','sha256:'||encode(sha256(convert_to((snapshot->'authorities'->2)::text,'UTF8')),'hex'),
  'providerAttemptId',attempt.attempt_id::text,'providerMethod',attempt.request->>'method',
  'providerRequestDigest','sha256:'||encode(attempt.request_digest,'hex'),
  'providerObservationDigest','sha256:'||encode(attempt.observation_digest,'hex'),
  'resultDisposition',CASE WHEN attempt.observation->>'outcome'='SUCCEEDED' THEN 'APPLY_RESERVED_TARGET'
   WHEN attempt.observation->>'reason'='NOT_APPLIED' THEN 'NO_EFFECT_RETRYABLE' ELSE 'ENTER_FAILED_STATE' END,
  'workloadPrincipalId',workload.principal_id::text,'workloadCredentialId',workload.credential_id::text,
  'workloadCredentialEpoch',workload.credential_epoch::text,'workloadKeyDigest','sha256:'||encode(workload.public_key_digest,'hex'),
  'currentAuthorityStatus',CASE WHEN (authority->>'unchangedLive')::boolean THEN 'UNCHANGED_LIVE' ELSE 'CHANGED' END,
  'currentAuthorityDigest','sha256:'||encode(openpc.signing_continuation_authority_digest(authority),'hex'));
 IF context IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-CONTEXT'; END IF;
END $$;


ALTER FUNCTION openpc.check_signing_continuation_context(context jsonb) OWNER TO openpc_control_owner;

--
-- Name: check_signing_continuation_snapshot(bytea, uuid, uuid, uuid, uuid, numeric, boolean); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_continuation_snapshot(p_snapshot bytea, p_participant uuid, p_privacy uuid, p_operation uuid, p_receipt uuid, p_recorded_ns numeric, p_consumed boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE snapshot jsonb; capability control.signing_continuation%ROWTYPE; expected jsonb;
BEGIN
 snapshot:=convert_from(p_snapshot,'UTF8')::jsonb;
 SELECT * INTO STRICT capability FROM control.signing_continuation WHERE participant_id=p_participant AND privacy_domain_id=p_privacy
  AND operation_id=p_operation AND assertion_id=(snapshot->>'continuationAssertionId')::uuid
  AND state=CASE WHEN p_consumed THEN 'CONSUMED' ELSE 'ISSUED' END;
 expected:=jsonb_build_object('schema','pc.control.signing-rotation-continuation-snapshot.v1',
  'participantId',p_participant::text,'privacyDomainId',p_privacy::text,'operationId',p_operation::text,
  'recordedAtNs',snapshot->'recordedAtNs','decision','RECORD_DISPATCHED_TRUTH','continuationAssertionId',capability.assertion_id::text,
  'continuationAssertionDigest','sha256:'||encode(capability.assertion_digest,'hex'),'context',convert_from(capability.context_preimage,'UTF8')::jsonb);
 IF snapshot IS DISTINCT FROM expected OR jsonb_typeof(snapshot->'recordedAtNs') IS DISTINCT FROM 'string'
  OR NOT ((snapshot->>'recordedAtNs') ~ '^[0-9]{1,20}$') OR (snapshot->>'recordedAtNs')::numeric>p_recorded_ns
  OR p_recorded_ns<capability.issued_at_ns OR p_recorded_ns>=capability.expires_at_ns
  OR (p_consumed AND (capability.consumed_receipt_id IS DISTINCT FROM p_receipt OR capability.consumed_at_ns<p_recorded_ns))
  OR (NOT p_consumed AND capability.expires_at_ns<=floor(extract(epoch FROM clock_timestamp())*1000000)*1000)
 THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-RECEIPT-SNAPSHOT'; END IF;
 IF NOT p_consumed THEN PERFORM openpc.check_signing_continuation_context(snapshot->'context'); END IF;
END $_$;


ALTER FUNCTION openpc.check_signing_continuation_snapshot(p_snapshot bytea, p_participant uuid, p_privacy uuid, p_operation uuid, p_receipt uuid, p_recorded_ns numeric, p_consumed boolean) OWNER TO openpc_control_owner;

--
-- Name: check_signing_generation_completion(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_generation_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.state<>'CONSUMED' THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_candidate candidate JOIN control.signing_rotation_command command
  ON command.participant_id=candidate.participant_id AND command.privacy_domain_id=candidate.privacy_domain_id
   AND command.operation_id=candidate.consumed_operation_id JOIN control.audit_occurrence receipt
   ON receipt.participant_id=command.participant_id AND receipt.privacy_domain_id=command.privacy_domain_id AND receipt.operation_id=command.operation_id
  WHERE candidate.mutation_candidate_id=NEW.candidate_id AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=NEW.consumed_operation_id
   AND command.authorization_generation_id=NEW.generation_id AND command.state IN ('SUCCEEDED','FAILED') AND command.result_revision=NEW.result_revision
   AND receipt.after_revision=NEW.result_revision AND receipt.before_revision=NEW.from_revision
   AND (NEW.hold_id IS NULL OR EXISTS(SELECT 1 FROM control.signing_rotation_authority_hold h WHERE h.hold_id=NEW.hold_id
    AND h.state='CLEARED' AND h.cleared_by_operation_id=NEW.consumed_operation_id)))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GENERATION-INCOMPLETE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.check_signing_generation_completion() OWNER TO openpc_control_owner;

--
-- Name: check_signing_generation_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_generation_current(p_generation uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE generation control.signing_authorization_generation%ROWTYPE; candidate control.mutation_candidate%ROWTYPE;
BEGIN
 SELECT * INTO STRICT generation FROM control.signing_authorization_generation WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND generation_id=p_generation AND state='STAGED';
 SELECT * INTO STRICT candidate FROM control.mutation_candidate WHERE participant_id=generation.participant_id
  AND privacy_domain_id=generation.privacy_domain_id AND mutation_candidate_id=generation.candidate_id
  AND candidate_digest=generation.candidate_digest AND state='APPROVED' AND expires_at>clock_timestamp();
 IF candidate.candidate_document->'context' IS DISTINCT FROM openpc.signing_governance_context(generation.rotation_id,generation.action_intent_id)
  OR NOT EXISTS(SELECT 1 FROM control.approval_request a JOIN control.approval_decision_record d
   USING(participant_id,privacy_domain_id,approval_request_id) WHERE a.participant_id=generation.participant_id
    AND a.privacy_domain_id=generation.privacy_domain_id AND a.subject_id=generation.candidate_id AND a.subject_digest=generation.candidate_digest
    AND a.subject_version=generation.from_revision AND a.state='APPROVED' AND a.expires_at>clock_timestamp()
    AND d.decision='APPROVE' AND d.approver_principal_id<>a.maker_principal_id AND d.candidate_digest=generation.candidate_digest)
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GOVERNANCE-STALE'; END IF;
END $$;


ALTER FUNCTION openpc.check_signing_generation_current(p_generation uuid) OWNER TO openpc_control_owner;

--
-- Name: check_signing_no_effect_completion(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_no_effect_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.signing_rotation_command c JOIN control.idempotency_record i USING(participant_id,privacy_domain_id,operation_id)
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.operation_id=NEW.operation_id
   AND c.state='FAILED' AND c.result_kind=NEW.kind AND c.result_revision=(convert_from(NEW.preimage,'UTF8')::jsonb->>'currentRevision')::bigint AND i.terminal_state='COMMITTED'
   AND i.result_payload->>'state'='FAILED' AND i.result_payload->'signingResult'->>'kind'=NEW.kind)
  OR EXISTS(SELECT 1 FROM control.signing_rotation_history h WHERE h.participant_id=NEW.participant_id
   AND h.privacy_domain_id=NEW.privacy_domain_id AND h.operation_id=NEW.operation_id)
  OR EXISTS(SELECT 1 FROM control.audit_occurrence a WHERE a.participant_id=NEW.participant_id
   AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=NEW.operation_id)
  OR EXISTS(SELECT 1 FROM control.signing_provider_attempt a WHERE a.participant_id=NEW.participant_id
   AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=NEW.operation_id
   AND ((NEW.kind='AUTHORITY_CHANGED_BEFORE_DISPATCH' AND a.state<>'CANCELLED') OR
    (NEW.kind='NO_EFFECT_RETRYABLE' AND a.state NOT IN ('REJECTED','SUPERSEDED'))))
 THEN RAISE EXCEPTION 'DATA-6021-NO-EFFECT-ATOMIC-COMPLETION'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.check_signing_no_effect_completion() OWNER TO openpc_control_owner;

--
-- Name: check_signing_rotation_event(control.outbox_event, control.audit_occurrence); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_rotation_event(event control.outbox_event, receipt control.audit_occurrence) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE state jsonb; expected_type text; expected_schema text; effects jsonb;
BEGIN
 state:=openpc.business_cbor(receipt.after_state_preimage)->8;
 effects:=openpc.signing_transition_effects(receipt.action_intent_id,openpc.business_cbor(receipt.before_state_preimage)->8->>'0',state->>'0');
 expected_type:=effects->>'eventType';
 expected_schema:=CASE expected_type WHEN 'io.openpc.ops.secret.revoked.v1' THEN 'SecretRevoked' WHEN 'io.openpc.ops.secret.rotated.v1' THEN 'SecretRotated' END;
 IF expected_type IS NULL OR receipt.catalog_operation_id<>'OPS-OP-ADVANCE-SIGNING-KEY-ROTATION'
  OR event.event_type IS DISTINCT FROM expected_type
  OR event.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/'||expected_schema
  OR event.aggregate_type<>receipt.aggregate_type OR event.aggregate_id<>receipt.aggregate_id
  OR event.payload_digest<>sha256(event.payload_cbor) OR state->>'5'<>'1'
  OR openpc.business_cbor(event.payload_cbor) IS DISTINCT FROM jsonb_build_object('0',openpc.business_uuid(receipt.aggregate_id),
    '1',state->>'3','2',state->'4','3',state->'6')
 THEN RAISE EXCEPTION 'DATA-6021-LIFECYCLE-STATE-EVENT'; END IF;
END $_$;


ALTER FUNCTION openpc.check_signing_rotation_event(event control.outbox_event, receipt control.audit_occurrence) OWNER TO openpc_control_owner;

--
-- Name: check_signing_rotation_receipt(control.audit_occurrence); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_signing_rotation_receipt(receipt control.audit_occurrence) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rotation control.signing_key_rotation%ROWTYPE; history control.signing_rotation_history%ROWTYPE;
 previous control.signing_rotation_history%ROWTYPE; attestation control.signing_rotation_attestation%ROWTYPE;
 before_new text; before_projection jsonb; after_projection jsonb; self_cutover boolean; effects jsonb;
BEGIN
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND rotation_id=receipt.aggregate_id AND revision=receipt.after_revision;
 SELECT * INTO STRICT history FROM control.signing_rotation_history WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND rotation_id=receipt.aggregate_id AND revision=receipt.after_revision
  AND receipt_id=receipt.receipt_id AND operation_id=receipt.operation_id;
 SELECT * INTO STRICT previous FROM control.signing_rotation_history WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND rotation_id=receipt.aggregate_id AND revision=receipt.before_revision;
 SELECT * INTO STRICT attestation FROM control.signing_rotation_attestation WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND rotation_id=receipt.aggregate_id AND operation_id=receipt.operation_id
  AND attempt_id=receipt.receipt_id AND from_revision=receipt.before_revision AND to_state=rotation.state;
 effects:=openpc.signing_transition_effects(receipt.action_intent_id,previous.state,rotation.state);
 IF effects IS NULL THEN RAISE EXCEPTION 'DATA-6022-SIGNING-TRANSITION-MATRIX'; END IF;
 IF attestation.receipt_cbor<>receipt.receipt_cbor OR attestation.authority_snapshot<>receipt.authority_snapshot
  OR attestation.before_state_preimage<>receipt.before_state_preimage OR attestation.after_state_preimage<>receipt.after_state_preimage
  OR attestation.history_digest<>history.history_digest OR receipt.after_revision<>receipt.before_revision+1
  OR jsonb_array_length(openpc.business_cbor(receipt.receipt_cbor)->'21')<>(CASE WHEN effects->>'eventType' IS NOT NULL THEN 1 ELSE 0 END)
  OR (effects->>'eventType' IS NOT NULL AND
    openpc.business_cbor(receipt.receipt_cbor)->'21'->0->'0' IS DISTINCT FROM openpc.business_uuid(attestation.event_id))
 THEN RAISE EXCEPTION 'DATA-6021-LIFECYCLE-RECEIPT-HISTORY'; END IF;
 before_new:=convert_from(previous.history_preimage,'UTF8')::jsonb->>'newFingerprint';
 before_projection:=jsonb_build_object('0',previous.state,'1',openpc.business_bytes(rotation.candidate_digest),
  '2',openpc.business_bytes(previous.history_digest),'3',rotation.request->>'signerRole',
  '4',openpc.business_bytes(decode(substring(rotation.old_signer_id from 8),'hex')),'5',CASE WHEN before_new IS NULL THEN 0 ELSE 1 END)
  ||CASE WHEN before_new IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('6',openpc.business_bytes(decode(substring(before_new from 8),'hex'))) END;
 after_projection:=jsonb_build_object('0',rotation.state,'1',openpc.business_bytes(rotation.candidate_digest),
  '2',openpc.business_bytes(history.history_digest),'3',rotation.request->>'signerRole',
  '4',openpc.business_bytes(decode(substring(rotation.old_signer_id from 8),'hex')),'5',CASE WHEN rotation.new_signer_id IS NULL THEN 0 ELSE 1 END)
  ||CASE WHEN rotation.new_signer_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('6',openpc.business_bytes(decode(substring(rotation.new_signer_id from 8),'hex'))) END;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM before_projection OR
  openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM after_projection
 THEN RAISE EXCEPTION 'DATA-6021-LIFECYCLE-ACTUAL-STATE'; END IF;
 self_cutover:=rotation.request->>'signerRole'='LIFECYCLE_EVIDENCE' AND (effects->>'cutover')::boolean
  AND receipt.signer_id=rotation.old_signer_id AND receipt.recorded_at_ns=rotation.cutover_at_ns;
 IF NOT EXISTS(SELECT 1 FROM control.receipt_signing_attempt a
  JOIN control.business_signing_key k ON k.participant_id=a.participant_id AND k.privacy_domain_id=a.privacy_domain_id AND k.signer_id=a.signer_id
  JOIN control.business_signing_key_state ks ON ks.participant_id=a.participant_id AND ks.privacy_domain_id=a.privacy_domain_id AND ks.signer_id=a.signer_id
  JOIN control.business_signing_selection s ON s.participant_id=a.participant_id AND s.privacy_domain_id=a.privacy_domain_id
   AND s.environment_id=k.environment_id AND s.profile_digest=a.profile_digest
  JOIN control.credential c ON c.participant_id=k.participant_id AND c.credential_id=k.workload_credential_id
  JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
  WHERE a.participant_id=receipt.participant_id AND a.privacy_domain_id=receipt.privacy_domain_id AND a.attempt_id=receipt.receipt_id
   AND a.reservation_kind='LIFECYCLE_DURABLE' AND a.payload_cbor=receipt.receipt_cbor AND a.operation_id=receipt.operation_id
   AND k.trust_digest=receipt.signer_trust_snapshot_digest AND k.key_epoch=a.key_epoch AND k.environment_id=receipt.environment_id
   AND k.valid_from_ns<=receipt.recorded_at_ns AND k.valid_until_ns>receipt.recorded_at_ns
   AND c.credential_epoch=k.workload_credential_epoch AND c.state='ACTIVE' AND p.state='ACTIVE' AND p.kind='WORKLOAD'
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND openpc.retained_signing_admission_matches(a.participant_id,a.privacy_domain_id,a.signer_id,a.operation_id,a.admission_version,s.admission_version)
   AND s.fenced_operation_id IS NULL AND ((NOT self_cutover AND ks.state='ACTIVE' AND s.signer_id=a.signer_id
    AND s.row_version=a.selection_version AND s.fence_generation=a.fence_generation
    AND k.valid_until_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000)
    OR (self_cutover AND ks.state='RETIRED' AND s.signer_id=rotation.new_signer_id
     AND s.row_version=a.selection_version+2 AND s.fence_generation=a.fence_generation+1))
   FOR SHARE OF s,ks,c,p)
 THEN RAISE EXCEPTION 'DATA-6021-LIFECYCLE-SIGNER-FENCE'; END IF;
END $$;


ALTER FUNCTION openpc.check_signing_rotation_receipt(receipt control.audit_occurrence) OWNER TO openpc_control_owner;

--
-- Name: check_work_item_effect_receipt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_work_item_effect_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt control.audit_occurrence%ROWTYPE; before_projection jsonb;
BEGIN
 -- WHEN is evaluated when the row changes, so later context changes cannot
 -- remove the queued check. Internal source-owned effects retain their owners.
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.aggregate_type='work-item'
  AND r.aggregate_id=NEW.work_item_id AND r.after_revision=NEW.row_version
  AND r.catalog_operation_id IN ('CFG-OP-CREATE-WORK-ITEM','CFG-OP-UPDATE-WORK-ITEM',
   'CFG-OP-CLAIM-WORK-ITEM','CFG-OP-COMPLETE-WORK-ITEM');
 IF TG_OP='INSERT' THEN before_projection:='{}'::jsonb;
 ELSE before_projection:=openpc.work_item_business_projection(OLD); END IF;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM before_projection
  OR openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM openpc.work_item_business_projection(NEW)
  OR receipt.before_revision IS DISTINCT FROM (CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.row_version END)
 THEN RAISE EXCEPTION 'DATA-6021-WORK-ITEM-EFFECT-RECEIPT'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.check_work_item_effect_receipt() OWNER TO openpc_control_owner;

--
-- Name: workload_renewal_policy; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.workload_renewal_policy (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    revision numeric(20,0) NOT NULL,
    principal_id uuid NOT NULL,
    workload_id text NOT NULL,
    digest bytea NOT NULL,
    governance_operation_id uuid NOT NULL,
    business_ancestors jsonb NOT NULL,
    attestation_profile_digest bytea NOT NULL,
    issuer_profile_digest bytea NOT NULL,
    provider_qualification_digest bytea NOT NULL,
    valid_from timestamp(6) with time zone NOT NULL,
    valid_until timestamp(6) with time zone NOT NULL,
    state text NOT NULL,
    definition jsonb NOT NULL,
    definition_canonical bytea NOT NULL,
    CONSTRAINT wr_policy_bounds_ck CHECK ((((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric)) AND (valid_until > valid_from) AND (state = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'REVOKED'::text])) AND (jsonb_typeof(business_ancestors) = 'array'::text) AND ((jsonb_array_length(business_ancestors) >= 1) AND (jsonb_array_length(business_ancestors) <= 64)))),
    CONSTRAINT wr_policy_definition_ck CHECK ((((octet_length(definition_canonical) >= 1) AND (octet_length(definition_canonical) <= 65536)) AND (digest = sha256(definition_canonical)) AND (jsonb_typeof(definition) = 'object'::text))),
    CONSTRAINT wr_policy_digests_ck CHECK (((octet_length(digest) = 32) AND (octet_length(attestation_profile_digest) = 32) AND (octet_length(issuer_profile_digest) = 32) AND (octet_length(provider_qualification_digest) = 32)))
);

ALTER TABLE ONLY control.workload_renewal_policy FORCE ROW LEVEL SECURITY;


ALTER TABLE control.workload_renewal_policy OWNER TO openpc_control_owner;

--
-- Name: check_workload_renewal_policy_ancestors(control.workload_renewal_policy, control.audit_occurrence); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.check_workload_renewal_policy_ancestors(policy control.workload_renewal_policy, receipt control.audit_occurrence) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snapshot jsonb:=convert_from(receipt.authority_snapshot,'UTF8')::jsonb; ancestor jsonb; bound jsonb;
 grant_row jsonb; path jsonb; expected jsonb; assignment control.assignment%ROWTYPE; delegation control.delegation%ROWTYPE;
 root uuid; prior_delegation uuid; principal_ids uuid[]; delegation_ids uuid[]; path_role_id uuid; i integer:=0; id uuid;
BEGIN
 IF jsonb_array_length(policy.business_ancestors)<>jsonb_array_length(snapshot->'authorities') THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENTS'; END IF;
 FOR ancestor IN SELECT value FROM jsonb_array_elements(policy.business_ancestors) LOOP
  bound:=snapshot->'authorities'->i;i:=i+1;grant_row:=ancestor->'grant';path:=ancestor->'dependencies'->'path';
  IF ancestor IS DISTINCT FROM jsonb_build_object('grant',grant_row,'dependencies',ancestor->'dependencies')
   OR grant_row-'catalogOperationId' IS DISTINCT FROM bound-ARRAY['sessionId','sessionEpoch']
   OR (grant_row ? 'catalogOperationId' AND grant_row->>'catalogOperationId'<>receipt.catalog_operation_id)
   OR path IS DISTINCT FROM jsonb_build_object('delegationIds',path->'delegationIds','principalIds',path->'principalIds','roleId',path->'roleId')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-BINDING'; END IF;
  SELECT * INTO STRICT assignment FROM control.assignment a WHERE a.participant_id=policy.participant_id
   AND a.assignment_id=(grant_row->>'assignmentId')::uuid;
  root:=assignment.principal_id;principal_ids:=ARRAY[root];delegation_ids:=ARRAY[]::uuid[];prior_delegation:=NULL;
  IF jsonb_typeof(path->'delegationIds') IS DISTINCT FROM 'array' OR jsonb_array_length(path->'delegationIds')>32 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  FOR id IN SELECT value::uuid FROM jsonb_array_elements_text(path->'delegationIds') LOOP
   SELECT * INTO STRICT delegation FROM control.delegation d WHERE d.participant_id=policy.participant_id AND d.delegation_id=id;
   IF id=ANY(delegation_ids) OR delegation.grantor_principal_id<>root
    OR (prior_delegation IS NULL AND (delegation.parent_assignment_id IS DISTINCT FROM assignment.assignment_id OR delegation.parent_delegation_id IS NOT NULL))
    OR (prior_delegation IS NOT NULL AND delegation.parent_delegation_id IS DISTINCT FROM prior_delegation)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-PATH'; END IF;
   delegation_ids:=delegation_ids||id;root:=delegation.delegate_principal_id;principal_ids:=principal_ids||root;prior_delegation:=id;
  END LOOP;
  SELECT r.authority_role_id INTO path_role_id FROM control.authority_role r WHERE r.participant_id=policy.participant_id AND r.role_id=assignment.role_id;
  IF root IS DISTINCT FROM (grant_row->>'principalId')::uuid OR path IS DISTINCT FROM jsonb_build_object(
   'delegationIds',to_jsonb(delegation_ids),'principalIds',to_jsonb(principal_ids),'roleId',path_role_id) THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-PATH'; END IF;
  SELECT jsonb_build_object('path',path,
   'principals',(SELECT jsonb_agg(jsonb_build_array(principal_id,authority_epoch::text) ORDER BY principal_id)
    FROM control.principal WHERE participant_id=policy.participant_id AND principal_id=ANY(principal_ids)),
   'privacy',(SELECT row_version::text FROM control.privacy_domain WHERE participant_id=policy.participant_id AND privacy_domain_id=(grant_row->>'privacyDomainId')::uuid),
   'role',(SELECT row_version::text FROM control.authority_role WHERE participant_id=policy.participant_id AND authority_role_id=path_role_id),
   'delegations',(SELECT jsonb_agg(jsonb_build_array(delegation_id,delegation_epoch::text,row_version::text) ORDER BY delegation_id)
    FROM control.delegation WHERE participant_id=policy.participant_id AND delegation_id=ANY(delegation_ids))) INTO expected;
  IF ancestor->'dependencies' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-PARENT-EPOCHS'; END IF;
 END LOOP;
END $$;


ALTER FUNCTION openpc.check_workload_renewal_policy_ancestors(policy control.workload_renewal_policy, receipt control.audit_occurrence) OWNER TO openpc_control_owner;

--
-- Name: cigl_profile_has_installed_lineage(uuid, bigint, uuid, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.cigl_profile_has_installed_lineage(p_profile uuid, p_revision bigint, p_target uuid, p_capsule text, p_policy text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT EXISTS(
  SELECT 1 FROM control.cigl_profile_version version
  JOIN control.cigl_analysis analysis ON analysis.analysis_id=version.analysis_id
   AND analysis.participant_id=version.participant_id AND analysis.privacy_domain_id=version.privacy_domain_id
  JOIN control.runtime_target target ON target.runtime_target_id=analysis.runtime_target_id
   AND target.participant_id=analysis.participant_id AND target.privacy_domain_id=analysis.privacy_domain_id
  WHERE version.profile_id=p_profile AND version.revision=p_revision AND version.state='COMPILED'
   AND version.participant_id=openpc.current_participant_id() AND version.privacy_domain_id=openpc.current_privacy_domain_id()
   AND analysis.state='REVIEWED' AND analysis.revision=3 AND analysis.runtime_target_id=p_target
   AND target.active_generation_digest=p_capsule
   AND ((analysis.capsule_digest=p_capsule AND analysis.policy_generation_digest=p_policy) OR EXISTS(
    SELECT 1 FROM control.runtime_activation_observation observation
    JOIN control.runtime_configuration_generation generation
     ON generation.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
      AND generation.participant_id=observation.participant_id AND generation.privacy_domain_id=observation.privacy_domain_id
    JOIN control.configuration_work work ON work.configuration_work_id=observation.configuration_work_id
     AND work.participant_id=observation.participant_id AND work.privacy_domain_id=observation.privacy_domain_id
     AND work.operation_id=observation.operation_id AND work.execution_attempt_id=observation.execution_attempt_id
     AND work.runtime_configuration_generation_id=generation.runtime_configuration_generation_id
     AND work.runtime_target_id=observation.runtime_target_id AND work.xds_version_digest=observation.xds_version_digest
     AND work.generation_digest=generation.generation_digest
    WHERE observation.participant_id=version.participant_id AND observation.privacy_domain_id=version.privacy_domain_id
     AND observation.runtime_target_id=p_target AND observation.capsule_digest=p_capsule
     AND generation.runtime_target_id=p_target AND generation.policy_generation_digest=p_policy AND generation.state='ACTIVE'
     AND work.work_kind='RUNTIME_ACTIVATION' AND work.state='COMPLETED' AND work.execution_started_at IS NOT NULL
     AND work.result_receipt_digest=observation.activation_receipt_digest
     AND generation.cigl_profile_selection->'profiles' @> jsonb_build_array(jsonb_build_object(
      'profileId','urn:openpc:resource:'||version.profile_id::text,'profileRevision',version.revision::text,
      'profileDigest',version.profile_digest,'compilationArtifactDigest',version.artifact_digest)))))
$$;


ALTER FUNCTION openpc.cigl_profile_has_installed_lineage(p_profile uuid, p_revision bigint, p_target uuid, p_capsule text, p_policy text) OWNER TO openpc_control_owner;

--
-- Name: cigl_subject_current(uuid, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.cigl_subject_current(p_participant uuid, p_subject jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE kind text:=p_subject->>'kind'; id text:=p_subject->>'id';
BEGIN
 IF jsonb_typeof(p_subject) IS DISTINCT FROM 'object' OR (p_subject-ARRAY['kind','id']) IS DISTINCT FROM '{}'::jsonb
  OR jsonb_typeof(p_subject->'kind') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 IF kind='ANY_AUTHENTICATED' THEN RETURN p_subject='{"kind":"ANY_AUTHENTICATED"}'::jsonb; END IF;
 IF jsonb_typeof(p_subject->'id') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
 IF kind IN ('ROLE','WORKLOAD') THEN
  IF (id ~ ('^urn:openpc:'||lower(kind)||':[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) IS DISTINCT FROM true THEN RETURN false; END IF;
 ELSIF (id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') IS DISTINCT FROM true THEN RETURN false; END IF;
 CASE kind
 WHEN 'ANY_AUTHENTICATED' THEN RETURN p_subject='{"kind":"ANY_AUTHENTICATED"}'::jsonb;
 WHEN 'ROLE' THEN RETURN EXISTS(SELECT 1 FROM control.authority_role WHERE participant_id=p_participant AND role_id=id AND state='ACTIVE');
 WHEN 'WORKLOAD' THEN RETURN EXISTS(SELECT 1 FROM control.credential credential
  JOIN control.principal principal ON principal.participant_id=credential.participant_id AND principal.principal_id=credential.principal_id
  WHERE credential.participant_id=p_participant AND credential.audience=id AND credential.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
   AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp()) AND principal.kind='WORKLOAD' AND principal.state='ACTIVE');
 WHEN 'USER' THEN RETURN EXISTS(SELECT 1 FROM control.principal principal WHERE principal.participant_id=p_participant AND principal.principal_id=id::uuid AND principal.kind='USER' AND principal.state='ACTIVE');
 WHEN 'GROUP' THEN RETURN EXISTS(SELECT 1 FROM control.authority_group WHERE participant_id=p_participant AND authority_group_id=id::uuid AND state='ACTIVE');
 WHEN 'PARTICIPANT' THEN RETURN id=p_participant::text AND EXISTS(SELECT 1 FROM control.participant WHERE participant_id=p_participant AND state='ACTIVE' AND archived_at IS NULL);
 ELSE RETURN false;
 END CASE;
END $_$;


ALTER FUNCTION openpc.cigl_subject_current(p_participant uuid, p_subject jsonb) OWNER TO openpc_control_owner;

--
-- Name: clear_notification_completion_phases(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.clear_notification_completion_phases() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_notification_completion_admission_owner();
 PERFORM openpc.assert_request_context(true);
 DELETE FROM control.notification_completion_phase_admission a WHERE a.database_role=session_user
  AND a.transaction_id=pg_current_xact_id()::text AND a.backend_pid=pg_backend_pid()
  AND a.participant_id=openpc.current_participant_id() AND a.privacy_domain_id=openpc.current_privacy_domain_id();
END $$;


ALTER FUNCTION openpc.clear_notification_completion_phases() OWNER TO openpc_control_owner;

--
-- Name: close_fleet_delivery_lease(uuid, uuid, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.close_fleet_delivery_lease(wanted_event uuid, wanted_lease uuid, result text, problem text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d control.fleet_fact_delivery; a control.fleet_fact_delivery_attempt; now_ms numeric; failures integer; next_state text;
BEGIN
 SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=wanted_event FOR UPDATE;
 SELECT * INTO STRICT a FROM control.fleet_fact_delivery_attempt WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 IF a.outcome<>'ACTIVE' THEN
  IF a.outcome IS DISTINCT FROM result OR a.problem IS DISTINCT FROM problem THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN d.state;
 END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF d.state<>'LEASED' OR d.lease_id IS DISTINCT FROM wanted_lease
  OR result NOT IN ('FAILED','LEASE_EXPIRED','CAPACITY_RELEASE','UNAVAILABLE_RELEASE','COMMITTED')
  OR (result='LEASE_EXPIRED' AND d.lease_until_ms>now_ms)
  OR (result<>'LEASE_EXPIRED' AND d.lease_until_ms<=now_ms)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 failures:=d.failed_attempts+CASE WHEN result IN ('FAILED','LEASE_EXPIRED') THEN 1 ELSE 0 END;
 next_state:=CASE WHEN result='COMMITTED' THEN 'COMMITTED' WHEN failures>=d.maximum_attempts THEN 'EXHAUSTED' ELSE 'WAITING' END;
 UPDATE control.fleet_fact_delivery_attempt SET outcome=result,ended_at_ms=now_ms,problem=close_fleet_delivery_lease.problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 UPDATE control.fleet_fact_delivery SET failed_attempts=failures,state=next_state,lease_id=NULL,lease_until_ms=NULL,
  next_attempt_ms=now_ms+openpc.fleet_delivery_retry_delay(failures,d.initial_backoff_ms,d.maximum_backoff_ms),last_problem=problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 RETURN next_state;
END $$;


ALTER FUNCTION openpc.close_fleet_delivery_lease(wanted_event uuid, wanted_lease uuid, result text, problem text) OWNER TO openpc_control_owner;

--
-- Name: commit_fleet_fact_admission(bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_fleet_fact_admission(material bytea, nonce bytea, mac bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;

BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32

 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V1','UTF8')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;

 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 RAISE EXCEPTION 'PC-AUTH-0005'; -- V1 remains exact historical replay only.
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,NULL);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $$;


ALTER FUNCTION openpc.commit_fleet_fact_admission(material bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

--
-- Name: commit_fleet_fact_admission_v2(bytea, bytea, bytea, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_fleet_fact_admission_v2(material bytea, nonce bytea, mac bytea, wanted_profile text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;
 installed control.fact_consumer_profile; pending control.fleet_fact_delivery; expected_pending jsonb; lease uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32
  OR coalesce(wanted_profile,'')!~'^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V2','UTF8')||decode(substring(wanted_profile from 8),'hex')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('fact-consumer-profile:'||p::text||':'||d::text||':LS-FLEET-CONTROL',0));
 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 installed:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF installed.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 lease:=encode(substring(nonce from 1 for 16),'hex')::uuid;
 SELECT * INTO STRICT pending FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=d AND event_id=event FOR UPDATE;
 expected_pending:=jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,'eventId',event::text,
  'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'consumerId','LS-FLEET-CONTROL',
  'envelope',e,'envelopeDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e),'UTF8')),'hex'),
  'dataDigest',e->>'datadigest');
 IF pending.state<>'LEASED' OR pending.lease_id IS DISTINCT FROM lease
  OR convert_from(pending.material,'UTF8')::jsonb IS DISTINCT FROM expected_pending
  OR NOT EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=p AND a.privacy_domain_id=d
   AND a.event_id=event AND a.lease_id=lease AND a.profile_digest=wanted_profile AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.close_fleet_delivery_lease(event,lease,'COMMITTED',NULL);
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,wanted_profile);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $_$;


ALTER FUNCTION openpc.commit_fleet_fact_admission_v2(material bytea, nonce bytea, mac bytea, wanted_profile text) OWNER TO openpc_control_owner;

--
-- Name: commit_fleet_fact_quarantine(bytea, bytea, bytea, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_fleet_fact_quarantine(material bytea, nonce bytea, mac bytea, wanted_profile text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE request jsonb; q control.fleet_fact_quarantine; d control.fleet_fact_delivery;
 profile control.fact_consumer_profile; signer control.fact_consumer_failure_signer;
 c jsonb; expected jsonb; signed_payload bytea; signed_cose bytea; now_ms numeric;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_FAILURE_COMMIT_V1');
 IF request IS DISTINCT FROM jsonb_build_object('participantId',openpc.current_participant_id()::text,
  'privacyDomainId',openpc.current_privacy_domain_id()::text,'eventId',(request->>'eventId')::uuid::text,
  'payload',request->>'payload','cose',request->>'cose')
  OR coalesce(request->>'payload','')!~'^[0-9a-f]+$' OR coalesce(request->>'cose','')!~'^[0-9a-f]+$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 signed_payload:=decode(request->>'payload','hex'); signed_cose:=decode(request->>'cose','hex');
 SELECT * INTO d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=(request->>'eventId')::uuid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO q FROM control.fleet_fact_quarantine WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF q.state='COMMITTED' THEN
  IF d.state<>'QUARANTINED' OR q.payload IS DISTINCT FROM signed_payload OR q.cose IS DISTINCT FROM signed_cose
   OR q.claims->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN q.work_item_id;
 END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 c:=q.claims; signer:=openpc.require_fact_failure_signer(profile,c->>'signerKeyId');
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF q.state<>'PREPARED' OR d.state<>'EXHAUSTED' OR q.material_digest<>d.material_digest
  OR profile.profile_digest IS DISTINCT FROM wanted_profile OR c->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  OR c->>'workloadCredentialId' IS DISTINCT FROM profile.workload_credential_id::text
  OR c->>'workloadCredentialEpoch' IS DISTINCT FROM profile.workload_credential_epoch::text
  OR c->>'failedAttempts' IS DISTINCT FROM d.failed_attempts::text OR c->>'maximumAttempts' IS DISTINCT FROM d.maximum_attempts::text
  OR c->>'leaseGeneration' IS DISTINCT FROM d.lease_generation::text OR d.lease_id IS NOT NULL
  OR d.failed_attempts<>d.maximum_attempts OR d.last_problem IS DISTINCT FROM 'PC-DATA-6005'
  OR (c->>'recordedAtMs')::numeric>now_ms OR now_ms-(c->>'recordedAtMs')::numeric>30000
  OR (c->>'recordedAtMs')::numeric<signer.valid_from_ms
  OR EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=d.participant_id
   AND a.privacy_domain_id=d.privacy_domain_id AND a.event_id=d.event_id AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object(
  '0',openpc.business_bytes(decode('b9d6f05813ff518d1cbc05ff0cd9a55c9729035bce9f9f8446a914d2098bfbea','hex')),
  '1',c->'environmentId',
  '2',openpc.business_uuid(q.participant_id),
  '3',openpc.business_uuid(q.privacy_domain_id),
  '4',c->'consumerId',
  '5',c->'subscriptionId',
  '6',openpc.business_uuid((c->>'eventId')::uuid),
  '7',openpc.business_uuid((c->>'candidateId')::uuid),
  '8',openpc.business_uuid((c->>'generationId')::uuid),
  '9',c->'factType',
  '10',(c->>'sequence')::numeric,
  '11',openpc.business_bytes(decode(substring(c->>'envelopeDigest' from 8),'hex')),
  '12',openpc.business_bytes(decode(substring(c->>'dataDigest' from 8),'hex')),
  '13',openpc.business_bytes(decode(substring(c->>'materialDigest' from 8),'hex')),
  '14',openpc.business_bytes(decode(substring(c->>'initialProfileDigest' from 8),'hex')),
  '15',openpc.business_bytes(decode(substring(c->>'currentProfileDigest' from 8),'hex')),
  '16',(c->>'failedAttempts')::numeric,
  '17',(c->>'maximumAttempts')::numeric,
  '18',(c->>'leaseGeneration')::numeric,
  '19',openpc.business_uuid((c->>'workloadCredentialId')::uuid),
  '20',(c->>'workloadCredentialEpoch')::numeric,
  '21',openpc.business_uuid((c->>'workloadPrincipalId')::uuid),
  '22',openpc.business_uuid(q.work_item_id),
  '23','PC-DATA-6005',
  '24',(c->>'recordedAtMs')::numeric,
  '25',openpc.business_bytes(sha256(signer.public_key_spki)),
  '26',openpc.business_uuid(q.receipt_id));
 IF openpc.business_cbor(signed_payload) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(signed_payload,signed_cose,signer.signer_key_id,24007,344);
 INSERT INTO control.work_item(work_item_id,participant_id,privacy_domain_id,kind,state,resource_ref,payload_digest,reason,created_by_principal_id,row_version)
 VALUES(q.work_item_id,q.participant_id,q.privacy_domain_id,'FLEET_FAILURE','OPEN','urn:openpc:resource:'||d.candidate_id::text,
   d.material_digest,'Fact delivery quarantined (PC-DATA-6005).',(c->>'workloadPrincipalId')::uuid,1);
 UPDATE control.fleet_fact_quarantine SET state='COMMITTED',payload=signed_payload,
  cose=signed_cose,receipt_digest='sha256:'||encode(sha256(signed_cose),'hex'),
  signer_key_id=signer.signer_key_id,committed_at_ms=now_ms
 WHERE participant_id=q.participant_id AND privacy_domain_id=q.privacy_domain_id AND event_id=q.event_id;
 INSERT INTO control.fleet_fact_failure_outbox(participant_id,privacy_domain_id,receipt_id,receipt_digest)
 VALUES(q.participant_id,q.privacy_domain_id,q.receipt_id,'sha256:'||encode(sha256(signed_cose),'hex'));
 UPDATE control.fleet_fact_delivery SET state='QUARANTINED' WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 -- Time can expire while signing; the same current workload/profile and signer
 -- are checked after effects and before this atomic transaction can succeed.
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 PERFORM openpc.require_fact_failure_signer(profile,signer.signer_key_id);
 RETURN q.work_item_id;
END $_$;


ALTER FUNCTION openpc.commit_fleet_fact_quarantine(material bytea, nonce bytea, mac bytea, wanted_profile text) OWNER TO openpc_control_owner;

--
-- Name: commit_platform_scope_replacement(jsonb, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_platform_scope_replacement(document jsonb, candidate_id uuid, approval_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE r control.platform_scope_replacement; initial control.platform_envelope_scope; current_root control.platform_context; readiness jsonb; queued record;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=(document->>'replacementId')::uuid
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() FOR UPDATE;
 SELECT * INTO STRICT current_root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE' FOR UPDATE;
 FOR queued IN SELECT q.runtime_target_id FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
  AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id ORDER BY q.runtime_target_id LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||r.participant_id::text||':'||r.privacy_domain_id::text||':'||queued.runtime_target_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 readiness:=openpc.read_platform_scope_replacement_readiness(r.replacement_id);
 IF coalesce((document->>'platformContextId'<>readiness->>'platformContextId'
   OR document->>'expectedRootRevision'<>readiness->>'rootRevision'
   OR document->>'expectedReplacementRevision'<>readiness->>'replacementRevision'
   OR document->>'predecessorEpoch'<>readiness->>'predecessorEpoch'
   OR document->>'predecessorDigest'<>readiness->>'predecessorDigest'
   OR document->>'successorDigest'<>readiness->>'successorDigest' OR document->>'readinessDigest'<>readiness->>'readinessDigest'
   OR readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
   OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric),true)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
 SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=r.platform_context_id;
 UPDATE control.platform_scope_replacement SET state='COMMITTED',row_version=2,commit_operation_id=openpc.current_operation_id(),
  commit_candidate_id=candidate_id,commit_approval_id=approval_id,readiness_digest=decode(substring(document->>'readinessDigest' from 8),'hex'),
  committed_at=clock_timestamp() WHERE replacement_id=r.replacement_id;
 INSERT INTO control.platform_envelope_scope_successor(platform_context_id,platform_authority_epoch,owner_participant_id,installation_privacy_domain_id,
  replacement_id,preparation_operation_id,predecessor_epoch,predecessor_digest,environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(r.platform_context_id,r.predecessor_epoch+1,r.participant_id,r.privacy_domain_id,r.replacement_id,r.prepare_operation_id,
  r.predecessor_epoch,r.predecessor_digest,initial.environment_id,initial.installation_digest,r.successor_scope_cbor,r.successor_preimage,r.successor_digest);
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=r.platform_context_id AND authority_epoch=r.predecessor_epoch AND row_version=r.expected_root_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 RETURN jsonb_build_object('replacementId',r.replacement_id::text,'successorDigest','sha256:'||encode(r.successor_digest,'hex'),
  'state','COMMITTED','revision','2','operationId',openpc.current_operation_id()::text,'platformAuthorityEpoch',(r.predecessor_epoch+1)::text);
END $$;


ALTER FUNCTION openpc.commit_platform_scope_replacement(document jsonb, candidate_id uuid, approval_id uuid) OWNER TO openpc_control_owner;

--
-- Name: commit_root_expiry_recovery(uuid, uuid, bytea, bytea, bytea, bytea, bytea, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_root_expiry_recovery(p_recovery uuid, p_activation uuid, p_scope bytea, p_preimage bytea, p_evidence bytea, p_digest bytea, p_cose bytea, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE c control.root_expiry_recovery_case; e control.root_expiry_recovery_enrollment; root control.platform_context;
 original_scope bytea; original_digest bytea; original jsonb; successor jsonb; base jsonb; expected jsonb; actual_result jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 SELECT * INTO STRICT c FROM control.root_expiry_recovery_case WHERE recovery_id=p_recovery
  AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) FOR UPDATE;
 SELECT * INTO STRICT e FROM openpc.lock_root_expiry_recovery_enrollment(c.enrollment_id);
 SELECT * INTO STRICT root FROM control.platform_context WHERE platform_context_id=e.platform_context_id FOR UPDATE;
 IF c.state<>'REQUESTED' OR c.valid_until<=clock_timestamp() OR NOT openpc.root_expiry_recovery_source_current(e.enrollment_id)
  OR NOT openpc.root_expiry_recovery_proofs_current(c,p_activation) OR openpc.root_expiry_recovery_executor_has_grants(e.enrollment_id)
  OR root.authority_epoch::text<>c.intent->>'predecessorEpoch' OR root.row_version::text<>c.intent->>'predecessorRevision'
  OR p_digest IS DISTINCT FROM sha256(p_evidence) OR octet_length(p_cose)=0 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 SELECT s.scope_cbor,s.admission_digest INTO STRICT original_scope,original_digest FROM (
  SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.platform_envelope_scope
  UNION ALL SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.platform_envelope_scope_successor
  UNION ALL SELECT platform_context_id,platform_authority_epoch,scope_cbor,admission_digest FROM control.root_expiry_recovery_scope
 ) s WHERE s.platform_context_id=root.platform_context_id AND s.platform_authority_epoch=root.authority_epoch;
 original:=openpc.business_cbor(original_scope); successor:=openpc.business_cbor(p_scope);
 IF NOT openpc.identity_envelope_scope_valid(p_scope) OR (successor-ARRAY['3','4']) IS DISTINCT FROM (original-ARRAY['3','4'])
  OR (original->>'4')::numeric>floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'3')::numeric<(original->>'4')::numeric
  OR (successor->>'3')::numeric>floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'4')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
  OR (successor->>'4')::numeric-(successor->>'3')::numeric>((original->>'4')::numeric-(original->>'3')::numeric)*(CASE WHEN e.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN 10 ELSE 1 END)
  OR (successor->>'4')::numeric-(successor->>'3')::numeric>86400000000000*(CASE WHEN e.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN 10 ELSE 1 END)
  OR (successor->>'3')::numeric<>extract(epoch from (e.document->>'successorValidFrom')::timestamptz)*1000000000
  OR (successor->>'4')::numeric<>extract(epoch from (e.document->>'successorValidUntil')::timestamptz)*1000000000
  OR c.intent->'successorScope' IS DISTINCT FROM openpc.platform_scope_document(p_scope)
  OR 'sha256:'||encode(original_digest,'hex')<>c.intent->>'predecessorDigest'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-BOUNDS'; END IF;
 base:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
  openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
  openpc.business_uuid(root.platform_context_id),openpc.business_uuid(root.owner_participant_id),
  openpc.business_uuid(e.privacy_domain_id),root.authority_epoch+1,e.document->>'installationEnvironmentId',
  openpc.business_bytes(decode(substring(e.document->>'installationDigest' from 8),'hex')),openpc.business_bytes(p_scope));
 expected:=openpc.business_cbor(p_preimage);
 IF jsonb_typeof(expected) IS DISTINCT FROM 'array' OR jsonb_array_length(expected)<>9
  OR expected->>0 IS DISTINCT FROM 'pc.identity.platform-envelope-scope.local-expiry-recovery.v1' OR expected->>1 IS DISTINCT FROM '1'
  OR expected->2 IS DISTINCT FROM openpc.business_uuid(c.recovery_id)
  OR expected->3 IS DISTINCT FROM openpc.business_uuid(openpc.current_operation_id())
  OR expected->4 IS DISTINCT FROM openpc.business_bytes(c.enrollment_digest)
  OR expected->5 IS DISTINCT FROM openpc.business_bytes(c.intent_digest)
  OR expected->>6 IS DISTINCT FROM root.authority_epoch::text
  OR expected->7 IS DISTINCT FROM openpc.business_bytes(original_digest)
  OR openpc.business_cbor(decode(expected#>>'{8,bytes}','hex')) IS DISTINCT FROM base
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-BYTES'; END IF;
 actual_result:=jsonb_build_object('rootEpoch',(root.authority_epoch+1)::text,'rootRevision',(root.row_version+1)::text,
  'rootDigest','sha256:'||encode(sha256(p_preimage),'hex'),'operationId',openpc.current_operation_id()::text);
 IF p_result IS DISTINCT FROM actual_result THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-RESULT'; END IF;
 INSERT INTO control.root_expiry_recovery_scope(platform_context_id,platform_authority_epoch,recovery_id,activation_operation_id,
  enrollment_digest,intent_digest,predecessor_epoch,predecessor_digest,owner_participant_id,installation_privacy_domain_id,
  environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(root.platform_context_id,root.authority_epoch+1,c.recovery_id,openpc.current_operation_id(),c.enrollment_digest,c.intent_digest,
  root.authority_epoch,original_digest,root.owner_participant_id,e.privacy_domain_id,e.document->>'installationEnvironmentId',e.document->>'installationDigest',
  p_scope,p_preimage,sha256(p_preimage));
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=root.platform_context_id AND authority_epoch=root.authority_epoch AND row_version=root.row_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-FENCE'; END IF;
 UPDATE control.root_expiry_recovery_case SET state='COMPLETED',row_version=row_version+1,updated_at=clock_timestamp(),
  result=actual_result,operation_id=openpc.current_operation_id(),evidence_cbor=p_evidence,evidence_digest=p_digest,evidence_cose=p_cose
 WHERE recovery_id=c.recovery_id AND state='REQUESTED';
 INSERT INTO control.outbox_aggregate_head(participant_id,aggregate_type,aggregate_id,last_sequence) VALUES(c.participant_id,'local-root-expiry-recovery',c.recovery_id,1);
 INSERT INTO control.outbox_event(participant_id,privacy_domain_id,aggregate_type,aggregate_id,aggregate_sequence,event_id,event_type,
  payload_cbor,payload_digest,cose_sign1,occurred_at) VALUES(c.participant_id,c.privacy_domain_id,'local-root-expiry-recovery',c.recovery_id,1,
  openpc.current_operation_id(),'openpc.identity.local-root-expiry-recovery.completed.v1',p_evidence,p_digest,p_cose,clock_timestamp());
 RETURN actual_result;
END $$;


ALTER FUNCTION openpc.commit_root_expiry_recovery(p_recovery uuid, p_activation uuid, p_scope bytea, p_preimage bytea, p_evidence bytea, p_digest bytea, p_cose bytea, p_result jsonb) OWNER TO openpc_control_owner;

--
-- Name: commit_runtime_artifact_source_denial(uuid, bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_runtime_artifact_source_denial(wanted uuid, wire bytea, nonce bytea, mac bytea) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.runtime_artifact_source_disposition; retained bytea; claims jsonb;
BEGIN
 PERFORM openpc.lock_runtime_artifact_source_custody();
 SELECT * INTO STRICT a FROM control.runtime_artifact_source_disposition WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND disposition_id=wanted AND xmin<>pg_current_xact_id()::xid;
 PERFORM openpc.runtime_artifact_source_admission(a);
 PERFORM openpc.verify_runtime_artifact_source_commit(a.source_owner_id,wire,nonce,mac);
 SELECT signed_denial INTO retained FROM control.runtime_artifact_source_denial WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND disposition_id=a.disposition_id;
 IF FOUND THEN
  IF retained IS DISTINCT FROM wire THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-CUSTODY'; END IF;
  RETURN;
 END IF;
 claims:=convert_from(wire,'UTF8')::jsonb->'claims';
 INSERT INTO control.runtime_artifact_source_denial(participant_id,privacy_domain_id,source_owner_id,disposition_id,
  sequence,previous_denial_digest,signed_denial,denial_digest,verification_nonce,verification_mac)
 VALUES(a.participant_id,a.privacy_domain_id,a.source_owner_id,a.disposition_id,(claims->>'sequence')::numeric,
  decode(claims->>'previous_denial_digest','hex'),wire,sha256(wire),nonce,mac);
END $$;


ALTER FUNCTION openpc.commit_runtime_artifact_source_denial(wanted uuid, wire bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

--
-- Name: commit_runtime_target_disposition(text, bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.commit_runtime_target_disposition(kind text, wire bytea, nonce bytea, mac bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE envelope jsonb; receipt_claims jsonb; identity jsonb; pid uuid; privacy uuid; target uuid; principal uuid;
 secret bytea; expected bytea; different integer:=0; wire_digest text; prior bytea; wanted_revision bigint;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 authority record; previous_sequence numeric;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR kind IS NULL OR kind NOT IN ('DELIVERY','ACK') OR wire IS NULL OR octet_length(wire) NOT BETWEEN 1 AND 16384
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_'||kind||'_V1','UTF8')||sha256(wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 envelope:=convert_from(wire,'UTF8')::jsonb; receipt_claims:=envelope->'claims'; identity:=receipt_claims->'target';
 IF envelope->>'purpose' IS DISTINCT FROM (CASE kind WHEN 'DELIVERY' THEN 'openpc:target-disposition-delivery:v1'
   ELSE 'openpc:target-disposition-acknowledgement:v1' END)
  OR envelope IS DISTINCT FROM jsonb_build_object('purpose',envelope->'purpose','claims',receipt_claims,
   'claims_digest',envelope->'claims_digest','signature_p1363_hex',envelope->'signature_p1363_hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 pid:=(identity->>'participant_id')::uuid; privacy:=(identity->>'privacy_domain_id')::uuid; target:=(identity->>'target_id')::uuid;
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR target IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,'sha256:'||(identity->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',target::text,
  'credential_id',authority.credential_id::text,'principal_id',principal::text,'credential_epoch',authority.credential_epoch,
  'principal_epoch',authority.principal_epoch,'certificate_digest',identity->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 wire_digest:='sha256:'||encode(sha256(wire),'hex');
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF kind='DELIVERY' THEN
  wanted_revision:=(receipt_claims->>'revision')::bigint;
  SELECT d.signed_delivery INTO prior FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision OR receipt_claims IS DISTINCT FROM
   head.binding||jsonb_build_object('committed_admission_digest',substring(head.admission_digest from 8))
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ADMISSION'; END IF;
  INSERT INTO control.runtime_target_disposition_delivery(participant_id,privacy_domain_id,runtime_target_id,revision,
   predecessor_digest,claims,signed_delivery,delivery_digest)
  VALUES(pid,privacy,target,wanted_revision,CASE WHEN receipt_claims->>'previous_delivery_digest' IS NULL THEN NULL
   ELSE 'sha256:'||(receipt_claims->>'previous_delivery_digest') END,receipt_claims,wire,wire_digest);
 ELSE
  wanted_revision:=(receipt_claims->>'disposition_revision')::bigint;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
    AND d.delivery_digest='sha256:'||(receipt_claims->>'delivery_digest') AND d.revision=wanted_revision;
  IF receipt_claims IS DISTINCT FROM jsonb_build_object('version',1,'target',delivery.claims->'target',
   'delivery_digest',substring(delivery.delivery_digest from 8),'disposition_revision',delivery.revision,
   'journal_sequence',receipt_claims->'journal_sequence','installed_state',(CASE delivery.claims->>'action'
    WHEN 'Withdraw' THEN 'NewUseDenied' WHEN 'Restore' THEN 'SuspensionCleared' WHEN 'ConfirmActivation' THEN 'ActivationConfirmed' END))
   OR jsonb_typeof(receipt_claims->'journal_sequence') IS DISTINCT FROM 'number'
   OR (receipt_claims->>'journal_sequence')::numeric NOT BETWEEN 1 AND 9223372036854775807
   OR (receipt_claims->>'journal_sequence')::numeric<>trunc((receipt_claims->>'journal_sequence')::numeric)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-BINDING'; END IF;
  SELECT a.signed_acknowledgement INTO prior FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
  SELECT max((a.claims->>'journal_sequence')::numeric) INTO previous_sequence
   FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target;
  IF (receipt_claims->>'journal_sequence')::numeric<=coalesce(previous_sequence,0)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-JOURNAL-ROLLBACK'; END IF;
  INSERT INTO control.runtime_target_disposition_acknowledgement(participant_id,privacy_domain_id,runtime_target_id,
   delivery_digest,claims,signed_acknowledgement,acknowledgement_digest)
  VALUES(pid,privacy,target,delivery.delivery_digest,receipt_claims,wire,wire_digest);
 END IF;
 RETURN true;
END $$;


ALTER FUNCTION openpc.commit_runtime_target_disposition(kind text, wire bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

--
-- Name: complete_archive_nonce(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.complete_archive_nonce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_receipt r JOIN control.evidence_archive_outbox o
  USING(participant_id,privacy_domain_id,receipt_id) WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.receipt_id=NEW.receipt_id
   AND r.commit_nonce=NEW.nonce AND r.receipt_digest=NEW.receipt_digest)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.complete_archive_nonce() OWNER TO openpc_control_owner;

--
-- Name: complete_archive_receipt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.complete_archive_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt control.evidence_archive_receipt;
BEGIN
 SELECT * INTO STRICT receipt FROM control.evidence_archive_receipt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 PERFORM openpc.require_archive_profile(receipt.profile_digest,openpc.business_cbor(receipt.payload)->>'19');
 PERFORM openpc.require_archive_commit_nonce(receipt);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_outbox o WHERE o.participant_id=receipt.participant_id
  AND o.privacy_domain_id=receipt.privacy_domain_id AND o.receipt_id=receipt.receipt_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.complete_archive_receipt() OWNER TO openpc_control_owner;

