--
-- Name: complete_notification_completion_source(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.complete_notification_completion_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c integer;first_attempt jsonb;
BEGIN
 SELECT count(*) INTO c FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT attempt INTO STRICT first_attempt FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=1;
 IF c<1 OR first_attempt->>'workerInstallationDigest' IS DISTINCT FROM NEW.initial_worker_installation_digest THEN RAISE EXCEPTION 'COMPLETION-SOURCE-FIRST-ATTEMPT'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.complete_notification_completion_source() OWNER TO openpc_control_owner;

--
-- Name: configuration_policy_provenance(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.configuration_policy_provenance(pid uuid, privacy uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected text; cardinality bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'DATA-6001-CONTEXT-INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0));
 SELECT count(*),min('sha256:'||encode(generation_digest,'hex')) INTO cardinality,selected
 FROM control.policy_generation WHERE participant_id=pid AND privacy_domain_id=privacy AND active AND state='ACTIVE';
 IF cardinality=1 THEN RETURN selected; END IF;
 IF cardinality<>0 THEN RAISE EXCEPTION 'DATA-6007-CONFIGURATION-POLICY-UNAVAILABLE'; END IF;
 -- A published generation can require fresh provider preparation before its
 -- first activation. Bind that preparation to the sole approved generation,
 -- never to an arbitrary or failed generation.
 SELECT count(*),min('sha256:'||encode(g.generation_digest,'hex')) INTO cardinality,selected
 FROM control.policy_generation g
 JOIN control.policy_release_bundle r ON r.participant_id=g.participant_id
  AND r.privacy_domain_id=g.privacy_domain_id
  AND r.policy_version_id=g.policy_version_id
  AND r.approval_request_id=g.approval_request_id
  AND r.manifest_digest=g.generation_digest
  AND r.state IN ('PUBLISHED','STAGED')
 WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
  AND g.state='PREPARED' AND NOT g.active;
 IF cardinality=1 THEN RETURN selected; END IF;
 IF cardinality<>0 OR EXISTS(SELECT 1 FROM control.policy_generation WHERE participant_id=pid AND privacy_domain_id=privacy)
 THEN RAISE EXCEPTION 'DATA-6007-CONFIGURATION-POLICY-UNAVAILABLE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.configuration_policy_provenance(pid uuid, privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: mutation_evidence; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.mutation_evidence (
    mutation_evidence_id uuid DEFAULT uuidv7() NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    checker_principal_id uuid,
    action_intent_id character varying(160) NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    candidate_digest bytea NOT NULL,
    approval_request_id uuid,
    mfa_challenge_id uuid,
    bound_participant_epoch bigint NOT NULL,
    bound_principal_epoch bigint CONSTRAINT mutation_evidence_bound_authority_epoch_not_null NOT NULL,
    evidence_cbor bytea NOT NULL,
    evidence_digest bytea NOT NULL,
    cose_sign1 bytea NOT NULL,
    occurred_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    catalog_operation_id character varying(160) DEFAULT 'LEGACY'::character varying NOT NULL,
    aggregate_version bigint,
    bound_authority_envelope_id uuid,
    bound_envelope_epoch bigint,
    bound_assignment_id uuid,
    webauthn_assertion_binding_digest bytea,
    signer_credential_id uuid,
    evidence_role text DEFAULT 'LEGACY_UNQUALIFIED_BUSINESS_EVIDENCE'::text NOT NULL,
    evidence_format text DEFAULT 'LEGACY'::text NOT NULL,
    CONSTRAINT mutation_evidence_aggregate_version_ck CHECK (((aggregate_version IS NULL) OR (aggregate_version >= 0))),
    CONSTRAINT mutation_evidence_catalog_operation_ck CHECK ((((catalog_operation_id)::text = 'LEGACY'::text) OR ((catalog_operation_id)::text ~ '^(ID|CFG)-OP-[A-Z0-9-]+$'::text) OR ((catalog_operation_id)::text = ANY ((ARRAY['MOD-OP-REGISTER'::character varying, 'MOD-OP-INSTALL'::character varying, 'MOD-OP-ENABLE'::character varying, 'MOD-OP-DISABLE'::character varying])::text[])) OR ((catalog_operation_id)::text = 'POL-OP-ACTIVATE'::text) OR ((catalog_operation_id)::text = ANY ((ARRAY['OPS-OP-ADVANCE-SIGNING-KEY-ROTATION'::character varying, 'OPS-OP-RECOVER-SIGNING-KEY-ROTATION'::character varying])::text[])))),
    CONSTRAINT mutation_evidence_role_format_ck CHECK ((((evidence_role = 'LEGACY_UNQUALIFIED_BUSINESS_EVIDENCE'::text) AND (evidence_format = 'LEGACY'::text)) OR ((evidence_role = ANY (ARRAY['AUTHORIZATION_INPUT'::text, 'IDENTITY_PROOF_INPUT'::text])) AND (evidence_format = 'IDENTITY_RUNTIME_ASSERTION_3002_2_13'::text)))),
    CONSTRAINT mutation_evidence_webauthn_binding_ck CHECK (((webauthn_assertion_binding_digest IS NULL) OR (octet_length(webauthn_assertion_binding_digest) = 32)))
);

ALTER TABLE ONLY control.mutation_evidence FORCE ROW LEVEL SECURITY;


ALTER TABLE control.mutation_evidence OWNER TO openpc_control_owner;

--
-- Name: configuration_step_up_receipt_input(control.audit_occurrence, control.mutation_evidence); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.configuration_step_up_receipt_input(receipt control.audit_occurrence, authorization_row control.mutation_evidence) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE verification control.mutation_evidence%ROWTYPE; snapshot jsonb;
BEGIN
 IF receipt.catalog_operation_id NOT IN ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT') OR authorization_row.approval_request_id IS NOT NULL
  OR authorization_row.checker_principal_id IS NOT NULL OR authorization_row.mfa_challenge_id IS NULL
  OR authorization_row.webauthn_assertion_binding_digest IS NULL
 THEN RAISE EXCEPTION 'DATA-6021-STEP-UP-RECEIPT-ADMISSION'; END IF;
 snapshot:=convert_from(receipt.authority_snapshot,'UTF8')::jsonb;
 SELECT v.* INTO STRICT verification FROM control.mutation_evidence v
  JOIN control.mfa_challenge c ON c.participant_id=v.participant_id AND c.mfa_challenge_id=v.mfa_challenge_id
   AND c.principal_id=v.principal_id AND c.session_id=v.aggregate_id
  JOIN control.idempotency_record committed ON committed.participant_id=v.participant_id
   AND committed.privacy_domain_id=v.privacy_domain_id AND committed.principal_id=v.principal_id
   AND committed.operation_id=v.operation_id AND committed.catalog_operation_id=v.catalog_operation_id
   AND committed.input_digest=v.candidate_digest AND committed.terminal_state='COMMITTED'
   AND committed.webauthn_assertion_binding_digest=v.webauthn_assertion_binding_digest
  WHERE v.participant_id=receipt.participant_id AND v.privacy_domain_id=receipt.privacy_domain_id
   AND v.principal_id=authorization_row.principal_id AND v.mfa_challenge_id=authorization_row.mfa_challenge_id
   AND v.action_intent_id='ACT-IDENTITY_UPDATE_STEP_UP-V1' AND v.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
   AND v.aggregate_type='webauthn-verification' AND v.evidence_digest=sha256(v.evidence_cbor)
   AND v.webauthn_assertion_binding_digest=authorization_row.webauthn_assertion_binding_digest
   AND c.action_intent_id=receipt.action_intent_id
   AND c.resource_digest=receipt.candidate_digest AND c.used_operation_id=receipt.operation_id
   AND c.used_at IS NOT NULL AND c.consumed_at IS NOT NULL
   AND extract(epoch from c.consumed_at)*1000000000<=receipt.recorded_at_ns
   AND extract(epoch from c.consumed_at)*1000000000>receipt.recorded_at_ns-300000000000
   AND (SELECT count(*) FROM jsonb_array_elements(snapshot->'authorities') a
    WHERE a->>'principalId'=v.principal_id::text AND a->>'sessionId'=c.session_id::text
     AND a->>'actionIntentId'=receipt.action_intent_id AND a->>'resourceId'=receipt.aggregate_id::text)=1
   AND EXISTS(SELECT 1 FROM control.outbox_event e WHERE e.participant_id=v.participant_id
    AND e.privacy_domain_id=v.privacy_domain_id AND e.aggregate_type=v.aggregate_type AND e.aggregate_id=v.aggregate_id
    AND e.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
    AND e.payload_cbor=v.evidence_cbor AND e.payload_digest=v.evidence_digest AND e.cose_sign1=v.cose_sign1
    AND e.webauthn_assertion_binding_digest=v.webauthn_assertion_binding_digest);
 RETURN jsonb_build_object('0',4,'1',verification.mutation_evidence_id::text,'2',openpc.business_bytes(verification.evidence_digest));
END $$;


ALTER FUNCTION openpc.configuration_step_up_receipt_input(receipt control.audit_occurrence, authorization_row control.mutation_evidence) OWNER TO openpc_control_owner;

--
-- Name: evidence_archive_profile; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.evidence_archive_profile (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    environment_id text NOT NULL,
    sink_id text NOT NULL,
    profile_id text NOT NULL,
    revision numeric(20,0) NOT NULL,
    issuer_key_id text NOT NULL,
    profile_digest text NOT NULL,
    transport_digest text NOT NULL,
    transport jsonb NOT NULL,
    claims jsonb NOT NULL,
    payload bytea NOT NULL,
    cose bytea NOT NULL,
    admitted_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT evidence_archive_profile_digest_ck CHECK (((profile_digest = ('sha256:'::text || encode(sha256(cose), 'hex'::text))) AND (transport_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND ((octet_length(payload) >= 1) AND (octet_length(payload) <= 65536)) AND ((octet_length(cose) >= 65) AND (octet_length(cose) <= 66560)) AND ((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric))))
);

ALTER TABLE ONLY control.evidence_archive_profile FORCE ROW LEVEL SECURITY;


ALTER TABLE control.evidence_archive_profile OWNER TO openpc_control_owner;

--
-- Name: evidence_archive_receipt; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.evidence_archive_receipt (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    profile_digest text NOT NULL,
    previous_receipt_digest text,
    receipt_digest text NOT NULL,
    payload bytea NOT NULL,
    cose bytea NOT NULL,
    commit_nonce bytea NOT NULL,
    commit_mac bytea NOT NULL,
    recorded_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT evidence_archive_receipt_capability_ck CHECK (((octet_length(commit_nonce) = 32) AND (octet_length(commit_mac) = 32))),
    CONSTRAINT evidence_archive_receipt_digest_ck CHECK (((receipt_digest = ('sha256:'::text || encode(sha256(cose), 'hex'::text))) AND ((octet_length(payload) >= 1) AND (octet_length(payload) <= 65536)) AND ((octet_length(cose) >= 65) AND (octet_length(cose) <= 66560)) AND ((previous_receipt_digest IS NULL) OR (previous_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))))
);

ALTER TABLE ONLY control.evidence_archive_receipt FORCE ROW LEVEL SECURITY;


ALTER TABLE control.evidence_archive_receipt OWNER TO openpc_control_owner;

--
-- Name: evidence_remote_archive_attempt; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.evidence_remote_archive_attempt (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    action text NOT NULL,
    binding jsonb NOT NULL,
    binding_digest text NOT NULL,
    protection_digest text NOT NULL,
    state text NOT NULL,
    observation jsonb,
    observation_digest text,
    started_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT evidence_remote_archive_attempt_ck CHECK (((action = ANY (ARRAY['PUT'::text, 'PROTECTION'::text])) AND (state = ANY (ARRAY['STARTED'::text, 'AMBIGUOUS'::text, 'OBSERVED'::text])) AND (binding_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (protection_digest ~ '^sha256:[0-9a-f]{64}$'::text) AND (jsonb_typeof(binding) = 'object'::text) AND ((octet_length((binding)::text) >= 1) AND (octet_length((binding)::text) <= 1048576)))),
    CONSTRAINT evidence_remote_archive_attempt_id_ck CHECK (((attempt_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT evidence_remote_archive_observation_ck CHECK ((((state = 'OBSERVED'::text) AND (observation IS NOT NULL) AND (jsonb_typeof(observation) = 'object'::text) AND ((octet_length((observation)::text) >= 1) AND (octet_length((observation)::text) <= 1048576)) AND (observation_digest IS NOT NULL) AND (observation_digest ~ '^sha256:[0-9a-f]{64}$'::text)) OR ((state <> 'OBSERVED'::text) AND (observation IS NULL) AND (observation_digest IS NULL))))
);

ALTER TABLE ONLY control.evidence_remote_archive_attempt FORCE ROW LEVEL SECURITY;


ALTER TABLE control.evidence_remote_archive_attempt OWNER TO openpc_control_owner;

--
-- Name: consume_archive_commit(control.evidence_archive_profile, control.evidence_remote_archive_attempt, control.evidence_archive_receipt); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.consume_archive_commit(p control.evidence_archive_profile, a control.evidence_remote_archive_attempt, v control.evidence_archive_receipt) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 IF session_user IS DISTINCT FROM p.claims->>'databaseRole'
  OR v.participant_id<>p.participant_id OR v.privacy_domain_id<>p.privacy_domain_id
  OR a.participant_id<>v.participant_id OR a.privacy_domain_id<>v.privacy_domain_id
  OR a.attempt_id<>v.attempt_id OR v.profile_digest<>p.profile_digest
  OR v.receipt_digest<>'sha256:'||encode(sha256(v.cose),'hex')
  OR octet_length(v.commit_nonce)<>32 OR octet_length(v.commit_mac)<>32
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.evidence_archive_commit_key
  WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id
   AND environment_id=p.environment_id AND sink_id=p.sink_id;
 expected:=public.hmac(convert_to('OPENPC_REMOTE_ARCHIVE_CUSTODY_COMMIT_V1','UTF8')
  ||uuid_send(v.participant_id)||uuid_send(v.privacy_domain_id)||sha256(v.cose)||sha256(v.payload)
  ||decode(substring(p.profile_digest from 8),'hex')||decode(substring(a.binding_digest from 8),'hex')||v.commit_nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(v.commit_mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 INSERT INTO control.evidence_archive_commit_nonce(participant_id,privacy_domain_id,nonce,receipt_id,receipt_digest)
  VALUES(v.participant_id,v.privacy_domain_id,v.commit_nonce,v.receipt_id,v.receipt_digest);
END $$;


ALTER FUNCTION openpc.consume_archive_commit(p control.evidence_archive_profile, a control.evidence_remote_archive_attempt, v control.evidence_archive_receipt) OWNER TO openpc_control_owner;

--
-- Name: current_action_intent_id(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.current_action_intent_id() RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE value text;
BEGIN
  value := current_setting('openpc.action_intent_id', true);
  IF value IS NULL OR value !~ '^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6001-CONTEXT-INVALID', DETAIL = 'openpc.action_intent_id';
  END IF;
  RETURN value;
END $_$;


ALTER FUNCTION openpc.current_action_intent_id() OWNER TO openpc_control_owner;

--
-- Name: current_notification_delivery_limit(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.current_notification_delivery_limit(p_environment text) RETURNS TABLE(generation_id uuid, effective_digest text, configured_limit integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE installed control.operations_installation%ROWTYPE; accepted control.operations_generation_commit%ROWTYPE;
 candidate control.operations_generation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('operations-generation:'||p_environment,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO installed FROM control.operations_installation i WHERE i.environment_id=p_environment FOR SHARE;
 IF installed.environment_id IS NULL OR installed.state<>'ACTIVE' THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 SELECT * INTO accepted FROM control.operations_generation_commit c WHERE c.environment_id=p_environment ORDER BY c.sequence DESC LIMIT 1;
 IF accepted.generation_id IS NULL THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 SELECT * INTO STRICT candidate FROM control.operations_generation g WHERE g.environment_id=p_environment AND g.generation_id=accepted.generation_id FOR SHARE;
 IF candidate.state<>'STAGED' OR openpc.operations_generation_missing(p_environment,accepted.generation_id)<>'[]'::jsonb
 THEN RAISE EXCEPTION 'OPS_CONFIG_UNREADY'; END IF;
 generation_id:=accepted.generation_id; effective_digest:=accepted.effective_digest;
 configured_limit:=(candidate.candidate->'configuration'->'settings'->>'operations.notification_delivery_limit')::integer;
 IF configured_limit IS NULL OR configured_limit<0 OR configured_limit>100 THEN RAISE EXCEPTION 'OPS_CONFIG_INVALID'; END IF;
 RETURN NEXT;
END $$;


ALTER FUNCTION openpc.current_notification_delivery_limit(p_environment text) OWNER TO openpc_control_owner;

