--
-- Name: deployment_module_generation(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.deployment_module_generation(participant uuid, privacy uuid) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH RECURSIVE nodes AS (
  SELECT m.*,v.module_id,v.semantic_version,v.manifest_digest,c.configuration_digest,c.generation,c.active
  FROM control.module_installation m JOIN control.module_version v USING(module_version_id)
  JOIN control.module_configuration_generation c USING(module_installation_id)
  WHERE m.participant_id=participant AND m.privacy_domain_id=privacy
   AND c.participant_id=participant AND c.privacy_domain_id=privacy AND v.release_payload_cbor IS NOT NULL
 ), closure(id) AS (
  SELECT module_installation_id FROM nodes WHERE module_id IN ('pc.transaction.delivery','pc.deployment.governance')
  UNION
  SELECT provider.module_installation_id FROM closure
   JOIN nodes consumer ON consumer.module_installation_id=closure.id
   JOIN control.module_dependency d ON d.consumer_module_version_id=consumer.module_version_id
   JOIN nodes provider ON provider.module_id=d.provider_module_id AND provider.semantic_version=d.semantic_version
    AND provider.manifest_digest=d.provider_manifest_digest
 ), selected AS (SELECT nodes.* FROM nodes JOIN closure ON closure.id=nodes.module_installation_id)
 SELECT CASE WHEN
  (SELECT count(*) FROM nodes WHERE module_id IN ('pc.transaction.delivery','pc.deployment.governance'))=2
  AND (SELECT count(DISTINCT module_id) FROM nodes WHERE module_id IN ('pc.transaction.delivery','pc.deployment.governance'))=2
  AND NOT EXISTS(SELECT 1 FROM selected WHERE state<>'ENABLED' OR NOT active OR generation<>1
   OR active_manifest_digest IS DISTINCT FROM manifest_digest OR lifecycle_evaluation_digest IS NULL
   OR NOT EXISTS(SELECT 1 FROM control.audit_occurrence a JOIN control.evidence_record e USING(participant_id,privacy_domain_id,receipt_id)
    WHERE a.participant_id=participant AND a.privacy_domain_id=privacy AND a.aggregate_id=selected.module_installation_id
     AND a.operation_id=selected.lifecycle_operation_id AND a.catalog_operation_id='MOD-OP-ENABLE'
     AND a.after_revision=selected.aggregate_version AND a.after_existence=1 AND a.receipt_digest=sha256(a.receipt_cbor)
     AND e.receipt_digest=a.receipt_digest))
  AND NOT EXISTS(SELECT 1 FROM selected consumer JOIN control.module_dependency d ON d.consumer_module_version_id=consumer.module_version_id
   WHERE NOT EXISTS(SELECT 1 FROM selected provider JOIN control.module_capability capability ON capability.module_version_id=provider.module_version_id
    WHERE provider.module_id=d.provider_module_id AND provider.semantic_version=d.semantic_version
     AND provider.manifest_digest=d.provider_manifest_digest AND capability.capability_id=d.capability_id))
  THEN sha256(convert_to(openpc.signing_canonical_json((SELECT jsonb_agg(jsonb_build_array(module_id,semantic_version,
    encode(manifest_digest,'hex'),encode(configuration_digest,'hex'),generation,aggregate_version,
    encode(lifecycle_evaluation_digest,'hex'),lifecycle_operation_id) ORDER BY module_id) FROM selected)),'UTF8'))
  ELSE NULL END
$$;


ALTER FUNCTION openpc.deployment_module_generation(participant uuid, privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: deployment_projection_retirement_blockers(control.evidence_catalogue, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.deployment_projection_retirement_blockers(source control.evidence_catalogue, p jsonb) RETURNS text[]
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE reservation control.deployment_address_reservation; latest control.deployment_result;
 claims jsonb; occurrence jsonb; blockers text[]:=ARRAY[]::text[];
BEGIN
 IF current_setting('openpc.action_intent_id')='ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1' THEN
  SELECT * INTO reservation FROM control.deployment_address_reservation r
  WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
   AND r.command_id=split_part((source).record_id,':',2)::uuid FOR SHARE;
 ELSE
  SELECT * INTO reservation FROM control.deployment_address_reservation r
  WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
   AND r.command_id=split_part((source).record_id,':',2)::uuid;
 END IF;
 IF NOT FOUND OR reservation.state<>'HANDOFF' THEN RETURN ARRAY['UNRESOLVED_OPERATION']; END IF;
 SELECT * INTO latest FROM control.deployment_result r WHERE r.participant_id=reservation.participant_id
  AND r.privacy_domain_id=reservation.privacy_domain_id AND r.command_id=reservation.command_id
 ORDER BY r.sequence DESC LIMIT 1;
 IF NOT FOUND THEN RETURN ARRAY['UNRESOLVED_OPERATION']; END IF;
 claims:=convert_from(latest.signed_bytes,'UTF8')::jsonb->'claims'; occurrence:=claims->'outcome'->'occurrence';
 IF claims->'outcome'->'invalidation' IS DISTINCT FROM 'null'::jsonb
  OR claims->'status'->>'state'='REORG' OR p->'historical'->>'finality' IN ('REORG','INVALIDATED')
 THEN blockers:=array_append(blockers,'REORG_FENCED'); END IF;
 IF claims->'status'->>'state' IS DISTINCT FROM 'CONFIRMED'
  OR claims->'status'->>'truthState' IS DISTINCT FROM 'SUCCESS'
  OR occurrence->>'finality' IS DISTINCT FROM 'FINALIZED'
  OR occurrence->>'reorgStatus' IS DISTINCT FROM 'CANONICAL'
  OR occurrence->>'receiptStatus' IS DISTINCT FROM '1'
  OR occurrence->>'creationGraphComplete' IS DISTINCT FROM 'true'
  OR occurrence->>'runtimeCodePresent' IS DISTINCT FROM 'true'
  OR occurrence->>'internalNativeTransfers' IS DISTINCT FROM '0'
  OR p->'historical'->>'state' IS DISTINCT FROM 'CONFIRMED'
  OR p->'historical'->>'truthState' IS DISTINCT FROM 'SUCCESS'
  OR p->'historical'->>'finality' IS DISTINCT FROM 'FINALIZED'
 THEN blockers:=array_append(blockers,'UNRESOLVED_OPERATION'); END IF;
 IF latest.sequence::text IS DISTINCT FROM p->'historical'->>'sourceVersion'
  OR latest.result_digest IS DISTINCT FROM (source).receipt_digest
  OR latest.result_digest IS DISTINCT FROM 'sha256:'||encode(sha256(latest.signed_bytes),'hex')
  OR p IS DISTINCT FROM openpc.evidence_deployment_projection(source)
  OR EXISTS(SELECT 1 FROM control.deployment_address_reservation successor
   WHERE successor.participant_id=reservation.participant_id AND successor.privacy_domain_id=reservation.privacy_domain_id
    AND successor.predecessor_command_id=reservation.command_id)
 THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 RETURN blockers;
END $$;


ALTER FUNCTION openpc.deployment_projection_retirement_blockers(source control.evidence_catalogue, p jsonb) OWNER TO openpc_control_owner;

--
-- Name: deployment_rejection_source(uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.deployment_rejection_source(command uuid, participant uuid, privacy uuid) RETURNS TABLE(signed_bytes bytea, result_digest text, created_at text, preparation_bytes bytea, publication_bytes bytea, signed_transaction text, candidate_digest text, evidence_digest text, attempt_id text, actor_principal_id text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
-- Shared immutable rejection source: signed command completion, never absence alone.
select result.signed_bytes,result.result_digest,result.created_at::text,
      intent.preparation_bytes,intent.publication_bytes,candidate.candidate_document->>'signedTransaction' signed_transaction,
      encode(candidate.candidate_digest,'hex') candidate_digest,encode(evidence.evidence_digest,'hex') evidence_digest,
      candidate.resource_id::text attempt_id,intent.actor_principal_id::text
     from control.deployment_result result
     join control.mutation_candidate candidate on candidate.participant_id=result.participant_id
      and candidate.privacy_domain_id=result.privacy_domain_id and candidate.consumed_operation_id=result.command_id
      and candidate.catalog_operation_id='CFG-OP-SUBMIT-DEPLOYMENT' and candidate.state='CONSUMED'
      and candidate.action_intent_id='ACT-DEPLOYMENT_SUBMISSIONS_CREATE_RESOURCE-V1'
      and candidate.resource_type='deployment-submission' and candidate.operation_class='CREATE'
     join control.idempotency_record receipt on receipt.participant_id=candidate.participant_id
      and receipt.privacy_domain_id=candidate.privacy_domain_id and receipt.operation_id=candidate.consumed_operation_id
      and receipt.catalog_operation_id=candidate.catalog_operation_id and receipt.input_digest=candidate.candidate_digest
      and receipt.principal_id=candidate.maker_principal_id and receipt.terminal_state='COMMITTED'
     join control.mutation_evidence evidence on evidence.participant_id=candidate.participant_id
      and evidence.privacy_domain_id=candidate.privacy_domain_id and evidence.operation_id=candidate.consumed_operation_id
      and evidence.catalog_operation_id=candidate.catalog_operation_id and evidence.candidate_digest=candidate.candidate_digest
      and evidence.aggregate_id=candidate.resource_id and evidence.aggregate_type='deployment-submission'
     join control.deployment_intent intent on intent.participant_id=candidate.participant_id
      and intent.privacy_domain_id=candidate.privacy_domain_id and intent.actor_principal_id=candidate.maker_principal_id
      and candidate.candidate_document->>'deploymentIntentId'='urn:openpc:resource:'||intent.deployment_intent_id::text
     where result.command_id=$1 and result.participant_id=$2 and result.privacy_domain_id=$3 and result.sequence=1
      and not exists(select 1 from control.deployment_address_reservation reservation where reservation.command_id=result.command_id)

$_$;


ALTER FUNCTION openpc.deployment_rejection_source(command uuid, participant uuid, privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: directory_group_permits(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.directory_group_permits(owner_id uuid, group_ref uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT NOT EXISTS (SELECT FROM control.directory_group_mapping WHERE participant_id=owner_id AND authority_group_id=group_ref)
 OR EXISTS (SELECT FROM control.directory_group_mapping m JOIN control.directory_connector c ON c.participant_id=m.participant_id AND c.connector_id=m.connector_id
 WHERE m.participant_id=owner_id AND m.authority_group_id=group_ref AND c.state='ACTIVE' AND c.profile_digest=m.profile_digest
 AND m.observed_at<=clock_timestamp() AND least(m.fresh_until,m.observed_at+make_interval(secs=>c.external_group_freshness_seconds))>clock_timestamp())
$$;


ALTER FUNCTION openpc.directory_group_permits(owner_id uuid, group_ref uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_approval_resume_eligible(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_approval_resume_eligible(p_participant uuid, p_privacy uuid, p_principal uuid, p_envelope uuid, p_approval uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT openpc.discovery_approval_resume_subject_visible(p_participant,p_privacy,p_principal,p_envelope,p_approval)
 AND NOT EXISTS(SELECT 1 FROM control.approval_request a JOIN control.mutation_candidate child
  ON child.participant_id=a.participant_id AND child.privacy_domain_id=a.privacy_domain_id AND child.predecessor_candidate_id=a.subject_id
  WHERE a.participant_id=p_participant AND a.privacy_domain_id=p_privacy AND a.approval_request_id=p_approval)
$$;


ALTER FUNCTION openpc.discovery_approval_resume_eligible(p_participant uuid, p_privacy uuid, p_principal uuid, p_envelope uuid, p_approval uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_approval_resume_enrollments_compatible(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_approval_resume_enrollments_compatible(p_old uuid, p_new uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE old_e control.platform_recovery_enrollment; new_e control.platform_recovery_enrollment;
 old_source jsonb; new_source jsonb; old_refs jsonb; new_refs jsonb; suffix jsonb; reference jsonb;
 delta integer; i integer; receipt record; previous_document jsonb; runtime_scope jsonb;
BEGIN
 SELECT * INTO old_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_old;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO new_e FROM control.platform_recovery_enrollment WHERE enrollment_id=p_new;
 IF NOT FOUND THEN RETURN false; END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NOT openpc.matches_participant(new_e.participant_id) OR NOT openpc.matches_privacy(new_e.privacy_domain_id)
  OR row(new_e.participant_id,new_e.privacy_domain_id,new_e.platform_context_id,new_e.source_purpose)
    IS DISTINCT FROM row(old_e.participant_id,old_e.privacy_domain_id,old_e.platform_context_id,old_e.source_purpose)
  OR old_e.source_purpose IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY'
  OR old_e.document->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-enrollment'
  OR new_e.document->>'schema' IS DISTINCT FROM old_e.document->>'schema'
  OR old_e.document->>'schemaVersion' IS DISTINCT FROM '2' OR new_e.document->>'schemaVersion' IS DISTINCT FROM '2'
  OR old_e.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  OR new_e.document->>'assurance' IS DISTINCT FROM old_e.document->>'assurance'
  OR new_e.document->'certificateRecovery' IS DISTINCT FROM old_e.document->'certificateRecovery'
  OR new_e.document->'administratorPrincipalIds' IS DISTINCT FROM old_e.document->'administratorPrincipalIds'
  OR new_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(new_e.document),'UTF8'))
  OR old_e.document_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(old_e.document),'UTF8'))
  OR new_e.state IS DISTINCT FROM 'ACTIVE' OR new_e.row_version<>1
  OR new_e.valid_from>clock_timestamp() OR new_e.valid_until<=clock_timestamp()
  OR openpc.platform_recovery_source_root_current(new_e) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 old_source:=old_e.document->'source'; new_source:=new_e.document->'source';
 IF row(new_e.root_epoch,new_e.root_revision,new_e.root_digest)=row(old_e.root_epoch,old_e.root_revision,old_e.root_digest)
 THEN RETURN openpc.discovery_approval_resume_source_compatible(old_source,new_source); END IF;
 IF new_e.root_epoch<=old_e.root_epoch OR new_e.root_epoch-old_e.root_epoch>31
  OR new_e.root_revision-old_e.root_revision IS DISTINCT FROM new_e.root_epoch-old_e.root_epoch
  OR jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR old_source->>'kind' IS DISTINCT FROM 'ROOT_EXPIRY_RECOVERY' OR new_source->>'kind' IS DISTINCT FROM old_source->>'kind'
  OR (new_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
    IS DISTINCT FROM (old_source-ARRAY['recoveryId','enrollmentId','activationOperationId','receiptDigest','ancestorReceipts','originalAdministrators'])
  OR openpc.discovery_approval_resume_source_compatible(old_source,
    old_source||jsonb_build_object('originalAdministrators',new_source->'originalAdministrators')) IS DISTINCT FROM true
 THEN RETURN false; END IF;
 delta:=(new_e.root_epoch-old_e.root_epoch)::integer;
 old_refs:=jsonb_build_array(old_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(old_source->'ancestorReceipts','[]'::jsonb);
 new_refs:=jsonb_build_array(new_source-ARRAY['kind','originalAdministrators','ancestorReceipts'])||coalesce(new_source->'ancestorReceipts','[]'::jsonb);
 IF jsonb_typeof(old_refs) IS DISTINCT FROM 'array' OR jsonb_typeof(new_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(new_refs)>32 OR jsonb_array_length(new_refs)<>jsonb_array_length(old_refs)+delta
 THEN RETURN false; END IF;
 SELECT jsonb_agg(value ORDER BY ordinality) INTO suffix FROM jsonb_array_elements(new_refs) WITH ORDINALITY WHERE ordinality>delta;
 IF suffix IS DISTINCT FROM old_refs THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(new_refs)-1 LOOP
  reference:=new_refs->i;
  SELECT recovery.result,recovery.intent,original.document,scope.admission_digest INTO receipt
   FROM control.root_expiry_recovery_case recovery
   JOIN control.root_expiry_recovery_enrollment original ON original.enrollment_id=recovery.enrollment_id
    AND original.participant_id=recovery.participant_id AND original.privacy_domain_id=recovery.privacy_domain_id
    AND original.row_version=recovery.enrollment_revision AND original.document_digest=recovery.enrollment_digest
   JOIN control.root_expiry_recovery_scope scope ON scope.recovery_id=recovery.recovery_id
    AND scope.platform_context_id=new_e.platform_context_id AND scope.owner_participant_id=recovery.participant_id
    AND scope.installation_privacy_domain_id=recovery.privacy_domain_id AND scope.activation_operation_id=recovery.operation_id
    AND scope.platform_authority_epoch=new_e.root_epoch-i
   WHERE recovery.recovery_id::text=reference->>'recoveryId' AND recovery.enrollment_id::text=reference->>'enrollmentId'
    AND recovery.operation_id::text=reference->>'activationOperationId'
    AND 'sha256:'||encode(recovery.evidence_digest,'hex')=reference->>'receiptDigest'
    AND recovery.participant_id=new_e.participant_id AND recovery.privacy_domain_id=new_e.privacy_domain_id
    AND recovery.state='COMPLETED' AND recovery.evidence_digest=sha256(recovery.evidence_cbor)
    AND recovery.intent_digest=sha256(convert_to(openpc.signing_canonical_json(recovery.intent),'UTF8'))
    AND original.document_digest=sha256(convert_to(openpc.signing_canonical_json(original.document),'UTF8'));
  IF NOT FOUND THEN RETURN false; END IF;
  IF receipt.result->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i)::text
   OR receipt.result->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i)::text
   OR receipt.result->>'rootDigest' IS DISTINCT FROM 'sha256:'||encode(receipt.admission_digest,'hex')
   OR receipt.document->>'rootEpoch' IS DISTINCT FROM (new_e.root_epoch-i-1)::text
   OR receipt.document->>'rootRevision' IS DISTINCT FROM (new_e.root_revision-i-1)::text
   OR receipt.document->>'platformContextId' IS DISTINCT FROM new_e.platform_context_id::text
   OR receipt.document->'administratorPrincipalIds' IS DISTINCT FROM new_e.document->'administratorPrincipalIds'
  THEN RETURN false; END IF;
  IF i=0 THEN
   IF receipt.admission_digest IS DISTINCT FROM new_e.root_digest THEN RETURN false; END IF;
   runtime_scope:=receipt.intent#>'{successorScope,runtime}';
  ELSE
   IF previous_document->>'rootDigest' IS DISTINCT FROM receipt.result->>'rootDigest'
    OR previous_document->>'installationDigest' IS DISTINCT FROM receipt.document->>'installationDigest'
    OR previous_document->>'installationEnvironmentId' IS DISTINCT FROM receipt.document->>'installationEnvironmentId'
    OR receipt.intent#>'{successorScope,runtime}' IS DISTINCT FROM runtime_scope
   THEN RETURN false; END IF;
  END IF;
  IF i=delta AND receipt.admission_digest IS DISTINCT FROM old_e.root_digest THEN RETURN false; END IF;
  previous_document:=receipt.document;
 END LOOP;
 RETURN true;
END $$;


ALTER FUNCTION openpc.discovery_approval_resume_enrollments_compatible(p_old uuid, p_new uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_approval_resume_source_compatible(jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_approval_resume_source_compatible(old_source jsonb, new_source jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected jsonb:=old_source; actions jsonb; i integer; scope text; old_actions jsonb;
BEGIN
 IF jsonb_typeof(old_source) IS DISTINCT FROM 'object' OR jsonb_typeof(new_source) IS DISTINCT FROM 'object'
  OR jsonb_typeof(old_source->'originalAdministrators') IS DISTINCT FROM 'array'
  OR jsonb_typeof(new_source->'originalAdministrators') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(old_source->'originalAdministrators')<>2
  OR jsonb_array_length(new_source->'originalAdministrators')<>2 THEN RETURN false; END IF;
 actions:=jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1');
 old_actions:=old_source#>'{originalAdministrators,0,usable,administration,actionIntentIds}';
 IF old_actions IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1') AND old_actions IS DISTINCT FROM actions THEN RETURN false; END IF;
 FOR i IN 0..1 LOOP
  FOREACH scope IN ARRAY ARRAY['usable','grantable'] LOOP
   IF old_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM old_actions
    OR new_source#>ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'] IS DISTINCT FROM actions
   THEN RETURN false; END IF;
   expected:=jsonb_set(expected,ARRAY['originalAdministrators',i::text,scope,'administration','actionIntentIds'],actions,false);
  END LOOP;
 END LOOP;
 RETURN expected=new_source;
END $$;


ALTER FUNCTION openpc.discovery_approval_resume_source_compatible(old_source jsonb, new_source jsonb) OWNER TO openpc_control_owner;

--
-- Name: discovery_approval_resume_subject_visible(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_approval_resume_subject_visible(p_participant uuid, p_privacy uuid, p_principal uuid, p_envelope uuid, p_approval uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT coalesce(EXISTS(SELECT 1 FROM control.approval_request approval
  JOIN control.mutation_candidate c ON c.participant_id=approval.participant_id AND c.privacy_domain_id=approval.privacy_domain_id
   AND c.mutation_candidate_id=approval.subject_id AND c.candidate_digest=approval.subject_digest
   AND c.expected_revision=approval.subject_version AND c.action_intent_id=approval.action_intent_id
   AND c.maker_principal_id=approval.maker_principal_id
  JOIN control.authority_envelope old_e ON old_e.participant_id=c.participant_id AND old_e.authority_envelope_id=c.maker_authority_envelope_id
   AND old_e.principal_id=c.maker_principal_id AND old_e.representation='RECOVERY_V1'
  JOIN control.platform_recovery_case old_case ON old_case.participant_id=c.participant_id AND old_case.privacy_domain_id=c.privacy_domain_id
   AND old_case.recovery_id=old_e.recovery_case_id AND old_case.state='EXPIRED' AND old_case.valid_until<=clock_timestamp()
   AND old_case.completion_operation_id IS NULL AND old_case.completion_result IS NULL
  JOIN control.platform_recovery_enrollment old_source ON old_source.enrollment_id=old_case.enrollment_id
   AND old_source.participant_id=c.participant_id AND old_source.privacy_domain_id=c.privacy_domain_id
   AND old_source.row_version=old_case.enrollment_revision AND old_source.document_digest=old_case.enrollment_digest
  JOIN control.authority_envelope e ON e.participant_id=c.participant_id AND e.authority_envelope_id=p_envelope
   AND e.principal_id=c.maker_principal_id AND e.representation='RECOVERY_V1'
  JOIN control.platform_recovery_case fresh ON fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id
   AND fresh.recovery_id=e.recovery_case_id AND fresh.recovery_id<>old_case.recovery_id AND fresh.state='ACTIVE'
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp()
   AND fresh.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' AND fresh.intent->>'schemaVersion'='2'
   AND fresh.intent->'certificateRecovery'=old_case.intent->'certificateRecovery'
   AND ((fresh.intent#>'{administrators,0}')-'principalEpoch')=((old_case.intent#>'{administrators,0}')-'principalEpoch')
   AND ((fresh.intent#>'{administrators,1}')-'principalEpoch')=((old_case.intent#>'{administrators,1}')-'principalEpoch')
  JOIN control.platform_recovery_enrollment source ON source.enrollment_id=fresh.enrollment_id
   AND source.participant_id=c.participant_id AND source.privacy_domain_id=c.privacy_domain_id
   AND source.row_version=fresh.enrollment_revision AND source.document_digest=fresh.enrollment_digest
  WHERE c.participant_id=p_participant AND c.privacy_domain_id=p_privacy AND c.maker_principal_id=p_principal
   AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)
   AND current_setting('openpc.local_qa_runtime',true)='1'
   AND approval.approval_request_id=p_approval AND approval.subject_type='CONFIGURATION_CANDIDATE'
   AND approval.state IN ('OPEN','APPROVED','EXPIRED') AND approval.checker_principal_id<>c.maker_principal_id
   AND approval.checker_principal_id::text=fresh.intent#>>'{administrators,1,principalId}'
   AND c.state IN ('APPROVAL_REQUESTED','APPROVED') AND c.consumed_operation_id IS NULL
   AND (c.catalog_operation_id,c.action_intent_id,c.resource_type,c.operation_class)=
     ('ID-OP-WORKLOAD-ROTATE','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','participant','UPDATE')
   AND old_case.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND c.resource_id::text=fresh.intent#>>'{certificateRecovery,predecessorCredentialId}'
   AND c.expected_revision::text=fresh.intent#>>'{certificateRecovery,predecessorRevision}'
   AND c.candidate_document=jsonb_build_object('replacedCredentialId',c.resource_id::text,
     'credentialId',fresh.intent#>>'{certificateRecovery,successorCredentialId}',
     'publicKeySpkiDer',fresh.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
   AND c.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(c.candidate_document),'UTF8'))
   AND source.source_purpose='ROOT_EXPIRY_RECOVERY' AND source.document->>'schemaVersion'='2'
   AND old_source.source_purpose=source.source_purpose AND source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
   AND old_source.document->>'assurance'=source.document->>'assurance'
   AND source.document->'certificateRecovery'=old_source.document->'certificateRecovery'
   AND source.document->'administratorPrincipalIds'=old_source.document->'administratorPrincipalIds'
   AND openpc.discovery_approval_resume_enrollments_compatible(old_source.enrollment_id,source.enrollment_id)
   AND old_source.document_digest=sha256(convert_to(openpc.signing_canonical_json(old_source.document),'UTF8'))
   AND source.document_digest=sha256(convert_to(openpc.signing_canonical_json(source.document),'UTF8'))
   AND openpc.platform_recovery_envelope_current(e.authority_envelope_id)),false)
$$;


ALTER FUNCTION openpc.discovery_approval_resume_subject_visible(p_participant uuid, p_privacy uuid, p_principal uuid, p_envelope uuid, p_approval uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_certificate_recovery_administrators_current(uuid, jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_certificate_recovery_administrators_current(p_enrollment uuid, p_administrators jsonb, p_bindings jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT coalesce(jsonb_array_length(p_administrators)=2
  and (select count(distinct a->>'principalId') from jsonb_array_elements(p_administrators) a)=2
  and NOT EXISTS(select 1 from jsonb_array_elements(p_administrators) administrator
   where NOT EXISTS(select 1 from control.platform_recovery_enrollment e
    left join control.platform_scope_replacement original on original.replacement_id=e.expired_replacement_id
     and original.participant_id=e.participant_id and original.privacy_domain_id=e.privacy_domain_id and original.state='COMMITTED'
    join lateral jsonb_array_elements(case when e.source_purpose='ROOT_EXPIRY_RECOVERY'
      then e.document#>'{source,originalAdministrators}' else original.candidate->'administrators' end) declared
     on declared->>'principalId'=administrator->>'principalId'
    join control.principal principal on principal.participant_id=e.participant_id and principal.principal_id::text=declared->>'principalId'
     and principal.state='ACTIVE' and principal.kind in ('USER','PLATFORM_OPERATOR')
    join control.authority_envelope expired on expired.participant_id=e.participant_id
     and expired.authority_envelope_id::text=declared->>'envelopeId' and expired.state='ACTIVE'
     and expired.platform_context_id=e.platform_context_id
     and expired.platform_authority_epoch=case when e.source_purpose='ROOT_EXPIRY_RECOVERY'
       then (select (ancestor.document->>'rootEpoch')::numeric from control.root_expiry_recovery_enrollment ancestor
         where ancestor.participant_id=e.participant_id and ancestor.privacy_domain_id=e.privacy_domain_id
          and ancestor.enrollment_id::text=coalesce(e.document#>>'{source,ancestorReceipts,-1,enrollmentId}',e.document#>>'{source,enrollmentId}'))
       else e.root_epoch end
     and (e.source_purpose='ROOT_EXPIRY_RECOVERY' or expired.valid_until<=clock_timestamp())
    join control.assignment assignment on assignment.participant_id=e.participant_id
     and assignment.assignment_id::text=declared->>'assignmentId' and assignment.authority_envelope_id=expired.authority_envelope_id
     and assignment.principal_id=principal.principal_id and assignment.state='ACTIVE'
     and (e.source_purpose='ROOT_EXPIRY_RECOVERY' or upper(assignment.valid_during)<=clock_timestamp())
    join control.authority_role role on role.participant_id=e.participant_id and role.authority_role_id::text=declared->>'roleId'
     and role.state='ACTIVE' and role.row_version::text=declared->>'expectedRoleRevision'
    where e.enrollment_id=p_enrollment and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id)
     and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
     and openpc.platform_recovery_source_root_current(e) and openpc.platform_recovery_original_administrators_current(e)
     and administrator->>'principalId' IN (e.document#>>'{administratorPrincipalIds,0}',e.document#>>'{administratorPrincipalIds,1}')
     and administrator->>'roleId'=declared->>'roleId' and administrator->>'roleRevision'=role.row_version::text
     and administrator->>'roleDigest'=declared->>'roleDigest'
     and administrator->>'roleDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
       'domain','pc.identity.envelope-role-binding.v1','participantId',e.participant_id::text,'role',jsonb_build_object(
        'roleId',role.role_id,'version',role.row_version::text,'actions',role.action_intent_ids,'origin',role.origin,
        'createdByPrincipalId',role.created_by_principal_id::text,'creatorParticipantId',role.creator_participant_id::text,
        'bootstrapMandateId',role.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',role.bootstrap_platform_participant_id::text))),'UTF8')),'hex')
     and role.action_intent_ids @> ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
      'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
      'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1']::text[]
     and (case when e.source_purpose='ROOT_EXPIRY_RECOVERY' then declared#>'{usable,administration,actionIntentIds}'
       else original.candidate#>'{successorScope,administration,actionIntentIds}' end) @> to_jsonb(ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
      'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
      'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1']::text[])
     and (e.source_purpose<>'ROOT_EXPIRY_RECOVERY' or (declared#>'{grantable,administration,actionIntentIds}') @>
       to_jsonb(ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
        'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
        'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1']::text[]))
     and (e.source_purpose='ROOT_EXPIRY_RECOVERY' or (
       (declared#>>'{usable,validUntilNs}')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
       and (declared#>>'{grantable,validUntilNs}')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)))
     and administrator->'riskClasses'=(select jsonb_agg(risk.value order by risk.ordinality)
      from jsonb_array_elements(declared#>'{usable,administration,riskClasses}') with ordinality risk(value,ordinality)
      where e.source_purpose='ROOT_EXPIRY_RECOVERY' or
        (original.candidate#>'{successorScope,administration,riskClasses}') @> jsonb_build_array(risk.value))
     and jsonb_array_length(administrator->'riskClasses')>0
     and ((p_bindings is null and principal.authority_epoch::text=administrator->>'principalEpoch')
      or (jsonb_array_length(p_bindings)=2 and principal.authority_epoch=(administrator->>'principalEpoch')::numeric+1
       and exists(select 1 from jsonb_array_elements(p_bindings) binding
        where binding->>'principalId'=principal.principal_id::text and binding->>'principalEpoch'=principal.authority_epoch::text)))))
 ,false)
$$;


ALTER FUNCTION openpc.discovery_certificate_recovery_administrators_current(p_enrollment uuid, p_administrators jsonb, p_bindings jsonb) OWNER TO openpc_control_owner;

--
-- Name: discovery_certificate_recovery_binding_current(jsonb, uuid, jsonb, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_certificate_recovery_binding_current(p_intent jsonb, p_privacy uuid, p_binding jsonb, p_activated timestamp with time zone, p_until timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT coalesce(EXISTS(select 1 from jsonb_array_elements(p_intent->'administrators') administrator
  join control.authority_role role on role.participant_id=openpc.current_participant_id()
   and role.authority_role_id::text=administrator->>'roleId' and role.state='ACTIVE'
   and role.row_version::text=administrator->>'roleRevision'
  where p_intent->>'schemaVersion' in ('1','2') and p_binding->>'principalId'=administrator->>'principalId'
   and (p_binding->>'principalEpoch')::numeric=(administrator->>'principalEpoch')::numeric+1
   and (p_binding#>>'{permissions,validFrom}')::timestamptz=p_activated
   and (p_binding#>>'{permissions,validUntil}')::timestamptz=p_until
   and p_binding->'permissions'=jsonb_build_object(
    'roleId',role.role_id,'validFrom',p_binding#>>'{permissions,validFrom}','validUntil',p_binding#>>'{permissions,validUntil}',
    'riskClasses',administrator->'riskClasses','privacyDomainIds',jsonb_build_array(p_privacy::text),
    'capabilityIds','[]'::jsonb,'makerCheckerRequired',true,'stepUpRequired',true,'onwardDelegationDepth',0,
    'actionIntentIds',case when p_intent->>'schemaVersion'='2' then jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1') else jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
     'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
     'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1') end,
    'resourceIds',(select jsonb_agg(resource order by resource collate "C") from (select distinct unnest(ARRAY[
     p_intent#>>'{certificateRecovery,targetId}',p_intent#>>'{certificateRecovery,workloadPrincipalId}',
     p_intent#>>'{certificateRecovery,predecessorCredentialId}',p_intent#>>'{certificateRecovery,successorCredentialId}',
     administrator->>'principalId','urn:openpc:self-session:'||(administrator->>'principalId')]) resource) resources)))
 ,false)
$$;


ALTER FUNCTION openpc.discovery_certificate_recovery_binding_current(p_intent jsonb, p_privacy uuid, p_binding jsonb, p_activated timestamp with time zone, p_until timestamp with time zone) OWNER TO openpc_control_owner;

--
-- Name: discovery_certificate_recovery_current(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_certificate_recovery_current(p_enrollment uuid, p_case uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE source jsonb; binding jsonb;
BEGIN
 SELECT openpc.discovery_certificate_recovery_source(p_enrollment,p_case) INTO source;
 IF source IS NULL THEN RETURN false; END IF;
 SELECT e.document->'certificateRecovery' INTO binding FROM control.platform_recovery_enrollment e
  WHERE e.enrollment_id=p_enrollment and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id);
 RETURN coalesce(source->>'participantState'='ACTIVE' and source->>'privacyState'='ACTIVE'
  and source->>'targetId'=binding->>'targetId' and source->>'targetRevision'=binding->>'targetRevision'
  and source->>'requiresAuthenticatedDiscovery'='true'
  and source->>'workloadPrincipalId'=binding->>'workloadPrincipalId' and source->>'workloadPrincipalState'='ACTIVE'
  and source->>'workloadPrincipalKind'='WORKLOAD' and source->>'workloadPrincipalEpoch'=binding->>'workloadPrincipalEpoch'
  and source->>'credentialId'=binding->>'predecessorCredentialId' and source->>'credentialState'='ACTIVE'
  and source->>'credentialKind'='WORKLOAD_MTLS' and source->>'credentialRevision'=binding->>'predecessorRevision'
  and source->>'credentialEpoch'=binding->>'predecessorEpoch' and (source->>'credentialEpoch')::numeric>0
  and source->>'certificateFingerprint'=binding->>'predecessorFingerprint'
  and source->>'certificateBytesDigest'=binding->>'predecessorFingerprint'
  and source->>'publicKeyDigest'=binding->>'predecessorPublicKeyDigest'
  and source->>'publicKeyBytesDigest'=binding->>'predecessorPublicKeyDigest' and source->>'issuer'=binding->>'issuer'
  and source->>'subject'='urn:openpc:participant:'||(source->>'participantId')||':workload:'||(binding->>'targetId')
  and source->>'audience'='urn:openpc:workload:'||(binding->>'targetId')
  and (source->>'notAfter')::timestamptz=(binding->>'predecessorNotAfter')::timestamptz
  and (source->>'notAfter')::timestamptz<=clock_timestamp()
  and (source->>'notBefore')::timestamptz<(source->>'notAfter')::timestamptz
  and (source->>'notBefore')::timestamptz<=clock_timestamp()
  and source->>'successorExists'='false' and source->>'competingSuccessor'='false',false);
END $$;


ALTER FUNCTION openpc.discovery_certificate_recovery_current(p_enrollment uuid, p_case uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_certificate_recovery_source(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_certificate_recovery_source(p_enrollment uuid, p_case uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT jsonb_build_object(
  'participantId',e.participant_id::text,'privacyDomainId',e.privacy_domain_id::text,
  'participantState',participant.state::text,'privacyState',privacy.state::text,
  'targetId',target.runtime_target_id::text,'targetParticipantId',target.participant_id::text,
  'targetPrivacyDomainId',target.privacy_domain_id::text,'targetRevision',target.revision::text,
  'requiresAuthenticatedDiscovery',target.requires_authenticated_discovery,
  'workloadPrincipalId',principal.principal_id::text,'workloadPrincipalParticipantId',principal.participant_id::text,
  'workloadPrincipalState',principal.state::text,'workloadPrincipalKind',principal.kind::text,
  'workloadPrincipalEpoch',principal.authority_epoch::text,
  'credentialId',credential.credential_id::text,'credentialParticipantId',credential.participant_id::text,
  'credentialPrincipalId',credential.principal_id::text,'credentialState',credential.state::text,
  'credentialKind',credential.kind::text,'credentialRevision',credential.row_version::text,
  'credentialEpoch',credential.credential_epoch::text,
  'certificateFingerprint','sha256:'||encode(credential.secret_fingerprint,'hex'),
  'certificateBytesDigest','sha256:'||encode(sha256(credential.certificate_der),'hex'),
  'publicKeyDigest','sha256:'||encode(credential.public_key_digest,'hex'),
  'publicKeyBytesDigest','sha256:'||encode(sha256(credential.public_key_spki_der),'hex'),
  'issuer',credential.issuer,'subject',credential.subject,'audience',credential.audience,
  'notBefore',credential.valid_from,'notAfter',credential.valid_until,'now',clock_timestamp(),
  'successorExists',exists(select 1 from control.credential successor where successor.participant_id=e.participant_id
    and successor.credential_id::text=e.document#>>'{certificateRecovery,successorCredentialId}'),
  'competingSuccessor',exists(select 1 from control.credential successor where successor.participant_id=e.participant_id
    and successor.rotated_from_credential_id=credential.credential_id)
   or exists(select 1 from control.discovery_certificate_issuance attempt where attempt.participant_id=e.participant_id
    and attempt.predecessor_credential_id=credential.credential_id and attempt.state<>'REJECTED'
    and attempt.recovery_id is distinct from p_case))
 FROM control.platform_recovery_enrollment e
 JOIN control.participant participant on participant.participant_id=e.participant_id and participant.state='ACTIVE'
 JOIN control.privacy_domain privacy on privacy.participant_id=e.participant_id and privacy.privacy_domain_id=e.privacy_domain_id and privacy.state='ACTIVE'
 JOIN control.platform_context root on root.platform_context_id=e.platform_context_id and root.owner_participant_id=e.participant_id
  and root.state='ACTIVE' and root.authority_epoch=e.root_epoch and root.row_version=e.root_revision
 JOIN control.runtime_target target on target.participant_id=e.participant_id and target.privacy_domain_id=e.privacy_domain_id
  and target.runtime_target_id::text=e.document#>>'{certificateRecovery,targetId}'
 JOIN control.principal principal on principal.participant_id=e.participant_id
  and principal.principal_id::text=e.document#>>'{certificateRecovery,workloadPrincipalId}'
 JOIN control.credential credential on credential.participant_id=e.participant_id and credential.principal_id=principal.principal_id
  and credential.credential_id::text=e.document#>>'{certificateRecovery,predecessorCredentialId}'
 WHERE e.enrollment_id=p_enrollment and e.state='ACTIVE'
  and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
  and e.document#>>'{certificateRecovery,purpose}'='DISCOVERY_CERTIFICATE_REPLACEMENT'
  and openpc.platform_recovery_source_root_current(e)
  and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id)
  and e.valid_from<=clock_timestamp() and e.valid_until>clock_timestamp()
  and (e.document->>'assurance'<>'LOCAL_QA_VIRTUAL_AUTHENTICATOR' or current_setting('openpc.local_qa_runtime',true)='1')
  and (p_case is null or exists(select 1 from control.platform_recovery_case c where c.recovery_id=p_case
   and c.enrollment_id=e.enrollment_id and c.participant_id=e.participant_id and c.privacy_domain_id=e.privacy_domain_id
   and c.enrollment_revision=e.row_version and c.enrollment_digest=e.document_digest
   and c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   and c.intent->'certificateRecovery'=e.document->'certificateRecovery'))
$$;


ALTER FUNCTION openpc.discovery_certificate_recovery_source(p_enrollment uuid, p_case uuid) OWNER TO openpc_control_owner;

--
-- Name: discovery_certificate_resume_administrators_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.discovery_certificate_resume_administrators_current(p_enrollment uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT coalesce(EXISTS(SELECT 1 FROM control.platform_recovery_enrollment e
 WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  AND e.source_purpose='ROOT_EXPIRY_RECOVERY' AND e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
  AND e.document->>'schemaVersion'='2' AND e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
  AND current_setting('openpc.local_qa_runtime',true)='1'
  AND jsonb_array_length(e.document#>'{source,originalAdministrators}')=2
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(e.document#>'{source,originalAdministrators}') a
   WHERE a#>'{usable,administration,actionIntentIds}' IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1')
    OR a#>'{grantable,administration,actionIntentIds}' IS DISTINCT FROM jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1','ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1','ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'))
  AND openpc.platform_recovery_source_root_current(e) AND openpc.platform_recovery_original_administrators_current(e)),false)
$$;


ALTER FUNCTION openpc.discovery_certificate_resume_administrators_current(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: enforce_mutation_candidate_lifecycle(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.enforce_mutation_candidate_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.mutation_candidate';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'PROPOSED' OR NEW."consumed_operation_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.mutation_candidate initial state';
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."mutation_candidate_id",NEW."participant_id",NEW."privacy_domain_id",
         NEW."action_intent_id",NEW."catalog_operation_id",NEW."resource_type",
         NEW."operation_class",NEW."resource_id",NEW."candidate_digest",
         NEW."candidate_document",NEW."expected_revision",NEW."idempotency_key",
         NEW."maker_principal_id",NEW."maker_session_id",NEW."maker_session_epoch",
         NEW."maker_participant_epoch",NEW."maker_principal_epoch",NEW."maker_assignment_id",
         NEW."maker_assignment_row_version",NEW."maker_authority_envelope_id",
         NEW."maker_authority_epoch",NEW."maker_delegation_epoch",NEW."expires_at",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."mutation_candidate_id",OLD."participant_id",OLD."privacy_domain_id",
         OLD."action_intent_id",OLD."catalog_operation_id",OLD."resource_type",
         OLD."operation_class",OLD."resource_id",OLD."candidate_digest",
         OLD."candidate_document",OLD."expected_revision",OLD."idempotency_key",
         OLD."maker_principal_id",OLD."maker_session_id",OLD."maker_session_epoch",
         OLD."maker_participant_epoch",OLD."maker_principal_epoch",OLD."maker_assignment_id",
         OLD."maker_assignment_row_version",OLD."maker_authority_envelope_id",
         OLD."maker_authority_epoch",OLD."maker_delegation_epoch",OLD."expires_at",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.mutation_candidate identity';
  END IF;
  IF NOT ((OLD."state" = 'PROPOSED' AND NEW."state" IN ('APPROVAL_REQUESTED','CANCELLED'))
          OR (OLD."state" = 'APPROVAL_REQUESTED' AND NEW."state" IN ('APPROVAL_REQUESTED','APPROVED','CANCELLED'))
          OR (OLD."state" = 'APPROVED' AND NEW."state" = 'CONSUMED')) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'control.mutation_candidate lifecycle';
  END IF;
  IF NEW."updated_at" <= OLD."updated_at"
     OR ((NEW."state" = 'CONSUMED') <> (NEW."consumed_operation_id" IS NOT NULL)) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.mutation_candidate transition';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION openpc.enforce_mutation_candidate_lifecycle() OWNER TO openpc_control_owner;

--
-- Name: enforce_mutation_resume(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.enforce_mutation_resume() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE old_attempt control.mutation_candidate%ROWTYPE; prior control.approval_request%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF row(NEW.predecessor_candidate_id,NEW.predecessor_approval_id,NEW.resume_operation_id,NEW.resume_request,NEW.attempt)
    IS DISTINCT FROM row(OLD.predecessor_candidate_id,OLD.predecessor_approval_id,OLD.resume_operation_id,OLD.resume_request,OLD.attempt)
   OR EXISTS (SELECT 1 FROM control.mutation_candidate s WHERE s.predecessor_candidate_id=OLD.mutation_candidate_id)
  THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.predecessor_candidate_id IS NULL THEN
  IF NEW.resume_request IS NOT NULL THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT old_attempt FROM control.mutation_candidate
  WHERE mutation_candidate_id=NEW.predecessor_candidate_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM control.authority_envelope e JOIN control.platform_recovery_case c
  ON c.participant_id=e.participant_id AND c.recovery_id=e.recovery_case_id
  WHERE e.participant_id=NEW.participant_id AND e.authority_envelope_id=NEW.maker_authority_envelope_id
   AND e.representation='RECOVERY_V1' AND c.intent ? 'continuation')
  AND NOT (NEW.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE' AND NEW.resume_request ? 'platformReceivingProof')
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.resume_request->>'command'='DISCOVERY_PREAPPROVAL_CONTINUE' THEN
  PERFORM openpc.assert_discovery_preapproval_continuation(NEW);
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT prior FROM control.approval_request
  WHERE approval_request_id=NEW.predecessor_approval_id FOR UPDATE;
 IF row(NEW.participant_id,NEW.privacy_domain_id,NEW.action_intent_id,NEW.catalog_operation_id,
        NEW.resource_type,NEW.operation_class,NEW.resource_id,NEW.candidate_digest,NEW.candidate_document,
        NEW.expected_revision,NEW.idempotency_key,NEW.maker_principal_id)
    IS DISTINCT FROM row(old_attempt.participant_id,old_attempt.privacy_domain_id,old_attempt.action_intent_id,
        old_attempt.catalog_operation_id,old_attempt.resource_type,old_attempt.operation_class,old_attempt.resource_id,
        old_attempt.candidate_digest,old_attempt.candidate_document,old_attempt.expected_revision,
        old_attempt.idempotency_key,old_attempt.maker_principal_id)
   OR NEW.attempt<>old_attempt.attempt+1 OR NEW.expires_at<=clock_timestamp()
   OR NEW.expires_at>clock_timestamp()+interval '30 minutes'
   OR prior.participant_id<>NEW.participant_id OR prior.privacy_domain_id<>NEW.privacy_domain_id
   OR prior.subject_type<>'CONFIGURATION_CANDIDATE' OR prior.subject_id<>old_attempt.mutation_candidate_id
   OR prior.subject_digest<>NEW.candidate_digest OR prior.subject_version<>NEW.expected_revision
   OR prior.maker_principal_id<>NEW.maker_principal_id OR prior.checker_principal_id IS NULL
   OR prior.checker_principal_id=NEW.maker_principal_id
   OR NOT EXISTS(SELECT 1 FROM control.principal checker WHERE checker.participant_id=NEW.participant_id
      AND checker.principal_id=prior.checker_principal_id AND checker.state='ACTIVE') OR prior.state NOT IN ('OPEN','APPROVED','EXPIRED')
   OR EXISTS (SELECT 1 FROM control.mutation_candidate s WHERE s.predecessor_candidate_id=old_attempt.mutation_candidate_id)
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- The database independently clips CREATE continuation to both original scope deadlines.
 IF NEW.catalog_operation_id='ID-OP-ENVELOPE-CREATE' AND NEW.expires_at>least(
    to_timestamp((old_attempt.candidate_document#>>'{usable,validUntilNs}')::numeric/1000000000),
    to_timestamp((old_attempt.candidate_document#>>'{grantable,validUntilNs}')::numeric/1000000000))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- A still-live approval cannot be replaced merely to obtain another authorization.
 IF NOT (NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request ? 'discoveryReceivingProof')
  AND NOT (NEW.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE' AND NEW.resume_request ? 'platformReceivingProof')
  AND old_attempt.expires_at>clock_timestamp() AND prior.expires_at>clock_timestamp() AND
    (prior.state='OPEN' OR EXISTS (SELECT 1 FROM control.approval_decision_record d
      JOIN control.mfa_challenge m ON m.participant_id=d.participant_id AND m.mfa_challenge_id=d.mfa_challenge_id
      JOIN control.session proof_session ON proof_session.participant_id=m.participant_id
        AND proof_session.session_id=m.session_id AND proof_session.principal_id=m.principal_id
        AND proof_session.session_id=d.approver_session_id AND proof_session.session_epoch=d.approver_session_epoch
      WHERE d.participant_id=prior.participant_id AND d.privacy_domain_id=prior.privacy_domain_id
        AND d.approval_request_id=prior.approval_request_id AND d.decision='APPROVE'
        AND m.principal_id=d.approver_principal_id AND m.session_id=d.approver_session_id
        AND CASE WHEN proof_session.step_up_mfa_challenge_id IS NULL
          THEN m.consumed_at>clock_timestamp()-interval '5 minutes'
          ELSE proof_session.step_up_mfa_challenge_id=m.mfa_challenge_id
            AND openpc.session_step_up_valid_until(m.participant_id,m.session_id,m.principal_id)>clock_timestamp() END
        AND m.expires_at>clock_timestamp()))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.resume_request IS NULL OR jsonb_typeof(NEW.resume_request)<>'object' OR NEW.resume_request->>'command' IS DISTINCT FROM 'RESUME'
    OR NEW.resume_request->>'actionIntentId' IS DISTINCT FROM 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
    OR NEW.resume_request->>'approvalRequestId' IS DISTINCT FROM 'urn:openpc:resource:'||prior.approval_request_id::text
    OR NEW.resume_request->>'expectedRevision' IS DISTINCT FROM prior.row_version::text
    OR NEW.resume_request->>'expectedAttempt' IS DISTINCT FROM old_attempt.attempt::text
    OR NEW.resume_request->>'predecessorCandidateId' IS DISTINCT FROM old_attempt.mutation_candidate_id::text
    OR NEW.resume_request->>'candidateDigest' IS DISTINCT FROM 'sha256:'||encode(old_attempt.candidate_digest,'hex')
    OR NOT EXISTS (SELECT 1 FROM control.idempotency_record r WHERE r.participant_id=NEW.participant_id
      AND r.privacy_domain_id=NEW.privacy_domain_id AND r.operation_id=NEW.resume_operation_id
      AND r.principal_id=NEW.maker_principal_id AND r.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
      AND r.catalog_operation_id='LEGACY' AND r.expected_aggregate_version=prior.row_version
      AND r.input_digest=sha256(convert_to(openpc.signing_canonical_json(CASE WHEN NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
       AND NEW.resume_request ? 'discoveryReceivingProof' THEN NEW.resume_request-'discoveryReceivingProof'
       WHEN NEW.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE' AND NEW.resume_request ? 'platformReceivingProof'
         THEN NEW.resume_request-'platformReceivingProof' ELSE NEW.resume_request END),'UTF8')))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  PERFORM openpc.assert_discovery_approval_resume(NEW);
 ELSIF NEW.resume_request ? 'platformReceivingProof' THEN
  PERFORM openpc.assert_platform_recovery_approval_resume(NEW);
 ELSE
  PERFORM openpc.assert_mutation_resume_no_effect(old_attempt.mutation_candidate_id);
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.enforce_mutation_resume() OWNER TO openpc_control_owner;

--
-- Name: enforce_pending_delivery_lifecycle(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.enforce_pending_delivery_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE captured_now timestamptz := clock_timestamp();
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.pending_delivery';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'PENDING' OR NEW."lease_owner" IS NOT NULL
       OR NEW."lease_expires_at" IS NOT NULL OR NEW."next_retry_at" IS NOT NULL
       OR NEW."safe_reason" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery initial state';
    END IF;
    NEW."first_observed_at" := captured_now;
    NEW."last_observed_at" := captured_now;
    RETURN NEW;
  END IF;
  IF NEW."pending_delivery_id" is distinct from OLD."pending_delivery_id"
     OR row(NEW."participant_id",NEW."privacy_domain_id",NEW."chain_id",NEW."profile_id",NEW."profile_version",NEW."correlated_log_identity_hmac",NEW."entity_hmac",NEW."entity_scope_digest",NEW."delivery_surface",NEW."protected_delivery_reference_digest",NEW."subscription_reference_digest",NEW."session_reference_digest") is distinct from row(OLD."participant_id",OLD."privacy_domain_id",OLD."chain_id",OLD."profile_id",OLD."profile_version",OLD."correlated_log_identity_hmac",OLD."entity_hmac",OLD."entity_scope_digest",OLD."delivery_surface",OLD."protected_delivery_reference_digest",OLD."subscription_reference_digest",OLD."session_reference_digest") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'pending delivery identity';
  END IF;
  IF NOT ((OLD."state" = 'PENDING' and NEW."state" = 'LEASED') or (OLD."state" = 'LEASED' and NEW."state" = 'DELIVERED') or (OLD."state" = 'LEASED' and NEW."state" = 'RETRY_WAIT') or (OLD."state" = 'RETRY_WAIT' and NEW."state" = 'LEASED') or (OLD."state" = 'PENDING' and NEW."state" = 'QUARANTINED') or (OLD."state" = 'LEASED' and NEW."state" = 'QUARANTINED') or (OLD."state" = 'RETRY_WAIT' and NEW."state" = 'QUARANTINED'))
     AND NOT (OLD."state" = 'LEASED' AND NEW."state" = 'LEASED'
              AND OLD."lease_expires_at" <= captured_now) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'pending delivery lifecycle';
  END IF;
  NEW."first_observed_at" := OLD."first_observed_at";
  NEW."last_observed_at" := captured_now;
  IF NEW."state" = 'LEASED' THEN
    IF NEW."lease_owner" IS NULL OR NEW."lease_expires_at" IS NULL
       OR NEW."lease_expires_at" <= captured_now THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery lease';
    END IF;
    NEW."next_retry_at" := NULL;
    NEW."safe_reason" := NULL;
  ELSIF NEW."state" = 'RETRY_WAIT' THEN
    IF NEW."next_retry_at" IS NULL OR NEW."next_retry_at" <= captured_now THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery retry';
    END IF;
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."safe_reason" := NULL;
  ELSIF NEW."state" = 'QUARANTINED' THEN
    IF NEW."safe_reason" IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'pending delivery quarantine';
    END IF;
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."next_retry_at" := NULL;
  ELSE
    NEW."lease_owner" := NULL;
    NEW."lease_expires_at" := NULL;
    NEW."next_retry_at" := NULL;
    NEW."safe_reason" := NULL;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION openpc.enforce_pending_delivery_lifecycle() OWNER TO openpc_control_owner;

--
-- Name: enforce_work_item_lifecycle(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.enforce_work_item_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'OPEN' OR NEW."row_version" <> 1
       OR NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item initial state';
    END IF;
    -- Public remediation creation keeps its business receipt owner. Every
    -- internal remediation insert must instead prove native completion custody;
    -- context chooses the checker, never supplies its authorization.
    IF openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
      OR (NEW.kind='REMEDIATION' AND openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-WORK_ITEMS_CREATE_RESOURCE-V1') THEN
      PERFORM openpc.check_notification_completion_remediation_effect(NEW);
    END IF;
    IF current_setting('openpc.action_intent_id',true)='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND NEW.kind='DELIVERY_FAILURE' THEN
      PERFORM openpc.check_notification_delivery_failure_work(NEW);
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."work_item_id",NEW."participant_id",NEW."privacy_domain_id",NEW."kind",
         NEW."resource_ref",NEW."created_by_principal_id",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."work_item_id",OLD."participant_id",OLD."privacy_domain_id",OLD."kind",
         OLD."resource_ref",OLD."created_by_principal_id",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item identity';
  END IF;
  IF NOT ((OLD."state" = 'OPEN' AND NEW."state" = 'OPEN')
          OR (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED')
          OR (OLD."state" = 'CLAIMED' AND NEW."state" = 'COMPLETED')
          OR (OLD."state" IN ('OPEN','CLAIMED') AND NEW."state" = 'CANCELLED')) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'control.work_item lifecycle';
  END IF;
  IF NEW."assignee_principal_id" IS DISTINCT FROM OLD."assignee_principal_id"
     AND NOT (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED'
              AND OLD."assignee_principal_id" IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item assignee';
  END IF;
  IF NEW."row_version" <> OLD."row_version" + 1 OR NEW."updated_at" <= OLD."updated_at" THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item revision';
  END IF;
  IF NEW."state" = 'OPEN' AND
     (NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item open actor';
  ELSIF NEW."state" = 'CLAIMED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NOT NULL
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item claim actor';
  ELSIF NEW."state" = 'COMPLETED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NULL
         OR NEW."completed_by_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id"
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."completed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item completion actor';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION openpc.enforce_work_item_lifecycle() OWNER TO openpc_control_owner;

--
-- Name: evidence_catalogue_projection(control.evidence_catalogue); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_catalogue_projection(c control.evidence_catalogue) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('evidenceId',(c).evidence_id::text,'participantId',(c).participant_id::text,
  'privacyDomainId',(c).privacy_domain_id::text,'streamId',(c).stream_id,'recordId',(c).record_id,
  'segmentId',(c).segment_id::text,'sequence',(c).sequence::text,'evidenceClass',(c).evidence_class,
  'sourceFormat',(c).source_format,'receiptDigest',(c).receipt_digest,
  'occurredAt',to_char((c).occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'createdAt',to_char((c).created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
$$;


ALTER FUNCTION openpc.evidence_catalogue_projection(c control.evidence_catalogue) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_action(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_action(selection jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE selection->>'version' WHEN 'OPENPC_LOCAL_EVIDENCE_DELETION_V1' THEN 'ACT-EVIDENCE_DELETIONS_CREATE_RESOURCE-V1'
 WHEN 'OPENPC_LOCAL_EVIDENCE_DELETION_BATCH_V1' THEN 'ACT-EVIDENCE_DELETIONS_CREATE_BATCH-V1'
 WHEN 'OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN 'ACT-EVIDENCE_DELETIONS_CREATE_RAW_BATCH-V1'
 WHEN 'OPENPC_PROJECTION_DELETION_BATCH_V1' THEN 'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
 WHEN 'OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1' THEN 'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1' END
$$;


ALTER FUNCTION openpc.evidence_deletion_action(selection jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_after_digest(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_after_digest(selector_digest text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.local-payload-after.v1','selectorDigest',selector_digest,'payloads','[]'::jsonb)),'UTF8')),'hex')
$$;


ALTER FUNCTION openpc.evidence_deletion_after_digest(selector_digest text) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_operation(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_operation(selection jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE selection->>'version' WHEN 'OPENPC_LOCAL_EVIDENCE_DELETION_V1' THEN 'CFG-OP-DELETE-LOCAL-EVIDENCE'
 WHEN 'OPENPC_LOCAL_EVIDENCE_DELETION_BATCH_V1' THEN 'CFG-OP-DELETE-LOCAL-EVIDENCE-BATCH'
 WHEN 'OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN 'CFG-OP-DELETE-RAW-PROOF-BATCH'
 WHEN 'OPENPC_PROJECTION_DELETION_BATCH_V1' THEN 'CFG-OP-DELETE-PROJECTION-BATCH'
 WHEN 'OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1' THEN 'CFG-OP-DELETE-RUNTIME-ARTIFACT-BATCH' END
$$;


ALTER FUNCTION openpc.evidence_deletion_operation(selection jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_profile_version(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_profile_version(selection jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN selection->>'version'='OPENPC_PROJECTION_DELETION_BATCH_V1' THEN
  CASE selection->>'sourceKind' WHEN 'RPC_RETIRED_CATALOGUE' THEN 3 WHEN 'RETENTION_POLICY_CATALOGUE' THEN 2 ELSE 1 END
 WHEN selection->>'version' IN ('OPENPC_LOCAL_EVIDENCE_DELETION_V1','OPENPC_LOCAL_EVIDENCE_DELETION_BATCH_V1') AND selection ? 'sourceRpcRetirements' THEN 2 ELSE 1 END
$$;


ALTER FUNCTION openpc.evidence_deletion_profile_version(selection jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_rejections(text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_rejections(stream text, segment uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE item control.evidence_catalogue; source record; claims jsonb; command uuid; proofs jsonb:='[]'::jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 -- Lock order: evidence lifecycle, then unique command UUIDs in lexical order.
 -- Reservation, handoff and terminal rejection already use this command fence.
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||current_setting('openpc.participant_id'),0));
 IF EXISTS(SELECT 1 FROM control.evidence_catalogue c
  WHERE c.participant_id=current_setting('openpc.participant_id')::uuid
   AND c.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
   AND c.stream_id=stream AND c.segment_id=segment
   AND c.evidence_class NOT IN ('AUTHENTICATION','BUSINESS_TRANSITION','EFFECT'))
 THEN RETURN NULL; END IF;
 FOR item IN SELECT c.* FROM control.evidence_catalogue c
  WHERE c.participant_id=current_setting('openpc.participant_id')::uuid
   AND c.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
   AND c.stream_id=stream AND c.segment_id=segment AND c.evidence_class='EFFECT'
  ORDER BY c.record_id,c.evidence_id
 LOOP
  IF item.source_format='OPENPC_RPC_DECISION_TRANSITION_V1' THEN
   -- The separately typed RPC proof list is mandatory in the selection. Never
   -- convert a completed read or a retirement receipt into a no-send rejection.
   IF openpc.rpc_retired_catalogue_proof(item) IS NULL OR openpc.rpc_retired_catalogue_has_references(item) THEN RETURN NULL; END IF;
   CONTINUE;
  END IF;
  IF item.source_format<>'PC-DEPLOYMENT-RESERVATION-REJECTION-1'
   OR item.record_id!~'^deployment:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:1$'
  THEN RETURN NULL; END IF;
  command:=split_part(item.record_id,':',2)::uuid;
  PERFORM openpc.lock_deployment_command(command);
  SELECT *,count(*) OVER() source_count INTO source
   FROM openpc.deployment_rejection_source(command,item.participant_id,item.privacy_domain_id);
  IF NOT FOUND OR source.source_count<>1 OR source.result_digest<>item.receipt_digest
   OR source.result_digest<>'sha256:'||encode(sha256(source.signed_bytes),'hex') THEN RETURN NULL; END IF;
  claims:=convert_from(source.signed_bytes,'UTF8')::jsonb;
  IF claims->>'purpose' IS DISTINCT FROM 'openpc:deployment-reservation-rejection:v1'
   OR claims->'claims'->>'schema' IS DISTINCT FROM item.source_format
   OR claims->'claims'->'binding'->>'commandId' IS DISTINCT FROM command::text
   OR claims->'claims'->'binding'->>'attemptId' IS DISTINCT FROM source.attempt_id
   OR claims->'claims'->'binding'->'owner'->>'participant_id' IS DISTINCT FROM item.participant_id::text
   OR claims->'claims'->'binding'->'owner'->>'privacy_domain_id' IS DISTINCT FROM item.privacy_domain_id::text
   OR claims->'claims'->>'candidateDigest' IS DISTINCT FROM source.candidate_digest
   OR claims->'claims'->>'authorizationEvidenceDigest' IS DISTINCT FROM source.evidence_digest
   OR NOT coalesce(claims->'claims'->>'reason' IN ('CUSTODY_CONFLICT','PREPARATION_EXPIRED','MODULE_GENERATION_UNAVAILABLE'),false)
  THEN RETURN NULL; END IF;
  proofs:=proofs||jsonb_build_array(jsonb_build_object(
   'evidenceId','urn:openpc:resource:'||item.evidence_id::text,'commandId',command::text,
   'attemptId',source.attempt_id,'receiptDigest',source.result_digest,
   'candidateDigest','sha256:'||source.candidate_digest,'authorizationEvidenceDigest','sha256:'||source.evidence_digest,
   'externalAttemptState','NOT_STARTED','sourceFormat',item.source_format));
 END LOOP;
 RETURN proofs;
END $_$;


ALTER FUNCTION openpc.evidence_deletion_rejections(stream text, segment uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_selection_plan(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_selection_plan(selection jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF selection->>'version'='OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1' THEN
  RETURN openpc.runtime_artifact_retirement_plan(right(selection->>'retentionPolicyId',36)::uuid,
   right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_PROJECTION_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.projection_deletion_batch_plan(right(selection->>'evidenceId',36)::uuid,NULL,selection->>'dataClass');
  END IF;
  RETURN openpc.projection_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid,selection->>'dataClass');
 ELSIF selection->>'version'='OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.raw_proof_deletion_batch_plan(right(selection->>'objectRef',36)::uuid,NULL);
  END IF;
  RETURN openpc.raw_proof_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_LOCAL_EVIDENCE_DELETION_V1' THEN
  RETURN openpc.local_evidence_deletion_plan(right(selection->>'evidenceId',36)::uuid);
 ELSIF selection->>'version'='OPENPC_LOCAL_EVIDENCE_DELETION_BATCH_V1' THEN
  IF selection->'priorCursor'='null'::jsonb THEN
   RETURN openpc.local_evidence_deletion_batch_plan(right(selection->>'evidenceId',36)::uuid,NULL);
  END IF;
  RETURN openpc.local_evidence_deletion_batch_plan(NULL,right(selection->'priorCursor'->>'deletionJobId',36)::uuid);
 END IF;
 RAISE EXCEPTION 'PC-DATA-6004';
END $$;


ALTER FUNCTION openpc.evidence_deletion_selection_plan(selection jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_selector_digest(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_selector_digest(selection jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.local-payload-selector.v1','participantId',selection->'participantId',
  'privacyDomainId',selection->'privacyDomainId','streamId',selection->'streamId','segmentId',selection->'segmentId',
  'firstSequence',selection->'firstSequence','throughSequence',selection->'throughSequence')),'UTF8')),'hex')
$$;


ALTER FUNCTION openpc.evidence_deletion_selector_digest(selection jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_deletion_state_projection(control.deletion_job); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deletion_state_projection(job control.deletion_job) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',openpc.business_uuid((job).retention_policy_id),
  '1',openpc.business_bytes(decode(substring((job).target_selector_digest from 8),'hex')),
  '2',openpc.business_bytes(decode(substring((job).eligibility_digest from 8),'hex')),
  '3',openpc.business_bytes(decode(substring((job).before_digest from 8),'hex')),
  '4',openpc.business_bytes(decode(substring((job).after_digest from 8),'hex')),
  '5',openpc.business_uuid((job).attempt_id),'6',openpc.business_uuid((job).operation_id),
  '7',openpc.business_uuid((job).approval_request_id),'8',(job).deleted_count,'9',(job).deleted_bytes,
  '10',(job).retained_alias_count,'11',floor(extract(epoch from (job).started_at)*1000000)*1000,
  '12',floor(extract(epoch from (job).completed_at)*1000000)*1000,'13',(job).before_used_bytes,'14',(job).after_used_bytes)
$$;


ALTER FUNCTION openpc.evidence_deletion_state_projection(job control.deletion_job) OWNER TO openpc_control_owner;

