--
-- Name: evidence_deployment_lineage_projection(control.evidence_catalogue); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deployment_lineage_projection(source control.evidence_catalogue) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r record; claims jsonb; occurrence jsonb; invalidation jsonb; historical jsonb;
BEGIN
 IF (source).evidence_class<>'EFFECT' OR (source).source_format<>'PC-DEPLOYMENT-JOURNAL-PROJECTION-1'
  OR (source).record_id!~'^deployment:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:[1-9][0-9]{0,19}$' THEN RETURN NULL; END IF;
 SELECT d.signed_bytes,d.result_digest,d.sequence,a.* INTO r
  FROM control.deployment_result d JOIN control.deployment_address_reservation a
   ON a.participant_id=d.participant_id AND a.privacy_domain_id=d.privacy_domain_id AND a.command_id=d.command_id
  WHERE d.participant_id=(source).participant_id AND d.privacy_domain_id=(source).privacy_domain_id
   AND d.command_id=split_part((source).record_id,':',2)::uuid AND d.sequence=split_part((source).record_id,':',3)::numeric
   AND d.result_digest=(source).receipt_digest AND d.result_digest='sha256:'||encode(sha256(d.signed_bytes),'hex')
   AND a.state='HANDOFF';
 IF NOT FOUND THEN RETURN NULL; END IF;
 claims:=convert_from(r.signed_bytes,'UTF8')::jsonb;
 IF claims->>'purpose' IS DISTINCT FROM 'openpc:deployment-journal-projection:v1' THEN RETURN NULL; END IF;
 claims:=claims->'claims';
 IF claims->>'schema' IS DISTINCT FROM (source).source_format
  OR claims->>'sequence' IS DISTINCT FROM r.sequence::text
  OR (regexp_replace(claims->>'observedAt','([.][0-9]{6})[0-9]+',chr(92)||'1'))::timestamptz IS DISTINCT FROM (source).occurred_at
  OR claims->'owner'->>'participant_id' IS DISTINCT FROM (source).participant_id::text
  OR claims->'owner'->>'privacy_domain_id' IS DISTINCT FROM (source).privacy_domain_id::text
  OR claims->'status'->>'operationId' IS DISTINCT FROM 'urn:openpc:operation:'||r.command_id::text
  OR claims->'status'->>'attemptId' IS DISTINCT FROM r.attempt_id::text
  OR claims->>'targetRuntimeId' IS DISTINCT FROM replace(r.target_runtime_id,'urn:openpc:resource:','')
  OR claims->>'intentDigest' IS DISTINCT FROM substring(r.intent_digest from 8)
  OR claims->>'preparationDigest' IS DISTINCT FROM substring(r.prepared_record_digest from 8)
  OR claims->>'chainId' IS DISTINCT FROM r.chain_id
  OR claims->>'genesisDigest' IS DISTINCT FROM substring(r.genesis_digest from 8)
  OR claims->'status'->>'signedTransactionHash' IS DISTINCT FROM r.transaction_hash THEN RETURN NULL; END IF;
 occurrence:=claims->'outcome'->'occurrence'; invalidation:=claims->'outcome'->'invalidation';
 historical:=jsonb_build_object('sourceVersion',r.sequence::text,'receiptDigest',r.result_digest,
  'observedAt',claims->>'observedAt','state',claims->'status'->>'state','truthState',claims->'status'->>'truthState',
  'journalEvidenceDigest',claims->'status'->>'evidenceDigest',
  'finality',CASE WHEN invalidation<>'null'::jsonb THEN CASE WHEN invalidation->>'reason'='REORG' THEN 'REORG' ELSE 'INVALIDATED' END
    WHEN occurrence<>'null'::jsonb THEN 'FINALIZED' ELSE 'NOT_ESTABLISHED' END,
  'occurrence',CASE WHEN occurrence='null'::jsonb THEN 'null'::jsonb ELSE jsonb_build_object(
   'occurrenceId',occurrence->>'occurrenceId','occurrenceDigest','sha256:'||(occurrence->>'semanticDigest'),
   'blockHash','sha256:'||(occurrence->>'blockHash'),'blockNumber',occurrence->>'blockNumber','reorgStatus',occurrence->>'reorgStatus') END,
  'invalidation',CASE WHEN invalidation='null'::jsonb THEN 'null'::jsonb ELSE jsonb_build_object(
   'occurrenceId',invalidation->>'occurrenceId','occurrenceDigest','sha256:'||(invalidation->>'occurrenceDigest'),
   'observationDigest','sha256:'||(invalidation->>'observationDigest'),'reason',invalidation->>'reason') END);
 RETURN jsonb_build_object('chainId',r.chain_id,'genesisDigest',r.genesis_digest,'historical',historical);
EXCEPTION WHEN insufficient_privilege OR invalid_text_representation OR datetime_field_overflow THEN RETURN NULL;
END $_$;


ALTER FUNCTION openpc.evidence_deployment_lineage_projection(source control.evidence_catalogue) OWNER TO openpc_control_owner;

--
-- Name: evidence_deployment_projection(control.evidence_catalogue); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_deployment_projection(source control.evidence_catalogue) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE lineage jsonb; r record;
BEGIN
 lineage:=openpc.evidence_deployment_lineage_projection(source);
 IF lineage IS NULL THEN RETURN NULL; END IF;
 SELECT a.*,i.deployment_intent_id,i.execution_principal_id,i.execution_workload_id INTO r
 FROM control.deployment_address_reservation a JOIN control.deployment_intent i
  ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
   AND i.preparation_digest=a.prepared_record_digest AND i.intent_digest=a.intent_digest
   AND 'urn:openpc:resource:'||i.runtime_target_id::text=a.target_runtime_id
 WHERE a.participant_id=(source).participant_id AND a.privacy_domain_id=(source).privacy_domain_id
  AND a.command_id=split_part((source).record_id,':',2)::uuid AND a.state='HANDOFF';
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('integrity','VERIFIED_PURPOSE_SIGNATURE','authority','OBSERVATION_ONLY',
  'operationId','urn:openpc:operation:'||r.command_id::text,'attemptId',r.attempt_id::text,
  'deploymentIntentId','urn:openpc:resource:'||r.deployment_intent_id::text,'targetRuntimeId',r.target_runtime_id,
  'executionPrincipalId',r.execution_principal_id::text,'workloadId',r.execution_workload_id,
  'intentDigest',r.intent_digest,'preparationDigest',r.prepared_record_digest,
  'chainId',r.chain_id,'genesisDigest',r.genesis_digest,'transactionHash',r.transaction_hash,
  'historical',lineage->'historical');
END $$;


ALTER FUNCTION openpc.evidence_deployment_projection(source control.evidence_catalogue) OWNER TO openpc_control_owner;

--
-- Name: evidence_export_completion_source(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_export_completion_source(export_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source jsonb;
BEGIN
 PERFORM openpc.assert_request_context(false);
 SELECT jsonb_build_object('participantId',r.participant_id::text,'privacyDomainId',r.privacy_domain_id::text,
  'streamId',r.stream_id,'evidenceExportId',r.evidence_export_id::text,'startOperationId',r.start_operation_id::text,
  'causationId',event.event_id::text,'requestDigest',r.request_digest,'checkpoint',r.checkpoint::text,
  'outputDigest',o.output_digest,'recordCount',jsonb_array_length(s.selection->'records')::text)
 INTO STRICT source
 FROM control.evidence_export_request r
 JOIN control.evidence_export_output o USING(participant_id,privacy_domain_id,stream_id,evidence_export_id)
 JOIN control.evidence_export_selection s USING(participant_id,privacy_domain_id,stream_id,request_digest)
 JOIN control.mutation_evidence e ON e.participant_id=r.participant_id AND e.privacy_domain_id=r.privacy_domain_id
  AND e.operation_id=r.start_operation_id AND e.aggregate_id=r.evidence_export_id AND e.aggregate_type='evidence-export'
  AND e.action_intent_id='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND e.catalog_operation_id='CFG-OP-START-EVIDENCE-EXPORT'
 JOIN control.idempotency_record i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
  AND i.operation_id=e.operation_id AND i.catalog_operation_id=e.catalog_operation_id AND i.action_intent_id=e.action_intent_id
  AND i.input_digest=e.candidate_digest AND i.terminal_state='COMMITTED'
 JOIN control.mutation_candidate c ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
  AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  AND c.action_intent_id=e.action_intent_id AND c.catalog_operation_id=e.catalog_operation_id
  AND c.operation_class='EXPORT' AND c.state='CONSUMED' AND c.candidate_document->>'inputDigest'=r.request_digest
 JOIN control.outbox_event event ON event.participant_id=e.participant_id AND event.privacy_domain_id=e.privacy_domain_id
  AND event.aggregate_type=e.aggregate_type AND event.aggregate_id=e.aggregate_id
  AND event.event_type='openpc.evidence.export.started.v1'
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'revision'=(i.expected_aggregate_version+1)::text
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex')
  AND event.payload_digest=sha256(event.payload_cbor)
 WHERE r.participant_id=current_setting('openpc.participant_id')::uuid
  AND r.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid AND r.evidence_export_id=export_id
  AND r.state='SUCCEEDED' AND r.output_digest=o.output_digest
  AND r.checkpoint=(s.selection->'range'->>'throughSequence')::numeric
  AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||r.evidence_export_id::text
  AND r.request_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(s.selection),'UTF8')),'hex')
  AND o.output_digest='sha256:'||encode(sha256(o.artifact),'hex')
  AND jsonb_array_length(convert_from(o.artifact,'UTF8')::jsonb->'records')=jsonb_array_length(s.selection->'records');
 RETURN source;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-DATA-6007-EVIDENCE-EXPORT-COMPLETION-SOURCE';
END $$;


ALTER FUNCTION openpc.evidence_export_completion_source(export_id uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_export_producer_authority(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_export_producer_authority(wanted text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE installed control.evidence_export_producer_installation; authority jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT installed FROM control.evidence_export_producer_installation
 WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id()
 AND trust_digest=wanted AND state='ACTIVE';
select jsonb_build_object('schema','pc.evidence-export.producer-authority.v1',
      'installationDigest',(installed.trust_digest)::text,'participantEpoch',p.authority_epoch::text,'principalEpoch',a.authority_epoch::text,
      'workloadEpoch',c.credential_epoch::text,'workloadCredentialId',c.credential_id::text,
      'participantId',p.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,
      'principalId',a.principal_id::text,'workloadId',c.audience,'certificateFingerprint',c.secret_fingerprint,
      'keyDigest','sha256:'||encode(c.public_key_digest,'hex'),
      'participantVersion',p.row_version::text,'privacyVersion',d.row_version::text,
      'principalVersion',a.row_version::text,'credentialVersion',c.row_version::text,
      'subject',c.subject,'validFrom',c.valid_from::text,'validUntil',c.valid_until::text) authority
      INTO STRICT authority
      from control.participant p join control.privacy_domain d on d.participant_id=p.participant_id
      join control.principal a on a.participant_id=p.participant_id
      join control.credential c on c.participant_id=a.participant_id and c.principal_id=a.principal_id
      where p.participant_id=(installed.participant_id) and d.privacy_domain_id=(installed.privacy_domain_id) and a.principal_id=(installed.principal_id) and c.credential_id=(installed.workload_credential_id)
      and p.state='ACTIVE' and d.state='ACTIVE' and a.state='ACTIVE' and a.kind='WORKLOAD'
      and c.kind='WORKLOAD_MTLS' and c.state='ACTIVE' and c.credential_epoch=(installed.workload_epoch) and c.audience=(installed.trust->>'workloadId')
      and c.valid_from<=clock_timestamp() and c.valid_until>clock_timestamp()
      and c.public_key_digest<>decode(substring((installed.signer_id)::text from 8),'hex')
      and floor(extract(epoch from clock_timestamp())*1000000)*1000 between (installed.trust->>'validFromNs')::numeric and (installed.trust->>'validUntilNs')::numeric-1 FOR SHARE OF p,d,a,c;
 RETURN authority;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-PRODUCER';
END $$;


ALTER FUNCTION openpc.evidence_export_producer_authority(wanted text) OWNER TO openpc_control_owner;

--
-- Name: evidence_fact_hold_metadata(control.evidence_catalogue); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_fact_hold_metadata(source control.evidence_catalogue) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb; queue jsonb; item jsonb; lineage jsonb; reference jsonb; candidates jsonb;
 seen text[]:=ARRAY[]::text[]; unresolved boolean:=false; steps integer:=0;
 projections jsonb:='[]'; facts jsonb:='[]'; blocks jsonb:='[]'; generations jsonb:='[]';
BEGIN
 -- The closure resolver reloads authoritative ancestors. First bind the caller's
 -- starting record itself, so a modified class/digest/sequence cannot borrow the
 -- lineage of an otherwise valid catalogue identity.
 IF (source).source_format IS DISTINCT FROM 'OPENPC_CANONICAL_FACT_V1'
  OR (source).evidence_class IS DISTINCT FROM 'EFFECT'
  OR NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c
   WHERE c.participant_id=(source).participant_id AND c.privacy_domain_id=(source).privacy_domain_id
    AND c.stream_id=(source).stream_id AND c.record_id=(source).record_id
    AND c IS NOT DISTINCT FROM source) THEN RETURN NULL; END IF;
 SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
  WHERE p.stream_id=(source).stream_id AND p.record_id=(source).record_id;
 IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN RETURN NULL; END IF;
 original:=candidates->0;
 queue:=jsonb_build_array(jsonb_build_object('lineage',original,'path','[]'::jsonb));
 WHILE jsonb_array_length(queue)>0 AND steps<64 LOOP
  item:=queue->0; queue:=queue-0; lineage:=item->'lineage'; steps:=steps+1;
  IF item->'path' ? (lineage->>'factDigest') THEN unresolved:=true; CONTINUE; END IF;
  IF lineage->>'factDigest'=ANY(seen) THEN CONTINUE; END IF;
  seen:=array_append(seen,lineage->>'factDigest');
  projections:=projections||jsonb_build_array(lineage->>'projectionId');
  facts:=facts||jsonb_build_array(jsonb_build_object('factType',lineage->>'factType','factProfileId',lineage->>'factProfileId','factKeyDigest',lineage->>'factKeyDigest'));
  blocks:=blocks||jsonb_build_array(jsonb_build_object('chainId',lineage->>'chainId','genesisDigest',lineage->>'genesisDigest','blockNumber',lineage->>'blockNumber'));
  generations:=generations||jsonb_build_array(jsonb_build_object('kind','CANONICAL_FACT','factProfileId',lineage->>'factProfileId','canonicalGeneration',lineage->>'canonicalGeneration'));
  FOR reference IN SELECT value FROM jsonb_array_elements(jsonb_build_array(lineage->'predecessorDigest',lineage->'relationshipPredecessorDigest',lineage->'reorgReplacementOf')) WHERE value<>'null'::jsonb LOOP
   SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates
    FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
    WHERE p.lineage->'factDigest'=reference OR p.lineage->'factId'=reference;
   IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN unresolved:=true;
   -- Visit descendants before queued siblings. Breadth-first de-duplication can
   -- mark both ends of a shared-reference cycle seen before either back edge
   -- reaches its ancestor path, incorrectly reporting complete closure.
   ELSE queue:=jsonb_build_array(jsonb_build_object('lineage',candidates->0,'path',(item->'path')||jsonb_build_array(lineage->>'factDigest')))||queue; END IF;
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('projections',projections,'facts',facts,'blocks',blocks,
  'generations',jsonb_build_object('CANONICAL_FACT',generations),'unresolvedReferences',unresolved OR jsonb_array_length(queue)>0);
EXCEPTION WHEN insufficient_privilege THEN RETURN NULL;
END $$;


ALTER FUNCTION openpc.evidence_fact_hold_metadata(source control.evidence_catalogue) OWNER TO openpc_control_owner;

--
-- Name: evidence_fact_lineages(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_fact_lineages(participant uuid, privacy uuid) RETURNS TABLE(stream_id text, record_id text, lineage jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p.stream_id,p.record_id,p.projection->'lineage'
 FROM control.evidence_fact_provenance p JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
 WHERE p.participant_id=participant AND p.privacy_domain_id=privacy
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND p.projection->>'receiptDigest'=c.receipt_digest AND p.projection->>'sourceSequence'=c.sequence::text
  AND (p.projection->>'admittedAt')::timestamptz=c.occurred_at
  AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex')
 UNION ALL
 SELECT r.stream_id,r.record_id,r.preservation_metadata->'factLineage'
 FROM control.evidence_projection_retirement r JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
 JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
 WHERE r.participant_id=participant AND r.privacy_domain_id=privacy AND r.data_class='NORMALIZED_JSON_PROJECTION'
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND r.evidence_id=c.evidence_id AND r.source_receipt_digest=c.receipt_digest AND r.sequence=c.sequence AND r.segment_id=c.segment_id
  AND j.state='SUCCEEDED' AND j.selection->>'sourceKind'='FACT_PROVENANCE'
  AND j.selection->>'projectionDigest'=r.projection_digest AND j.selection->>'sourceReceiptDigest'=r.source_receipt_digest
  AND r.retirement_digest=openpc.projection_retirement_digest(r)
  AND jsonb_typeof(r.preservation_metadata->'factLineage')='object'
$$;


ALTER FUNCTION openpc.evidence_fact_lineages(participant uuid, privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_match_state(jsonb, uuid, uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_match_state(selector jsonb, participant uuid, privacy uuid, stream text, segment uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN bool_or(matched) THEN 'MATCH' WHEN count(*)=0 OR bool_or(matched IS NULL) THEN 'UNKNOWN' ELSE 'NON_MATCH' END
 FROM (SELECT CASE selector->>'type'
  WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
  WHEN 'SEQUENCE_RANGE' THEN selector->>'streamId'=c.stream_id AND c.sequence>=(selector->>'fromSequence')::numeric
   AND (selector->'throughSequence'='null'::jsonb OR c.sequence<=(selector->>'throughSequence')::numeric)
  WHEN 'DIGEST' THEN selector->>'recordDigest'=c.receipt_digest
  ELSE openpc.evidence_hold_source_match(selector,openpc.evidence_hold_record_metadata(c)) END matched
  FROM control.evidence_catalogue c WHERE c.participant_id=participant AND c.privacy_domain_id=privacy
   AND c.stream_id=stream AND c.segment_id=segment
  UNION ALL SELECT CASE selector->>'type'
   WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
   WHEN 'SEQUENCE_RANGE' THEN selector->>'streamId'=r.stream_id AND r.sequence>=(selector->>'fromSequence')::numeric
    AND (selector->'throughSequence'='null'::jsonb OR r.sequence<=(selector->>'throughSequence')::numeric)
   WHEN 'DIGEST' THEN selector->>'recordDigest'=r.source_receipt_digest
   ELSE openpc.evidence_hold_source_match(selector,r.preservation_metadata) END
  FROM control.evidence_projection_retirement r JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   WHERE r.participant_id=participant AND r.privacy_domain_id=privacy AND r.stream_id=stream AND r.segment_id=segment
    AND r.data_class='SEARCH_PROJECTION' AND j.state='SUCCEEDED'
    AND r.retirement_digest=openpc.projection_retirement_digest(r)) matches
$$;


ALTER FUNCTION openpc.evidence_hold_match_state(selector jsonb, participant uuid, privacy uuid, stream text, segment uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_matches(jsonb, uuid, uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_matches(selector jsonb, participant uuid, privacy uuid, stream text, segment uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT openpc.evidence_hold_match_state(selector,participant,privacy,stream,segment)<>'NON_MATCH'
$$;


ALTER FUNCTION openpc.evidence_hold_matches(selector jsonb, participant uuid, privacy uuid, stream text, segment uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_record_metadata(control.evidence_catalogue); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_record_metadata(source control.evidence_catalogue) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE metadata jsonb; binding record; occurrence jsonb; invalidation jsonb;
BEGIN
 IF (source).source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1' THEN
  IF EXISTS(SELECT 1 FROM control.authentication_occurrence a WHERE a.participant_id=(source).participant_id
   AND a.privacy_domain_id=(source).privacy_domain_id AND a.occurrence_id::text=(source).record_id
   AND (source).receipt_digest='sha256:'||encode(a.receipt_digest,'hex') AND a.receipt_digest=sha256(a.receipt)
   AND a.occurred_at=(source).occurred_at) THEN
   RETURN jsonb_build_object('projections','[]'::jsonb,'facts','[]'::jsonb,'blocks','[]'::jsonb,'generations',jsonb_build_object('RUNTIME_CONFIGURATION','[]'::jsonb,'CANONICAL_FACT','[]'::jsonb));
  END IF;
 ELSIF (source).evidence_class='BUSINESS_TRANSITION' THEN
  RETURN openpc.retention_policy_receipt_hold_metadata(source);
 ELSIF (source).source_format='OPENPC_CANONICAL_FACT_V1' THEN
  RETURN openpc.evidence_fact_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_CANDIDATE_PROJECTION_CHUNK_V1','OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1') THEN
  RETURN openpc.candidate_archive_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_RUNTIME_ARTIFACT_CHUNK_V1','OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1') THEN
  RETURN openpc.runtime_artifact_archive_hold_metadata(source);
 ELSIF (source).source_format='PC-DEPLOYMENT-JOURNAL-PROJECTION-1' THEN
  SELECT p.projection INTO metadata FROM control.evidence_deployment_lineage p
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT'
    AND p.projection=openpc.evidence_deployment_lineage_projection(source)
    AND p.projection->'historical'->>'receiptDigest'=(source).receipt_digest
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF NOT FOUND THEN RETURN NULL; END IF;
  occurrence:=metadata->'historical'->'occurrence';
  invalidation:=metadata->'historical'->'invalidation';
  IF invalidation<>'null'::jsonb THEN
   -- A reorg invalidates authority, not the preservation duty for its original
   -- block. Require one exact, previously verified occurrence reference.
   SELECT p.projection->'historical'->'occurrence' INTO STRICT occurrence
    FROM control.evidence_deployment_lineage p
    WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
     AND p.stream_id=(source).stream_id AND split_part(p.record_id,':',2)=split_part((source).record_id,':',2)
     AND (p.projection->'historical'->>'sourceVersion')::numeric<(metadata->'historical'->>'sourceVersion')::numeric
     AND p.projection->>'chainId'=metadata->>'chainId' AND p.projection->>'genesisDigest'=metadata->>'genesisDigest'
     AND p.projection->'historical'->'occurrence'->>'occurrenceId'=invalidation->>'occurrenceId'
     AND p.projection->'historical'->'occurrence'->>'occurrenceDigest'=invalidation->>'occurrenceDigest'
     AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex')
    GROUP BY p.projection->'historical'->'occurrence';
   IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  IF occurrence IS NULL OR occurrence='null'::jsonb THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('blocks',jsonb_build_array(jsonb_build_object('chainId',metadata->>'chainId',
   'genesisDigest',metadata->>'genesisDigest','blockNumber',occurrence->>'blockNumber')));
 ELSIF (source).source_format='OPENPC_RPC_DECISION_TRANSITION_V1' THEN
  SELECT r.preservation_metadata INTO metadata FROM control.evidence_projection_retirement r
   JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
    AND r.evidence_id=(source).evidence_id AND r.stream_id=(source).stream_id AND r.record_id=(source).record_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.source_receipt_digest=(source).receipt_digest
    AND r.retirement_digest=openpc.projection_retirement_digest(r) AND j.state='SUCCEEDED';
  IF FOUND THEN RETURN metadata; END IF;
  SELECT p.projection,g.projection_plan_id,g.runtime_configuration_generation_id INTO binding
   FROM control.evidence_rpc_provenance p JOIN control.runtime_configuration_generation g
    ON g.participant_id=p.participant_id AND g.privacy_domain_id=p.privacy_domain_id
     AND g.runtime_configuration_generation_id::text=p.projection->'activation'->>'generationId'
     AND g.generation_digest=p.projection->'activation'->>'generationDigest'
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT' AND p.projection->>'sourceDigest'=(source).receipt_digest
    AND p.projection->>'sourceSequence'=(source).sequence::text
    AND extract(epoch FROM (source).occurred_at)*1000000=floor((p.projection->>'occurredAtNs')::numeric/1000)
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF FOUND THEN
   RETURN jsonb_build_object('projections',jsonb_build_array('urn:openpc:resource:'||binding.projection_plan_id::text),
    'generations',jsonb_build_object('RUNTIME_CONFIGURATION',jsonb_build_array(jsonb_build_object('kind','RUNTIME_CONFIGURATION',
      'generationId','urn:openpc:resource:'||binding.runtime_configuration_generation_id::text))));
  END IF;
 END IF;
 RETURN NULL;
EXCEPTION WHEN insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN NULL;
END $$;


ALTER FUNCTION openpc.evidence_hold_record_metadata(source control.evidence_catalogue) OWNER TO openpc_control_owner;

--
-- Name: retention_hold; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.retention_hold (
    retention_hold_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    hold_kind text NOT NULL,
    selector_type text NOT NULL,
    selector jsonb NOT NULL,
    selector_cbor bytea NOT NULL,
    selector_digest text NOT NULL,
    state text DEFAULT 'ACTIVE'::text NOT NULL,
    approval_request_id uuid NOT NULL,
    release_approval_request_id uuid,
    creation_operation_id uuid NOT NULL,
    release_operation_id uuid,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    effective_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT retention_hold_kind_ck CHECK ((hold_kind = ANY (ARRAY['LEGAL'::text, 'REGULATORY'::text, 'INCIDENT'::text]))),
    CONSTRAINT retention_hold_selector_ck CHECK (((selector_type = ANY (ARRAY['PARTICIPANT'::text, 'PRIVACY_DOMAIN'::text, 'PROJECTION'::text, 'FACT_TYPE_KEY'::text, 'SEQUENCE_RANGE'::text, 'BLOCK_RANGE'::text, 'GENERATION'::text, 'DIGEST'::text])) AND ((selector ->> 'type'::text) = selector_type) AND ((octet_length(selector_cbor) >= 1) AND (octet_length(selector_cbor) <= 65536)) AND (selector_digest = ('sha256:'::text || encode(sha256(selector_cbor), 'hex'::text))))),
    CONSTRAINT retention_hold_state_ck CHECK ((((state = 'ACTIVE'::text) AND (revision = (1)::numeric) AND (release_operation_id IS NULL) AND (release_approval_request_id IS NULL)) OR ((state = 'RELEASED'::text) AND (revision = (2)::numeric) AND (release_operation_id IS NOT NULL) AND (release_approval_request_id IS NOT NULL))))
);

ALTER TABLE ONLY control.retention_hold FORCE ROW LEVEL SECURITY;


ALTER TABLE control.retention_hold OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_requires_coverage(control.retention_hold, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_requires_coverage(rule control.retention_hold, stream text, segment uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.evidence_segment s WHERE s.participant_id=(rule).participant_id
  AND ((rule).selector_type='PARTICIPANT' OR s.privacy_domain_id=(rule).privacy_domain_id)
  AND s.stream_id=stream AND s.segment_id=segment
  AND openpc.evidence_hold_matches((rule).selector,s.participant_id,s.privacy_domain_id,stream,segment)
  AND ((rule).state='ACTIVE' OR s.admitted_at<=(rule).updated_at))
$$;


ALTER FUNCTION openpc.evidence_hold_requires_coverage(rule control.retention_hold, stream text, segment uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_selector_encoding(jsonb, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_selector_encoding(selector jsonb, participant uuid, privacy uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE kind text:=selector->>'type'; expected jsonb:=jsonb_build_object('type',kind);
 encoded jsonb:=jsonb_build_object('0','pc.evidence.hold-selector.v1','1',openpc.business_uuid(participant),
 '2',openpc.business_uuid(privacy),'3',kind); first_value numeric; last_value numeric; generation jsonb;
 resource_pattern text:='^urn:openpc:resource:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
 profile_pattern text:=replace(resource_pattern,':resource:',':fact-profile:');
BEGIN
 IF participant IS NULL OR privacy IS NULL OR jsonb_typeof(selector) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF kind='SEQUENCE_RANGE' THEN
  IF coalesce(selector->>'streamId','')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
   OR coalesce(selector->>'fromSequence','')!~'^[1-9][0-9]{0,19}$' OR NOT(selector ? 'throughSequence') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromSequence')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'streamId','5',first_value,'6',CASE WHEN selector->'throughSequence'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughSequence'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughSequence','')!~'^[1-9][0-9]{0,19}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughSequence')::numeric; encoded:=encoded||jsonb_build_object('7',last_value);
  END IF;
  expected:=expected||jsonb_build_object('streamId',selector->>'streamId','fromSequence',first_value::text,'throughSequence',last_value::text);
 ELSIF kind='DIGEST' THEN
  IF coalesce(selector->>'recordDigest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('recordDigest',selector->>'recordDigest');
  encoded:=encoded||jsonb_build_object('4',openpc.business_bytes(decode(substring(selector->>'recordDigest' from 8),'hex')));
 ELSIF kind='PROJECTION' THEN
  IF coalesce(selector->>'projectionId','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('projectionId',selector->>'projectionId');
  encoded:=encoded||jsonb_build_object('4',openpc.business_uuid(right(selector->>'projectionId',36)::uuid));
 ELSIF kind='FACT_TYPE_KEY' THEN
  IF coalesce(selector->>'factType','') NOT IN ('CONTRACT_STATE_CALL','RELATIONSHIP','EXTERNAL_DECISION')
   OR coalesce(selector->>'factProfileId','')!~profile_pattern OR NOT(selector ? 'factKeyDigest')
   OR (selector->'factKeyDigest'<>'null'::jsonb AND coalesce(selector->>'factKeyDigest','')!~'^sha256:[0-9a-f]{64}$') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('factType',selector->>'factType','factProfileId',selector->>'factProfileId','factKeyDigest',selector->'factKeyDigest');
  encoded:=encoded||jsonb_build_object('4',selector->>'factType','5',selector->>'factProfileId','6',CASE WHEN selector->'factKeyDigest'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'factKeyDigest'<>'null'::jsonb THEN encoded:=encoded||jsonb_build_object('7',openpc.business_bytes(decode(substring(selector->>'factKeyDigest' from 8),'hex'))); END IF;
 ELSIF kind='BLOCK_RANGE' THEN
  IF coalesce(selector->>'chainId','')!~'^(0|[1-9][0-9]{0,77})$' OR (selector->>'chainId')::numeric>=power(2::numeric,256)
   OR coalesce(selector->>'genesisDigest','')!~'^sha256:[0-9a-f]{64}$'
   OR coalesce(selector->>'fromBlock','')!~'^(0|[1-9][0-9]{0,19})$' OR NOT(selector ? 'throughBlock') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromBlock')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'chainId','5',openpc.business_bytes(decode(substring(selector->>'genesisDigest' from 8),'hex')),
   '6',first_value,'7',CASE WHEN selector->'throughBlock'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughBlock'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughBlock','')!~'^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughBlock')::numeric; encoded:=encoded||jsonb_build_object('8',last_value);
  END IF;
  expected:=expected||jsonb_build_object('chainId',selector->>'chainId','genesisDigest',selector->>'genesisDigest','fromBlock',first_value::text,'throughBlock',last_value::text);
 ELSIF kind='GENERATION' THEN
  generation:=selector->'generation';
  IF generation->>'kind'='RUNTIME_CONFIGURATION' THEN
   IF coalesce(generation->>'generationId','')!~resource_pattern OR generation IS DISTINCT FROM jsonb_build_object('kind','RUNTIME_CONFIGURATION','generationId',generation->>'generationId') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','RUNTIME_CONFIGURATION','5',openpc.business_uuid(right(generation->>'generationId',36)::uuid));
  ELSIF generation->>'kind'='CANONICAL_FACT' THEN
   IF coalesce(generation->>'factProfileId','')!~profile_pattern OR coalesce(generation->>'canonicalGeneration','')!~'^[1-9][0-9]{0,19}$'
    OR (generation->>'canonicalGeneration')::numeric>18446744073709551615
    OR generation IS DISTINCT FROM jsonb_build_object('kind','CANONICAL_FACT','factProfileId',generation->>'factProfileId','canonicalGeneration',generation->>'canonicalGeneration') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','CANONICAL_FACT','5',generation->>'factProfileId','6',(generation->>'canonicalGeneration')::numeric);
  ELSE RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('generation',generation);
 ELSIF kind NOT IN ('PARTICIPANT','PRIVACY_DOMAIN') OR kind IS NULL THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF first_value>18446744073709551615 OR last_value>18446744073709551615 OR last_value<first_value
  OR selector IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 RETURN encoded;
END $_$;


ALTER FUNCTION openpc.evidence_hold_selector_encoding(selector jsonb, participant uuid, privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_source_match(jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_source_match(selector jsonb, metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE entries jsonb; dimension text; entry jsonb; check_selector jsonb; matched boolean;
BEGIN
 IF metadata ? 'unresolvedReferences' AND jsonb_typeof(metadata->'unresolvedReferences') IS DISTINCT FROM 'boolean' THEN RETURN NULL; END IF;
 dimension:=CASE selector->>'type' WHEN 'PROJECTION' THEN 'projections' WHEN 'FACT_TYPE_KEY' THEN 'facts'
  WHEN 'BLOCK_RANGE' THEN 'blocks' WHEN 'GENERATION' THEN 'generations' END;
 -- Generation namespaces have independent completeness. A known runtime UUID
 -- never proves that a record references no canonical Fact generation.
 entries:=CASE WHEN dimension='generations' THEN metadata->dimension->(selector->'generation'->>'kind') ELSE metadata->dimension END;
 IF dimension IS NULL OR jsonb_typeof(entries) IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
 -- Validate every source item before proving absence. A malformed sibling must
 -- not silently become a non-match, even when another item is well formed.
 FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
  IF dimension='projections' THEN
   check_selector:=jsonb_build_object('type','PROJECTION','projectionId',entry);
  ELSIF dimension='facts' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry->'factKeyDigest' IS NOT DISTINCT FROM 'null'::jsonb THEN RETURN NULL; END IF;
   check_selector:=entry||jsonb_build_object('type','FACT_TYPE_KEY');
  ELSIF dimension='blocks' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['chainId','genesisDigest','blockNumber']<>'{}'::jsonb THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','BLOCK_RANGE','chainId',entry->'chainId','genesisDigest',entry->'genesisDigest',
    'fromBlock',entry->'blockNumber','throughBlock',entry->'blockNumber');
  ELSE
   IF entry->>'kind' IS DISTINCT FROM selector->'generation'->>'kind' THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','GENERATION','generation',entry);
  END IF;
  BEGIN
   PERFORM openpc.evidence_hold_selector_encoding(check_selector,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid);
  EXCEPTION WHEN raise_exception OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
  END;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(entries) e WHERE
  (dimension='projections' AND e=selector->'projectionId')
  OR (dimension='facts' AND e->>'factType'=selector->>'factType' AND e->>'factProfileId'=selector->>'factProfileId'
   AND (selector->'factKeyDigest'='null'::jsonb OR e->>'factKeyDigest'=selector->>'factKeyDigest'))
  OR (dimension='blocks' AND e->>'chainId'=selector->>'chainId' AND e->>'genesisDigest'=selector->>'genesisDigest'
   AND (e->>'blockNumber')::numeric>=(selector->>'fromBlock')::numeric
   AND (selector->'throughBlock'='null'::jsonb OR (e->>'blockNumber')::numeric<=(selector->>'throughBlock')::numeric))
  OR (dimension='generations' AND e=selector->'generation')) INTO matched;
 -- A verified positive remains a preservation duty. Missing reference closure
 -- prevents a negative result from being used as permission to delete.
 IF NOT matched AND metadata->'unresolvedReferences'='true'::jsonb THEN RETURN NULL; END IF;
 RETURN matched;
END $$;


ALTER FUNCTION openpc.evidence_hold_source_match(selector jsonb, metadata jsonb) OWNER TO openpc_control_owner;

--
-- Name: evidence_hold_state_projection(control.retention_hold); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_hold_state_projection(rule control.retention_hold) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',(rule).hold_kind,
  '1',openpc.business_bytes(decode(substring((rule).selector_digest from 8),'hex')),'2',(rule).state,
  '3',openpc.business_uuid((rule).approval_request_id),'4',openpc.business_uuid((rule).creation_operation_id),
  '5',CASE WHEN (rule).release_approval_request_id IS NULL THEN openpc.business_bytes(''::bytea) ELSE openpc.business_uuid((rule).release_approval_request_id) END,
  '6',CASE WHEN (rule).release_operation_id IS NULL THEN openpc.business_bytes(''::bytea) ELSE openpc.business_uuid((rule).release_operation_id) END,
  '7',floor(extract(epoch from (rule).effective_at)*1000000)*1000,
  '8',floor(extract(epoch from (rule).updated_at)*1000000)*1000)
$$;


ALTER FUNCTION openpc.evidence_hold_state_projection(rule control.retention_hold) OWNER TO openpc_control_owner;

--
-- Name: evidence_kms_cose_binding(bytea, bytea, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_kms_cose_binding(payload bytea, cose bytea, family text, signer text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m jsonb; c jsonb; h jsonb; parsed jsonb; wanted_schema integer; wanted_purpose integer; wanted_digest text; wanted_fields integer;
BEGIN
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN wanted_schema:=24015; wanted_purpose:=352; wanted_digest:='0c1c466ce7dc697f151bfb0d574a8837d11ae52b6c94d7f454b29120546376fe'; wanted_fields:=28;
WHEN 'EvidenceWrappedKeyRecordV1' THEN wanted_schema:=24016; wanted_purpose:=353; wanted_digest:='b69bd016306d45d700e68aea1ce41225a774556df3070dbfea71d762cde3b700'; wanted_fields:=20;
WHEN 'EvidenceKmsReceiptV1' THEN wanted_schema:=24017; wanted_purpose:=354; wanted_digest:='2de3abbbc13222bd7473f0aa11d9dcbfb1bb9b538f0e426259d276c17b5d8ad2'; wanted_fields:=31;
 ELSE RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-FAMILY'; END CASE;
 IF octet_length(payload) NOT BETWEEN 1 AND 65536 OR octet_length(cose) NOT BETWEEN 1 AND 131072 OR get_byte(cose,0)<>210
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 parsed:=openpc.business_cbor_item(cose,1,0); c:=parsed->'value';
 IF (parsed->>'next')::integer<>octet_length(cose) OR jsonb_typeof(c) IS DISTINCT FROM 'array'
 OR jsonb_array_length(c)<>4 OR c->1 IS DISTINCT FROM '{}'::jsonb
 OR c->2 IS DISTINCT FROM jsonb_build_object('bytes',encode(payload,'hex'))
 OR length(c->3->>'bytes') IS DISTINCT FROM 128 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 h:=openpc.business_cbor(decode(c->0->>'bytes','hex'));
 IF h IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),'3','application/pc+cbor',
 '4',jsonb_build_object('bytes',encode(convert_to(signer,'UTF8'),'hex')),'100',wanted_schema,'101',1,'102',wanted_purpose,'103',2)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ROLE'; END IF;
 m:=openpc.business_cbor(payload);
 IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(m))<>wanted_fields
 OR m->'0' IS DISTINCT FROM jsonb_build_object('bytes',wanted_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-DEFINITION'; END IF;
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'profileId',(m->'4'->>'bytes')::uuid::text,'revision',m->>'5','producerTrustDigest','sha256:'||(m->'6'->>'bytes'),'owner',m->>'7','secretClass',m->>'8','providerId',m->>'9','reference',m->>'10','version',m->>'11','providerKeyId',m->>'12','providerKeyVersion',m->>'13','keyEpoch',m->>'14','wrapProfileDigest','sha256:'||(m->'15'->>'bytes'),'policyDigest','sha256:'||(m->'16'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'17'->>'bytes'),'providerOrigin',m->>'18','providerTlsSpkiDigest','sha256:'||(m->'19'->>'bytes'),'receiptKeyId','sha256:'||(m->'20'->>'bytes'),'recoveryKeyId','sha256:'||(m->'21'->>'bytes'),'permissions',m->>'22','kekExportPolicy',m->>'23','recoveryMode',m->>'24','validFromMs',m->>'25','validUntilMs',m->>'26','issuerKeyId','sha256:'||(m->'27'->>'bytes'));
WHEN 'EvidenceWrappedKeyRecordV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'attemptId',(m->'4'->>'bytes')::uuid::text,'originalRequestDigest','sha256:'||(m->'5'->>'bytes'),'objectIntentDigest','sha256:'||(m->'6'->>'bytes'),'profileDigest','sha256:'||(m->'7'->>'bytes'),'providerId',m->>'8','reference',m->>'9','version',m->>'10','providerKeyId',m->>'11','providerKeyVersion',m->>'12','keyEpoch',m->>'13','wrapProfileDigest','sha256:'||(m->'14'->>'bytes'),'policyDigest','sha256:'||(m->'15'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'16'->>'bytes'),'wrappedKey',m->'17'->>'bytes','createdAtMs',m->>'18','signerKeyId','sha256:'||(m->'19'->>'bytes'));
WHEN 'EvidenceKmsReceiptV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'profileDigest','sha256:'||(m->'5'->>'bytes'),'operation',m->>'6','attemptId',(m->'7'->>'bytes')::uuid::text,'exchangeId',(m->'8'->>'bytes')::uuid::text,'requestDigest','sha256:'||(m->'9'->>'bytes'),'challenge',m->'10'->>'bytes','objectIntentDigest','sha256:'||(m->'11'->>'bytes'),'keyId','sha256:'||(m->'12'->>'bytes'),'keyUse',m->>'13','providerId',m->>'14','reference',m->>'15','version',m->>'16','providerKeyId',m->>'17','providerKeyVersion',m->>'18','keyEpoch',m->>'19','wrapProfileDigest','sha256:'||(m->'20'->>'bytes'),'policyDigest','sha256:'||(m->'21'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'22'->>'bytes'),'outcome',m->>'23','keyState',m->>'24','providerSequence',m->>'25','recoveryFloor',m->>'26','materialDigest','sha256:'||(m->'27'->>'bytes'),'observedAtMs',m->>'28','validUntilMs',m->>'29','signerKeyId','sha256:'||(m->'30'->>'bytes'));
 END CASE;
END $$;


ALTER FUNCTION openpc.evidence_kms_cose_binding(payload bytea, cose bytea, family text, signer text) OWNER TO openpc_control_owner;

--
-- Name: evidence_kms_stored_outcome(bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.evidence_kms_stored_outcome(pack bytea) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p jsonb; m jsonb;
BEGIN
 p:=convert_from(pack,'UTF8')::jsonb;
 m:=openpc.business_cbor(decode(p->'receipt'->>'payloadHex','hex'));
 RETURN m->>'23';
END $$;


ALTER FUNCTION openpc.evidence_kms_stored_outcome(pack bytea) OWNER TO openpc_control_owner;

--
-- Name: expired_activation_state_digest(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_activation_state_digest(wanted uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'work',to_jsonb(w),'target',to_jsonb(t),'generation',to_jsonb(g),'observation',to_jsonb(o),
  'head',to_jsonb(a),'delivery',to_jsonb(d),'acknowledgement',to_jsonb(k))),'UTF8')),'hex')
 FROM control.configuration_work w
 JOIN control.runtime_target t USING(participant_id,privacy_domain_id,runtime_target_id)
 JOIN control.runtime_configuration_generation g ON g.participant_id=w.participant_id
  AND g.privacy_domain_id=w.privacy_domain_id AND g.runtime_configuration_generation_id=w.runtime_configuration_generation_id
 JOIN control.runtime_activation_observation o ON o.configuration_work_id=w.configuration_work_id
  AND o.participant_id=w.participant_id AND o.privacy_domain_id=w.privacy_domain_id
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=w.participant_id
  AND a.privacy_domain_id=w.privacy_domain_id AND a.runtime_target_id=w.runtime_target_id
  AND a.revision=(SELECT max(h.revision) FROM control.runtime_target_disposition_admission h
   WHERE h.participant_id=w.participant_id AND h.privacy_domain_id=w.privacy_domain_id AND h.runtime_target_id=w.runtime_target_id)
 JOIN control.runtime_target_disposition_delivery d ON d.participant_id=a.participant_id
  AND d.privacy_domain_id=a.privacy_domain_id AND d.runtime_target_id=a.runtime_target_id AND d.revision=a.revision
 JOIN control.runtime_target_disposition_acknowledgement k ON k.participant_id=d.participant_id
  AND k.privacy_domain_id=d.privacy_domain_id AND k.runtime_target_id=d.runtime_target_id AND k.delivery_digest=d.delivery_digest
 WHERE w.configuration_work_id=wanted AND w.participant_id=openpc.current_participant_id()
  AND w.privacy_domain_id=openpc.current_privacy_domain_id()
$$;


ALTER FUNCTION openpc.expired_activation_state_digest(wanted uuid) OWNER TO openpc_control_owner;

--
-- Name: expired_credential_denial_state_digest(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_credential_denial_state_digest(wanted_work uuid, certificate text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e control.runtime_expired_activation_denial;p record;original text;
BEGIN
 SELECT * INTO STRICT e FROM control.runtime_expired_activation_denial x
 WHERE x.configuration_work_id=wanted_work AND x.participant_id=openpc.current_participant_id()
  AND x.privacy_domain_id=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT p FROM openpc.expired_denial_credential_bootstrap(e.runtime_target_id,certificate);
 original:=openpc.expired_denial_handover_state_digest(wanted_work);
 IF original IS NULL THEN RAISE EXCEPTION 'EXPIRED-CREDENTIAL-DENIAL-STATE';END IF;
 RETURN 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
 'originalState',original,'credentialBinding',p.binding,'rotationOperationId',p.rotation_operation_id::text)),'UTF8')),'hex');
END
$$;


ALTER FUNCTION openpc.expired_credential_denial_state_digest(wanted_work uuid, certificate text) OWNER TO openpc_control_owner;

--
-- Name: expired_credential_handover_issuance_matches(uuid, bigint, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_credential_handover_issuance_matches(wanted_target uuid, wanted_revision bigint, wanted_digest text, wanted_worker text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE h control.runtime_expired_denial_handover;e control.runtime_expired_activation_denial;
 a control.runtime_target_disposition_admission;old control.runtime_target_disposition_admission;p record;
BEGIN
 SELECT * INTO h FROM control.runtime_expired_denial_handover x
 WHERE x.participant_id=openpc.current_participant_id() AND x.privacy_domain_id=openpc.current_privacy_domain_id()
  AND x.runtime_target_id=wanted_target AND x.admission_revision=wanted_revision AND x.admission_digest=wanted_digest;
 IF NOT FOUND OR h.proof->'intent'->>'purpose' IS DISTINCT FROM 'EXPIRED_OBSERVED_CREDENTIAL_DENIAL_HANDOVER_V1'
  OR h.proof->'intent'->'custody'->>'workerId' IS DISTINCT FROM wanted_worker
  OR (h.proof->'intent'->>'issuedAtMs')::numeric>extract(epoch from clock_timestamp())*1000
  OR (h.proof->'intent'->>'expiresAtMs')::numeric<=extract(epoch from clock_timestamp())*1000
 THEN RETURN false;END IF;
 SELECT * INTO STRICT e FROM control.runtime_expired_activation_denial x WHERE x.configuration_work_id=h.configuration_work_id
  AND x.participant_id=h.participant_id AND x.privacy_domain_id=h.privacy_domain_id AND x.runtime_target_id=h.runtime_target_id;
 SELECT * INTO STRICT old FROM control.runtime_target_disposition_admission x WHERE x.participant_id=e.participant_id
  AND x.privacy_domain_id=e.privacy_domain_id AND x.runtime_target_id=e.runtime_target_id AND x.revision=e.admission_revision;
 SELECT * INTO STRICT a FROM control.runtime_target_disposition_admission x WHERE x.participant_id=h.participant_id
  AND x.privacy_domain_id=h.privacy_domain_id AND x.runtime_target_id=h.runtime_target_id AND x.revision=h.admission_revision;
 IF h.abandoned_revision IS DISTINCT FROM e.admission_revision OR h.abandoned_admission_digest IS DISTINCT FROM e.admission_digest
  OR h.admission_revision IS DISTINCT FROM e.admission_revision+1 OR old.admission_digest IS DISTINCT FROM e.admission_digest
  OR a.admission_digest IS DISTINCT FROM h.admission_digest OR a.binding->>'action' IS DISTINCT FROM 'Withdraw'
  OR a.binding->'source' IS DISTINCT FROM old.binding->'source' OR a.binding->'target' IS DISTINCT FROM h.proof->'target'
  OR a.binding->'cause'->>'kind' IS DISTINCT FROM 'ExpiredObservedCredentialDenialHandover'
  OR a.binding->'cause'->'abandoned_target' IS DISTINCT FROM old.binding->'target'
  OR a.binding->'cause'->>'credential_rotation_operation_id' IS DISTINCT FROM h.proof->'intent'->'credentialTransition'->>'rotationOperationId'
  OR a.binding->'cause'->>'original_receipt_wire_digest' IS DISTINCT FROM e.proof->>'receiptWireDigest'
  OR a.revision IS DISTINCT FROM (SELECT max(x.revision)FROM control.runtime_target_disposition_admission x
   WHERE x.participant_id=a.participant_id AND x.privacy_domain_id=a.privacy_domain_id AND x.runtime_target_id=a.runtime_target_id)
 THEN RETURN false;END IF;
 SELECT * INTO STRICT p FROM openpc.expired_denial_credential_provenance(wanted_target,
  'sha256:'||(a.binding->'target'->>'certificate_digest'),(a.binding->'cause'->>'credential_rotation_operation_id')::uuid);
 RETURN p.binding->'target'=a.binding->'target' AND p.binding->'source'=a.binding->'source'
  AND p.binding->'credential_predecessor'=old.binding->'target';
END $$;


ALTER FUNCTION openpc.expired_credential_handover_issuance_matches(wanted_target uuid, wanted_revision bigint, wanted_digest text, wanted_worker text) OWNER TO openpc_control_owner;

--
-- Name: expired_denial_credential_bootstrap(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_denial_credential_bootstrap(wanted_target uuid, certificate text) RETURNS TABLE(binding jsonb, rotation_operation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    SET jit TO 'off'
    AS $$
DECLARE e control.runtime_expired_activation_denial;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT e FROM control.runtime_expired_activation_denial x WHERE x.participant_id=openpc.current_participant_id()
  AND x.privacy_domain_id=openpc.current_privacy_domain_id() AND x.runtime_target_id=wanted_target;
 IF e.admission_revision IS DISTINCT FROM (SELECT max(a.revision)FROM control.runtime_target_disposition_admission a
   WHERE a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id AND a.runtime_target_id=e.runtime_target_id)
  OR EXISTS(SELECT 1 FROM control.runtime_expired_denial_handover h WHERE h.configuration_work_id=e.configuration_work_id)
 THEN RAISE EXCEPTION 'EXPIRED-CREDENTIAL-DENIAL-HEAD';END IF;
 RETURN QUERY SELECT p.binding,p.rotation_operation_id FROM openpc.expired_denial_credential_provenance(wanted_target,certificate,NULL)p;
END $$;


ALTER FUNCTION openpc.expired_denial_credential_bootstrap(wanted_target uuid, certificate text) OWNER TO openpc_control_owner;

--
-- Name: expired_denial_credential_provenance(uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_denial_credential_provenance(wanted_target uuid, certificate text, wanted_rotation uuid DEFAULT NULL::uuid) RETURNS TABLE(binding jsonb, rotation_operation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    SET jit TO 'off'
    AS $$
DECLARE pid uuid;privacy uuid;authority record;current_credential control.credential;
 original_credential control.credential;e control.runtime_expired_activation_denial;
 a control.runtime_target_disposition_admission;p control.runtime_target_disposition_admission;
 d control.runtime_target_disposition_delivery;k control.runtime_target_disposition_acknowledgement;
 w control.configuration_work;t control.runtime_target;old_target jsonb;current_target jsonb;rotations uuid[];
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'EXPIRED-CREDENTIAL-DENIAL-CONTEXT';END IF;
 pid:=openpc.current_participant_id();privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(wanted_target,certificate);
 SELECT * INTO STRICT current_credential FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 SELECT * INTO STRICT e FROM control.runtime_expired_activation_denial x WHERE x.participant_id=pid
  AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target;
 SELECT * INTO STRICT w FROM control.configuration_work x WHERE x.participant_id=pid AND x.privacy_domain_id=privacy
  AND x.configuration_work_id=e.configuration_work_id AND x.runtime_target_id=wanted_target;
 SELECT * INTO STRICT t FROM control.runtime_target x WHERE x.participant_id=pid AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target;
 SELECT * INTO STRICT a FROM control.runtime_target_disposition_admission x WHERE x.participant_id=pid
  AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target AND x.revision=e.admission_revision;
 SELECT * INTO STRICT p FROM control.runtime_target_disposition_admission x WHERE x.participant_id=pid
  AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target AND x.revision=e.admission_revision-1;
 SELECT * INTO STRICT d FROM control.runtime_target_disposition_delivery x WHERE x.participant_id=pid
  AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target AND x.revision=p.revision;
 SELECT * INTO STRICT k FROM control.runtime_target_disposition_acknowledgement x WHERE x.participant_id=pid
  AND x.privacy_domain_id=privacy AND x.runtime_target_id=wanted_target AND x.delivery_digest=d.delivery_digest;
 old_target:=a.binding->'target';
 SELECT * INTO STRICT original_credential FROM control.credential c WHERE c.participant_id=pid
  AND c.credential_id=(old_target->>'credential_id')::uuid;
 current_target:=jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',wanted_target::text,
  'credential_id',current_credential.credential_id::text,'principal_id',current_credential.principal_id::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',substring(certificate from 8));
 IF w.state IS DISTINCT FROM 'RECONCILING' OR w.reconcile_after IS DISTINCT FROM 'infinity'::timestamptz
  OR w.work_kind IS DISTINCT FROM 'RUNTIME_ACTIVATION' OR w.execution_attempt_id IS DISTINCT FROM e.execution_attempt_id
  OR w.execution_started_at IS NULL OR w.lease_owner IS NOT NULL OR w.lease_until IS NOT NULL
  OR w.result_event_id IS NOT NULL OR w.completed_at IS NOT NULL
  OR t.state IS DISTINCT FROM 'STAGING' OR t.active_generation_digest IS DISTINCT FROM w.predecessor_digest
  OR t.desired_generation_digest IS DISTINCT FROM w.generation_digest
  OR a.admission_digest IS DISTINCT FROM e.admission_digest OR a.binding->>'action' IS DISTINCT FROM 'Withdraw'
  OR a.binding->'source' IS DISTINCT FROM e.proof->'source'
  OR a.binding->'cause' IS DISTINCT FROM jsonb_build_object('kind','Activation','work_id',w.configuration_work_id::text,
   'operation_id',w.operation_id::text,'execution_attempt_id',w.execution_attempt_id::text)
  OR old_target->>'participant_id' IS DISTINCT FROM pid::text OR old_target->>'privacy_domain_id' IS DISTINCT FROM privacy::text
  OR old_target->>'target_id' IS DISTINCT FROM wanted_target::text
  OR old_target->>'principal_id' IS DISTINCT FROM current_credential.principal_id::text
  OR old_target->'principal_epoch' IS DISTINCT FROM to_jsonb(authority.principal_epoch)
  OR (old_target->>'credential_epoch')::numeric+1 IS DISTINCT FROM authority.credential_epoch::numeric
  OR original_credential.state IS DISTINCT FROM 'REVOKED'
  OR original_credential.kind IS DISTINCT FROM 'WORKLOAD_MTLS'
  OR original_credential.principal_id IS DISTINCT FROM current_credential.principal_id
  OR original_credential.audience IS DISTINCT FROM current_credential.audience
  OR current_credential.rotated_from_credential_id IS DISTINCT FROM original_credential.credential_id
  OR original_credential.credential_epoch IS DISTINCT FROM current_credential.credential_epoch
  OR old_target->>'certificate_digest' IS DISTINCT FROM encode(original_credential.secret_fingerprint,'hex')
  OR original_credential.certificate_der IS NULL OR sha256(original_credential.certificate_der) IS DISTINCT FROM original_credential.secret_fingerprint
  OR current_target=old_target OR current_target->>'certificate_digest'=old_target->>'certificate_digest'
  OR a.binding->'previous_revision' IS DISTINCT FROM to_jsonb(p.revision)
  OR a.binding->>'previous_delivery_digest' IS DISTINCT FROM substring(d.delivery_digest from 8)
  OR p.binding->'target' IS DISTINCT FROM old_target OR p.binding->>'action' IS DISTINCT FROM 'Withdraw'
  OR p.binding->'cause' IS DISTINCT FROM jsonb_build_object('kind','Activation','work_id',w.configuration_work_id::text,
   'operation_id',w.operation_id::text,'execution_attempt_id',NULL)
  OR p.binding->'source'->>'capsule_digest' IS DISTINCT FROM substring(w.predecessor_digest from 8)
  OR a.binding->'source'->>'predecessor_capsule_digest' IS DISTINCT FROM p.binding->'source'->>'capsule_digest'
  OR d.claims IS DISTINCT FROM p.binding||jsonb_build_object('committed_admission_digest',substring(p.admission_digest from 8))
  OR d.delivery_digest IS DISTINCT FROM 'sha256:'||encode(sha256(d.signed_delivery),'hex')
  OR k.claims->'target' IS DISTINCT FROM old_target OR k.claims->>'installed_state' IS DISTINCT FROM 'NewUseDenied'
  OR k.claims->'disposition_revision' IS DISTINCT FROM to_jsonb(p.revision)
  OR k.acknowledgement_digest IS DISTINCT FROM 'sha256:'||encode(sha256(k.signed_acknowledgement),'hex')
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery x WHERE x.participant_id=pid AND x.privacy_domain_id=privacy
   AND x.runtime_target_id=wanted_target AND x.revision=e.admission_revision)
 THEN RAISE EXCEPTION 'EXPIRED-CREDENTIAL-DENIAL-ORIGINAL';END IF;
 SELECT array_agg(chosen_rotation.consumed_operation_id ORDER BY chosen_rotation.consumed_operation_id) INTO rotations
 FROM control.mutation_candidate chosen_rotation WHERE chosen_rotation.participant_id=pid AND chosen_rotation.privacy_domain_id=privacy
  AND chosen_rotation.resource_id=original_credential.credential_id AND chosen_rotation.state='CONSUMED'
  AND chosen_rotation.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'AND chosen_rotation.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND (wanted_rotation IS NULL OR chosen_rotation.consumed_operation_id=wanted_rotation)
  AND EXISTS (
    SELECT 1 FROM control.credential predecessor
    JOIN control.credential successor ON successor.participant_id=predecessor.participant_id
      AND successor.rotated_from_credential_id=predecessor.credential_id
      AND successor.principal_id=predecessor.principal_id AND successor.audience=predecessor.audience
    JOIN control.mutation_candidate candidate ON candidate.participant_id=predecessor.participant_id
      AND candidate.privacy_domain_id=privacy
      AND candidate.resource_id=predecessor.credential_id
      AND candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
      AND candidate.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
      AND candidate.state='CONSUMED' AND candidate.consumed_operation_id IS NOT NULL
      AND candidate.candidate_document=jsonb_build_object('replacedCredentialId',predecessor.credential_id::text,
        'credentialId',successor.credential_id::text,
        'publicKeySpkiDer',replace(encode(successor.public_key_spki_der,'base64'),E'\n',''))
      AND candidate.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(candidate.candidate_document),'UTF8'))
    JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id
      AND approval.privacy_domain_id=candidate.privacy_domain_id AND approval.subject_type='CONFIGURATION_CANDIDATE'
      AND approval.subject_id=candidate.mutation_candidate_id AND approval.subject_digest=candidate.candidate_digest
      AND approval.maker_principal_id=candidate.maker_principal_id AND approval.state='APPROVED'
      AND approval.subject_version=candidate.expected_revision AND approval.action_intent_id=candidate.action_intent_id
    JOIN control.approval_decision_record decision ON decision.participant_id=approval.participant_id
      AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
      AND decision.decision='APPROVE' AND decision.candidate_digest=candidate.candidate_digest
      AND decision.approver_principal_id<>approval.maker_principal_id AND decision.cose_sign1 IS NOT NULL
      AND decision.aggregate_version=approval.subject_version
    JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
      AND evidence.privacy_domain_id=candidate.privacy_domain_id AND evidence.operation_id=candidate.consumed_operation_id
      AND evidence.action_intent_id=candidate.action_intent_id AND evidence.catalog_operation_id=candidate.catalog_operation_id
      AND evidence.aggregate_type='workload-credential' AND evidence.aggregate_id=predecessor.credential_id
      AND evidence.candidate_digest=candidate.candidate_digest AND evidence.principal_id=approval.maker_principal_id
      AND evidence.checker_principal_id=decision.approver_principal_id AND evidence.approval_request_id=approval.approval_request_id
      AND evidence.evidence_digest=sha256(evidence.evidence_cbor) AND evidence.cose_sign1 IS NOT NULL
      AND evidence.evidence_cbor=decision.evidence_cbor AND evidence.cose_sign1=decision.cose_sign1
      AND evidence.signer_credential_id=decision.signer_credential_id
      AND evidence.webauthn_assertion_binding_digest IS NOT NULL AND evidence.mfa_challenge_id IS NOT NULL
    JOIN control.idempotency_record committed ON committed.participant_id=evidence.participant_id
      AND committed.privacy_domain_id=evidence.privacy_domain_id AND committed.operation_id=evidence.operation_id
      AND committed.action_intent_id=evidence.action_intent_id AND committed.catalog_operation_id=evidence.catalog_operation_id
      AND committed.principal_id=evidence.principal_id
      AND committed.terminal_state='COMMITTED' AND committed.input_digest=evidence.candidate_digest
      AND committed.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
      AND committed.result_payload->>'credentialId'=successor.credential_id::text
      AND committed.result_payload->>'replacedCredentialId'=predecessor.credential_id::text
      AND committed.result_payload->>'principalId'=successor.principal_id::text
      AND committed.result_payload->>'workloadId'=successor.audience
      AND committed.result_payload->>'workloadEpoch'=successor.credential_epoch::text
      AND committed.result_payload->>'state'='ACTIVE'
    JOIN control.outbox_event event ON event.participant_id=evidence.participant_id
      AND event.privacy_domain_id=evidence.privacy_domain_id AND event.aggregate_type=evidence.aggregate_type
      AND event.aggregate_id=evidence.aggregate_id AND event.payload_cbor=evidence.evidence_cbor
      AND event.event_type='openpc.identity.workload-credential.mutation.committed.v1'
      AND event.payload_digest=evidence.evidence_digest AND event.cose_sign1=evidence.cose_sign1
      AND event.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
    WHERE predecessor.participant_id=pid
      AND predecessor.credential_id=original_credential.credential_id AND successor.credential_id=current_credential.credential_id
      AND predecessor.kind='WORKLOAD_MTLS' AND predecessor.state='REVOKED'
      AND successor.kind='WORKLOAD_MTLS' AND successor.state='ACTIVE'
      AND predecessor.credential_epoch=(old_target->>'credential_epoch')::numeric+1
      AND successor.credential_epoch=predecessor.credential_epoch
      AND successor.credential_epoch=current_credential.credential_epoch
      AND successor.valid_from<=clock_timestamp() AND successor.valid_until>clock_timestamp()
      AND evidence.operation_id=chosen_rotation.consumed_operation_id
  );
 IF cardinality(rotations) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'EXPIRED-CREDENTIAL-DENIAL-ROTATION';END IF;
 RETURN QUERY SELECT jsonb_build_object('target',current_target,'source',a.binding->'source','credential_predecessor',old_target),rotations[1];
END $$;


ALTER FUNCTION openpc.expired_denial_credential_provenance(wanted_target uuid, certificate text, wanted_rotation uuid) OWNER TO openpc_control_owner;

--
-- Name: expired_denial_handover_state_digest(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_denial_handover_state_digest(wanted uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
 'originalDenial',to_jsonb(e),'work',to_jsonb(w),'target',to_jsonb(t),'generation',to_jsonb(g),
 'observation',to_jsonb(o),'abandoned',to_jsonb(a),'previous',to_jsonb(p),
 'previousDelivery',to_jsonb(d),'previousAcknowledgement',to_jsonb(k))),'UTF8')),'hex')
 FROM control.runtime_expired_activation_denial e
 JOIN control.configuration_work w USING(configuration_work_id,participant_id,privacy_domain_id,runtime_target_id,execution_attempt_id)
 JOIN control.runtime_target t USING(participant_id,privacy_domain_id,runtime_target_id)
 JOIN control.runtime_configuration_generation g ON g.participant_id=w.participant_id AND g.privacy_domain_id=w.privacy_domain_id
  AND g.runtime_configuration_generation_id=w.runtime_configuration_generation_id
 JOIN control.runtime_activation_observation o ON o.configuration_work_id=w.configuration_work_id
  AND o.participant_id=w.participant_id AND o.privacy_domain_id=w.privacy_domain_id
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
  AND a.runtime_target_id=e.runtime_target_id AND a.revision=e.admission_revision AND a.admission_digest=e.admission_digest
 JOIN control.runtime_target_disposition_admission p ON p.participant_id=a.participant_id AND p.privacy_domain_id=a.privacy_domain_id
  AND p.runtime_target_id=a.runtime_target_id AND p.revision=a.revision-1
 JOIN control.runtime_target_disposition_delivery d ON d.participant_id=p.participant_id AND d.privacy_domain_id=p.privacy_domain_id
  AND d.runtime_target_id=p.runtime_target_id AND d.revision=p.revision
 JOIN control.runtime_target_disposition_acknowledgement k ON k.participant_id=d.participant_id AND k.privacy_domain_id=d.privacy_domain_id
  AND k.runtime_target_id=d.runtime_target_id AND k.delivery_digest=d.delivery_digest
 WHERE e.configuration_work_id=wanted AND e.participant_id=openpc.current_participant_id()
  AND e.privacy_domain_id=openpc.current_privacy_domain_id()
  AND a.revision=(SELECT max(h.revision)FROM control.runtime_target_disposition_admission h
   WHERE h.participant_id=a.participant_id AND h.privacy_domain_id=a.privacy_domain_id AND h.runtime_target_id=a.runtime_target_id)
  AND NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery x WHERE x.participant_id=a.participant_id
   AND x.privacy_domain_id=a.privacy_domain_id AND x.runtime_target_id=a.runtime_target_id AND x.revision=a.revision)
  AND NOT EXISTS(SELECT 1 FROM control.runtime_expired_denial_handover h WHERE h.configuration_work_id=e.configuration_work_id)
$$;


ALTER FUNCTION openpc.expired_denial_handover_state_digest(wanted uuid) OWNER TO openpc_control_owner;

--
-- Name: expired_denial_issuance_matches(uuid, bigint, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_denial_issuance_matches(target uuid, revision bigint, digest text, worker text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT EXISTS(SELECT 1 FROM control.runtime_expired_activation_denial e
 JOIN control.configuration_work w USING(configuration_work_id,participant_id,privacy_domain_id,runtime_target_id,execution_attempt_id)
 JOIN control.runtime_activation_observation o USING(configuration_work_id,participant_id,privacy_domain_id,runtime_target_id,execution_attempt_id)
 JOIN control.runtime_target t USING(participant_id,privacy_domain_id,runtime_target_id)
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=e.participant_id
  AND a.privacy_domain_id=e.privacy_domain_id AND a.runtime_target_id=e.runtime_target_id AND a.revision=e.admission_revision
 WHERE e.participant_id=openpc.current_participant_id() AND e.privacy_domain_id=openpc.current_privacy_domain_id()
  AND e.runtime_target_id=$1 AND e.admission_revision=$2 AND e.admission_digest=$3
  AND e.proof->'intent'->'custody'->>'workerId'=$4
  AND (e.proof->'intent'->>'issuedAtMs')::numeric<=extract(epoch from clock_timestamp())*1000
  AND (e.proof->'intent'->>'expiresAtMs')::numeric>extract(epoch from clock_timestamp())*1000
  AND e.capsule_digest=o.capsule_digest AND e.execution_attempt_id=w.execution_attempt_id
  AND w.state='RECONCILING' AND w.reconcile_after='infinity'::timestamptz AND w.lease_owner IS NULL AND w.lease_until IS NULL
  AND w.result_event_id IS NULL AND w.completed_at IS NULL AND t.state='STAGING'
  AND t.active_generation_digest=w.predecessor_digest AND t.desired_generation_digest=w.generation_digest
  AND a.binding->>'action'='Withdraw' AND a.binding->'source'->>'original_work_id'=w.configuration_work_id::text
  AND a.binding->'source'->>'capsule_digest'=substring(e.capsule_digest from 8)
  AND a.binding->'cause'=jsonb_build_object('kind','Activation','work_id',w.configuration_work_id::text,
   'operation_id',w.operation_id::text,'execution_attempt_id',w.execution_attempt_id::text)
  AND a.revision=(SELECT max(h.revision) FROM control.runtime_target_disposition_admission h
   WHERE h.participant_id=e.participant_id AND h.privacy_domain_id=e.privacy_domain_id AND h.runtime_target_id=e.runtime_target_id))
$_$;


ALTER FUNCTION openpc.expired_denial_issuance_matches(target uuid, revision bigint, digest text, worker text) OWNER TO openpc_control_owner;

--
-- Name: expired_denial_terminal_replay(uuid, text, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_denial_terminal_replay(wanted uuid, intent_digest text, intent_bytes bytea) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT EXISTS(SELECT 1 FROM control.runtime_expired_activation_denial e
 LEFT JOIN control.runtime_expired_denial_handover h ON h.configuration_work_id=e.configuration_work_id
  AND h.participant_id=e.participant_id AND h.privacy_domain_id=e.privacy_domain_id AND h.runtime_target_id=e.runtime_target_id
 JOIN control.runtime_denied_predecessor c ON c.configuration_work_id=e.configuration_work_id AND c.participant_id=e.participant_id
  AND c.privacy_domain_id=e.privacy_domain_id AND c.runtime_target_id=e.runtime_target_id
 JOIN control.configuration_work w ON w.configuration_work_id=e.configuration_work_id AND w.participant_id=e.participant_id
  AND w.privacy_domain_id=e.privacy_domain_id AND w.runtime_target_id=e.runtime_target_id AND w.execution_attempt_id=e.execution_attempt_id
 JOIN control.runtime_activation_observation o ON o.configuration_work_id=w.configuration_work_id AND o.participant_id=w.participant_id
  AND o.privacy_domain_id=w.privacy_domain_id AND o.execution_attempt_id=w.execution_attempt_id
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
  AND a.runtime_target_id=e.runtime_target_id AND a.revision=coalesce(h.admission_revision,e.admission_revision)
 JOIN control.runtime_target_disposition_delivery d ON d.participant_id=a.participant_id AND d.privacy_domain_id=a.privacy_domain_id
  AND d.runtime_target_id=a.runtime_target_id AND d.revision=a.revision
 JOIN control.runtime_target_disposition_acknowledgement k ON k.participant_id=d.participant_id AND k.privacy_domain_id=d.privacy_domain_id
  AND k.runtime_target_id=d.runtime_target_id AND k.delivery_digest=d.delivery_digest
 JOIN control.outbox_event event ON event.event_id=w.result_event_id AND event.participant_id=w.participant_id
  AND event.privacy_domain_id=w.privacy_domain_id AND event.aggregate_id=w.runtime_target_id
 WHERE e.configuration_work_id=$1 AND e.participant_id=openpc.current_participant_id() AND e.privacy_domain_id=openpc.current_privacy_domain_id()
  AND coalesce(h.intent_digest,e.intent_digest)=$2 AND coalesce(h.intent_bytes,e.intent_bytes)=$3
  AND w.state='FAILED' AND w.completed_at IS NOT NULL AND w.result_event_id=c.result_event_id
  AND w.result_receipt->>'outcome'='EXPIRED_OBSERVED_DENIED'
  AND w.result_receipt->>'capsuleDigest'=c.capsule_digest AND c.capsule_digest=e.capsule_digest
  AND w.result_receipt->>'originalReceiptDigest'=o.activation_receipt_digest
  AND w.result_receipt->>'denialDeliveryDigest'=d.delivery_digest
  AND w.result_receipt->>'denialAcknowledgementDigest'='sha256:'||encode(sha256(k.signed_acknowledgement),'hex')
  AND w.result_receipt_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(w.result_receipt),'UTF8')),'hex')
  AND event.event_type='runtime-target.activation-expired-denied.v1'
  AND event.payload_cbor=convert_to(openpc.signing_canonical_json(w.result_receipt),'UTF8') AND event.payload_digest=sha256(event.payload_cbor)
  AND a.admission_digest=coalesce(h.admission_digest,e.admission_digest) AND a.binding->>'action'='Withdraw'
  AND c.denial_revision=a.revision AND c.delivery_digest=d.delivery_digest
  AND c.acknowledgement_digest='sha256:'||encode(sha256(k.signed_acknowledgement),'hex')
  AND d.delivery_digest='sha256:'||encode(sha256(d.signed_delivery),'hex')
  AND k.claims->>'installed_state'='NewUseDenied')
$_$;


ALTER FUNCTION openpc.expired_denial_terminal_replay(wanted uuid, intent_digest text, intent_bytes bytea) OWNER TO openpc_control_owner;

--
-- Name: expired_handover_issuance_matches(uuid, bigint, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_handover_issuance_matches(target uuid, revision bigint, digest text, worker text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT EXISTS(SELECT 1 FROM control.runtime_expired_denial_handover h
 JOIN control.runtime_expired_activation_denial e USING(configuration_work_id,participant_id,privacy_domain_id,runtime_target_id)
 JOIN control.configuration_work w ON w.configuration_work_id=e.configuration_work_id AND w.participant_id=e.participant_id
  AND w.privacy_domain_id=e.privacy_domain_id AND w.runtime_target_id=e.runtime_target_id
 JOIN control.runtime_target t ON t.participant_id=w.participant_id AND t.privacy_domain_id=w.privacy_domain_id AND t.runtime_target_id=w.runtime_target_id
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=h.participant_id AND a.privacy_domain_id=h.privacy_domain_id
  AND a.runtime_target_id=h.runtime_target_id AND a.revision=h.admission_revision
 JOIN control.runtime_target_disposition_admission abandoned ON abandoned.participant_id=e.participant_id AND abandoned.privacy_domain_id=e.privacy_domain_id
  AND abandoned.runtime_target_id=e.runtime_target_id AND abandoned.revision=e.admission_revision
 WHERE h.participant_id=openpc.current_participant_id() AND h.privacy_domain_id=openpc.current_privacy_domain_id()
  AND h.runtime_target_id=$1 AND h.admission_revision=$2 AND h.admission_digest=$3
  AND h.proof->'intent'->'custody'->>'workerId'=$4
  AND (h.proof->'intent'->>'issuedAtMs')::numeric<=extract(epoch from clock_timestamp())*1000
  AND (h.proof->'intent'->>'expiresAtMs')::numeric>extract(epoch from clock_timestamp())*1000
  AND h.abandoned_revision=e.admission_revision AND h.abandoned_admission_digest=e.admission_digest
  AND h.admission_revision=h.abandoned_revision+1 AND abandoned.admission_digest=e.admission_digest
  AND a.binding->'source'=abandoned.binding->'source' AND a.binding->'target'=abandoned.binding->'target'
  AND a.binding->>'action'='Withdraw' AND a.binding->'cause'->>'kind'='ExpiredObservedDenialHandover'
  AND a.binding->'cause'->>'original_receipt_wire_digest'=e.proof->>'receiptWireDigest'
  AND a.admission_digest=h.admission_digest AND w.execution_attempt_id=e.execution_attempt_id
  AND w.state='RECONCILING' AND w.reconcile_after='infinity'::timestamptz AND w.lease_owner IS NULL AND w.lease_until IS NULL
  AND w.result_event_id IS NULL AND w.completed_at IS NULL AND t.state='STAGING'
  AND t.active_generation_digest=w.predecessor_digest AND t.desired_generation_digest=w.generation_digest
  AND NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=e.participant_id
   AND d.privacy_domain_id=e.privacy_domain_id AND d.runtime_target_id=e.runtime_target_id AND d.revision=e.admission_revision)
  AND a.revision=(SELECT max(x.revision)FROM control.runtime_target_disposition_admission x WHERE x.participant_id=a.participant_id
   AND x.privacy_domain_id=a.privacy_domain_id AND x.runtime_target_id=a.runtime_target_id))
$_$;


ALTER FUNCTION openpc.expired_handover_issuance_matches(target uuid, revision bigint, digest text, worker text) OWNER TO openpc_control_owner;

--
-- Name: expired_operator_issuance_window_matches(uuid, bigint, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.expired_operator_issuance_window_matches(target uuid, revision bigint, digest text, worker text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM control.runtime_expired_activation_denial e
  WHERE e.participant_id=openpc.current_participant_id() AND e.privacy_domain_id=openpc.current_privacy_domain_id()
   AND e.runtime_target_id=$1 AND e.admission_revision=$2)
 THEN openpc.expired_denial_issuance_matches($1,$2,$3,$4)
 WHEN EXISTS(SELECT 1 FROM control.runtime_expired_denial_handover h
  WHERE h.participant_id=openpc.current_participant_id() AND h.privacy_domain_id=openpc.current_privacy_domain_id()
   AND h.runtime_target_id=$1 AND h.admission_revision=$2
   AND h.proof->'intent'->>'purpose'='EXPIRED_OBSERVED_CREDENTIAL_DENIAL_HANDOVER_V1')
 THEN openpc.expired_credential_handover_issuance_matches($1,$2,$3,$4)
 WHEN EXISTS(SELECT 1 FROM control.runtime_expired_denial_handover h
  WHERE h.participant_id=openpc.current_participant_id() AND h.privacy_domain_id=openpc.current_privacy_domain_id()
   AND h.runtime_target_id=$1 AND h.admission_revision=$2)
 THEN openpc.expired_handover_issuance_matches($1,$2,$3,$4) ELSE false END
$_$;


ALTER FUNCTION openpc.expired_operator_issuance_window_matches(target uuid, revision bigint, digest text, worker text) OWNER TO openpc_control_owner;

--
-- Name: fail_fleet_fact_delivery(bytea, bytea, bytea, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.fail_fleet_fact_delivery(material bytea, nonce bytea, mac bytea, wanted_profile text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE request jsonb; p uuid; v uuid; event uuid; lease uuid; result text; problem text; profile control.fact_consumer_profile;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_DELIVERY_FAIL_V1');
 p:=(request->>'participantId')::uuid; v:=(request->>'privacyDomainId')::uuid;
 event:=(request->>'eventId')::uuid; lease:=(request->>'leaseId')::uuid;
 result:=request->>'outcome'; problem:=request->>'problem';
 IF request IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',v::text,'eventId',event::text,'leaseId',lease::text,'outcome',result,'problem',problem)
  OR p IS DISTINCT FROM openpc.current_participant_id() OR v IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR result IS NULL OR problem IS NULL OR result NOT IN ('FAILED','CAPACITY_RELEASE','UNAVAILABLE_RELEASE') OR problem<>'PC-DATA-6005'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF profile.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.fleet_fact_delivery_attempt WHERE participant_id=p AND privacy_domain_id=v AND event_id=event
  AND lease_id=lease AND profile_digest=wanted_profile;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN openpc.close_fleet_delivery_lease(event,lease,result,problem);
END $$;


ALTER FUNCTION openpc.fail_fleet_fact_delivery(material bytea, nonce bytea, mac bytea, wanted_profile text) OWNER TO openpc_control_owner;

--
-- Name: fence_identity_envelope_recovery_issuer(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.fence_identity_envelope_recovery_issuer(p_recovery uuid, p_activation uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE recovery control.platform_recovery_case; enrollment control.identity_envelope_recovery_enrollment; epoch numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR openpc.current_operation_id() IS NULL THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery
  AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id);
 IF NOT FOUND OR recovery.signer_repair_enrollment_id IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 SELECT * INTO enrollment FROM openpc.lock_identity_envelope_recovery_enrollment(recovery.signer_repair_enrollment_id);
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery FOR UPDATE;
 IF enrollment.enrollment_id IS NULL OR recovery.state<>'REQUESTED' OR recovery.activated_at IS NOT NULL
  OR recovery.valid_from>clock_timestamp() OR recovery.valid_until<=clock_timestamp()
  OR recovery.intent_digest<>sha256(convert_to(openpc.signing_canonical_json(recovery.intent),'UTF8'))
  OR NOT coalesce(openpc.identity_envelope_recovery_proofs_current(recovery,p_activation),false)
  OR NOT openpc.identity_envelope_recovery_old_selection_current(enrollment.enrollment_id)
  OR recovery.intent->>'sourceIssuerPrincipalEpoch' IS DISTINCT FROM enrollment.document->>'issuerPrincipalEpoch'
  OR recovery.intent->>'sourceIssuerCredentialEpoch' IS DISTINCT FROM enrollment.document->>'issuerCredentialEpoch'
  OR recovery.intent->>'sourceParticipantEpoch' IS DISTINCT FROM enrollment.document->>'issuerParticipantEpoch'
  OR EXISTS(SELECT 1 FROM control.platform_recovery_case prior JOIN control.identity_envelope_recovery_enrollment original
    ON original.enrollment_id=prior.signer_repair_enrollment_id AND original.participant_id=prior.participant_id
    WHERE prior.participant_id=recovery.participant_id AND original.document->>'issuerPrincipalId'=enrollment.document->>'issuerPrincipalId'
     AND prior.recovery_id<>recovery.recovery_id AND prior.activated_at IS NOT NULL AND prior.reviewed_at IS NULL)
  OR EXISTS(SELECT 1 FROM control.signing_key_rotation rotation WHERE rotation.participant_id=enrollment.participant_id
    AND rotation.privacy_domain_id=enrollment.privacy_domain_id AND rotation.environment_id=enrollment.document#>>'{request,environmentId}'
    AND rotation.workload_credential_id::text=enrollment.document#>>'{request,workloadCredentialId}' AND rotation.state<>'COMPLETE')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.credential credential JOIN control.principal issuer
  ON issuer.participant_id=credential.participant_id AND issuer.principal_id=credential.principal_id
  JOIN control.participant participant ON participant.participant_id=issuer.participant_id
  WHERE credential.participant_id=enrollment.participant_id AND credential.credential_id::text=enrollment.document#>>'{request,workloadCredentialId}'
   AND issuer.principal_id::text=enrollment.document->>'issuerPrincipalId' AND issuer.kind='WORKLOAD' AND issuer.state='ACTIVE'
   AND issuer.authority_epoch::text=enrollment.document->>'issuerPrincipalEpoch'
   AND participant.state='ACTIVE' AND participant.authority_epoch::text=enrollment.document->>'issuerParticipantEpoch'
   AND credential.kind='WORKLOAD_MTLS' AND credential.state='ACTIVE' AND credential.credential_epoch::text=enrollment.document->>'issuerCredentialEpoch'
   AND 'sha256:'||encode(credential.public_key_digest,'hex')=enrollment.document->>'issuerCredentialPublicKeyDigest'
   AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  FOR UPDATE OF issuer FOR SHARE OF credential;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 UPDATE control.principal SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE participant_id=enrollment.participant_id AND principal_id::text=enrollment.document->>'issuerPrincipalId'
   AND state='ACTIVE' AND authority_epoch=(enrollment.document->>'issuerPrincipalEpoch')::numeric RETURNING authority_epoch INTO epoch;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 UPDATE control.session SET state='REVOKED',revoked_at=clock_timestamp(),revoked_reason='identity-envelope-signer-recovery',
  session_epoch=session_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE participant_id=enrollment.participant_id AND principal_id::text=enrollment.document->>'issuerPrincipalId'
   AND state IN ('ACTIVE','STEP_UP_REQUIRED');
 RETURN epoch;
END $$;


ALTER FUNCTION openpc.fence_identity_envelope_recovery_issuer(p_recovery uuid, p_activation uuid) OWNER TO openpc_control_owner;

--
-- Name: fence_native_value_reservation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.fence_native_value_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE admitted boolean:=false; wallet_id uuid; actor_id uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-NATIVE-VALUE-CUSTODY';
 END IF;
 IF NEW.native_value_authorization_id IS NULL AND NEW.native_value_authorization_digest IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.state='EXPIRED' THEN RETURN NEW; END IF;
 SELECT wallet_binding_id,actor_principal_id INTO STRICT wallet_id,actor_id FROM control.native_value_authorization
 WHERE native_value_authorization_id=NEW.native_value_authorization_id;
 PERFORM openpc.lock_native_value_authority(wallet_id,actor_id);
 SELECT true INTO admitted FROM control.native_value_authorization issued_grant
 JOIN control.deployment_intent preparation ON preparation.participant_id=issued_grant.participant_id
  AND preparation.privacy_domain_id=issued_grant.privacy_domain_id AND preparation.preparation_digest=NEW.prepared_record_digest
  AND preparation.intent_digest=NEW.intent_digest AND preparation.wallet_binding_id=issued_grant.wallet_binding_id
  AND coalesce(preparation.execution_principal_id,preparation.actor_principal_id)=issued_grant.actor_principal_id
  AND preparation.execution_workload_id IS NOT DISTINCT FROM issued_grant.execution_workload_id
 JOIN control.mutation_candidate submission ON submission.participant_id=issued_grant.participant_id
  AND submission.privacy_domain_id=issued_grant.privacy_domain_id AND submission.resource_id=NEW.attempt_id
  AND submission.consumed_operation_id=NEW.command_id AND submission.maker_principal_id=preparation.actor_principal_id
  AND submission.state='CONSUMED' AND submission.catalog_operation_id='CFG-OP-SUBMIT-DEPLOYMENT'
  AND submission.action_intent_id='ACT-DEPLOYMENT_SUBMISSIONS_CREATE_RESOURCE-V1'
  AND submission.candidate_document->>'deploymentIntentId'='urn:openpc:resource:'||preparation.deployment_intent_id::text
 JOIN control.idempotency_record receipt ON receipt.participant_id=submission.participant_id
  AND receipt.privacy_domain_id=submission.privacy_domain_id AND receipt.operation_id=submission.consumed_operation_id
  AND receipt.catalog_operation_id=submission.catalog_operation_id AND receipt.input_digest=submission.candidate_digest
  AND receipt.principal_id=submission.maker_principal_id AND receipt.terminal_state='COMMITTED'
 JOIN control.mutation_evidence evidence ON evidence.participant_id=submission.participant_id
  AND evidence.privacy_domain_id=submission.privacy_domain_id AND evidence.operation_id=submission.consumed_operation_id
  AND evidence.catalog_operation_id=submission.catalog_operation_id AND evidence.candidate_digest=submission.candidate_digest
  AND evidence.aggregate_id=submission.resource_id AND evidence.aggregate_type='deployment-submission'
 CROSS JOIN LATERAL (SELECT convert_from(preparation.preparation_bytes,'UTF8')::jsonb AS prepared,
  convert_from(issued_grant.document_bytes,'UTF8')::jsonb AS document) exact
 JOIN control.wallet_binding wallet ON wallet.participant_id=issued_grant.participant_id
  AND wallet.privacy_domain_id=issued_grant.privacy_domain_id AND wallet.wallet_binding_id=issued_grant.wallet_binding_id
  AND wallet.binding_epoch=issued_grant.wallet_binding_epoch AND wallet.subject_id=issued_grant.actor_principal_id
  AND wallet.state='ACTIVE' AND wallet.chain_id::text=NEW.chain_id AND wallet.wallet_address=NEW.sender_address
 JOIN control.participant participant ON participant.participant_id=issued_grant.participant_id
  AND participant.state='ACTIVE' AND participant.authority_epoch=(exact.document->>'participantEpoch')::numeric
 JOIN control.principal principal ON principal.participant_id=issued_grant.participant_id
  AND principal.principal_id=issued_grant.actor_principal_id AND principal.state='ACTIVE'
 WHERE issued_grant.native_value_authorization_id=NEW.native_value_authorization_id
  AND issued_grant.participant_id=NEW.participant_id AND issued_grant.privacy_domain_id=NEW.privacy_domain_id
  AND issued_grant.semantic_digest=NEW.native_value_authorization_digest
  AND issued_grant.valid_until>clock_timestamp() AND issued_grant.valid_until>=NEW.expires_at
  AND 'urn:openpc:resource:'||preparation.runtime_target_id::text=NEW.target_runtime_id AND preparation.expires_at>=NEW.expires_at
  AND exact.prepared->'context'->>'nativeValueAuthorizationBytes'='0x'||encode(issued_grant.document_bytes,'hex')
  AND exact.prepared->'context'->>'participantEpoch'=exact.document->>'participantEpoch'
  AND exact.prepared->'context'->>'walletBindingEpoch'=issued_grant.wallet_binding_epoch::text
  AND exact.prepared->'context'->>'chainEnvironmentId'=exact.document->>'chainEnvironmentId'
  AND exact.prepared->'intent'->>'nativeValueAuthorizationDigest'=substring(issued_grant.semantic_digest,8)
  AND exact.prepared->'intent'->>'chainId'=NEW.chain_id AND exact.document->>'chainId'=NEW.chain_id
  AND exact.document->>'genesisHash'=substring(NEW.genesis_digest,8)
  AND exact.prepared->'intent'->>'valueWei' ~ '^[1-9][0-9]{0,77}$'
  AND (exact.prepared->'intent'->>'valueWei')::numeric<2::numeric^256
  AND ((exact.document->>'amountMode'='EXACT' AND exact.document->>'maxAmountWei'=exact.prepared->'intent'->>'valueWei')
   OR (exact.document->>'amountMode'='MAXIMUM' AND (exact.prepared->'intent'->>'valueWei')::numeric<=(exact.document->>'maxAmountWei')::numeric))
  AND (issued_grant.execution_workload_id IS NULL OR EXISTS(SELECT 1 FROM control.credential credential
   WHERE credential.participant_id=principal.participant_id AND credential.principal_id=principal.principal_id
    AND principal.kind='WORKLOAD' AND credential.kind='WORKLOAD_MTLS' AND credential.audience=issued_grant.execution_workload_id
    AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND credential.valid_until>clock_timestamp()));
 IF admitted IS DISTINCT FROM true THEN RAISE EXCEPTION 'PC-AUTH-0002-NATIVE-VALUE-CUSTODY'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.fence_native_value_reservation() OWNER TO openpc_control_owner;

--
-- Name: fleet_delivery_retry_delay(integer, integer, integer); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.fleet_delivery_retry_delay(failures integer, initial_ms integer, maximum_ms integer) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT least(maximum_ms::bigint,initial_ms::bigint*(1::bigint<<least(greatest(failures-1,0),32)))
$$;


ALTER FUNCTION openpc.fleet_delivery_retry_delay(failures integer, initial_ms integer, maximum_ms integer) OWNER TO openpc_control_owner;

--
-- Name: guard_abi_artifact_registration(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_abi_artifact_registration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected text;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'abi_artifact' OR TG_OP NOT IN ('INSERT','UPDATE')
 THEN RAISE EXCEPTION 'DATA-6004-CONTRACT-REGISTRATION-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'DATA-6001-CONTEXT-INVALID'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.participant_id IS DISTINCT FROM OLD.participant_id OR NEW.privacy_domain_id IS DISTINCT FROM OLD.privacy_domain_id
    OR NEW.policy_generation_digest IS DISTINCT FROM OLD.policy_generation_digest
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-IMMUTABLE'; END IF;
 ELSE
  expected:=openpc.configuration_policy_provenance(NEW.participant_id,NEW.privacy_domain_id);
  IF NEW.policy_generation_digest IS DISTINCT FROM expected
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-PROVENANCE'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_abi_artifact_registration() OWNER TO openpc_control_owner;

--
-- Name: guard_archive_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_archive_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_owner','MEMBER')
  AND NOT pg_has_role(current_user,'openpc_control_key_governor','MEMBER')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_archive_installation() OWNER TO openpc_control_owner;

--
-- Name: guard_archive_outbox(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_archive_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt control.evidence_archive_receipt; actual jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 SELECT * INTO STRICT receipt FROM control.evidence_archive_receipt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 actual:=openpc.business_cbor(NEW.event);
 IF actual IS DISTINCT FROM jsonb_build_object('0','pc.evidence.remote-custody.v1',
  '1',openpc.business_uuid(receipt.participant_id),'2',openpc.business_uuid(receipt.privacy_domain_id),
  '3',openpc.business_uuid(receipt.receipt_id),'4',openpc.business_bytes(decode(substring(receipt.receipt_digest from 8),'hex')),
  '5',openpc.business_bytes(decode(substring(receipt.profile_digest from 8),'hex')),'6',openpc.business_uuid(receipt.attempt_id))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_archive_outbox() OWNER TO openpc_control_owner;

--
-- Name: guard_archive_profile(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_archive_profile() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t control.evidence_archive_trust; c jsonb; expected jsonb; actual jsonb; streams jsonb; protected_profile boolean;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT t FROM control.evidence_archive_trust WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND environment_id=NEW.environment_id AND sink_id=NEW.sink_id
  AND issuer_key_id=NEW.issuer_key_id;
 c:=NEW.claims; protected_profile:=c ? 'sourceKind';
 expected:=jsonb_build_object('environmentId',t.environment_id,'participantId',t.participant_id::text,
  'privacyDomainId',t.privacy_domain_id::text,'profileId',NEW.profile_id,'sinkId',t.sink_id,'revision',NEW.revision::text,
  'validFromMs',c->'validFromMs','validUntilMs',c->'validUntilMs','transportProfileDigest',NEW.transport_digest,
  'receiptSignerSpki',c->'receiptSignerSpki','streamIds',c->'streamIds','issuerKeyId',t.issuer_key_id,
  'workloadCredentialId',t.workload_credential_id::text,'workloadCredentialEpoch',t.workload_credential_epoch::text,
  'databaseRole',t.database_role);
 IF protected_profile THEN expected:=expected||jsonb_build_object('sourceKind','PROTECTED_PROOF','retentionPolicy','SOURCE_DEADLINE_EXACT','heldExpiredPolicy','PRESERVE_EXISTING_ONLY'); END IF;
 IF c IS DISTINCT FROM expected OR jsonb_typeof(c->'streamIds') IS DISTINCT FROM 'array'
  OR jsonb_array_length(c->'streamIds') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(c->'validFromMs') IS DISTINCT FROM 'number'
  OR jsonb_typeof(c->'validUntilMs') IS DISTINCT FROM 'number'
  OR coalesce(c->>'validFromMs','')!~'^[0-9]+$' OR coalesce(c->>'validUntilMs','')!~'^[0-9]+$'
  OR (c->>'validFromMs')::numeric<t.valid_from_ms OR (c->>'validUntilMs')::numeric>t.valid_until_ms
  OR (c->>'validFromMs')::numeric>=(c->>'validUntilMs')::numeric
  OR coalesce(c->>'receiptSignerSpki','')!~'^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
  OR sha256(decode(c->>'receiptSignerSpki','hex'))=sha256(t.issuer_spki)
  OR NEW.transport_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.transport),'UTF8')),'hex')
  OR NEW.transport->>'sinkId' IS DISTINCT FROM t.sink_id OR NEW.transport->>'profileId' IS DISTINCT FROM NEW.profile_id
  OR NEW.revision IS DISTINCT FROM (SELECT coalesce(max(revision),0)+1 FROM control.evidence_archive_profile
   WHERE participant_id=t.participant_id AND privacy_domain_id=t.privacy_domain_id AND environment_id=t.environment_id AND sink_id=t.sink_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT jsonb_agg(v ORDER BY convert_to(v#>>'{}','UTF8')) INTO streams
  FROM (SELECT DISTINCT value v FROM jsonb_array_elements(c->'streamIds')) items;
 IF streams IS DISTINCT FROM c->'streamIds' OR EXISTS(SELECT 1 FROM jsonb_array_elements(streams) v
  WHERE jsonb_typeof(v)<>'string' OR (v#>>'{}')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 actual:=openpc.business_cbor(NEW.payload);
 expected:=jsonb_build_object('0',openpc.business_bytes(decode(CASE WHEN protected_profile THEN '2c3a4bb5fdb78858baea6f1ce7074512933880ae2ef6b47e397d852c1ad85fc1' ELSE '86dcf0707192cc456b41e8bf114abebc21180232256159490d74e5db151ac7d3' END,'hex')),
  '1',t.environment_id,'2',openpc.business_uuid(t.participant_id),'3',openpc.business_uuid(t.privacy_domain_id),
  '4',NEW.profile_id,'5',t.sink_id,'6',NEW.revision,'7',(c->>'validFromMs')::numeric,'8',(c->>'validUntilMs')::numeric,
  '9',openpc.business_bytes(decode(substring(NEW.transport_digest from 8),'hex')),
  '10',openpc.business_bytes(decode(c->>'receiptSignerSpki','hex')),'11',streams,
  '12',openpc.business_bytes(decode(substring(t.issuer_key_id from 8),'hex')),
  '13',openpc.business_uuid(t.workload_credential_id),'14',t.workload_credential_epoch,'15',t.database_role);
 IF protected_profile THEN expected:=expected||jsonb_build_object('16',1,'17',1,'18',1); END IF;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(NEW.payload,NEW.cose,t.issuer_key_id,CASE WHEN protected_profile THEN 24004 ELSE 24002 END,CASE WHEN protected_profile THEN 341 ELSE 339 END);
 NEW.admitted_at:=clock_timestamp(); RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_archive_profile() OWNER TO openpc_control_owner;

--
-- Name: guard_archive_receipt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_archive_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p control.evidence_archive_profile; a control.evidence_remote_archive_attempt; i control.evidence_remote_archive_intent;
 s control.evidence_segment; previous control.evidence_archive_receipt; actual jsonb; expected jsonb; recorded numeric; signer text; facts jsonb; object jsonb; protected_source boolean;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT a FROM control.evidence_remote_archive_attempt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id AND intent_id=NEW.intent_id AND state='OBSERVED';
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND intent_id=a.intent_id;
 p:=openpc.require_archive_profile(NEW.profile_digest,i.stream_id);
 protected_source:=i.source_kind='PROTECTED_PROOF';
 IF coalesce(p.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM i.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF protected_source THEN
  facts:=openpc.protected_remote_archive_source(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id,i.intent_id);
  IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'object' IS DISTINCT FROM i.intent->'source'->'object'
   OR facts->'lineage'->>'streamId' IS DISTINCT FROM i.stream_id
   OR (a.observation->'observedRetention'->>'retainUntil')::timestamptz IS DISTINCT FROM (facts->'object'->>'retainUntil')::timestamptz
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object:=facts->'object';
 ELSE
  SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
   AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
 END IF;
 recorded:=floor(extract(epoch FROM NEW.recorded_at)*1000000);
 signer:='sha256:'||encode(sha256(decode(p.claims->>'receiptSignerSpki','hex')),'hex');
 IF i.profile_digest<>p.transport_digest OR i.profile IS DISTINCT FROM p.transport OR i.sink_id<>p.sink_id
  OR p.participant_id<>NEW.participant_id OR p.privacy_domain_id<>NEW.privacy_domain_id
  OR recorded<(p.claims->>'validFromMs')::numeric*1000 OR recorded>=(p.claims->>'validUntilMs')::numeric*1000
  OR NEW.recorded_at<a.updated_at
  OR NEW.recorded_at>clock_timestamp() OR NEW.recorded_at<clock_timestamp()-interval '30 seconds'
  OR NEW.receipt_id::text!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO previous FROM control.evidence_archive_receipt prior WHERE prior.participant_id=i.participant_id
  AND prior.privacy_domain_id=i.privacy_domain_id AND prior.intent_id=i.intent_id
  ORDER BY (openpc.business_cbor(prior.payload)->>'13')::numeric DESC LIMIT 1;
 IF (a.action='PUT' AND (previous.receipt_id IS NOT NULL OR NEW.previous_receipt_digest IS NOT NULL))
  OR (a.action='PROTECTION' AND (previous.receipt_id IS NULL OR NEW.previous_receipt_digest IS DISTINCT FROM previous.receipt_digest
   OR (openpc.business_cbor(previous.payload)->>'13')::numeric>=(a.binding->'protection'->>'revision')::numeric))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 actual:=openpc.business_cbor(NEW.payload);
 expected:=jsonb_build_object('0',openpc.business_bytes(decode(CASE WHEN protected_source THEN 'd935f1479b41f87578a183d4cd7024371faae089e338f2abf1aa2c39a4b4445b' ELSE '6f1409ec49a98e1416adccd37517e0ed9b402b0e673f398cef40878bb8ea65fc' END,'hex')),
  '1',p.environment_id,'2',openpc.business_uuid(i.participant_id),'3',openpc.business_uuid(i.privacy_domain_id),
  '4',openpc.business_uuid(NEW.receipt_id),'5',openpc.business_uuid(i.intent_id),'6',openpc.business_uuid(a.attempt_id),
  '7',openpc.business_bytes(decode(substring(p.profile_digest from 8),'hex')),
  '8',openpc.business_bytes(decode(substring(a.observation_digest from 8),'hex')),
  '9',openpc.business_bytes(decode(substring(a.binding_digest from 8),'hex')),
  '10',openpc.business_bytes(decode(substring(CASE WHEN protected_source THEN object->>'objectDigest' ELSE s.object_digest END from 8),'hex')),
  '11',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(a.observation->'locator'),'UTF8'))),
  '12',openpc.business_bytes(decode(substring(a.protection_digest from 8),'hex')),
  '13',(a.binding->'protection'->>'revision')::numeric,
  '14',floor(extract(epoch FROM (a.observation->'observedRetention'->>'retainUntil')::timestamptz)*1000000),
  '15',recorded,'16',openpc.business_bytes(coalesce(decode(substring(NEW.previous_receipt_digest from 8),'hex'),''::bytea)),
  '17',CASE a.action WHEN 'PUT' THEN 1 ELSE 2 END,'18',openpc.business_bytes(decode(substring(signer from 8),'hex')),
  '19',i.stream_id,'22',1,'23',0);
 IF protected_source THEN
  expected:=expected||jsonb_build_object('20',openpc.business_uuid(i.protected_object_id),'21',i.protected_object_version,
   '24',openpc.business_bytes(decode(substring(object->>'payloadDigest' from 8),'hex')),
   '25',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(object->'source'),'UTF8'))),
   '26',floor(extract(epoch FROM (object->>'retainUntil')::timestamptz)*1000000));
 ELSE expected:=expected||jsonb_build_object('20',openpc.business_uuid(i.segment_id),'21',s.through_sequence); END IF;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(NEW.payload,NEW.cose,signer,CASE WHEN protected_source THEN 24005 ELSE 24003 END,CASE WHEN protected_source THEN 342 ELSE 340 END);
 PERFORM openpc.consume_archive_commit(p,a,NEW);
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_archive_receipt() OWNER TO openpc_control_owner;

--
-- Name: guard_archive_trust(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_archive_trust() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF NEW.environment_id!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR NEW.sink_id!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR EXISTS(SELECT 1 FROM control.evidence_checkpoint c WHERE c.participant_id=NEW.participant_id
   AND c.privacy_domain_id=NEW.privacy_domain_id AND c.sink_id=NEW.sink_id)
  OR encode(substring(NEW.issuer_spki from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
   AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole
   AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
   AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER')
   AND NOT pg_has_role(r.oid,'openpc_control_key_governor','MEMBER'))
  OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
   WHERE c.participant_id=NEW.participant_id AND c.credential_id=NEW.workload_credential_id
    AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC') AND w.kind='WORKLOAD'
    AND c.state='ACTIVE' AND w.state='ACTIVE' AND c.credential_epoch=NEW.workload_credential_epoch
    AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
    AND c.public_key_digest IS DISTINCT FROM sha256(NEW.issuer_spki))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_archive_trust() OWNER TO openpc_control_owner;

--
-- Name: guard_assignment_group(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_assignment_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.authority_group_id IS NULL OR NEW.state NOT IN ('ACTIVE','SUSPENDED') THEN RETURN NEW; END IF;
 IF NOT EXISTS (SELECT FROM control.authority_group g JOIN control.authority_group_member m
    ON m.participant_id=g.participant_id AND m.authority_group_id=g.authority_group_id
    JOIN control.participant_membership binding ON binding.participant_id=m.participant_id AND binding.membership_id=m.principal_id
    JOIN control.principal p ON p.participant_id=m.participant_id AND p.principal_id=m.principal_id
    WHERE g.participant_id=NEW.participant_id AND g.authority_group_id=NEW.authority_group_id AND g.state='ACTIVE'
      AND m.principal_id=NEW.principal_id AND m.state='ACTIVE' AND NEW.valid_during <@ m.valid_during
      AND p.state='ACTIVE' AND p.kind IN ('USER','PLATFORM_OPERATOR')
      AND openpc.directory_group_permits(NEW.participant_id,NEW.authority_group_id)) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-ASSIGNMENT-GROUP';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_assignment_group() OWNER TO openpc_control_owner;

--
-- Name: guard_assignment_role(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_assignment_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE role_row control.authority_role%ROWTYPE;
BEGIN
 IF NEW.role_id IS NULL OR NEW.state NOT IN ('ACTIVE','SUSPENDED') THEN RETURN NEW; END IF;
 SELECT * INTO role_row FROM control.authority_role role
  WHERE role.participant_id=NEW.participant_id AND role.role_id=NEW.role_id FOR SHARE;
 IF NOT FOUND OR role_row.state<>'ACTIVE' OR NOT NEW.action_intent_ids <@ role_row.action_intent_ids THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-ASSIGNMENT-ROLE';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_assignment_role() OWNER TO openpc_control_owner;

--
-- Name: guard_authority_group(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_authority_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'group_name'-'state'-'row_version'-'updated_at'-'last_mutation_operation_id') IS DISTINCT FROM
     (to_jsonb(OLD)-'group_name'-'state'-'row_version'-'updated_at'-'last_mutation_operation_id') OR
     OLD.state<>'ACTIVE' OR NEW.state NOT IN ('ACTIVE','RETIRED') OR NEW.row_version<>OLD.row_version+1 THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-TRANSITION';
  END IF;
  IF NEW.state='RETIRED' AND (EXISTS(SELECT FROM control.authority_group_member m WHERE m.participant_id=NEW.participant_id AND m.authority_group_id=NEW.authority_group_id AND m.state IN ('ACTIVE','SUSPENDED'))
    OR EXISTS(SELECT FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.authority_group_id=NEW.authority_group_id AND a.state IN ('ACTIVE','SUSPENDED'))) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-DEPENDENTS';
  END IF;
 ELSIF NEW.state<>'ACTIVE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-STATE';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_authority_group() OWNER TO openpc_control_owner;

--
-- Name: guard_authority_group_member(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_authority_group_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-MEMBER-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'state'-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'revoked_at') OR
     OLD.state IN ('REVOKED','EXPIRED','RETIRED') OR NEW.state NOT IN ('REVOKED','EXPIRED') OR NEW.revoked_at IS NULL THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-MEMBER-TRANSITION';
  END IF;
 ELSE
  IF NEW.state<>'ACTIVE' OR NEW.revoked_at IS NOT NULL OR isempty(NEW.valid_during) OR lower_inf(NEW.valid_during) OR NOT lower_inc(NEW.valid_during) OR upper_inc(NEW.valid_during)
    OR NOT EXISTS (SELECT FROM control.authority_group g WHERE g.participant_id=NEW.participant_id AND g.authority_group_id=NEW.authority_group_id AND g.state='ACTIVE')
    OR NOT EXISTS (SELECT FROM control.principal p JOIN control.participant_membership m ON m.participant_id=p.participant_id AND m.membership_id=p.principal_id
      WHERE p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id AND p.state='ACTIVE' AND p.kind IN ('USER','PLATFORM_OPERATOR')) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-GROUP-MEMBER-SCOPE';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_authority_group_member() OWNER TO openpc_control_owner;

--
-- Name: guard_authority_role(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_authority_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-ROLE-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'creator_participant_id'-'state'-'row_version'-'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD)-'creator_participant_id'-'state'-'row_version'-'updated_at') OR
     OLD.state<>'ACTIVE' OR NEW.state<>'ARCHIVED' OR NEW.row_version<>OLD.row_version+1 OR
     EXISTS(SELECT 1 FROM control.assignment a WHERE a.participant_id=NEW.participant_id
       AND a.role_id=NEW.role_id AND a.state IN ('ACTIVE','SUSPENDED')) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-ROLE-TRANSITION';
  END IF;
 ELSIF NEW.state<>'ACTIVE' OR EXISTS(
   SELECT 1 FROM unnest(NEW.action_intent_ids) capability
    WHERE NOT EXISTS (SELECT 1 FROM control.action_intent registered WHERE registered.action_intent_id=capability)
 ) THEN RAISE EXCEPTION 'PC-IDENTITY-1002-ROLE-CAPABILITY';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_authority_role() OWNER TO openpc_control_owner;

--
-- Name: guard_bootstrap_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_bootstrap_custody() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR NEW.participant_epoch<>0 OR NEW.custody_generation<>1 OR NEW.row_version<>1
    OR NEW.candidate_membership_id IS NOT NULL OR NEW.accepted_membership_id IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM control.participant WHERE participant_id=NEW.participant_id AND state='PROVISIONING' AND authority_epoch=0)
    OR EXISTS(SELECT 1 FROM control.principal WHERE participant_id=NEW.participant_id AND state='ACTIVE') THEN
   RAISE EXCEPTION 'PC-AUTH-0002';
  END IF;
 ELSE
  IF OLD.state NOT IN ('ACTIVE','CLAIM_PENDING') OR NEW.row_version<>OLD.row_version+1
    OR (to_jsonb(NEW)-'custody_generation'-'state'-'candidate_membership_id'-'candidate_session_id'-'accepted_membership_id'-'accepted_operation_id'-'accepted_intent_digest'-'acceptance_result'-'closed_at'-'row_version')
      IS DISTINCT FROM (to_jsonb(OLD)-'custody_generation'-'state'-'candidate_membership_id'-'candidate_session_id'-'accepted_membership_id'-'accepted_operation_id'-'accepted_intent_digest'-'acceptance_result'-'closed_at'-'row_version')
    OR NOT ((OLD.state='ACTIVE' AND NEW.state='CLAIM_PENDING' AND NEW.custody_generation=OLD.custody_generation AND NEW.candidate_membership_id IS NOT NULL AND NEW.expires_at>clock_timestamp())
      OR (OLD.state='CLAIM_PENDING' AND NEW.state='ACCEPTED' AND NEW.custody_generation=OLD.custody_generation AND NEW.candidate_membership_id=OLD.candidate_membership_id
        AND NEW.candidate_session_id=OLD.candidate_session_id AND NEW.accepted_membership_id=OLD.candidate_membership_id AND NEW.expires_at>clock_timestamp())
      OR (NEW.state='ACTIVE' AND NEW.custody_generation=OLD.custody_generation+1 AND NEW.candidate_membership_id IS NULL AND NEW.candidate_session_id IS NULL AND NEW.expires_at>clock_timestamp())
      OR (NEW.state IN ('CANCELLED','RECOVERY_REQUIRED') AND NEW.custody_generation=OLD.custody_generation AND NEW.candidate_membership_id IS NOT DISTINCT FROM OLD.candidate_membership_id AND NEW.candidate_session_id IS NOT DISTINCT FROM OLD.candidate_session_id)) THEN RAISE EXCEPTION 'PC-AUTH-0002'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_bootstrap_custody() OWNER TO openpc_control_owner;

--
-- Name: guard_business_authority_snapshot(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_authority_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE snapshot jsonb; expected jsonb; bound jsonb;
BEGIN
 IF octet_length(NEW.authority_snapshot)>65536 THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-SIZE'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema'='pc.control.signing-rotation-continuation-snapshot.v1' THEN
  IF NEW.aggregate_type<>'signing-key-rotation' THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-RECEIPT-PURPOSE'; END IF;
  PERFORM openpc.check_signing_continuation_snapshot(NEW.authority_snapshot,NEW.participant_id,NEW.privacy_domain_id,
   NEW.operation_id,NEW.receipt_id,NEW.recorded_at_ns,true);
  RETURN NEW;
 END IF;
 IF snapshot IS DISTINCT FROM jsonb_build_object('schema','pc.control.precommit-authority-snapshot.v1',
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'operationId',NEW.operation_id::text,
  'recordedAtNs',snapshot->'recordedAtNs','decision','ALLOW','authorities',snapshot->'authorities','dependencies',snapshot->'dependencies') OR
  jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR
  jsonb_array_length(snapshot->'authorities')<>(CASE WHEN NEW.aggregate_type='signing-key-rotation' OR NEW.catalog_operation_id IN ('ID-OP-WORKLOAD-RENEWAL-POLICY-CREATE','ID-OP-WORKLOAD-RENEWAL-POLICY-REVISE','ID-OP-WORKLOAD-RENEWAL-POLICY-SUSPEND','ID-OP-WORKLOAD-RENEWAL-POLICY-REVOKE','MOD-OP-REGISTER','MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE','CFG-OP-CREATE-EVIDENCE-HOLD','CFG-OP-RELEASE-EVIDENCE-HOLD','CFG-OP-CREATE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-RELEASE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-DELETE-LOCAL-EVIDENCE','CFG-OP-DELETE-LOCAL-EVIDENCE-BATCH','CFG-OP-DELETE-RAW-PROOF-BATCH','CFG-OP-DELETE-PROJECTION-BATCH','CFG-OP-ADMIT-STORE-RETIREMENT','CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE','CFG-OP-DELETE-RUNTIME-ARTIFACT-BATCH','CFG-OP-ACTIVATE-RETENTION-POLICY','CFG-OP-RETIRE-RETENTION-POLICY') THEN 3 ELSE 1 END) OR
  NOT ((snapshot->>'recordedAtNs') ~ '^[0-9]{1,20}$') OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns THEN
   RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-HEADER'; END IF;
 IF snapshot->'dependencies' IS DISTINCT FROM jsonb_build_object('assignment',snapshot->'dependencies'->'assignment','authority_envelope',snapshot->'dependencies'->'authority_envelope','authority_role',snapshot->'dependencies'->'authority_role','credential',snapshot->'dependencies'->'credential','delegation',snapshot->'dependencies'->'delegation','participant',snapshot->'dependencies'->'participant','principal',snapshot->'dependencies'->'principal','privacy_domain',snapshot->'dependencies'->'privacy_domain','session',snapshot->'dependencies'->'session') THEN
  RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-DEPENDENCIES'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
   FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
    (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
  IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
   FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
    (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
  IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
   FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
    (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
  IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
   FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
    (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
  IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
   FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
    (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
  IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
   FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
    (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
  IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
   FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
    (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
  IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
   FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
    (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
  IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected  THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;

  IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-TYPE'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
   FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
    (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
  IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected AND NOT (
    NEW.aggregate_type='signing-key-rotation'
    AND jsonb_array_length(snapshot->'dependencies'->'session')=jsonb_array_length(expected)
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'session') retained
      WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected) current_row
       WHERE (retained-'idle_expires_at')=(current_row-'idle_expires_at')
        AND (retained->>'idle_expires_at')::timestamptz<=(current_row->>'idle_expires_at')::timestamptz
        AND (extract(epoch FROM (retained->>'idle_expires_at')::timestamptz)*1000000000)>NEW.recorded_at_ns
        AND (current_row->>'idle_expires_at')::timestamptz>clock_timestamp()))
  ) THEN
    RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-ACTUAL-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR
    bound->>'actionIntentId' IS DISTINCT FROM NEW.action_intent_id OR bound->>'resourceId' IS DISTINCT FROM NEW.aggregate_id::text OR
    NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch'))) OR
    NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE'))) OR
    NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',bound->>'principalId','state','ACTIVE','authority_epoch',bound->>'principalEpoch'))) OR
    NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',bound->>'principalId','state','ACTIVE','session_epoch',bound->>'sessionEpoch'))) OR
    NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion'))) OR
    NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch'))) THEN
   RAISE EXCEPTION 'DATA-6021-AUTHORITY-SNAPSHOT-BOUND-PATH'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_business_authority_snapshot() OWNER TO openpc_control_owner;

--
-- Name: guard_business_custody_mutation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_custody_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_TABLE_NAME='outbox_event' THEN
  IF OLD.proof_kind<>'LEGACY' OR (TG_OP='UPDATE' AND (NEW.proof_kind<>OLD.proof_kind OR
    NEW.sequence_namespace<>OLD.sequence_namespace OR NEW.receipt_id IS DISTINCT FROM OLD.receipt_id)) THEN
    RAISE EXCEPTION 'DATA-6020-IMMUTABLE-BUSINESS-OUTBOX'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM control.audit_occurrence a WHERE a.participant_id=OLD.participant_id
   AND a.privacy_domain_id=OLD.privacy_domain_id AND a.operation_id=OLD.operation_id) AND OLD.terminal_state='COMMITTED' THEN
    RAISE EXCEPTION 'DATA-6020-IMMUTABLE-BUSINESS-IDEMPOTENCY'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_business_custody_mutation() OWNER TO openpc_control_owner;

--
-- Name: guard_business_head(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF (TG_OP='INSERT' AND NEW.last_sequence<>1) OR
   (TG_OP='UPDATE' AND (NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id OR
     NEW.sequence_namespace<>OLD.sequence_namespace OR NEW.aggregate_type<>OLD.aggregate_type OR NEW.aggregate_id<>OLD.aggregate_id OR
     NEW.last_sequence<>OLD.last_sequence+1)) THEN RAISE EXCEPTION 'DATA-6021-BUSINESS-SEQUENCE-TRANSITION'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_business_head() OWNER TO openpc_control_owner;

--
-- Name: guard_business_key_lifecycle(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_key_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE key_row control.business_signing_key%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='business_signing_selection' AND TG_OP='UPDATE' AND
  (to_jsonb(NEW)->>'admission_version') IS DISTINCT FROM (to_jsonb(OLD)->>'admission_version') THEN
  IF (to_jsonb(NEW)-'admission_version') IS DISTINCT FROM (to_jsonb(OLD)-'admission_version') OR
   (to_jsonb(NEW)->>'admission_version')::numeric<>(to_jsonb(OLD)->>'admission_version')::numeric+1 OR
   NOT EXISTS(SELECT 1 FROM control.signing_rotation_command c JOIN control.signing_key_rotation r
     ON r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.rotation_id=c.rotation_id
     JOIN control.signing_rotation_observation o ON o.participant_id=c.participant_id AND o.privacy_domain_id=c.privacy_domain_id AND o.operation_id=c.operation_id
    WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
     AND c.operation_id=openpc.current_operation_id() AND c.state='WRITE_AMBIGUITY' AND o.kind='UNRESOLVED'
     AND NEW.signer_id IN(r.old_signer_id,r.new_signer_id))
   THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ADMISSION-VERSION'; END IF;
  RETURN NEW;
 END IF;
 IF NOT pg_has_role(current_user,'openpc_control_key_governor','MEMBER') AND
    NOT pg_has_role(current_user,'openpc_control_owner','MEMBER') THEN
  IF openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' OR
   NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r
    JOIN control.signing_rotation_command command ON command.participant_id=r.participant_id AND command.privacy_domain_id=r.privacy_domain_id
     AND command.rotation_id=r.rotation_id AND command.operation_id=openpc.current_operation_id()
     AND command.action_intent_id=openpc.current_action_intent_id() AND command.state IN ('ACCEPTED','WRITE_AMBIGUITY')
    CROSS JOIN LATERAL (SELECT openpc.signing_transition_effects(command.action_intent_id,r.state,command.to_state) value) effects
    WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
    AND NEW.change_reference='urn:openpc:resource:'||r.rotation_id::text AND r.approval_request_id IS NOT NULL
    AND ((TG_TABLE_NAME='business_signing_selection' AND (effects.value->>'cutover')::boolean AND
       (NEW.signer_id=r.new_signer_id OR (NEW.signer_id=r.old_signer_id AND EXISTS(
         SELECT 1 FROM control.signing_rotation_attestation a WHERE a.participant_id=r.participant_id AND a.privacy_domain_id=r.privacy_domain_id
          AND a.rotation_id=r.rotation_id AND a.operation_id=command.operation_id AND a.from_revision=r.revision
          AND a.to_state=command.to_state AND a.history_digest=NEW.change_digest
          AND to_jsonb(NEW)->>'fenced_operation_id'=a.operation_id::text))))
      OR (TG_TABLE_NAME='business_signing_key_state' AND
       (((effects.value->>'admitTrust')::boolean AND TG_OP='INSERT' AND NEW.signer_id=r.new_signer_id AND to_jsonb(NEW)->>'state'='ADMITTED')
        OR ((effects.value->>'cutover')::boolean AND ((NEW.signer_id=r.new_signer_id AND to_jsonb(NEW)->>'state'='ACTIVE')
          OR (NEW.signer_id=r.old_signer_id AND to_jsonb(NEW)->>'state'='RETIRED')))
        OR ((effects.value->>'revoke')::boolean AND NEW.signer_id=r.old_signer_id AND to_jsonb(NEW)->>'state'='REVOKED'))))) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PC-AUTH-0005-KEY-GOVERNANCE-REQUIRED';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-KEY-HISTORY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id OR
     NEW.row_version<>OLD.row_version+1 OR NEW.changed_at_ns<OLD.changed_at_ns OR
     NEW.change_digest=OLD.change_digest THEN RAISE EXCEPTION 'DATA-6021-KEY-LIFECYCLE-REVISION'; END IF;
  IF TG_TABLE_NAME='business_signing_key_state' THEN
   IF NEW.signer_id<>OLD.signer_id OR NOT (
     (OLD.state='ADMITTED' AND NEW.state IN ('ACTIVE','REVOKED','COMPROMISED')) OR
     (OLD.state='ACTIVE' AND NEW.state IN ('RETIRED','REVOKED','COMPROMISED')) OR
     (OLD.state='RETIRED' AND NEW.state IN ('REVOKED','COMPROMISED')) OR
     (OLD.state='REVOKED' AND NEW.state='COMPROMISED')) THEN RAISE EXCEPTION 'DATA-6021-KEY-LIFECYCLE-TRANSITION'; END IF;
  ELSE
   IF NEW.environment_id<>OLD.environment_id OR NEW.profile_digest<>OLD.profile_digest OR NOT (
      (NEW.signer_id=OLD.signer_id AND OLD.fenced_operation_id IS NULL AND NEW.fenced_operation_id IS NOT NULL
       AND NEW.fenced_operation_id=openpc.current_operation_id() AND NEW.fence_generation=OLD.fence_generation+1) OR
      (NEW.signer_id<>OLD.signer_id AND OLD.fenced_operation_id IS NOT NULL AND OLD.fenced_operation_id=openpc.current_operation_id()
       AND NEW.fenced_operation_id IS NULL AND NEW.fence_generation=OLD.fence_generation))
   THEN RAISE EXCEPTION 'DATA-6021-KEY-SELECTION-TRANSITION'; END IF;
  END IF;
 ELSE
  IF NEW.row_version<>1 THEN RAISE EXCEPTION 'DATA-6021-KEY-LIFECYCLE-REVISION'; END IF;
  IF TG_TABLE_NAME='business_signing_key_state' THEN
   IF NEW.state<>'ADMITTED' THEN RAISE EXCEPTION 'DATA-6021-KEY-LIFECYCLE-TRANSITION'; END IF;
  END IF;
 END IF;
 IF TG_TABLE_NAME='business_signing_selection' THEN
  IF TG_OP='INSERT' AND (NEW.fence_generation<>1 OR NEW.admission_version<>1 OR NEW.fenced_operation_id IS NOT NULL) THEN RAISE EXCEPTION 'DATA-6021-KEY-SELECTION-FENCE'; END IF;
  SELECT k.* INTO STRICT key_row FROM control.business_signing_key k
   JOIN control.business_signing_key_state s USING(participant_id,privacy_domain_id,signer_id)
   WHERE k.participant_id=NEW.participant_id AND k.privacy_domain_id=NEW.privacy_domain_id
    AND k.signer_id=NEW.signer_id AND k.environment_id=NEW.environment_id AND s.state='ACTIVE'
    AND k.valid_from_ns<=floor(extract(epoch FROM clock_timestamp())*1000000)*1000
    AND k.valid_until_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000 FOR SHARE OF s;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_business_key_lifecycle() OWNER TO openpc_control_owner;

--
-- Name: guard_business_outbox(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE receipt control.audit_occurrence%ROWTYPE; payload jsonb;
BEGIN
 IF NEW.proof_kind='LEGACY' THEN RETURN NEW; END IF;
 -- This distinct namespace is fail-closed until the Control export owner installs
 -- its exact receipt/source/outbox checker. It cannot enter command receipt admission.
 IF NEW.proof_kind='EVIDENCE_EXPORT_COMPLETION_REFERENCE' THEN
  PERFORM openpc.check_evidence_export_completion_event(NEW);
  RETURN NEW;
 END IF;
 -- A distinct registered family: the owning checker must exist and validate
 -- actual original receipts, source, occurrence, payload references and cursors.
 -- Any missing owner or denial propagates; there is no command-receipt fallback.
 IF NEW.proof_kind='NOTIFICATION_DELIVERY_REQUEST_REFERENCE' THEN
  PERFORM openpc.check_notification_delivery_requested_event(NEW);
  RETURN NEW;
 END IF;
 -- Terminal native outcomes have a separate source-owned proof. A request
 -- receipt cannot authorize completion; missing final publication stays closed.
 IF NEW.proof_kind='NOTIFICATION_DELIVERY_COMPLETION_REFERENCE' THEN
  PERFORM openpc.check_notification_delivery_completed_event(NEW);
  RETURN NEW;
 END IF;
 IF NEW.proof_kind<>'BUSINESS_RECEIPT_REFERENCE' THEN RAISE EXCEPTION 'DATA-6021-UNADMITTED-OUTBOX-PROOF'; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 payload:=openpc.business_cbor(NEW.payload_cbor);
 IF receipt.aggregate_type='signing-key-rotation' THEN
  PERFORM openpc.check_signing_rotation_event(NEW,receipt);
  RETURN NEW;
 END IF;
 IF NEW.aggregate_type<>receipt.aggregate_type OR NEW.aggregate_id<>receipt.aggregate_id OR
    NEW.payload_digest<>sha256(NEW.payload_cbor) OR NEW.event_type<>'io.openpc.control.command.committed.v1' OR
    NEW.data_schema_uri<>'https://schemas.openpc.local/event-payloads.schema.json#/$defs/CommandCommitted' OR
    payload IS DISTINCT FROM jsonb_build_object('0',openpc.business_uuid(receipt.operation_id),
      '1','urn:openpc:'||receipt.aggregate_type||':'||receipt.aggregate_id::text,
      '2',receipt.action_intent_id,'3',openpc.business_bytes(receipt.action_intent_digest)) THEN
   RAISE EXCEPTION 'DATA-6021-OUTBOX-RECEIPT-PAYLOAD'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_business_outbox() OWNER TO openpc_control_owner;

--
-- Name: guard_business_profile_admission(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_profile_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.definition_canonical_json NOT IN (decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex'),decode('','hex')) THEN RAISE EXCEPTION 'DATA-6021-UNADMITTED-BUSINESS-PROFILE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_business_profile_admission() OWNER TO openpc_control_owner;

--
-- Name: guard_business_receipt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_business_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE actual jsonb; expected jsonb; before_state jsonb; after_state jsonb; proof jsonb; receipt_version integer; continuation control.signing_continuation%ROWTYPE; continuation_used boolean:=false; authorization_time numeric;
 profile control.business_transition_profile%ROWTYPE; authorization_row control.mutation_evidence%ROWTYPE; runtime_payload jsonb; runtime_key_id text; outer_cose jsonb; protected_header jsonb;
BEGIN
 actual:=openpc.business_cbor(NEW.receipt_cbor);
 SELECT * INTO STRICT profile FROM control.business_transition_profile WHERE profile_digest=NEW.profile_digest;
 receipt_version:=CASE encode(profile.schema_definition_digest,'hex')
  WHEN '41a877ca7e00e74f32c8becf8daee38f26c12ab9d9dcf6ff80ed8e75608b3c1f' THEN 1
  WHEN '4e7de36861819909275bdec8103d1df04984c03b34cb593437dfe68f5c2c1d9a' THEN 2 END;
 IF receipt_version IS NULL OR (receipt_version=2 AND profile.catalog_operation_id NOT IN
  ('OPS-OP-ADVANCE-SIGNING-KEY-ROTATION','OPS-OP-RECOVER-SIGNING-KEY-ROTATION'))
 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-SCHEMA-VERSION'; END IF;
 IF NEW.schema_definition_digest<>profile.schema_definition_digest OR NEW.action_intent_id<>profile.action_intent_id OR
    NEW.catalog_operation_id<>profile.catalog_operation_id OR NEW.aggregate_type<>profile.aggregate_type OR
    NEW.transition_kind<>profile.transition_kind THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-PROFILE-BINDING'; END IF;
 expected:=jsonb_build_object('0',openpc.business_uuid(NEW.receipt_id),'1',openpc.business_bytes(NEW.schema_definition_digest),
  '2',NEW.profile_id,'3',NEW.profile_version,'4',openpc.business_bytes(NEW.profile_digest),'5',NEW.environment_id,
  '6',openpc.business_uuid(NEW.participant_id),'7',openpc.business_uuid(NEW.privacy_domain_id),
  '8',openpc.business_uuid(NEW.operation_id),'9',NEW.action_intent_id,'10',NEW.catalog_operation_id,
  '11',NEW.aggregate_type,'12',openpc.business_uuid(NEW.aggregate_id),'13',openpc.business_bytes(NEW.actor_key_digest),
  '14',openpc.business_bytes(NEW.pre_commit_authority_digest),'15',openpc.business_bytes(NEW.action_intent_digest),
  '16',openpc.business_bytes(NEW.candidate_digest),'17',openpc.business_uuid(NEW.idempotency_record_id),
  '18',jsonb_build_object('0',NEW.before_existence,'1',NEW.before_revision,'2',openpc.business_bytes(NEW.before_state_digest)),
  '19',jsonb_build_object('0',NEW.after_existence,'1',NEW.after_revision,'2',openpc.business_bytes(NEW.after_state_digest)),
  '20',actual->'20','21',actual->'21','22',NEW.transition_kind,'23',NEW.recorded_at_ns,
  '24',NEW.signer_id,'25',openpc.business_bytes(NEW.signer_trust_snapshot_digest),'26',openpc.business_bytes(NEW.request_digest));
 IF actual IS DISTINCT FROM expected OR octet_length(NEW.actor_key_digest)<>32 OR
    octet_length(NEW.action_intent_digest)<>32 OR octet_length(NEW.candidate_digest)<>32 OR
    octet_length(NEW.request_digest)<>32 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-TYPED-BINDING'; END IF;
 IF get_byte(NEW.cose_sign1,0)<>210 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-COSE-TAG'; END IF;
 outer_cose:=openpc.business_cbor_item(NEW.cose_sign1,1,0);
 IF (outer_cose->>'next')::integer<>octet_length(NEW.cose_sign1) THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-COSE-TRAILING'; END IF;
 outer_cose:=outer_cose->'value';
 IF jsonb_typeof(outer_cose)<>'array' OR jsonb_array_length(outer_cose)<>4 OR outer_cose->1<>'{}'::jsonb OR
    outer_cose->2 IS DISTINCT FROM openpc.business_bytes(NEW.receipt_cbor) OR
    length(outer_cose->3->>'bytes') IS DISTINCT FROM 128 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-COSE-BINDING'; END IF;
 protected_header:=openpc.business_cbor(decode(outer_cose->0->>'bytes','hex'));
 IF protected_header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),
  '3','application/pc+cbor','4',openpc.business_bytes(convert_to(NEW.signer_id,'UTF8')),
  '100',24001,'101',receipt_version,'102',338,'103',2) THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-COSE-CONTEXT'; END IF;
 before_state:=openpc.business_cbor(NEW.before_state_preimage);
 after_state:=openpc.business_cbor(NEW.after_state_preimage);
 IF before_state IS DISTINCT FROM jsonb_build_array('pc.control.transition-state.v1',openpc.business_bytes(NEW.profile_digest),
  openpc.business_uuid(NEW.participant_id),openpc.business_uuid(NEW.privacy_domain_id),NEW.aggregate_type,
  openpc.business_uuid(NEW.aggregate_id),NEW.before_existence,NEW.before_revision,before_state->8) OR
  after_state IS DISTINCT FROM jsonb_build_array('pc.control.transition-state.v1',openpc.business_bytes(NEW.profile_digest),
  openpc.business_uuid(NEW.participant_id),openpc.business_uuid(NEW.privacy_domain_id),NEW.aggregate_type,
  openpc.business_uuid(NEW.aggregate_id),NEW.after_existence,NEW.after_revision,after_state->8) OR
  (NEW.before_existence=0 AND before_state->8<>'{}'::jsonb) THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-STATE-BINDING'; END IF;
 IF receipt_version=2 AND convert_from(NEW.authority_snapshot,'UTF8')::jsonb->>'schema'='pc.control.signing-rotation-continuation-snapshot.v1' THEN
  SELECT * INTO STRICT continuation FROM control.signing_continuation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id AND state='CONSUMED'
   AND consumed_receipt_id=NEW.receipt_id;
  continuation_used:=true;
 END IF;
 IF jsonb_typeof(actual->'20') IS DISTINCT FROM 'array' OR jsonb_array_length(actual->'20')<>(CASE WHEN continuation_used OR NEW.catalog_operation_id IN ('ID-OP-WORKLOAD-RENEWAL-POLICY-CREATE','ID-OP-WORKLOAD-RENEWAL-POLICY-REVISE','ID-OP-WORKLOAD-RENEWAL-POLICY-SUSPEND','ID-OP-WORKLOAD-RENEWAL-POLICY-REVOKE','MOD-OP-REGISTER','MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE','CFG-OP-CREATE-EVIDENCE-HOLD','CFG-OP-RELEASE-EVIDENCE-HOLD','CFG-OP-CREATE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-RELEASE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-DELETE-LOCAL-EVIDENCE','CFG-OP-DELETE-LOCAL-EVIDENCE-BATCH','CFG-OP-DELETE-RAW-PROOF-BATCH','CFG-OP-DELETE-PROJECTION-BATCH','CFG-OP-ADMIT-STORE-RETIREMENT','CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE','CFG-OP-DELETE-RUNTIME-ARTIFACT-BATCH','CFG-OP-ACTIVATE-RETENTION-POLICY','CFG-OP-RETIRE-RETENTION-POLICY') OR NEW.catalog_operation_id IN ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT') THEN 2 ELSE 1 END) OR
    jsonb_typeof(actual->'21') IS DISTINCT FROM 'array' OR
    (receipt_version=1 AND jsonb_array_length(actual->'21')<>1) OR
    (receipt_version=2 AND jsonb_array_length(actual->'21') NOT BETWEEN 0 AND 1) THEN
  RAISE EXCEPTION 'DATA-6021-RECEIPT-PROFILE-CARDINALITY'; END IF;
 IF NEW.catalog_operation_id IN ('MOD-OP-REGISTER','MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE') THEN
  PERFORM openpc.check_module_admission_receipt(NEW);
 ELSIF NEW.catalog_operation_id IN ('ID-OP-WORKLOAD-RENEWAL-POLICY-CREATE','ID-OP-WORKLOAD-RENEWAL-POLICY-REVISE','ID-OP-WORKLOAD-RENEWAL-POLICY-SUSPEND','ID-OP-WORKLOAD-RENEWAL-POLICY-REVOKE','MOD-OP-REGISTER','MOD-OP-INSTALL','MOD-OP-ENABLE','MOD-OP-DISABLE','CFG-OP-CREATE-EVIDENCE-HOLD','CFG-OP-RELEASE-EVIDENCE-HOLD','CFG-OP-CREATE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-RELEASE-PARTICIPANT-EVIDENCE-HOLD','CFG-OP-DELETE-LOCAL-EVIDENCE','CFG-OP-DELETE-LOCAL-EVIDENCE-BATCH','CFG-OP-DELETE-RAW-PROOF-BATCH','CFG-OP-DELETE-PROJECTION-BATCH','CFG-OP-ADMIT-STORE-RETIREMENT','CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE','CFG-OP-DELETE-RUNTIME-ARTIFACT-BATCH','CFG-OP-ACTIVATE-RETENTION-POLICY','CFG-OP-RETIRE-RETENTION-POLICY') THEN
  PERFORM openpc.check_governed_configuration_receipt(NEW);
 ELSE
 SELECT * INTO STRICT authorization_row FROM control.mutation_evidence e WHERE e.participant_id=NEW.participant_id
  AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=NEW.operation_id
  AND e.action_intent_id=NEW.action_intent_id AND e.catalog_operation_id=NEW.catalog_operation_id AND e.aggregate_id=NEW.aggregate_id
  AND e.candidate_digest=NEW.candidate_digest AND e.evidence_digest=sha256(e.evidence_cbor)
  AND e.evidence_role='AUTHORIZATION_INPUT' AND e.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13';
 proof:=jsonb_build_object('0',2,'1',authorization_row.mutation_evidence_id::text,'2',openpc.business_bytes(authorization_row.evidence_digest));
 IF continuation_used THEN
  SELECT jsonb_agg(p ORDER BY p->>'1') INTO expected FROM jsonb_array_elements(jsonb_build_array(proof,
   jsonb_build_object('0',2,'1',continuation.assertion_id::text,'2',openpc.business_bytes(continuation.assertion_digest)))) p;
  SELECT (convert_from(c.authorization_snapshot,'UTF8')::jsonb->>'recordedAtNs')::numeric INTO STRICT authorization_time
   FROM control.signing_rotation_command c WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.operation_id=NEW.operation_id AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1';
 ELSIF NEW.catalog_operation_id IN ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT') THEN
  expected:=jsonb_build_array(proof,openpc.configuration_step_up_receipt_input(NEW,authorization_row));
  authorization_time:=NEW.recorded_at_ns;
 ELSE expected:=jsonb_build_array(proof); authorization_time:=NEW.recorded_at_ns;
 END IF;
 IF actual->'20' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-AUTHORIZATION-OWNER'; END IF;
 runtime_payload:=openpc.business_cbor(authorization_row.evidence_cbor);
 runtime_key_id:=openpc.identity_runtime_cose_key_id(authorization_row.evidence_cbor,authorization_row.cose_sign1);
 IF runtime_key_id=NEW.signer_id OR
    runtime_payload->'1' IS DISTINCT FROM openpc.business_bytes(NEW.actor_key_digest) OR
    jsonb_typeof(runtime_payload->'8') IS DISTINCT FROM 'number' OR jsonb_typeof(runtime_payload->'9') IS DISTINCT FROM 'number' OR
    (runtime_payload->>'8')::numeric>authorization_time OR (runtime_payload->>'9')::numeric<=authorization_time THEN
   RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-TYPED-PURPOSE-BINDING'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.idempotency_record i WHERE i.participant_id=NEW.participant_id
   AND i.privacy_domain_id=NEW.privacy_domain_id AND i.operation_id=NEW.operation_id
   AND i.idempotency_record_id=NEW.idempotency_record_id AND i.action_intent_id=NEW.action_intent_id
   AND i.catalog_operation_id=NEW.catalog_operation_id AND i.input_digest=NEW.candidate_digest
   AND NEW.request_digest=openpc.business_request_digest(ARRAY[i.participant_id::text,i.privacy_domain_id::text,i.principal_id::text,
     i.action_intent_id,i.catalog_operation_id,NEW.aggregate_type,NEW.aggregate_id::text,i.expected_aggregate_version::text,
     'sha256:'||encode(i.input_digest,'hex'),i.idempotency_key])) THEN
  RAISE EXCEPTION 'DATA-6021-RECEIPT-IDEMPOTENCY-OWNER'; END IF;

 IF NEW.aggregate_type='evidence-hold' THEN
  PERFORM openpc.assert_evidence_hold_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='evidence-deletion' THEN
  PERFORM openpc.assert_evidence_deletion_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='runtime-artifact-disposition' THEN
  PERFORM openpc.assert_runtime_artifact_disposition_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='store-retirement' THEN
  PERFORM openpc.assert_store_retirement_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='retention-policy' THEN
  PERFORM openpc.assert_retention_policy_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='workload-renewal-policy' THEN
  PERFORM openpc.assert_workload_renewal_policy_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='work-item' THEN
  PERFORM openpc.assert_work_item_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='notification' THEN
  PERFORM openpc.assert_notification_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='notification-endpoint' THEN
  PERFORM openpc.assert_notification_endpoint_receipt(NEW);
 END IF;
 IF NEW.aggregate_type='indexer-profile' THEN
  IF profile.profile_version NOT IN (1,2) OR (profile.profile_version=2 AND (
    (NEW.before_existence=1 AND (NOT (before_state->8 ?& ARRAY['0','1','2','3','4']) OR
      before_state->8->'4' NOT IN ('0'::jsonb,'1'::jsonb) OR
      (before_state->8 ? '5') IS DISTINCT FROM (before_state->8->'4'='1'::jsonb) OR
      ((before_state->8)-ARRAY['0','1','2','3','4','5'])<>'{}'::jsonb OR
      (before_state->8->'4'='1'::jsonb AND (before_state->8->'5' IS DISTINCT FROM
        jsonb_build_object('bytes',before_state->8->'5'->>'bytes') OR
        coalesce(before_state->8->'5'->>'bytes','')!~'^[0-9a-f]{64}$')))) OR
    after_state->8->'4' NOT IN ('0'::jsonb,'1'::jsonb)))
  THEN RAISE EXCEPTION 'DATA-6021-INDEXER-PROVENANCE-PROFILE'; END IF;
  IF NOT EXISTS(SELECT 1 FROM control.indexer_profile i WHERE i.participant_id=NEW.participant_id
   AND i.privacy_domain_id=NEW.privacy_domain_id AND i.indexer_profile_id=NEW.aggregate_id
   AND i.revision=NEW.after_revision AND NEW.after_existence=1
   AND (profile.profile_version=2 OR i.policy_generation_digest IS NOT NULL)
   AND after_state->8=(jsonb_build_object('0',i.engine,'1',i.engine_version,
    '2',openpc.business_bytes(decode(substring(i.method_profile_digest from 8),'hex')),'3',i.state) ||
    CASE WHEN profile.profile_version=1 THEN jsonb_build_object('4',openpc.business_bytes(decode(substring(i.policy_generation_digest from 8),'hex')))
    WHEN i.policy_generation_digest IS NULL THEN jsonb_build_object('4',0)
    ELSE jsonb_build_object('4',1,'5',openpc.business_bytes(decode(substring(i.policy_generation_digest from 8),'hex'))) END)) THEN
    RAISE EXCEPTION 'DATA-6021-RECEIPT-ACTUAL-INDEXER-STATE'; END IF;
  IF (NEW.catalog_operation_id='CFG-OP-CREATE-INDEXER-PROFILE' AND
      (NEW.before_existence<>0 OR NEW.after_revision<>1 OR after_state->8->>'3'<>'REGISTERED')) OR
     (NEW.catalog_operation_id='CFG-OP-UPDATE-INDEXER-PROFILE' AND
      (NEW.before_existence<>1 OR NEW.after_revision<>NEW.before_revision+1 OR
       before_state->8->'0' IS DISTINCT FROM after_state->8->'0' OR
       before_state->8->'1' IS DISTINCT FROM after_state->8->'1' OR
       before_state->8->'3' IS DISTINCT FROM after_state->8->'3' OR
       (before_state->8->'2'=after_state->8->'2' AND before_state->8->'4'=after_state->8->'4'
        AND before_state->8->'5' IS NOT DISTINCT FROM after_state->8->'5'))) THEN
    RAISE EXCEPTION 'DATA-6021-RECEIPT-INDEXER-TRANSITION'; END IF;
 END IF;
 IF receipt_version=2 THEN
  PERFORM openpc.check_signing_rotation_receipt(NEW);
  RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.business_signing_selection s
  JOIN control.business_signing_key k USING(participant_id,privacy_domain_id,signer_id)
  JOIN control.business_signing_key_state lifecycle USING(participant_id,privacy_domain_id,signer_id)
  JOIN control.credential c ON c.participant_id=k.participant_id AND c.credential_id=k.workload_credential_id
  JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
  WHERE s.participant_id=NEW.participant_id AND s.privacy_domain_id=NEW.privacy_domain_id
   AND s.environment_id=NEW.environment_id AND s.profile_digest=NEW.profile_digest AND s.signer_id=NEW.signer_id
   AND k.trust_digest=NEW.signer_trust_snapshot_digest AND k.environment_id=NEW.environment_id
   AND lifecycle.state='ACTIVE' AND c.state='ACTIVE' AND p.kind='WORKLOAD' AND p.state='ACTIVE'
   AND c.credential_epoch=k.workload_credential_epoch
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND k.valid_from_ns<=NEW.recorded_at_ns AND k.valid_until_ns>NEW.recorded_at_ns
   AND k.valid_until_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
   FOR SHARE OF s,lifecycle,c,p) THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-LIVE-SIGNING-TRUST'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_business_receipt() OWNER TO openpc_control_owner;

--
-- Name: guard_candidate_archive(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_candidate_archive() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m jsonb:=NEW.manifest; i jsonb:=m->'identity'; b jsonb:=i->'block'; entry jsonb;
 prefix text; expected_id text; expected_digest text; expected_format text; index integer:=0;
 total integer; part_count integer; previous_sequence numeric:=0; original control.evidence_catalogue;
 field text; block_field text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NOT pg_has_role(current_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF m IS DISTINCT FROM jsonb_build_object('version','OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1',
  'class','CANDIDATE_PROJECTION','store','openpc_candidate_index','authority','NONE',
  'currentReadiness','NOT_ESTABLISHED','identity',i,'identityDigest',m->'identityDigest','chunks',m->'chunks')
  OR jsonb_typeof(i) IS DISTINCT FROM 'object' OR jsonb_typeof(b) IS DISTINCT FROM 'object'
  OR i-ARRAY['participantId','privacyDomainId','sourceProfileId','generationId','partitionId','candidateId',
   'publicationDigest','sourceProfileDigest','partitionDigest','projectionId','mappingDigest','nativeRecordId',
   'recordKind','recordSequence','candidateFeedSequence','observedEventId','observedEventDigest','payloadDigest',
   'payloadBytes','schemaDigest','evidenceDigest','checkpointDigest','occurredAt','chainId','genesisDigest','block']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(i))<>26
  OR b-ARRAY['number','hash','parentHash','finalityKind','finalityEvidenceDigest','headNumber','headHash']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(b))<>7
  OR jsonb_typeof(m->'chunks') IS DISTINCT FROM 'array'
  OR jsonb_array_length(m->'chunks') NOT BETWEEN 1 AND 16
  OR i->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR i->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR i->>'candidateId' IS DISTINCT FROM NEW.candidate_id::text
  OR NEW.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(m),'UTF8')),'hex')
  OR m->>'identityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(i),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR field IN SELECT jsonb_object_keys(i) LOOP
  IF field NOT IN ('payloadBytes','block') AND jsonb_typeof(i->field) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOR field IN SELECT jsonb_object_keys(b) LOOP
  IF jsonb_typeof(b->field) IS DISTINCT FROM 'string'
   AND NOT(field IN ('headNumber','headHash') AND b->field='null'::jsonb)
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['participantId','privacyDomainId','sourceProfileId','generationId','partitionId','candidateId','projectionId','observedEventId'] LOOP
  IF coalesce(i->>field,'')!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['publicationDigest','sourceProfileDigest','partitionDigest','mappingDigest','observedEventDigest',
  'payloadDigest','schemaDigest','evidenceDigest','checkpointDigest','genesisDigest'] LOOP
  IF coalesce(i->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH block_field IN ARRAY ARRAY['hash','parentHash','finalityEvidenceDigest'] LOOP
  IF coalesce(b->>block_field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 IF coalesce(i->>'recordKind','') NOT IN ('EVENT_LOG','STATE_CALL','TRANSACTION_RECEIPT','BLOCK_HEADER','FULL_BLOCK_TRANSACTIONS','EXTERNAL_OBSERVATION')
  OR length(i->>'nativeRecordId') NOT BETWEEN 1 AND 256
  OR coalesce(i->>'recordSequence','')!~'^(0|[1-9][0-9]{0,19})$' OR (i->>'recordSequence')::numeric>18446744073709551615
  OR coalesce(i->>'candidateFeedSequence','')!~'^[1-9][0-9]{0,18}$' OR (i->>'candidateFeedSequence')::numeric>9223372036854775807
  OR coalesce(i->>'chainId','')!~'^(0|[1-9][0-9]{0,77})$' OR (i->>'chainId')::numeric>=power(2::numeric,256)
  OR coalesce(b->>'number','')!~'^(0|[1-9][0-9]{0,19})$' OR (b->>'number')::numeric>18446744073709551615
  OR coalesce(b->>'finalityKind','') NOT IN ('SAFE_TAG','FINALIZED_TAG','CONFIRMATIONS')
  OR ((b->>'finalityKind'='CONFIRMATIONS') IS DISTINCT FROM (b->'headNumber'<>'null'::jsonb AND b->'headHash'<>'null'::jsonb))
  OR ((b->'headNumber'='null'::jsonb) IS DISTINCT FROM (b->'headHash'='null'::jsonb))
  OR (b->'headNumber'<>'null'::jsonb AND (coalesce(b->>'headNumber','')!~'^(0|[1-9][0-9]{0,19})$'
    OR (b->>'headNumber')::numeric>18446744073709551615 OR coalesce(b->>'headHash','')!~'^sha256:[0-9a-f]{64}$'))
  OR jsonb_typeof(i->'payloadBytes') IS DISTINCT FROM 'number'
  OR coalesce(i->>'payloadBytes','')!~'^[1-9][0-9]{0,6}$' OR (i->>'payloadBytes')::integer NOT BETWEEN 1 AND 1048576
  OR coalesce(i->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 total:=(i->>'payloadBytes')::integer; part_count:=jsonb_array_length(m->'chunks');
 prefix:='candidate:'||substring(m->>'identityDigest' from 8);
 IF part_count<>(total+65535)/65536 OR NEW.record_id<>prefix||':manifest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(m->'chunks') LOOP
  IF entry IS DISTINCT FROM jsonb_build_object('index',index,'offset',index*65536,
    'bytes',least(65536,total-index*65536),'recordId',prefix||':chunk:'||index::text,'digest',entry->'digest')
    OR coalesce(entry->>'digest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  index:=index+1;
 END LOOP;
 -- Every chunk precedes the final manifest. Native feed sequence is independent
 -- of the catalogue's contiguous archive sequence and is never used as its cursor.
 FOR index IN 0..part_count LOOP
  expected_id:=CASE WHEN index=part_count THEN NEW.record_id ELSE m->'chunks'->index->>'recordId' END;
  expected_digest:=CASE WHEN index=part_count THEN NEW.manifest_digest ELSE m->'chunks'->index->>'digest' END;
  expected_format:=CASE WHEN index=part_count THEN 'OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1' ELSE 'OPENPC_CANDIDATE_PROJECTION_CHUNK_V1' END;
  SELECT c.* INTO STRICT original FROM control.evidence_catalogue c
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_segment_payload body USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.stream_id=NEW.stream_id AND c.record_id=expected_id
    AND c.evidence_class='EFFECT' AND c.source_format=expected_format AND c.receipt_digest=expected_digest
    AND c.occurred_at=(i->>'occurredAt')::timestamptz AND c.sequence BETWEEN s.first_sequence AND s.through_sequence
    AND s.object_digest='sha256:'||encode(sha256(body.encrypted_segment),'hex');
  IF original.sequence<=previous_sequence THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  previous_sequence:=original.sequence;
 END LOOP;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_candidate_archive() OWNER TO openpc_control_owner;

--
-- Name: guard_candidate_archive_part(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_candidate_archive_part() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE parent control.evidence_candidate_archive; expected text; count_parts integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT parent FROM control.evidence_candidate_archive WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.manifest_record_id;
 count_parts:=jsonb_array_length(parent.manifest->'chunks');
 expected:=CASE WHEN NEW.ordinal=count_parts THEN parent.record_id ELSE parent.manifest->'chunks'->NEW.ordinal->>'recordId' END;
 IF expected IS NULL OR NEW.record_id IS DISTINCT FROM expected OR NEW.ordinal<0 OR NEW.ordinal>count_parts THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_candidate_archive_part() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_activation_selection(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_activation_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE item jsonb; last_id text:=''; selected control.cigl_profile_version; root_id uuid; roots uuid[]:='{}';
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.cigl_profile_selection IS DISTINCT FROM OLD.cigl_profile_selection THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-ACTIVATION-IMMUTABLE'; END IF;
  IF OLD.cigl_profile_selection IS NOT NULL AND
   ROW(NEW.runtime_configuration_generation_id,NEW.participant_id,NEW.privacy_domain_id,NEW.runtime_target_id,
     NEW.provider_profile_id,NEW.projection_plan_id,NEW.predecessor_digest,NEW.generation_digest,NEW.policy_generation_digest,NEW.created_at)
   IS DISTINCT FROM ROW(OLD.runtime_configuration_generation_id,OLD.participant_id,OLD.privacy_domain_id,OLD.runtime_target_id,
     OLD.provider_profile_id,OLD.projection_plan_id,OLD.predecessor_digest,OLD.generation_digest,OLD.policy_generation_digest,OLD.created_at) THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-ACTIVATION-IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.cigl_profile_selection IS NULL THEN
  IF EXISTS(SELECT 1 FROM control.runtime_target target
   JOIN control.runtime_activation_observation observation ON observation.runtime_target_id=target.runtime_target_id
    AND observation.participant_id=target.participant_id AND observation.privacy_domain_id=target.privacy_domain_id
    AND observation.capsule_digest=target.active_generation_digest
   JOIN control.runtime_configuration_generation previous ON previous.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
   WHERE target.runtime_target_id=NEW.runtime_target_id AND previous.cigl_profile_selection IS NOT NULL) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ACTIVATION-REQUIRED'; END IF;
  RETURN NEW;
 END IF;
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.lock_cigl_grant_sources();
 IF openpc.current_action_intent_id()<>'ACT-CIGL_PROFILES_ACTIVATE_RESOURCE-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
  OR NEW.state<>'ACTIVATING' OR NEW.revision<>1 OR NEW.predecessor_digest IS NULL
  OR NOT EXISTS(SELECT 1 FROM control.participant WHERE participant_id=NEW.participant_id AND state='ACTIVE'
    AND archived_at IS NULL AND authority_epoch::text=NEW.cigl_profile_selection->>'participantEpoch')
  OR NOT EXISTS(SELECT 1 FROM control.runtime_target WHERE runtime_target_id=NEW.runtime_target_id
    AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND state='ACTIVE_MATCHED'
    AND active_generation_digest=NEW.predecessor_digest AND desired_generation_digest=NEW.predecessor_digest) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ACTIVATION-SOURCE'; END IF;
 IF NEW.cigl_profile_selection ? 'policyRenewal' THEN
  IF NOT EXISTS(SELECT 1 FROM control.policy_activation_occurrence occurrence
   JOIN control.policy_activation activation ON activation.policy_activation_id=occurrence.activation_occurrence_id
    AND activation.participant_id=occurrence.participant_id AND activation.privacy_domain_id=occurrence.privacy_domain_id
    AND activation.policy_generation_id=occurrence.policy_generation_id AND activation.state='PREPARED'
   JOIN control.policy_generation policy ON policy.policy_generation_id=occurrence.policy_generation_id
    AND policy.participant_id=occurrence.participant_id AND policy.privacy_domain_id=occurrence.privacy_domain_id
    AND policy.state='PREPARED' AND NOT policy.active
   JOIN control.policy_activation_occurrence_target cohort ON cohort.activation_occurrence_id=occurrence.activation_occurrence_id
    AND cohort.participant_id=occurrence.participant_id AND cohort.privacy_domain_id=occurrence.privacy_domain_id
   WHERE occurrence.participant_id=NEW.participant_id AND occurrence.privacy_domain_id=NEW.privacy_domain_id
    AND 'urn:openpc:resource:'||occurrence.activation_occurrence_id::text=NEW.cigl_profile_selection->'policyRenewal'->>'activationOccurrenceRef'
    AND occurrence.revision::text=NEW.cigl_profile_selection->'policyRenewal'->>'expectedRevision'
    AND occurrence.state='REQUESTED' AND occurrence.total_target_count=1
    AND 'sha256:'||encode(policy.generation_digest,'hex')=NEW.policy_generation_digest
    AND NEW.policy_generation_digest=NEW.cigl_profile_selection->'policyRenewal'->>'policyGenerationDigest'
    AND cohort.runtime_target_id=NEW.runtime_target_id AND cohort.phase='FORWARD' AND cohort.state='REQUESTED'
    AND cohort.expected_predecessor_digest=NEW.predecessor_digest AND cohort.configuration_work_id IS NULL) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-RENEWAL-AUTHORITY'; END IF;
  -- Renewal carries every installed graph; changing or removing a graph requires
  -- its own analysis/review, not a policy freshness renewal.
  IF NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation observation
   JOIN control.runtime_configuration_generation previous ON previous.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
    AND previous.participant_id=observation.participant_id AND previous.privacy_domain_id=observation.privacy_domain_id
   WHERE observation.runtime_target_id=NEW.runtime_target_id AND observation.participant_id=NEW.participant_id
    AND observation.privacy_domain_id=NEW.privacy_domain_id AND observation.capsule_digest=NEW.predecessor_digest
    AND previous.state='ACTIVE' AND previous.cigl_profile_selection IS NOT NULL
    AND (SELECT jsonb_agg(value-'grantSourcesDigest' ORDER BY value->>'profileId') FROM jsonb_array_elements(previous.cigl_profile_selection->'profiles'))
      = (SELECT jsonb_agg(value-'grantSourcesDigest' ORDER BY value->>'profileId') FROM jsonb_array_elements(NEW.cigl_profile_selection->'profiles'))) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-RENEWAL-LINEAGE'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target WHERE runtime_target_id=NEW.runtime_target_id
   AND policy_generation_digest=NEW.policy_generation_digest) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-RENEWAL-REQUIRED'; END IF;
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.cigl_profile_selection->'profiles') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT item ?& ARRAY['profileId','profileRevision','profileDigest','compilationArtifactDigest','grantSourcesDigest']
   OR item-ARRAY['profileId','profileRevision','profileDigest','compilationArtifactDigest','grantSourcesDigest']<>'{}'::jsonb
   OR EXISTS(SELECT 1 FROM jsonb_each(item) field WHERE jsonb_typeof(field.value)<>'string')
   OR (item->>'profileId' ~ '^urn:openpc:resource:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') IS DISTINCT FROM true
   OR (item->>'profileRevision' ~ '^[1-9][0-9]{0,19}$') IS DISTINCT FROM true
   OR (item->>'grantSourcesDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
   OR item->>'profileId'<=last_id THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-ACTIVATION-SELECTION'; END IF;
  last_id:=item->>'profileId';
  SELECT version.* INTO selected FROM control.cigl_profile_version version
   JOIN control.cigl_analysis analysis ON analysis.analysis_id=version.analysis_id
    AND analysis.participant_id=version.participant_id AND analysis.privacy_domain_id=version.privacy_domain_id
   WHERE version.profile_id=substring(item->>'profileId' from 21)::uuid AND version.revision::text=item->>'profileRevision'
    AND version.participant_id=NEW.participant_id AND version.privacy_domain_id=NEW.privacy_domain_id
    AND version.state='COMPILED' AND version.profile_digest=item->>'profileDigest' AND version.artifact_digest=item->>'compilationArtifactDigest'
    AND version.dependency_paths_digest IS NOT NULL AND analysis.runtime_target_id=NEW.runtime_target_id
    AND openpc.cigl_profile_has_installed_lineage(version.profile_id,version.revision,
      NEW.runtime_target_id,NEW.predecessor_digest,
      (SELECT policy_generation_digest FROM control.runtime_target WHERE runtime_target_id=NEW.runtime_target_id));
  IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007-CIGL-ACTIVATION-SELECTION'; END IF;
  SELECT root_contract_method_policy_id INTO root_id FROM control.cigl_method_profile WHERE profile_id=selected.profile_id;
  IF root_id=ANY(roots) THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-ACTIVATION-ROOT'; END IF;
  roots:=array_append(roots,root_id);
 END LOOP;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_cigl_activation_selection() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_activation_work(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_activation_work() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM control.runtime_configuration_generation generation
   WHERE generation.runtime_configuration_generation_id=OLD.runtime_configuration_generation_id
    AND generation.cigl_profile_selection IS NOT NULL) AND
  ROW(NEW.configuration_work_id,NEW.participant_id,NEW.privacy_domain_id,NEW.operation_id,NEW.work_kind,NEW.resource_id,
    NEW.input_digest,NEW.configuration_digest,NEW.runtime_configuration_generation_id,NEW.runtime_target_id,
    NEW.generation_digest,NEW.predecessor_digest,NEW.policy_generation_digest,NEW.xds_version_digest,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.configuration_work_id,OLD.participant_id,OLD.privacy_domain_id,OLD.operation_id,OLD.work_kind,OLD.resource_id,
    OLD.input_digest,OLD.configuration_digest,OLD.runtime_configuration_generation_id,OLD.runtime_target_id,
    OLD.generation_digest,OLD.predecessor_digest,OLD.policy_generation_digest,OLD.xds_version_digest,OLD.created_at) THEN
  RAISE EXCEPTION 'PC-DATA-6004-CIGL-ACTIVATION-WORK-IMMUTABLE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_activation_work() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_analysis(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_analysis() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE capsule text; policy text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ANALYSIS'; END IF;
 IF TG_OP='INSERT' THEN
  IF current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_CREATE_RESOURCE-V1'
   OR NEW.creation_operation_id<>NEW.publication_operation_id OR NEW.state<>'OPEN' OR NEW.revision<>1 THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ANALYSIS-CREATE'; END IF;
  IF jsonb_typeof(NEW.definition) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_each(NEW.definition) field WHERE field.key<>'expiresInSeconds' AND jsonb_typeof(field.value)<>'string')
   OR (NEW.definition-ARRAY['targetRuntimeId','expectedGenerationDigest','runtimeBindingId','contractMethodPolicyId',
     'expectedRuntimeBindingRevision','expectedMethodRevision','workloadId','transactionHash','expiresInSeconds']) IS DISTINCT FROM '{}'::jsonb
   OR NOT NEW.definition ?& ARRAY['targetRuntimeId','expectedGenerationDigest','runtimeBindingId','contractMethodPolicyId',
     'expectedRuntimeBindingRevision','expectedMethodRevision','workloadId','transactionHash','expiresInSeconds']
   OR NEW.definition->>'targetRuntimeId' IS DISTINCT FROM 'urn:openpc:resource:'||NEW.runtime_target_id::text
   OR NEW.definition->>'runtimeBindingId' IS DISTINCT FROM 'urn:openpc:resource:'||NEW.runtime_binding_id::text
   OR NEW.definition->>'contractMethodPolicyId' IS DISTINCT FROM 'urn:openpc:resource:'||NEW.contract_method_policy_id::text
   OR (NEW.definition->>'transactionHash' ~ '^0x[0-9a-f]{64}$') IS DISTINCT FROM true
   OR (NEW.definition->>'expectedGenerationDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
   OR (NEW.definition->>'expectedRuntimeBindingRevision' ~ '^[1-9][0-9]{0,19}$') IS DISTINCT FROM true
   OR (NEW.definition->>'expectedMethodRevision' ~ '^[1-9][0-9]{0,19}$') IS DISTINCT FROM true
   OR jsonb_typeof(NEW.definition->'expiresInSeconds') IS DISTINCT FROM 'number'
   OR (NEW.definition->>'expiresInSeconds' ~ '^[0-9]+$') IS DISTINCT FROM true
   OR (NEW.definition->>'expiresInSeconds')::numeric NOT BETWEEN 30 AND 900 THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-DEFINITION'; END IF;
  NEW.created_at:=date_trunc('milliseconds',clock_timestamp());
  NEW.expires_at:=NEW.created_at+make_interval(secs=>(NEW.definition->>'expiresInSeconds')::integer);
 ELSE
  IF clock_timestamp()>=OLD.expires_at
   OR ROW(NEW.analysis_id,NEW.participant_id,NEW.privacy_domain_id,NEW.runtime_target_id,NEW.runtime_binding_id,
     NEW.contract_method_policy_id,NEW.definition,NEW.capsule_digest,NEW.policy_generation_digest,NEW.creation_operation_id,NEW.created_at,NEW.expires_at)
   IS DISTINCT FROM ROW(OLD.analysis_id,OLD.participant_id,OLD.privacy_domain_id,OLD.runtime_target_id,OLD.runtime_binding_id,
     OLD.contract_method_policy_id,OLD.definition,OLD.capsule_digest,OLD.policy_generation_digest,OLD.creation_operation_id,OLD.created_at,OLD.expires_at)
   OR NEW.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.signed_receipt),'hex') THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-IMMUTABLE'; END IF;
  IF OLD.state='OPEN' AND OLD.revision=1 THEN
   IF current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_UPDATE_RESOURCE-V1' OR NEW.state<>'OBSERVED' OR NEW.revision<>2 THEN
    RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-IMMUTABLE'; END IF;
  ELSIF OLD.state='OBSERVED' AND OLD.revision=2 THEN
   IF current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_REVIEW_RESOURCE-V1' OR NEW.state<>'REVIEWED' OR NEW.revision<>3
    OR ROW(NEW.signed_receipt,NEW.receipt_digest,NEW.analysis_digest) IS DISTINCT FROM ROW(OLD.signed_receipt,OLD.receipt_digest,OLD.analysis_digest)
    OR NEW.review_definition->>'analysisDigest' IS DISTINCT FROM NEW.analysis_digest
    OR NEW.review_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.review_definition),'UTF8')),'hex') THEN
    RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-IMMUTABLE'; END IF;
  ELSE RAISE EXCEPTION 'PC-DATA-6004-CIGL-ANALYSIS-IMMUTABLE'; END IF;
 END IF;
 -- Share-lock the actual source owners through the mutation. A supplied digest
 -- cannot manufacture a current activation, method or workload credential.
 SELECT observation.capsule_digest,target.policy_generation_digest INTO STRICT capsule,policy
 FROM control.runtime_target target JOIN control.runtime_activation_observation observation
  ON observation.participant_id=target.participant_id AND observation.privacy_domain_id=target.privacy_domain_id
   AND observation.runtime_target_id=target.runtime_target_id AND observation.capsule_digest=target.active_generation_digest
 JOIN control.contract_runtime_binding binding ON binding.participant_id=target.participant_id
  AND binding.privacy_domain_id=target.privacy_domain_id AND binding.runtime_binding_id=NEW.runtime_binding_id
 JOIN control.contract_method_policy method ON method.participant_id=binding.participant_id AND method.privacy_domain_id=binding.privacy_domain_id
  AND method.runtime_binding_id=binding.runtime_binding_id AND method.contract_method_policy_id=NEW.contract_method_policy_id
 WHERE target.runtime_target_id=NEW.runtime_target_id AND target.participant_id=NEW.participant_id AND target.privacy_domain_id=NEW.privacy_domain_id
  AND target.state='ACTIVE_MATCHED' AND target.active_generation_digest=target.desired_generation_digest
  AND target.active_generation_digest=NEW.definition->>'expectedGenerationDigest'
  AND binding.state='BOUND' AND binding.revision::text=NEW.definition->>'expectedRuntimeBindingRevision'
  AND method.state IN ('PREPARED','ACTIVE') AND method.revision::text=NEW.definition->>'expectedMethodRevision'
  AND openpc.cigl_subject_current(NEW.participant_id,jsonb_build_object('kind','WORKLOAD','id',NEW.definition->>'workloadId'))
 FOR SHARE OF target,binding,method;
 IF TG_OP='INSERT' THEN NEW.capsule_digest:=capsule; NEW.policy_generation_digest:=policy;
 ELSIF NEW.capsule_digest<>capsule OR NEW.policy_generation_digest<>policy THEN RAISE EXCEPTION 'PC-AUTH-0005-CIGL-ANALYSIS-REFERENCE'; END IF;
 RETURN NEW;
 EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'PC-AUTH-0005-CIGL-ANALYSIS-REFERENCE';
END $_$;


ALTER FUNCTION openpc.guard_cigl_analysis() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_dependency_claim(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_dependency_claim() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-DEPENDENCY-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.lock_cigl_grant_sources();
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-CIGL_GRANTS_UPDATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state NOT IN ('RELEASED','INVALIDATED')
   OR NEW.released_operation_id IS DISTINCT FROM current_setting('openpc.operation_id')::uuid
   OR (to_jsonb(NEW)-ARRAY['state','released_at','released_operation_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','released_at','released_operation_id'])
   OR NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants changed
    WHERE changed.participant_id=NEW.participant_id AND changed.privacy_domain_id=NEW.privacy_domain_id
     AND changed.publication_operation_id=NEW.released_operation_id
     AND ((NEW.state='RELEASED' AND changed.grant_id=NEW.source_grant_id AND changed.revision>NEW.source_grant_revision)
       OR (NEW.state='INVALIDATED' AND changed.grant_id=NEW.required_grant_id AND changed.revision>NEW.required_grant_revision))) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-OWNER'; END IF;
  NEW.released_at:=clock_timestamp(); RETURN NEW;
 END IF;
 -- Retain the same physical/method and policy source fence for direct SQL as
 -- for the repository. The grant advisory lock alone does not lock a binding.
 PERFORM 1 FROM control.cigl_profile_method_source retained
  JOIN control.contract_method_policy method ON method.contract_method_policy_id=retained.contract_method_policy_id AND method.participant_id=retained.participant_id AND method.privacy_domain_id=retained.privacy_domain_id
  JOIN control.contract_runtime_binding binding ON binding.runtime_binding_id=retained.runtime_binding_id AND binding.participant_id=retained.participant_id AND binding.privacy_domain_id=retained.privacy_domain_id
  WHERE retained.profile_id=NEW.profile_id AND retained.profile_revision=NEW.profile_revision ORDER BY method.contract_method_policy_id FOR SHARE OF method,binding;
 PERFORM 1 FROM control.cigl_profile_version version JOIN control.cigl_analysis analysis ON analysis.analysis_id=version.analysis_id
  JOIN control.runtime_target target ON target.runtime_target_id=analysis.runtime_target_id
  JOIN control.runtime_activation_observation observation ON observation.runtime_target_id=target.runtime_target_id
   AND observation.participant_id=target.participant_id AND observation.privacy_domain_id=target.privacy_domain_id
   AND observation.capsule_digest=target.active_generation_digest
  JOIN control.runtime_configuration_generation generation ON generation.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
   AND generation.runtime_target_id=target.runtime_target_id
   AND generation.participant_id=target.participant_id AND generation.privacy_domain_id=target.privacy_domain_id
   AND generation.generation_digest=observation.generation_digest AND generation.state='ACTIVE'
  WHERE version.profile_id=NEW.profile_id AND version.revision=NEW.profile_revision FOR SHARE OF target,generation;
 IF NEW.state<>'ACTIVE' OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid
  OR NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants source
   JOIN control.cigl_method_access_grants required ON required.participant_id=source.participant_id AND required.privacy_domain_id=source.privacy_domain_id
   JOIN control.cigl_profile_version version ON version.profile_id=NEW.profile_id AND version.revision=NEW.profile_revision
    AND version.participant_id=source.participant_id AND version.privacy_domain_id=source.privacy_domain_id
   JOIN control.cigl_profile_dependency_path path ON path.profile_id=version.profile_id AND path.profile_revision=version.revision AND path.ordinal=NEW.ordinal
   JOIN control.cigl_analysis analysis ON analysis.analysis_id=version.analysis_id AND analysis.participant_id=source.participant_id AND analysis.privacy_domain_id=source.privacy_domain_id
   JOIN control.contract_method_policy root ON root.contract_method_policy_id=analysis.contract_method_policy_id AND root.participant_id=source.participant_id AND root.privacy_domain_id=source.privacy_domain_id
   JOIN control.runtime_target target ON target.runtime_target_id=analysis.runtime_target_id AND target.participant_id=source.participant_id AND target.privacy_domain_id=source.privacy_domain_id
   JOIN control.participant participant ON participant.participant_id=source.participant_id
   WHERE source.grant_id=NEW.source_grant_id AND source.participant_id=NEW.participant_id AND source.privacy_domain_id=NEW.privacy_domain_id
    AND source.origin='SHARED' AND source.status='ACTIVE' AND source.definition->>'effect'='ALLOW' AND source.revision=NEW.source_grant_revision
    AND source.publication_operation_id=NEW.publication_operation_id AND openpc.cigl_subject_current(source.participant_id,source.definition->'subject')
    AND required.grant_id=NEW.required_grant_id AND required.revision=NEW.required_grant_revision AND required.status='ACTIVE' AND required.definition->>'effect'='ALLOW'
    AND required.definition->'subject'=source.definition->'subject' AND required.definition->>'surface'=source.definition->>'surface'
    AND required.runtime_binding_id::text=path.document->>'runtimeBindingId'
    AND required.selector='0x'||(SELECT string_agg(lpad(to_hex(value::text::integer),2,'0'),'' ORDER BY n) FROM jsonb_array_elements(path.document->'selector') WITH ORDINALITY s(value,n))
    AND root.runtime_binding_id=source.runtime_binding_id AND root.selector=source.selector AND root.revision=source.method_revision AND root.state='ACTIVE'
    AND EXISTS(SELECT 1 FROM control.cigl_profile_method_source retained WHERE retained.profile_id=NEW.profile_id AND retained.profile_revision=NEW.profile_revision
      AND retained.contract_method_policy_id=root.contract_method_policy_id AND retained.binding_revision=source.binding_revision AND retained.method_revision=source.method_revision)
    AND EXISTS(SELECT 1 FROM control.cigl_profile_method_source retained WHERE retained.profile_id=NEW.profile_id AND retained.profile_revision=NEW.profile_revision
      AND retained.contract_method_policy_id::text=path.document->>'contractMethodPolicyId' AND retained.binding_revision=required.binding_revision AND retained.method_revision=required.method_revision)
    AND ((NEW.capability='SIMULATE_CALL' AND root.effect='READ' AND source.definition->>'surface'='ETH_CALL')
      OR (NEW.capability='EXECUTE_TRANSACTION' AND root.effect='WRITE' AND source.definition->>'surface' IN ('PREPARE_WRITE','RAW_SUBMISSION','RUNTIME_WRITE_TRACE')))
    AND version.state='COMPILED' AND version.dependency_paths_digest IS NOT NULL AND analysis.analysis_digest=NEW.graph_digest
    AND analysis.policy_generation_digest=NEW.policy_generation_digest AND target.policy_generation_digest=NEW.policy_generation_digest
    AND target.state='ACTIVE_MATCHED' AND target.active_generation_digest=target.desired_generation_digest
    AND target.active_generation_digest=analysis.definition->>'expectedGenerationDigest'
    AND participant.state='ACTIVE' AND participant.archived_at IS NULL AND participant.authority_epoch=NEW.participant_epoch
    AND EXISTS(SELECT 1 FROM control.runtime_activation_observation observation
      JOIN control.runtime_configuration_generation generation ON generation.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
      AND generation.participant_id=observation.participant_id AND generation.privacy_domain_id=observation.privacy_domain_id
      AND generation.runtime_target_id=observation.runtime_target_id AND generation.generation_digest=observation.generation_digest
      WHERE observation.participant_id=NEW.participant_id AND observation.privacy_domain_id=NEW.privacy_domain_id
      AND observation.capsule_digest=target.active_generation_digest
      AND generation.runtime_target_id=target.runtime_target_id AND generation.state='ACTIVE'
      AND generation.policy_generation_digest=NEW.policy_generation_digest)
    AND NOT EXISTS(SELECT 1 FROM control.cigl_profile_method_source retained
      LEFT JOIN control.contract_method_policy live ON live.contract_method_policy_id=retained.contract_method_policy_id AND live.participant_id=retained.participant_id AND live.privacy_domain_id=retained.privacy_domain_id
      LEFT JOIN control.contract_runtime_binding binding ON binding.runtime_binding_id=retained.runtime_binding_id AND binding.participant_id=retained.participant_id AND binding.privacy_domain_id=retained.privacy_domain_id
      WHERE retained.profile_id=version.profile_id AND retained.profile_revision=version.revision
       AND (live.contract_method_policy_id IS NULL OR live.state<>'ACTIVE' OR live.revision<>retained.method_revision
        OR binding.runtime_binding_id IS NULL OR binding.state<>'BOUND' OR binding.revision<>retained.binding_revision))
    AND NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants denial WHERE denial.participant_id=source.participant_id AND denial.privacy_domain_id=source.privacy_domain_id
      AND denial.runtime_binding_id=required.runtime_binding_id AND denial.selector=required.selector AND denial.status='ACTIVE'
      AND denial.definition->>'effect'='DENY' AND denial.definition->>'surface'=source.definition->>'surface'
      AND (denial.definition->'subject'=source.definition->'subject' OR denial.definition->'subject'='{"kind":"ANY_AUTHENTICATED"}'::jsonb))) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-SOURCE'; END IF;
 NEW.created_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_dependency_claim() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_grant(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_grant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE canonical jsonb; bytes bytea;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-GRANT-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GRANT';
 END IF;
 PERFORM openpc.lock_cigl_grant_sources();
 IF TG_OP='INSERT' THEN
  IF NEW.revision<>1 OR NOT (
   (NEW.origin='SHARED' AND current_setting('openpc.action_intent_id')='ACT-CIGL_GRANTS_CREATE_RESOURCE-V1' AND NEW.status='DISABLED')
   OR (NEW.origin='GENERATED' AND current_setting('openpc.action_intent_id')='ACT-CIGL_GRANTS_UPDATE_RESOURCE-V1' AND NEW.status='ACTIVE'
     AND NEW.definition->>'effect'='ALLOW' AND EXISTS(SELECT 1 FROM control.cigl_method_access_grants source WHERE source.grant_id=NEW.generated_by_grant_id
      AND source.participant_id=NEW.participant_id AND source.privacy_domain_id=NEW.privacy_domain_id AND source.origin='SHARED'
      AND source.status='ACTIVE' AND source.publication_operation_id=NEW.publication_operation_id))) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GRANT-CREATE'; END IF;
  NEW.created_at:=clock_timestamp();
 ELSE
  IF current_setting('openpc.action_intent_id')<>'ACT-CIGL_GRANTS_UPDATE_RESOURCE-V1'
   OR NEW.revision<>OLD.revision+1 OR (NEW.status=OLD.status AND NEW.status<>'ACTIVE')
   OR (OLD.origin='GENERATED' AND (OLD.status<>'ACTIVE' OR NEW.status<>'DISABLED'
     OR EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims WHERE required_grant_id=OLD.grant_id AND state='ACTIVE')
     OR NOT EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims WHERE required_grant_id=OLD.grant_id AND released_operation_id=NEW.publication_operation_id)))
   OR ROW(NEW.grant_id,NEW.participant_id,NEW.privacy_domain_id,NEW.runtime_binding_id,NEW.selector,NEW.definition,
      NEW.binding_revision,NEW.method_revision,NEW.created_at,NEW.origin,NEW.generated_by_grant_id)
    IS DISTINCT FROM ROW(OLD.grant_id,OLD.participant_id,OLD.privacy_domain_id,OLD.runtime_binding_id,OLD.selector,OLD.definition,
      OLD.binding_revision,OLD.method_revision,OLD.created_at,OLD.origin,OLD.generated_by_grant_id) THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-GRANT-IMMUTABLE'; END IF;
 END IF;
 IF NEW.definition->>'runtimeBindingId' IS DISTINCT FROM 'urn:openpc:resource:'||NEW.runtime_binding_id::text
  OR NEW.definition->>'selector' IS DISTINCT FROM NEW.selector OR (NEW.definition->>'effect' IN ('ALLOW','DENY')) IS DISTINCT FROM true
  OR (NEW.definition->>'surface' IN ('ETH_CALL','ETH_ESTIMATE_GAS','PREPARE_WRITE','RAW_SUBMISSION','DEPLOYMENT_CONSTRUCTOR','RUNTIME_WRITE_TRACE')) IS DISTINCT FROM true
  OR (NEW.definition-ARRAY['runtimeBindingId','selector','subject','surface','effect']) IS DISTINCT FROM '{}'::jsonb
  OR NOT (NEW.definition ?& ARRAY['runtimeBindingId','selector','subject','surface','effect']) THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-GRANT-DEFINITION'; END IF;
 IF TG_OP='INSERT' OR NEW.status='ACTIVE' THEN
  IF openpc.cigl_subject_current(NEW.participant_id,NEW.definition->'subject') IS DISTINCT FROM true
   OR NOT EXISTS(SELECT 1 FROM control.contract_runtime_binding binding JOIN control.contract_method_policy method
    ON method.participant_id=binding.participant_id AND method.privacy_domain_id=binding.privacy_domain_id AND method.runtime_binding_id=binding.runtime_binding_id
    WHERE binding.participant_id=NEW.participant_id AND binding.privacy_domain_id=NEW.privacy_domain_id
     AND binding.runtime_binding_id=NEW.runtime_binding_id AND binding.state='BOUND' AND binding.revision=NEW.binding_revision
     AND method.selector=NEW.selector AND method.revision=NEW.method_revision AND method.state IN ('PREPARED','ACTIVE')) THEN RAISE EXCEPTION 'PC-AUTH-0005-CIGL-GRANT-REFERENCE'; END IF;
 END IF;
 bytes:=decode(substr(NEW.selector,3),'hex');
 canonical:=jsonb_build_object('grantId',NEW.grant_id::text,'runtimeBindingId',NEW.runtime_binding_id::text,
  'selector',jsonb_build_array(get_byte(bytes,0),get_byte(bytes,1),get_byte(bytes,2),get_byte(bytes,3)),
  'subject',NEW.definition->'subject','surface',NEW.definition->>'surface','effect',NEW.definition->>'effect','status',NEW.status);
 IF NEW.grant_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(canonical),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'PC-DATA-6004-CIGL-GRANT-DIGEST'; END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_grant() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_grant_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_grant_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-GRANT-HISTORY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants grant_row WHERE
  ROW(grant_row.grant_id,grant_row.participant_id,grant_row.privacy_domain_id,grant_row.revision,grant_row.status,grant_row.grant_digest,
   grant_row.publication_operation_id,grant_row.publication_authority_digest)
  =ROW(NEW.grant_id,NEW.participant_id,NEW.privacy_domain_id,NEW.revision,NEW.status,NEW.grant_digest,
   NEW.publication_operation_id,NEW.publication_authority_digest)) THEN RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GRANT-HISTORY'; END IF;
 NEW.occurred_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_grant_history() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_profile_owner(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_profile_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_REVIEW_RESOURCE-V1'
  OR NOT EXISTS(SELECT 1 FROM control.cigl_analysis analysis WHERE analysis.participant_id=NEW.participant_id
    AND analysis.privacy_domain_id=NEW.privacy_domain_id AND analysis.contract_method_policy_id=NEW.root_contract_method_policy_id
    AND analysis.state='REVIEWED' AND analysis.revision=3 AND analysis.publication_operation_id=current_setting('openpc.operation_id')::uuid) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-OWNER'; END IF;
 NEW.created_at:=date_trunc('milliseconds',clock_timestamp()); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_profile_owner() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_profile_source(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_profile_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','MEMBER')
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NOT EXISTS(SELECT 1 FROM control.cigl_profile_version version JOIN control.configuration_work work
    ON work.configuration_work_id=version.configuration_work_id AND work.participant_id=version.participant_id AND work.privacy_domain_id=version.privacy_domain_id
    WHERE version.profile_id=NEW.profile_id AND version.revision=NEW.profile_revision AND version.participant_id=NEW.participant_id
     AND version.privacy_domain_id=NEW.privacy_domain_id AND version.state='PENDING' AND work.state='LEASED' AND work.lease_until>clock_timestamp()) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-SOURCE'; END IF;
 IF TG_TABLE_NAME='cigl_profile_grant_source' THEN
  IF NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants grant_row WHERE grant_row.grant_id=NEW.grant_id
   AND grant_row.participant_id=NEW.participant_id AND grant_row.privacy_domain_id=NEW.privacy_domain_id
   AND grant_row.revision=NEW.grant_revision AND grant_row.grant_digest=NEW.grant_digest) THEN RAISE EXCEPTION 'PC-DATA-6007-CIGL-PROFILE-GRANT'; END IF;
 ELSIF TG_TABLE_NAME='cigl_profile_method_source' THEN
  IF NOT EXISTS(SELECT 1 FROM control.contract_method_policy method JOIN control.contract_runtime_binding binding
   ON binding.runtime_binding_id=method.runtime_binding_id AND binding.participant_id=method.participant_id AND binding.privacy_domain_id=method.privacy_domain_id
   WHERE method.contract_method_policy_id=NEW.contract_method_policy_id AND method.participant_id=NEW.participant_id
    AND method.privacy_domain_id=NEW.privacy_domain_id AND binding.runtime_binding_id=NEW.runtime_binding_id
    AND method.revision=NEW.method_revision AND binding.revision=NEW.binding_revision) THEN RAISE EXCEPTION 'PC-DATA-6007-CIGL-PROFILE-METHOD'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM control.cigl_profile_method_source method WHERE method.profile_id=NEW.profile_id
    AND method.profile_revision=NEW.profile_revision AND method.contract_method_policy_id::text=NEW.document->>'contractMethodPolicyId'
    AND method.runtime_binding_id::text=NEW.document->>'runtimeBindingId') THEN RAISE EXCEPTION 'PC-DATA-6007-CIGL-PROFILE-PATH'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_profile_source() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_profile_version(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_profile_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE claims jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-HISTORY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-SCOPE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PENDING' OR current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_REVIEW_RESOURCE-V1'
   OR NOT EXISTS(SELECT 1 FROM control.cigl_analysis analysis JOIN control.cigl_method_profile profile
     ON profile.participant_id=analysis.participant_id AND profile.privacy_domain_id=analysis.privacy_domain_id
      AND profile.root_contract_method_policy_id=analysis.contract_method_policy_id
     JOIN control.configuration_work work ON work.configuration_work_id=NEW.configuration_work_id
      AND work.participant_id=analysis.participant_id AND work.privacy_domain_id=analysis.privacy_domain_id
      AND work.resource_id=analysis.analysis_id AND work.operation_id=analysis.publication_operation_id
      AND work.work_kind='CIGL_PROFILE_COMPILATION' AND work.state='PENDING'
     WHERE analysis.analysis_id=NEW.analysis_id AND analysis.participant_id=NEW.participant_id
      AND analysis.privacy_domain_id=NEW.privacy_domain_id AND profile.profile_id=NEW.profile_id
      AND analysis.state='REVIEWED' AND analysis.revision=3 AND analysis.review_digest=NEW.review_digest
      AND analysis.publication_operation_id=current_setting('openpc.operation_id')::uuid)
   OR NEW.revision<>(SELECT coalesce(max(revision),0)+1 FROM control.cigl_profile_version WHERE profile_id=NEW.profile_id) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-REVIEW'; END IF;
  NEW.created_at:=date_trunc('milliseconds',clock_timestamp());
 ELSE
  IF NOT pg_has_role(current_user,'openpc_control_worker','MEMBER') OR OLD.state<>'PENDING' OR NEW.state<>'COMPILED'
   OR (to_jsonb(NEW)-ARRAY['state','profile_cbor','profile_digest','artifact_digest','compilation_receipt','compilation_signer_id','compiled_at','dependency_paths_digest'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','profile_cbor','profile_digest','artifact_digest','compilation_receipt','compilation_signer_id','compiled_at','dependency_paths_digest'])
   OR NEW.artifact_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.profile_cbor),'hex') THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-IMMUTABLE'; END IF;
  claims:=convert_from(NEW.compilation_receipt,'UTF8')::jsonb;
  IF claims->>'purpose' IS DISTINCT FROM 'openpc:cigl-profile-compilation:v1' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-RECEIPT'; END IF;
  claims:=claims->'claims';
  IF claims->>'schemaVersion' IS DISTINCT FROM '1.0' OR claims->>'profileId' IS DISTINCT FROM NEW.profile_id::text
   OR claims->>'profileRevision' IS DISTINCT FROM NEW.revision::text OR claims->>'analysisId' IS DISTINCT FROM NEW.analysis_id::text
   OR claims->>'configurationWorkId' IS DISTINCT FROM NEW.configuration_work_id::text
   OR claims->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR claims->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR claims->>'reviewDigest' IS DISTINCT FROM substr(NEW.review_digest,8) OR claims->>'artifactDigest' IS DISTINCT FROM substr(NEW.artifact_digest,8)
   OR claims->>'profileDigest' IS DISTINCT FROM substr(NEW.profile_digest,8) OR claims->>'signerId' IS DISTINCT FROM NEW.compilation_signer_id
   OR NEW.dependency_paths_digest IS NULL
   OR claims->>'dependencyPathsDigest' IS DISTINCT FROM substr(NEW.dependency_paths_digest,8)
   OR NEW.dependency_paths_digest IS DISTINCT FROM (SELECT 'sha256:'||encode(sha256(convert_to(
     openpc.signing_canonical_json(coalesce(jsonb_agg(path.document ORDER BY path.ordinal),'[]'::jsonb)),'UTF8')),'hex')
     FROM control.cigl_profile_dependency_path path WHERE path.profile_id=NEW.profile_id AND path.profile_revision=NEW.revision)
   OR claims->>'compiledAtMs' IS DISTINCT FROM floor(extract(epoch from NEW.compiled_at)*1000)::text
   OR NEW.compiled_at<NEW.created_at OR NEW.compiled_at>clock_timestamp()
   OR NOT EXISTS(SELECT 1 FROM control.configuration_work work JOIN control.cigl_analysis analysis ON analysis.analysis_id=NEW.analysis_id
      AND analysis.participant_id=work.participant_id AND analysis.privacy_domain_id=work.privacy_domain_id
     WHERE work.configuration_work_id=NEW.configuration_work_id AND work.state='LEASED' AND work.lease_owner=NEW.compilation_signer_id
      AND work.lease_until>clock_timestamp() AND analysis.expires_at>clock_timestamp()
      AND claims->>'operationId'=work.operation_id::text AND claims->>'targetRuntimeId'=analysis.runtime_target_id::text
      AND claims->>'capsuleDigest'=substr(analysis.capsule_digest,8) AND claims->>'analysisDigest'=substr(analysis.analysis_digest,8)
      AND claims->>'policyGenerationDigest'=substr(analysis.policy_generation_digest,8)) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-RECEIPT'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_profile_version() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_profile_work(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_cigl_profile_work() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.work_kind='CIGL_PROFILE_COMPILATION' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-HISTORY'; END IF;
  RETURN OLD;
 END IF;
 IF NEW.work_kind<>'CIGL_PROFILE_COMPILATION' THEN
  IF TG_OP='UPDATE' AND OLD.work_kind='CIGL_PROFILE_COMPILATION' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-WORK'; END IF;
  RETURN NEW;
 END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.execution_started_at IS NOT NULL OR NEW.execution_attempt_id IS NOT NULL OR NEW.state='RECONCILING' THEN RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-WORK'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PENDING' OR NEW.attempt_count<>0 OR NEW.operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-CIGL_ANALYSES_REVIEW_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-WORK'; END IF;
 ELSE
  IF NOT pg_has_role(current_user,'openpc_control_worker','MEMBER') OR OLD.state IN ('COMPLETED','FAILED')
   OR ROW(NEW.configuration_work_id,NEW.participant_id,NEW.privacy_domain_id,NEW.operation_id,NEW.work_kind,NEW.resource_id,
     NEW.input_digest,NEW.configuration_digest,NEW.runtime_configuration_generation_id,NEW.runtime_target_id,NEW.generation_digest,NEW.predecessor_digest,
     NEW.policy_generation_digest,NEW.xds_version_digest,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.configuration_work_id,OLD.participant_id,OLD.privacy_domain_id,OLD.operation_id,OLD.work_kind,OLD.resource_id,
     OLD.input_digest,OLD.configuration_digest,OLD.runtime_configuration_generation_id,OLD.runtime_target_id,OLD.generation_digest,OLD.predecessor_digest,
     OLD.policy_generation_digest,OLD.xds_version_digest,OLD.created_at)
   OR (NEW.state='LEASED' AND NOT ((OLD.state='PENDING' OR (OLD.state='LEASED' AND OLD.lease_until<=clock_timestamp())) AND NEW.attempt_count=OLD.attempt_count+1))
   OR (NEW.state<>'LEASED' AND (OLD.state<>'LEASED' OR OLD.lease_until<=clock_timestamp() OR NEW.attempt_count<>OLD.attempt_count))
   OR (NEW.state IN ('COMPLETED','FAILED') AND NEW.result_receipt_digest IS DISTINCT FROM
     'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.result_receipt),'UTF8')),'hex')) THEN
   RAISE EXCEPTION 'PC-DATA-6004-CIGL-PROFILE-WORK'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_cigl_profile_work() OWNER TO openpc_control_owner;

--
-- Name: guard_cigl_settings(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

