ALTER FUNCTION openpc.guard_contract_runtime_binding_registration() OWNER TO openpc_control_owner;

--
-- Name: guard_denied_predecessor_work_link(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_denied_predecessor_work_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cursor_row control.runtime_denied_predecessor;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.denied_predecessor_work_id IS DISTINCT FROM OLD.denied_predecessor_work_id
   THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-LINK-IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.work_kind<>'RUNTIME_ACTIVATION' THEN
  IF NEW.denied_predecessor_work_id IS NOT NULL THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-KIND'; END IF;
  RETURN NEW;
 END IF;
 -- Direct queue inserts must not bypass the candidate's unresolved-cursor fence.
 IF EXISTS(SELECT 1 FROM control.runtime_denied_predecessor c
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.runtime_target_id=NEW.runtime_target_id)
 THEN PERFORM openpc.runtime_installed_predecessor(NEW.runtime_target_id); END IF;
 SELECT * INTO cursor_row FROM openpc.runtime_denied_predecessor(NEW.runtime_target_id);
 IF NEW.denied_predecessor_work_id IS NULL THEN
  IF FOUND THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-LINK-REQUIRED'; END IF;
 ELSE
  IF NOT FOUND OR NEW.denied_predecessor_work_id IS DISTINCT FROM cursor_row.configuration_work_id
   OR NEW.participant_id IS DISTINCT FROM cursor_row.participant_id
   OR NEW.privacy_domain_id IS DISTINCT FROM cursor_row.privacy_domain_id
   OR NEW.predecessor_digest IS DISTINCT FROM cursor_row.capsule_digest
   OR NEW.created_at<cursor_row.created_at OR NEW.state<>'PENDING'
   OR NEW.execution_attempt_id IS NOT NULL OR NEW.execution_started_at IS NOT NULL
   OR openpc.current_action_intent_id()<>'ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'
   OR current_setting('transaction_isolation')<>'serializable'
  THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-LINK'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_denied_predecessor_work_link() OWNER TO openpc_control_owner;

--
-- Name: guard_deployment_address_reservation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_deployment_address_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed_at timestamptz:=date_trunc('milliseconds',clock_timestamp());
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'DELETE' THEN
  PERFORM openpc.lock_deployment_command(NEW.command_id);
  IF EXISTS(SELECT 1 FROM control.deployment_result result WHERE result.command_id=NEW.command_id
   AND convert_from(result.signed_bytes,'UTF8')::jsonb->>'purpose'='openpc:deployment-reservation-rejection:v1')
  THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'RESERVED' OR NEW.handoff_at IS NOT NULL OR NEW.expired_at IS NOT NULL OR NEW.expires_at<=observed_at THEN
   RAISE EXCEPTION 'PC-DATA-6004';
  END IF;
  IF NEW.predecessor_command_id IS NOT NULL THEN
   -- A new approved command can share only the exact still-held original
   -- address/nonce custody. This is not a pending-chain or send assertion.
   PERFORM 1 FROM control.deployment_address_reservation prior
    JOIN control.mutation_candidate original ON original.consumed_operation_id=prior.command_id
     AND original.participant_id=prior.participant_id AND original.privacy_domain_id=prior.privacy_domain_id
     AND original.state='CONSUMED' AND original.catalog_operation_id='CFG-OP-SUBMIT-DEPLOYMENT'
    JOIN control.mutation_candidate successor ON successor.consumed_operation_id=NEW.command_id
     AND successor.participant_id=NEW.participant_id AND successor.privacy_domain_id=NEW.privacy_domain_id
     AND successor.state='CONSUMED' AND successor.catalog_operation_id='CFG-OP-SUBMIT-DEPLOYMENT'
     AND successor.maker_principal_id=original.maker_principal_id
     AND successor.candidate_document->>'predecessorOperationId'='urn:openpc:operation:'||prior.command_id::text
    WHERE prior.command_id=NEW.predecessor_command_id AND prior.predecessor_command_id IS NULL
     AND prior.state='HANDOFF' AND prior.participant_id=NEW.participant_id AND prior.privacy_domain_id=NEW.privacy_domain_id
     AND ROW(prior.target_runtime_id,prior.chain_id,prior.genesis_digest,prior.contract_address,prior.helper_address,
      prior.sender_address,prior.sender_nonce,prior.creator_address,prior.mechanism,prior.salt_namespace_digest,prior.effective_salt,
      prior.artifact_digest,prior.init_code_hash,prior.profile_digest,prior.generation_digest,
      prior.native_value_authorization_id,prior.native_value_authorization_digest)
      IS NOT DISTINCT FROM ROW(NEW.target_runtime_id,NEW.chain_id,NEW.genesis_digest,NEW.contract_address,NEW.helper_address,
      NEW.sender_address,NEW.sender_nonce,NEW.creator_address,NEW.mechanism,NEW.salt_namespace_digest,NEW.effective_salt,
      NEW.artifact_digest,NEW.init_code_hash,NEW.profile_digest,NEW.generation_digest,
      NEW.native_value_authorization_id,NEW.native_value_authorization_digest)
     AND prior.transaction_hash<>NEW.transaction_hash FOR UPDATE OF prior;
   IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  END IF;
  NEW.created_at:=observed_at;
 ELSIF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'PC-DATA-6004';
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','handoff_at','expired_at']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','handoff_at','expired_at']) OR OLD.state<>'RESERVED' THEN
   RAISE EXCEPTION 'PC-DATA-6004';
  END IF;
  IF NEW.state='HANDOFF' AND NEW.sender_nonce IS NOT NULL AND OLD.expires_at>observed_at AND NEW.expired_at IS NULL THEN
   NEW.handoff_at:=observed_at;
  ELSIF NEW.state='EXPIRED' AND OLD.expires_at<=observed_at AND NEW.handoff_at IS NULL THEN
   NEW.expired_at:=observed_at;
  ELSE
   RAISE EXCEPTION 'PC-DATA-6004';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_deployment_address_reservation() OWNER TO openpc_control_owner;

--
-- Name: guard_deployment_intent(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_deployment_intent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE document jsonb; source jsonb; captured jsonb;
BEGIN
 IF TG_OP IS DISTINCT FROM 'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 PERFORM openpc.assert_request_context(true);
 document:=convert_from(NEW.preparation_bytes,'UTF8')::jsonb;
 source:=convert_from(NEW.publication_bytes,'UTF8')::jsonb;
 captured:=document->'context';
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('module-admission:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 IF NEW.module_generation_digest IS NULL OR NEW.module_generation_digest IS DISTINCT FROM
   openpc.deployment_module_generation(NEW.participant_id,NEW.privacy_domain_id)
 THEN RAISE EXCEPTION 'PC-AUTH-0002-DEPLOYMENT-MODULE-GENERATION'; END IF;
 IF NEW.participant_id IS DISTINCT FROM current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id IS DISTINCT FROM current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.creation_operation_id IS DISTINCT FROM current_setting('openpc.operation_id')::uuid
  OR current_setting('openpc.action_intent_id') IS DISTINCT FROM 'ACT-DEPLOYMENT_INTENTS_CREATE_RESOURCE-V1'
  OR document->>'schemaVersion' IS DISTINCT FROM 'PC-DEPLOYMENT-PREPARATION-1'
  OR captured->>'intentId' IS DISTINCT FROM NEW.deployment_intent_id::text
  OR captured->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR captured->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR captured->>'actorSubjectId' IS DISTINCT FROM coalesce(NEW.execution_principal_id,NEW.actor_principal_id)::text
  OR captured->>'workloadBindingId' IS DISTINCT FROM NEW.execution_workload_id
  OR (NEW.execution_principal_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM control.principal principal JOIN control.credential credential USING(participant_id,principal_id)
   WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=NEW.execution_principal_id
    AND principal.kind='WORKLOAD' AND principal.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS'
    AND credential.audience=NEW.execution_workload_id AND credential.state='ACTIVE'
    AND credential.valid_from<=clock_timestamp() AND credential.valid_until>clock_timestamp()))
  OR captured->>'walletBindingId' IS DISTINCT FROM NEW.wallet_binding_id::text
  OR captured->>'targetRuntimeId' IS DISTINCT FROM NEW.runtime_target_id::text
  OR document->>'deploymentPolicyId' IS DISTINCT FROM NEW.deployment_policy_id::text
  OR NEW.creation_authority_digest IS DISTINCT FROM 'sha256:'||(captured->>'authorityDigest')
  OR NEW.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.preparation_bytes),'hex')
  OR NEW.intent_digest IS DISTINCT FROM 'sha256:'||(document->'intent'->>'semanticDigest')
  OR document->>'publicationDigest' IS DISTINCT FROM encode(sha256(NEW.publication_bytes),'hex')
  OR NEW.expires_at IS DISTINCT FROM to_timestamp((captured->>'expiresAtMs')::numeric/1000)
  OR NEW.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION 'PC-AUTH-0002-DEPLOYMENT-INTENT';
 END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_deployment_intent() OWNER TO openpc_control_owner;

--
-- Name: guard_deployment_policy(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_deployment_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-DEPLOYMENT_POLICIES_CREATE_RESOURCE-V1'
  OR NEW.definition_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.definition),'UTF8')),'hex')
  OR (NEW.definition->>'expiresAt')::timestamptz<=clock_timestamp() THEN
  RAISE EXCEPTION 'PC-AUTH-0002-DEPLOYMENT-PUBLICATION';
 END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_deployment_policy() OWNER TO openpc_control_owner;

--
-- Name: guard_deployment_result(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_deployment_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE reservation control.deployment_address_reservation%ROWTYPE; envelope jsonb; claims jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 PERFORM openpc.assert_request_context(true);
 envelope:=convert_from(NEW.signed_bytes,'UTF8')::jsonb; claims:=envelope->'claims';
 IF envelope->>'purpose'='openpc:deployment-reservation-rejection:v1' THEN
  PERFORM openpc.validate_deployment_rejection(NEW);
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT reservation FROM control.deployment_address_reservation
  WHERE command_id=NEW.command_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR UPDATE;
 IF reservation.state<>'HANDOFF' OR envelope->>'purpose' IS DISTINCT FROM 'openpc:deployment-journal-projection:v1'
  OR claims->>'schema' IS DISTINCT FROM 'PC-DEPLOYMENT-JOURNAL-PROJECTION-1'
  OR claims->'owner'->>'participant_id' IS DISTINCT FROM NEW.participant_id::text
  OR claims->'owner'->>'privacy_domain_id' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR 'urn:openpc:resource:'||(claims->>'targetRuntimeId') IS DISTINCT FROM reservation.target_runtime_id
  OR claims->>'sequence' IS DISTINCT FROM NEW.sequence::text
  OR claims->>'intentDigest' IS DISTINCT FROM substring(reservation.intent_digest from 8)
  OR claims->>'preparationDigest' IS DISTINCT FROM substring(reservation.prepared_record_digest from 8)
  OR claims->>'chainId' IS DISTINCT FROM reservation.chain_id
  OR claims->>'genesisDigest' IS DISTINCT FROM substring(reservation.genesis_digest from 8)
  OR claims->'status'->>'operationId' IS DISTINCT FROM 'urn:openpc:operation:'||NEW.command_id::text
  OR claims->'status'->>'attemptId' IS DISTINCT FROM reservation.attempt_id::text
  OR claims->'status'->>'signedTransactionHash' IS DISTINCT FROM reservation.transaction_hash
  OR (claims->>'observedAt')::timestamptz>clock_timestamp()+interval '5 seconds'
  OR EXISTS(SELECT 1 FROM control.deployment_result result WHERE result.command_id=NEW.command_id AND result.sequence>=NEW.sequence)
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_deployment_result() OWNER TO openpc_control_owner;

--
-- Name: guard_deployment_sender_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_deployment_sender_custody() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.sender_nonce IS NULL OR EXISTS(
   SELECT 1 FROM control.deployment_address_reservation held
   WHERE held.chain_id=NEW.chain_id AND held.genesis_digest=NEW.genesis_digest
    AND held.sender_address=NEW.sender_address AND held.sender_nonce IS NULL AND held.state<>'EXPIRED') THEN
  RAISE EXCEPTION 'PC-DATA-6004';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_deployment_sender_custody() OWNER TO openpc_control_owner;

--
-- Name: guard_directory_connector(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_directory_connector() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'display_name'-'state'-'mass_change_threshold'-'external_group_freshness_seconds'-'row_version'-'updated_at'-'last_mutation_operation_id') IS DISTINCT FROM
     (to_jsonb(OLD)-'display_name'-'state'-'mass_change_threshold'-'external_group_freshness_seconds'-'row_version'-'updated_at'-'last_mutation_operation_id') OR
     OLD.state='RETIRED' OR NEW.row_version<>OLD.row_version+1 THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-TRANSITION';
  END IF;
 ELSIF NEW.state<>'ACTIVE' OR NEW.row_version<>1 THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-INITIAL-STATE';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_directory_connector() OWNER TO openpc_control_owner;

--
-- Name: guard_directory_group_mapping(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_directory_group_mapping() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-GROUP-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'provider_version'-'provider_modified_at'-'source_digest'-'source_member_ids'-'observed_at'-'fresh_until'-'row_version'-'last_mutation_operation_id'-'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD)-'provider_version'-'provider_modified_at'-'source_digest'-'source_member_ids'-'observed_at'-'fresh_until'-'row_version'-'last_mutation_operation_id'-'updated_at') OR
     NEW.row_version<>OLD.row_version+1 OR NEW.observed_at<OLD.observed_at OR NEW.provider_modified_at<OLD.provider_modified_at OR
     (NEW.provider_version=OLD.provider_version AND NEW.source_digest<>OLD.source_digest) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-GROUP-TRANSITION';
  END IF;
 ELSE
  IF NEW.row_version<>1 OR EXISTS (SELECT FROM control.authority_group_member WHERE participant_id=NEW.participant_id AND authority_group_id=NEW.authority_group_id AND state IN ('ACTIVE','SUSPENDED'))
   OR EXISTS (SELECT FROM control.assignment WHERE participant_id=NEW.participant_id AND authority_group_id=NEW.authority_group_id AND state IN ('ACTIVE','SUSPENDED')) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-GROUP-INITIAL-STATE';
  END IF;
 END IF;
 IF NEW.observed_at>clock_timestamp() OR NEW.provider_modified_at>clock_timestamp() OR
  (SELECT count(DISTINCT value) FROM unnest(NEW.source_member_ids) value)<>cardinality(NEW.source_member_ids) OR
  NOT EXISTS (SELECT FROM control.directory_connector c JOIN control.authority_group g ON g.participant_id=c.participant_id
    WHERE c.participant_id=NEW.participant_id AND c.connector_id=NEW.connector_id AND c.state='ACTIVE' AND c.profile_digest=NEW.profile_digest
      AND g.authority_group_id=NEW.authority_group_id AND g.state='ACTIVE'
      AND NEW.fresh_until=NEW.observed_at+make_interval(secs=>c.external_group_freshness_seconds)
      AND NEW.observed_at>=clock_timestamp()-make_interval(secs=>least(300,c.external_group_freshness_seconds))) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-GROUP-SOURCE';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_directory_group_mapping() OWNER TO openpc_control_owner;

--
-- Name: guard_directory_group_member(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_directory_group_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF EXISTS (SELECT FROM control.directory_group_mapping WHERE participant_id=NEW.participant_id AND authority_group_id=NEW.authority_group_id) AND
  NOT EXISTS (SELECT FROM control.directory_group_mapping g JOIN control.directory_member m ON m.participant_id=g.participant_id AND m.connector_id=g.connector_id
   WHERE g.participant_id=NEW.participant_id AND g.authority_group_id=NEW.authority_group_id AND m.principal_id=NEW.principal_id AND m.state='LINKED'
    AND m.external_id=ANY(g.source_member_ids) AND openpc.directory_group_permits(g.participant_id,g.authority_group_id)) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-GROUP-MEMBER';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_directory_group_member() OWNER TO openpc_control_owner;

--
-- Name: guard_directory_member(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_directory_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-MEMBER-TOMBSTONE'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'state'-'provider_version'-'provider_modified_at'-'observed_at'-'source_digest'-'row_version'-'updated_at'-'last_mutation_operation_id') IS DISTINCT FROM
     (to_jsonb(OLD)-'state'-'provider_version'-'provider_modified_at'-'observed_at'-'source_digest'-'row_version'-'updated_at'-'last_mutation_operation_id') OR
     OLD.state='OFFBOARDED' OR NEW.row_version<>OLD.row_version+1 OR NEW.provider_modified_at<OLD.provider_modified_at OR NEW.observed_at<OLD.observed_at OR
     (NEW.provider_version=OLD.provider_version AND NEW.source_digest<>OLD.source_digest) THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-MEMBER-TRANSITION';
  END IF;
 ELSIF NEW.state<>'LINKED' OR NEW.row_version<>1 THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-MEMBER-INITIAL-STATE';
 END IF;
 IF NOT EXISTS (SELECT FROM control.principal p JOIN control.participant_membership m ON m.participant_id=p.participant_id AND m.membership_id=p.principal_id
    JOIN control.credential c ON c.participant_id=p.participant_id AND c.principal_id=p.principal_id
    WHERE p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id AND p.kind='USER' AND c.credential_id=NEW.oidc_credential_id AND c.kind='OIDC_SUBJECT') THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-DIRECTORY-MEMBER-BINDING';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_directory_member() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_approval_resume_completed(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_approval_resume_completed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
  IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at'])
   OR stored.state IS DISTINCT FROM 'APPROVAL_REQUESTED' OR stored.consumed_operation_id IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM control.idempotency_record resume JOIN control.approval_request approval
    ON approval.participant_id=resume.participant_id AND approval.privacy_domain_id=resume.privacy_domain_id
     AND approval.subject_type='CONFIGURATION_CANDIDATE' AND approval.subject_id=stored.mutation_candidate_id
    WHERE resume.participant_id=stored.participant_id AND resume.privacy_domain_id=stored.privacy_domain_id
     AND resume.operation_id=stored.resume_operation_id AND resume.terminal_state='COMMITTED'
     AND resume.expected_aggregate_version::text=stored.resume_request->>'expectedRevision'
     AND resume.principal_id=stored.maker_principal_id AND resume.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
     AND resume.catalog_operation_id='LEGACY' AND approval.state='OPEN' AND approval.row_version=1
     AND approval.subject_digest=stored.candidate_digest AND approval.subject_version=stored.expected_revision
     AND approval.action_intent_id=stored.action_intent_id AND approval.maker_principal_id=stored.maker_principal_id
     AND approval.checker_principal_id<>stored.maker_principal_id AND approval.expires_at=stored.expires_at
     AND resume.result_payload->>'resourceRef'='urn:openpc:resource:'||approval.approval_request_id::text)
  THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  PERFORM openpc.assert_discovery_approval_resume(stored);
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_discovery_approval_resume_completed() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_approval_resume_final(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_approval_resume_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE stored control.mutation_candidate;
BEGIN
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
  IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at'])
   OR stored.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR stored.consumed_operation_id IS NOT NULL
  THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
  PERFORM openpc.assert_discovery_approval_resume(stored);
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_discovery_approval_resume_final() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_approval_resume_target_claims(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_approval_resume_target_claims() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE c control.platform_recovery_case; stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.resume_request->>'command' IS DISTINCT FROM 'RESUME' THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
 IF (to_jsonb(stored)-ARRAY['state','updated_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','updated_at']) OR stored.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR stored.consumed_operation_id IS NOT NULL THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT c FROM control.platform_recovery_case
  WHERE recovery_id=(SELECT e.recovery_case_id FROM control.authority_envelope e WHERE e.participant_id=NEW.participant_id AND e.authority_envelope_id=NEW.maker_authority_envelope_id AND e.principal_id=NEW.maker_principal_id AND e.representation='RECOVERY_V1') AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
   AND state='ACTIVE' AND valid_from<=clock_timestamp() AND valid_until>clock_timestamp()
   AND intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' AND intent->>'schemaVersion'='2';
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.resource_id::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorCredentialId}'
  OR NEW.candidate_document IS DISTINCT FROM jsonb_build_object('replacedCredentialId',NEW.resource_id::text,
    'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
    'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
  OR NEW.expected_revision::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorRevision}'
  OR NEW.maker_principal_id::text IS DISTINCT FROM c.intent#>>'{administrators,0,principalId}'
  OR NEW.state NOT IN ('PROPOSED','APPROVAL_REQUESTED') OR NEW.consumed_operation_id IS NOT NULL OR NEW.predecessor_candidate_id IS NULL
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF EXISTS(SELECT 1 FROM control.discovery_certificate_issuance i WHERE i.participant_id=c.participant_id
    AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuer_attempt a JOIN control.discovery_certificate_issuance i
    ON i.participant_id=a.participant_id AND i.issuance_id=a.issuance_id WHERE i.participant_id=c.participant_id
     AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
      OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- A clock advance may have hidden all target rows through their RLS basis.
 -- Reauthenticate the SAME case/source after the scan before any success.
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_case fresh WHERE fresh.recovery_id=c.recovery_id
   AND fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id AND fresh.state='ACTIVE'
   AND fresh.enrollment_id=c.enrollment_id AND fresh.enrollment_revision=c.enrollment_revision
   AND fresh.enrollment_digest=c.enrollment_digest AND fresh.intent=c.intent
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp())
  OR NEW.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_approval_resume_target_claims() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_certificate_issuance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_certificate_issuance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE intent jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 SELECT c.intent INTO intent FROM control.platform_recovery_case c WHERE c.recovery_id=NEW.recovery_id
  and c.participant_id=NEW.participant_id and c.privacy_domain_id=NEW.privacy_domain_id;
 IF intent IS NULL or intent->>'schema'<>'pc.identity.discovery-certificate-recovery-intent'
  or NEW.request_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.request),'UTF8'))
  or NEW.predecessor_credential_id::text IS DISTINCT FROM intent#>>'{certificateRecovery,predecessorCredentialId}'
  or NEW.successor_credential_id::text IS DISTINCT FROM intent#>>'{certificateRecovery,successorCredentialId}'
  or NEW.request IS DISTINCT FROM jsonb_build_object('credentialId',NEW.successor_credential_id::text,
   'participantId',NEW.participant_id::text,'principalId',intent#>>'{certificateRecovery,workloadPrincipalId}',
   'workloadId','urn:openpc:workload:'||(intent#>>'{certificateRecovery,targetId}'),
   'publicKeySpkiDer',intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' or NEW.row_version<>1 or NOT EXISTS(select 1 from control.mutation_candidate candidate
    join control.approval_request approval on approval.participant_id=candidate.participant_id
     and approval.privacy_domain_id=candidate.privacy_domain_id and approval.subject_id=candidate.mutation_candidate_id
     and approval.subject_digest=candidate.candidate_digest and approval.subject_version=candidate.expected_revision
     and approval.maker_principal_id=candidate.maker_principal_id and approval.state='APPROVED'
     and approval.expires_at>clock_timestamp() and approval.approval_request_id=NEW.approval_request_id
    join control.authority_envelope envelope on envelope.participant_id=candidate.participant_id
     and envelope.authority_envelope_id=candidate.maker_authority_envelope_id and envelope.recovery_case_id=NEW.recovery_id
     and envelope.representation='RECOVERY_V1' and openpc.platform_recovery_envelope_current(envelope.authority_envelope_id)
    where candidate.participant_id=NEW.participant_id and candidate.privacy_domain_id=NEW.privacy_domain_id
     and candidate.mutation_candidate_id=NEW.mutation_candidate_id and candidate.candidate_digest=NEW.candidate_digest
     and candidate.state='APPROVED' and candidate.expires_at>clock_timestamp()
     and candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
     and candidate.resource_id=NEW.predecessor_credential_id
     and candidate.expected_revision=(intent#>>'{certificateRecovery,predecessorRevision}')::numeric
     and candidate.candidate_document=jsonb_build_object('replacedCredentialId',NEW.predecessor_credential_id::text,
       'credentialId',NEW.successor_credential_id::text,'publicKeySpkiDer',intent#>>'{certificateRecovery,successorPublicKeySpkiDer}'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 ELSE
  IF NEW.row_version<>OLD.row_version+1 or NEW.updated_at<=OLD.updated_at
   or (to_jsonb(NEW)-ARRAY['state','row_version','updated_at','certificate_der','certificate_fingerprint','failure_code','committed_operation_id'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','row_version','updated_at','certificate_der','certificate_fingerprint','failure_code','committed_operation_id'])
   or NOT ((OLD.state='PREPARED' and NEW.state IN ('ISSUING','REJECTED'))
     or (OLD.state='ISSUING' and NEW.state IN ('OBSERVED','AMBIGUOUS','REJECTED'))
     or (OLD.state='AMBIGUOUS' and NEW.state='ISSUING' and OLD.replay_profile='IMMUTABLE_REQUEST_RESPONSE')
     or (OLD.state='OBSERVED' and NEW.state='COMMITTED'))
   or (OLD.state='OBSERVED' and (NEW.certificate_der,NEW.certificate_fingerprint) IS DISTINCT FROM (OLD.certificate_der,OLD.certificate_fingerprint))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 END IF;
 IF NEW.state='COMMITTED' and (NEW.committed_operation_id IS DISTINCT FROM openpc.current_operation_id()
  or NOT EXISTS(select 1 from control.credential successor join control.credential predecessor
    on predecessor.participant_id=successor.participant_id and predecessor.credential_id=NEW.predecessor_credential_id
   where successor.participant_id=NEW.participant_id and successor.credential_id=NEW.successor_credential_id
    and successor.rotated_from_credential_id=predecessor.credential_id and predecessor.state='REVOKED'
    and successor.state='ACTIVE' and successor.kind='WORKLOAD_MTLS' and successor.certificate_der=NEW.certificate_der
    and successor.secret_fingerprint=NEW.certificate_fingerprint)) THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_certificate_issuance() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_certificate_issuance_attempt_phase(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_certificate_issuance_attempt_phase() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE attempt control.discovery_certificate_issuer_attempt;
BEGIN
 IF TG_OP='INSERT' THEN RETURN NEW; END IF;
 SELECT * INTO attempt FROM control.discovery_certificate_issuer_attempt a WHERE a.participant_id=NEW.participant_id
  and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id ORDER BY a.sequence DESC LIMIT 1;
 IF NEW.state IN ('ISSUING','AMBIGUOUS','OBSERVED','COMMITTED') and NOT FOUND THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='ISSUING' and (attempt.state<>'ISSUING' or attempt.deadline<=clock_timestamp()
  or attempt.preparation_operation_id IS DISTINCT FROM openpc.current_operation_id()) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='AMBIGUOUS' and (attempt.state<>'AMBIGUOUS' or NEW.failure_code IS DISTINCT FROM attempt.failure_code) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state IN ('OBSERVED','COMMITTED') and (attempt.state<>'OBSERVED'
  or NEW.certificate_fingerprint IS DISTINCT FROM attempt.certificate_fingerprint) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='REJECTED' and OLD.state='ISSUING' and attempt.state<>'REJECTED' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_certificate_issuance_attempt_phase() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_certificate_issuer_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_certificate_issuer_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE issuance control.discovery_certificate_issuance;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 SELECT * INTO issuance FROM control.discovery_certificate_issuance i WHERE i.issuance_id=NEW.issuance_id
  and i.participant_id=NEW.participant_id and i.privacy_domain_id=NEW.privacy_domain_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ISSUING' or NEW.row_version<>1 or NEW.preparation_operation_id IS DISTINCT FROM openpc.current_operation_id()
   or NEW.sequence<>(select coalesce(max(a.sequence),0)+1 from control.discovery_certificate_issuer_attempt a
    where a.participant_id=NEW.participant_id and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id)
   or NEW.sequence>10 or EXISTS(select 1 from control.discovery_certificate_issuer_attempt a
    where a.participant_id=NEW.participant_id and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id and a.state='ISSUING')
   or NOT ((NEW.sequence=1 and issuance.state='PREPARED')
     or (NEW.sequence>1 and issuance.state='AMBIGUOUS' and issuance.replay_profile='IMMUTABLE_REQUEST_RESPONSE'
       and current_setting('openpc.local_qa_runtime',true)='1'))
   or NOT EXISTS(select 1 from control.mutation_candidate candidate
    join control.approval_request approval on approval.participant_id=candidate.participant_id
     and approval.privacy_domain_id=candidate.privacy_domain_id and approval.subject_id=candidate.mutation_candidate_id
     and approval.subject_digest=candidate.candidate_digest and approval.subject_version=candidate.expected_revision
     and approval.maker_principal_id=candidate.maker_principal_id and approval.approval_request_id=issuance.approval_request_id
     and approval.subject_type='CONFIGURATION_CANDIDATE' and approval.state='APPROVED' and approval.expires_at>clock_timestamp()
    join control.authority_envelope maker on maker.participant_id=candidate.participant_id
     and maker.authority_envelope_id=candidate.maker_authority_envelope_id and maker.representation='RECOVERY_V1'
     and maker.recovery_case_id=issuance.recovery_id and openpc.platform_recovery_envelope_current(maker.authority_envelope_id)
    join control.platform_recovery_case recovery on recovery.participant_id=maker.participant_id
     and recovery.recovery_id=maker.recovery_case_id and recovery.privacy_domain_id=candidate.privacy_domain_id and recovery.state='ACTIVE'
    join control.session session on session.participant_id=candidate.participant_id and session.session_id=candidate.maker_session_id
     and session.principal_id=candidate.maker_principal_id and session.session_epoch=candidate.maker_session_epoch
     and session.authority_epoch=candidate.maker_principal_epoch and session.participant_epoch=candidate.maker_participant_epoch
     and session.context_mode='PLATFORM' and session.privacy_domain_id is null and session.state='ACTIVE'
     and session.idle_expires_at>clock_timestamp() and session.absolute_expires_at>clock_timestamp()
    join control.approval_decision_record decision on decision.participant_id=approval.participant_id
     and decision.approval_request_id=approval.approval_request_id and decision.decision='APPROVE'
     and decision.approver_principal_id<>candidate.maker_principal_id and decision.candidate_digest=candidate.candidate_digest
     and decision.aggregate_version=candidate.expected_revision and decision.evidence_cbor=NEW.authorization_evidence_cbor
     and decision.cose_sign1=NEW.authorization_cose
    join control.authority_envelope checker on checker.participant_id=decision.participant_id
     and checker.authority_envelope_id=decision.approver_authority_envelope_id and checker.representation='RECOVERY_V1'
     and checker.recovery_case_id=recovery.recovery_id and openpc.platform_recovery_envelope_current(checker.authority_envelope_id)
    join control.mfa_challenge challenge on challenge.participant_id=candidate.participant_id
     and challenge.principal_id=candidate.maker_principal_id and challenge.session_id=candidate.maker_session_id
     and challenge.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' and challenge.resource_digest=candidate.candidate_digest
     and (case when session.step_up_mfa_challenge_id is null
       then challenge.consumed_at>clock_timestamp()-interval '5 minutes'
       else session.step_up_mfa_challenge_id=challenge.mfa_challenge_id
         and openpc.session_step_up_valid_until(challenge.participant_id,challenge.session_id,challenge.principal_id)>clock_timestamp()
       end) and challenge.used_at is null
    join control.mutation_evidence verification on verification.participant_id=challenge.participant_id
     and verification.privacy_domain_id=candidate.privacy_domain_id and verification.principal_id=candidate.maker_principal_id
     and verification.mfa_challenge_id=challenge.mfa_challenge_id and verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
     and verification.aggregate_type='webauthn-verification' and verification.aggregate_id=challenge.session_id
     and verification.webauthn_assertion_binding_digest=NEW.webauthn_assertion_binding_digest
    join control.idempotency_record verified on verified.participant_id=verification.participant_id
     and verified.privacy_domain_id=verification.privacy_domain_id and verified.operation_id=verification.operation_id
     and verified.catalog_operation_id=verification.catalog_operation_id and verified.input_digest=verification.candidate_digest
     and verified.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest and verified.terminal_state='COMMITTED'
    join control.outbox_event event on event.participant_id=verification.participant_id and event.privacy_domain_id=verification.privacy_domain_id
     and event.aggregate_type=verification.aggregate_type and event.aggregate_id=verification.aggregate_id
     and event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
     and event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
     and event.payload_cbor=verification.evidence_cbor and event.payload_digest=verification.evidence_digest and event.cose_sign1=verification.cose_sign1
    where candidate.participant_id=issuance.participant_id and candidate.privacy_domain_id=issuance.privacy_domain_id
     and candidate.mutation_candidate_id=issuance.mutation_candidate_id and candidate.state='APPROVED' and candidate.expires_at>clock_timestamp()
     and candidate.candidate_digest=issuance.candidate_digest and candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
     and candidate.idempotency_key=NEW.idempotency_key and candidate.maker_principal_id=NEW.maker_principal_id
     and candidate.maker_session_id=NEW.maker_session_id and NEW.started_at<=clock_timestamp() and NEW.deadline>clock_timestamp()
     and NEW.deadline<=least(recovery.valid_until,approval.expires_at,candidate.expires_at,challenge.expires_at,
       session.idle_expires_at,session.absolute_expires_at,
       case when session.step_up_mfa_challenge_id is null then challenge.consumed_at+interval '5 minutes'
         else coalesce(openpc.session_step_up_valid_until(challenge.participant_id,challenge.session_id,challenge.principal_id),'-infinity'::timestamptz) end)
     and (issuance.replay_profile<>'IMMUTABLE_REQUEST_RESPONSE' or (current_setting('openpc.local_qa_runtime',true)='1'
      and exists(select 1 from control.platform_recovery_enrollment enrollment where enrollment.enrollment_id=recovery.enrollment_id
       and enrollment.participant_id=recovery.participant_id and enrollment.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'))))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 ELSE
  IF OLD.state<>'ISSUING' or NEW.state NOT IN ('AMBIGUOUS','OBSERVED','REJECTED') or NEW.row_version<>OLD.row_version+1
   or (to_jsonb(NEW)-ARRAY['state','row_version','finished_at','certificate_fingerprint','failure_code']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','row_version','finished_at','certificate_fingerprint','failure_code'])
   or (NEW.failure_code='CLAIM_EXPIRED' and OLD.deadline>clock_timestamp())
   or NEW.finished_at>clock_timestamp() THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_certificate_issuer_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_certificate_recovery_case(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_certificate_recovery_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE source control.platform_recovery_enrollment;
BEGIN
 IF NEW.intent->>'schema'<>'pc.identity.discovery-certificate-recovery-intent' THEN RETURN NEW; END IF;
 -- Historical closure preserves the immutable case and activation bytes under
 -- the shared guard. Completion retains its current administrator checks.
 SELECT * INTO source FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=NEW.enrollment_id
  and e.participant_id=NEW.participant_id and e.privacy_domain_id=NEW.privacy_domain_id;
 IF NOT FOUND or source.document->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-enrollment'
  or NEW.intent->>'schemaVersion' not in ('1','2')
  or (NEW.state NOT IN ('REVOKED','EXPIRED') and NEW.intent->>'schemaVersion'='2'
   and NOT openpc.discovery_certificate_resume_administrators_current(NEW.enrollment_id))
  or NEW.intent->'certificateRecovery' IS DISTINCT FROM source.document->'certificateRecovery'
  or NEW.intent-ARRAY['schema','schemaVersion','recoveryId','enrollmentId','enrollmentRevision','enrollmentDigest',
    'certificateRecovery','administrators','validFrom','validUntil','lifetimes']<>'{}'::jsonb
  or NOT (NEW.intent ?& ARRAY['certificateRecovery','administrators','lifetimes'])
  or NEW.planned_record_ids<>'[]'::jsonb THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state IN ('DRAFT','REQUESTED','ACTIVE') and (NOT openpc.discovery_certificate_recovery_current(NEW.enrollment_id,null)
  or NOT openpc.discovery_certificate_recovery_administrators_current(NEW.enrollment_id,NEW.intent->'administrators',
   case when NEW.state='ACTIVE' then NEW.lease_bindings else null end)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state='ACTIVE' and (jsonb_array_length(NEW.lease_bindings)<>2
  or (select count(distinct binding->>'principalId') from jsonb_array_elements(NEW.lease_bindings) binding)<>2
  or EXISTS(select 1 from jsonb_array_elements(NEW.lease_bindings) binding where NOT
    openpc.discovery_certificate_recovery_binding_current(NEW.intent,NEW.privacy_domain_id,binding,NEW.activated_at,NEW.valid_until))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state='COMPLETED' and (NEW.completion_operation_id IS DISTINCT FROM openpc.current_operation_id()
  or NOT EXISTS(select 1 from control.discovery_certificate_issuance issuance where issuance.participant_id=NEW.participant_id
   and issuance.privacy_domain_id=NEW.privacy_domain_id and issuance.recovery_id=NEW.recovery_id and issuance.state='COMMITTED'
   and issuance.committed_operation_id=NEW.completion_operation_id
   and NEW.completion_result=jsonb_build_object('issuanceId',issuance.issuance_id::text,'operationId',issuance.committed_operation_id::text,
    'predecessorCredentialId',issuance.predecessor_credential_id::text,'successorCredentialId',issuance.successor_credential_id::text,
    'certificateFingerprint','sha256:'||encode(issuance.certificate_fingerprint,'hex')))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_certificate_recovery_case() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_preapproval_final(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_preapproval_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.resume_request->>'command'='DISCOVERY_PREAPPROVAL_CONTINUE' THEN
  PERFORM openpc.assert_discovery_preapproval_continuation(NEW);
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_preapproval_final() OWNER TO openpc_control_owner;

--
-- Name: guard_discovery_preapproval_target_claims(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_discovery_preapproval_target_claims() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE c control.platform_recovery_case; stored control.mutation_candidate;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'mutation_candidate' OR TG_OP<>'INSERT'
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 IF NEW.resume_request->>'command' IS DISTINCT FROM 'DISCOVERY_PREAPPROVAL_CONTINUE' THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id() IS DISTINCT FROM NEW.action_intent_id THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
 IF to_jsonb(stored) IS DISTINCT FROM to_jsonb(NEW) THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 SELECT * INTO STRICT c FROM control.platform_recovery_case
  WHERE recovery_id::text=NEW.resume_request->>'recoveryId' AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)
   AND state='ACTIVE' AND valid_from<=clock_timestamp() AND valid_until>clock_timestamp()
   AND intent->>'schema'='pc.identity.discovery-certificate-recovery-intent';
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NEW.catalog_operation_id<>'ID-OP-WORKLOAD-ROTATE' OR NEW.action_intent_id<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.resource_id::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorCredentialId}'
  OR NEW.candidate_document IS DISTINCT FROM jsonb_build_object('replacedCredentialId',NEW.resource_id::text,
    'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
    'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
  OR NEW.expected_revision::text IS DISTINCT FROM c.intent#>>'{certificateRecovery,predecessorRevision}'
  OR NEW.maker_principal_id::text IS DISTINCT FROM c.intent#>>'{administrators,0,principalId}'
  OR NEW.state<>'PROPOSED' OR NEW.consumed_operation_id IS NOT NULL OR NEW.predecessor_candidate_id IS NULL
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF EXISTS(SELECT 1 FROM control.discovery_certificate_issuance i WHERE i.participant_id=c.participant_id
    AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
     OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
  OR EXISTS(SELECT 1 FROM control.discovery_certificate_issuer_attempt a JOIN control.discovery_certificate_issuance i
    ON i.participant_id=a.participant_id AND i.issuance_id=a.issuance_id WHERE i.participant_id=c.participant_id
     AND (i.predecessor_credential_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
      OR i.successor_credential_id::text=c.intent#>>'{certificateRecovery,successorCredentialId}'))
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 -- A clock advance may have hidden all target rows through their RLS basis.
 -- Reauthenticate the SAME case/source after the scan before any success.
 PERFORM * FROM openpc.lock_discovery_certificate_recovery_source(c.enrollment_id,c.recovery_id);
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_case fresh WHERE fresh.recovery_id=c.recovery_id
   AND fresh.participant_id=c.participant_id AND fresh.privacy_domain_id=c.privacy_domain_id AND fresh.state='ACTIVE'
   AND fresh.enrollment_id=c.enrollment_id AND fresh.enrollment_revision=c.enrollment_revision
   AND fresh.enrollment_digest=c.enrollment_digest AND fresh.intent=c.intent
   AND fresh.valid_from<=clock_timestamp() AND fresh.valid_until>clock_timestamp())
  OR NEW.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_discovery_preapproval_target_claims() OWNER TO openpc_control_owner;

--
-- Name: guard_envelope_platform_binding(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_envelope_platform_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.platform_context_id IS DISTINCT FROM OLD.platform_context_id
   OR NEW.platform_authority_epoch IS DISTINCT FROM OLD.platform_authority_epoch THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_envelope_platform_binding() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_custody() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE head control.evidence_stream%ROWTYPE; segment control.evidence_segment%ROWTYPE;
 prior control.evidence_checkpoint%ROWTYPE; expected jsonb; payload_size integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' AND TG_TABLE_NAME='evidence_catalogue' THEN
  PERFORM openpc.record_projection_deletion(OLD,'SEARCH_PROJECTION',openpc.evidence_catalogue_projection(OLD));
  RETURN OLD;
 END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND TG_TABLE_NAME<>'evidence_stream') THEN
  RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW';
 END IF;
 IF TG_TABLE_NAME='evidence_stream' AND TG_OP='UPDATE'
  AND current_setting('openpc.action_intent_id') IN ('ACT-EVIDENCE_DELETIONS_CREATE_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_BATCH-V1') THEN
  PERFORM openpc.assert_evidence_deletion_accounting(OLD,NEW);
  RETURN NEW;
 END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN
  RAISE EXCEPTION 'PC-AUTH-0005';
 END IF;
 IF TG_TABLE_NAME='evidence_stream' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
  IF TG_OP='INSERT' THEN
   IF NEW.last_sequence<>0 OR NEW.last_segment_digest IS NOT NULL OR NEW.used_bytes<>0 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE
   IF (to_jsonb(NEW)-ARRAY['last_sequence','last_segment_digest','used_bytes']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['last_sequence','last_segment_digest','used_bytes']) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   SELECT * INTO segment FROM control.evidence_segment WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND first_sequence=OLD.last_sequence+1;
   IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   SELECT octet_length(p.encrypted_segment) INTO payload_size FROM control.evidence_segment_payload p
    WHERE p.participant_id=segment.participant_id AND p.privacy_domain_id=segment.privacy_domain_id
     AND p.stream_id=segment.stream_id AND p.segment_id=segment.segment_id;
   IF NOT FOUND OR NEW.last_sequence<>segment.through_sequence OR NEW.last_segment_digest<>segment.object_digest
    OR NEW.used_bytes<>OLD.used_bytes+payload_size THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO head FROM control.evidence_stream WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_TABLE_NAME='evidence_segment' THEN
  IF NEW.first_sequence<>head.last_sequence+1 OR NEW.previous_segment_digest IS DISTINCT FROM head.last_segment_digest
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.admitted_at:=clock_timestamp();
 ELSIF TG_TABLE_NAME='evidence_catalogue' THEN
  IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
   AND r.data_class='SEARCH_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO segment FROM control.evidence_segment WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
  IF NOT FOUND OR NEW.sequence NOT BETWEEN segment.first_sequence AND segment.through_sequence THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  SELECT * INTO segment FROM control.evidence_segment WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
  IF NOT FOUND OR NEW.through_sequence<>segment.through_sequence OR NEW.object_digest<>segment.object_digest THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO prior FROM control.evidence_checkpoint WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND sink_id=NEW.sink_id ORDER BY through_sequence DESC LIMIT 1;
  IF segment.first_sequence<>coalesce(prior.through_sequence,0)+1 OR NEW.previous_checkpoint_digest IS DISTINCT FROM prior.checkpoint_digest THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1' THEN
   PERFORM openpc.assert_remote_archive_checkpoint(NEW);
  ELSE
  IF EXISTS(SELECT 1 FROM control.evidence_archive_trust t WHERE t.participant_id=NEW.participant_id
   AND t.privacy_domain_id=NEW.privacy_domain_id AND t.sink_id=NEW.sink_id)
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  expected:=jsonb_build_object('object',jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
   'streamId',NEW.stream_id,'sinkId',NEW.sink_id,'segmentId',NEW.segment_id::text,'objectDigest',NEW.object_digest,
   'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,'previousSegmentDigest',segment.previous_segment_digest,
   'keyId',segment.key_id,'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
   'versionId',NEW.object_digest,'assurance','LOCAL_FSYNC_READBACK');
  IF NEW.receipt-'receiptDigest' IS DISTINCT FROM expected OR NEW.receipt->>'receiptDigest' IS DISTINCT FROM NEW.receipt_digest
   OR NEW.receipt_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  END IF;
  expected:=jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
   'streamId',NEW.stream_id,'sinkId',NEW.sink_id,'segmentId',NEW.segment_id::text,'throughSequence',NEW.through_sequence::text,
   'objectDigest',NEW.object_digest,'previousCheckpointDigest',NEW.previous_checkpoint_digest,'receiptDigest',NEW.receipt_digest);
  IF NEW.checkpoint_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.acknowledged_at:=clock_timestamp();
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_custody() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_deletion_item(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_deletion_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND pg_trigger_depth()=2 AND NEW.protected_object_id IS NOT NULL
  AND openpc.raw_proof_deletion_item_matches(NEW) THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>2
  OR NOT EXISTS(SELECT 1 FROM control.deletion_job j JOIN control.evidence_segment_payload p
   ON p.participant_id=j.participant_id AND p.privacy_domain_id=j.privacy_domain_id AND p.segment_id=j.segment_id
   WHERE j.participant_id=NEW.participant_id AND j.privacy_domain_id=NEW.privacy_domain_id
    AND j.deletion_job_id=NEW.deletion_job_id AND j.operation_id=current_setting('openpc.operation_id')::uuid
    AND j.state='EXECUTING' AND j.segment_id=NEW.segment_id AND j.selection->>'objectDigest'=NEW.object_digest
    AND p.ciphertext_bytes=NEW.ciphertext_bytes)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_deletion_item() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_deletion_job(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_deletion_job() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE plan jsonb; item control.evidence_deletion_item%ROWTYPE; current_bytes bigint;
BEGIN
 IF TG_OP<>'DELETE' AND NEW.selection->>'version'='OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1' THEN
  RETURN openpc.guard_runtime_artifact_deletion_job(TG_OP,OLD,NEW);
 END IF;
 IF TG_OP<>'DELETE' AND NEW.selection->>'version'='OPENPC_PROJECTION_DELETION_BATCH_V1' THEN
  RETURN openpc.guard_projection_deletion_job(TG_OP,OLD,NEW);
 END IF;
 IF TG_OP<>'DELETE' AND NEW.selection->>'version'='OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN
  RETURN openpc.guard_raw_proof_deletion_job(TG_OP,OLD,NEW);
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id') IS DISTINCT FROM openpc.evidence_deletion_action(NEW.selection)
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.operation_id<>current_setting('openpc.operation_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT used_bytes INTO STRICT current_bytes FROM control.evidence_stream
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
  NEW.previous_deletion_job_id:=right(NEW.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  IF NEW.previous_deletion_job_id IS NOT NULL THEN
   PERFORM 1 FROM control.deletion_job WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
    AND deletion_job_id=NEW.previous_deletion_job_id FOR UPDATE;
  END IF;
  plan:=openpc.evidence_deletion_selection_plan(NEW.selection);
  IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM NEW.selection
   OR plan->>'beforeDigest' IS DISTINCT FROM NEW.before_digest OR NEW.state<>'EXECUTING' OR NEW.revision<>0
   OR NEW.retention_policy_id<>right(NEW.selection->>'retentionPolicyId',36)::uuid
   OR NEW.stream_id<>NEW.selection->>'streamId' OR NEW.segment_id<>(NEW.selection->>'segmentId')::uuid
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.target_selector_digest:=openpc.evidence_deletion_selector_digest(NEW.selection);
  NEW.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.selection),'UTF8')),'hex');
  NEW.before_used_bytes:=current_bytes;NEW.after_used_bytes:=NULL;
  NEW.started_at:=clock_timestamp();NEW.created_at:=NEW.started_at;
 ELSE
  IF OLD.state<>'EXECUTING' OR NEW.state<>'SUCCEEDED' OR OLD.revision<>0 OR NEW.revision<>1
   OR (to_jsonb(NEW)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.evidence_deletion_item WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND deletion_job_id=NEW.deletion_job_id;
  IF item.segment_id<>NEW.segment_id OR item.object_digest<>NEW.selection->>'objectDigest'
   OR current_bytes<>NEW.before_used_bytes-item.ciphertext_bytes
   OR EXISTS(SELECT 1 FROM control.evidence_segment_payload WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND segment_id=NEW.segment_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.deleted_count:=1;NEW.deleted_bytes:=item.ciphertext_bytes;NEW.after_used_bytes:=current_bytes;
  NEW.after_digest:=openpc.evidence_deletion_after_digest(NEW.target_selector_digest);
  NEW.completed_at:=clock_timestamp();
 END IF;
 NEW.updated_at:=clock_timestamp();RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_deletion_job() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_deployment_lineage(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_deployment_lineage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT openpc.evidence_deployment_lineage_projection(c) INTO expected FROM control.evidence_catalogue c
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id;
 IF expected IS NULL OR NEW.projection IS DISTINCT FROM expected
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_deployment_lineage() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_deployment_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_deployment_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source control.evidence_catalogue; expected jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id
   AND privacy_domain_id=OLD.privacy_domain_id AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT source FROM control.evidence_catalogue WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.record_id;
 expected:=openpc.evidence_deployment_projection(source);
 IF expected IS NULL OR NEW.projection IS DISTINCT FROM expected
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_deployment_provenance() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_export_completion_preparation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_export_completion_preparation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c jsonb; source jsonb; installed control.evidence_export_producer_installation; expected jsonb; now_ns numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='UPDATE' THEN
  IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
   OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
   OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
   OR NOT ((OLD.state='PREPARED' AND NEW.state='OBSERVED' AND OLD.cose_sign1 IS NULL AND NEW.cose_sign1 IS NOT NULL)
    OR (OLD.state='OBSERVED' AND NEW.state='PUBLISHED' AND OLD.cose_sign1 IS NOT NULL AND NEW.cose_sign1=OLD.cose_sign1))
   OR to_jsonb(NEW)-ARRAY['state','cose_sign1'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','cose_sign1']
  THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
  -- A direct UPDATE already owns a row lock. Never wait in reverse order.
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
  source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
  IF source->>'streamId' IS DISTINCT FROM NEW.stream_id OR
   source-'streamId' IS DISTINCT FROM NEW.claims-ARRAY['environmentId','eventId','sourceId','sequence','recordedAtNs','dataDigest','authoritySnapshotDigest','signerTrustSnapshotDigest','signerKeyId']
  THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
  PERFORM openpc.archive_cose_binding(NEW.receipt_payload,NEW.cose_sign1,NEW.claims->>'signerKeyId',24013,350);
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 OR NEW.state<>'PREPARED' OR NEW.cose_sign1 IS NOT NULL
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT installed FROM control.evidence_export_producer_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND trust_digest=NEW.trust_digest AND state='ACTIVE';
 IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
 source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
 c:=NEW.claims;
 expected:=(source-'streamId')||jsonb_build_object(
  'environmentId',installed.environment_id,'eventId',NEW.event_id::text,'sourceId',installed.source_id::text,
  'sequence','1','recordedAtNs',c->>'recordedAtNs','dataDigest','sha256:'||encode(sha256(NEW.source_data),'hex'),
  'authoritySnapshotDigest','sha256:'||encode(sha256(NEW.authority_snapshot),'hex'),
  'signerTrustSnapshotDigest',installed.trust_digest,'signerKeyId',installed.signer_id);
 IF c IS DISTINCT FROM expected OR source->>'streamId' IS DISTINCT FROM NEW.stream_id
 OR coalesce(c->>'recordedAtNs','')!~'^[1-9][0-9]{0,19}$'
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
 now_ns:=floor(extract(epoch from clock_timestamp())*1000000)*1000;
 IF (c->>'recordedAtNs')::numeric>now_ns OR (c->>'recordedAtNs')::numeric<now_ns-5000000000
 OR mod((c->>'recordedAtNs')::numeric,1000)<>0
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-TIME'; END IF;
 IF openpc.business_cbor(NEW.source_data) IS DISTINCT FROM jsonb_build_object(
  '0','urn:openpc:resource:'||NEW.evidence_export_id::text,'1',(source->>'checkpoint')::numeric,
  '2',openpc.business_bytes(decode(substr(source->>'outputDigest',8),'hex')),'3',(source->>'recordCount')::numeric)
 OR openpc.business_cbor(NEW.receipt_payload) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('ee72df3cca5024c26c52c5983b15087426b4faabeb511cace227b92a04d2eb8f','hex')),'1',c->>'environmentId','2',openpc.business_uuid((c->>'participantId')::uuid),'3',openpc.business_uuid((c->>'privacyDomainId')::uuid),'4',openpc.business_uuid((c->>'eventId')::uuid),'5',openpc.business_uuid((c->>'sourceId')::uuid),'6',openpc.business_uuid((c->>'evidenceExportId')::uuid),'7',openpc.business_uuid((c->>'startOperationId')::uuid),'8',openpc.business_uuid((c->>'causationId')::uuid),'9',(c->>'sequence')::numeric,'10',(c->>'recordedAtNs')::numeric,'11',openpc.business_bytes(decode(substr(c->>'requestDigest',8),'hex')),'12',(c->>'checkpoint')::numeric,'13',openpc.business_bytes(decode(substr(c->>'outputDigest',8),'hex')),'14',(c->>'recordCount')::numeric,'15',openpc.business_bytes(decode(substr(c->>'dataDigest',8),'hex')),'16',openpc.business_bytes(decode(substr(c->>'authoritySnapshotDigest',8),'hex')),'17',openpc.business_bytes(decode(substr(c->>'signerTrustSnapshotDigest',8),'hex')),'18',c->>'signerKeyId')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-PAYLOAD'; END IF;
 expected:=jsonb_build_object('specversion','1.0','id',NEW.event_id::text,'source','urn:openpc:service:'||installed.source_id::text,
  'type','io.openpc.evidence.export.completed.v1','subject','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'time',to_char(to_timestamp(floor((c->>'recordedAtNs')::numeric/1000000000)::double precision) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'.'||lpad(mod((c->>'recordedAtNs')::numeric/1000,1000000)::bigint::text,6,'0')||'Z',
  'datacontenttype','application/json','dataschema','https://schemas.openpc.local/event-payloads.schema.json#/$defs/EvidenceExportCompleted',
  'participantid','urn:openpc:participant:'||NEW.participant_id::text,'privacydomainid','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'correlationid',source->>'startOperationId','causationid',source->>'causationId','sequence','1','datadigest',c->>'dataDigest',
  'data',jsonb_build_object('evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,'checkpoint',source->>'checkpoint','outputDigest',source->>'outputDigest','recordCount',source->>'recordCount'));
 IF NEW.event_payload IS DISTINCT FROM convert_to(openpc.signing_canonical_json(expected),'UTF8')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-EVENT'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_evidence_export_completion_preparation() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_export_output(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_export_output() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE request control.evidence_export_request%ROWTYPE; v_selection jsonb; records jsonb; artifact jsonb; assurance text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT request FROM control.evidence_export_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND evidence_export_id=NEW.evidence_export_id FOR UPDATE;
 IF request.state NOT IN ('RUNNING','BACKLOGGED') OR request.start_operation_id<>current_setting('openpc.operation_id')::uuid
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT s.selection INTO STRICT v_selection FROM control.evidence_export_selection s WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=request.request_digest;
 assurance:=CASE WHEN EXISTS(SELECT 1 FROM control.evidence_archive_trust t WHERE t.participant_id=NEW.participant_id
   AND t.privacy_domain_id=NEW.privacy_domain_id AND t.sink_id=NEW.sink_id)
   THEN 'REMOTE_INTERFACE_VERIFIED' ELSE 'LOCAL_FSYNC_READBACK' END;
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN
  PERFORM openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),NEW.stream_id);
 END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId',r->>'evidenceId','sequence',r->>'sequence',
   'evidenceClass',r->>'evidenceClass','recordDigest',r->>'recordDigest','occurredAt',r->>'occurredAt',
   'segmentDigest',r->>'objectDigest','checkpointDigest',c.checkpoint_digest) ORDER BY (r->>'sequence')::numeric)
 INTO records FROM jsonb_array_elements(v_selection->'records') r JOIN control.evidence_checkpoint c
   ON c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
    AND c.segment_id=(r->>'segmentId')::uuid AND c.object_digest=r->>'objectDigest' AND c.sink_id=NEW.sink_id
    AND c.receipt->>'assurance'=assurance
    AND (assurance='LOCAL_FSYNC_READBACK' OR (c.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1'
      AND openpc.remote_archive_covers(c.participant_id,c.privacy_domain_id,c.stream_id,c.segment_id,c.sink_id)
      AND EXISTS(SELECT 1 FROM control.evidence_archive_receipt ar JOIN control.evidence_archive_outbox ao
       USING(participant_id,privacy_domain_id,receipt_id) WHERE ar.participant_id=c.participant_id
        AND ar.privacy_domain_id=c.privacy_domain_id AND ar.receipt_digest=c.receipt_digest
        AND ar.receipt_id::text=c.receipt->>'receiptId' AND ar.profile_digest=c.receipt->>'profileDigest')));
 IF records IS NULL OR jsonb_array_length(records)<>jsonb_array_length(v_selection->'records')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 artifact:=jsonb_build_object('version','OPENPC_EVIDENCE_REDACTED_EXPORT_V1',
  'evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'participantId','urn:openpc:participant:'||NEW.participant_id::text,
  'privacyDomainId','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'requestDigest',request.request_digest,'range',v_selection->'range','sinkId',NEW.sink_id,
  'assurance',assurance,'records',records);
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN artifact:=artifact||jsonb_build_object('providerQualification','NOT_ESTABLISHED'); END IF;
 IF NEW.artifact<>convert_to(openpc.signing_canonical_json(artifact),'UTF8')
  OR NEW.output_digest<>'sha256:'||encode(sha256(NEW.artifact),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_export_output() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_export_producer_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_export_producer_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t jsonb;
BEGIN
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EXPORT-PRODUCER-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
   OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- A direct UPDATE already has its row lock. Do not wait in reverse order.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
   IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
   THEN RAISE EXCEPTION 'DATA-6020-EXPORT-PRODUCER-IMMUTABLE'; END IF;
   RETURN NEW;
 END IF;
 t:=NEW.trust;
 IF NEW.state<>'ACTIVE' OR jsonb_typeof(t) IS DISTINCT FROM 'object'
   OR t - ARRAY['schema','schemaDefinitionDigest','owner','purpose','environmentId','participantId','privacyDomainId','sourceId','principalId','workloadCredentialId','workloadEpoch','workloadId','secretClass','secretReference','secretVersion','publicKeySpkiHex','keyEpoch','validFromNs','validUntilNs','installationReference','signerKeyId'] IS DISTINCT FROM '{}'::jsonb
   OR (SELECT count(*) FROM jsonb_object_keys(t))<>21
   OR t->>'schema' IS DISTINCT FROM 'pc.evidence-export.producer-trust.v1'
   OR t->>'schemaDefinitionDigest' IS DISTINCT FROM 'sha256:ee72df3cca5024c26c52c5983b15087426b4faabeb511cace227b92a04d2eb8f'
   OR t->>'owner' IS DISTINCT FROM 'LS-EVIDENCE-EXPORT'
   OR t->>'purpose' IS DISTINCT FROM 'pc.cose.evidence-export-completion-receipt.v1'
   OR t->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
   OR t->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR t->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR t->>'sourceId' IS DISTINCT FROM NEW.source_id::text
   OR t->>'principalId' IS DISTINCT FROM NEW.principal_id::text
   OR t->>'workloadCredentialId' IS DISTINCT FROM NEW.workload_credential_id::text
   OR t->>'workloadEpoch' IS DISTINCT FROM NEW.workload_epoch::text
   OR t->>'environmentId' IS DISTINCT FROM NEW.environment_id
   OR t->>'signerKeyId' IS DISTINCT FROM NEW.signer_id
   OR EXISTS(SELECT 1 FROM jsonb_each(t) e WHERE jsonb_typeof(e.value)<>'string' OR e.value#>>'{}'<>btrim(e.value#>>'{}'))
   OR NOT coalesce(t->>'environmentId' ~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$',false)
   OR NOT coalesce(t->>'secretReference' ~ '^secret://[a-z][a-z0-9-]{1,31}/[A-Za-z0-9._/-]{1,192}#[A-Za-z0-9._-]{1,96}$',false)
   OR split_part(t->>'secretReference','#',2) IS DISTINCT FROM t->>'secretVersion'
   OR lower(t->>'secretVersion') IN ('latest','current')
   OR length(t->>'workloadId') NOT BETWEEN 1 AND 160 OR length(t->>'installationReference') NOT BETWEEN 1 AND 256
   OR NEW.trust_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8')
   OR NEW.signer_id IS DISTINCT FROM 'sha256:'||encode(sha256(decode(t->>'publicKeySpkiHex','hex')),'hex')
   OR NOT coalesce(t->>'publicKeySpkiHex' ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
   OR NOT coalesce(t->>'keyEpoch' ~ '^[1-9][0-9]{0,19}$',false)
   OR NOT coalesce(t->>'validFromNs' ~ '^(0|[1-9][0-9]{0,19})$',false)
   OR NOT coalesce(t->>'validUntilNs' ~ '^[1-9][0-9]{0,19}$',false)
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PRODUCER-TRUST'; END IF;
 IF (t->>'keyEpoch')::numeric>18446744073709551615 OR (t->>'validUntilNs')::numeric>18446744073709551615
   OR (t->>'validFromNs')::numeric>=(t->>'validUntilNs')::numeric
   OR mod((t->>'validFromNs')::numeric,1000)<>0 OR mod((t->>'validUntilNs')::numeric,1000)<>0
   OR NOT EXISTS(SELECT 1 FROM control.credential c WHERE c.participant_id=NEW.participant_id
      AND c.credential_id=NEW.workload_credential_id AND c.principal_id=NEW.principal_id
      AND c.kind='WORKLOAD_MTLS' AND c.audience=t->>'workloadId'
      AND c.credential_epoch=NEW.workload_epoch
      AND c.public_key_digest<>decode(substr(NEW.signer_id,8),'hex'))
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PRODUCER-IDENTITY'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_evidence_export_producer_installation() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_export_request(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_export_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action text; operation uuid; v_through_sequence numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 action:=current_setting('openpc.action_intent_id'); operation:=current_setting('openpc.operation_id')::uuid;
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF action<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1' OR NEW.creation_operation_id<>operation
   OR NEW.last_operation_id<>operation OR NEW.state<>'REQUESTED' OR NEW.start_operation_id IS NOT NULL
   OR NEW.revision<>1 OR NEW.checkpoint<>0 OR NEW.output_digest IS NOT NULL OR NEW.last_error_code IS NOT NULL
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE
  IF NEW.revision<>OLD.revision+1 OR NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id
   OR NEW.evidence_export_id<>OLD.evidence_export_id OR NEW.created_at<>OLD.created_at OR NEW.creation_operation_id<>OLD.creation_operation_id
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF action='ACT-EVIDENCE_EXPORTS_UPDATE_RESOURCE-V1' THEN
   IF OLD.state<>'REQUESTED' OR NEW.state<>'REQUESTED' OR NEW.request_digest=OLD.request_digest
    OR NEW.last_operation_id<>operation OR NEW.last_error_code IS NOT NULL
    OR (to_jsonb(NEW)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND OLD.state='REQUESTED' THEN
   IF NEW.state<>'RUNNING' OR NEW.last_operation_id<>operation OR NEW.start_operation_id<>operation
    OR (to_jsonb(NEW)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND pg_has_role(current_user,'openpc_control_worker','USAGE') THEN
   IF OLD.state NOT IN ('RUNNING','BACKLOGGED') OR NEW.state NOT IN ('SUCCEEDED','FAILED','BACKLOGGED')
    OR operation<>OLD.start_operation_id OR
    (to_jsonb(NEW)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   IF NEW.state='SUCCEEDED' THEN
    SELECT (selection->'range'->>'throughSequence')::numeric INTO v_through_sequence FROM control.evidence_export_selection
     WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=NEW.request_digest;
    IF NEW.checkpoint IS DISTINCT FROM v_through_sequence OR NEW.last_error_code IS NOT NULL OR NOT EXISTS
     (SELECT 1 FROM control.evidence_export_output WHERE evidence_export_id=NEW.evidence_export_id
       AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND output_digest=NEW.output_digest)
    THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   ELSIF NEW.last_error_code IS DISTINCT FROM 'PC-OPS-9002' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.updated_at:=clock_timestamp();
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_export_request() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_export_selection(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_export_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual jsonb; v_first_sequence numeric; v_last_sequence numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 v_first_sequence:=(NEW.selection->'range'->>'fromSequence')::numeric;
 v_last_sequence:=(NEW.selection->'range'->>'throughSequence')::numeric;
 IF v_first_sequence IS NULL OR v_last_sequence IS NULL OR v_first_sequence<1 OR v_last_sequence<v_first_sequence
  OR v_last_sequence>18446744073709551615 OR v_last_sequence-v_first_sequence>=128
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId','urn:openpc:resource:'||c.evidence_id::text,
  'sourceRecordId',c.record_id,'segmentId',c.segment_id::text,'objectDigest',s.object_digest,
  'sequence',c.sequence::text,'evidenceClass',c.evidence_class,'recordDigest',c.receipt_digest,
  'occurredAt',to_char(c.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY c.sequence)
 INTO actual FROM control.evidence_catalogue c JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
 WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
  AND c.sequence BETWEEN v_first_sequence AND v_last_sequence;
 IF actual IS NULL OR jsonb_array_length(actual)<>v_last_sequence-v_first_sequence+1 OR
  NEW.selection IS DISTINCT FROM jsonb_build_object('version','OPENPC_EVIDENCE_EXPORT_SELECTION_V1',
   'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
   'range',jsonb_build_object('streamId',NEW.stream_id,'fromSequence',v_first_sequence::text,
    'throughSequence',v_last_sequence::text,'redactionProfileId','pc.evidence.minimized-audit.v1'),'records',actual)
  OR NEW.request_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.selection),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_export_selection() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_fact_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_fact_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p jsonb:=NEW.projection; l jsonb:=p->'lineage'; field text; deleted_source control.evidence_catalogue;
 resource_pattern text:='^urn:openpc:fact:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT deleted_source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
   AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(deleted_source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR jsonb_typeof(l) IS DISTINCT FROM 'object'
  OR p-ARRAY['candidateId','sourceSequence','receiptDigest','admittedAt','lineage','integrity','authority','currentReadiness','sourceProfileId','verificationKeyId','verificationKeyDigest']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(p))<>11
  OR l-ARRAY['factId','factDigest','factType','factProfileId','factKeyDigest','canonicalGeneration','projectionId','chainId','genesisDigest','blockNumber','blockHash','predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(l))<>14
  OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key<>'lineage' AND jsonb_typeof(e.value)<>'string')
  OR EXISTS(SELECT 1 FROM jsonb_each(l) e WHERE jsonb_typeof(e.value)<>'string'
   AND NOT(e.key IN ('predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf') AND e.value='null'::jsonb))
  OR p->>'integrity' IS DISTINCT FROM 'FACT_COSE_VERIFIED_AT_CUSTODY'
  OR p->>'authority' IS DISTINCT FROM 'NONE' OR p->>'currentReadiness' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR coalesce(l->>'factId','')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'candidateId'),'')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'sourceProfileId'),'')!~resource_pattern
  OR coalesce(p->>'sourceSequence','')!~'^[1-9][0-9]{0,18}$'
  OR (p->>'sourceSequence')::numeric>9223372036854775807
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR NEW.record_id<>'fact:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(NEW.participant_id::text,NEW.privacy_domain_id::text,p->>'sourceProfileId')),'UTF8')),'hex')||':'||(p->>'sourceSequence')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOREACH field IN ARRAY ARRAY['verificationKeyId','verificationKeyDigest','receiptDigest'] LOOP
  IF coalesce(p->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['factDigest','blockHash'] LOOP
  IF coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['predecessorDigest','relationshipPredecessorDigest'] LOOP
  IF l->field<>'null'::jsonb AND coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 IF l->'reorgReplacementOf'<>'null'::jsonb AND coalesce(l->>'reorgReplacementOf','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','FACT_TYPE_KEY','factType',l->>'factType','factProfileId',l->>'factProfileId','factKeyDigest',l->>'factKeyDigest'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','PROJECTION','projectionId',l->>'projectionId'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','GENERATION','generation',jsonb_build_object('kind','CANONICAL_FACT','factProfileId',l->>'factProfileId','canonicalGeneration',l->>'canonicalGeneration')),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','BLOCK_RANGE','chainId',l->>'chainId','genesisDigest',l->>'genesisDigest','fromBlock',l->>'blockNumber','throughBlock',l->>'blockNumber'),NEW.participant_id,NEW.privacy_domain_id);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c WHERE c.participant_id=NEW.participant_id
  AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND c.receipt_digest=p->>'receiptDigest' AND c.sequence::text=p->>'sourceSequence'
  AND c.occurred_at=(p->>'admittedAt')::timestamptz) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_evidence_fact_provenance() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_hold(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE encoded jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 encoded:=openpc.evidence_hold_selector_encoding(NEW.selector,NEW.participant_id,NEW.privacy_domain_id);
 IF NEW.selector_type IS DISTINCT FROM NEW.selector->>'type'
  OR openpc.business_cbor(NEW.selector_cbor) IS DISTINCT FROM encoded THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF NEW.selector_type='PARTICIPANT' AND NOT EXISTS(SELECT 1 FROM control.participant p
  WHERE p.participant_id=NEW.participant_id AND p.root_privacy_domain_id=NEW.privacy_domain_id)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR NEW.revision<>1 OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>(CASE WHEN NEW.selector_type='PARTICIPANT' THEN 'ACT-EVIDENCE_HOLDS_CREATE_PARTICIPANT-V1' ELSE 'ACT-EVIDENCE_HOLDS_CREATE_RESOURCE-V1' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.effective_at:=NEW.created_at;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','revision','release_operation_id','release_approval_request_id','updated_at']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','revision','release_operation_id','release_approval_request_id','updated_at'])
   OR OLD.state<>'ACTIVE' OR NEW.state<>'RELEASED' OR NEW.revision<>2
   OR NEW.release_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>(CASE WHEN NEW.selector_type='PARTICIPANT' THEN 'ACT-EVIDENCE_HOLDS_RELEASE_PARTICIPANT-V1' ELSE 'ACT-EVIDENCE_HOLDS_RELEASE_RESOURCE-V1' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_hold() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_hold_coverage(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_hold_coverage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE hold control.retention_hold%ROWTYPE; segment control.evidence_segment%ROWTYPE; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT hold FROM control.retention_hold WHERE participant_id=NEW.participant_id
  AND (selector_type='PARTICIPANT' OR privacy_domain_id=NEW.privacy_domain_id) AND retention_hold_id=NEW.retention_hold_id;
 SELECT * INTO STRICT segment FROM control.evidence_segment WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
 IF hold.revision<>NEW.hold_revision OR segment.object_digest<>NEW.object_digest
  OR NOT openpc.evidence_hold_requires_coverage(hold,NEW.stream_id,NEW.segment_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('version','OPENPC_EVIDENCE_HOLD_ACK_V1','object',jsonb_build_object(
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'streamId',NEW.stream_id,
  'sinkId',NEW.sink_id,'segmentId',NEW.segment_id::text,'objectDigest',NEW.object_digest,
  'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,
  'previousSegmentDigest',segment.previous_segment_digest,'keyId',segment.key_id,
  'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'holdId',hold.retention_hold_id::text,'selectorDigest',hold.selector_digest,'revision',hold.revision::text,
  'state',hold.state,'operationId',coalesce(hold.release_operation_id,hold.creation_operation_id)::text,
  'assurance','LOCAL_FSYNC_READBACK');
 IF NEW.receipt-'receiptDigest' IS DISTINCT FROM expected OR NEW.receipt->>'receiptDigest' IS DISTINCT FROM NEW.receipt_digest
  OR NEW.receipt_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.acknowledged_at:=clock_timestamp(); RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_hold_coverage() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_kms_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_kms_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE installed control.evidence_kms_installation; r jsonb; o jsonb; authority jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT installed FROM control.evidence_kms_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND installation_digest=NEW.installation_digest;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||installed.installation_id::text,0));
 SELECT * INTO STRICT installed FROM control.evidence_kms_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND installation_digest=NEW.installation_digest;
 -- Current Identity authority is necessary; it does not authenticate a peer or
 -- replace the application owner using its actual TLS socket.
 authority:=openpc.evidence_export_producer_authority(installed.producer_trust_digest);
 IF TG_OP='UPDATE' THEN
  IF NEW.state IN ('PROVED','REJECTED') THEN
   IF OLD.state NOT IN ('DISPATCHED','UNKNOWN') OR
     to_jsonb(OLD)-ARRAY['state','result_receipt_bytes','result_receipt_digest'] IS DISTINCT FROM
     to_jsonb(NEW)-ARRAY['state','result_receipt_bytes','result_receipt_digest'] OR
     NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=NEW.participant_id
       AND e.privacy_domain_id=NEW.privacy_domain_id AND e.attempt_id=NEW.attempt_id AND e.state='PROVED'
       AND e.kind IN ('PREPARE','READ_ATTEMPT') AND e.receipt_bytes=NEW.result_receipt_bytes
       AND e.receipt_digest=NEW.result_receipt_digest
       AND openpc.evidence_kms_stored_outcome(e.receipt_bytes)=CASE WHEN NEW.state='PROVED' THEN '1' ELSE '2' END)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RESULT-BINDING'; END IF;
   IF NEW.state='PROVED' AND NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key k
     WHERE k.participant_id=NEW.participant_id AND k.privacy_domain_id=NEW.privacy_domain_id AND k.attempt_id=NEW.attempt_id)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-MISSING'; END IF;
   RETURN NEW;
  END IF;
  IF to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
    OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED')
      OR (OLD.state IN ('DISPATCHED','UNKNOWN') AND NEW.state='UNKNOWN'))
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-TRANSITION'; END IF;
  IF NEW.state='UNKNOWN' THEN RETURN NEW; END IF;
 ELSE
  IF NEW.state<>'PREPARED' OR NEW.result_receipt_bytes IS NOT NULL OR NEW.result_receipt_digest IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PREPARE'; END IF;
 END IF;
 IF installed.state<>'ACTIVE' OR NOT installed.pins->'permissions' ? 'ENCRYPT'
 OR floor(extract(epoch from clock_timestamp())*1000)<(installed.pins->>'validFromMs')::numeric
 OR floor(extract(epoch from clock_timestamp())*1000)>=(installed.pins->>'validUntilMs')::numeric
 THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
 IF TG_OP='UPDATE' THEN RETURN NEW; END IF;
 IF NEW.authority_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(authority),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-AUTHORITY'; END IF;
 r:=NEW.request; o:=r->'objectIntent';
 IF jsonb_typeof(r) IS DISTINCT FROM 'object'
 OR r-ARRAY['operation','recipient','attemptId','objectIntent','challenge'] IS DISTINCT FROM '{}'::jsonb
 OR NOT r ?& ARRAY['operation','recipient','attemptId','objectIntent','challenge']
 OR r->>'operation' IS DISTINCT FROM 'PREPARE'
 OR r->'recipient' IS DISTINCT FROM jsonb_build_object('participantId',NEW.participant_id::text,
   'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',NEW.installation_digest,
   'producerTrustDigest',installed.producer_trust_digest)
 OR r->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
 OR NOT coalesce(r->>'challenge' ~ '^[0-9a-f]{64}$',false)
 OR jsonb_typeof(o) IS DISTINCT FROM 'object'
 OR o-ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
   'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
   'redactionProfileDigest','preferenceGeneration','payloadDigest'] IS DISTINCT FROM '{}'::jsonb
 OR NOT o ?& ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
   'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
   'redactionProfileDigest','preferenceGeneration','payloadDigest']
 OR o->>'environmentId' IS DISTINCT FROM installed.pins->>'environmentId'
 OR o->>'participantId' IS DISTINCT FROM NEW.participant_id::text
 OR o->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
 OR o->>'payloadObjectId' IS DISTINCT FROM NEW.object_id::text
 OR o->>'objectVersion' IS DISTINCT FROM NEW.object_version
 OR NEW.object_intent_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(o),'UTF8')),'hex')
 OR NEW.request_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(r),'UTF8')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-REQUEST'; END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005';
END $_$;


ALTER FUNCTION openpc.guard_evidence_kms_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_kms_exchange(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_kms_exchange() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a control.evidence_kms_attempt; i control.evidence_kms_installation; request jsonb; pack jsonb;
 p jsonb; r jsonb; f jsonb; k jsonb; item text; now_ms numeric; original_key text; original_use text; fields text[];
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_kms_attempt WHERE participant_id=NEW.participant_id
 AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id FOR UPDATE;
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 PERFORM openpc.evidence_export_producer_authority(i.producer_trust_digest);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||i.installation_id::text,0));
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 request:=convert_from(NEW.request_bytes,'UTF8')::jsonb;
 IF NEW.request_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(request),'UTF8')
 OR request->>'operation' IS DISTINCT FROM NEW.kind OR request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
 OR request->>'challenge' IS DISTINCT FROM NEW.challenge
 OR request->'recipient' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,
 'privacyDomainId',a.privacy_domain_id::text,'installationDigest',a.installation_digest,'producerTrustDigest',i.producer_trust_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
 IF NEW.kind='PREPARE' THEN
  IF NEW.exchange_id<>NEW.attempt_id OR NEW.request_bytes<>a.request_bytes THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:='sha256:'||repeat('0',64); original_use:='NONE';
 ELSE
  fields:=ARRAY['operation','exchangeId','attemptId','recipient','originalRequestDigest','objectIntentDigest','keyId','keyUse','challenge'];
  IF NEW.kind='READ_ATTEMPT' THEN fields:=fields||ARRAY['readExchangeId','readRequestDigest']; END IF;
  IF jsonb_typeof(request) IS DISTINCT FROM 'object' OR request-fields IS DISTINCT FROM '{}'::jsonb OR NOT request ?& fields
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-SHAPE'; END IF;
  IF request->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
  OR request->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
  OR request->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:=request->>'keyId'; original_use:=request->>'keyUse';
  IF NEW.kind='READ_ATTEMPT' AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange target
   WHERE target.participant_id=a.participant_id AND target.privacy_domain_id=a.privacy_domain_id
   AND target.attempt_id=a.attempt_id AND target.exchange_id::text=request->>'readExchangeId'
   AND target.request_digest=request->>'readRequestDigest' AND target.kind IN ('PREPARE','UNWRAP'))
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-READBACK-TARGET'; END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' OR NEW.receipt_bytes IS NOT NULL THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
  IF NEW.kind='UNWRAP' THEN
   IF a.state<>'PROVED' OR original_use NOT IN ('ENCRYPT','DECRYPT') OR NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key
    WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND key_id=original_key)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNWRAP'; END IF;
   IF original_use='ENCRYPT' AND EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
     AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
     AND convert_from(e.request_bytes,'UTF8')::jsonb->>'keyUse'='ENCRYPT')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-NO-RESEAL'; END IF;
   IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
    AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
    AND e.state IN ('PREPARED','DISPATCHED','UNKNOWN') AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange done
      WHERE done.participant_id=e.participant_id AND done.privacy_domain_id=e.privacy_domain_id AND done.attempt_id=e.attempt_id
      AND done.kind='READ_ATTEMPT' AND done.state='PROVED' AND openpc.evidence_kms_stored_outcome(done.receipt_bytes) IN ('1','2')
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readExchangeId'=e.exchange_id::text
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=e.request_digest))
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNKNOWN'; END IF;
  ELSIF original_use IS DISTINCT FROM 'NONE' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY-USE'; END IF;
  IF NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF to_jsonb(OLD)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor'] IS DISTINCT FROM
 to_jsonb(NEW)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor']
 THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.state IN ('DISPATCHED','UNKNOWN') THEN
  IF NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state IN ('DISPATCHED','UNKNOWN') AND NEW.state='UNKNOWN'))
  OR NEW.receipt_bytes IS NOT NULL OR NEW.provider_sequence IS NOT NULL OR NEW.recovery_floor IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
  IF NEW.state='DISPATCHED' AND NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE'
   OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END
   OR floor(extract(epoch from clock_timestamp())*1000)<(i.pins->>'validFromMs')::numeric
   OR floor(extract(epoch from clock_timestamp())*1000)>=(i.pins->>'validUntilMs')::numeric)
   THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.state NOT IN ('DISPATCHED','UNKNOWN') OR NEW.state<>'PROVED' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-kms-provider-key:'||jsonb_build_array(
  NEW.participant_id,NEW.privacy_domain_id,i.pins->>'providerId',i.pins->>'providerKeyId',i.pins->>'providerKeyVersion')::text,0));
 IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e
   JOIN control.evidence_kms_attempt prior USING(participant_id,privacy_domain_id,attempt_id)
   JOIN control.evidence_kms_installation prior_i USING(participant_id,privacy_domain_id,installation_digest)
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND prior_i.pins->>'providerId'=i.pins->>'providerId' AND prior_i.pins->>'providerKeyId'=i.pins->>'providerKeyId'
   AND prior_i.pins->>'providerKeyVersion'=i.pins->>'providerKeyVersion'
   AND (e.provider_sequence>NEW.provider_sequence OR e.recovery_floor>NEW.recovery_floor))
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECOVERY-FLOOR'; END IF;
 pack:=convert_from(NEW.receipt_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(pack) IS DISTINCT FROM 'object' OR pack-ARRAY['profile','receipt','record','recovery'] IS DISTINCT FROM '{}'::jsonb
 OR NOT pack ?& ARRAY['profile','receipt','record','recovery']
 OR NEW.receipt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(pack),'UTF8') THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 FOREACH item IN ARRAY ARRAY['profile','receipt','record','recovery'] LOOP
  IF jsonb_typeof(pack->item) IS DISTINCT FROM 'object' OR (pack->item)-ARRAY['payloadHex','coseHex'] IS DISTINCT FROM '{}'::jsonb
  OR NOT (pack->item) ?& ARRAY['payloadHex','coseHex']
  OR NOT coalesce(pack->item->>'payloadHex' ~ '^([0-9a-f]{2})*$',false)
  OR NOT coalesce(pack->item->>'coseHex' ~ '^([0-9a-f]{2})*$',false) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 END LOOP;
 p:=openpc.evidence_kms_cose_binding(decode(pack->'profile'->>'payloadHex','hex'),decode(pack->'profile'->>'coseHex','hex'),
 'EvidenceKmsProfileV1','sha256:'||encode(sha256(decode(i.pins->>'profileIssuerSpkiHex','hex')),'hex'));
 IF 'sha256:'||encode(sha256(decode(pack->'profile'->>'coseHex','hex')),'hex') IS DISTINCT FROM i.pins->>'profileDigest'
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PROFILE'; END IF;
 r:=openpc.evidence_kms_cose_binding(decode(pack->'receipt'->>'payloadHex','hex'),decode(pack->'receipt'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
 f:=openpc.evidence_kms_cose_binding(decode(pack->'recovery'->>'payloadHex','hex'),decode(pack->'recovery'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'recoveryAuthoritySpkiHex','hex')),'hex'));
 FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
  IF r->>item IS DISTINCT FROM i.pins->>item OR f->>item IS DISTINCT FROM i.pins->>item OR p->>item IS DISTINCT FROM i.pins->>item
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-SCOPE'; END IF;
 END LOOP;
 IF r->>'operation' IS DISTINCT FROM (CASE NEW.kind WHEN 'PREPARE' THEN '1' WHEN 'READ_ATTEMPT' THEN '2' WHEN 'STATUS' THEN '3' WHEN 'UNWRAP' THEN '4' END)
 OR r->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR r->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
 OR r->>'requestDigest' IS DISTINCT FROM NEW.request_digest OR r->>'challenge' IS DISTINCT FROM NEW.challenge
 OR r->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR r->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
 OR r->>'keyUse' IS DISTINCT FROM (CASE original_use WHEN 'NONE' THEN '1' WHEN 'ENCRYPT' THEN '2' WHEN 'DECRYPT' THEN '3' END)
 OR r->>'providerSequence' IS DISTINCT FROM NEW.provider_sequence::text OR r->>'recoveryFloor' IS DISTINCT FROM NEW.recovery_floor::text
 OR f->>'operation' IS DISTINCT FROM '5' OR f->>'keyUse' IS DISTINCT FROM '1' OR f->>'outcome' IS DISTINCT FROM '1'
 OR f-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs'] IS DISTINCT FROM
 r-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs']
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECEIPT'; END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF (r->>'observedAtMs')::numeric>now_ms OR (r->>'observedAtMs')::numeric<now_ms-5000 OR (r->>'validUntilMs')::numeric<=now_ms
 OR (r->>'validUntilMs')::numeric-(r->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 OR (f->>'observedAtMs')::numeric>now_ms OR (f->>'observedAtMs')::numeric<now_ms-5000 OR (f->>'validUntilMs')::numeric<=now_ms
 OR (f->>'validUntilMs')::numeric-(f->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-STALE'; END IF;
 IF original_key<>'sha256:'||repeat('0',64) AND r->>'keyId' IS DISTINCT FROM original_key THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY'; END IF;
 IF NEW.kind='UNWRAP' AND r->>'outcome'='1' THEN
  IF i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? original_use OR r->>'keyState' NOT IN ('1','2')
  OR (original_use='ENCRYPT' AND r->>'keyState'<>'1') OR now_ms<(i.pins->>'validFromMs')::numeric
  OR now_ms>=(i.pins->>'validUntilMs')::numeric OR r->>'materialDigest'='sha256:'||repeat('0',64)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
 ELSIF r->>'materialDigest' IS DISTINCT FROM 'sha256:'||repeat('0',64) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-MATERIAL'; END IF;
 IF pack->'record'->>'payloadHex'<>'' THEN
  k:=openpc.evidence_kms_cose_binding(decode(pack->'record'->>'payloadHex','hex'),decode(pack->'record'->>'coseHex','hex'),
   'EvidenceWrappedKeyRecordV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
  FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
   IF k->>item IS DISTINCT FROM i.pins->>item THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-SCOPE'; END IF;
  END LOOP;
  IF k->>'attemptId' IS DISTINCT FROM a.attempt_id::text OR k->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
   OR k->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR k->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
   OR r->>'keyId' IS DISTINCT FROM 'sha256:'||encode(sha256(decode(pack->'record'->>'payloadHex','hex')),'hex')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 ELSE
  IF pack->'record'->>'coseHex'<>'' OR (NEW.kind IN ('PREPARE','READ_ATTEMPT','UNWRAP') AND r->>'outcome'='1')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005';
END $_$;


ALTER FUNCTION openpc.guard_evidence_kms_exchange() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_kms_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_kms_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p jsonb; allowed text[]; item text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||NEW.installation_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
   IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
   OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
   THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
   RETURN NEW;
 END IF;
 p:=NEW.pins;
 allowed:=ARRAY['owner','secretClass','environmentId','participantId','privacyDomainId','installationId',
 'producerTrustDigest','reference','version','keyEpoch','providerId','providerOrigin','providerTlsSpkiDigest',
 'profileIssuerSpkiHex','providerReceiptSpkiHex','recoveryAuthoritySpkiHex','providerKeyId','providerKeyVersion','wrapProfileDigest',
 'policyDigest','recoveryProfileDigest','profileDigest','permissions','validFromMs','validUntilMs'];
 IF NEW.state<>'ACTIVE' OR jsonb_typeof(p) IS DISTINCT FROM 'object'
 OR p-allowed IS DISTINCT FROM '{}'::jsonb OR NOT p ?& allowed
 OR p->>'owner' IS DISTINCT FROM 'LS-EVIDENCE-EXPORT'
 OR p->>'secretClass' IS DISTINCT FROM 'SECRET-EVIDENCE-VAULT'
 OR p->>'participantId' IS DISTINCT FROM NEW.participant_id::text
 OR p->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
 OR p->>'installationId' IS DISTINCT FROM NEW.installation_id::text
 OR p->>'producerTrustDigest' IS DISTINCT FROM NEW.producer_trust_digest
 OR NEW.pins_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8')
 OR NEW.installation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.pins_bytes),'hex')
 OR EXISTS(SELECT 1 FROM jsonb_each(p-ARRAY['permissions','validFromMs','validUntilMs']) e
   WHERE jsonb_typeof(e.value)<>'string' OR e.value#>>'{}'<>btrim(e.value#>>'{}')
   OR e.value#>>'{}' ~ '[[:cntrl:]]')
 OR NOT coalesce(p->>'reference' ~ '^secret://[a-z][a-z0-9-]{1,31}/[A-Za-z0-9._/-]{1,192}#[A-Za-z0-9._-]{1,96}$',false)
 OR split_part(p->>'reference','#',2) IS DISTINCT FROM p->>'version'
 OR split_part(p->>'reference','/',3) IS DISTINCT FROM p->>'providerId'
 OR p->>'reference' ~ '/(\.|\.\.)/' OR p->>'reference' ~ '/(\.|\.\.)#'
 OR p->>'reference' ~ '^secret://[^/]+//|^secret://[^/]+/[^#]*//'
 OR lower(p->>'version') IN ('latest','current')
 OR lower(p->>'providerKeyVersion') IN ('latest','current')
 OR NOT coalesce(p->>'providerOrigin' ~ '^https://[a-z0-9.-]+(:[1-9][0-9]{0,4})?$',false)
 OR NOT coalesce(p->>'environmentId' ~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$',false)
 OR length(p->>'providerKeyId') NOT BETWEEN 1 AND 256
 OR length(p->>'providerKeyVersion') NOT BETWEEN 1 AND 96
 OR length(p->>'providerOrigin') NOT BETWEEN 1 AND 512
 OR jsonb_typeof(p->'permissions') IS DISTINCT FROM 'array'
 OR NOT coalesce(p->'permissions' IN ('["ENCRYPT"]'::jsonb,'["DECRYPT"]'::jsonb,'["DECRYPT","ENCRYPT"]'::jsonb),false)
 OR NOT coalesce(p->>'keyEpoch' ~ '^[1-9][0-9]{0,19}$',false)
 OR jsonb_typeof(p->'validFromMs') IS DISTINCT FROM 'number'
 OR jsonb_typeof(p->'validUntilMs') IS DISTINCT FROM 'number'
 OR NOT coalesce(p->>'validFromMs' ~ '^(0|[1-9][0-9]{0,15})$',false)
 OR NOT coalesce(p->>'validUntilMs' ~ '^[1-9][0-9]{0,15}$',false)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-INSTALLATION'; END IF;
 FOREACH item IN ARRAY ARRAY['producerTrustDigest','providerTlsSpkiDigest','wrapProfileDigest','policyDigest','recoveryProfileDigest','profileDigest'] LOOP
  IF NOT coalesce(p->>item ~ '^sha256:[0-9a-f]{64}$',false) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-DIGEST'; END IF;
 END LOOP;
 FOREACH item IN ARRAY ARRAY['profileIssuerSpkiHex','providerReceiptSpkiHex','recoveryAuthoritySpkiHex'] LOOP
  IF NOT coalesce(p->>item ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-TRUST'; END IF;
 END LOOP;
 IF p->>'profileIssuerSpkiHex' IN (p->>'providerReceiptSpkiHex',p->>'recoveryAuthoritySpkiHex')
 OR p->>'providerReceiptSpkiHex'=p->>'recoveryAuthoritySpkiHex'
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ROLE-SEPARATION'; END IF;
 IF (p->>'keyEpoch')::numeric>18446744073709551615
 OR (p->>'validUntilMs')::numeric>9007199254740991
 OR (p->>'validFromMs')::numeric>=(p->>'validUntilMs')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.evidence_export_producer_installation e
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.trust_digest=NEW.producer_trust_digest AND e.state='ACTIVE'
   AND e.environment_id=p->>'environmentId')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PRODUCER'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_evidence_kms_installation() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_payload(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE segment control.evidence_segment%ROWTYPE; envelope jsonb; expected jsonb; head numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  PERFORM openpc.record_evidence_payload_deletion(OLD);
  RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT segment FROM control.evidence_segment s WHERE s.participant_id=NEW.participant_id
  AND s.privacy_domain_id=NEW.privacy_domain_id AND s.stream_id=NEW.stream_id AND s.segment_id=NEW.segment_id;
 SELECT last_sequence INTO STRICT head FROM control.evidence_stream WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id FOR UPDATE;
 IF segment.first_sequence<=head THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF segment.object_digest<>'sha256:'||encode(sha256(NEW.encrypted_segment),'hex') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 envelope:=convert_from(NEW.encrypted_segment,'UTF8')::jsonb;
 expected:=jsonb_build_object('version','OPENPC_EVIDENCE_SEGMENT_V1','participantId',segment.participant_id::text,
  'privacyDomainId',segment.privacy_domain_id::text,'streamId',segment.stream_id,'segmentId',segment.segment_id::text,
  'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,'previousSegmentDigest',segment.previous_segment_digest,
  'keyId',segment.key_id,'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 IF envelope->'header' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_payload() OWNER TO openpc_control_owner;

--
-- Name: guard_evidence_wrapped_key(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_evidence_wrapped_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE') OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=NEW.participant_id
 AND e.privacy_domain_id=NEW.privacy_domain_id AND e.attempt_id=NEW.attempt_id AND e.state='PROVED' AND e.kind IN ('PREPARE','READ_ATTEMPT')
 AND openpc.evidence_kms_stored_outcome(e.receipt_bytes)='1'
 AND convert_from(e.receipt_bytes,'UTF8')::jsonb->'record' IS NOT DISTINCT FROM
 jsonb_build_object('payloadHex',encode(NEW.record_bytes,'hex'),'coseHex',encode(NEW.record_cose,'hex')))
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-BINDING'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_evidence_wrapped_key() OWNER TO openpc_control_owner;

--
-- Name: guard_explorer_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_explorer_custody() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_READ_PROJECTION-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN
  RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-CUSTODY';
 END IF;
 IF TG_TABLE_NAME='privacy_explorer_execution' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.revision<>0 OR NEW.disposition<>'OPEN' OR NEW.evidence IS NOT NULL
    OR NEW.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   NEW.created_at:=clock_timestamp();
  ELSE
   IF OLD.disposition<>'OPEN' OR
    (to_jsonb(NEW)-ARRAY['snapshot','revision','disposition','evidence','evidence_digest','release_claim_id','release_authorized_at','updated_at'])
      IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['snapshot','revision','disposition','evidence','evidence_digest','release_claim_id','release_authorized_at','updated_at']) THEN
    RAISE EXCEPTION 'PC-DATA-6007';
   END IF;
   IF NEW.revision=OLD.revision THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.evidence IS DISTINCT FROM OLD.evidence
     OR NEW.evidence_digest IS DISTINCT FROM OLD.evidence_digest
     OR NEW.disposition NOT IN ('RELEASE_AUTHORIZED','INTERRUPTED') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   ELSIF NEW.revision<>OLD.revision+1 OR NEW.disposition NOT IN ('OPEN','SUPPRESSED')
     OR OLD.evidence IS NOT NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   IF NEW.disposition='RELEASE_AUTHORIZED' AND NEW.deadline_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'PC-OPS-9003';
   END IF;
  END IF;
  NEW.updated_at:=clock_timestamp();
 ELSE
  IF TG_OP='INSERT' AND NEW.consumed_by IS NOT NULL THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  IF TG_OP='UPDATE' AND (OLD.consumed_by IS NOT NULL OR NEW.consumed_by IS NULL
    OR (to_jsonb(NEW)-'consumed_by') IS DISTINCT FROM (to_jsonb(OLD)-'consumed_by')) THEN
    RAISE EXCEPTION 'PC-DATA-6007';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_explorer_custody() OWNER TO openpc_control_owner;

--
-- Name: guard_explorer_profile(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_explorer_profile() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.profile_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.profile-'digest'),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'REGISTERED' OR NEW.revision<>1 OR NEW.revocation_operation_id IS NOT NULL
   OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_PROFILES_CREATE_RESOURCE-V1' THEN
   RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
  END IF;
  NEW.created_at:=clock_timestamp();
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('privacy-explorer-profile:'||OLD.registration_id::text,0));
  IF (to_jsonb(NEW)-ARRAY['state','revision','revocation_operation_id']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','revision','revocation_operation_id'])
   OR OLD.state<>'REGISTERED' OR NEW.state<>'REVOKED' OR NEW.revision<>OLD.revision+1
   OR NEW.revocation_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-PRIVACY_EXPLORER_PROFILES_REVOKE_RESOURCE-V1' THEN
   RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_explorer_profile() OWNER TO openpc_control_owner;

--
-- Name: guard_fact_admission_cursor(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fact_admission_cursor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE amount bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.sequence<>0 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
 ELSE
  IF row(NEW.participant_id,NEW.privacy_domain_id,NEW.fact_type) IS DISTINCT FROM row(OLD.participant_id,OLD.privacy_domain_id,OLD.fact_type)
   OR NEW.sequence<=OLD.sequence OR NEW.sequence>OLD.sequence+256 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
  SELECT count(*) INTO amount FROM control.evidence_fact_admission_inbox i WHERE i.participant_id=NEW.participant_id
   AND i.privacy_domain_id=NEW.privacy_domain_id AND i.fact_type=NEW.fact_type AND i.sequence>OLD.sequence AND i.sequence<=NEW.sequence;
  IF amount<>NEW.sequence-OLD.sequence THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-GAP'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_fact_admission_cursor() OWNER TO openpc_control_owner;

--
-- Name: guard_fact_admission_inbox(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fact_admission_inbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE e jsonb:=NEW.envelope; d jsonb:=e->'data'; p jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT f.projection INTO p FROM control.evidence_fact_provenance f
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment_payload b USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE f.participant_id=NEW.participant_id AND f.privacy_domain_id=NEW.privacy_domain_id
   AND f.stream_id=NEW.stream_id AND f.record_id=NEW.record_id
   AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.receipt_digest=NEW.source_receipt_digest;
 IF p IS NULL THEN
  p:=nullif(current_setting('openpc.fact_delivery_source_projection',true),'')::jsonb;
  IF p IS NULL OR octet_length(p::text)>4096 OR NOT EXISTS(
   SELECT 1 FROM control.evidence_projection_retirement r
    JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
    JOIN control.evidence_catalogue c ON c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
      AND c.stream_id=r.stream_id AND c.record_id=r.record_id AND c.segment_id=r.segment_id
    JOIN control.evidence_segment_payload b ON b.participant_id=c.participant_id AND b.privacy_domain_id=c.privacy_domain_id
      AND b.stream_id=c.stream_id AND b.segment_id=c.segment_id
   WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
    AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND j.state='SUCCEEDED'
    AND j.selection->>'sourceKind'='FACT_PROVENANCE'
    AND r.retirement_digest=openpc.projection_retirement_digest(r)
    AND r.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
    AND r.source_receipt_digest=NEW.source_receipt_digest
    AND r.preservation_metadata=jsonb_build_object('factLineage',p->'lineage')
    AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.receipt_digest=NEW.source_receipt_digest
    AND c.sequence::text=p->>'sourceSequence' AND c.occurred_at=(p->>'admittedAt')::timestamptz
  ) THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CUSTODY-BINDING'; END IF;
 END IF;
 IF p->>'candidateId' IS DISTINCT FROM NEW.candidate_id::text
  OR p->>'receiptDigest' IS DISTINCT FROM NEW.source_receipt_digest
  OR p->'lineage'->>'factId' IS DISTINCT FROM 'urn:openpc:fact:'||NEW.event_id::text
  OR p->'lineage'->>'factType' IS DISTINCT FROM NEW.fact_type
  OR e IS DISTINCT FROM jsonb_build_object(
   'specversion','1.0','id',NEW.event_id::text,'source','urn:openpc:service:LS-FACT-BRIDGE',
   'type','io.openpc.fact.candidate.admitted.v1','subject','urn:openpc:resource:'||NEW.candidate_id::text,
   'time',e->>'time','datacontenttype','application/json',
   'dataschema','https://schemas.openpc.local/event-payloads.schema.json#/$defs/FactCandidateAdmitted',
   'participantid','urn:openpc:participant:'||NEW.participant_id::text,
   'privacydomainid','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
   'correlationid',NEW.candidate_id::text,'authoritygeneration',e->>'authoritygeneration',
   'sequence',NEW.sequence::text,'datadigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(d),'UTF8')),'hex'),
   'data',d)
  OR d IS DISTINCT FROM jsonb_build_object('candidateId','urn:openpc:resource:'||NEW.candidate_id::text,
   'factArtifactId','urn:openpc:resource:'||NEW.candidate_id::text,'artifactDigest',d->>'artifactDigest',
   'sourceProfileDigest',d->>'sourceProfileDigest','sourceNeutral',true)
  OR coalesce(d->>'artifactDigest','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(d->>'sourceProfileDigest','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(e->>'authoritygeneration','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(e->>'time','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
  OR NEW.envelope_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CUSTODY-BINDING'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_fact_admission_inbox() OWNER TO openpc_control_owner;

--
-- Name: guard_fact_consumer_profile(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fact_consumer_profile() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c jsonb; expected jsonb; previous control.fact_consumer_profile; issuer text;
BEGIN
 IF TG_OP<>'INSERT' OR NOT (current_user='openpc_control_owner' OR pg_has_role(current_user,'openpc_control_key_governor','USAGE'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('fact-consumer-profile:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.consumer_id,0));
 SELECT * INTO previous FROM control.fact_consumer_profile WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND consumer_id=NEW.consumer_id ORDER BY revision DESC LIMIT 1;
 IF NEW.revision<>coalesce(previous.revision,0)+1 OR (previous.revision IS NOT NULL AND
   (NEW.profile_id IS DISTINCT FROM previous.profile_id OR NEW.claims->>'environmentId' IS DISTINCT FROM previous.claims->>'environmentId'))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 c:=NEW.claims; issuer:='sha256:'||encode(sha256(NEW.issuer_spki),'hex');
 expected:=jsonb_build_object('environmentId',c->'environmentId','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'profileId',NEW.profile_id,'revision',NEW.revision::text,
  'consumerId',NEW.consumer_id,'subscriptionId',CASE NEW.consumer_id WHEN 'LS-CONTROL-WORK' THEN 'SUB-FACTCANDIDATEADMITTED-CONTROL_WORK-V1' WHEN 'LS-FLEET-CONTROL' THEN 'SUB-FACTCANDIDATEADMITTED-FLEET_CONTROL-V1' END,
  'validFromMs',c->'validFromMs','validUntilMs',c->'validUntilMs','issuerKeyId',issuer,
  'workloadCredentialId',NEW.workload_credential_id::text,'workloadCredentialEpoch',NEW.workload_credential_epoch::text,
  'databaseRole',NEW.database_role,'maximumAttempts',c->'maximumAttempts','initialBackoffMs',c->'initialBackoffMs','maximumBackoffMs',c->'maximumBackoffMs');
 IF c IS DISTINCT FROM expected OR jsonb_typeof(c->'environmentId') IS DISTINCT FROM 'string'
  OR coalesce(c->>'environmentId','')!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  OR NEW.profile_id!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  OR NOT (NEW.database_role~'^[a-z_][a-z0-9_]{0,62}$' OR (
    NEW.participant_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.privacy_domain_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.database_role='openpc_rs_login_'||translate(rtrim(encode(sha256(convert_to(
      '["openpc:runtime-source-scope:v1","'||NEW.participant_id::text||'","'||NEW.privacy_domain_id::text||'"]',
      'UTF8')),'base64'),'='),'+/','-_')))
  OR encode(NEW.issuer_spki,'hex')!~'^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
  OR substring(NEW.workload_credential_id::text from 15 for 1)<>'7'
  OR EXISTS(SELECT 1 FROM jsonb_each(c) e WHERE e.key IN ('validFromMs','validUntilMs','maximumAttempts','initialBackoffMs','maximumBackoffMs')
    AND (jsonb_typeof(e.value)<>'number' OR (e.value#>>'{}')!~'^(0|[1-9][0-9]*)$'))
  OR (c->>'validFromMs')::numeric<0 OR (c->>'validUntilMs')::numeric>9007199254740991
  OR (c->>'validUntilMs')::numeric<=(c->>'validFromMs')::numeric
  OR (c->>'maximumAttempts')::numeric NOT BETWEEN 1 AND 1000
  OR (c->>'initialBackoffMs')::numeric NOT BETWEEN 1 AND 3600000
  OR (c->>'maximumBackoffMs')::numeric NOT BETWEEN (c->>'initialBackoffMs')::numeric AND 3600000
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('0',openpc.business_bytes(decode('60c93313ff9d2ead84868b1af9d8d2b469b97f3b4eabbed3d6df6a5f4bd5395d','hex')),
  '1',c->'environmentId','2',openpc.business_uuid(NEW.participant_id),'3',openpc.business_uuid(NEW.privacy_domain_id),
  '4',NEW.profile_id,'5',NEW.revision,'6',NEW.consumer_id,'7',c->'subscriptionId',
  '8',(c->>'validFromMs')::numeric,'9',(c->>'validUntilMs')::numeric,'10',openpc.business_bytes(sha256(NEW.issuer_spki)),
  '11',openpc.business_uuid(NEW.workload_credential_id),'12',NEW.workload_credential_epoch,
  '13',NEW.database_role,'14',(c->>'maximumAttempts')::numeric,'15',(c->>'initialBackoffMs')::numeric,'16',(c->>'maximumBackoffMs')::numeric);
 IF openpc.business_cbor(NEW.payload) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(NEW.payload,NEW.cose,issuer,24006,343);
 PERFORM 1 FROM pg_catalog.pg_roles WHERE rolname=NEW.database_role AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls
  AND pg_has_role(rolname,'openpc_control_worker','USAGE');
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 NEW.admitted_at:=clock_timestamp(); RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_fact_consumer_profile() OWNER TO openpc_control_owner;

--
-- Name: guard_fact_failure_signer(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fact_failure_signer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF NOT (current_user='openpc_control_owner' OR pg_has_role(current_user,'openpc_control_key_governor','USAGE'))
  OR TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
   OR to_jsonb(NEW)-'state' IS DISTINCT FROM to_jsonb(OLD)-'state'
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  IF NEW.state<>'ACTIVE' OR NOT (NEW.database_role~'^[a-z_][a-z0-9_]{0,62}$' OR (
    NEW.participant_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.privacy_domain_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.database_role='openpc_rs_login_'||translate(rtrim(encode(sha256(convert_to(
      '["openpc:runtime-source-scope:v1","'||NEW.participant_id::text||'","'||NEW.privacy_domain_id::text||'"]',
      'UTF8')),'base64'),'='),'+/','-_')))
   OR NEW.environment_id!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
   OR substring(NEW.workload_credential_id::text from 15 for 1)<>'7'
   OR encode(NEW.public_key_spki,'hex')!~'^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
   OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
     AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole
     AND pg_has_role(r.rolname,'openpc_control_worker','USAGE')
     AND NOT pg_has_role(r.rolname,'openpc_control_owner','MEMBER')
     AND NOT pg_has_role(r.rolname,'openpc_control_key_governor','MEMBER'))
   OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
     WHERE c.participant_id=NEW.participant_id AND c.credential_id=NEW.workload_credential_id
      AND c.credential_epoch=NEW.workload_credential_epoch AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
      AND c.state='ACTIVE' AND w.state='ACTIVE' AND w.kind='WORKLOAD'
      AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
      AND c.public_key_digest IS DISTINCT FROM sha256(NEW.public_key_spki))
   OR EXISTS(SELECT 1 FROM control.fact_consumer_profile p WHERE p.participant_id=NEW.participant_id
     AND p.privacy_domain_id=NEW.privacy_domain_id AND p.issuer_spki=NEW.public_key_spki)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_fact_failure_signer() OWNER TO openpc_control_owner;

--
-- Name: guard_fleet_delivery_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fleet_delivery_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='fleet_fact_delivery_attempt' THEN
   IF OLD.outcome<>'ACTIVE' OR NEW.outcome='ACTIVE'
    OR to_jsonb(NEW)-ARRAY['outcome','ended_at_ms','problem'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['outcome','ended_at_ms','problem']
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE
   IF to_jsonb(NEW)-ARRAY['failed_attempts','lease_generation','state','lease_id','lease_until_ms','next_attempt_ms','last_problem','maximum_attempts']
    IS DISTINCT FROM to_jsonb(OLD)-ARRAY['failed_attempts','lease_generation','state','lease_id','lease_until_ms','next_attempt_ms','last_problem','maximum_attempts']
    OR NEW.maximum_attempts>OLD.maximum_attempts
    OR NEW.failed_attempts NOT BETWEEN OLD.failed_attempts AND OLD.failed_attempts+1
    OR NEW.lease_generation NOT BETWEEN OLD.lease_generation AND OLD.lease_generation+1
    OR OLD.state IN ('QUARANTINED','COMMITTED')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_fleet_delivery_history() OWNER TO openpc_control_owner;

--
-- Name: guard_fleet_quarantine_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_fleet_quarantine_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME='fleet_fact_failure_outbox' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF OLD.state<>'PREPARED' OR NEW.state<>'COMMITTED'
  OR to_jsonb(NEW)-ARRAY['state','payload','cose','receipt_digest','signer_key_id','committed_at_ms']
    IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','payload','cose','receipt_digest','signer_key_id','committed_at_ms']
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_fleet_quarantine_history() OWNER TO openpc_control_owner;

--
-- Name: guard_governed_initial_enrollment(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_governed_initial_enrollment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'openpc', 'control'
    AS $$
DECLARE selected record;
BEGIN
 IF TG_OP='UPDATE' AND NEW.governed_initial_profile_digest IS DISTINCT FROM OLD.governed_initial_profile_digest THEN
  RAISE EXCEPTION 'IDENTITY-1004-INITIAL-PROFILE-SUBSTITUTION'; END IF;
 IF NEW.governed_initial_profile_digest IS NULL THEN RETURN NEW; END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' THEN
  RAISE EXCEPTION 'IDENTITY-1002-INITIAL-QA-ONLY'; END IF;
 SELECT profile.profile_digest INTO selected FROM control.governed_initial_enrollment_profile profile
 CROSS JOIN LATERAL jsonb_array_elements(profile.document->'accounts') account
 JOIN control.session session ON session.participant_id=profile.participant_id
  AND session.session_id=NEW.session_id AND session.principal_id=NEW.principal_id
 WHERE profile.profile_digest=NEW.governed_initial_profile_digest AND profile.participant_id=NEW.participant_id
  AND account->>'principalId'=NEW.principal_id::text AND profile.document->>'origin'=NEW.origin
  AND NEW.replaced_credential_id IS NULL
  AND session.context_mode='PLATFORM' AND session.state='ACTIVE'
  AND (TG_OP='UPDATE' OR (profile.state='ACTIVE' AND profile.valid_from<=clock_timestamp()
    AND profile.valid_until>clock_timestamp() AND session.step_up_verified_at IS NULL
    AND NEW.expires_at>clock_timestamp() AND NEW.expires_at<=NEW.created_at+interval '5 minutes'));
 IF NOT FOUND THEN RAISE EXCEPTION 'IDENTITY-1002-INITIAL-PROFILE-SOURCE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_governed_initial_enrollment() OWNER TO openpc_control_owner;

--
-- Name: guard_governed_initial_profile(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_governed_initial_profile() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'openpc', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'IDENTITY-1004-INITIAL-PROFILE-IMMUTABLE'; END IF;
 IF current_user<>'openpc_control_owner' OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id) THEN
  RAISE EXCEPTION 'IDENTITY-1002-INITIAL-PROFILE-OPERATOR'; END IF;
 IF TG_OP='UPDATE' AND (OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
  OR (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state')) THEN
  RAISE EXCEPTION 'IDENTITY-1004-INITIAL-PROFILE-IMMUTABLE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_governed_initial_profile() OWNER TO openpc_control_owner;

--
-- Name: guard_handover_admission_approval(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_handover_admission_approval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE candidate_row control.mutation_candidate;
BEGIN
 IF NEW.action_intent_id='ACT-WORKLOAD_SIGNING_HANDOVERS_ACTIVATE_RESOURCE-V1' THEN
  IF NEW.subject_type<>'CONFIGURATION_CANDIDATE' THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-APPROVAL-SUBJECT'; END IF;
  SELECT * INTO STRICT candidate_row FROM control.mutation_candidate WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND mutation_candidate_id=NEW.subject_id
    AND maker_principal_id=NEW.maker_principal_id AND candidate_digest=NEW.subject_digest;
  IF TG_OP='INSERT' OR (NEW.state='APPROVED' AND OLD.state IS DISTINCT FROM 'APPROVED') THEN
   PERFORM openpc.assert_handover_admission_candidate(candidate_row);
   IF NEW.expires_at>candidate_row.expires_at THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-APPROVAL-EXPIRY'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_handover_admission_approval() OWNER TO openpc_control_owner;

--
-- Name: guard_handover_admission_candidate(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_handover_admission_candidate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-SIGNING-HANDOVER-ADMIT' THEN
  IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-WORKLOAD_SIGNING_HANDOVERS_ACTIVATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-ADMISSION-STAGING'; END IF;
  PERFORM openpc.assert_handover_admission_candidate(NEW);
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_handover_admission_candidate() OWNER TO openpc_control_owner;

--
-- Name: guard_handover_admission_candidate_commit(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_handover_admission_candidate_commit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-SIGNING-HANDOVER-ADMIT' THEN PERFORM openpc.assert_handover_admission_candidate(NEW); END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_handover_admission_candidate_commit() OWNER TO openpc_control_owner;

--
-- Name: guard_human_membership(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_human_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM control.principal principal
   WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=NEW.membership_id
     AND principal.kind IN ('USER','PLATFORM_OPERATOR')) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-MEMBERSHIP-KIND';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_human_membership() OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_activation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_activation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p control.identity_envelope_proposal%ROWTYPE; c control.mutation_candidate%ROWTYPE;
 a control.approval_request%ROWTYPE; d control.approval_decision_record%ROWTYPE;
 i control.idempotency_record%ROWTYPE; k control.business_signing_key%ROWTYPE;
 payload jsonb; proposal jsonb; maker jsonb; checker jsonb; expected jsonb;
 submission_digest bytea; outer_cose jsonb; header jsonb; source_envelope uuid; now_ns numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-HISTORY'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CONTEXT'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'state'-'observation'-'cose_sign1'-'dispatched_at'-'observed_at'-'committed_at'-'row_version')
   IS DISTINCT FROM (to_jsonb(OLD)-'state'-'observation'-'cose_sign1'-'dispatched_at'-'observed_at'-'committed_at'-'row_version')
   OR NEW.row_version<>OLD.row_version+1
   OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED')
    OR (OLD.state='DISPATCHED' AND NEW.state='OBSERVED')
    OR (OLD.state='OBSERVED' AND NEW.state='COMMITTED'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-PHASE'; END IF;
  IF OLD.state='DISPATCHED' AND NEW.dispatched_at IS DISTINCT FROM OLD.dispatched_at
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-DISPATCH'; END IF;
 ELSE
  IF NEW.state<>'PREPARED' OR NEW.row_version<>1
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-INITIAL'; END IF;
 END IF;
 payload:=openpc.business_cbor(NEW.payload_cbor);
 SELECT * INTO STRICT p FROM control.identity_envelope_proposal WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND envelope_id=NEW.envelope_id;
 proposal:=openpc.business_cbor(p.proposal_cbor);
 IF p.state<>'APPROVED' OR p.row_version<>3 OR p.target_participant_id<>NEW.participant_id
  OR p.proposal_digest<>NEW.proposal_digest OR proposal->>'7'<>'1'
  OR payload->'0' IS DISTINCT FROM openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex'))
  OR payload->'1' IS DISTINCT FROM openpc.business_bytes(p.proposal_cbor)
  OR payload->'2' IS DISTINCT FROM openpc.business_bytes(p.proposal_digest)
  OR payload->>'6' IS DISTINCT FROM NEW.reserved_at_ns::text
  OR NEW.reserved_at_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-PROPOSAL'; END IF;
 SELECT * INTO STRICT i FROM control.idempotency_record WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND principal_id=NEW.principal_id
  AND action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND idempotency_key=NEW.idempotency_key AND idempotency_record_id=NEW.idempotency_record_id
  AND operation_id=NEW.operation_id AND input_digest=NEW.candidate_digest AND expected_aggregate_version=3
  AND terminal_state IS NULL;
 SELECT * INTO STRICT c FROM control.mutation_candidate WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND mutation_candidate_id=NEW.candidate_id
  AND resource_id=NEW.envelope_id AND expected_revision=3 AND (NEW.state='OBSERVED' OR state='APPROVED')
  AND maker_principal_id=NEW.principal_id AND candidate_digest=NEW.candidate_digest
  AND action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND candidate_document=jsonb_build_object('envelopeId',NEW.envelope_id::text);
 SELECT * INTO STRICT a FROM control.approval_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=NEW.approval_request_id
  AND (NEW.state='OBSERVED' OR state='APPROVED') AND subject_type='CONFIGURATION_CANDIDATE' AND subject_id=c.mutation_candidate_id
  AND subject_digest=c.candidate_digest AND subject_version=3 AND maker_principal_id=NEW.principal_id
  AND action_intent_id=c.action_intent_id;
 SELECT * INTO STRICT d FROM control.approval_decision_record WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=a.approval_request_id
  AND decision='APPROVE' AND candidate_digest=c.candidate_digest AND aggregate_version=3
  AND approver_principal_id<>NEW.principal_id;
 SELECT decision.decision_digest INTO STRICT submission_digest FROM control.approval_decision_record decision
  JOIN control.approval_request approved ON approved.participant_id=decision.participant_id
   AND approved.privacy_domain_id=decision.privacy_domain_id AND approved.approval_request_id=decision.approval_request_id
   AND approved.subject_type='AUTHORITY_ENVELOPE' AND approved.subject_id=p.envelope_id
   AND approved.subject_digest=p.proposal_digest AND approved.subject_version=1 AND approved.state='APPROVED'
  WHERE decision.participant_id=p.participant_id AND decision.privacy_domain_id=p.privacy_domain_id
   AND decision.approval_request_id=p.submission_approval_id AND decision.decision='APPROVE'
   AND decision.candidate_digest=p.proposal_digest AND decision.aggregate_version=1
   AND decision.approver_principal_id::text=p.submission_checker#>>'{authority,principalId}';
 SELECT jsonb_build_object('authority',NEW.maker_authority->'binding','stepUpChallengeId',challenge.mfa_challenge_id::text,
   'stepUpEvidenceDigest','sha256:'||encode(verification.evidence_digest,'hex'),
   'signerCredentialId',verification.signer_credential_id::text,'signerCredentialEpoch',challenge.signer_credential_epoch::text)
 INTO STRICT maker FROM control.mfa_challenge challenge JOIN control.mutation_evidence verification
  ON verification.participant_id=challenge.participant_id AND verification.privacy_domain_id=NEW.privacy_domain_id
   AND verification.principal_id=challenge.principal_id AND verification.mfa_challenge_id=challenge.mfa_challenge_id
   AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
   AND verification.webauthn_assertion_binding_digest=i.webauthn_assertion_binding_digest
   AND verification.evidence_digest=sha256(verification.evidence_cbor)
   AND verification.signer_credential_id=challenge.signer_credential_id
 WHERE challenge.participant_id=NEW.participant_id AND challenge.principal_id=NEW.principal_id
  AND challenge.mfa_challenge_id=NEW.maker_challenge_id AND challenge.resource_id=NEW.envelope_id::text
  AND challenge.resource_digest=NEW.candidate_digest AND challenge.action_intent_id=c.action_intent_id
  AND challenge.session_id=c.maker_session_id AND challenge.used_operation_id=NEW.operation_id
  AND challenge.used_at IS NOT NULL AND challenge.used_at>=challenge.consumed_at
  AND challenge.used_at<challenge.expires_at AND challenge.used_at<challenge.consumed_at+interval '5 minutes';
 checker:=jsonb_build_object('authority',NEW.checker_authority->'binding','stepUpChallengeId',d.mfa_challenge_id::text,
  'stepUpEvidenceDigest','sha256:'||encode(sha256(d.evidence_cbor),'hex'),'signerCredentialId',d.signer_credential_id::text,
  'signerCredentialEpoch',d.signer_credential_epoch::text);
 IF NEW.maker_authority#>>'{binding,principalId}' IS DISTINCT FROM c.maker_principal_id::text
  OR NEW.maker_authority#>>'{binding,sessionId}' IS DISTINCT FROM c.maker_session_id::text
  OR NEW.maker_authority#>>'{binding,sessionEpoch}' IS DISTINCT FROM c.maker_session_epoch::text
  OR NEW.maker_authority#>>'{binding,participantEpoch}' IS DISTINCT FROM c.maker_participant_epoch::text
  OR NEW.maker_authority#>>'{binding,principalEpoch}' IS DISTINCT FROM c.maker_principal_epoch::text
  OR NEW.maker_authority#>>'{binding,authorityEpoch}' IS DISTINCT FROM c.maker_authority_epoch::text
  OR NEW.maker_authority#>>'{binding,delegationEpoch}' IS DISTINCT FROM c.maker_delegation_epoch::text
  OR NEW.maker_authority#>>'{binding,assignmentId}' IS DISTINCT FROM c.maker_assignment_id::text
  OR NEW.maker_authority#>>'{binding,assignmentVersion}' IS DISTINCT FROM c.maker_assignment_row_version::text
  OR NEW.maker_authority#>>'{binding,authorityEnvelopeId}' IS DISTINCT FROM c.maker_authority_envelope_id::text
  OR NEW.checker_authority#>>'{binding,principalId}' IS DISTINCT FROM d.approver_principal_id::text
  OR NEW.checker_authority#>>'{binding,sessionId}' IS DISTINCT FROM d.approver_session_id::text
  OR NEW.checker_authority#>>'{binding,sessionEpoch}' IS DISTINCT FROM d.approver_session_epoch::text
  OR NEW.checker_authority#>>'{binding,participantEpoch}' IS DISTINCT FROM d.approver_participant_epoch::text
  OR NEW.checker_authority#>>'{binding,principalEpoch}' IS DISTINCT FROM d.approver_principal_epoch::text
  OR NEW.checker_authority#>>'{binding,authorityEpoch}' IS DISTINCT FROM d.approver_envelope_epoch::text
  OR NEW.checker_authority#>>'{binding,delegationEpoch}' IS DISTINCT FROM d.approver_delegation_epoch::text
  OR NEW.checker_authority#>>'{binding,assignmentId}' IS DISTINCT FROM d.approver_assignment_id::text
  OR NEW.checker_authority#>>'{binding,assignmentVersion}' IS DISTINCT FROM d.approver_assignment_row_version::text
  OR NEW.checker_authority#>>'{binding,authorityEnvelopeId}' IS DISTINCT FROM d.approver_authority_envelope_id::text
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-ACTOR'; END IF;
 expected:=jsonb_build_object('1',openpc.business_uuid(p.submission_operation_id),'2',openpc.business_uuid(p.envelope_id),
  '3',openpc.business_bytes(p.proposal_digest),'4',openpc.business_uuid(p.submission_approval_id),
  '5',openpc.business_bytes(submission_digest),'6',2,'7',3,
  '8',openpc.identity_envelope_actor_wire(p.submission_maker),'9',openpc.identity_envelope_actor_wire(p.submission_checker));
 IF payload->'3' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-SUBMISSION'; END IF;
 expected:=jsonb_build_object('domain','pc.identity.authority-envelope-activation-idempotency.v1',
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'envelopeId',NEW.envelope_id::text,
  'operationId',NEW.operation_id::text,'actionIntentId',c.action_intent_id,'catalogOperationId',c.catalog_operation_id,
  'candidateDigest','sha256:'||encode(c.candidate_digest,'hex'),'expectedApprovedVersion','3',
  'recordId',i.idempotency_record_id::text,'key',i.idempotency_key,'principalId',i.principal_id::text,
  'assertionBindingDigest','sha256:'||encode(i.webauthn_assertion_binding_digest,'hex'));
 expected:=jsonb_build_object('1',openpc.business_uuid(NEW.operation_id),'2',openpc.business_uuid(c.mutation_candidate_id),
  '3',openpc.business_bytes(c.candidate_digest),'4',openpc.business_uuid(a.approval_request_id),
  '5',openpc.business_bytes(d.decision_digest),'6',3,'7',4,
  '8',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8'))),
  '9',1,'10',1,
  '11',openpc.identity_envelope_actor_wire(maker),'12',openpc.identity_envelope_actor_wire(checker));
 IF payload->'4' IS DISTINCT FROM expected
  OR (SELECT count(DISTINCT value) FROM (VALUES (p.submission_maker->>'stepUpChallengeId'),
   (p.submission_checker->>'stepUpChallengeId'),(maker->>'stepUpChallengeId'),(checker->>'stepUpChallengeId')) proof(value))<>4
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-INTENT'; END IF;
 -- Observation resolves the immutable original key, even after selection or
 -- lifecycle changes. Current selection is a separate pre-dispatch fence.
 SELECT key.* INTO STRICT k FROM control.business_signing_key key
  WHERE key.participant_id=NEW.participant_id AND key.privacy_domain_id=NEW.privacy_domain_id
   AND key.environment_id=NEW.request->>'environmentId' AND key.signer_id=NEW.request->>'expectedFingerprint'
   AND key.signing_purpose_code=371;
 expected:=jsonb_build_object('1',k.environment_id,'2',openpc.business_uuid(k.participant_id),'3',openpc.business_uuid(k.privacy_domain_id),
  '4','pc.identity.authority-envelope.v1','5',1,'6',openpc.business_bytes(decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')),
  '7',openpc.business_bytes(decode(substr(k.signer_id,8),'hex')),'8',k.secret_version,
  '9',openpc.business_uuid(k.workload_credential_id),'10',k.workload_credential_epoch,'11',openpc.business_bytes(k.trust_digest));
 IF payload->'5' IS DISTINCT FROM expected OR payload IS DISTINCT FROM jsonb_build_object('0',payload->'0','1',payload->'1',
  '2',payload->'2','3',payload->'3','4',payload->'4','5',expected,'6',NEW.reserved_at_ns)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-SIGNER'; END IF;
 expected:=jsonb_build_object('participantId',k.participant_id::text,'privacyDomainId',k.privacy_domain_id::text,
  'environmentId',k.environment_id,'workloadCredentialId',k.workload_credential_id::text,
  'workloadCredentialEpoch',k.workload_credential_epoch::text,'secretClass','SECRET-SIGNING-KEY','reference',k.secret_reference,
  'version',k.secret_version,'purpose','pc.cose.identity-authority-envelope.v1','purposeCode',371,'schemaId',24034,
  'schemaVersion',1,'schemaDefinitionDigest','sha256:6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5',
  'profileId','pc.identity.authority-envelope.v1','profileVersion',1,'profileDigest','sha256:54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74',
  'trustContextDigest','sha256:'||encode(k.trust_digest,'hex'),'method','SIGN_AUTHORITY_ENVELOPE',
  'callerWorkloadCredentialId',NEW.request->'callerWorkloadCredentialId','attemptId',NEW.attempt_id::text,
  'operationId',NEW.operation_id::text,'expectedFingerprint',k.signer_id,'payloadHex',encode(NEW.payload_cbor,'hex'));
 IF NEW.request IS DISTINCT FROM expected OR NEW.request_digest<>sha256(convert_to('pc.identity.authority-envelope-provider-request.v1','UTF8')
  ||decode('00','hex')||convert_to(openpc.signing_canonical_json(expected),'UTF8'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-REQUEST'; END IF;
 IF NEW.state IN ('PREPARED','DISPATCHED') THEN
  now_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
  IF (NEW.state='PREPARED' AND i.expires_at<=clock_timestamp())
   OR NOT openpc.identity_envelope_activation_intent_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.candidate_id,NEW.approval_request_id)
   OR (proposal#>>'{8,3}')::numeric>now_ns OR (proposal#>>'{8,4}')::numeric<=now_ns
   OR (proposal#>>'{9,3}')::numeric>now_ns OR (proposal#>>'{9,4}')::numeric<=now_ns
   OR NOT EXISTS(SELECT 1 FROM control.participant target WHERE target.participant_id=NEW.participant_id
     AND target.state='ACTIVE' AND target.authority_epoch=(proposal->>'4')::numeric
     AND target.authority_epoch=(proposal->>'5')::numeric)
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.maker_authority,c.action_intent_id,NEW.envelope_id,NEW.state='PREPARED')
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.checker_authority,c.action_intent_id,NEW.envelope_id,NEW.state='PREPARED')
   OR NOT ((openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    p.issuer_authority,'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1',NEW.envelope_id,false)
    AND openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    p.submission_checker_authority,'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1',NEW.envelope_id,false))
    OR (NEW.principal_id=p.maker_principal_id
      AND NEW.checker_authority#>>'{binding,principalId}'=p.submission_checker#>>'{authority,principalId}'
      AND openpc.platform_recovery_proposal_history_current(NEW.participant_id,NEW.privacy_domain_id,
      (NEW.maker_authority#>>'{binding,authorityEnvelopeId}')::uuid,NEW.envelope_id)
      AND openpc.platform_recovery_proposal_history_current(NEW.participant_id,NEW.privacy_domain_id,
      (NEW.checker_authority#>>'{binding,authorityEnvelopeId}')::uuid,NEW.envelope_id)))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CURRENT-AUTHORITY'; END IF;
  FOREACH source_envelope IN ARRAY ARRAY[
   (p.issuer_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (p.submission_checker_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (NEW.maker_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (NEW.checker_authority#>>'{binding,authorityEnvelopeId}')::uuid] LOOP
   IF NOT EXISTS(SELECT 1 FROM control.authority_envelope source
     JOIN control.platform_context platform ON platform.platform_context_id=source.platform_context_id
      AND platform.authority_epoch=source.platform_authority_epoch AND platform.state='ACTIVE'
     JOIN (select platform_context_id,platform_authority_epoch,
  owner_participant_id,installation_privacy_domain_id,admission_digest from control.platform_envelope_scope
  union all select platform_context_id,platform_authority_epoch,owner_participant_id,
    installation_privacy_domain_id,admission_digest from control.platform_envelope_scope_successor
  union all select platform_context_id,platform_authority_epoch,owner_participant_id,
    installation_privacy_domain_id,admission_digest from control.root_expiry_recovery_scope) root ON root.platform_context_id=platform.platform_context_id
      AND root.platform_authority_epoch=platform.authority_epoch AND root.owner_participant_id=NEW.participant_id
     WHERE source.participant_id=NEW.participant_id AND source.authority_envelope_id=source_envelope
      AND source.state='ACTIVE' AND platform.owner_participant_id=NEW.participant_id
      AND openpc.business_uuid(platform.platform_context_id)=proposal#>'{10,3}'
      AND ((to_jsonb(platform.authority_epoch)=proposal#>'{10,4}'
         AND openpc.business_bytes(root.admission_digest)=proposal#>'{10,5}')
        OR EXISTS(SELECT 1 FROM control.platform_scope_replacement pending
          JOIN control.mutation_candidate create_intent ON create_intent.participant_id=pending.participant_id
            AND create_intent.mutation_candidate_id=p.create_candidate_id AND create_intent.state='CONSUMED'
          CROSS JOIN LATERAL jsonb_array_elements(pending.candidate->'administrators') admin
          WHERE pending.platform_context_id=platform.platform_context_id AND pending.participant_id=NEW.participant_id
            AND pending.privacy_domain_id=NEW.privacy_domain_id AND pending.state='WITHDRAWING' AND pending.row_version=1
            AND pending.predecessor_epoch=platform.authority_epoch AND pending.expected_root_revision=platform.row_version
            AND to_jsonb(pending.predecessor_epoch+1)=proposal#>'{10,4}'
            AND openpc.business_bytes(pending.successor_digest)=proposal#>'{10,5}'
            AND create_intent.candidate_document->>'platformScopeReplacementId'=pending.replacement_id::text
            AND admin->>'envelopeId'=NEW.envelope_id::text
            AND create_intent.candidate_document->'usable'=admin->'usable'
            AND create_intent.candidate_document->'grantable'=admin->'grantable'
            AND openpc.platform_scope_document_value(proposal->'8')=admin->'usable'
            AND openpc.platform_scope_document_value(proposal->'9')=admin->'grantable')))

   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-ROOT'; END IF;
  END LOOP;
  IF k.valid_from_ns>now_ns OR k.valid_until_ns<=now_ns
   OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_signing_selection selection
     JOIN control.identity_envelope_signing_grant grant_row ON grant_row.participant_id=selection.participant_id
      AND grant_row.privacy_domain_id=selection.privacy_domain_id AND grant_row.signer_id=selection.signer_id
      AND grant_row.profile_digest=selection.profile_digest AND grant_row.signing_purpose_code=371
     WHERE selection.participant_id=k.participant_id AND selection.privacy_domain_id=k.privacy_domain_id
      AND selection.environment_id=k.environment_id AND selection.signer_id=k.signer_id AND selection.admission_version>0
      AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex'))
   OR NOT EXISTS(SELECT 1 FROM control.business_signing_key_state lifecycle
     JOIN control.credential credential ON credential.participant_id=lifecycle.participant_id
      AND credential.credential_id=k.workload_credential_id AND credential.kind='WORKLOAD_MTLS'
      AND credential.credential_epoch=k.workload_credential_epoch AND credential.state='ACTIVE'
      AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
     JOIN control.principal principal ON principal.participant_id=credential.participant_id
      AND principal.principal_id=credential.principal_id AND principal.kind='WORKLOAD' AND principal.state='ACTIVE'
      AND principal.authority_epoch=k.envelope_workload_principal_epoch
     JOIN control.participant participant ON participant.participant_id=principal.participant_id
      AND participant.state='ACTIVE' AND participant.authority_epoch=k.envelope_workload_participant_epoch
     WHERE lifecycle.participant_id=k.participant_id AND lifecycle.privacy_domain_id=k.privacy_domain_id
      AND lifecycle.signer_id=k.signer_id AND lifecycle.state='ACTIVE')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CURRENT-KEY'; END IF;
 END IF;
 IF NEW.state='DISPATCHED' AND (NEW.dispatched_at<NEW.created_at OR NEW.dispatched_at>clock_timestamp())
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-DISPATCH'; END IF;
 IF NEW.state IN ('OBSERVED','COMMITTED') THEN
  expected:=(NEW.request-ARRAY['method','callerWorkloadCredentialId','attemptId','operationId','expectedFingerprint','payloadHex'])
   ||jsonb_build_object('algorithm','ES256','publicKeySpkiHex',encode(k.public_key_spki_der,'hex'),
    'fingerprint',k.signer_id,'validFromNs',k.valid_from_ns::text,'validUntilNs',k.valid_until_ns::text,'state','ACTIVE');
  IF NEW.observed_at<NEW.dispatched_at OR NEW.observed_at>clock_timestamp()
   OR NEW.observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.observation->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.observation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.request_digest,'hex')
   OR NEW.observation->>'method' IS DISTINCT FROM 'SIGN_AUTHORITY_ENVELOPE'
   OR NEW.observation->>'coseHex' IS DISTINCT FROM encode(NEW.cose_sign1,'hex')
   OR NEW.observation->'descriptor' IS DISTINCT FROM expected
   OR NEW.observation IS DISTINCT FROM jsonb_build_object('schemaVersion',1,'method','SIGN_AUTHORITY_ENVELOPE',
    'attemptId',NEW.attempt_id::text,'operationId',NEW.operation_id::text,
    'requestDigest','sha256:'||encode(NEW.request_digest,'hex'),'recordedAtNs',NEW.observation->'recordedAtNs',
    'descriptor',expected,'coseHex',encode(NEW.cose_sign1,'hex'))
   OR (NEW.observation->>'recordedAtNs')::numeric<NEW.reserved_at_ns
   OR (NEW.observation->>'recordedAtNs')::numeric>=k.valid_until_ns
   OR (NEW.observation->>'recordedAtNs')::numeric>floor(extract(epoch FROM NEW.observed_at)*1000000)*1000
   OR get_byte(NEW.cose_sign1,0)<>210
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-OBSERVATION'; END IF;
  outer_cose:=openpc.business_cbor_item(NEW.cose_sign1,1,0);
  IF (outer_cose->>'next')::integer<>octet_length(NEW.cose_sign1)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE'; END IF;
  outer_cose:=outer_cose->'value';
  IF jsonb_typeof(outer_cose)<>'array' OR jsonb_array_length(outer_cose)<>4 OR outer_cose->1<>'{}'::jsonb
   OR outer_cose->2 IS DISTINCT FROM openpc.business_bytes(NEW.payload_cbor) OR length(outer_cose->3->>'bytes') IS DISTINCT FROM 128
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE'; END IF;
  header:=openpc.business_cbor(decode(outer_cose->0->>'bytes','hex'));
  IF header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),
   '3','application/pc+cbor','4',openpc.business_bytes(convert_to(k.signer_id,'UTF8')),'100',24034,'101',1,'102',371,'103',2)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE-CONTEXT'; END IF;
 END IF;
 IF NEW.state='COMMITTED' AND NOT EXISTS(
  SELECT 1 FROM control.authority_envelope envelope
   WHERE envelope.participant_id=NEW.participant_id
    AND envelope.authority_envelope_id=NEW.envelope_id
    AND envelope.state='ACTIVE' AND envelope.row_version=4
    AND envelope.last_mutation_operation_id=NEW.operation_id
    AND envelope.cose_sign1=NEW.cose_sign1)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SEALED-ACTIVATION-REQUIRED'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_identity_envelope_activation() OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_proposal(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_proposal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE proposal jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-HISTORY'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-INITIAL-STATE'; END IF;
 ELSE
  IF (to_jsonb(NEW)-'state'-'submission_operation_id'-'submission_intent_digest'-'submission_approval_id'-'submission_maker'-'submission_checker'-'submission_checker_authority'-'row_version')
    IS DISTINCT FROM (to_jsonb(OLD)-'state'-'submission_operation_id'-'submission_intent_digest'-'submission_approval_id'-'submission_maker'-'submission_checker'-'submission_checker_authority'-'row_version')
    OR NEW.row_version<>OLD.row_version+1
    OR NOT ((OLD.state='DRAFT' AND NEW.state='SUBMITTED') OR (OLD.state='SUBMITTED' AND NEW.state='APPROVED')) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-HISTORY'; END IF;
  IF OLD.state='SUBMITTED' AND (NEW.submission_operation_id,NEW.submission_intent_digest,NEW.submission_approval_id,NEW.submission_maker)
    IS DISTINCT FROM (OLD.submission_operation_id,OLD.submission_intent_digest,OLD.submission_approval_id,OLD.submission_maker) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SUBMISSION-IMMUTABLE'; END IF;
 END IF;
 proposal:=openpc.business_cbor(NEW.proposal_cbor);
 IF jsonb_typeof(proposal) IS DISTINCT FROM 'object'
   OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(proposal) key) IS DISTINCT FROM ARRAY['0','1','10','2','3','4','5','6','7','8','9']
   OR proposal->'0' IS DISTINCT FROM jsonb_build_object('bytes','6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5')
   OR proposal->'1' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.envelope_id::text,'-',''))
   OR proposal->>'2' IS DISTINCT FROM '1'
   OR proposal->'3' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.target_participant_id::text,'-',''))
   OR proposal#>'{10,2,1}' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.participant_id::text,'-',''))
   OR proposal#>'{10,2,3}' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.maker_principal_id::text,'-',''))
   OR NEW.issuer_authority#>>'{binding,participantId}' IS DISTINCT FROM NEW.participant_id::text
   OR NEW.issuer_authority#>>'{binding,principalId}' IS DISTINCT FROM NEW.maker_principal_id::text
   OR NEW.issuer_authority#>>'{durable,grant,privacyDomainId}' IS DISTINCT FROM NEW.privacy_domain_id::text THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-PROVENANCE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_identity_envelope_proposal() OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_recovery_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_recovery_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE expected_schema text; record_id text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.row_version<>OLD.row_version+1
   OR (to_jsonb(NEW)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  NEW.revoked_at:=clock_timestamp();
  RETURN NEW;
 END IF;
 IF current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 PERFORM openpc.assert_request_context(true);
 expected_schema:=CASE TG_TABLE_NAME
  WHEN 'identity_envelope_recovery_custody_trust' THEN 'pc.installation.identity-envelope-recovery-receiving-trust'
  WHEN 'identity_envelope_recovery_enrollment' THEN 'pc.identity.identity-envelope-recovery-enrollment'
  ELSE NULL END;
 record_id:=CASE TG_TABLE_NAME
  WHEN 'identity_envelope_recovery_custody_trust' THEN to_jsonb(NEW)->>'custody_trust_id'
  ELSE to_jsonb(NEW)->>'enrollment_id' END;
 IF expected_schema IS NULL OR NEW.document->>'schema' IS DISTINCT FROM expected_schema
  OR NEW.document->>'schemaVersion' IS DISTINCT FROM '1'
  OR NEW.document->>'purpose' IS DISTINCT FROM 'pc.installation.identity-envelope-repair-custody.v1'
  OR NEW.state<>'ACTIVE' OR NEW.row_version<>1
  OR NEW.document_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.document),'UTF8'))
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR NEW.document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NEW.document->>'platformContextId' IS DISTINCT FROM NEW.platform_context_id::text
  OR (NEW.document->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
  OR (NEW.document->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
  OR NEW.valid_from>clock_timestamp() OR NEW.valid_until<=clock_timestamp()
  OR (CASE WHEN TG_TABLE_NAME='identity_envelope_recovery_custody_trust'
    THEN NEW.document->>'custodyTrustId' ELSE NEW.document->>'enrollmentId' END) IS DISTINCT FROM record_id
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 IF TG_TABLE_NAME='identity_envelope_recovery_enrollment' THEN
  IF NEW.document->>'custodyTrustId' IS DISTINCT FROM NEW.custody_trust_id::text
   OR NEW.document->>'custodyTrustDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.custody_trust_digest,'hex')
   OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_custody_trust trust
    WHERE trust.custody_trust_id=NEW.custody_trust_id AND trust.participant_id=NEW.participant_id
     AND trust.privacy_domain_id=NEW.privacy_domain_id AND trust.document_digest=NEW.custody_trust_digest
     AND trust.state='ACTIVE' AND trust.row_version=1 AND trust.valid_from<=NEW.valid_from AND trust.valid_until>=NEW.valid_until)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-CUSTODY'; END IF;
 END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_identity_envelope_recovery_installation() OWNER TO openpc_control_owner;

--
-- Name: signing_key_rotation; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.signing_key_rotation (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    rotation_id uuid NOT NULL,
    request jsonb NOT NULL,
    candidate_digest bytea NOT NULL,
    maker_principal_id uuid NOT NULL,
    approval_request_id uuid,
    approved_operation_id uuid,
    environment_id text NOT NULL,
    workload_credential_id uuid NOT NULL,
    old_signer_id text NOT NULL,
    new_signer_id text,
    old_trust_digest bytea NOT NULL,
    state text DEFAULT 'REQUESTED'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    cutover_at_ns bigint,
    recovery_from_state text,
    recovery_from_revision bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recovery_case_id uuid,
    CONSTRAINT signing_rotation_approval_ck CHECK ((((recovery_case_id IS NULL) AND (((state = 'REQUESTED'::text) AND (approval_request_id IS NULL) AND (approved_operation_id IS NULL)) OR ((state <> 'REQUESTED'::text) AND (approval_request_id IS NOT NULL) AND (approved_operation_id IS NOT NULL)))) OR ((recovery_case_id IS NOT NULL) AND (approval_request_id IS NULL) AND ((request ->> 'signerRole'::text) = 'IDENTITY_ENVELOPE'::text) AND ((request ->> 'purpose'::text) = 'pc.cose.identity-authority-envelope.v1'::text) AND (((state = 'REQUESTED'::text) AND (approved_operation_id IS NULL)) OR ((state <> 'REQUESTED'::text) AND (approved_operation_id IS NOT NULL)))))),
    CONSTRAINT signing_rotation_digests_ck CHECK (((octet_length(candidate_digest) = 32) AND (octet_length(old_trust_digest) = 32) AND (old_signer_id <> new_signer_id))),
    CONSTRAINT signing_rotation_recovery_ck CHECK (((state = 'RECOVERING'::text) = ((recovery_from_state IS NOT NULL) AND (recovery_from_revision IS NOT NULL)))),
    CONSTRAINT signing_rotation_revision_ck CHECK ((revision > 0)),
    CONSTRAINT signing_rotation_state_ck CHECK ((state = ANY (ARRAY['REQUESTED'::text, 'APPROVED'::text, 'PREPARED'::text, 'DISTRIBUTED'::text, 'VERIFIED'::text, 'CUTOVER_FENCED'::text, 'OBSERVING'::text, 'OLD_REVOKED'::text, 'OLD_RETIRED'::text, 'COMPLETE'::text, 'FAILED'::text, 'RECOVERING'::text])))
);

ALTER TABLE ONLY control.signing_key_rotation FORCE ROW LEVEL SECURITY;


ALTER TABLE control.signing_key_rotation OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_recovery_rotation(control.signing_key_rotation, control.signing_key_rotation, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_recovery_rotation(p_new control.signing_key_rotation, p_old control.signing_key_rotation, p_operation text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE recovery control.platform_recovery_case; enrollment control.identity_envelope_recovery_enrollment; method text; expected_revision numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_new.recovery_case_id
  AND c.participant_id=p_new.participant_id AND c.privacy_domain_id=p_new.privacy_domain_id;
 IF NOT FOUND OR NOT openpc.matches_participant(p_new.participant_id) OR NOT openpc.matches_privacy(p_new.privacy_domain_id)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NOT coalesce(openpc.identity_envelope_recovery_lease_current(recovery.recovery_id),false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CUSTODY'; END IF;
 SELECT * INTO STRICT enrollment FROM control.identity_envelope_recovery_enrollment e WHERE e.enrollment_id=recovery.signer_repair_enrollment_id
  AND e.participant_id=recovery.participant_id AND e.privacy_domain_id=recovery.privacy_domain_id;
 IF p_new.rotation_id::text IS DISTINCT FROM recovery.lease_bindings->>'rotationId'
  OR p_new.request IS DISTINCT FROM enrollment.document->'request'
  OR p_new.request->>'signerRole' IS DISTINCT FROM 'IDENTITY_ENVELOPE'
  OR p_new.request->>'purpose' IS DISTINCT FROM 'pc.cose.identity-authority-envelope.v1'
  OR NOT EXISTS(SELECT 1 FROM control.action_intent action WHERE action.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
    AND action.action_intent_id=p_new.request->>'actionIntentId' AND action.resource_type='signing-key-rotation'
    AND action.operation_class='CREATE' AND action.maker_checker_required
    AND 'sha256:'||encode(action.semantic_digest,'hex')=p_new.request->>'actionIntentDigest')
  OR p_new.candidate_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(
    jsonb_build_object('request',p_new.request,'lease',recovery.lease_bindings)),'UTF8'))
  OR p_new.old_trust_digest IS DISTINCT FROM decode(substr(recovery.lease_bindings->>'oldTrustDigest',8),'hex')
  OR p_new.maker_principal_id::text IS DISTINCT FROM recovery.lease_bindings->>'executorPrincipalId'
  OR p_new.old_signer_id IS DISTINCT FROM p_new.request->>'oldFingerprint'
  OR p_new.environment_id IS DISTINCT FROM p_new.request->>'environmentId'
  OR p_new.workload_credential_id::text IS DISTINCT FROM p_new.request->>'workloadCredentialId'
  OR p_new.approval_request_id IS NOT NULL
  OR (p_new.state NOT IN ('CUTOVER_FENCED','OBSERVING','OLD_REVOKED','OLD_RETIRED','COMPLETE') AND p_new.cutover_at_ns IS NOT NULL)
  OR p_new.recovery_from_state IS NOT NULL OR p_new.recovery_from_revision IS NOT NULL
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-RESERVATION'; END IF;
 IF p_operation='INSERT' THEN
  IF p_new.state<>'REQUESTED' OR p_new.revision<>1 OR p_new.approved_operation_id IS NOT NULL OR p_new.new_signer_id IS NOT NULL
   OR openpc.current_operation_id()::text IS DISTINCT FROM recovery.lease_bindings->>'creationOperationId' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-INITIAL'; END IF;
 ELSIF p_operation='UPDATE' THEN
  IF (p_old.state='OBSERVING' AND p_new.state='OLD_REVOKED') OR (p_old.state='OLD_REVOKED' AND p_new.state='OLD_RETIRED') OR (p_old.state='OLD_RETIRED' AND p_new.state='COMPLETE') THEN
   expected_revision:=CASE p_old.state WHEN 'OBSERVING' THEN 7 WHEN 'OLD_REVOKED' THEN 8 ELSE 9 END;
   method:=CASE p_new.state WHEN 'OLD_REVOKED' THEN 'REVOKE' WHEN 'OLD_RETIRED' THEN 'RETIRE' ELSE NULL END;
   IF p_old.revision<>expected_revision OR p_new.revision<>expected_revision+1 OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step WHERE step.operation_id=openpc.current_operation_id()
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id AND step.rotation_id=p_new.rotation_id AND step.recovery_id=recovery.recovery_id
      AND step.state='COMMITTED' AND step.from_revision=expected_revision AND step.from_state=p_old.state AND step.to_state=p_new.state
      AND step.result->>'state'=p_new.state AND openpc.identity_envelope_rotation_step_current(step) AND EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step consumer
 JOIN control.signing_key_rotation r ON r.participant_id=consumer.participant_id AND r.privacy_domain_id=consumer.privacy_domain_id AND r.rotation_id=consumer.rotation_id AND r.recovery_case_id=consumer.recovery_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key next ON next.participant_id=selection.participant_id AND next.privacy_domain_id=selection.privacy_domain_id AND next.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant next_grant ON next_grant.participant_id=next.participant_id AND next_grant.privacy_domain_id=next.privacy_domain_id AND next_grant.signer_id=next.signer_id AND next_grant.profile_digest=selection.profile_digest AND next_grant.signing_purpose_code=371
 JOIN control.business_signing_key_state next_life ON next_life.participant_id=next.participant_id AND next_life.privacy_domain_id=next.privacy_domain_id AND next_life.signer_id=next.signer_id
 JOIN control.business_signing_key old_key ON old_key.participant_id=r.participant_id AND old_key.privacy_domain_id=r.privacy_domain_id AND old_key.signer_id=r.old_signer_id
 JOIN control.business_signing_key_state old_life ON old_life.participant_id=old_key.participant_id AND old_life.privacy_domain_id=old_key.privacy_domain_id AND old_life.signer_id=old_key.signer_id
 JOIN control.identity_envelope_activation a ON a.participant_id=consumer.participant_id AND a.privacy_domain_id=consumer.privacy_domain_id AND a.operation_id=consumer.consumer_activation_operation_id
 WHERE consumer.operation_id=step.consumer_observation_operation_id AND consumer.participant_id=step.participant_id AND consumer.privacy_domain_id=step.privacy_domain_id
 AND consumer.rotation_id=step.rotation_id AND consumer.recovery_id=step.recovery_id AND consumer.principal_id=step.principal_id
 AND consumer.from_revision=6 AND consumer.from_state='CUTOVER_FENCED' AND consumer.to_state='OBSERVING' AND consumer.state='COMMITTED'
 AND consumer.authority_binding=step.authority_binding AND consumer.authority_digest=step.authority_digest
 AND consumer.evidence_digest=sha256(consumer.evidence_cbor) AND octet_length(consumer.cose_sign1)>0
 AND a.state='COMMITTED' AND a.row_version=4 AND a.payload_digest=sha256(a.payload_cbor)
 AND a.operation_id::text=consumer.result->>'consumerActivationOperationId' AND a.envelope_id::text=consumer.result->>'consumerEnvelopeId'
 AND 'sha256:'||encode(a.payload_digest,'hex')=consumer.result->>'consumerPayloadDigest'
 AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=next.participant_id AND ordinary.privacy_domain_id=next.privacy_domain_id AND ordinary.signer_id IN(next.signer_id,old_key.signer_id))
 AND next_life.state='ACTIVE' AND next.signing_purpose_code=371 AND old_key.signing_purpose_code=371
 AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
 AND selection.admission_version=(step.authority_binding#>>'{lease,selectionAdmissionVersion}')::numeric+1
 AND selection.admission_version::text=consumer.result->>'selectionAdmissionVersion'
 AND 'sha256:'||encode(next.trust_digest,'hex')=consumer.result->>'trustDigest' AND next.signer_id=consumer.result->>'signerId'
 AND old_key.trust_digest=decode(substr(step.authority_binding#>>'{lease,oldTrustDigest}',8),'hex')
 AND old_life.state=(CASE WHEN step.from_state='OBSERVING' AND true THEN 'ACTIVE' ELSE 'REVOKED' END)
 AND (step.result IS NULL OR (step.result->>'consumerObservationOperationId'=consumer.operation_id::text
 AND step.result->>'consumerActivationOperationId'=consumer.result->>'consumerActivationOperationId'
 AND step.result->>'consumerEnvelopeId'=consumer.result->>'consumerEnvelopeId' AND step.result->>'consumerPayloadDigest'=consumer.result->>'consumerPayloadDigest'
 AND step.result->>'consumerReceiptDigest'=consumer.result->>'consumerReceiptDigest' AND step.result->>'signerId'=consumer.result->>'signerId'
 AND step.result->>'trustDigest'=consumer.result->>'trustDigest' AND step.result->>'selectionAdmissionVersion'=consumer.result->>'selectionAdmissionVersion'
 AND step.result->>'predecessorSignerId'=old_key.signer_id AND step.result->>'permissionEffect'='NONE')))
      AND (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)=(CASE WHEN method IS NULL THEN 0 ELSE 1 END)
      AND (method IS NULL OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a JOIN control.business_signing_key key
        ON key.participant_id=a.participant_id AND key.privacy_domain_id=a.privacy_domain_id AND key.signer_id=p_new.old_signer_id
        WHERE a.operation_id=step.operation_id AND a.slot='old' AND a.state='OBSERVED' AND a.request->>'method'=method
        AND a.observation->>'outcome'='SUCCEEDED' AND a.observation=a.first_observation AND a.observation#>>'{descriptor,fingerprint}'=key.signer_id
        AND a.observation#>>'{descriptor,publicKeySpkiHex}'=encode(key.public_key_spki_der,'hex') AND a.observation#>>'{descriptor,reference}'=key.secret_reference
        AND a.observation#>>'{descriptor,state}'=(CASE method WHEN 'REVOKE' THEN 'REVOKED' ELSE 'RETIRED' END)
        AND (a.observation#>>ARRAY['descriptor',CASE method WHEN 'REVOKE' THEN 'revokedAtNs' ELSE 'retiredAtNs' END])::numeric>=floor(extract(epoch from a.started_at)*1000000)*1000
        AND a.observation#>>'{descriptor,revokedAtNs}'=step.result->>'oldPrivateKeyRevokedAtNs'
        AND a.observation#>>'{descriptor,retiredAtNs}' IS NOT DISTINCT FROM step.result->>'oldPrivateKeyRetiredAtNs'
        AND (a.observation->>'recordedAtNs')::numeric<=floor(extract(epoch from step.completed_at)*1000000)*1000))
      AND (p_new.state='OLD_REVOKED' OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step prior WHERE prior.participant_id=step.participant_id
        AND prior.privacy_domain_id=step.privacy_domain_id AND prior.rotation_id=step.rotation_id AND prior.recovery_id=step.recovery_id
        AND prior.consumer_observation_operation_id=step.consumer_observation_operation_id AND prior.state='COMMITTED'
        AND prior.from_revision=expected_revision-1 AND prior.to_state=p_old.state
        AND prior.result->>'oldPrivateKeyRevokedAtNs'=step.result->>'oldPrivateKeyRevokedAtNs'
        AND (p_new.state<>'COMPLETE' OR (prior.result->>'oldPrivateKeyRetiredAtNs'=step.result->>'oldPrivateKeyRetiredAtNs' AND step.result->>'postReviewRequired'='true')))))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-RETIREMENT'; END IF;
   RETURN;
  END IF;
  IF p_old.state='CUTOVER_FENCED' AND p_new.state='OBSERVING' THEN
   IF p_old.revision<>6 OR p_new.revision<>7 OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step WHERE step.operation_id=openpc.current_operation_id()
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id AND step.rotation_id=p_new.rotation_id
      AND step.recovery_id=recovery.recovery_id AND step.from_revision=6 AND step.from_state='CUTOVER_FENCED' AND step.to_state='OBSERVING'
      AND step.state='COMMITTED' AND openpc.identity_envelope_rotation_step_current(step) AND step.result->>'state'='OBSERVING'
      AND step.result->>'permissionEffect'='NONE' AND EXISTS(SELECT 1 FROM control.signing_key_rotation r
 JOIN control.identity_envelope_activation a ON a.participant_id=r.participant_id AND a.privacy_domain_id=r.privacy_domain_id AND a.operation_id=step.consumer_activation_operation_id
 JOIN control.identity_envelope_proposal p ON p.participant_id=a.participant_id AND p.privacy_domain_id=a.privacy_domain_id AND p.envelope_id=a.envelope_id
 JOIN control.authority_envelope e ON e.participant_id=a.participant_id AND e.authority_envelope_id=a.envelope_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key k ON k.participant_id=selection.participant_id AND k.privacy_domain_id=selection.privacy_domain_id AND k.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant g ON g.participant_id=k.participant_id AND g.privacy_domain_id=k.privacy_domain_id AND g.signer_id=k.signer_id
 JOIN control.business_signing_key_state life ON life.participant_id=k.participant_id AND life.privacy_domain_id=k.privacy_domain_id AND life.signer_id=k.signer_id
 JOIN control.mutation_candidate candidate ON candidate.participant_id=a.participant_id AND candidate.privacy_domain_id=a.privacy_domain_id AND candidate.mutation_candidate_id=a.candidate_id
 JOIN control.idempotency_record idem ON idem.participant_id=a.participant_id AND idem.privacy_domain_id=a.privacy_domain_id AND idem.operation_id=a.operation_id AND idem.idempotency_record_id=a.idempotency_record_id
 JOIN control.mutation_evidence receipt ON receipt.participant_id=a.participant_id AND receipt.privacy_domain_id=a.privacy_domain_id AND receipt.operation_id=a.operation_id AND receipt.aggregate_id=a.envelope_id
 JOIN control.outbox_event event ON event.participant_id=receipt.participant_id AND event.privacy_domain_id=receipt.privacy_domain_id AND event.aggregate_type='authority-envelope' AND event.aggregate_id=a.envelope_id AND event.event_type='openpc.authority-envelope.mutation.committed.v1'
  AND event.payload_cbor=receipt.evidence_cbor AND event.payload_digest=receipt.evidence_digest AND event.cose_sign1=receipt.cose_sign1
 WHERE r.participant_id=step.participant_id AND r.privacy_domain_id=step.privacy_domain_id AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id
  AND selection.admission_version=(step.authority_binding#>>'{lease,selectionAdmissionVersion}')::numeric+1 AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  AND k.signing_purpose_code=371 AND g.signing_purpose_code=371 AND g.profile_digest=selection.profile_digest AND life.state='ACTIVE'
  AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=k.participant_id AND ordinary.privacy_domain_id=k.privacy_domain_id AND ordinary.signer_id=k.signer_id)
  AND a.state='COMMITTED' AND a.row_version=4 AND a.reserved_at_ns>=r.cutover_at_ns AND a.committed_at<=step.created_at
  AND a.payload_digest=sha256(a.payload_cbor) AND a.request->>'expectedFingerprint'=k.signer_id AND a.request->>'trustContextDigest'='sha256:'||encode(k.trust_digest,'hex')
  AND a.request->>'reference'=k.secret_reference AND a.request->>'version'=k.secret_version AND a.request->>'callerWorkloadCredentialId'=k.workload_credential_id::text
  AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=a.operation_id AND candidate.candidate_digest=a.candidate_digest AND candidate.resource_id=a.envelope_id
  AND candidate.action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND candidate.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND idem.terminal_state='COMMITTED' AND idem.action_intent_id=candidate.action_intent_id AND idem.catalog_operation_id=candidate.catalog_operation_id
  AND e.representation='TYPED_V1' AND e.state='ACTIVE' AND e.row_version=4 AND e.last_mutation_operation_id=a.operation_id
  AND e.cose_sign1=a.cose_sign1 AND e.semantic_cbor=p.proposal_cbor AND e.semantic_digest=p.proposal_digest
  AND receipt.action_intent_id=candidate.action_intent_id AND receipt.catalog_operation_id=candidate.catalog_operation_id AND receipt.aggregate_version=3
  AND receipt.evidence_digest=sha256(receipt.evidence_cbor) AND octet_length(receipt.cose_sign1)>0
  AND (step.result IS NULL OR (step.result->>'consumerActivationOperationId'=a.operation_id::text
   AND step.result->>'consumerEnvelopeId'=a.envelope_id::text AND step.result->>'consumerPayloadDigest'='sha256:'||encode(a.payload_digest,'hex')
   AND step.result->>'consumerReceiptDigest'='sha256:'||encode(receipt.evidence_digest,'hex') AND step.result->>'signerId'=k.signer_id
   AND step.result->>'trustDigest'='sha256:'||encode(k.trust_digest,'hex') AND step.result->>'selectionAdmissionVersion'=selection.admission_version::text
   AND EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt proof WHERE proof.operation_id=step.operation_id
    AND proof.participant_id=step.participant_id AND proof.privacy_domain_id=step.privacy_domain_id AND proof.rotation_id=step.rotation_id
    AND proof.slot='effective' AND proof.state='OBSERVED' AND proof.request->>'method'='PROVE' AND proof.observation->>'outcome'='SUCCEEDED'
    AND proof.observation=proof.first_observation AND proof.request->>'expectedFingerprint'=k.signer_id
    AND proof.request->>'challengeHex'=encode(k.trust_digest,'hex') AND proof.observation#>>'{descriptor,fingerprint}'=k.signer_id
    AND proof.observation#>>'{descriptor,publicKeySpkiHex}'=encode(k.public_key_spki_der,'hex') AND proof.observation#>>'{descriptor,state}'='ACTIVE'
    AND (proof.request->>'challengeExpiresAtNs')::numeric>floor(extract(epoch from clock_timestamp())*1000000)*1000
    AND (proof.observation->>'recordedAtNs')::numeric<=floor(extract(epoch from step.completed_at)*1000000)*1000))))
      AND (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)=1
      AND EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id AND a.slot='effective'
        AND a.state='OBSERVED' AND a.request->>'method'='PROVE' AND a.observation->>'outcome'='SUCCEEDED' AND a.observation=a.first_observation
        AND a.observation#>>'{descriptor,fingerprint}'=p_new.new_signer_id AND a.observation#>>'{descriptor,state}'='ACTIVE'
        AND a.request->>'challengeHex'=substr(step.result->>'trustDigest',8)))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CONSUMER'; END IF;
   RETURN;
  END IF;
  IF p_old.state='VERIFIED' AND p_new.state='CUTOVER_FENCED' THEN
   IF p_old.revision<>5 OR p_new.revision<>6 OR p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id OR p_old.cutover_at_ns IS NOT NULL
    OR p_new.cutover_at_ns IS NULL OR p_new.cutover_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','cutover_at_ns']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','cutover_at_ns'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id() AND s.participant_id=p_new.participant_id
      AND s.privacy_domain_id=p_new.privacy_domain_id AND s.rotation_id=p_new.rotation_id AND s.recovery_id=recovery.recovery_id
      AND s.from_revision=5 AND s.from_state='VERIFIED' AND s.to_state='CUTOVER_FENCED' AND s.state='COMMITTED'
      AND openpc.identity_envelope_rotation_step_current(s) AND s.result->>'signerId'=p_new.new_signer_id AND s.result->>'state'='CUTOVER_FENCED'
      AND s.result->>'permissionEffect'='NONE' AND (s.result->>'selectionAdmissionVersion')::numeric=(recovery.lease_bindings->>'selectionAdmissionVersion')::numeric+1
      AND p_new.cutover_at_ns=floor(extract(epoch from s.completed_at)*1000000)*1000
      AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=s.operation_id))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CUTOVER'; END IF;
   RETURN;
  END IF;
  IF p_old.state='DISTRIBUTED' AND p_new.state='VERIFIED' THEN
   IF p_old.revision<>4 OR p_new.revision<>5 OR p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step WHERE step.operation_id=openpc.current_operation_id()
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id AND step.rotation_id=p_new.rotation_id
      AND step.recovery_id=recovery.recovery_id AND step.from_revision=4 AND step.from_state='DISTRIBUTED' AND step.to_state='VERIFIED'
      AND step.state='COMMITTED' AND openpc.identity_envelope_rotation_step_current(step)
      AND step.result->>'state'='VERIFIED' AND step.result->>'admissionState'='ADMITTED' AND step.result->>'signerId'=p_new.new_signer_id
      AND (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)=2
      AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id
        AND (a.state<>'OBSERVED' OR a.request->>'method'<>'PROVE' OR a.observation IS DISTINCT FROM a.first_observation
          OR a.observation->>'outcome'<>'SUCCEEDED' OR a.request->>'challengeHex' IS DISTINCT FROM substr(step.result->>'trustDigest',8))))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-VERIFICATION'; END IF;
   RETURN;
  END IF;
  IF (p_old.state='APPROVED' AND p_new.state='PREPARED') OR (p_old.state='PREPARED' AND p_new.state='DISTRIBUTED') THEN
   method:=CASE WHEN p_new.state='PREPARED' THEN 'PREPARE' ELSE 'DISTRIBUTE' END;
   expected_revision:=CASE WHEN method='PREPARE' THEN 2 ELSE 3 END;
   IF p_old.revision<>expected_revision OR p_new.revision<>expected_revision+1 OR p_new.new_signer_id IS NULL
    OR (method='PREPARE' AND p_old.new_signer_id IS NOT NULL)
    OR (method='DISTRIBUTE' AND p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id)
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','new_signer_id'])
      IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','new_signer_id'])
    OR p_new.approved_operation_id::text IS DISTINCT FROM recovery.lease_bindings->>'activationOperationId'
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step
     JOIN control.identity_envelope_rotation_attempt attempt ON attempt.operation_id=step.operation_id AND attempt.rotation_id=step.rotation_id
      AND attempt.participant_id=step.participant_id AND attempt.privacy_domain_id=step.privacy_domain_id AND attempt.slot='new'
     WHERE step.operation_id=openpc.current_operation_id() AND step.rotation_id=p_new.rotation_id AND step.recovery_id=recovery.recovery_id
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id
      AND step.from_revision=expected_revision AND step.from_state=p_old.state AND step.to_state=p_new.state AND step.state='COMMITTED'
      AND openpc.identity_envelope_rotation_step_current(step) AND step.result->>'state'=p_new.state
      AND step.result->>'signerId'=p_new.new_signer_id AND attempt.state='OBSERVED' AND attempt.request->>'method'=method
      AND attempt.observation->>'outcome'='SUCCEEDED' AND attempt.observation=attempt.first_observation
      AND attempt.observation#>>'{descriptor,fingerprint}'=p_new.new_signer_id
      AND attempt.observation#>>'{descriptor,reference}'=p_new.request->>'newReference'
      AND attempt.observation#>>'{descriptor,state}'='ACTIVE'
      AND attempt.observation#>>'{descriptor,fingerprint}'='sha256:'||encode(sha256(decode(attempt.observation#>>'{descriptor,publicKeySpkiHex}','hex')),'hex')
      AND (method='PREPARE' OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step prepared
        JOIN control.identity_envelope_rotation_attempt original USING(participant_id,privacy_domain_id,rotation_id,operation_id)
        WHERE prepared.participant_id=step.participant_id AND prepared.privacy_domain_id=step.privacy_domain_id AND prepared.rotation_id=step.rotation_id
          AND prepared.recovery_id=step.recovery_id AND prepared.from_revision=2 AND prepared.to_state='PREPARED'
          AND prepared.state='COMMITTED' AND original.slot='new' AND original.state='OBSERVED'
          AND original.observation->'descriptor'=attempt.observation->'descriptor'
          AND prepared.result->>'trustDigest'=attempt.request->>'trustContextDigest'
          AND prepared.result->>'trustDigest'=step.result->>'trustDigest')))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-PREPARE'; END IF;
   RETURN;
  END IF;
  IF p_old.state<>'REQUESTED' OR p_new.state<>'APPROVED' OR p_new.revision<>p_old.revision+1
   OR openpc.current_operation_id()::text IS DISTINCT FROM recovery.lease_bindings->>'creationOperationId'
   OR p_new.new_signer_id IS NOT NULL
   OR p_new.updated_at<=p_old.updated_at
   OR p_new.approved_operation_id::text IS DISTINCT FROM recovery.lease_bindings->>'activationOperationId'
   OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','approved_operation_id'])
      IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','approved_operation_id']) THEN
   -- Later proof/admission/cutover remain closed until immutable
   -- trust, versioned selection and genuine consumer owners are connected.
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-PHASE'; END IF;
 ELSE RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-OWNER';
 END IF;
END $$;


ALTER FUNCTION openpc.guard_identity_envelope_recovery_rotation(p_new control.signing_key_rotation, p_old control.signing_key_rotation, p_operation text) OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_representation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_representation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.representation,NEW.participant_id,NEW.issuer_participant_id,NEW.issuer_privacy_domain_id,NEW.principal_id)
   IS DISTINCT FROM (OLD.representation,OLD.participant_id,OLD.issuer_participant_id,OLD.issuer_privacy_domain_id,OLD.principal_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-REPRESENTATION';
 END IF;
 IF NEW.representation IN ('LEGACY','RECOVERY_V1') THEN RETURN NEW; END IF;
 IF NEW.representation<>'TYPED_V1' OR NEW.platform_context_id IS NULL OR NEW.platform_authority_epoch IS NULL
   OR NEW.valid_until IS NULL
   OR (NEW.state='ACTIVE') IS DISTINCT FROM (octet_length(NEW.cose_sign1)>0)
   OR NEW.semantic_digest<>sha256(NEW.semantic_cbor) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-PROPOSAL'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 OR NEW.checker_principal_id IS NOT NULL THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-INITIAL-STATE'; END IF;
 ELSE
  IF (to_jsonb(NEW)-'creator_participant_id'-'state'-'checker_principal_id'-'last_mutation_operation_id'-'row_version'-'updated_at'-'cose_sign1')
    IS DISTINCT FROM (to_jsonb(OLD)-'creator_participant_id'-'state'-'checker_principal_id'-'last_mutation_operation_id'-'row_version'-'updated_at'-'cose_sign1')
    OR NEW.row_version<>OLD.row_version+1 OR NEW.last_mutation_operation_id IS NULL
    OR NOT (
      (OLD.state='DRAFT' AND NEW.state='SUBMITTED' AND NEW.checker_principal_id IS NULL
       AND NEW.cose_sign1=OLD.cose_sign1)
      OR (OLD.state='SUBMITTED' AND NEW.state='APPROVED' AND NEW.checker_principal_id IS NOT NULL
       AND NEW.cose_sign1=OLD.cose_sign1)
      OR (OLD.state='APPROVED' AND NEW.state='ACTIVE' AND NEW.checker_principal_id=OLD.checker_principal_id
       AND EXISTS(SELECT 1 FROM control.identity_envelope_activation activation
        WHERE activation.participant_id=NEW.participant_id
         AND activation.privacy_domain_id=NEW.issuer_privacy_domain_id
         AND activation.envelope_id=NEW.authority_envelope_id
         AND activation.operation_id=openpc.current_operation_id()
         AND activation.state='OBSERVED' AND activation.row_version=3
         AND activation.cose_sign1=NEW.cose_sign1))
    ) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SEALED-ACTIVATION-REQUIRED'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_identity_envelope_representation() OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_rotation_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_rotation_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation; effects jsonb; issuer jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=NEW.operation_id
  AND s.participant_id=NEW.participant_id AND s.privacy_domain_id=NEW.privacy_domain_id AND s.rotation_id=NEW.rotation_id;
 IF NOT coalesce(openpc.identity_envelope_rotation_step_bound(step),false) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id;
  effects:=openpc.signing_transition_effects('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1',step.from_state,step.to_state);
  issuer:=step.authority_binding#>'{lease,issuer}';
  IF step.state<>'READY' OR NEW.state<>'READY' OR NEW.started_at IS NOT NULL OR NEW.observation IS NOT NULL OR NEW.first_observation IS NOT NULL OR NEW.ambiguity_kind IS NOT NULL
   OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
   OR NOT (effects->'providerSteps' @> jsonb_build_array(jsonb_build_array(NEW.slot,NEW.request->>'method')))
   OR NEW.request_digest<>sha256(convert_to('pc.identity.envelope-key-rotation-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(NEW.request),'UTF8'))
   OR NEW.request->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR NEW.request->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR NEW.request->>'rotationId' IS DISTINCT FROM NEW.rotation_id::text OR NEW.request->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.request->>'purpose' IS DISTINCT FROM 'pc.cose.identity-authority-envelope.v1' OR NEW.request->>'purposeCode' IS DISTINCT FROM '371'
   OR NEW.request->>'schemaId' IS DISTINCT FROM '24034' OR NEW.request->>'schemaVersion' IS DISTINCT FROM '1'
   OR NEW.request->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
   OR NEW.request->>'schemaDefinitionDigest' IS DISTINCT FROM 'sha256:6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5'
   OR NEW.request->>'profileId' IS DISTINCT FROM 'pc.identity.authority-envelope.v1'
   OR NEW.request->>'profileVersion' IS DISTINCT FROM '1'
   OR NEW.request->>'profileDigest' IS DISTINCT FROM 'sha256:54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74'
   OR NEW.request-ARRAY['participantId','privacyDomainId','environmentId','workloadCredentialId','workloadCredentialEpoch',
    'secretClass','reference','version','purpose','purposeCode','schemaId','schemaVersion','schemaDefinitionDigest','profileId',
    'profileVersion','profileDigest','callerWorkloadCredentialId','rotationId','operationId','attemptId','issuerParticipantEpoch',
    'issuerPrincipalEpoch','governanceDigest','method','expectedFingerprint']-
      (CASE NEW.request->>'method' WHEN 'DISTRIBUTE' THEN ARRAY['trustContextDigest']
       WHEN 'PROVE' THEN ARRAY['challengeHex','challengeIssuedAtNs','challengeExpiresAtNs','recoveryPredecessor'] ELSE ARRAY[]::text[] END)<>'{}'::jsonb
   OR NEW.request->'recoveryPredecessor' IS DISTINCT FROM
     (CASE WHEN NEW.slot='old' AND NEW.request->>'method'='PROVE'
       THEN jsonb_build_object('purpose','IDENTITY_ENVELOPE_SIGNER_REPAIR_ONLY',
    'enrollmentId',step.authority_binding#>>'{lease,enrollmentId}',
    'enrollmentDigest',step.authority_binding#>>'{lease,enrollmentDigest}',
    'recoveryId',step.authority_binding#>>'{lease,recoveryId}',
    'activationOperationId',step.authority_binding#>>'{lease,activationOperationId}',
    'leaseDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(step.authority_binding->'lease'),'UTF8')),'hex'),
    'oldTrustDigest',step.authority_binding#>>'{lease,oldTrustDigest}') ELSE NULL END)
   OR NEW.request->>'environmentId' IS DISTINCT FROM rotation.environment_id
   OR NEW.request->>'workloadCredentialId' IS DISTINCT FROM issuer->>'workloadCredentialId'
   OR NEW.request->>'callerWorkloadCredentialId' IS DISTINCT FROM issuer->>'workloadCredentialId'
   OR NEW.request->>'workloadCredentialEpoch' IS DISTINCT FROM issuer->>'workloadCredentialEpoch'
   OR NEW.request->>'issuerParticipantEpoch' IS DISTINCT FROM issuer->>'workloadParticipantEpoch'
   OR NEW.request->>'issuerPrincipalEpoch' IS DISTINCT FROM issuer->>'workloadPrincipalEpoch'
   OR NEW.request->>'reference' IS DISTINCT FROM (CASE WHEN NEW.slot='old' THEN rotation.request->>'oldReference' ELSE rotation.request->>'newReference' END)
   OR NEW.request->>'version' IS DISTINCT FROM split_part(NEW.request->>'reference','#',2)
   OR NEW.request->>'governanceDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
      jsonb_build_object('domain','pc.identity.envelope-rotation-governance.v1','admission',step.authority_binding)),'UTF8')),'hex')
   OR (NEW.request->>'method'<>'PREPARE' AND NEW.request->>'expectedFingerprint' IS DISTINCT FROM
     (CASE WHEN NEW.slot='old' THEN rotation.old_signer_id ELSE rotation.new_signer_id END))
   OR (NEW.request->>'method'='PREPARE' AND NEW.request->>'expectedFingerprint' IS DISTINCT FROM rotation.request->>'newFingerprint')
   OR (NEW.request->>'method'='DISTRIBUTE' AND NOT EXISTS(
     SELECT 1 FROM control.identity_envelope_rotation_step prepared WHERE prepared.participant_id=NEW.participant_id
      AND prepared.privacy_domain_id=NEW.privacy_domain_id AND prepared.rotation_id=NEW.rotation_id AND prepared.recovery_id=step.recovery_id
      AND prepared.from_revision=2 AND prepared.from_state='APPROVED' AND prepared.to_state='PREPARED' AND prepared.state='COMMITTED'
      AND prepared.result->>'signerId'=rotation.new_signer_id AND prepared.result->>'trustDigest'=NEW.request->>'trustContextDigest'))
   OR (NEW.slot='effective' AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_activation consumer WHERE consumer.operation_id=step.consumer_activation_operation_id
     AND consumer.participant_id=step.participant_id AND consumer.privacy_domain_id=step.privacy_domain_id AND consumer.state='COMMITTED'
     AND floor(extract(epoch from consumer.committed_at)*1000000)*1000<=(NEW.request->>'challengeIssuedAtNs')::numeric))
   OR (NEW.request->>'method'='PROVE' AND (
      coalesce(NEW.request->>'challengeHex','') !~ '^[0-9a-f]{64}$'
      OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step prepared WHERE prepared.participant_id=NEW.participant_id
        AND prepared.privacy_domain_id=NEW.privacy_domain_id AND prepared.rotation_id=NEW.rotation_id AND prepared.recovery_id=step.recovery_id
        AND prepared.from_revision=3 AND prepared.to_state='DISTRIBUTED' AND prepared.state='COMMITTED'
        AND prepared.result->>'signerId'=rotation.new_signer_id AND substr(prepared.result->>'trustDigest',8)=NEW.request->>'challengeHex')
      OR
      (NEW.request->>'challengeIssuedAtNs')::numeric>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
      OR (NEW.request->>'challengeExpiresAtNs')::numeric<=(NEW.request->>'challengeIssuedAtNs')::numeric
      OR (NEW.request->>'challengeExpiresAtNs')::numeric>(NEW.request->>'challengeIssuedAtNs')::numeric+300000000000
      OR (NEW.request->>'challengeExpiresAtNs')::numeric>floor(extract(epoch FROM (step.authority_binding#>>'{lease,validUntil}')::timestamptz)*1000000)*1000))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-REQUEST'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','started_at','observed_at','observation','observation_digest','first_observation','first_observation_digest','ambiguity_kind'])
   IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','started_at','observed_at','observation','observation_digest','first_observation','first_observation_digest','ambiguity_kind'])
  OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  OR (OLD.first_observation IS NOT NULL AND (NEW.first_observation,NEW.first_observation_digest) IS DISTINCT FROM (OLD.first_observation,OLD.first_observation_digest))
  OR (OLD.observation IS NOT NULL AND (NEW.observation,NEW.observation_digest,NEW.observed_at) IS DISTINCT FROM (OLD.observation,OLD.observation_digest,OLD.observed_at))
  OR (OLD.ambiguity_kind IS NOT NULL AND NEW.ambiguity_kind IS DISTINCT FROM OLD.ambiguity_kind)
  OR OLD.state='OBSERVED' THEN RAISE EXCEPTION 'DATA-6020-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF NOT ((OLD.state='READY' AND NEW.state='STARTED') OR
   (OLD.state='STARTED' AND NEW.state IN ('STARTED','OBSERVED','WRITE_AMBIGUITY')) OR
   (OLD.state='WRITE_AMBIGUITY' AND NEW.state IN ('WRITE_AMBIGUITY','OBSERVED'))) THEN
  RAISE EXCEPTION 'DATA-6022-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF OLD.state='READY' AND NEW.state='STARTED' AND (step.state<>'STARTED' OR NEW.started_at IS NULL
   OR NEW.started_at>clock_timestamp() OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
   OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt sibling WHERE sibling.operation_id=NEW.operation_id AND sibling.state='WRITE_AMBIGUITY')
   OR (NEW.slot='effective' AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_activation consumer WHERE consumer.operation_id=step.consumer_activation_operation_id
     AND consumer.participant_id=step.participant_id AND consumer.privacy_domain_id=step.privacy_domain_id AND consumer.state='COMMITTED'
     AND floor(extract(epoch from consumer.committed_at)*1000000)*1000<=(NEW.request->>'challengeIssuedAtNs')::numeric))
   OR (NEW.request->>'method'='PROVE' AND (NEW.request->>'challengeExpiresAtNs')::numeric<=floor(extract(epoch FROM clock_timestamp())*1000000)*1000)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-DISPATCH'; END IF;
 IF NEW.first_observation IS NOT NULL AND (NEW.first_observation_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(NEW.first_observation),'UTF8'))
   OR NEW.first_observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.first_observation->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.first_observation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.request_digest,'hex')
   OR NEW.first_observation->>'method' IS DISTINCT FROM NEW.request->>'method') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-OBSERVATION'; END IF;
 IF NEW.state='OBSERVED' AND (NEW.observation IS DISTINCT FROM NEW.first_observation
   OR NEW.observation_digest IS DISTINCT FROM NEW.first_observation_digest OR NEW.observed_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-LOOKUP'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_identity_envelope_rotation_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_identity_envelope_rotation_step(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_identity_envelope_rotation_step() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE rotation control.signing_key_rotation; effects jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT coalesce(openpc.identity_envelope_rotation_step_bound(NEW),false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-STEP'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id;
 effects:=openpc.signing_transition_effects('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1',NEW.from_state,NEW.to_state);
 IF effects IS NULL OR effects->>'kind'<>'ADVANCE' OR effects->>'resumeFrom' IS NOT NULL
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-TRANSITION'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'READY' OR NEW.started_at IS NOT NULL OR NEW.result IS NOT NULL
   OR NEW.from_revision<>rotation.revision OR NEW.from_state<>rotation.state
   OR (NEW.from_state='CUTOVER_FENCED' AND NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r
 JOIN control.identity_envelope_activation a ON a.participant_id=r.participant_id AND a.privacy_domain_id=r.privacy_domain_id AND a.operation_id=NEW.consumer_activation_operation_id
 JOIN control.identity_envelope_proposal p ON p.participant_id=a.participant_id AND p.privacy_domain_id=a.privacy_domain_id AND p.envelope_id=a.envelope_id
 JOIN control.authority_envelope e ON e.participant_id=a.participant_id AND e.authority_envelope_id=a.envelope_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key k ON k.participant_id=selection.participant_id AND k.privacy_domain_id=selection.privacy_domain_id AND k.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant g ON g.participant_id=k.participant_id AND g.privacy_domain_id=k.privacy_domain_id AND g.signer_id=k.signer_id
 JOIN control.business_signing_key_state life ON life.participant_id=k.participant_id AND life.privacy_domain_id=k.privacy_domain_id AND life.signer_id=k.signer_id
 JOIN control.mutation_candidate candidate ON candidate.participant_id=a.participant_id AND candidate.privacy_domain_id=a.privacy_domain_id AND candidate.mutation_candidate_id=a.candidate_id
 JOIN control.idempotency_record idem ON idem.participant_id=a.participant_id AND idem.privacy_domain_id=a.privacy_domain_id AND idem.operation_id=a.operation_id AND idem.idempotency_record_id=a.idempotency_record_id
 JOIN control.mutation_evidence receipt ON receipt.participant_id=a.participant_id AND receipt.privacy_domain_id=a.privacy_domain_id AND receipt.operation_id=a.operation_id AND receipt.aggregate_id=a.envelope_id
 JOIN control.outbox_event event ON event.participant_id=receipt.participant_id AND event.privacy_domain_id=receipt.privacy_domain_id AND event.aggregate_type='authority-envelope' AND event.aggregate_id=a.envelope_id AND event.event_type='openpc.authority-envelope.mutation.committed.v1'
  AND event.payload_cbor=receipt.evidence_cbor AND event.payload_digest=receipt.evidence_digest AND event.cose_sign1=receipt.cose_sign1
 WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id AND r.recovery_case_id=NEW.recovery_id
  AND selection.admission_version=(NEW.authority_binding#>>'{lease,selectionAdmissionVersion}')::numeric+1 AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  AND k.signing_purpose_code=371 AND g.signing_purpose_code=371 AND g.profile_digest=selection.profile_digest AND life.state='ACTIVE'
  AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=k.participant_id AND ordinary.privacy_domain_id=k.privacy_domain_id AND ordinary.signer_id=k.signer_id)
  AND a.state='COMMITTED' AND a.row_version=4 AND a.reserved_at_ns>=r.cutover_at_ns AND a.committed_at<=NEW.created_at
  AND a.payload_digest=sha256(a.payload_cbor) AND a.request->>'expectedFingerprint'=k.signer_id AND a.request->>'trustContextDigest'='sha256:'||encode(k.trust_digest,'hex')
  AND a.request->>'reference'=k.secret_reference AND a.request->>'version'=k.secret_version AND a.request->>'callerWorkloadCredentialId'=k.workload_credential_id::text
  AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=a.operation_id AND candidate.candidate_digest=a.candidate_digest AND candidate.resource_id=a.envelope_id
  AND candidate.action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND candidate.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND idem.terminal_state='COMMITTED' AND idem.action_intent_id=candidate.action_intent_id AND idem.catalog_operation_id=candidate.catalog_operation_id
  AND e.representation='TYPED_V1' AND e.state='ACTIVE' AND e.row_version=4 AND e.last_mutation_operation_id=a.operation_id
  AND e.cose_sign1=a.cose_sign1 AND e.semantic_cbor=p.proposal_cbor AND e.semantic_digest=p.proposal_digest
  AND receipt.action_intent_id=candidate.action_intent_id AND receipt.catalog_operation_id=candidate.catalog_operation_id AND receipt.aggregate_version=3
  AND receipt.evidence_digest=sha256(receipt.evidence_cbor) AND octet_length(receipt.cose_sign1)>0
  AND (NEW.result IS NULL OR (NEW.result->>'consumerActivationOperationId'=a.operation_id::text
   AND NEW.result->>'consumerEnvelopeId'=a.envelope_id::text AND NEW.result->>'consumerPayloadDigest'='sha256:'||encode(a.payload_digest,'hex')
   AND NEW.result->>'consumerReceiptDigest'='sha256:'||encode(receipt.evidence_digest,'hex') AND NEW.result->>'signerId'=k.signer_id
   AND NEW.result->>'trustDigest'='sha256:'||encode(k.trust_digest,'hex') AND NEW.result->>'selectionAdmissionVersion'=selection.admission_version::text
   AND EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt proof WHERE proof.operation_id=NEW.operation_id
    AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.rotation_id=NEW.rotation_id
    AND proof.slot='effective' AND proof.state='OBSERVED' AND proof.request->>'method'='PROVE' AND proof.observation->>'outcome'='SUCCEEDED'
    AND proof.observation=proof.first_observation AND proof.request->>'expectedFingerprint'=k.signer_id
    AND proof.request->>'challengeHex'=encode(k.trust_digest,'hex') AND proof.observation#>>'{descriptor,fingerprint}'=k.signer_id
    AND proof.observation#>>'{descriptor,publicKeySpkiHex}'=encode(k.public_key_spki_der,'hex') AND proof.observation#>>'{descriptor,state}'='ACTIVE'
    AND (proof.request->>'challengeExpiresAtNs')::numeric>floor(extract(epoch from clock_timestamp())*1000000)*1000
    AND (proof.observation->>'recordedAtNs')::numeric<=floor(extract(epoch from NEW.completed_at)*1000000)*1000)))))
   OR (NEW.from_state IN('OBSERVING','OLD_REVOKED','OLD_RETIRED') AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step consumer
 JOIN control.signing_key_rotation r ON r.participant_id=consumer.participant_id AND r.privacy_domain_id=consumer.privacy_domain_id AND r.rotation_id=consumer.rotation_id AND r.recovery_case_id=consumer.recovery_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key next ON next.participant_id=selection.participant_id AND next.privacy_domain_id=selection.privacy_domain_id AND next.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant next_grant ON next_grant.participant_id=next.participant_id AND next_grant.privacy_domain_id=next.privacy_domain_id AND next_grant.signer_id=next.signer_id AND next_grant.profile_digest=selection.profile_digest AND next_grant.signing_purpose_code=371
 JOIN control.business_signing_key_state next_life ON next_life.participant_id=next.participant_id AND next_life.privacy_domain_id=next.privacy_domain_id AND next_life.signer_id=next.signer_id
 JOIN control.business_signing_key old_key ON old_key.participant_id=r.participant_id AND old_key.privacy_domain_id=r.privacy_domain_id AND old_key.signer_id=r.old_signer_id
 JOIN control.business_signing_key_state old_life ON old_life.participant_id=old_key.participant_id AND old_life.privacy_domain_id=old_key.privacy_domain_id AND old_life.signer_id=old_key.signer_id
 JOIN control.identity_envelope_activation a ON a.participant_id=consumer.participant_id AND a.privacy_domain_id=consumer.privacy_domain_id AND a.operation_id=consumer.consumer_activation_operation_id
 WHERE consumer.operation_id=NEW.consumer_observation_operation_id AND consumer.participant_id=NEW.participant_id AND consumer.privacy_domain_id=NEW.privacy_domain_id
 AND consumer.rotation_id=NEW.rotation_id AND consumer.recovery_id=NEW.recovery_id AND consumer.principal_id=NEW.principal_id
 AND consumer.from_revision=6 AND consumer.from_state='CUTOVER_FENCED' AND consumer.to_state='OBSERVING' AND consumer.state='COMMITTED'
 AND consumer.authority_binding=NEW.authority_binding AND consumer.authority_digest=NEW.authority_digest
 AND consumer.evidence_digest=sha256(consumer.evidence_cbor) AND octet_length(consumer.cose_sign1)>0
 AND a.state='COMMITTED' AND a.row_version=4 AND a.payload_digest=sha256(a.payload_cbor)
 AND a.operation_id::text=consumer.result->>'consumerActivationOperationId' AND a.envelope_id::text=consumer.result->>'consumerEnvelopeId'
 AND 'sha256:'||encode(a.payload_digest,'hex')=consumer.result->>'consumerPayloadDigest'
 AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=next.participant_id AND ordinary.privacy_domain_id=next.privacy_domain_id AND ordinary.signer_id IN(next.signer_id,old_key.signer_id))
 AND next_life.state='ACTIVE' AND next.signing_purpose_code=371 AND old_key.signing_purpose_code=371
 AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
 AND selection.admission_version=(NEW.authority_binding#>>'{lease,selectionAdmissionVersion}')::numeric+1
 AND selection.admission_version::text=consumer.result->>'selectionAdmissionVersion'
 AND 'sha256:'||encode(next.trust_digest,'hex')=consumer.result->>'trustDigest' AND next.signer_id=consumer.result->>'signerId'
 AND old_key.trust_digest=decode(substr(NEW.authority_binding#>>'{lease,oldTrustDigest}',8),'hex')
 AND old_life.state=(CASE WHEN NEW.from_state='OBSERVING' AND true THEN 'ACTIVE' ELSE 'REVOKED' END)
 AND (NEW.result IS NULL OR (NEW.result->>'consumerObservationOperationId'=consumer.operation_id::text
 AND NEW.result->>'consumerActivationOperationId'=consumer.result->>'consumerActivationOperationId'
 AND NEW.result->>'consumerEnvelopeId'=consumer.result->>'consumerEnvelopeId' AND NEW.result->>'consumerPayloadDigest'=consumer.result->>'consumerPayloadDigest'
 AND NEW.result->>'consumerReceiptDigest'=consumer.result->>'consumerReceiptDigest' AND NEW.result->>'signerId'=consumer.result->>'signerId'
 AND NEW.result->>'trustDigest'=consumer.result->>'trustDigest' AND NEW.result->>'selectionAdmissionVersion'=consumer.result->>'selectionAdmissionVersion'
 AND NEW.result->>'predecessorSignerId'=old_key.signer_id AND NEW.result->>'permissionEffect'='NONE'))))
   OR length(NEW.idempotency_key) NOT BETWEEN 1 AND 200
   OR NOT coalesce(openpc.identity_envelope_rotation_step_current(NEW),false)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-STEP'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','started_at','completed_at','result','evidence_cbor','evidence_digest','cose_sign1'])
   IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','started_at','completed_at','result','evidence_cbor','evidence_digest','cose_sign1'])
  OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  OR (OLD.completed_at IS NOT NULL AND (NEW.completed_at,NEW.result,NEW.evidence_cbor,NEW.evidence_digest,NEW.cose_sign1)
   IS DISTINCT FROM (OLD.completed_at,OLD.result,OLD.evidence_cbor,OLD.evidence_digest,OLD.cose_sign1))
  THEN RAISE EXCEPTION 'DATA-6020-ENVELOPE-ROTATION-STEP'; END IF;
 IF NOT ((OLD.state='READY' AND NEW.state='STARTED') OR
  (OLD.state='STARTED' AND NEW.state IN ('COMMITTED','WRITE_AMBIGUITY','FAILED')) OR
  (OLD.state='WRITE_AMBIGUITY' AND NEW.state='STARTED')) THEN
  RAISE EXCEPTION 'DATA-6022-ENVELOPE-ROTATION-STEP'; END IF;
 IF NEW.state='STARTED' AND (
   (OLD.state='READY' AND NEW.from_state IN('OBSERVING','OLD_REVOKED','OLD_RETIRED') AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step consumer
 JOIN control.signing_key_rotation r ON r.participant_id=consumer.participant_id AND r.privacy_domain_id=consumer.privacy_domain_id AND r.rotation_id=consumer.rotation_id AND r.recovery_case_id=consumer.recovery_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key next ON next.participant_id=selection.participant_id AND next.privacy_domain_id=selection.privacy_domain_id AND next.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant next_grant ON next_grant.participant_id=next.participant_id AND next_grant.privacy_domain_id=next.privacy_domain_id AND next_grant.signer_id=next.signer_id AND next_grant.profile_digest=selection.profile_digest AND next_grant.signing_purpose_code=371
 JOIN control.business_signing_key_state next_life ON next_life.participant_id=next.participant_id AND next_life.privacy_domain_id=next.privacy_domain_id AND next_life.signer_id=next.signer_id
 JOIN control.business_signing_key old_key ON old_key.participant_id=r.participant_id AND old_key.privacy_domain_id=r.privacy_domain_id AND old_key.signer_id=r.old_signer_id
 JOIN control.business_signing_key_state old_life ON old_life.participant_id=old_key.participant_id AND old_life.privacy_domain_id=old_key.privacy_domain_id AND old_life.signer_id=old_key.signer_id
 JOIN control.identity_envelope_activation a ON a.participant_id=consumer.participant_id AND a.privacy_domain_id=consumer.privacy_domain_id AND a.operation_id=consumer.consumer_activation_operation_id
 WHERE consumer.operation_id=NEW.consumer_observation_operation_id AND consumer.participant_id=NEW.participant_id AND consumer.privacy_domain_id=NEW.privacy_domain_id
 AND consumer.rotation_id=NEW.rotation_id AND consumer.recovery_id=NEW.recovery_id AND consumer.principal_id=NEW.principal_id
 AND consumer.from_revision=6 AND consumer.from_state='CUTOVER_FENCED' AND consumer.to_state='OBSERVING' AND consumer.state='COMMITTED'
 AND consumer.authority_binding=NEW.authority_binding AND consumer.authority_digest=NEW.authority_digest
 AND consumer.evidence_digest=sha256(consumer.evidence_cbor) AND octet_length(consumer.cose_sign1)>0
 AND a.state='COMMITTED' AND a.row_version=4 AND a.payload_digest=sha256(a.payload_cbor)
 AND a.operation_id::text=consumer.result->>'consumerActivationOperationId' AND a.envelope_id::text=consumer.result->>'consumerEnvelopeId'
 AND 'sha256:'||encode(a.payload_digest,'hex')=consumer.result->>'consumerPayloadDigest'
 AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=next.participant_id AND ordinary.privacy_domain_id=next.privacy_domain_id AND ordinary.signer_id IN(next.signer_id,old_key.signer_id))
 AND next_life.state='ACTIVE' AND next.signing_purpose_code=371 AND old_key.signing_purpose_code=371
 AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
 AND selection.admission_version=(NEW.authority_binding#>>'{lease,selectionAdmissionVersion}')::numeric+1
 AND selection.admission_version::text=consumer.result->>'selectionAdmissionVersion'
 AND 'sha256:'||encode(next.trust_digest,'hex')=consumer.result->>'trustDigest' AND next.signer_id=consumer.result->>'signerId'
 AND old_key.trust_digest=decode(substr(NEW.authority_binding#>>'{lease,oldTrustDigest}',8),'hex')
 AND old_life.state=(CASE WHEN NEW.from_state='OBSERVING' AND true THEN 'ACTIVE' ELSE 'REVOKED' END)
 AND (NEW.result IS NULL OR (NEW.result->>'consumerObservationOperationId'=consumer.operation_id::text
 AND NEW.result->>'consumerActivationOperationId'=consumer.result->>'consumerActivationOperationId'
 AND NEW.result->>'consumerEnvelopeId'=consumer.result->>'consumerEnvelopeId' AND NEW.result->>'consumerPayloadDigest'=consumer.result->>'consumerPayloadDigest'
 AND NEW.result->>'consumerReceiptDigest'=consumer.result->>'consumerReceiptDigest' AND NEW.result->>'signerId'=consumer.result->>'signerId'
 AND NEW.result->>'trustDigest'=consumer.result->>'trustDigest' AND NEW.result->>'selectionAdmissionVersion'=consumer.result->>'selectionAdmissionVersion'
 AND NEW.result->>'predecessorSignerId'=old_key.signer_id AND NEW.result->>'permissionEffect'='NONE')))) OR
   (OLD.state='READY' AND NEW.from_state='CUTOVER_FENCED' AND NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r
 JOIN control.identity_envelope_activation a ON a.participant_id=r.participant_id AND a.privacy_domain_id=r.privacy_domain_id AND a.operation_id=NEW.consumer_activation_operation_id
 JOIN control.identity_envelope_proposal p ON p.participant_id=a.participant_id AND p.privacy_domain_id=a.privacy_domain_id AND p.envelope_id=a.envelope_id
 JOIN control.authority_envelope e ON e.participant_id=a.participant_id AND e.authority_envelope_id=a.envelope_id
 JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
 JOIN control.business_signing_key k ON k.participant_id=selection.participant_id AND k.privacy_domain_id=selection.privacy_domain_id AND k.signer_id=selection.signer_id
 JOIN control.identity_envelope_signing_grant g ON g.participant_id=k.participant_id AND g.privacy_domain_id=k.privacy_domain_id AND g.signer_id=k.signer_id
 JOIN control.business_signing_key_state life ON life.participant_id=k.participant_id AND life.privacy_domain_id=k.privacy_domain_id AND life.signer_id=k.signer_id
 JOIN control.mutation_candidate candidate ON candidate.participant_id=a.participant_id AND candidate.privacy_domain_id=a.privacy_domain_id AND candidate.mutation_candidate_id=a.candidate_id
 JOIN control.idempotency_record idem ON idem.participant_id=a.participant_id AND idem.privacy_domain_id=a.privacy_domain_id AND idem.operation_id=a.operation_id AND idem.idempotency_record_id=a.idempotency_record_id
 JOIN control.mutation_evidence receipt ON receipt.participant_id=a.participant_id AND receipt.privacy_domain_id=a.privacy_domain_id AND receipt.operation_id=a.operation_id AND receipt.aggregate_id=a.envelope_id
