ALTER FUNCTION openpc.guard_participant_lifecycle_history() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_context(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_context() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT'; END IF;
 IF NEW.platform_context_id<>OLD.platform_context_id OR NEW.owner_participant_id<>OLD.owner_participant_id
   OR NEW.created_at<>OLD.created_at OR OLD.state='RETIRED'
   OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1
   OR NEW.updated_at<=OLD.updated_at THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_context() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_envelope_scope(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_envelope_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SCOPE'; END IF;
 IF current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
   OR NEW.installed_by<>session_user THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-AUTHORITY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.owner_participant_id) OR NOT openpc.matches_privacy(NEW.installation_privacy_domain_id)
   OR NEW.platform_authority_epoch<>1 OR NEW.admission_version<>1 OR NOT openpc.identity_envelope_scope_valid(NEW.scope_cbor)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BINDING'; END IF;
 -- Configuration's installation owner creates this source before this adapter;
 -- the Identity migration may be installed before that cross-lane table exists.
 PERFORM 1 FROM control.participant WHERE participant_id=NEW.owner_participant_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PARTICIPANT'; END IF;
 PERFORM 1 FROM control.privacy_domain WHERE participant_id=NEW.owner_participant_id
  AND privacy_domain_id=NEW.installation_privacy_domain_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PRIVACY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('operations-generation:'||NEW.environment_id,0))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-BUSY'; END IF;
 PERFORM 1 FROM control.operations_installation i
  WHERE i.participant_id=NEW.owner_participant_id AND i.privacy_domain_id=NEW.installation_privacy_domain_id
    AND i.environment_id=NEW.environment_id AND i.state='ACTIVE' AND i.installation_digest=NEW.installation_digest
    AND openpc.operations_source_authentication_valid(i.installation)
    AND NOT EXISTS(SELECT 1 FROM control.operations_generation_commit c WHERE c.environment_id=i.environment_id)
  FOR SHARE OF i;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PROVENANCE'; END IF;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id
   AND p.owner_participant_id=NEW.owner_participant_id AND p.authority_epoch=NEW.platform_authority_epoch AND p.state='ACTIVE'
   AND p.row_version=1 AND p.xmin=(mod(pg_current_xact_id()::text::numeric,4294967296))::text::xid FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INITIAL-ROOT'; END IF;
 expected:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
  openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
  openpc.business_uuid(NEW.platform_context_id),openpc.business_uuid(NEW.owner_participant_id),
  openpc.business_uuid(NEW.installation_privacy_domain_id),NEW.platform_authority_epoch,NEW.environment_id,
  openpc.business_bytes(decode(substring(NEW.installation_digest FROM 8),'hex')),openpc.business_bytes(NEW.scope_cbor));
 IF openpc.business_cbor(NEW.admission_preimage) IS DISTINCT FROM expected OR NEW.admission_digest<>sha256(NEW.admission_preimage)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-DIGEST'; END IF;
 NEW.installed_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_envelope_scope() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_pending_runtime_effect(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_pending_runtime_effect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.state='WITHDRAWING') THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='configuration_work' THEN
  IF NEW.work_kind='RUNTIME_ACTIVATION' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-WITHDRAWING'; END IF;
 ELSIF TG_TABLE_NAME='runtime_target' THEN
 IF TG_OP='UPDATE' AND (
   NEW.active_generation_digest IS DISTINCT FROM OLD.active_generation_digest
   OR NEW.desired_generation_digest IS DISTINCT FROM OLD.desired_generation_digest)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-WITHDRAWING'; END IF;
 IF TG_OP='INSERT' AND (
   NEW.active_generation_digest IS NOT NULL OR NEW.desired_generation_digest IS NOT NULL)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-WITHDRAWING'; END IF;
 ELSE RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_pending_runtime_effect() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_recovery_case(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_recovery_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE source record; signer_repair boolean; review boolean;
BEGIN
 signer_repair:=NEW.signer_repair_enrollment_id IS NOT NULL;
 review:=TG_OP='UPDATE' AND NEW.reviewed_at IS NOT NULL AND OLD.reviewed_at IS NULL;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' THEN
  IF EXISTS(SELECT 1 FROM control.platform_recovery_enrollment completion_source
   WHERE completion_source.participant_id=NEW.participant_id AND completion_source.privacy_domain_id=NEW.privacy_domain_id
    AND completion_source.enrollment_id=NEW.enrollment_id
    AND CASE WHEN completion_source.document#>'{source}' ? 'activatedHandoff' THEN
      NEW.intent->>'completionSourceDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(completion_source.document#>'{source,activatedHandoff}'),'UTF8')),'hex')
      OR NOT (NEW.intent ? 'continuation') OR NEW.intent ?| ARRAY['pendingExpiry','approvalContinuation','closedApprovalSourceDigest','supersession']
     ELSE NEW.intent ? 'completionSourceDigest' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF EXISTS(SELECT 1 FROM control.platform_recovery_enrollment source_enrollment WHERE source_enrollment.participant_id=NEW.participant_id
    AND source_enrollment.privacy_domain_id=NEW.privacy_domain_id AND source_enrollment.enrollment_id=NEW.enrollment_id
    AND CASE WHEN source_enrollment.document#>'{source}' ? 'closedApproval' THEN
      NEW.intent->>'closedApprovalSourceDigest' IS DISTINCT FROM
        'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(source_enrollment.document#>'{source,closedApproval}'),'UTF8')),'hex')
      OR NEW.intent->'approvalContinuation' IS DISTINCT FROM source_enrollment.document#>'{source,closedApproval,approval}'
     ELSE NEW.intent ? 'closedApprovalSourceDigest' END)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 OR NEW.activated_at IS NOT NULL
   OR NEW.intent_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.intent),'UTF8'))
   OR NEW.intent->>'recoveryId' IS DISTINCT FROM NEW.recovery_id::text
   OR NEW.intent->>'enrollmentId' IS DISTINCT FROM coalesce(NEW.enrollment_id,NEW.signer_repair_enrollment_id)::text
   OR NEW.intent->>'enrollmentRevision' IS DISTINCT FROM NEW.enrollment_revision::text
   OR NEW.intent->>'enrollmentDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.enrollment_digest,'hex')
   OR (NEW.intent->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
   OR (NEW.intent->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
   OR NEW.intent->>'schema' IS NULL OR NEW.intent->>'schema' NOT IN ('pc.identity.platform-recovery-intent','pc.identity.discovery-certificate-recovery-intent','pc.identity.identity-envelope-recovery-intent')
   OR (NEW.intent->>'schemaVersion' IS DISTINCT FROM '1'
    AND NOT (NEW.intent->>'schemaVersion' IS NOT DISTINCT FROM '2'
     AND NEW.intent->>'schema' IS NOT DISTINCT FROM 'pc.identity.discovery-certificate-recovery-intent'
     AND NOT signer_repair))
   OR jsonb_array_length(NEW.planned_record_ids)<>(CASE WHEN signer_repair THEN 2 WHEN NEW.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' THEN 0 ELSE 5 END)
   OR NEW.completion_operation_id IS NOT NULL OR NEW.completion_result IS NOT NULL
   OR num_nonnulls(NEW.reviewed_at,NEW.reviewed_by_principal_id,NEW.review_operation_id,NEW.review_note_digest)<>0
   OR (NEW.intent#>>'{lifetimes,profile}'='LOCAL_QA_10X' AND
       (current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' OR
        current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X'))
   OR (NEW.intent ? 'lifetimes' AND (NOT (NEW.intent->'lifetimes' ?& ARRAY['profile','leaseMs','administratorMs'])
      OR (NEW.intent->'lifetimes')-ARRAY['profile','leaseMs','administratorMs']<>'{}'::jsonb
      OR NEW.intent#>>'{lifetimes,profile}' NOT IN ('C17','LOCAL_QA','LOCAL_QA_10X')
      OR (NEW.intent#>>'{lifetimes,leaseMs}')::bigint NOT BETWEEN 1 AND CASE NEW.intent#>>'{lifetimes,profile}' WHEN 'LOCAL_QA_10X' THEN 9000000 WHEN 'LOCAL_QA' THEN 3600000 ELSE 900000 END
      OR (NEW.intent#>>'{lifetimes,administratorMs}')::bigint NOT BETWEEN 1 AND CASE NEW.intent#>>'{lifetimes,profile}' WHEN 'LOCAL_QA_10X' THEN 36000000 WHEN 'LOCAL_QA' THEN 86400000 ELSE 3600000 END
      OR NEW.valid_until>NEW.valid_from+((NEW.intent#>>'{lifetimes,leaseMs}')::bigint*interval '1 millisecond')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 ELSE
  IF NEW.row_version<>OLD.row_version+1 OR NEW.updated_at<=OLD.updated_at
   OR (to_jsonb(NEW)-ARRAY['state','row_version','updated_at','activated_at','activation_operation_id',
      'activation_evidence_cbor','activation_evidence_digest','activation_cose','lease_bindings','completion_operation_id','completion_result',
      'reviewed_at','reviewed_by_principal_id','review_operation_id','review_note_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','updated_at','activated_at','activation_operation_id',
      'activation_evidence_cbor','activation_evidence_digest','activation_cose','lease_bindings','completion_operation_id','completion_result',
      'reviewed_at','reviewed_by_principal_id','review_operation_id','review_note_digest'])
   OR NOT ((OLD.state='DRAFT' AND NEW.state IN ('REQUESTED','REVOKED','EXPIRED'))
      OR (OLD.state='REQUESTED' AND NEW.state IN ('ACTIVE','REVOKED','EXPIRED'))
      OR (OLD.state='ACTIVE' AND NEW.state IN ('COMPLETED','REVOKED','EXPIRED'))
      OR (review AND OLD.state=NEW.state AND OLD.state IN ('COMPLETED','REVOKED','EXPIRED')))
   OR (NEW.state<>'ACTIVE' AND (NEW.activated_at,NEW.activation_operation_id,NEW.activation_evidence_cbor,
      NEW.activation_evidence_digest,NEW.activation_cose,NEW.lease_bindings) IS DISTINCT FROM
     (OLD.activated_at,OLD.activation_operation_id,OLD.activation_evidence_cbor,
      OLD.activation_evidence_digest,OLD.activation_cose,OLD.lease_bindings))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.completion_operation_id,NEW.completion_result) IS DISTINCT FROM (OLD.completion_operation_id,OLD.completion_result)
  AND NOT (OLD.state='ACTIVE' AND NEW.state='COMPLETED' AND NEW.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND NEW.completion_operation_id IS NOT NULL AND NEW.completion_result IS NOT NULL) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF signer_repair THEN
  IF NEW.enrollment_id IS NOT NULL OR NEW.intent->>'schema' IS DISTINCT FROM 'pc.identity.identity-envelope-recovery-intent'
   OR NEW.intent->>'purpose' IS DISTINCT FROM 'IDENTITY_ENVELOPE_SIGNER_REPAIR_ONLY'
   OR NEW.intent->'postReviewRequired' IS DISTINCT FROM 'true'::jsonb
   OR NEW.intent-ARRAY['schema','schemaVersion','purpose','recoveryId','enrollmentId','enrollmentRevision','enrollmentDigest',
     'rotationId','creationOperationId','sourceParticipantEpoch','sourceIssuerPrincipalEpoch','sourceIssuerCredentialEpoch','lifetimes',
     'oldTrustDigest','selectionAdmissionVersion','validFrom','validUntil','postReviewRequired']<>'{}'::jsonb
   OR NEW.planned_record_ids IS DISTINCT FROM jsonb_build_array(NEW.intent->>'rotationId',NEW.intent->>'creationOperationId')
   OR NEW.intent->>'rotationId'=NEW.intent->>'creationOperationId'
   OR (NEW.intent ? 'lifetimes' AND NEW.intent#>>'{lifetimes,profile}' IS DISTINCT FROM 'LOCAL_QA_10X')
   OR NEW.valid_until>NEW.valid_from+coalesce((NEW.intent#>>'{lifetimes,leaseMs}')::bigint,900000)*interval '1 millisecond'
   OR (TG_OP='INSERT' AND EXISTS(SELECT 1 FROM control.platform_recovery_case prior
     JOIN control.identity_envelope_recovery_enrollment original ON original.enrollment_id=prior.signer_repair_enrollment_id
      AND original.participant_id=prior.participant_id
     JOIN control.identity_envelope_recovery_enrollment proposed ON proposed.enrollment_id=NEW.signer_repair_enrollment_id
      AND proposed.participant_id=NEW.participant_id
     WHERE prior.participant_id=NEW.participant_id AND original.document->>'issuerPrincipalId'=proposed.document->>'issuerPrincipalId'
      AND prior.activated_at IS NOT NULL AND prior.reviewed_at IS NULL))
   -- Completion is owned by the genuine consumer/old-key retirement suffix.
   OR NEW.state='COMPLETED' THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  IF NEW.state='ACTIVE' AND (NEW.activation_operation_id IS DISTINCT FROM openpc.current_operation_id()
    OR NEW.activation_operation_id::text IS DISTINCT FROM NEW.lease_bindings->>'activationOperationId'
    OR NEW.activated_at IS DISTINCT FROM (NEW.lease_bindings->>'validFrom')::timestamptz
    OR NOT coalesce(openpc.identity_envelope_recovery_binding_current(NEW.signer_repair_enrollment_id,NEW.intent,NEW.lease_bindings),false)
    OR NOT openpc.identity_envelope_recovery_proofs_current(NEW,(NEW.lease_bindings#>>'{proofIds,3}')::uuid)) THEN
    RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.reviewed_at,NEW.reviewed_by_principal_id,NEW.review_operation_id,NEW.review_note_digest)
   IS DISTINCT FROM (OLD.reviewed_at,OLD.reviewed_by_principal_id,OLD.review_operation_id,OLD.review_note_digest) THEN
  IF NOT review OR NOT signer_repair OR NEW.review_operation_id IS DISTINCT FROM openpc.current_operation_id()
    OR OLD.activated_at IS NULL OR OLD.state NOT IN ('COMPLETED','REVOKED','EXPIRED')
    OR NEW.reviewed_by_principal_id IS NULL OR NEW.review_note_digest IS NULL
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment enrollment
      JOIN control.mutation_candidate candidate ON candidate.participant_id=enrollment.participant_id
       AND candidate.privacy_domain_id=enrollment.privacy_domain_id AND candidate.catalog_operation_id='ID-OP-RECOVERY-POST-REVIEW'
       AND candidate.resource_id=NEW.recovery_id AND candidate.maker_principal_id=NEW.reviewed_by_principal_id
       AND candidate.state='APPROVED' AND candidate.candidate_document->>'recoveryId'=NEW.recovery_id::text
       AND sha256(convert_to(candidate.candidate_document->>'note','UTF8'))=NEW.review_note_digest
      JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id
       AND approval.privacy_domain_id=candidate.privacy_domain_id AND approval.subject_id=candidate.mutation_candidate_id
       AND approval.subject_digest=candidate.candidate_digest AND approval.state='APPROVED'
      WHERE enrollment.enrollment_id=NEW.signer_repair_enrollment_id
       AND NEW.reviewed_by_principal_id::text NOT IN (enrollment.document->>'issuerPrincipalId',enrollment.document#>>'{recoveryPrincipal,principalId}')
       AND approval.checker_principal_id::text NOT IN (enrollment.document->>'issuerPrincipalId',enrollment.document#>>'{recoveryPrincipal,principalId}')
       AND approval.checker_principal_id<>NEW.reviewed_by_principal_id
       AND EXISTS(SELECT 1 FROM control.approval_decision_record decision WHERE decision.participant_id=approval.participant_id
         AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
         AND decision.approver_principal_id=approval.checker_principal_id AND decision.decision='APPROVE'
         AND decision.candidate_digest=candidate.candidate_digest)) THEN
    RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-REVIEW'; END IF;
 END IF;
 IF NEW.state IN ('DRAFT','REQUESTED','ACTIVE') THEN
  IF (NEW.intent ? 'continuation' OR NEW.intent ? 'pendingExpiry') AND NEW.planned_record_ids IS DISTINCT FROM
    jsonb_build_array(NEW.intent#>>'{preparation,replacementId}',NEW.intent#>>'{preparation,administrators,0,envelopeId}',
      NEW.intent#>>'{preparation,administrators,0,assignmentId}',NEW.intent#>>'{preparation,administrators,1,envelopeId}',
      NEW.intent#>>'{preparation,administrators,1,assignmentId}') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF NEW.intent ? 'continuation' AND NOT coalesce(openpc.platform_recovery_continuation_current(NEW.participant_id,NEW.enrollment_id,NEW.intent->'continuation',NEW.intent->'preparation'),false) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF NEW.intent ? 'pendingExpiry' AND openpc.platform_recovery_pending_expiry_intent_current(NEW.participant_id,NEW.enrollment_id,NEW.intent) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF NEW.intent ? 'supersession' AND NOT openpc.platform_recovery_supersession_current(NEW.participant_id,NEW.enrollment_id,NEW.intent->'supersession',NEW.intent->'preparation') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF signer_repair THEN
   SELECT * INTO source FROM control.identity_envelope_recovery_enrollment e WHERE e.enrollment_id=NEW.signer_repair_enrollment_id
    AND e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.state='ACTIVE'
    AND e.row_version=NEW.enrollment_revision AND e.document_digest=NEW.enrollment_digest
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp()
    AND openpc.identity_envelope_recovery_source_current(e.enrollment_id);
  ELSE
   SELECT * INTO source FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=NEW.enrollment_id
    AND e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.state='ACTIVE'
    AND e.row_version=NEW.enrollment_revision AND e.document_digest=NEW.enrollment_digest
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp();
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF signer_repair AND (
    NEW.intent->>'sourceParticipantEpoch' IS DISTINCT FROM source.document->>'issuerParticipantEpoch'
    OR NEW.intent->>'sourceIssuerPrincipalEpoch' IS DISTINCT FROM source.document->>'issuerPrincipalEpoch'
    OR NEW.intent->>'sourceIssuerCredentialEpoch' IS DISTINCT FROM source.document->>'issuerCredentialEpoch'
    OR NEW.intent->>'oldTrustDigest' IS DISTINCT FROM source.document->>'oldTrustDigest'
    OR NEW.intent->>'selectionAdmissionVersion' IS DISTINCT FROM source.document->>'selectionAdmissionVersion') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  IF NOT signer_repair THEN
   IF (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY') IS DISTINCT FROM (NEW.intent ? 'pendingExpiry') THEN
    RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
   IF (source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION') IS DISTINCT FROM (NEW.intent ? 'continuation') THEN
    RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  END IF;
  IF NEW.intent->>'schema' IS DISTINCT FROM (CASE source.document->>'schema'
     WHEN 'pc.identity.platform-recovery-enrollment' THEN 'pc.identity.platform-recovery-intent'
     WHEN 'pc.identity.discovery-certificate-recovery-enrollment' THEN 'pc.identity.discovery-certificate-recovery-intent'
     WHEN 'pc.identity.identity-envelope-recovery-enrollment' THEN 'pc.identity.identity-envelope-recovery-intent' ELSE NULL END)
    OR NEW.valid_until>source.valid_until OR NEW.valid_until<=clock_timestamp()
   OR (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1')
   OR (NEW.intent#>>'{lifetimes,profile}' IN ('LOCAL_QA','LOCAL_QA_10X') AND source.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF NEW.state IN ('REQUESTED','ACTIVE') THEN
  IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
     JOIN control.platform_recovery_challenge h ON h.participant_id=proof.participant_id
      AND h.privacy_domain_id=proof.privacy_domain_id AND h.recovery_id=proof.recovery_id
      AND h.challenge_id=proof.challenge_id AND h.proof_id=proof.proof_id
     WHERE proof.recovery_id=NEW.recovery_id
   AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='REQUEST'
   AND proof.principal_id::text=source.document#>>'{recoveryPrincipal,principalId}' AND proof.intent_digest=NEW.intent_digest
   AND proof.verified_at<=clock_timestamp()
    AND proof.verified_at>clock_timestamp()-make_interval(secs=>h.verified_proof_max_age_ms/1000.0)
    AND (h.verified_proof_max_age_ms=300000 OR (h.verified_proof_max_age_ms=3000000
      AND h.duration_profile='LOCAL_QA_10X' AND h.expires_at>clock_timestamp()))) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF NEW.state='ACTIVE' THEN
  IF NEW.activation_evidence_digest<>sha256(NEW.activation_evidence_cbor)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(source.document->'custodians') custodian
    WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
     JOIN control.platform_recovery_challenge h ON h.participant_id=proof.participant_id
      AND h.privacy_domain_id=proof.privacy_domain_id AND h.recovery_id=proof.recovery_id
      AND h.challenge_id=proof.challenge_id AND h.proof_id=proof.proof_id
     WHERE proof.recovery_id=NEW.recovery_id
     AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='APPROVE'
     AND proof.principal_id::text=custodian->>'principalId' AND proof.credential_id::text=custodian->>'credentialId'
     AND proof.principal_epoch::text=custodian->>'principalEpoch' AND proof.credential_epoch::text=custodian->>'credentialEpoch'
     AND proof.intent_digest=NEW.intent_digest AND proof.verified_at<=clock_timestamp()
    AND proof.verified_at>clock_timestamp()-make_interval(secs=>h.verified_proof_max_age_ms/1000.0)
    AND (h.verified_proof_max_age_ms=300000 OR (h.verified_proof_max_age_ms=3000000
      AND h.duration_profile='LOCAL_QA_10X' AND h.expires_at>clock_timestamp()))))
   OR NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
     JOIN control.platform_recovery_challenge h ON h.participant_id=proof.participant_id
      AND h.privacy_domain_id=proof.privacy_domain_id AND h.recovery_id=proof.recovery_id
      AND h.challenge_id=proof.challenge_id AND h.proof_id=proof.proof_id
     WHERE proof.recovery_id=NEW.recovery_id
    AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='ACTIVATE'
    AND proof.principal_id::text=source.document#>>'{recoveryPrincipal,principalId}' AND proof.intent_digest=NEW.intent_digest
    AND proof.verified_at<=clock_timestamp()
    AND proof.verified_at>clock_timestamp()-make_interval(secs=>h.verified_proof_max_age_ms/1000.0)
    AND (h.verified_proof_max_age_ms=300000 OR (h.verified_proof_max_age_ms=3000000
      AND h.duration_profile='LOCAL_QA_10X' AND h.expires_at>clock_timestamp()))) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_recovery_case() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_recovery_challenge(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_recovery_challenge() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='UPDATE' AND (OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL OR NEW.proof_id IS NULL
   OR (to_jsonb(NEW)-ARRAY['consumed_at','proof_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['consumed_at','proof_id'])
   OR NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof p WHERE p.proof_id=NEW.proof_id AND p.challenge_id=NEW.challenge_id
    AND p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id AND p.recovery_id=NEW.recovery_id)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND (NEW.consumed_at IS NOT NULL OR NEW.proof_id IS NOT NULL) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND NEW.verified_proof_max_age_ms IS DISTINCT FROM
   (CASE WHEN NEW.duration_profile='LOCAL_QA_10X' THEN 3000000 ELSE 300000 END) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND NEW.duration_profile='LOCAL_QA_10X' AND
  (current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
   OR current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X'
   OR NOT EXISTS(SELECT 1 FROM control.platform_recovery_case r
     WHERE r.recovery_id=NEW.recovery_id AND r.participant_id=NEW.participant_id
      AND r.privacy_domain_id=NEW.privacy_domain_id AND r.intent_digest=NEW.intent_digest
      AND r.intent#>>'{lifetimes,profile}'='LOCAL_QA_10X' AND NEW.expires_at<=r.valid_until)
   OR NOT EXISTS(SELECT 1 FROM control.session s JOIN control.credential c
      ON c.participant_id=s.participant_id AND c.principal_id=s.principal_id AND c.credential_id=NEW.credential_id
     WHERE s.participant_id=NEW.participant_id AND s.principal_id=NEW.principal_id AND s.session_id=NEW.session_id
      AND s.session_epoch=NEW.session_epoch AND s.duration_profile='LOCAL_QA_10X' AND s.state='ACTIVE'
      AND NEW.expires_at<=s.idle_expires_at AND NEW.expires_at<=s.absolute_expires_at
      AND c.kind='WEBAUTHN' AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp()
      AND (c.valid_until IS NULL OR NEW.expires_at<=c.valid_until))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_recovery_challenge() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_recovery_enrollment(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_recovery_enrollment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.row_version<>OLD.row_version+1
   OR (to_jsonb(NEW)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 ELSE
  IF NEW.document->>'schema' IS NULL OR NEW.document->>'schema' NOT IN ('pc.identity.platform-recovery-enrollment','pc.identity.discovery-certificate-recovery-enrollment')
   OR (NEW.source_purpose='EXPIRED_REPLACEMENT' AND NEW.document->>'schemaVersion' IS DISTINCT FROM '1')
   OR (NEW.source_purpose='ROOT_EXPIRY_RECOVERY' AND NEW.document->>'schemaVersion' IS DISTINCT FROM '2')
   OR (NEW.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' AND (NEW.document->>'schemaVersion' IS DISTINCT FROM '3'
     OR NEW.document->>'schema' IS DISTINCT FROM 'pc.identity.platform-recovery-enrollment'))
   OR (NEW.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' AND (NEW.document->>'schemaVersion' IS DISTINCT FROM '4'
     OR NEW.document->>'schema' IS DISTINCT FROM 'pc.identity.platform-recovery-enrollment'))
   OR NEW.state<>'ACTIVE' OR NEW.row_version<>1 OR NEW.document_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.document),'UTF8'))
   OR NEW.document->>'enrollmentId' IS DISTINCT FROM NEW.enrollment_id::text
   OR NEW.document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR NEW.document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR NEW.document->>'platformContextId' IS DISTINCT FROM NEW.platform_context_id::text
   OR (NEW.source_purpose='EXPIRED_REPLACEMENT' AND NEW.document->>'expiredReplacementId' IS DISTINCT FROM NEW.expired_replacement_id::text)
   OR NEW.document->>'rootEpoch' IS DISTINCT FROM NEW.root_epoch::text
   OR NEW.document->>'rootRevision' IS DISTINCT FROM NEW.root_revision::text
   OR NEW.document->>'rootDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.root_digest,'hex')
   OR (NEW.document->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
   OR (NEW.document->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
   OR NOT coalesce(openpc.platform_recovery_source_root_current(NEW),false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_recovery_enrollment() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_recovery_envelope(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_recovery_envelope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE recovery control.platform_recovery_case; source control.platform_recovery_enrollment; binding jsonb;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.representation='RECOVERY_V1' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  RETURN OLD;
 END IF;
 IF NEW.representation<>'RECOVERY_V1' THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=NEW.recovery_case_id
  AND c.participant_id=NEW.participant_id AND c.state='ACTIVE' AND c.valid_until>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 SELECT * INTO source FROM control.platform_recovery_enrollment s WHERE s.enrollment_id=recovery.enrollment_id
  AND s.participant_id=recovery.participant_id AND s.privacy_domain_id=recovery.privacy_domain_id AND s.state='ACTIVE'
  AND s.row_version=recovery.enrollment_revision AND s.document_digest=recovery.enrollment_digest;
 SELECT value INTO binding FROM jsonb_array_elements(recovery.lease_bindings) a(value)
  WHERE value->>'envelopeId'=NEW.authority_envelope_id::text;
 IF source.enrollment_id IS NULL OR binding IS NULL OR NEW.state<>'ACTIVE' OR NEW.row_version<>1
  OR NEW.authority_epoch<>1 OR NEW.delegation_epoch<>0
  OR NEW.last_mutation_operation_id IS DISTINCT FROM recovery.activation_operation_id
  OR NEW.last_mutation_operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NEW.principal_id::text IS DISTINCT FROM binding->>'principalId'
  OR NEW.maker_principal_id::text IS DISTINCT FROM source.document#>>'{recoveryPrincipal,principalId}'
  OR NEW.checker_principal_id::text IS DISTINCT FROM source.document#>>'{custodians,0,principalId}'
  OR NEW.platform_context_id IS DISTINCT FROM source.platform_context_id OR NEW.platform_authority_epoch IS DISTINCT FROM source.root_epoch
  OR NEW.valid_from IS DISTINCT FROM (binding#>>'{permissions,validFrom}')::timestamptz OR NEW.valid_until IS DISTINCT FROM recovery.valid_until
  OR NEW.semantic_cbor IS DISTINCT FROM decode(binding->>'evidenceCbor','hex')
  OR NEW.semantic_digest IS DISTINCT FROM decode(binding->>'evidenceDigest','hex') OR NEW.semantic_digest<>sha256(NEW.semantic_cbor)
  OR NEW.cose_sign1 IS DISTINCT FROM decode(binding->>'coseSign1','hex') OR octet_length(NEW.cose_sign1)=0
  OR to_jsonb(NEW.privacy_domain_ids) IS DISTINCT FROM binding#>'{permissions,privacyDomainIds}'
  OR to_jsonb(NEW.action_intent_ids) IS DISTINCT FROM binding#>'{permissions,actionIntentIds}'
  OR to_jsonb(NEW.resource_ids) IS DISTINCT FROM binding#>'{permissions,resourceIds}'
  OR to_jsonb(NEW.risk_classes) IS DISTINCT FROM binding#>'{permissions,riskClasses}'
  OR cardinality(NEW.runtime_capability_ids)<>0 OR '*'=ANY(NEW.resource_ids)
  OR NOT NEW.maker_checker_required OR NOT NEW.step_up_required OR NEW.onward_delegation_depth<>0 THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_recovery_envelope() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_recovery_proof(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_recovery_proof() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_challenge c JOIN control.platform_recovery_case r
   ON r.recovery_id=c.recovery_id AND r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id
  JOIN (SELECT enrollment_id,participant_id,privacy_domain_id,state,row_version,document_digest,document,valid_from,valid_until,
    CASE document->>'schema' WHEN 'pc.identity.platform-recovery-enrollment' THEN 'pc.identity.platform-recovery-intent'
      WHEN 'pc.identity.discovery-certificate-recovery-enrollment' THEN 'pc.identity.discovery-certificate-recovery-intent' END purpose
    FROM control.platform_recovery_enrollment
   UNION ALL SELECT enrollment_id,participant_id,privacy_domain_id,state,row_version,document_digest,document,valid_from,valid_until,
    'pc.identity.identity-envelope-recovery-intent' purpose FROM control.identity_envelope_recovery_enrollment) source
   ON source.enrollment_id=coalesce(r.enrollment_id,r.signer_repair_enrollment_id) AND source.purpose=r.intent->>'schema'
   AND source.participant_id=r.participant_id AND source.privacy_domain_id=r.privacy_domain_id
   AND source.state='ACTIVE' AND source.row_version=r.enrollment_revision AND source.document_digest=r.enrollment_digest
   AND (r.signer_repair_enrollment_id IS NULL OR openpc.identity_envelope_recovery_source_current(source.enrollment_id))
  JOIN LATERAL jsonb_array_elements(CASE WHEN NEW.phase='APPROVE' THEN source.document->'custodians'
    ELSE jsonb_build_array(source.document->'recoveryPrincipal') END) signer
   ON signer->>'principalId'=NEW.principal_id::text AND signer->>'credentialId'=NEW.credential_id::text
    AND signer->>'principalEpoch'=NEW.principal_epoch::text AND signer->>'credentialEpoch'=NEW.credential_epoch::text
  JOIN control.principal p ON p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id
   AND p.state='ACTIVE' AND p.authority_epoch=NEW.principal_epoch
  JOIN control.credential credential ON credential.participant_id=p.participant_id AND credential.principal_id=p.principal_id
   AND credential.credential_id=NEW.credential_id AND credential.credential_epoch=NEW.credential_epoch
   AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  JOIN control.session session ON session.participant_id=p.participant_id AND session.principal_id=p.principal_id
   AND session.session_id=NEW.session_id AND session.session_epoch=NEW.session_epoch AND session.authority_epoch=p.authority_epoch
   AND session.context_mode='PLATFORM' AND session.privacy_domain_id IS NULL AND session.state='ACTIVE'
   AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
  JOIN control.participant participant ON participant.participant_id=p.participant_id AND participant.state='ACTIVE'
   AND participant.authority_epoch=session.participant_epoch
  WHERE c.challenge_id=NEW.challenge_id AND c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND c.recovery_id=NEW.recovery_id AND c.principal_id=NEW.principal_id AND c.credential_id=NEW.credential_id
   AND c.session_id=NEW.session_id AND c.session_epoch=NEW.session_epoch AND c.phase=NEW.phase
   AND c.intent_digest=NEW.intent_digest AND r.intent_digest=NEW.intent_digest
   AND ((NEW.phase='REQUEST' AND r.state='DRAFT') OR (NEW.phase IN ('APPROVE','ACTIVATE') AND r.state='REQUESTED'))
   AND c.consumed_at IS NULL AND c.expires_at>clock_timestamp() AND r.valid_until>clock_timestamp()
   AND NEW.verified_at BETWEEN c.created_at AND clock_timestamp()
   AND source.valid_from<=clock_timestamp() AND source.valid_until>clock_timestamp()
   AND (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator h
    WHERE h.participant_id=p.participant_id AND h.principal_id=p.principal_id AND h.credential_id=credential.credential_id))
   AND NEW.assertion_evidence#>>'{verified,version}'='OPENPC_VERIFIED_WEBAUTHN_ASSERTION_V1'
   AND NEW.assertion_evidence#>>'{verified,userVerification}'='REQUIRED_VERIFIED'
   AND NEW.assertion_evidence#>>'{verified,credentialId}'=credential.credential_id::text
   AND NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}'='sha256:'||encode(credential.public_key_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,principalId}'=NEW.principal_id::text
   AND NEW.assertion_evidence#>>'{verified,sessionId}'=NEW.session_id::text
   AND NEW.assertion_evidence#>>'{verified,actionIntentId}'='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
   AND NEW.assertion_evidence#>>'{verified,resourceDigest}'='sha256:'||encode(NEW.intent_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,challengeDigest}'='sha256:'||encode(c.challenge_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,origin}'=c.origin
   AND NEW.assertion_evidence#>>'{verified,signCount}'=NEW.authenticator_sign_count::text
   AND (NEW.assertion_evidence#>>'{verified,verifiedAt}')::timestamptz=NEW.verified_at) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NEW.assertion_digest IS DISTINCT FROM sha256(convert_to(NEW.assertion_evidence#>>'{verified,version}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,principalId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,sessionId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,actionIntentId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,resourceDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,challengeDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,rpIdHash}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,origin}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,authenticatorDataDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,clientDataJsonDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signatureDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signCount}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,verifiedAt}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,userVerification}','UTF8')) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_recovery_proof() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_scope_replacement(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_scope_replacement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE root control.platform_context; initial control.platform_envelope_scope; base jsonb; expected jsonb; predecessor bytea; predecessor_scope bytea; current_scope jsonb; next_scope jsonb; dimension integer; readiness jsonb;
BEGIN
 IF TG_OP='DELETE' OR current_user<>'openpc_control_owner' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT root FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id FOR UPDATE;
  SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=root.platform_context_id;
  SELECT s.admission_digest,s.scope_cbor INTO STRICT predecessor,predecessor_scope FROM (
    SELECT platform_context_id,platform_authority_epoch,admission_digest,scope_cbor FROM control.platform_envelope_scope
    UNION ALL
    SELECT s.platform_context_id,s.platform_authority_epoch,s.admission_digest,s.scope_cbor
      FROM control.platform_envelope_scope_successor s JOIN control.platform_scope_replacement r
        ON r.replacement_id=s.replacement_id AND r.state='COMMITTED'
    UNION ALL SELECT platform_context_id,platform_authority_epoch,admission_digest,scope_cbor FROM control.root_expiry_recovery_scope
   ) s WHERE s.platform_context_id=root.platform_context_id AND s.platform_authority_epoch=root.authority_epoch;
  IF coalesce((root.owner_participant_id<>NEW.participant_id OR initial.installation_privacy_domain_id<>NEW.privacy_domain_id
    OR root.state<>'ACTIVE' OR root.authority_epoch<>NEW.predecessor_epoch OR root.row_version<>NEW.expected_root_revision
    OR NEW.state<>'WITHDRAWING' OR NEW.row_version<>1 OR NEW.prepare_operation_id<>openpc.current_operation_id()
    OR NEW.candidate->>'replacementId'<>NEW.replacement_id::text
    OR NEW.candidate->>'platformContextId'<>NEW.platform_context_id::text
    OR NEW.candidate->>'predecessorEpoch'<>NEW.predecessor_epoch::text
    OR NEW.candidate->>'expectedRootRevision'<>NEW.expected_root_revision::text
    OR NEW.candidate->>'predecessorDigest'<>'sha256:'||encode(NEW.predecessor_digest,'hex')
    OR NEW.candidate->'successorScope' IS DISTINCT FROM openpc.platform_scope_document(NEW.successor_scope_cbor)
    OR NEW.predecessor_digest IS DISTINCT FROM predecessor),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
  current_scope:=openpc.business_cbor(predecessor_scope); next_scope:=openpc.business_cbor(NEW.successor_scope_cbor);
  IF NOT coalesce(openpc.identity_envelope_scope_valid(NEW.successor_scope_cbor),false)
    OR coalesce(((next_scope->>'3')::numeric<(current_scope->>'3')::numeric
      OR (next_scope->>'4')::numeric>(current_scope->>'4')::numeric
      OR (next_scope->>'3')::numeric>extract(epoch from clock_timestamp())*1000000000
      OR (next_scope->>'4')::numeric<=extract(epoch from clock_timestamp())*1000000000
      OR next_scope->>'7'<>'0' OR next_scope=current_scope),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BOUNDS'; END IF;
  FOR dimension IN 1..7 LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(next_scope->'2'->dimension::text) value
      WHERE NOT (current_scope->'2'->dimension::text @> jsonb_build_array(value)))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RUNTIME-WIDENING'; END IF;
  END LOOP;
  IF (SELECT coalesce(jsonb_agg(entry ORDER BY entry->>'targetId'),'[]') FROM jsonb_array_elements(NEW.candidate->'affectedTargets') entry)
    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(target ORDER BY target->>'targetId'),'[]')
      FROM openpc.read_platform_scope_affected_targets(NEW.platform_context_id))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
  base:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
    openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
    openpc.business_uuid(root.platform_context_id),openpc.business_uuid(root.owner_participant_id),
    openpc.business_uuid(initial.installation_privacy_domain_id),NEW.predecessor_epoch+1,initial.environment_id,
    openpc.business_bytes(decode(substring(initial.installation_digest FROM 8),'hex')),
    openpc.business_bytes(NEW.successor_scope_cbor));
  expected:=openpc.business_cbor(NEW.successor_preimage);
  IF jsonb_typeof(expected) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE';
  END IF;
  IF coalesce((jsonb_array_length(expected)<>7
    OR expected->>0<>'pc.identity.platform-envelope-scope.successor.v1' OR expected->>1<>'1'
    OR expected->2 IS DISTINCT FROM openpc.business_uuid(NEW.replacement_id)
    OR expected->3 IS DISTINCT FROM openpc.business_uuid(NEW.prepare_operation_id)
    OR expected->>4<>NEW.predecessor_epoch::text
    OR expected->5 IS DISTINCT FROM openpc.business_bytes(NEW.predecessor_digest)
    OR openpc.business_cbor(decode(expected#>>'{6,bytes}','hex')) IS DISTINCT FROM base),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE'; END IF;
 ELSIF NEW.state='SUPERSEDED' THEN
  -- Candidate visibility is bound to an inserted replacement by RLS. Validate
  -- its complete consumed provenance at the deferred boundary below, after
  -- both rows exist, without granting pre-insert candidate visibility.
  IF OLD.state<>'WITHDRAWING' OR OLD.row_version<>1 OR NEW.row_version<>2
    OR NEW.superseded_by IS NULL OR NEW.superseded_by=OLD.replacement_id
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.candidate->'administrators') a
      WHERE greatest((a#>>'{usable,validUntilNs}')::numeric,(a#>>'{grantable,validUntilNs}')::numeric)
        >extract(epoch from clock_timestamp())*1000000000)
    OR (to_jsonb(NEW)-'state'-'row_version'-'superseded_by') IS DISTINCT FROM
       (to_jsonb(OLD)-'state'-'row_version'-'superseded_by')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
 ELSE
  readiness:=openpc.read_platform_scope_replacement_readiness(OLD.replacement_id);
  IF readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
    OR NEW.readiness_digest IS DISTINCT FROM decode(substring(readiness->>'readinessDigest' from 8),'hex')
    OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
  IF coalesce((OLD.state<>'WITHDRAWING' OR NEW.state<>'COMMITTED' OR NEW.row_version<>OLD.row_version+1
    OR NEW.commit_operation_id<>openpc.current_operation_id()
    OR (to_jsonb(NEW)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')
      IS DISTINCT FROM (to_jsonb(OLD)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_scope_replacement() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_scope_successor(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_scope_successor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' OR current_user<>'openpc_control_owner'
  OR NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r
    JOIN control.platform_envelope_scope initial ON initial.platform_context_id=r.platform_context_id
    WHERE r.replacement_id=NEW.replacement_id AND r.state='COMMITTED' AND r.row_version=2
      AND r.commit_operation_id=openpc.current_operation_id()
      AND r.platform_context_id=NEW.platform_context_id AND NEW.platform_authority_epoch=r.predecessor_epoch+1
      AND NEW.preparation_operation_id=r.prepare_operation_id AND NEW.predecessor_epoch=r.predecessor_epoch
      AND NEW.predecessor_digest=r.predecessor_digest
      AND r.participant_id=NEW.owner_participant_id AND r.privacy_domain_id=NEW.installation_privacy_domain_id
      AND NEW.scope_cbor=r.successor_scope_cbor AND NEW.admission_preimage=r.successor_preimage
      AND NEW.admission_digest=r.successor_digest AND NEW.environment_id=initial.environment_id
      AND NEW.installation_digest=initial.installation_digest)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SUCCESSOR'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_scope_successor() OWNER TO openpc_control_owner;

--
-- Name: guard_platform_scope_target_withdrawal(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_platform_scope_target_withdrawal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' OR current_user<>'openpc_control_owner' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.replacement_id=NEW.replacement_id
  AND r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id AND r.state='WITHDRAWING'
  AND r.prepare_operation_id=openpc.current_operation_id() AND r.row_version=1
  AND r.candidate->'affectedTargets' @> jsonb_build_array(NEW.source))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_platform_scope_target_withdrawal() OWNER TO openpc_control_owner;

--
-- Name: guard_policy_generation_fence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_policy_generation_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE mode text; scope_key bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_NARGS=0 THEN mode:='BLOCKING';
 ELSIF TG_NARGS=1 AND TG_ARGV[0] IN ('TRY','TRY_CIGL_INSERT') THEN mode:=TG_ARGV[0];
 ELSE RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='PC-DATA-6004'; END IF;
 IF mode='TRY_CIGL_INSERT' THEN
  IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'runtime_configuration_generation'
  THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='PC-DATA-6004'; END IF;
  -- Its INSERT row guard takes the grant fence. Acquire it without waiting
  -- before policy, even for an empty INSERT or a caller already holding rows.
  IF TG_OP='INSERT' THEN PERFORM openpc.lock_cigl_grant_sources(true); END IF;
 END IF;
 scope_key:=hashtextextended('openpc-policy-generations:'||
  current_setting('openpc.participant_id')||':'||current_setting('openpc.privacy_domain_id'),0);
 IF mode='BLOCKING' THEN PERFORM pg_advisory_xact_lock(scope_key);
 ELSIF NOT pg_try_advisory_xact_lock(scope_key)
 THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_policy_generation_fence() OWNER TO openpc_control_owner;

--
-- Name: guard_policy_generation_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_policy_generation_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6007-POLICY-HISTORY-IMMUTABLE'; END IF;
 IF TG_OP='UPDATE' AND (NEW.participant_id IS DISTINCT FROM OLD.participant_id OR
   NEW.privacy_domain_id IS DISTINCT FROM OLD.privacy_domain_id OR NEW.policy_generation_id IS DISTINCT FROM OLD.policy_generation_id)
 THEN RAISE EXCEPTION 'DATA-6007-POLICY-HISTORY-IMMUTABLE'; END IF;
 IF TG_OP='INSERT' AND to_regclass('control.configuration_work') IS NOT NULL THEN
  IF EXISTS(SELECT 1 FROM control.configuration_work WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND policy_generation_digest IS NULL
    AND state IN ('PENDING','LEASED','RECONCILING'))
  THEN RAISE EXCEPTION 'DATA-6007-INITIAL-PREPARATION-INCOMPLETE'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_policy_generation_history() OWNER TO openpc_control_owner;

--
-- Name: guard_projection_deletion_job(text, control.deletion_job, control.deletion_job); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_projection_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) RETURNS control.deletion_job
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE plan jsonb; item control.evidence_projection_retirement;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF operation NOT IN ('INSERT','UPDATE') OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
  OR new_job.participant_id<>current_setting('openpc.participant_id')::uuid OR new_job.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR new_job.operation_id<>current_setting('openpc.operation_id')::uuid
  OR new_job.target_data_class NOT IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') OR new_job.target_database<>'openpc_control'
  OR new_job.selection->>'version'<>'OPENPC_PROJECTION_DELETION_BATCH_V1' OR new_job.selection->>'dataClass'<>new_job.target_data_class
  OR new_job.stream_id IS DISTINCT FROM new_job.selection->>'streamId' OR new_job.segment_id IS DISTINCT FROM (new_job.selection->>'segmentId')::uuid
  OR new_job.protected_object_id IS NOT NULL THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||new_job.participant_id::text,0));
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  IF new_job.previous_deletion_job_id IS NOT NULL THEN
   PERFORM 1 FROM control.deletion_job WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id
    AND deletion_job_id=new_job.previous_deletion_job_id FOR UPDATE;
  END IF;
  plan:=openpc.evidence_deletion_selection_plan(new_job.selection);
  IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM new_job.selection
   OR plan->>'beforeDigest' IS DISTINCT FROM new_job.before_digest OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.retention_policy_id IS DISTINCT FROM right(new_job.selection->>'retentionPolicyId',36)::uuid THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'domain','pc.evidence.projection-selector.v1','participantId',new_job.participant_id::text,'privacyDomainId',new_job.privacy_domain_id::text,
   'dataClass',new_job.target_data_class,'streamId',new_job.stream_id,'recordId',new_job.selection->>'recordId')),'UTF8')),'hex');
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(new_job.selection),'UTF8')),'hex');
  new_job.before_used_bytes:=(new_job.selection->>'projectionBytes')::integer; new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED' OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
    (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.evidence_projection_retirement WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.projection_bytes;new_job.after_used_bytes:=0;
  new_job.after_digest:=openpc.projection_deletion_after_digest(item);
  IF NOT coalesce(openpc.projection_deletion_effect_matches(new_job,item),false) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;


ALTER FUNCTION openpc.guard_projection_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) OWNER TO openpc_control_owner;

--
-- Name: guard_projection_retirement(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_projection_retirement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c control.evidence_catalogue; job control.deletion_job; plan jsonb; metadata jsonb;
BEGIN
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>2 THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT c FROM control.evidence_catalogue WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND stream_id=NEW.stream_id AND record_id=NEW.record_id;
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND deletion_job_id=NEW.deletion_job_id AND operation_id=current_setting('openpc.operation_id')::uuid AND state='EXECUTING';
 plan:=openpc.evidence_deletion_selection_plan(job.selection); metadata:=openpc.projection_preservation_metadata(c);
 IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM job.selection
  OR metadata IS NULL OR NEW.preservation_metadata IS DISTINCT FROM metadata OR NEW.evidence_id<>c.evidence_id OR NEW.segment_id<>c.segment_id
  OR NEW.sequence<>c.sequence OR NEW.source_receipt_digest<>c.receipt_digest OR NEW.data_class<>job.target_data_class
  OR NEW.projection_digest<>job.selection->>'projectionDigest' OR NEW.projection_bytes<>(job.selection->>'projectionBytes')::integer
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.retirement_digest:=openpc.projection_retirement_digest(NEW);RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_projection_retirement() OWNER TO openpc_control_owner;

--
-- Name: guard_protected_proof_access(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_protected_proof_access() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o control.protected_proof_object; expected jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO o FROM control.protected_proof_object WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 IF o.object_id IS NULL OR o.retain_until<=clock_timestamp() OR NEW.expires_at>o.retain_until
  OR NEW.object_binding IS DISTINCT FROM openpc.protected_proof_binding(o)
  OR NEW.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='INSERT' THEN
  IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOF_ACCESS_CREATE_RESOURCE-V1'
   OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid OR NEW.revision<>1
   OR NEW.consumed_at IS NOT NULL OR NEW.consumption_operation_id IS NOT NULL OR NEW.consumption_request IS NOT NULL
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE
  IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1'
   OR OLD.revision<>1 OR NEW.revision<>2 OR NEW.consumption_operation_id<>current_setting('openpc.operation_id')::uuid
   OR (to_jsonb(NEW)-ARRAY['revision','consumption_operation_id','consumed_at','updated_at','consumption_request']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['revision','consumption_operation_id','consumed_at','updated_at','consumption_request'])
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  expected:=jsonb_build_object('targetRef','urn:openpc:resource:'||NEW.access_id::text,'expectedRevision','1',
   'object',NEW.object_binding,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'recipientPrincipalId',NEW.recipient_principal_id::text,'expiresAt',to_char(NEW.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  IF NEW.consumption_request-ARRAY['reason','actionIntentId','actionIntentDigest'] IS DISTINCT FROM expected
   OR NEW.consumption_request->>'actionIntentId'<>'ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1'
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.consumed_at:=clock_timestamp(); NEW.updated_at:=NEW.consumed_at;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_protected_proof_access() OWNER TO openpc_control_owner;

--
-- Name: guard_protected_proof_checkpoint(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_protected_proof_checkpoint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE object control.protected_proof_object; payload control.protected_proof_payload; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT object FROM control.protected_proof_object
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 SELECT * INTO STRICT payload FROM control.protected_proof_payload
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 IF NEW.payload_digest IS DISTINCT FROM openpc.protected_proof_payload_digest(payload)
  OR NEW.ciphertext_bytes<>octet_length(payload.ciphertext) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NEW.receipt->>'kind'='SIGNED_REMOTE_PROTECTED_ARCHIVE_V1' THEN
  PERFORM openpc.assert_protected_remote_checkpoint(NEW);
 ELSE
 expected:=jsonb_build_object('object',openpc.protected_proof_binding(object)||jsonb_build_object(
  'dataClass','RAW_SOURCE_BODY','participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
  'sinkId',NEW.sink_id,'payloadDigest',NEW.payload_digest,'ciphertextBytes',NEW.ciphertext_bytes,
  'retainUntil',to_char(object.retain_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'versionId',NEW.payload_digest,'assurance','LOCAL_FSYNC_READBACK');
 IF NEW.receipt-'receiptDigest' IS DISTINCT FROM expected OR NEW.receipt->>'receiptDigest' IS DISTINCT FROM NEW.receipt_digest
  OR NEW.receipt_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 expected:=jsonb_build_object('domain','pc.evidence.protected-checkpoint.v1','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'objectRef','urn:openpc:resource:'||NEW.object_id::text,
  'objectVersion',object.object_version::text,'sinkId',NEW.sink_id,'payloadDigest',NEW.payload_digest,'receiptDigest',NEW.receipt_digest);
 IF NEW.checkpoint_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.acknowledged_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_protected_proof_checkpoint() OWNER TO openpc_control_owner;

--
-- Name: guard_protected_proof_object(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_protected_proof_object() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a record; e record; expected jsonb; payload jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT occurrence.* INTO a FROM control.evidence_catalogue c JOIN control.authentication_occurrence occurrence
  ON occurrence.participant_id=c.participant_id AND occurrence.privacy_domain_id=c.privacy_domain_id
   AND occurrence.occurrence_id::text=c.record_id AND c.evidence_class='AUTHENTICATION'
   AND c.receipt_digest='sha256:'||encode(occurrence.receipt_digest,'hex')
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND 'urn:openpc:resource:'||c.evidence_id::text=NEW.source->>'evidenceId' AND occurrence.method='WEBAUTHN_ASSERTION';
 SELECT proof.* INTO e FROM control.mutation_evidence proof JOIN control.idempotency_record i
  ON i.participant_id=proof.participant_id AND i.privacy_domain_id=proof.privacy_domain_id
   AND i.operation_id=proof.operation_id AND i.terminal_state='COMMITTED' AND i.input_digest=proof.candidate_digest
  WHERE proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id
   AND proof.operation_id=a.operation_id AND proof.principal_id=a.principal_id AND proof.aggregate_id=a.session_id
   AND proof.mfa_challenge_id=a.source_id AND proof.signer_credential_id=a.credential_id
   AND proof.webauthn_assertion_binding_digest=a.proof_digest AND proof.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY';
 IF a.occurrence_id IS NULL OR e.operation_id IS NULL OR e.evidence_digest<>sha256(e.evidence_cbor)
  OR coalesce(NEW.source->>'signerKeyDigest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('evidenceId',NEW.source->>'evidenceId','occurrenceId',a.occurrence_id::text,
  'operationId',a.operation_id::text,'sourceReceiptDigest','sha256:'||encode(a.receipt_digest,'hex'),
  'proofDigest','sha256:'||encode(a.proof_digest,'hex'),'assertionDigest','sha256:'||encode(e.evidence_digest,'hex'),
  'signatureDigest','sha256:'||encode(sha256(e.cose_sign1),'hex'),'signerKeyDigest',NEW.source->>'signerKeyDigest',
  'occurredAt',to_char(a.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'materialType','IDENTITY_SIGNED_AUTHORIZATION_ASSERTION','evidenceClass','AUTHENTICATION',
  'sourceFormat','IDENTITY_RUNTIME_ASSERTION_3002_2_13','occurrenceIntegrity','CONTROL_DATABASE_IMMUTABLE',
  'proofIntegrity','IDENTITY_COSE_ED25519','finality','NOT_APPLICABLE','authorityEffect','NONE');
 payload:=jsonb_build_object('version','OPENPC_PROTECTED_IDENTITY_PROOF_V1','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'source',expected,
  'assertionBase64',replace(encode(e.evidence_cbor,'base64'),chr(10),''),'coseSign1Base64',replace(encode(e.cose_sign1,'base64'),chr(10),''));
 IF NEW.source IS DISTINCT FROM expected OR NEW.object_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(payload),'UTF8')),'hex')
  OR NEW.object_version<>1 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_protected_proof_object() OWNER TO openpc_control_owner;

--
-- Name: guard_protected_proof_payload(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_protected_proof_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE used bigint;
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM openpc.record_raw_proof_payload_deletion(OLD);
  RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT EXISTS(SELECT 1 FROM control.protected_proof_object o WHERE o.object_id=NEW.object_id
  AND o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id
  AND o.creation_operation_id=current_setting('openpc.operation_id')::uuid)
  OR current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('protected-proof-capacity:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 SELECT coalesce(sum(octet_length(ciphertext)),0) INTO used FROM control.protected_proof_payload
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id;
 IF used+octet_length(NEW.ciphertext)>16777216 THEN RAISE EXCEPTION 'PC-OPS-9002'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_protected_proof_payload() OWNER TO openpc_control_owner;

--
-- Name: guard_provider_probe_observation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_provider_probe_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='DELETE' OR OLD.state<>'RUNNING' OR
    ROW(NEW.observation_id,NEW.participant_id,NEW.privacy_domain_id,NEW.provider_profile_id,
        NEW.source_revision,NEW.input_digest,NEW.configuration_digest,NEW.created_at)
    IS DISTINCT FROM
    ROW(OLD.observation_id,OLD.participant_id,OLD.privacy_domain_id,OLD.provider_profile_id,
        OLD.source_revision,OLD.input_digest,OLD.configuration_digest,OLD.created_at) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='DATA-6020-IMMUTABLE-ROW';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_provider_probe_observation() OWNER TO openpc_control_owner;

--
-- Name: guard_provider_retry_qualification(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_provider_retry_qualification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE root control.operations_qualification_root%ROWTYPE; prior control.operations_qualification_state%ROWTYPE;
 current_state control.operations_qualification_state%ROWTYPE; issuance control.operations_qualification_state%ROWTYPE;
 g control.operations_generation%ROWTYPE; installed control.operations_installation%ROWTYPE;
 k jsonb; r jsonb; kd jsonb; rd jsonb; old_kd jsonb; old_rd jsonb; i jsonb; receipt jsonb; doc jsonb; evidence jsonb; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR openpc.current_action_intent_id()<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('operations-generation:'||NEW.environment_id,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('operations-qualification:'||NEW.environment_id||':'||NEW.authority_id,0));
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF TG_TABLE_NAME='operations_qualification_root' THEN
  IF NOT pg_has_role(current_user,'openpc_operations_qualification_bootstrap','USAGE') OR pg_has_role(current_user,'openpc_operations_qualification_owner','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  IF TG_OP='UPDATE' THEN
   IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state' THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_IMMUTABLE'; END IF;
   RETURN NEW;
  END IF;
  IF EXISTS(SELECT 1 FROM control.operations_qualification_state history CROSS JOIN LATERAL jsonb_array_elements((convert_from(decode(history.custody->'keyset'->>'documentHex','hex'),'UTF8')::jsonb)->'keys') key WHERE history.environment_id=NEW.environment_id AND history.authority_id=NEW.authority_id AND key->>'keyId'=NEW.root_key_id)
   OR NEW.state<>'ACTIVE' OR NEW.valid_from_ms>now_ms OR NEW.valid_until_ms<=now_ms
   OR NEW.root_epoch<=coalesce((SELECT max(root_epoch) FROM control.operations_qualification_root WHERE environment_id=NEW.environment_id AND authority_id=NEW.authority_id),0)
   OR encode(NEW.root_spki,'hex') !~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
  THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
  PERFORM 1 FROM control.operations_installation WHERE environment_id=NEW.environment_id AND state='ACTIVE' AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_operations_qualification_owner','USAGE') OR pg_has_role(current_user,'openpc_operations_qualification_bootstrap','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF octet_length(NEW.custody_bytes) NOT BETWEEN 1 AND (CASE WHEN TG_TABLE_NAME='operations_qualification_state' THEN 10000000 ELSE 1500000 END)
 OR NEW.custody_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.custody_bytes),'hex')
 OR NEW.custody IS DISTINCT FROM convert_from(NEW.custody_bytes,'UTF8')::jsonb OR NEW.custody_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.custody),'UTF8') THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
 SELECT * INTO root FROM control.operations_qualification_root WHERE environment_id=NEW.environment_id AND authority_id=NEW.authority_id ORDER BY root_epoch DESC LIMIT 1 FOR SHARE;
 IF root.authority_id IS NULL OR root.state<>'ACTIVE' OR root.participant_id<>NEW.participant_id OR root.privacy_domain_id<>NEW.privacy_domain_id OR root.valid_from_ms>now_ms OR root.valid_until_ms<=now_ms THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_ROOT_UNBOUND'; END IF;
 IF TG_TABLE_NAME='operations_qualification_state' THEN
  k:=openpc.provider_retry_claims('keyset',decode(NEW.custody->'keyset'->>'payloadHex','hex'),decode(NEW.custody->'keyset'->>'coseHex','hex'),root.root_key_id);
  r:=openpc.provider_retry_claims('revocations',decode(NEW.custody->'revocations'->>'payloadHex','hex'),decode(NEW.custody->'revocations'->>'coseHex','hex'),root.root_key_id);
  kd:=convert_from(decode(NEW.custody->'keyset'->>'documentHex','hex'),'UTF8')::jsonb;
  rd:=convert_from(decode(NEW.custody->'revocations'->>'documentHex','hex'),'UTF8')::jsonb;
  IF (SELECT count(*) FROM jsonb_object_keys(NEW.custody))<>2 OR NOT NEW.custody ?& ARRAY['keyset','revocations']
   OR (SELECT count(*) FROM jsonb_object_keys(kd))<>6 OR NOT kd ?& ARRAY['schemaVersion','authorityId','policySigner','keys','issuedAt','signatureEnvelope']
   OR (SELECT count(*) FROM jsonb_object_keys(rd))<>3 OR NOT rd ?& ARRAY['schemaVersion','authorityId','revocations']
   OR kd->>'schemaVersion'<>'1.0' OR rd->>'schemaVersion'<>'1.0' OR kd->>'policySigner'<>root.policy_signer
   OR jsonb_typeof(kd->'keys')<>'array' OR jsonb_array_length(kd->'keys') NOT BETWEEN 1 AND 64
   OR jsonb_typeof(rd->'revocations')<>'array' OR jsonb_array_length(rd->'revocations')>4096
   OR (k->>'issuedAtMs')::numeric<root.valid_from_ms OR (r->>'issuedAtMs')::numeric<root.valid_from_ms
   OR (k->>'validUntilMs')::numeric>root.valid_until_ms OR (r->>'validUntilMs')::numeric>root.valid_until_ms
   OR NEW.root_epoch<>root.root_epoch OR k->>'rootEpoch'<>root.root_epoch::text OR r->>'rootEpoch'<>root.root_epoch::text
   OR k->>'authorityId'<>NEW.authority_id OR r->>'authorityId'<>NEW.authority_id
   OR k->>'rootKeyId'<>root.root_key_id OR r->>'rootKeyId'<>root.root_key_id OR k->>'policySigner'<>root.policy_signer
   OR NEW.sequence::text<>k->>'sequence' OR NEW.snapshot_sequence::text<>r->>'sequence'
   OR NEW.keyset_digest IS DISTINCT FROM 'sha256:'||encode(sha256(decode(NEW.custody->'keyset'->>'payloadHex','hex')),'hex')
   OR NEW.revocations_digest IS DISTINCT FROM 'sha256:'||encode(sha256(decode(NEW.custody->'revocations'->>'payloadHex','hex')),'hex')
   OR k->>'revocationPayloadDigest'<>NEW.revocations_digest
   OR k->>'keysetDocumentDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(kd),'UTF8')),'hex')
   OR r->>'revocationDocumentDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(rd),'UTF8')),'hex')
   OR (k->>'issuedAtMs')::numeric>now_ms OR (r->>'issuedAtMs')::numeric>now_ms
   OR NEW.valid_until_ms IS DISTINCT FROM least((k->>'validUntilMs')::numeric,(r->>'validUntilMs')::numeric,root.valid_until_ms)
   OR NEW.valid_until_ms<=now_ms OR kd->>'authorityId'<>NEW.authority_id OR rd->>'authorityId'<>NEW.authority_id
  THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(kd->'keys') key WHERE
    (SELECT count(*) FROM jsonb_object_keys(key))<>9 OR NOT key ?& ARRAY['keyId','epoch','state','purpose','nonExportable','backend','publicKeySpkiHex','validFromMs','validUntilMs']
    OR EXISTS(SELECT 1 FROM control.operations_qualification_root installed_root WHERE installed_root.environment_id=NEW.environment_id AND installed_root.authority_id=NEW.authority_id AND installed_root.root_key_id=key->>'keyId') OR key->>'keyId' IS DISTINCT FROM 'sha256:'||encode(sha256(decode(key->>'publicKeySpkiHex','hex')),'hex')
    OR key->>'publicKeySpkiHex' !~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
    OR key->'nonExportable' IS DISTINCT FROM 'true'::jsonb OR key->>'backend' NOT IN ('KMS','HSM')
    OR key->>'state' NOT IN ('DRAFT','ACTIVE','SUSPENDED','RETIRED','REVOKED')
    OR key->>'purpose' NOT IN ('pc.cose.operations-qualification-input.v1','pc.cose.operations-qualification-executed-receipt.v1','pc.cose.operations-notification-async-input.v1','pc.cose.operations-notification-async-capacity-receipt.v1')
    OR key->>'epoch' !~ '^[1-9][0-9]*$' OR (key->>'epoch')::numeric>9007199254740991
    OR (key->>'validFromMs')::numeric<0 OR (key->>'validUntilMs')::numeric<=(key->>'validFromMs')::numeric OR (key->>'validUntilMs')::numeric>9007199254740991)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(kd->'keys') a JOIN jsonb_array_elements(kd->'keys') b ON a->>'keyId'=b->>'keyId' WHERE a->>'purpose'<>b->>'purpose')
   OR (SELECT count(*) FROM jsonb_array_elements(kd->'keys'))<>(SELECT count(DISTINCT (key->>'keyId',key->>'epoch')) FROM jsonb_array_elements(kd->'keys') key)
   THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
  SELECT * INTO prior FROM control.operations_qualification_state WHERE environment_id=NEW.environment_id AND authority_id=NEW.authority_id ORDER BY sequence DESC LIMIT 1;
  IF prior.authority_id IS NOT NULL THEN
   old_kd:=convert_from(decode(prior.custody->'keyset'->>'documentHex','hex'),'UTF8')::jsonb;
   old_rd:=convert_from(decode(prior.custody->'revocations'->>'documentHex','hex'),'UTF8')::jsonb;
   IF NEW.sequence<=prior.sequence OR NEW.snapshot_sequence<=prior.snapshot_sequence OR NEW.root_epoch<prior.root_epoch
    OR (k->>'issuedAtMs')::numeric<(openpc.business_cbor(decode(prior.custody->'keyset'->>'payloadHex','hex'))->>'9')::numeric
    OR (r->>'issuedAtMs')::numeric<(openpc.business_cbor(decode(prior.custody->'revocations'->>'payloadHex','hex'))->>'7')::numeric
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(old_kd->'keys') AS retained_key(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(kd->'keys') AS next_key(value) WHERE retained_key.value->>'keyId'=next_key.value->>'keyId' AND retained_key.value->'epoch'=next_key.value->'epoch' AND retained_key.value-'state'=next_key.value-'state' AND (retained_key.value->>'state'<>'REVOKED' OR next_key.value->>'state'='REVOKED') AND (retained_key.value->>'state'<>'RETIRED' OR next_key.value->>'state' IN ('RETIRED','REVOKED'))))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(old_rd->'revocations') AS retained_revocation(value) WHERE NOT (rd->'revocations') @> jsonb_build_array(retained_revocation.value))
   THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_STATE_ROLLBACK'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO current_state FROM control.operations_qualification_state WHERE environment_id=NEW.environment_id AND authority_id=NEW.authority_id ORDER BY sequence DESC LIMIT 1;
 SELECT * INTO issuance FROM control.operations_qualification_state WHERE environment_id=NEW.environment_id AND authority_id=NEW.authority_id AND sequence=NEW.issuance_sequence;
 IF issuance.authority_id IS NULL OR current_state.authority_id IS NULL OR current_state.root_epoch<>root.root_epoch OR current_state.valid_until_ms<=now_ms THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
 -- The dedicated writer verifies both signatures and documents before INSERT.
 -- Derive issuer identities from actual payloads; never accept a replacement JWK.
 i:=openpc.business_cbor(decode(NEW.custody->'input'->>'payloadHex','hex'));
 i:=openpc.provider_retry_claims('input',decode(NEW.custody->'input'->>'payloadHex','hex'),decode(NEW.custody->'input'->>'coseHex','hex'),'sha256:'||(i->'18'->>'bytes'));
 receipt:=openpc.business_cbor(decode(NEW.custody->'receipt'->>'payloadHex','hex'));
 receipt:=openpc.provider_retry_claims('receipt',decode(NEW.custody->'receipt'->>'payloadHex','hex'),decode(NEW.custody->'receipt'->>'coseHex','hex'),'sha256:'||(receipt->'11'->>'bytes'));
 doc:=convert_from(decode(NEW.custody->'receipt'->>'documentHex','hex'),'UTF8')::jsonb;
 SELECT * INTO g FROM control.operations_generation WHERE environment_id=NEW.environment_id AND generation_id=NEW.generation_id FOR SHARE;
 SELECT * INTO installed FROM control.operations_installation WHERE environment_id=NEW.environment_id FOR SHARE;
 IF (SELECT count(*) FROM jsonb_object_keys(NEW.custody))<>2 OR NOT NEW.custody ?& ARRAY['input','receipt']
  OR g.state IS DISTINCT FROM 'STAGED' OR installed.state IS DISTINCT FROM 'ACTIVE' OR NOT openpc.operations_generation_source_authenticated(NEW.environment_id,NEW.generation_id)
  OR i->>'authorityId'<>NEW.authority_id OR i->>'environmentId'<>NEW.environment_id OR receipt->>'environmentId'<>NEW.environment_id OR receipt->>'authorityId'<>NEW.authority_id
  OR i->>'profile' IS DISTINCT FROM g.candidate->'configuration'->>'profile' OR i->>'profile' IS DISTINCT FROM receipt->>'profile'
  OR i->>'slot' IS DISTINCT FROM installed.installation->'namedProfile'->'requiredSettingInputs'->>'provider.read_retry_limit'
  OR i->>'setting' IS DISTINCT FROM 'provider.read_retry_limit' OR i->>'methodClass' IS DISTINCT FROM 'RETRY_SAFE_READ'
  OR (i->>'value')::integer NOT BETWEEN 0 AND 3 OR i->'value' IS DISTINCT FROM g.candidate->'configuration'->'settings'->'provider.read_retry_limit'
  OR i->>'configurationSchemaDigest' IS DISTINCT FROM installed.installation->'pins'->>'configurationSchemaDigest'
  OR i->>'namedProfileDigest' IS DISTINCT FROM installed.installation->'pins'->>'namedProfileDigest'
  OR NEW.input_digest IS DISTINCT FROM 'sha256:'||encode(sha256(decode(NEW.custody->'input'->>'payloadHex','hex')),'hex')
  OR NEW.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(decode(NEW.custody->'receipt'->>'payloadHex','hex')),'hex')
  OR receipt->>'inputPayloadDigest'<>NEW.input_digest OR receipt->>'qualificationRef' IS DISTINCT FROM 'qualification://'||NEW.authority_id||'/'||(i->>'inputId')||'@'||NEW.input_digest
  OR receipt->>'qualificationRef' IS DISTINCT FROM g.candidate->'configuration'->'qualificationInputBindings'->>'provider.read_retry_limit'
  OR receipt->>'keysetPayloadDigest'<>issuance.keyset_digest OR receipt->>'revocationPayloadDigest'<>issuance.revocations_digest
  OR receipt->>'receiptDocumentDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(doc),'UTF8')),'hex')
  OR (i->>'validFromMs')::numeric>now_ms OR (receipt->>'issuedAtMs')::numeric>now_ms OR (i->>'validUntilMs')::numeric<=now_ms
  OR NEW.valid_until_ms IS DISTINCT FROM (receipt->>'expiresAtMs')::numeric OR NEW.valid_until_ms<=now_ms
 THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
 evidence:=openpc.require_provider_retry_evidence(NEW.environment_id,NEW.generation_id,NEW.input_digest,receipt->>'receiptDocumentDigest');
 IF evidence->'input' IS DISTINCT FROM i OR evidence->'receiptDocument' IS DISTINCT FROM doc THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_provider_retry_qualification() OWNER TO openpc_control_owner;

--
-- Name: guard_qualification_deployment_observation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_qualification_deployment_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control', 'openpc'
    AS $$
DECLARE pins control.qualification_deployment_installation%ROWTYPE;
 attempt control.qualification_deployment_attempt%ROWTYPE;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_IMMUTABLE'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR openpc.current_action_intent_id()<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_CONTEXT'; END IF;
 IF TG_TABLE_NAME='qualification_deployment_installation' THEN
  IF current_user<>'openpc_operations_qualification_bootstrap' THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_INSTALLER'; END IF;
  IF TG_OP='UPDATE' THEN
   IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') OR NEW.state<>'REVOKED' THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_IMMUTABLE'; END IF;
  ELSE
   IF NEW.state<>'ACTIVE' OR NEW.pins->'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(NEW.pins))<>25
    OR NOT NEW.pins ?& ARRAY['schemaVersion','installationId','participantId','privacyDomainId','environmentId','operationsInstallationDigest','peer','daemonId','engineEndpoint','containerId','imageId','containerStartedAt','installedProcess','expectedUid','executable','argv','networkId','address','memoryBytes','nanoCpus','pidsLimit','mounts','tmpfsTargets','artifacts','separatedFrom']
    OR convert_from(NEW.pins_bytes,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(NEW.pins)
    OR NEW.pins->>'installationId' IS DISTINCT FROM NEW.installation_id::text
    OR NEW.pins->>'participantId' IS DISTINCT FROM NEW.participant_id::text
    OR NEW.pins->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
    OR NEW.pins->>'environmentId' IS DISTINCT FROM NEW.environment_id
    OR NEW.pins->>'engineEndpoint' IS DISTINCT FROM 'unix:///var/run/docker.sock'
    OR NOT EXISTS(SELECT 1 FROM control.operations_installation i WHERE i.environment_id=NEW.environment_id AND i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id AND i.state='ACTIVE' AND i.installation_digest=NEW.pins->>'operationsInstallationDigest')
   THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_PINS'; END IF;
  END IF;
 ELSE
  IF TG_OP<>'INSERT' OR current_user NOT IN ('openpc_control_owner','openpc_operations_qualification_owner') THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_NATIVE_OWNER'; END IF;
  IF TG_TABLE_NAME='qualification_deployment_attempt' THEN
   SELECT * INTO pins FROM control.qualification_deployment_installation WHERE installation_id=NEW.installation_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR SHARE;
   IF NOT FOUND OR pins.state<>'ACTIVE' OR NEW.request->'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(NEW.request))<>8
    OR NOT NEW.request ?& ARRAY['schemaVersion','observationId','operationId','installationDigest','pins','separatedPins','issuedAtMs','deadlineAtMs']
    OR NEW.request->'pins' IS DISTINCT FROM pins.pins OR NEW.request->>'installationDigest' IS DISTINCT FROM pins.pins_digest
    OR NEW.request->>'observationId' IS DISTINCT FROM NEW.observation_id::text OR NEW.request->>'operationId' IS DISTINCT FROM NEW.operation_id::text
    OR convert_from(NEW.request_bytes,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(NEW.request)
    OR jsonb_typeof(NEW.request->'issuedAtMs') IS DISTINCT FROM 'number' OR jsonb_typeof(NEW.request->'deadlineAtMs') IS DISTINCT FROM 'number'
    OR (NEW.request->>'issuedAtMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)
    OR (NEW.request->>'deadlineAtMs')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
    OR (NEW.request->>'deadlineAtMs')::numeric-(NEW.request->>'issuedAtMs')::numeric NOT BETWEEN 1 AND 30000
    OR NOT EXISTS(SELECT 1 FROM control.operations_installation i WHERE i.environment_id=pins.environment_id AND i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id AND i.state='ACTIVE' AND i.installation_digest=pins.pins->>'operationsInstallationDigest')
   THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_REQUEST'; END IF;
   IF jsonb_typeof(NEW.request->'separatedPins') IS DISTINCT FROM 'array'
    OR jsonb_array_length(NEW.request->'separatedPins')>8
    OR (SELECT coalesce(jsonb_agg(v->>'installationId' ORDER BY v->>'installationId'),'[]'::jsonb) FROM jsonb_array_elements(NEW.request->'separatedPins') v)
       IS DISTINCT FROM (SELECT coalesce(jsonb_agg(v ORDER BY v),'[]'::jsonb) FROM jsonb_array_elements(pins.pins->'separatedFrom') v)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.request->'separatedPins') p WHERE NOT EXISTS(
     SELECT 1 FROM control.qualification_deployment_installation i WHERE i.installation_id=(p->>'installationId')::uuid AND i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id AND i.environment_id=pins.environment_id AND i.state='ACTIVE' AND i.pins=p))
   THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_SEPARATION'; END IF;
  ELSE
   SELECT * INTO attempt FROM control.qualification_deployment_attempt WHERE observation_id=NEW.observation_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR SHARE;
   IF NOT FOUND OR NEW.observation->'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(NEW.observation))<>7
    OR NOT NEW.observation ?& ARRAY['schemaVersion','observationId','requestDigest','state','measurement','identityRecheckedAtMs','retainedAtMs']
    OR NEW.observation->>'observationId' IS DISTINCT FROM NEW.observation_id::text OR NEW.observation->>'requestDigest' IS DISTINCT FROM attempt.request_digest
    OR NEW.observation->>'state' IS NULL OR NEW.observation->>'state' NOT IN ('OBSERVED','HISTORICAL','UNKNOWN')
    OR convert_from(NEW.observation_bytes,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(NEW.observation)
    OR jsonb_typeof(NEW.observation->'retainedAtMs') IS DISTINCT FROM 'number'
    OR (NEW.observation->>'retainedAtMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)
   THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_RESULT'; END IF;
   IF NEW.observation->>'state'='UNKNOWN' THEN
    IF NEW.observation->'measurement' IS DISTINCT FROM 'null'::jsonb OR NEW.observation->'identityRecheckedAtMs' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_UNKNOWN'; END IF;
   ELSE
    IF jsonb_typeof(NEW.observation->'measurement') IS DISTINCT FROM 'object'
     OR NEW.observation->'measurement'->'schemaVersion' IS DISTINCT FROM '1'::jsonb
     OR NEW.observation->'measurement'->>'scope' IS DISTINCT FROM 'CONTAINER_WORKLOAD'
     OR (SELECT count(*) FROM jsonb_object_keys(NEW.observation->'measurement'))<>15
     OR jsonb_typeof(NEW.observation->'measurement'->'startedAtMs') IS DISTINCT FROM 'number'
     OR jsonb_typeof(NEW.observation->'measurement'->'completedAtMs') IS DISTINCT FROM 'number'
     OR (NEW.observation->'measurement'->>'startedAtMs')::numeric<(attempt.request->>'issuedAtMs')::numeric
     OR (NEW.observation->'measurement'->>'completedAtMs')::numeric<(NEW.observation->'measurement'->>'startedAtMs')::numeric
     OR (NEW.observation->'measurement'->>'completedAtMs')::numeric>=(attempt.request->>'deadlineAtMs')::numeric
     OR (NEW.observation->'measurement'->>'completedAtMs')::numeric>(NEW.observation->>'retainedAtMs')::numeric
     OR NEW.observation->'measurement'->>'installationDigest' IS DISTINCT FROM attempt.request->>'installationDigest'
     OR NEW.observation->'measurement'->>'observationId' IS DISTINCT FROM NEW.observation_id::text
     OR NEW.observation->'measurement'->>'requestDigest' IS DISTINCT FROM attempt.request_digest
     OR EXISTS(SELECT 1 FROM unnest(ARRAY['sourceBuildLink','changeAuthorship','exactSocketProcess','qualification']) k WHERE NEW.observation->'measurement'->>k IS DISTINCT FROM 'UNESTABLISHED')
    THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_CLAIM'; END IF;
    IF NEW.observation->>'state'='OBSERVED' THEN
     IF jsonb_typeof(NEW.observation->'identityRecheckedAtMs') IS DISTINCT FROM 'number'
      OR (NEW.observation->>'identityRecheckedAtMs')::numeric<(NEW.observation->'measurement'->>'completedAtMs')::numeric
      OR (NEW.observation->>'identityRecheckedAtMs')::numeric>(NEW.observation->>'retainedAtMs')::numeric
     THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_RECHECK'; END IF;
    ELSIF NEW.observation->'identityRecheckedAtMs' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'QUALIFICATION_DEPLOYMENT_HISTORY'; END IF;
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_qualification_deployment_observation() OWNER TO openpc_control_owner;

--
-- Name: guard_qualification_key_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_qualification_key_custody() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control', 'openpc'
    AS $$
DECLARE pins control.qualification_key_installation%ROWTYPE;
 attempt control.qualification_key_attempt%ROWTYPE;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'QUALIFICATION_KEY_IMMUTABLE'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR openpc.current_action_intent_id()<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'QUALIFICATION_KEY_CONTEXT'; END IF;
 IF TG_TABLE_NAME='qualification_key_installation' THEN
  IF current_user<>'openpc_operations_qualification_bootstrap' THEN RAISE EXCEPTION 'QUALIFICATION_KEY_INSTALLER'; END IF;
  IF TG_OP='UPDATE' THEN
   IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state')
     OR OLD.state NOT IN ('ACTIVE','REVOKED') OR NEW.state<>'REVOKED' THEN RAISE EXCEPTION 'QUALIFICATION_KEY_IMMUTABLE'; END IF;
  ELSE
   IF NEW.state<>'ACTIVE' OR NEW.pins->'schemaVersion' IS DISTINCT FROM '1'::jsonb
     OR NOT NEW.pins ?& ARRAY['schemaVersion','installationId','participantId','privacyDomainId','environmentId','authorityId','rootEpoch','keyId','keyEpoch','purpose','publicKeySpkiHex','reference','version','providerId','providerOrigin','providerTlsSpkiDigest','peer','validFromMs','validUntilMs'] OR convert_from(NEW.pins_bytes,'UTF8')<>openpc.signing_canonical_json(NEW.pins)
     OR NEW.pins->>'installationId' IS DISTINCT FROM NEW.installation_id::text OR NEW.pins->>'participantId' IS DISTINCT FROM NEW.participant_id::text
     OR NEW.pins->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR NEW.pins->>'environmentId' IS DISTINCT FROM NEW.environment_id
     OR NOT EXISTS(SELECT 1 FROM control.operations_installation i WHERE i.environment_id=NEW.environment_id AND i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id AND i.state='ACTIVE')
   THEN RAISE EXCEPTION 'QUALIFICATION_KEY_INSTALLATION'; END IF;
  END IF;
 ELSE
  IF current_user NOT IN ('openpc_control_owner','openpc_operations_qualification_owner') THEN RAISE EXCEPTION 'QUALIFICATION_KEY_NATIVE_OWNER'; END IF;
  IF TG_TABLE_NAME='qualification_key_attempt' THEN
   SELECT * INTO pins FROM control.qualification_key_installation WHERE installation_id=NEW.installation_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR SHARE;
   IF NOT FOUND OR pins.state<>'ACTIVE' THEN RAISE EXCEPTION 'QUALIFICATION_KEY_UNINSTALLED'; END IF;
   IF TG_OP='UPDATE' THEN
    IF (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') OR OLD.state<>'PREPARED' OR NEW.state<>'DISPATCHED' THEN RAISE EXCEPTION 'QUALIFICATION_KEY_IMMUTABLE'; END IF;
   ELSE
    IF NEW.state<>'PREPARED' OR NEW.request->'schemaVersion' IS DISTINCT FROM '1'::jsonb
     OR NOT NEW.request ?& ARRAY['schemaVersion','installationDigest','participantId','privacyDomainId','environmentId','authorityId','rootEpoch','keysetDigest','revocationsDigest','keyId','keyEpoch','purpose','providerId','reference','version','peer','operationId','attemptId','issuedAtMs','deadlineAtMs','method'] OR convert_from(NEW.request_bytes,'UTF8')<>openpc.signing_canonical_json(NEW.request)
     OR NEW.request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR NEW.request->>'operationId' IS DISTINCT FROM NEW.operation_id::text
     OR NEW.request->>'installationDigest' IS DISTINCT FROM pins.pins_digest OR NEW.request->'peer' IS DISTINCT FROM pins.pins->'peer'
     OR NEW.request->>'method' NOT IN ('INSPECT','PROVE')
     OR (NEW.request->>'issuedAtMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)
     OR (NEW.request->>'deadlineAtMs')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
     OR EXISTS(SELECT 1 FROM unnest(ARRAY['participantId','privacyDomainId','environmentId','authorityId','rootEpoch','keyId','keyEpoch','purpose','providerId','reference','version']) k WHERE NEW.request->k IS DISTINCT FROM pins.pins->k)
    THEN RAISE EXCEPTION 'QUALIFICATION_KEY_REQUEST'; END IF;
   END IF;
  ELSE
   IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'QUALIFICATION_KEY_IMMUTABLE'; END IF;
   SELECT * INTO attempt FROM control.qualification_key_attempt WHERE attempt_id=NEW.attempt_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id FOR SHARE;
   IF NOT FOUND OR attempt.state<>'DISPATCHED' OR NEW.observation->'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR NOT NEW.observation ?& ARRAY['schemaVersion','attemptId','requestDigest','observedAtMs','outcome','reason','descriptor','proofHex'] OR convert_from(NEW.observation_bytes,'UTF8')<>openpc.signing_canonical_json(NEW.observation)
    OR NEW.observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR NEW.observation->>'requestDigest' IS DISTINCT FROM attempt.request_digest
    OR NEW.observation->>'outcome' NOT IN ('OBSERVED','REJECTED')
   THEN RAISE EXCEPTION 'QUALIFICATION_KEY_OBSERVATION'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_qualification_key_custody() OWNER TO openpc_control_owner;

--
-- Name: guard_qualified_checkpoint(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_qualified_checkpoint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-CHECKPOINT'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.last_sequence<>0 THEN RAISE EXCEPTION 'DATA-6021-CHECKPOINT-INITIAL'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['last_sequence','last_receipt_id']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['last_sequence','last_receipt_id']) OR NEW.last_sequence<>OLD.last_sequence+1 OR NOT EXISTS(
  SELECT 1 FROM control.qualified_receipt_inbox i WHERE i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id
   AND i.namespace=NEW.namespace AND i.aggregate_type=NEW.aggregate_type AND i.aggregate_id=NEW.aggregate_id
   AND i.sequence=NEW.last_sequence AND i.receipt_id=NEW.last_receipt_id) THEN RAISE EXCEPTION 'DATA-6021-CHECKPOINT-ACCEPTANCE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_qualified_checkpoint() OWNER TO openpc_control_owner;

--
-- Name: guard_raw_proof_deletion_job(text, control.deletion_job, control.deletion_job); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_raw_proof_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) RETURNS control.deletion_job
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE plan jsonb; item control.evidence_deletion_item; current_bytes integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF operation NOT IN ('INSERT','UPDATE') OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_RAW_BATCH-V1'
  OR new_job.participant_id<>current_setting('openpc.participant_id')::uuid
  OR new_job.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR new_job.operation_id<>current_setting('openpc.operation_id')::uuid
  OR new_job.target_data_class<>'RAW_SOURCE_BODY' OR new_job.target_database<>'openpc_control'
  OR new_job.selection->>'version'<>'OPENPC_RAW_PROOF_DELETION_BATCH_V1'
  OR new_job.stream_id IS NOT NULL OR new_job.segment_id IS NOT NULL
  OR new_job.protected_object_id IS DISTINCT FROM right(new_job.selection->>'objectRef',36)::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||new_job.participant_id::text,0));
 SELECT coalesce(sum(octet_length(ciphertext)),0)::integer INTO current_bytes FROM control.protected_proof_payload
  WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id;
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  IF new_job.previous_deletion_job_id IS NOT NULL THEN
   PERFORM 1 FROM control.deletion_job WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id
    AND deletion_job_id=new_job.previous_deletion_job_id FOR UPDATE;
  END IF;
  plan:=openpc.evidence_deletion_selection_plan(new_job.selection);
  IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM new_job.selection
   OR plan->>'beforeDigest' IS DISTINCT FROM new_job.before_digest OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.retention_policy_id IS DISTINCT FROM right(new_job.selection->>'retentionPolicyId',36)::uuid
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:=openpc.raw_proof_deletion_selector_digest(new_job.selection);
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(new_job.selection),'UTF8')),'hex');
  new_job.before_used_bytes:=current_bytes;new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.target_data_class<>'RAW_SOURCE_BODY' OR old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED'
   OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
      (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.evidence_deletion_item WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  IF item.protected_object_id IS DISTINCT FROM new_job.protected_object_id OR item.object_digest<>new_job.selection->>'payloadDigest'
   OR current_bytes<>new_job.before_used_bytes-item.ciphertext_bytes
   OR EXISTS(SELECT 1 FROM control.protected_proof_payload WHERE participant_id=new_job.participant_id
    AND privacy_domain_id=new_job.privacy_domain_id AND object_id=new_job.protected_object_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.ciphertext_bytes;new_job.after_used_bytes:=current_bytes;
  new_job.after_digest:=openpc.evidence_deletion_after_digest(new_job.target_selector_digest);
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;


ALTER FUNCTION openpc.guard_raw_proof_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) OWNER TO openpc_control_owner;

--
-- Name: guard_receipt_attempt_reference(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_receipt_attempt_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.receipt_signing_attempt a WHERE a.participant_id=NEW.participant_id
  AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=NEW.operation_id AND a.attempt_id=NEW.receipt_id
  AND a.payload_cbor=NEW.receipt_cbor AND a.payload_digest=NEW.receipt_digest AND a.signer_id=NEW.signer_id
  AND a.signer_trust_digest=NEW.signer_trust_snapshot_digest AND a.profile_digest=NEW.profile_digest)
 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-SIGNING-ATTEMPT-REQUIRED'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_receipt_attempt_reference() OWNER TO openpc_control_owner;

--
-- Name: guard_receipt_signing_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_receipt_signing_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE payload jsonb; profile control.business_transition_profile%ROWTYPE;
BEGIN
 payload:=openpc.business_cbor(NEW.payload_cbor);
 SELECT * INTO STRICT profile FROM control.business_transition_profile WHERE profile_digest=NEW.profile_digest;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR
    NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() OR
    NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR
    profile.action_intent_id IS DISTINCT FROM openpc.current_action_intent_id() OR
    payload->'0' IS DISTINCT FROM openpc.business_uuid(NEW.attempt_id) OR
    payload->'1' IS DISTINCT FROM openpc.business_bytes(profile.schema_definition_digest) OR
    payload->>'2' IS DISTINCT FROM profile.profile_id OR payload->'3' IS DISTINCT FROM to_jsonb(profile.profile_version) OR
    payload->'4' IS DISTINCT FROM openpc.business_bytes(NEW.profile_digest) OR
    payload->'6' IS DISTINCT FROM openpc.business_uuid(NEW.participant_id) OR
    payload->'7' IS DISTINCT FROM openpc.business_uuid(NEW.privacy_domain_id) OR
    payload->'8' IS DISTINCT FROM openpc.business_uuid(NEW.operation_id) OR
    payload->>'9' IS DISTINCT FROM profile.action_intent_id OR payload->>'10' IS DISTINCT FROM profile.catalog_operation_id OR
    payload->>'11' IS DISTINCT FROM profile.aggregate_type OR
    payload->>'24' IS DISTINCT FROM NEW.signer_id OR
    payload->'25' IS DISTINCT FROM openpc.business_bytes(NEW.signer_trust_digest) OR
    jsonb_typeof(payload->'23') IS DISTINCT FROM 'number' OR (payload->>'23')::numeric>NEW.reserved_at_ns OR
    NEW.reserved_at_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000 OR
    NOT EXISTS(SELECT 1 FROM control.idempotency_record i WHERE i.participant_id=NEW.participant_id
     AND i.privacy_domain_id=NEW.privacy_domain_id AND i.operation_id=NEW.operation_id AND i.terminal_state IS NULL
     AND payload->'17'=openpc.business_uuid(i.idempotency_record_id) AND payload->'16'=openpc.business_bytes(i.input_digest)
     AND i.action_intent_id=profile.action_intent_id AND i.catalog_operation_id=profile.catalog_operation_id)
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-PAYLOAD'; END IF;
 IF (NEW.reservation_kind='ORDINARY_ATOMIC' AND
     (NEW.schema_version<>1 OR profile.profile_digest NOT IN (decode('d542e56d6db3fe17fed5e5872c850fd4c9a8115077e75941fd477b78729a7b26','hex'),decode('946fcea402d8a83d11bbc68f962729bbafcab59d70bb9c0184da7441f904ea0d','hex'),decode('0153b58a620f9c81e27622a714add5a155ae443b9d18d43e4aaacc2a3c6ca2a9','hex'),decode('0531ef64f2f4aee45bd8ca4d07baaef7ee40b6fceeee117c3797e70118ba218a','hex'),decode('dd31b618e1b8df721fcc23a39214b4731b7fbb18bee13e00902a7abe6e06902b','hex'),decode('c619642e3beda311a511be6d44ad26ead0cdae68e692e883a4a7ac3e63741a55','hex'),decode('fe1906fe240af7e54d5900905af784cac684f6543589d54c0b8cf952d0437445','hex'),decode('fe27d7409b2442ba50a24f46697d8d3e6cef75df2251eceb7ceaa672519f6817','hex'),decode('5ce4897d55b58c268e0fe074eaf583fe7474f5003ae35259128eecd4cae64d44','hex'),decode('d1a1871de2c1f4a2384cc084eb65523ce39c15b968c413e0578c66e177482348','hex'),decode('c5e4dddece0f5e1132cc2df0bcaad338b5e12a7021589f62f292e2962503b672','hex'),decode('47f934877eef5446cf1879d06842209e6512174274d39810ef832c2982a7c938','hex'),decode('0d9012e193c3610a6923cb050b8391b4d697785ff8ec2161ea475d04482940a5','hex'),decode('ea3c533260127e981fe6101d8694c317e37bc8d0d6a7de649af802f4ed9ccd34','hex'),decode('2d087de15c84a6516407ee619cc3f68273916cd9f1cbf86ce16104b452626c5c','hex'),decode('8004afb64e5469e566d7e30fff676124c769732356d7d315ebb115fb73617244','hex'),decode('b976628ecb1267a9dc37bb00aa2e3eaf2ff4651110d88a0964fccd283440dbdc','hex'),decode('303fcd4983bb2c1cac3786bc515a8c864e3dd8e69db32c1913a506674fc266af','hex'),decode('707a618dc0195f8d42560646a148fa6d86cc9194ab64aa2859f7c0e255a71981','hex'),decode('50311f1a2bfc10ca1950ee49d3f432d2ac42310c23104a6f13b8ffd89bfa3979','hex'),decode('7e5b8098c114e840c4f7ece48830ddd7a1201941f54409d14d6b9b97cb04c2f5','hex'),decode('f781ba69e6bc55e070c11e44105508be530a1c32cf6a486474a0baf58e113bac','hex'),decode('a36ada5edf71d8aeb88ce00182e9beb71da3774efcb34b9e793094cf4bdd1b78','hex'),decode('938120e0cd02b01e01632058ca7d73fe2acc07d13f3184c10812597a6ec66d60','hex'),decode('638dfaa2fde289bfd2be4996c59be041c64beb04a2cc52dfc08fa5286f4b6ceb','hex'),decode('d1f1c8ccfbd049063197e8511e1b0604888963b29cc40fec7ca8e72f539d85c5','hex'),decode('c7dd85f469fd74d8f750c1c04d037f5d809696d64eac91175e5c20eb16030016','hex'),decode('c17924c198e473950f12495e87b38676217114aff67408b332aee96fc618fe51','hex'),decode('f9b51989335315afc016422d711f639dfd3ae0dcbb86498f9170ebe1e2a59875','hex'),decode('1061d0df60e81533f20a776034df61d3325446fd9ba5024f607d1852c736f351','hex'),decode('c2315242a6622f61e09e630eb0a90b81343ad930d7af3f65739c75443b4870a4','hex'),decode('55def1ac5122437197df4147ddf3073b30fcc9f311621865b62319a993f7cc28','hex'),decode('5786ec3c5914dc0dfa69f646c66e6e49dee240b6a29d23d546b7f7dbf694eccf','hex'),decode('b2eb7af4bbf9ca7e8609ab763fa542fa7edaf147774f33e0a7a96af9263bf1c1','hex'),decode('66b61e0cf06a4c986d6d7935122840e6ae1daea4d6ad0ef228d497a18011b720','hex'),decode('32eb97df80806f25376f657606b0bce8f2434156f6ef45764622111e6e875b5d','hex'),decode('f909db987a850e8bae75825af7fb3420adbac6af2ee3a0a07a04379d225c238f','hex'),decode('1750d142c98240306871e641587a6dddf68586fd377c7b3010a18c3c0b59a3ce','hex')))) OR
    (NEW.reservation_kind='LIFECYCLE_DURABLE' AND (NEW.schema_version<>2 OR profile.aggregate_type<>'signing-key-rotation')) THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-OWNER'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.business_signing_selection s
  JOIN control.business_signing_key k USING(participant_id,privacy_domain_id,signer_id)
  JOIN control.business_signing_key_state ks USING(participant_id,privacy_domain_id,signer_id)
  WHERE s.participant_id=NEW.participant_id AND s.privacy_domain_id=NEW.privacy_domain_id
   AND s.environment_id=payload->>'5' AND s.profile_digest=NEW.profile_digest AND s.signer_id=NEW.signer_id
   AND s.row_version=NEW.selection_version AND s.admission_version=NEW.admission_version AND s.fence_generation=NEW.fence_generation
   AND s.fenced_operation_id IS NULL
   AND k.trust_digest=NEW.signer_trust_digest AND k.key_epoch=NEW.key_epoch AND ks.state='ACTIVE'
   AND k.valid_from_ns<=(payload->>'23')::numeric AND k.valid_until_ns>NEW.reserved_at_ns
   FOR SHARE OF s,ks) THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-FENCE'; END IF;
 IF NOT openpc.signing_admission_open(NEW.participant_id,NEW.privacy_domain_id,NEW.signer_id,NEW.operation_id)
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-UNRESOLVED-ADMISSION'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_receipt_signing_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_remote_archive_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_remote_archive_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE i control.evidence_remote_archive_intent; s control.evidence_segment;
 expected jsonb; prior jsonb; rules jsonb; protection jsonb; locator jsonb; observation jsonb;
 object_key text; legal_hold text; deadline text; version_id text; admitted record; facts jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND intent_id=NEW.intent_id;
 admitted:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),i.stream_id);
 IF admitted.transport_digest IS DISTINCT FROM i.profile_digest OR admitted.transport IS DISTINCT FROM i.profile
  OR admitted.sink_id IS DISTINCT FROM i.sink_id
  OR coalesce(admitted.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM i.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'STARTED' OR NEW.observation IS NOT NULL OR NEW.observation_digest IS NOT NULL
   OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt a WHERE a.participant_id=i.participant_id
    AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id AND a.state IN ('STARTED','AMBIGUOUS'))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF i.source_kind='SEGMENT' THEN
  SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
   AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
  rules:=openpc.remote_archive_rules(s);
  ELSE
   facts:=openpc.protected_remote_archive_source(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id,i.intent_id);
   IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'object' IS DISTINCT FROM i.intent->'source'->'object'
    OR facts->'lineage'->>'streamId' IS DISTINCT FROM i.stream_id
    OR (NEW.action='PUT' AND (facts->'packet'='null'::jsonb OR (facts->'object'->>'retainUntil')::timestamptz<=clock_timestamp()))
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   rules:=facts->'rules';
  END IF;
  IF jsonb_array_length(rules)>1024 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT a.binding->'protection' INTO prior FROM control.evidence_remote_archive_attempt a
   WHERE a.participant_id=i.participant_id AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id
   ORDER BY (a.binding->'protection'->>'revision')::numeric DESC,a.attempt_id DESC LIMIT 1;
  prior:=coalesce(prior,i.intent->'initialProtection');
  protection:=jsonb_build_object('revision',CASE WHEN rules=prior->'rules' THEN prior->>'revision'
   ELSE ((prior->>'revision')::numeric+1)::text END,'rules',rules);
  IF (protection->>'revision')::numeric NOT BETWEEN 1 AND 18446744073709551615
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.action='PUT' THEN
   locator:='null'::jsonb;
   IF protection IS DISTINCT FROM i.intent->'initialProtection'
    OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt a WHERE a.participant_id=i.participant_id
     AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id)
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF NEW.action='PROTECTION' THEN
   SELECT a.observation->'locator' INTO locator FROM control.evidence_remote_archive_attempt a
    WHERE a.participant_id=i.participant_id AND a.privacy_domain_id=i.privacy_domain_id
     AND a.intent_id=i.intent_id AND a.action='PUT' AND a.state='OBSERVED';
   IF locator IS NULL OR locator='null'::jsonb THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  expected:=jsonb_build_object('attemptId',NEW.attempt_id::text,'intent',i.intent,'intentDigest',i.intent_digest,
   'action',NEW.action,'locator',locator,'protection',protection,
   'protectionDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(protection),'UTF8')),'hex'));
  IF NEW.binding IS DISTINCT FROM expected OR NEW.protection_digest IS DISTINCT FROM expected->>'protectionDigest'
   OR NEW.binding_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.started_at:=clock_timestamp();
 ELSE
  IF OLD.state='OBSERVED' OR OLD.state NOT IN ('STARTED','AMBIGUOUS')
   OR NEW.state NOT IN ('AMBIGUOUS','OBSERVED')
   OR (to_jsonb(NEW)-ARRAY['state','observation','observation_digest','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','observation','observation_digest','updated_at'])
  THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 END IF;
 IF NEW.state='OBSERVED' THEN
  observation:=NEW.observation;
  version_id:=observation->'locator'->>'versionId';
  deadline:=observation->'observedRetention'->>'retainUntil';
  IF coalesce(length(version_id),0) NOT BETWEEN 1 AND 1024 OR version_id='null'
   OR version_id~'[[:cntrl:][:space:]]'
   OR coalesce(deadline,'')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?Z$'
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF i.source_kind='SEGMENT' THEN
  IF deadline::timestamptz < (i.intent->'source'->'object'->>'retentionUntil')::timestamptz
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object_key:=(i.profile->>'prefix')||'/segment/'||encode(sha256(convert_to(openpc.signing_canonical_json(
   jsonb_build_object('sinkId',i.sink_id,'participantId',i.participant_id::text,
    'privacyDomainId',i.privacy_domain_id::text,'streamId',i.stream_id,'segmentId',i.segment_id::text)),'UTF8')),'hex');
  ELSE
   IF deadline::timestamptz IS DISTINCT FROM (i.intent->'source'->'object'->>'retainUntil')::timestamptz
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   object_key:=(i.profile->>'prefix')||'/proof/'||encode(sha256(convert_to(openpc.signing_canonical_json(
    jsonb_build_object('sinkId',i.sink_id,'participantId',i.participant_id::text,
     'privacyDomainId',i.privacy_domain_id::text,'objectRef','urn:openpc:resource:'||i.protected_object_id::text,
     'objectVersion',i.protected_object_version::text)),'UTF8')),'hex');
  END IF;
  locator:=jsonb_build_object('sinkId',i.sink_id,'profileDigest',i.profile_digest,
   'bucket',i.profile->>'bucket','key',object_key,'versionId',version_id);
  SELECT CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.binding->'protection'->'rules') rule
   WHERE rule->>'state'='ACTIVE') THEN 'ON' ELSE 'OFF' END INTO legal_hold;
  expected:=jsonb_build_object('version','OPENPC_REMOTE_ARCHIVE_RECEIPT_V1',
   'intent',i.intent,'intentDigest',i.intent_digest,'locator',locator,
   'assurance','REMOTE_INTERFACE_VERIFIED','providerQualification','NOT_ESTABLISHED',
   'observedRetention',jsonb_build_object('mode','COMPLIANCE','retainUntil',deadline),
   'protection',NEW.binding->'protection','protectionDigest',NEW.protection_digest,
   'observedLegalHold',legal_hold);
  expected:=expected||jsonb_build_object('receiptDigest',
   'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex'));
  IF observation IS DISTINCT FROM expected
   OR NEW.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(observation),'UTF8')),'hex')
   OR (NEW.binding->'locator'<>'null'::jsonb AND observation->'locator' IS DISTINCT FROM NEW.binding->'locator')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_remote_archive_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_remote_archive_intent(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_remote_archive_intent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s control.evidence_segment; payload bytea; object jsonb; expected jsonb; rules jsonb; p jsonb; admitted record; facts jsonb; payload_digest text; payload_size integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 p:=NEW.profile;
 admitted:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),NEW.stream_id);
 IF admitted.transport_digest IS DISTINCT FROM NEW.profile_digest OR admitted.transport IS DISTINCT FROM p
  OR admitted.sink_id IS DISTINCT FROM NEW.sink_id
  OR coalesce(admitted.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM NEW.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 expected:=jsonb_build_object('profileId',p->>'profileId','sinkId',NEW.sink_id,
  'endpoint',p->>'endpoint','transport',p->>'transport','region',p->>'region',
  'bucket',p->>'bucket','expectedBucketOwner',p->>'expectedBucketOwner','prefix',p->>'prefix',
  'lockMode','COMPLIANCE','requestTimeoutMs',p->'requestTimeoutMs','maxVersionPages',p->'maxVersionPages');
 IF p IS DISTINCT FROM expected
  OR NEW.profile_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR coalesce(p->>'profileId','')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR NEW.sink_id!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR coalesce(p->>'region','')!~'^[a-z0-9-]{1,63}$'
  OR coalesce(p->>'bucket','')!~'^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$'
  OR coalesce(p->>'prefix','')!~'^[a-zA-Z0-9_-]{1,64}$'
  OR coalesce(p->>'expectedBucketOwner','')!~'^[0-9]{12}$'
  OR jsonb_typeof(p->'requestTimeoutMs') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p->'maxVersionPages') IS DISTINCT FROM 'number'
  OR coalesce(p->>'requestTimeoutMs','')!~'^[0-9]+$'
  OR coalesce(p->>'maxVersionPages','')!~'^[0-9]+$'
  OR (p->>'requestTimeoutMs')::numeric NOT BETWEEN 100 AND 30000
  OR (p->>'maxVersionPages')::numeric NOT BETWEEN 1 AND 32
  OR NOT coalesce((p->>'transport'='HTTPS' AND p->>'endpoint'~'^https://[^/@?#[:space:]]+/?$')
   OR (p->>'transport'='LOOPBACK_TEST' AND p->>'endpoint'~'^http://127[.]0[.]0[.]1(:[0-9]{1,5})?/?$'),false)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF NEW.source_kind='SEGMENT' THEN
 SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
 SELECT encrypted_segment INTO STRICT payload FROM control.evidence_segment_payload
  WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id
   AND stream_id=s.stream_id AND segment_id=s.segment_id;
 rules:=openpc.remote_archive_rules(s);
 IF jsonb_array_length(rules)>1024 OR s.object_digest<>'sha256:'||encode(sha256(payload),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 object:=jsonb_build_object('sinkId',NEW.sink_id,'participantId',s.participant_id::text,
  'privacyDomainId',s.privacy_domain_id::text,'streamId',s.stream_id,'segmentId',s.segment_id::text,
  'firstSequence',s.first_sequence::text,'throughSequence',s.through_sequence::text,
  'previousSegmentDigest',s.previous_segment_digest,'objectDigest',s.object_digest,'keyId',s.key_id,
  'retentionUntil',to_char(s.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  payload_digest:=s.object_digest; payload_size:=octet_length(payload);
 ELSIF NEW.source_kind='PROTECTED_PROOF' THEN
  facts:=openpc.protected_remote_archive_source(NEW.participant_id,NEW.privacy_domain_id,NEW.protected_object_id,NEW.sink_id);
  IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'packet'='null'::jsonb
   OR facts->'lineage'->>'streamId' IS DISTINCT FROM NEW.stream_id
   OR (facts->'object'->>'retainUntil')::timestamptz<=clock_timestamp()
   OR (facts->'object'->>'objectVersion')::numeric IS DISTINCT FROM NEW.protected_object_version
   OR facts->'object'->>'objectDigest' IS DISTINCT FROM NEW.protected_object_digest
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object:=facts->'object'; rules:=facts->'rules';
  payload_digest:=object->>'payloadDigest'; payload_size:=(facts->>'payloadBytes')::integer;
 ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('intentId',NEW.intent_id::text,'profileDigest',NEW.profile_digest,
  'source',jsonb_build_object('kind',NEW.source_kind,'object',object),'payloadDigest',payload_digest,
  'payloadBytes',payload_size,'initialProtection',jsonb_build_object('revision','1','rules',rules));
 IF NEW.intent IS DISTINCT FROM expected
  OR NEW.intent_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_remote_archive_intent() OWNER TO openpc_control_owner;

--
-- Name: guard_removed_membership(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_removed_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF OLD.state='OFFBOARDED' AND NEW.state<>OLD.state AND EXISTS (
   SELECT 1 FROM control.participant_membership membership
    WHERE membership.participant_id=OLD.participant_id AND membership.membership_id=OLD.principal_id) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-MEMBERSHIP-TERMINAL';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_removed_membership() OWNER TO openpc_control_owner;

--
-- Name: guard_retention_policy(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_retention_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE predecessor control.retention_policy%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF openpc.business_cbor(NEW.policy_cbor) IS DISTINCT FROM jsonb_build_object(
  '0','pc.evidence.retention-policy.v1','1',openpc.business_uuid(NEW.participant_id),'2',openpc.business_uuid(NEW.privacy_domain_id),
  '3',NEW.data_class,'4',NEW.policy_version,'5',NEW.retention_period_ms,'6',NEW.local_grace_ms,
  '7',NEW.sink_quorum,'8',NEW.deletion_mode,'9',CASE WHEN NEW.maker_checker_required THEN 1 ELSE 0 END) THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision<>1 OR NEW.active_until IS NOT NULL OR NEW.retirement_operation_id IS NOT NULL
   OR NEW.retirement_approval_request_id IS NOT NULL OR NEW.activation_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-RETENTION_POLICIES_CREATE_RESOURCE-V1'
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  SELECT * INTO predecessor FROM control.retention_policy p WHERE p.participant_id=NEW.participant_id
   AND p.privacy_domain_id=NEW.privacy_domain_id AND p.data_class=NEW.data_class
   ORDER BY p.active_from DESC,p.retention_policy_id DESC LIMIT 1 FOR UPDATE;
  IF NEW.predecessor_policy_id IS DISTINCT FROM predecessor.retention_policy_id
   OR (predecessor.retention_policy_id IS NOT NULL AND predecessor.active_until IS NULL)
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.active_from:=clock_timestamp();NEW.created_at:=NEW.active_from;
  IF predecessor.active_until IS NOT NULL AND predecessor.active_until>NEW.active_from THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['revision','active_until','retirement_operation_id','retirement_approval_request_id','updated_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['revision','active_until','retirement_operation_id','retirement_approval_request_id','updated_at'])
   OR OLD.revision<>1 OR NEW.revision<>2 OR OLD.active_until IS NOT NULL
   OR NEW.retirement_operation_id<>current_setting('openpc.operation_id')::uuid
   OR current_setting('openpc.action_intent_id')<>'ACT-RETENTION_POLICIES_RETIRE_RESOURCE-V1'
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.active_until:=clock_timestamp();
 END IF;
 NEW.updated_at:=clock_timestamp();RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_retention_policy() OWNER TO openpc_control_owner;

--
-- Name: guard_root_expiry_recovery_case(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_root_expiry_recovery_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE e control.root_expiry_recovery_enrollment;
BEGIN
 IF TG_OP='DELETE' OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.intent->>'qaDurationProfile'='LOCAL_QA_10X' AND
     current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 OR NEW.result IS NOT NULL OR NEW.operation_id IS NOT NULL THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 ELSE
  IF NEW.row_version<>OLD.row_version+1 OR NEW.updated_at<=OLD.updated_at
   OR (to_jsonb(NEW)-ARRAY['state','row_version','updated_at','result','operation_id','evidence_cbor','evidence_digest','evidence_cose']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','updated_at','result','operation_id','evidence_cbor','evidence_digest','evidence_cose'])
   OR NOT ((OLD.state='DRAFT' AND NEW.state IN ('REQUESTED','REVOKED','EXPIRED')) OR
      (OLD.state='REQUESTED' AND NEW.state IN ('COMPLETED','REVOKED','EXPIRED')))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 END IF;
 IF NEW.intent->>'schema' IS DISTINCT FROM 'pc.identity.local-root-expiry-recovery-intent'
   OR NOT coalesce(((NEW.intent->>'schemaVersion'='1' AND NEW.intent->>'purpose'='LOCAL_ROOT_EXPIRY_RECOVERY_ONLY'
      AND NOT (NEW.intent ? 'pending')) OR (NEW.intent->>'schemaVersion'='2'
      AND NEW.intent->>'purpose'='LOCAL_ROOT_EXPIRY_PENDING_RECOVERY_ONLY' AND jsonb_typeof(NEW.intent->'pending')='object')
      OR (NEW.intent->>'schemaVersion'='3' AND NEW.intent->>'purpose'='LOCAL_ROOT_EXPIRY_PENDING_ANCESTRY_RECOVERY_ONLY'
        AND jsonb_typeof(NEW.intent->'pending')='object' AND jsonb_typeof(NEW.intent->'rootAncestry')='object')),false)
   OR NEW.intent_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.intent),'UTF8'))
   OR NEW.intent->>'recoveryId' IS DISTINCT FROM NEW.recovery_id::text OR NEW.intent->>'enrollmentId' IS DISTINCT FROM NEW.enrollment_id::text
   OR NEW.intent->>'enrollmentRevision' IS DISTINCT FROM NEW.enrollment_revision::text
   OR NEW.intent->>'enrollmentDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.enrollment_digest,'hex')
   OR (NEW.intent->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from OR (NEW.intent->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 IF NEW.state IN ('DRAFT','REQUESTED') THEN
  SELECT * INTO e FROM control.root_expiry_recovery_enrollment WHERE enrollment_id=NEW.enrollment_id AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND row_version=NEW.enrollment_revision AND document_digest=NEW.enrollment_digest
   AND valid_until>=NEW.valid_until AND openpc.root_expiry_recovery_source_current(enrollment_id);
  IF NOT FOUND OR NEW.valid_until<=clock_timestamp()
   OR NEW.intent->'qaDurationProfile' IS DISTINCT FROM e.document->'qaDurationProfile'
   OR NEW.intent->>'schemaVersion' IS DISTINCT FROM e.document->>'schemaVersion'
   OR NEW.intent->'pending' IS DISTINCT FROM e.document->'pending'
   OR NEW.intent->'rootAncestry' IS DISTINCT FROM e.document->'rootAncestry'
   OR NEW.valid_until>NEW.valid_from+(CASE WHEN e.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN interval '2 days' ELSE interval '15 minutes' END)
   -- Historical signed cases retain their original ceiling on continuation.
   OR (TG_OP='INSERT' AND e.document->>'qaDurationProfile'='LOCAL_QA_10X'
       AND NEW.valid_until>NEW.valid_from+interval '150 minutes')
   OR NEW.intent->>'predecessorEpoch' IS DISTINCT FROM e.document->>'rootEpoch'
   OR NEW.intent->>'predecessorRevision' IS DISTINCT FROM e.document->>'rootRevision'
   OR NEW.intent->>'predecessorDigest' IS DISTINCT FROM e.document->>'rootDigest'
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 END IF;
 IF NEW.state='REQUESTED' AND NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_proof p
  WHERE p.recovery_id=NEW.recovery_id AND p.participant_id=NEW.participant_id AND p.phase='REQUEST' AND p.intent_digest=NEW.intent_digest) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 IF NEW.state='COMPLETED' AND (current_user<>'openpc_control_owner' OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_scope s WHERE s.recovery_id=NEW.recovery_id
    AND s.owner_participant_id=NEW.participant_id AND s.installation_privacy_domain_id=NEW.privacy_domain_id
    AND s.activation_operation_id=NEW.operation_id AND s.intent_digest=NEW.intent_digest AND s.enrollment_digest=NEW.enrollment_digest)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_root_expiry_recovery_case() OWNER TO openpc_control_owner;

--
-- Name: guard_root_expiry_recovery_challenge(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_root_expiry_recovery_challenge() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='UPDATE' AND (OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL OR NEW.proof_id IS NULL
   OR (to_jsonb(NEW)-ARRAY['consumed_at','proof_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['consumed_at','proof_id'])
   OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_proof p WHERE p.proof_id=NEW.proof_id AND p.challenge_id=NEW.challenge_id
    AND p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id AND p.recovery_id=NEW.recovery_id)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND (NEW.consumed_at IS NOT NULL OR NEW.proof_id IS NOT NULL) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND NEW.verified_proof_max_age_ms IS DISTINCT FROM
   (CASE WHEN NEW.duration_profile='LOCAL_QA_10X' THEN 3000000 ELSE 300000 END) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND NEW.duration_profile='LOCAL_QA_10X' AND
  (current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
   OR current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X'
   OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_case r
     WHERE r.recovery_id=NEW.recovery_id AND r.participant_id=NEW.participant_id
      AND r.privacy_domain_id=NEW.privacy_domain_id AND r.intent_digest=NEW.intent_digest
      AND r.intent->>'qaDurationProfile'='LOCAL_QA_10X' AND NEW.expires_at<=r.valid_until)
   OR NOT EXISTS(SELECT 1 FROM control.session s JOIN control.credential c
      ON c.participant_id=s.participant_id AND c.principal_id=s.principal_id AND c.credential_id=NEW.credential_id
     WHERE s.participant_id=NEW.participant_id AND s.principal_id=NEW.principal_id AND s.session_id=NEW.session_id
      AND s.session_epoch=NEW.session_epoch AND s.duration_profile='LOCAL_QA_10X' AND s.state='ACTIVE'
      AND NEW.expires_at<=s.idle_expires_at AND NEW.expires_at<=s.absolute_expires_at
      AND c.kind='WEBAUTHN' AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp()
      AND (c.valid_until IS NULL OR NEW.expires_at<=c.valid_until))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_root_expiry_recovery_challenge() OWNER TO openpc_control_owner;

--
-- Name: guard_root_expiry_recovery_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_root_expiry_recovery_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE expected_schema text; record_id text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.row_version<>OLD.row_version+1
   OR (to_jsonb(NEW)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  NEW.revoked_at:=clock_timestamp();
  RETURN NEW;
 END IF;
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' OR current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 PERFORM openpc.assert_request_context(true);
 expected_schema:=CASE TG_TABLE_NAME
  WHEN 'root_expiry_recovery_trust' THEN 'pc.installation.local-root-expiry-recovery-receiving-trust'
  WHEN 'root_expiry_recovery_enrollment' THEN 'pc.identity.local-root-expiry-recovery-enrollment'
  ELSE NULL END;
 record_id:=CASE TG_TABLE_NAME
  WHEN 'root_expiry_recovery_trust' THEN to_jsonb(NEW)->>'custody_trust_id'
  ELSE to_jsonb(NEW)->>'enrollment_id' END;
 IF NEW.document->>'schemaVersion' IN ('2','3') THEN PERFORM openpc.lock_root_expiry_pending_source(NEW.platform_context_id); END IF;
 IF expected_schema IS NULL OR NEW.document->>'schema' IS DISTINCT FROM expected_schema
  OR NOT coalesce(((NEW.document->>'schemaVersion'='1'
      AND NEW.document->>'purpose'='pc.installation.local-root-expiry-recovery-custody.v1' AND NOT (NEW.document ? 'pending')
      AND NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.platform_context_id=NEW.platform_context_id AND r.state='WITHDRAWING'))
    OR (NEW.document->>'schemaVersion'='2'
      AND NEW.document->>'purpose'='pc.installation.local-root-expiry-pending-recovery-custody.v2'
      AND NEW.document->'pending'=openpc.read_root_expiry_pending_witness(NEW.platform_context_id))
    OR (NEW.document->>'schemaVersion'='3'
      AND NEW.document->>'purpose'='pc.installation.local-root-expiry-pending-ancestry-custody.v3'
      AND jsonb_build_object('pending',NEW.document->'pending','rootAncestry',NEW.document->'rootAncestry')=
        openpc.read_root_expiry_pending_ancestry_witness(NEW.platform_context_id))),false)
  OR NEW.document->>'profile' IS DISTINCT FROM 'LOCAL_QA'
  OR (NEW.document ? 'qaDurationProfile' AND (NEW.document->>'qaDurationProfile' IS DISTINCT FROM 'LOCAL_QA_10X'
      OR current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X'))
  OR NEW.valid_until>NEW.valid_from+(CASE WHEN NEW.document->>'qaDurationProfile'='LOCAL_QA_10X' THEN interval '10 days' ELSE interval '1 day' END)
  OR NEW.state<>'ACTIVE' OR NEW.row_version<>1
  OR NEW.document_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.document),'UTF8'))
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR NEW.document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NEW.document->>'platformContextId' IS DISTINCT FROM NEW.platform_context_id::text
  OR (NEW.document->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
  OR (NEW.document->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
  OR NEW.valid_from>clock_timestamp() OR NEW.valid_until<=clock_timestamp()
  OR (CASE WHEN TG_TABLE_NAME='root_expiry_recovery_trust'
    THEN NEW.document->>'custodyTrustId' ELSE NEW.document->>'enrollmentId' END) IS DISTINCT FROM record_id
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 IF TG_TABLE_NAME='root_expiry_recovery_enrollment' THEN
  IF NEW.document->>'custodyTrustId' IS DISTINCT FROM NEW.custody_trust_id::text
   OR NEW.document->>'custodyTrustDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.custody_trust_digest,'hex')
   OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_trust trust
    WHERE trust.custody_trust_id=NEW.custody_trust_id AND trust.participant_id=NEW.participant_id
     AND trust.privacy_domain_id=NEW.privacy_domain_id AND trust.document_digest=NEW.custody_trust_digest
     AND trust.document->'qaDurationProfile' IS NOT DISTINCT FROM NEW.document->'qaDurationProfile'
     AND trust.document->>'schemaVersion'=NEW.document->>'schemaVersion'
     AND trust.document->>'purpose'=NEW.document->>'purpose'
     AND trust.document->'pending' IS NOT DISTINCT FROM NEW.document->'pending'
     AND trust.document->'rootAncestry' IS NOT DISTINCT FROM NEW.document->'rootAncestry'
     AND trust.state='ACTIVE' AND trust.row_version=1 AND trust.valid_from<=NEW.valid_from AND trust.valid_until>=NEW.valid_until)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-CUSTODY'; END IF;
  IF (NEW.document->>'successorValidFrom')::timestamptz < clock_timestamp()-interval '30 seconds'
   OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_trust trust WHERE trust.custody_trust_id=NEW.custody_trust_id
    AND (NEW.document->>'successorValidFrom')::timestamptz>=trust.created_at-interval '30 seconds')
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY-INSTALLATION-TIME'; END IF;
 END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_root_expiry_recovery_installation() OWNER TO openpc_control_owner;

--
-- Name: guard_root_expiry_recovery_proof(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_root_expiry_recovery_proof() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_challenge c JOIN control.root_expiry_recovery_case r
   ON r.recovery_id=c.recovery_id AND r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id
  JOIN control.root_expiry_recovery_enrollment source ON source.enrollment_id=r.enrollment_id
   AND source.participant_id=r.participant_id AND source.privacy_domain_id=r.privacy_domain_id
   AND source.state='ACTIVE' AND source.row_version=r.enrollment_revision AND source.document_digest=r.enrollment_digest
   AND openpc.root_expiry_recovery_source_current(source.enrollment_id)
  JOIN LATERAL jsonb_array_elements(CASE WHEN NEW.phase='APPROVE' THEN source.document->'custodians'
    ELSE jsonb_build_array(source.document->'recoveryPrincipal') END) signer
   ON signer->>'principalId'=NEW.principal_id::text AND signer->>'credentialId'=NEW.credential_id::text
    AND signer->>'principalEpoch'=NEW.principal_epoch::text AND signer->>'credentialEpoch'=NEW.credential_epoch::text
  JOIN control.principal p ON p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id
   AND p.state='ACTIVE' AND p.authority_epoch=NEW.principal_epoch
  JOIN control.credential credential ON credential.participant_id=p.participant_id AND credential.principal_id=p.principal_id
   AND credential.credential_id=NEW.credential_id AND credential.credential_epoch=NEW.credential_epoch
   AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  JOIN control.session session ON session.participant_id=p.participant_id AND session.principal_id=p.principal_id
   AND session.session_id=NEW.session_id AND session.session_epoch=NEW.session_epoch AND session.authority_epoch=p.authority_epoch
   AND session.context_mode='PLATFORM' AND session.privacy_domain_id IS NULL AND session.state='ACTIVE'
   AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
  JOIN control.participant participant ON participant.participant_id=p.participant_id AND participant.state='ACTIVE'
   AND participant.authority_epoch=session.participant_epoch
  WHERE c.challenge_id=NEW.challenge_id AND c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND c.recovery_id=NEW.recovery_id AND c.principal_id=NEW.principal_id AND c.credential_id=NEW.credential_id
   AND c.session_id=NEW.session_id AND c.session_epoch=NEW.session_epoch AND c.phase=NEW.phase
   AND c.intent_digest=NEW.intent_digest AND r.intent_digest=NEW.intent_digest
   AND ((NEW.phase='REQUEST' AND r.state='DRAFT') OR (NEW.phase IN ('APPROVE','ACTIVATE') AND r.state='REQUESTED'))
   AND c.consumed_at IS NULL AND c.expires_at>clock_timestamp() AND r.valid_until>clock_timestamp()
   AND NEW.verified_at BETWEEN c.created_at AND clock_timestamp()
   AND source.valid_from<=clock_timestamp() AND source.valid_until>clock_timestamp()
   AND (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator h
    WHERE h.participant_id=p.participant_id AND h.principal_id=p.principal_id AND h.credential_id=credential.credential_id))
   AND NEW.assertion_evidence#>>'{verified,version}'='OPENPC_VERIFIED_WEBAUTHN_ASSERTION_V1'
   AND NEW.assertion_evidence#>>'{verified,userVerification}'='REQUIRED_VERIFIED'
   AND NEW.assertion_evidence#>>'{verified,credentialId}'=credential.credential_id::text
   AND NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}'='sha256:'||encode(credential.public_key_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,principalId}'=NEW.principal_id::text
   AND NEW.assertion_evidence#>>'{verified,sessionId}'=NEW.session_id::text
   AND NEW.assertion_evidence#>>'{verified,actionIntentId}'='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
   AND NEW.assertion_evidence#>>'{verified,resourceDigest}'='sha256:'||encode(NEW.intent_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,challengeDigest}'='sha256:'||encode(c.challenge_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,origin}'=c.origin
   AND NEW.assertion_evidence#>>'{verified,signCount}'=NEW.authenticator_sign_count::text
   AND (NEW.assertion_evidence#>>'{verified,verifiedAt}')::timestamptz=NEW.verified_at) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NEW.assertion_digest IS DISTINCT FROM sha256(convert_to(NEW.assertion_evidence#>>'{verified,version}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,principalId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,sessionId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,actionIntentId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,resourceDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,challengeDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,rpIdHash}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,origin}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,authenticatorDataDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,clientDataJsonDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signatureDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signCount}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,verifiedAt}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,userVerification}','UTF8')) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_root_expiry_recovery_proof() OWNER TO openpc_control_owner;

--
-- Name: guard_root_expiry_recovery_scope(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_root_expiry_recovery_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' OR current_user<>'openpc_control_owner' OR NEW.activation_operation_id IS DISTINCT FROM openpc.current_operation_id()
 OR NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_case c JOIN control.root_expiry_recovery_enrollment e
  ON e.enrollment_id=c.enrollment_id AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
  JOIN control.platform_context p ON p.platform_context_id=e.platform_context_id AND p.owner_participant_id=e.participant_id
  WHERE c.recovery_id=NEW.recovery_id AND c.state='REQUESTED' AND c.intent_digest=NEW.intent_digest AND c.enrollment_digest=NEW.enrollment_digest
   AND p.authority_epoch=NEW.predecessor_epoch AND p.authority_epoch+1=NEW.platform_authority_epoch
   AND openpc.root_expiry_recovery_source_current(e.enrollment_id)
   AND openpc.root_expiry_recovery_proofs_current(c,(select proof_id from control.root_expiry_recovery_proof
     where recovery_id=c.recovery_id and participant_id=c.participant_id and phase='ACTIVATE'))
   AND NEW.predecessor_digest=decode(substring(c.intent->>'predecessorDigest' from 8),'hex')
   AND openpc.platform_scope_document(NEW.scope_cbor)=c.intent->'successorScope') THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_root_expiry_recovery_scope() OWNER TO openpc_control_owner;

--
-- Name: guard_rotation_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_rotation_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rotation control.signing_key_rotation%ROWTYPE; previous control.signing_rotation_history%ROWTYPE;
BEGIN
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id
  AND revision=NEW.revision AND state=NEW.state;
 IF NEW.revision>1 THEN
  SELECT * INTO STRICT previous FROM control.signing_rotation_history WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.revision-1;
  IF NEW.prior_state<>previous.state OR NEW.prior_digest<>previous.history_digest THEN RAISE EXCEPTION 'DATA-6021-ROTATION-HISTORY-CHAIN'; END IF;
 END IF;
 IF NEW.history_preimage<>openpc.rotation_history_preimage(rotation,NEW.prior_state,NEW.operation_id,NEW.event_id,NEW.receipt_id,NEW.evidence_id)
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-HISTORY-BINDING'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_rotation_history() OWNER TO openpc_control_owner;

--
-- Name: guard_rpc_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_rpc_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p jsonb:=NEW.projection; a jsonb:=p->'activation'; t jsonb:=p->'transition'; deleted_source control.evidence_catalogue;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT deleted_source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
   AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(deleted_source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF p-ARRAY['integrity','activationIntegrity','authority','currentAuthority','providerEffect','chainFinality',
  'decisionId','targetRuntimeId','spoolId','sourceSequence','sourceDigest','capsuleDigest','reservedAtNs','occurredAtNs','transition','activation']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(p))<>16
  OR a-ARRAY['operationId','attemptId','configurationWorkId','generationId','generationDigest','receiptDigest','signerId','verificationKeyDigest']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(a))<>8
  OR t-ARRAY['phase','traceId','requestDigest','decisionDigest','responseDigest','authorityBindingDigest','sourceScopeDigest','operationId',
   'pcCode','decisionEffect','boundary','sourceSegmentId','sourceRecordDigest','admittedAtNs']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(t))<>14
  OR p->>'integrity' IS DISTINCT FROM 'AEAD_CHAIN_VERIFIED_AT_CUSTODY'
  OR p->>'activationIntegrity' IS DISTINCT FROM 'ACTIVATION_COSE_VERIFIED_AT_CUSTODY'
  OR p->>'authority' IS DISTINCT FROM 'NONE' OR p->>'currentAuthority' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR p->>'providerEffect' IS DISTINCT FROM 'NOT_ESTABLISHED' OR p->>'chainFinality' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR NEW.record_id<>'rpc:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(p->>'targetRuntimeId',p->>'spoolId')),'UTF8')),'hex')||':'||(p->>'sourceSequence')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c WHERE c.participant_id=NEW.participant_id
  AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id
  AND c.evidence_class='EFFECT' AND c.source_format='OPENPC_RPC_DECISION_TRANSITION_V1'
  AND c.receipt_digest=p->>'sourceDigest' AND c.sequence::text=p->>'sourceSequence'
  AND extract(epoch FROM c.occurred_at)*1000000=floor((p->>'occurredAtNs')::numeric/1000)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation o JOIN control.configuration_work w
  ON w.participant_id=o.participant_id AND w.privacy_domain_id=o.privacy_domain_id AND w.configuration_work_id=o.configuration_work_id
   AND w.runtime_target_id=o.runtime_target_id AND w.runtime_configuration_generation_id=o.runtime_configuration_generation_id
   AND w.operation_id=o.operation_id AND w.execution_attempt_id=o.execution_attempt_id AND w.generation_digest=o.generation_digest AND w.state='COMPLETED'
  WHERE o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id
   AND o.runtime_target_id::text=p->>'targetRuntimeId' AND o.capsule_digest=p->>'capsuleDigest'
   AND o.operation_id::text=a->>'operationId' AND o.execution_attempt_id::text=a->>'attemptId'
   AND o.configuration_work_id::text=a->>'configurationWorkId' AND o.runtime_configuration_generation_id::text=a->>'generationId'
   AND o.generation_digest=a->>'generationDigest'
   AND 'sha256:'||encode(sha256(decode(o.activation_receipt->>'activationReceiptCoseHex','hex')),'hex')=a->>'receiptDigest') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_rpc_provenance() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_activation_maintenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_activation_maintenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'ACTIVATION-MAINTENANCE-IMMUTABLE'; END IF;
 IF current_user<>session_user OR current_setting('role')<>'none'
 OR NEW.intent->>'databaseRole' IS DISTINCT FROM current_user::text
 OR NEW.intent->>'workerRole' IS DISTINCT FROM 'openpc_control_worker'
 OR NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
 OR pg_has_role(current_user,'openpc_control_owner','USAGE')
 OR has_schema_privilege(current_user,'control','CREATE')
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN(current_user,session_user) AND (rolsuper OR rolbypassrls))
 OR current_setting('session_replication_role')<>'origin' 
 OR current_setting('row_security')<>'on'
 OR NOT EXISTS (
  SELECT 1 FROM control.configuration_work w
  JOIN control.runtime_activation_observation o USING(configuration_work_id,participant_id,privacy_domain_id,operation_id,execution_attempt_id,runtime_target_id,runtime_configuration_generation_id,generation_digest,xds_version_digest)
  JOIN control.policy_activation_occurrence_target c ON c.participant_id=w.participant_id
   AND c.privacy_domain_id=w.privacy_domain_id AND c.configuration_work_id=w.configuration_work_id
   AND c.phase='FORWARD' AND c.state='ACTIVE_MATCHED'
  JOIN control.runtime_target_disposition_admission a ON a.participant_id=w.participant_id
   AND a.privacy_domain_id=w.privacy_domain_id AND a.runtime_target_id=w.runtime_target_id
   AND a.revision=(NEW.intent->>'dispositionRevision')::bigint
  JOIN control.runtime_target_disposition_delivery d ON d.participant_id=a.participant_id
   AND d.privacy_domain_id=a.privacy_domain_id AND d.runtime_target_id=a.runtime_target_id AND d.revision=a.revision
  JOIN control.runtime_target_disposition_acknowledgement k ON k.participant_id=d.participant_id
   AND k.privacy_domain_id=d.privacy_domain_id AND k.runtime_target_id=d.runtime_target_id AND k.delivery_digest=d.delivery_digest
  WHERE w.configuration_work_id=NEW.configuration_work_id AND w.participant_id=NEW.participant_id
   AND w.privacy_domain_id=NEW.privacy_domain_id AND w.operation_id=NEW.operation_id
   AND w.execution_attempt_id=NEW.execution_attempt_id AND w.result_event_id=NEW.result_event_id
   AND w.state='COMPLETED' AND w.work_kind='RUNTIME_ACTIVATION' AND w.predecessor_digest IS NULL
   AND w.attempt_count=NEW.claim_count AND w.lease_owner IS NULL AND w.lease_until IS NULL
   AND w.xmin=pg_current_xact_id()::xid
   AND NEW.intent->>'schemaVersion'='1'
   AND NEW.intent->>'occurrenceId'=c.activation_occurrence_id::text
   AND a.binding->>'action'='ConfirmActivation'
   AND a.binding->'source'->>'original_work_id'=w.configuration_work_id::text
   AND a.activation_proof->>'occurrenceId'=c.activation_occurrence_id::text
   AND NEW.intent->>'deliveryDigest'='sha256:'||encode(sha256(d.signed_delivery),'hex')
   AND NEW.intent->>'acknowledgementDigest'='sha256:'||encode(sha256(k.signed_acknowledgement),'hex')
   AND NEW.intent->>'participantId'=w.participant_id::text
   AND NEW.intent->>'privacyDomainId'=w.privacy_domain_id::text
   AND NEW.intent->>'workId'=w.configuration_work_id::text
   AND NEW.intent->>'operationId'=w.operation_id::text
   AND NEW.intent->>'executionAttemptId'=w.execution_attempt_id::text
   AND NEW.intent->>'runtimeTargetId'=w.runtime_target_id::text
   AND NEW.intent->>'generationId'=w.runtime_configuration_generation_id::text
   AND NEW.intent->>'generationDigest'=w.generation_digest
   AND NEW.intent->>'configurationDigest'=w.configuration_digest
   AND NEW.intent->>'xdsVersionDigest'=w.xds_version_digest
   AND NEW.intent->>'capsuleDigest'=o.capsule_digest
   AND NEW.intent->>'receiptDigest'=o.activation_receipt_digest
   AND NEW.intent->>'receiptDigest'=w.result_receipt_digest
   AND (NEW.intent->>'claimCount')::bigint=NEW.claim_count
 ) THEN RAISE EXCEPTION 'ACTIVATION-MAINTENANCE-ORIGINAL-REJECTED'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_activation_maintenance() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_archive(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_archive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE m jsonb:=NEW.manifest; i jsonb:=m->'identity'; entry jsonb;
 prefix text; expected_id text; expected_digest text; expected_format text; index integer:=0;
 total integer; part_count integer; previous_sequence numeric:=0; original control.evidence_catalogue;
 native control.runtime_configuration_input; source control.runtime_artifact_source; pending jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- Direct SQL may arrive after other row locks; never reverse-wait. The
 -- ordinary custody owner already acquired this same lock before stream rows.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT native FROM control.runtime_configuration_input WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND runtime_configuration_input_id=NEW.runtime_configuration_input_id FOR SHARE;
 IF i IS DISTINCT FROM jsonb_build_object('participantId',native.participant_id::text,
  'privacyDomainId',native.privacy_domain_id::text,'runtimeConfigurationInputId',native.runtime_configuration_input_id::text,
  'moduleInstallationId',native.module_installation_id::text,'moduleConfigurationGenerationId',native.module_configuration_generation_id::text,
  'configurationDigest','sha256:'||encode(native.configuration_digest,'hex'),'configurationBytes',octet_length(native.configuration_cbor),
  'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(native.resource_bindings),'UTF8')),'hex'),
  'createdAt',to_char(native.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
  OR sha256(native.configuration_cbor) IS DISTINCT FROM native.configuration_digest
  OR octet_length(native.configuration_cbor) NOT BETWEEN 1 AND 4194304
  OR m IS DISTINCT FROM jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1',
   'class','RUNTIME_ARTIFACT','store','openpc_control','authority','NONE','currentReadiness','NOT_ESTABLISHED',
   'identity',i,'identityDigest',m->'identityDigest','chunks',m->'chunks')
  OR jsonb_typeof(m->'chunks') IS DISTINCT FROM 'array'
  OR jsonb_array_length(m->'chunks') NOT BETWEEN 1 AND 64
  OR NEW.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(m),'UTF8')),'hex')
  OR m->>'identityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
   jsonb_build_object('domain','pc.runtime-artifact.archive-identity.v1','identity',i)),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO source FROM control.runtime_artifact_source WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id;
 IF source.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v2' THEN
  pending:=openpc.runtime_artifact_archive_permit(NEW.runtime_configuration_input_id,NEW.stream_id);
  IF NEW.source_pending_original IS DISTINCT FROM decode(pending->>'original','hex')
   THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-ORIGINAL-UNAVAILABLE'; END IF;
 ELSIF NEW.source_pending_original IS NOT NULL THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-ORIGINAL-UNAVAILABLE'; END IF;
 total:=octet_length(native.configuration_cbor); part_count:=jsonb_array_length(m->'chunks');
 prefix:='runtime-artifact:'||substring(m->>'identityDigest' from 8);
 IF part_count<>(total+65535)/65536 OR NEW.record_id<>prefix||':manifest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(m->'chunks') LOOP
  IF entry IS DISTINCT FROM jsonb_build_object('index',index,'offset',index*65536,
    'bytes',least(65536,total-index*65536),'recordId',prefix||':chunk:'||index::text,'digest',entry->'digest')
    OR entry->>'digest' IS DISTINCT FROM 'sha256:'||encode(sha256(substring(native.configuration_cbor from index*65536+1 for least(65536,total-index*65536))),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  index:=index+1;
 END LOOP;
 -- Every chunk precedes the final manifest. The native input identity never
 -- substitutes for the catalogue's contiguous archive sequence.
 FOR index IN 0..part_count LOOP
  expected_id:=CASE WHEN index=part_count THEN NEW.record_id ELSE m->'chunks'->index->>'recordId' END;
  expected_digest:=CASE WHEN index=part_count THEN NEW.manifest_digest ELSE m->'chunks'->index->>'digest' END;
  expected_format:=CASE WHEN index=part_count THEN 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1' ELSE 'OPENPC_RUNTIME_ARTIFACT_CHUNK_V1' END;
  SELECT c.* INTO STRICT original FROM control.evidence_catalogue c
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_segment_payload body USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.stream_id=NEW.stream_id AND c.record_id=expected_id
    AND c.evidence_class='EFFECT' AND c.source_format=expected_format AND c.receipt_digest=expected_digest
    AND c.occurred_at=native.created_at AND c.sequence BETWEEN s.first_sequence AND s.through_sequence
    AND s.object_digest='sha256:'||encode(sha256(body.encrypted_segment),'hex')
    AND (NEW.source_pending_original IS NULL OR (c.xmin=pg_current_xact_id()::xid AND s.xmin=pg_current_xact_id()::xid AND body.xmin=pg_current_xact_id()::xid));
  IF original.sequence<=previous_sequence THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  previous_sequence:=original.sequence;
 END LOOP;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_archive() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_archive_part(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_archive_part() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE parent control.evidence_runtime_artifact_archive; expected text; count_parts integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT parent FROM control.evidence_runtime_artifact_archive WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.manifest_record_id;
 count_parts:=jsonb_array_length(parent.manifest->'chunks');
 expected:=CASE WHEN NEW.ordinal=count_parts THEN parent.record_id ELSE parent.manifest->'chunks'->NEW.ordinal->>'recordId' END;
 IF expected IS NULL OR NEW.record_id IS DISTINCT FROM expected OR NEW.ordinal<0 OR NEW.ordinal>count_parts THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_archive_part() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_deletion_job(text, control.deletion_job, control.deletion_job); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) RETURNS control.deletion_job
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected jsonb; item control.runtime_artifact_retirement;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF operation NOT IN ('INSERT','UPDATE') OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
  OR new_job.participant_id IS DISTINCT FROM openpc.current_participant_id() OR new_job.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR new_job.operation_id IS DISTINCT FROM openpc.current_operation_id() OR new_job.target_database<>'openpc_control'
  OR new_job.target_data_class<>'RUNTIME_ARTIFACT' OR new_job.external_attempt_state<>'NOT_STARTED'
  OR new_job.selection->>'version' IS DISTINCT FROM 'OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1'
  OR new_job.stream_id IS DISTINCT FROM new_job.selection->>'streamId' OR new_job.segment_id IS NOT NULL
  OR new_job.protected_object_id IS NOT NULL
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  selected:=openpc.runtime_artifact_retirement_selection(new_job.retention_policy_id,new_job.previous_deletion_job_id);
  IF selected IS DISTINCT FROM new_job.selection OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before(selected->'source')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'domain','pc.evidence.runtime-artifact-selector.v1','source',selected->'source')),'UTF8')),'hex');
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(selected),'UTF8')),'hex');
  new_job.before_used_bytes:=(selected->'source'->>'configurationBytes')::integer;new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED' OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
    (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.runtime_artifact_retirement WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.configuration_bytes;new_job.after_used_bytes:=0;
  new_job.after_digest:=openpc.runtime_artifact_retirement_after_digest(item);
  PERFORM openpc.assert_runtime_artifact_retirement_effect(new_job,item);
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_deletion_job(operation text, old_job control.deletion_job, new_job control.deletion_job) OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_disposition_row(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_disposition_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual jsonb;
BEGIN
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>1 OR openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR NEW.revision<>1
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 actual:=openpc.runtime_artifact_disposition_selection(NEW.runtime_configuration_input_id,right(NEW.selection->'observation'->>'retentionPolicyId',36)::uuid);
 IF actual IS DISTINCT FROM NEW.selection OR NEW.source_owner_id IS DISTINCT FROM (actual->>'sourceOwnerId')::uuid
  OR NEW.configuration_digest IS DISTINCT FROM decode(substring(actual->'observation'->'source'->>'configurationDigest' from 8),'hex')
  OR NEW.selection_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(actual),'UTF8'))
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-STALE_SELECTION'; END IF;
 NEW.admitted_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_disposition_row() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_lifecycle_fence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_lifecycle_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
   OR TG_OP='TRUNCATE' OR current_setting('session_replication_role')<>'origin'
 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6004'; END IF;
 -- Producers can already own module, policy, target or occurrence locks.
 -- Never wait in the reverse order. Use the exclusive lock also used by
 -- evidence publication, avoiding shared-to-exclusive upgrade deadlocks.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||
   openpc.current_participant_id()::text,0))
 -- This is a definite statement/transaction abort, not an unknown effect.
 -- Serializable public owners may retry their same operation after rollback.
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_lifecycle_fence() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_retirement(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_retirement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source record; job control.deletion_job;
BEGIN
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>2 THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT module_installation_id,module_configuration_generation_id,configuration_digest,created_at,resource_bindings,selected,
  openpc.runtime_artifact_input_information(runtime_configuration_input_id) info INTO STRICT source
  FROM control.runtime_configuration_input WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND runtime_configuration_input_id=NEW.runtime_configuration_input_id;
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND deletion_job_id=NEW.deletion_job_id AND operation_id=openpc.current_operation_id()
  AND state='EXECUTING' AND revision=0 AND target_database='openpc_control' AND target_data_class='RUNTIME_ARTIFACT'
  AND external_attempt_state='NOT_STARTED';
 IF source.selected OR source.info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb
  OR NEW.module_installation_id IS DISTINCT FROM source.module_installation_id
  OR NEW.module_configuration_generation_id IS DISTINCT FROM source.module_configuration_generation_id
  OR NEW.configuration_digest IS DISTINCT FROM 'sha256:'||encode(source.configuration_digest,'hex')
  OR NEW.configuration_bytes IS DISTINCT FROM (source.info->>'byteLength')::integer
  OR NEW.source_created_at IS DISTINCT FROM source.created_at
  OR NEW.resource_bindings_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(source.resource_bindings),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-SOURCE'; END IF;
 NEW.retirement_digest:=openpc.runtime_artifact_retirement_digest(NEW);
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_retirement() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_retirement_statement(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_retirement_statement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_retirement_statement() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_source_denial(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_source_denial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a control.runtime_artifact_source_disposition; wire jsonb; claims jsonb; original jsonb;
 previous control.runtime_artifact_source_denial;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.lock_runtime_artifact_source_custody();
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.runtime_artifact_source_disposition WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND disposition_id=NEW.disposition_id AND source_owner_id=NEW.source_owner_id
  AND xmin<>pg_current_xact_id()::xid;
 original:=openpc.runtime_artifact_source_admission(a);
 PERFORM openpc.verify_runtime_artifact_source_commit(NEW.source_owner_id,NEW.signed_denial,NEW.verification_nonce,NEW.verification_mac);
 wire:=convert_from(NEW.signed_denial,'UTF8')::jsonb;
 claims:=wire->'claims';
 SELECT * INTO previous FROM control.runtime_artifact_source_denial WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND source_owner_id=NEW.source_owner_id ORDER BY sequence DESC LIMIT 1;
 IF NEW.sequence IS DISTINCT FROM coalesce(previous.sequence,0)+1
  OR NEW.previous_denial_digest IS DISTINCT FROM previous.denial_digest
  OR NEW.denial_digest IS DISTINCT FROM sha256(NEW.signed_denial)
  OR NEW.signed_denial IS DISTINCT FROM openpc.runtime_artifact_source_denial_envelope_bytes(wire)
  OR claims IS DISTINCT FROM jsonb_build_object('version',2,'admission',original,'sequence',NEW.sequence,
    'previous_denial_digest',encode(NEW.previous_denial_digest,'hex'),'recovery','ForwardOnly','custody',claims->'custody')
  OR wire IS DISTINCT FROM jsonb_build_object('purpose','openpc:runtime-artifact-source-denial:v1','claims',claims,
   'claims_digest',encode(sha256(openpc.runtime_artifact_source_denial_claims_bytes(claims)),'hex'),
   'signature_p1363_hex',wire->>'signature_p1363_hex')
  OR coalesce(wire->>'signature_p1363_hex','')!~'^[0-9a-f]{128}$'
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-CUSTODY'; END IF;
 PERFORM openpc.assert_runtime_artifact_source_non_use(a,claims->'custody');
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_runtime_artifact_source_denial() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_source_disposition_immutable(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_source_disposition_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.lock_runtime_artifact_disposition();
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_runtime_artifact_source_disposition_immutable() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_artifact_source_installation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_artifact_source_installation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF NEW.archive_custody IS NOT NULL AND (
  NEW.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR jsonb_typeof(NEW.archive_custody) IS DISTINCT FROM 'object'
  OR NEW.archive_custody IS DISTINCT FROM jsonb_build_object('database_role',NEW.archive_custody->'database_role','stream_id',NEW.archive_custody->'stream_id','keys',NEW.archive_custody->'keys')
  OR jsonb_typeof(NEW.archive_custody->'keys') IS DISTINCT FROM 'object'
  OR coalesce(NEW.archive_custody->>'stream_id','') !~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.archive_custody->>'database_role' AND r.rolcanlogin
   AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication
   AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
   AND shobj_description(r.oid,'pg_authid')::jsonb=jsonb_build_object('installation',jsonb_build_object('participant_id',NEW.participant_id::text,
 'privacy_domain_id',NEW.privacy_domain_id::text,'source_owner_id',NEW.source_owner_id::text,
 'source_file_binding',encode(NEW.source_file_binding,'hex')),'root',NEW.custody_root,'archive',NEW.archive_custody)))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-INSTALLATION-UNAVAILABLE'; END IF;
 IF NEW.custody_root IS NOT NULL AND (
  NEW.custody_root IS DISTINCT FROM jsonb_build_object(
   'generation_id',NEW.custody_root->>'generation_id',
   'journal_binding',NEW.custody_root->>'journal_binding',
   'retained_root_binding',NEW.custody_root->>'retained_root_binding',
   'consumer_profile',NEW.custody_root->>'consumer_profile') ||
   CASE WHEN NEW.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v2'
    THEN jsonb_build_object('database',openpc.runtime_artifact_database_identity()) ELSE '{}'::jsonb END
  OR coalesce(NEW.custody_root->>'consumer_profile','') NOT IN ('openpc:local-runtime-source-consumers:v1','openpc:local-runtime-source-consumers:v2')
  OR coalesce(NEW.custody_root->>'generation_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(NEW.custody_root->>'journal_binding','') !~ '^[0-9a-f]{64}$'
  OR coalesce(NEW.custody_root->>'retained_root_binding','') !~ '^[0-9a-f]{64}$'
  OR NEW.custody_root->>'journal_binding'=NEW.custody_root->>'retained_root_binding')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- Rooted custody is installed with actual first trust. Existing scopes keep
 -- legacy custody; neither this birth pin nor an empty scope proves non-use.
 IF NEW.custody_root IS NOT NULL AND (
  NOT EXISTS(SELECT 1 FROM control.participant p WHERE p.participant_id=NEW.participant_id
    AND p.root_privacy_domain_id=NEW.privacy_domain_id AND p.xmin=pg_current_xact_id()::xid)
  OR NOT EXISTS(SELECT 1 FROM control.privacy_domain p WHERE p.participant_id=NEW.participant_id
    AND p.privacy_domain_id=NEW.privacy_domain_id AND p.xmin=pg_current_xact_id()::xid)
  OR EXISTS(SELECT 1 FROM control.runtime_artifact_source s WHERE s.participant_id=NEW.participant_id
    AND s.privacy_domain_id=NEW.privacy_domain_id))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-GENESIS-REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
  AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb
  AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
  AND NOT pg_has_role(r.oid,'openpc_control_runtime','MEMBER')
  AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER')
  AND NOT pg_has_role(r.oid,'openpc_control_key_governor','MEMBER'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_runtime_artifact_source_installation() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_configuration_input(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_configuration_input() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control', 'openpc'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN PERFORM openpc.assert_runtime_artifact_source_import(NEW); END IF;
 IF TG_OP='DELETE' THEN
  -- The earlier authentic BEFORE DELETE capture must already exist. Only this
  -- transaction's exact governed job can release its original input row.
  IF pg_trigger_depth()<>1 OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
   OR NOT EXISTS(SELECT 1 FROM control.runtime_artifact_retirement r JOIN control.deletion_job j
    USING(participant_id,privacy_domain_id,deletion_job_id) WHERE r.participant_id=OLD.participant_id
     AND r.privacy_domain_id=OLD.privacy_domain_id AND r.runtime_configuration_input_id=OLD.runtime_configuration_input_id
     AND r.configuration_digest='sha256:'||encode(OLD.configuration_digest,'hex')
     AND r.configuration_bytes=octet_length(OLD.configuration_cbor) AND j.operation_id=openpc.current_operation_id()
     AND j.state='EXECUTING' AND j.revision=0)
  THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6004'; END IF;
  RETURN OLD;
 END IF;
 IF (TG_OP='UPDATE' AND
   (to_jsonb(NEW)-'selected') IS DISTINCT FROM (to_jsonb(OLD)-'selected')) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6004';
 END IF;
 -- A new row is new use even when it starts unselected. Matching bytes under
 -- another module installation/generation cannot bypass an original retirement.
 IF (TG_OP='INSERT' OR NEW.selected) AND
  openpc.runtime_artifact_new_use_allowed(NEW.participant_id,NEW.privacy_domain_id,NEW.configuration_digest) IS DISTINCT FROM true
 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007'; END IF;
 IF NEW.selected AND (
   NOT openpc.runtime_configuration_bindings_current(NEW.participant_id,NEW.privacy_domain_id,NEW.resource_bindings)
   OR NOT EXISTS (
     SELECT 1 FROM control.module_configuration_generation c
       JOIN control.module_installation i ON i.module_installation_id=c.module_installation_id
       JOIN control.module_version v ON v.module_version_id=i.module_version_id
      WHERE c.generation_id=NEW.module_configuration_generation_id
        AND c.module_installation_id=NEW.module_installation_id
        AND c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
        AND i.participant_id=c.participant_id AND i.privacy_domain_id=c.privacy_domain_id
        AND c.active AND i.state='ENABLED' AND i.lifecycle_operation_id IS NOT NULL
        AND v.module_id='pc.config.assets'
   )) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_configuration_input() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_denied_predecessor(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_denied_predecessor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-IMMUTABLE'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_user<>session_user OR current_setting('role')<>'none'
  OR NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR pg_has_role(current_user,'openpc_control_owner','USAGE')
  OR current_setting('row_security')<>'on' OR current_setting('session_replication_role')<>'origin'
  OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
  OR NOT EXISTS(SELECT 1 FROM control.runtime_expired_activation_denial e
   LEFT JOIN control.runtime_expired_denial_handover h ON h.configuration_work_id=e.configuration_work_id
    AND h.participant_id=e.participant_id AND h.privacy_domain_id=e.privacy_domain_id AND h.runtime_target_id=e.runtime_target_id
   JOIN control.configuration_work w ON w.configuration_work_id=e.configuration_work_id AND w.participant_id=e.participant_id
    AND w.privacy_domain_id=e.privacy_domain_id AND w.runtime_target_id=e.runtime_target_id AND w.execution_attempt_id=e.execution_attempt_id
   JOIN control.runtime_activation_observation o ON o.configuration_work_id=w.configuration_work_id AND o.participant_id=w.participant_id
    AND o.privacy_domain_id=w.privacy_domain_id AND o.runtime_target_id=w.runtime_target_id AND o.execution_attempt_id=w.execution_attempt_id
   JOIN control.runtime_configuration_generation g ON g.runtime_configuration_generation_id=w.runtime_configuration_generation_id
    AND g.participant_id=w.participant_id AND g.privacy_domain_id=w.privacy_domain_id
   JOIN control.runtime_target t ON t.participant_id=w.participant_id AND t.privacy_domain_id=w.privacy_domain_id
    AND t.runtime_target_id=w.runtime_target_id
   JOIN control.runtime_target_disposition_admission a ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
    AND a.runtime_target_id=e.runtime_target_id AND a.revision=coalesce(h.admission_revision,e.admission_revision)
   JOIN control.runtime_target_disposition_delivery d ON d.participant_id=a.participant_id AND d.privacy_domain_id=a.privacy_domain_id
    AND d.runtime_target_id=a.runtime_target_id AND d.revision=a.revision
   JOIN control.runtime_target_disposition_acknowledgement k ON k.participant_id=d.participant_id AND k.privacy_domain_id=d.privacy_domain_id
    AND k.runtime_target_id=d.runtime_target_id AND k.delivery_digest=d.delivery_digest
   JOIN control.outbox_event event ON event.event_id=w.result_event_id AND event.participant_id=w.participant_id
    AND event.privacy_domain_id=w.privacy_domain_id AND event.aggregate_id=w.runtime_target_id
   JOIN control.mutation_evidence approval ON approval.participant_id=w.participant_id
    AND approval.privacy_domain_id=w.privacy_domain_id AND approval.operation_id=w.operation_id
   WHERE e.configuration_work_id=NEW.configuration_work_id AND e.participant_id=NEW.participant_id
    AND e.privacy_domain_id=NEW.privacy_domain_id AND e.runtime_target_id=NEW.runtime_target_id
    AND e.proof->'intent'->'custody'->>'databaseRole'=current_user::text
    AND e.capsule_digest=NEW.capsule_digest AND e.capsule_generation=NEW.capsule_generation
    AND w.predecessor_digest=NEW.last_confirmed_capsule_digest AND w.xds_version_digest=NEW.xds_version_digest
    AND w.state='FAILED' AND w.xmin=pg_current_xact_id()::xid AND w.completed_at IS NOT NULL
    AND w.reconcile_after IS NULL AND w.lease_owner IS NULL AND w.lease_until IS NULL
    AND w.result_event_id=NEW.result_event_id AND g.state='FAILED' AND g.activated_at IS NULL
    AND t.state='FAILED' AND t.active_generation_digest=NEW.last_confirmed_capsule_digest AND t.desired_generation_digest IS NULL
    AND w.result_receipt=jsonb_build_object('outcome','EXPIRED_OBSERVED_DENIED','errorCode','PC-RUNTIME-3002',
     'observedEffect',true,'runtimeNewUse','DENIED','capsuleDigest',e.capsule_digest,
     'originalReceiptDigest',o.activation_receipt_digest,'denialDeliveryDigest',d.delivery_digest,
     'denialAcknowledgementDigest','sha256:'||encode(sha256(k.signed_acknowledgement),'hex'),
     'terminal',true,'resourceId',w.runtime_target_id::text,'workKind','RUNTIME_ACTIVATION')
    AND w.result_receipt_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(w.result_receipt),'UTF8')),'hex')
    AND event.event_type='runtime-target.activation-expired-denied.v1' AND event.aggregate_type='runtime-targets'
    AND event.payload_cbor=convert_to(openpc.signing_canonical_json(w.result_receipt),'UTF8')
    AND event.payload_digest=sha256(event.payload_cbor) AND event.cose_sign1=approval.cose_sign1
    AND octet_length(approval.cose_sign1)>0
    AND a.revision=NEW.denial_revision AND a.admission_digest=coalesce(h.admission_digest,e.admission_digest) AND a.binding->>'action'='Withdraw'
    AND a.binding->'source'->>'original_work_id'=w.configuration_work_id::text
    AND a.binding->'source'->>'capsule_digest'=substring(e.capsule_digest from 8)
    AND ((h.configuration_work_id IS NULL AND a.binding->'cause'=jsonb_build_object('kind','Activation','work_id',w.configuration_work_id::text,
     'operation_id',w.operation_id::text,'execution_attempt_id',w.execution_attempt_id::text))
     OR (h.configuration_work_id IS NOT NULL AND h.abandoned_revision=e.admission_revision
      AND h.abandoned_admission_digest=e.admission_digest AND h.admission_revision=h.abandoned_revision+1
      AND (a.binding->'cause'->>'kind'='ExpiredObservedDenialHandover'
       OR (a.binding->'cause'->>'kind'='ExpiredObservedCredentialDenialHandover'
        AND h.proof->'intent'->>'purpose'='EXPIRED_OBSERVED_CREDENTIAL_DENIAL_HANDOVER_V1'
        AND a.binding->'target'=h.proof->'target'
        AND a.binding->'cause'->'abandoned_target'=e.proof->'target'
        AND a.binding->'cause'->>'credential_rotation_operation_id'=h.proof->'intent'->'credentialTransition'->>'rotationOperationId'))
      AND a.binding->'cause'->>'abandoned_admission_digest'=substring(e.admission_digest from 8)
      AND a.binding->'cause'->>'original_receipt_wire_digest'=e.proof->>'receiptWireDigest'))
    AND a.revision=(SELECT max(h.revision) FROM control.runtime_target_disposition_admission h
     WHERE h.participant_id=e.participant_id AND h.privacy_domain_id=e.privacy_domain_id AND h.runtime_target_id=e.runtime_target_id)
    AND d.delivery_digest=NEW.delivery_digest AND k.claims->>'installed_state'='NewUseDenied'
    AND NEW.acknowledgement_digest='sha256:'||encode(sha256(k.signed_acknowledgement),'hex'))
 THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-ORIGINAL'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_denied_predecessor() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_generation_retry(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_generation_retry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior control.runtime_configuration_generation; work control.configuration_work;
 target control.runtime_target; payload bytea;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.runtime_configuration_generation g
  WHERE g.runtime_target_id=NEW.runtime_target_id AND g.generation_digest=NEW.generation_digest
   AND g.predecessor_digest IS NOT DISTINCT FROM NEW.predecessor_digest AND g.state='FAILED')
 THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR openpc.current_action_intent_id() NOT IN
    ('ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1','ACT-POLICY_ACTIVATE_RELEASE-V1')
  OR current_setting('transaction_isolation')<>'serializable'
  OR NEW.state<>'ACTIVATING' OR NEW.revision<>1 OR NEW.activated_at IS NOT NULL
  OR NEW.cigl_profile_selection IS NOT NULL
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 -- Reentrant with the shared BEFORE STATEMENT reference fence. Never reverse-wait.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='PC-DATA-6007'; END IF;
 SELECT * INTO STRICT target FROM control.runtime_target t
  WHERE t.participant_id=NEW.participant_id AND t.privacy_domain_id=NEW.privacy_domain_id
   AND t.runtime_target_id=NEW.runtime_target_id FOR UPDATE NOWAIT;
 -- Public activation still checks current discovery and expected revision;
 -- this guard only proves the old attempt cannot have dispatched an effect.
 IF target.state<>'FAILED' OR openpc.runtime_installed_predecessor(target.runtime_target_id) IS DISTINCT FROM NEW.predecessor_digest
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 IF openpc.current_action_intent_id()='ACT-POLICY_ACTIVATE_RELEASE-V1' AND
  (NEW.policy_generation_digest IS NULL OR NOT EXISTS (
    SELECT 1 FROM control.policy_activation_occurrence occurrence
    JOIN control.policy_activation_occurrence_target cohort
      ON cohort.activation_occurrence_id=occurrence.activation_occurrence_id
     AND cohort.participant_id=occurrence.participant_id
     AND cohort.privacy_domain_id=occurrence.privacy_domain_id
    WHERE occurrence.participant_id=NEW.participant_id
      AND occurrence.privacy_domain_id=NEW.privacy_domain_id
      AND occurrence.state='REQUESTED'
      AND cohort.runtime_target_id=NEW.runtime_target_id
      AND cohort.phase='FORWARD' AND cohort.state='REQUESTED'
      AND cohort.configuration_work_id IS NULL
      AND cohort.expected_target_revision=target.revision
      AND cohort.expected_predecessor_digest IS NOT DISTINCT FROM target.active_generation_digest
      AND NEW.policy_generation_digest='sha256:'||encode(occurrence.target_generation_digest,'hex')
  )) THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 FOR prior IN SELECT g.* FROM control.runtime_configuration_generation g
  WHERE g.runtime_target_id=NEW.runtime_target_id AND g.generation_digest=NEW.generation_digest
   AND g.predecessor_digest IS NOT DISTINCT FROM NEW.predecessor_digest
  ORDER BY g.runtime_configuration_generation_id FOR SHARE NOWAIT
 LOOP
  IF prior.participant_id<>NEW.participant_id OR prior.privacy_domain_id<>NEW.privacy_domain_id
   OR prior.state<>'FAILED' OR prior.activated_at IS NOT NULL OR prior.cigl_profile_selection IS NOT NULL
  THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
  SELECT * INTO STRICT work FROM control.configuration_work w
   WHERE w.participant_id=prior.participant_id AND w.privacy_domain_id=prior.privacy_domain_id
    AND w.runtime_configuration_generation_id=prior.runtime_configuration_generation_id FOR SHARE NOWAIT;
  payload:=openpc.runtime_generation_retry_failure_payload(prior,work);
  -- This is the existing configuration-result owner's canonical failure payload
  -- bound to its original committed authorization signature, not a new signature
  -- over a fabricated result or a new permission to execute.
  IF (NOT EXISTS(SELECT 1 FROM control.outbox_event e JOIN control.mutation_evidence a
    ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
     AND a.operation_id=work.operation_id AND a.aggregate_id=work.resource_id
     AND a.action_intent_id='ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'
     AND a.catalog_operation_id='CFG-OP-UPDATE-RUNTIME-TARGET'
    JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
     AND i.operation_id=a.operation_id AND i.input_digest=a.candidate_digest
     AND i.terminal_state='COMMITTED' AND i.result_payload->>'state'='FAILED'
     AND i.result_payload->>'truthState'='FAILED'
    WHERE e.participant_id=work.participant_id AND e.privacy_domain_id=work.privacy_domain_id
     AND e.event_id=work.result_event_id AND e.aggregate_id=work.resource_id
     AND e.aggregate_type='runtime-targets' AND e.event_type='runtime-target.activation-failed.v1'
     AND e.payload_cbor=payload AND e.payload_digest=sha256(payload)
     AND e.cose_sign1=a.cose_sign1 AND octet_length(a.cose_sign1)>0
     AND a.evidence_digest=sha256(a.evidence_cbor))
   AND NOT EXISTS(SELECT 1 FROM control.outbox_event e
    JOIN control.idempotency_record i
      ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
     AND i.operation_id=work.operation_id AND i.terminal_state='COMMITTED'
     AND i.result_payload->>'state'='FAILED' AND i.result_payload->>'truthState'='FAILED'
    JOIN control.policy_activation_occurrence_target cohort
      ON cohort.configuration_work_id=work.configuration_work_id
     AND cohort.runtime_configuration_generation_id=prior.runtime_configuration_generation_id
     AND cohort.participant_id=work.participant_id AND cohort.privacy_domain_id=work.privacy_domain_id
     AND cohort.phase='FORWARD' AND cohort.state='FAILED'
    JOIN control.policy_activation_occurrence occurrence
      ON occurrence.activation_occurrence_id=cohort.activation_occurrence_id
     AND occurrence.participant_id=cohort.participant_id
     AND occurrence.privacy_domain_id=cohort.privacy_domain_id
     AND occurrence.state='FAILED'
    JOIN control.policy_activation activation
      ON activation.policy_activation_id=occurrence.activation_occurrence_id
     AND activation.participant_id=occurrence.participant_id
     AND activation.privacy_domain_id=occurrence.privacy_domain_id
     AND activation.state='FAILED_FENCED' AND activation.activated_at IS NULL
     AND activation.webauthn_assertion_binding_digest IS NOT NULL
    WHERE openpc.current_action_intent_id()='ACT-POLICY_ACTIVATE_RELEASE-V1'
      AND e.participant_id=work.participant_id AND e.privacy_domain_id=work.privacy_domain_id
      AND e.event_id=work.result_event_id AND e.aggregate_id=work.resource_id
      AND e.aggregate_type='runtime-targets' AND e.event_type='runtime-target.activation-failed.v1'
      AND e.payload_cbor=payload AND e.payload_digest=sha256(payload)
      AND octet_length(e.cose_sign1)>0))
   OR EXISTS(SELECT 1 FROM control.runtime_activation_observation o
    WHERE o.runtime_configuration_generation_id=prior.runtime_configuration_generation_id
     OR o.configuration_work_id=work.configuration_work_id)
   OR EXISTS(SELECT 1 FROM control.policy_activation_occurrence_target o
    LEFT JOIN control.policy_activation_occurrence occurrence
      ON occurrence.activation_occurrence_id=o.activation_occurrence_id
     AND occurrence.participant_id=o.participant_id
     AND occurrence.privacy_domain_id=o.privacy_domain_id
    WHERE (o.runtime_configuration_generation_id=prior.runtime_configuration_generation_id
       OR o.configuration_work_id=work.configuration_work_id)
      AND (o.phase<>'FORWARD' OR o.state<>'FAILED' OR occurrence.state IS DISTINCT FROM 'FAILED'))
   OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
    WHERE a.runtime_target_id=prior.runtime_target_id AND (
     a.binding->'source'->>'original_work_id'=work.configuration_work_id::text
     OR a.binding->'source'->>'runtime_configuration_generation_id'=prior.runtime_configuration_generation_id::text
     OR (a.binding->'cause'->>'work_id'=work.configuration_work_id::text AND (
       -- The failed successor did not run. Its acknowledged withdrawal denied
       -- the predecessor, not this content generation. A fresh governed attempt
       -- keeps that denial and must issue/ACK its own handoff and activation.
       a.participant_id=prior.participant_id AND a.privacy_domain_id=prior.privacy_domain_id
       AND a.binding->>'action'='Withdraw' AND a.activation_proof IS NULL AND a.restoration_proof IS NULL
       AND a.binding->'cause'=jsonb_build_object('kind','Activation',
         'work_id',work.configuration_work_id::text,'operation_id',work.operation_id::text,'execution_attempt_id',NULL)
       AND a.binding->'source'->>'capsule_digest'=substring(NEW.predecessor_digest from 8)
       AND a.revision=(SELECT max(head.revision) FROM control.runtime_target_disposition_admission head
         WHERE head.participant_id=a.participant_id AND head.privacy_domain_id=a.privacy_domain_id
          AND head.runtime_target_id=a.runtime_target_id)
       AND EXISTS(SELECT 1 FROM control.runtime_activation_observation original
         WHERE original.participant_id=a.participant_id AND original.privacy_domain_id=a.privacy_domain_id
          AND original.runtime_target_id=a.runtime_target_id AND original.capsule_digest=NEW.predecessor_digest
          AND original.configuration_work_id::text=a.binding->'source'->>'original_work_id'
          AND original.runtime_configuration_generation_id::text=a.binding->'source'->>'runtime_configuration_generation_id'
          AND original.configuration_work_id<>work.configuration_work_id
          AND original.runtime_configuration_generation_id<>prior.runtime_configuration_generation_id)
       AND (openpc.runtime_unsigned_withdrawal_recoverable(a.runtime_target_id,a.revision::bigint,a.admission_digest)
        OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery delivery
         JOIN control.runtime_target_disposition_acknowledgement acknowledgement
          ON acknowledgement.participant_id=delivery.participant_id AND acknowledgement.privacy_domain_id=delivery.privacy_domain_id
           AND acknowledgement.runtime_target_id=delivery.runtime_target_id AND acknowledgement.delivery_digest=delivery.delivery_digest
         WHERE delivery.participant_id=a.participant_id AND delivery.privacy_domain_id=a.privacy_domain_id
          AND delivery.runtime_target_id=a.runtime_target_id AND delivery.revision=a.revision
          AND acknowledgement.claims->>'installed_state'='NewUseDenied'))
     ) IS NOT TRUE)))
  THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 END LOOP;
 RETURN NEW;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='PC-DATA-6007';
END $$;


ALTER FUNCTION openpc.guard_runtime_generation_retry() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_input_reference_fence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_input_reference_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6001';
 END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||
   openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0)) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007';
 END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||
   openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0)) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PC-DATA-6007';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_runtime_input_reference_fence() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_target_connection(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_target_connection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','MEMBER') OR
  NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR
  NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() OR
  (TG_OP='UPDATE' AND (NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id OR NEW.runtime_target_id<>OLD.runtime_target_id))
 THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-OWNER-INVALID'; END IF;
 IF NEW.connected AND (NEW.observed_at>clock_timestamp() OR NEW.valid_until<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM control.runtime_target t JOIN control.credential c
  ON c.participant_id=t.participant_id AND c.credential_id=NEW.credential_id
  JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
  WHERE t.runtime_target_id=NEW.runtime_target_id AND t.participant_id=NEW.participant_id
   AND t.privacy_domain_id=NEW.privacy_domain_id AND t.requires_authenticated_discovery
   AND c.kind='WORKLOAD_MTLS' AND c.state='ACTIVE' AND c.credential_epoch=NEW.credential_epoch
   AND c.subject='urn:openpc:participant:'||t.participant_id::text||':workload:'||t.runtime_target_id::text
   AND c.audience='urn:openpc:workload:'||t.runtime_target_id::text
   AND c.certificate_der IS NOT NULL AND sha256(c.certificate_der)=c.secret_fingerprint
   AND c.secret_fingerprint=decode(substring(NEW.certificate_digest from 8),'hex')
   AND c.valid_from<=NEW.observed_at AND c.valid_until>=NEW.valid_until
   AND p.kind='WORKLOAD' AND p.state='ACTIVE' AND p.authority_epoch=NEW.principal_epoch))
 THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-CREDENTIAL-INVALID'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_target_connection() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_target_disposition_immutable(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_target_disposition_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 RAISE EXCEPTION 'TARGET-DISPOSITION-IMMUTABLE';
END $$;


ALTER FUNCTION openpc.guard_runtime_target_disposition_immutable() OWNER TO openpc_control_owner;

--
-- Name: guard_runtime_target_profile_binding(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_runtime_target_profile_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE expected text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-DATA-6004-RUNTIME-PROFILE-IMMUTABLE'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-RUNTIME_TARGET_PROFILES_CREATE_RESOURCE-V1'
   OR NEW.participant_id<>openpc.current_participant_id()
   OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
   OR NEW.publication_operation_id<>current_setting('openpc.operation_id')::uuid
   OR NOT pg_has_role(current_user,'openpc_control_runtime','MEMBER') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-RUNTIME-PROFILE-OWNER'; END IF;
 -- Snapshot publication takes UPDATE on this same root before reading mappings.
 PERFORM 1 FROM control.participant WHERE participant_id=NEW.participant_id FOR SHARE;
 PERFORM 1 FROM control.runtime_target WHERE runtime_target_id=NEW.runtime_target_id
  AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND revision=NEW.target_revision AND state IN ('OFFLINE','DISCOVERED')
  AND desired_generation_digest IS NULL AND active_generation_digest IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-PROFILE-TARGET'; END IF;
 expected:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'purpose','openpc.identity.runtime-target-profile-binding.v1',
   'participant_id',NEW.participant_id::text,'privacy_domain_id',NEW.privacy_domain_id::text,
   'runtime_target_id',NEW.runtime_target_id::text,'target_profile_id',NEW.target_profile_id)),'UTF8')),'hex');
 IF expected<>NEW.binding_digest THEN RAISE EXCEPTION 'PC-DATA-6004-RUNTIME-PROFILE-DIGEST'; END IF;
 NEW.created_at:=clock_timestamp();
 NEW.updated_at:=NEW.created_at;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_runtime_target_profile_binding() OWNER TO openpc_control_owner;

--
-- Name: guard_session_duration_profile(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_session_duration_profile() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND
  (NEW.participant_id,NEW.principal_id,NEW.refresh_family_id,NEW.issued_at,NEW.absolute_expires_at,
   NEW.duration_profile,NEW.idle_timeout_ms,NEW.absolute_timeout_ms) IS DISTINCT FROM
  (OLD.participant_id,OLD.principal_id,OLD.refresh_family_id,OLD.issued_at,OLD.absolute_expires_at,
   OLD.duration_profile,OLD.idle_timeout_ms,OLD.absolute_timeout_ms) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SESSION-DURATION';
 END IF;
 IF TG_OP='INSERT' AND NEW.duration_profile<>'C17' AND
  (current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1' OR
   (NEW.duration_profile='LOCAL_QA_10X' AND
    current_setting('openpc.local_qa_duration_profile',true) IS DISTINCT FROM 'LOCAL_QA_10X')) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SESSION-DURATION';
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('openpc-session-duration-family:'||NEW.participant_id::text||':'||NEW.refresh_family_id::text,0));
  IF EXISTS(SELECT 1 FROM control.session s
    WHERE s.participant_id=NEW.participant_id AND s.refresh_family_id=NEW.refresh_family_id
      AND (s.principal_id,s.issued_at,s.absolute_expires_at,s.duration_profile,s.idle_timeout_ms,s.absolute_timeout_ms)
       IS DISTINCT FROM
          (NEW.principal_id,NEW.issued_at,NEW.absolute_expires_at,NEW.duration_profile,NEW.idle_timeout_ms,NEW.absolute_timeout_ms)) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SESSION-DURATION';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_session_duration_profile() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_attestation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_attestation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rotation control.signing_key_rotation%ROWTYPE; command control.signing_rotation_command%ROWTYPE;
 attempt control.receipt_signing_attempt%ROWTYPE; provider control.signing_provider_attempt%ROWTYPE;
 payload jsonb; after_state jsonb; prospective control.signing_key_rotation%ROWTYPE; attester jsonb; expected bytea; expected_authorization jsonb; effects jsonb;
BEGIN
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.from_revision;
 SELECT * INTO STRICT command FROM control.signing_rotation_command WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND operation_id=NEW.operation_id
  AND state IN ('ACCEPTED','WRITE_AMBIGUITY');
 SELECT * INTO STRICT attempt FROM control.receipt_signing_attempt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id AND attempt_id=NEW.attempt_id
  AND reservation_kind='LIFECYCLE_DURABLE' AND schema_version=2;
 SELECT * INTO STRICT provider FROM control.signing_provider_attempt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id AND attempt_id=NEW.attempt_id AND state='READY';
 IF command.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND EXISTS(
  SELECT 1 FROM control.signing_rotation_command recovery WHERE recovery.participant_id=NEW.participant_id
   AND recovery.privacy_domain_id=NEW.privacy_domain_id AND recovery.original_operation_id=NEW.operation_id
   AND recovery.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND recovery.state='ACCEPTED')
 THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-IN-PROGRESS'; END IF;
 effects:=openpc.signing_transition_effects(command.action_intent_id,rotation.state,NEW.to_state);
 IF effects IS NULL OR (effects->>'resumeFrom' IS NOT NULL AND effects->>'resumeFrom' IS DISTINCT FROM rotation.recovery_from_state)
 THEN RAISE EXCEPTION 'DATA-6022-SIGNING-TRANSITION-MATRIX'; END IF;
 payload:=openpc.business_cbor(NEW.receipt_cbor);
 IF NEW.continuation_assertion_id IS NOT NULL THEN
  PERFORM openpc.check_signing_continuation_snapshot(NEW.authority_snapshot,NEW.participant_id,NEW.privacy_domain_id,
   NEW.operation_id,NEW.attempt_id,(payload->>'23')::numeric,false);
  SELECT jsonb_agg(proof ORDER BY proof->>'1') INTO expected_authorization FROM control.signing_continuation c
   JOIN control.mutation_evidence e ON e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND e.operation_id=c.operation_id AND e.mutation_evidence_id=command.authorization_evidence_id
   CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(
    jsonb_build_object('0',2,'1',c.assertion_id::text,'2',openpc.business_bytes(c.assertion_digest)),
    jsonb_build_object('0',2,'1',e.mutation_evidence_id::text,'2',openpc.business_bytes(e.evidence_digest)))) proof
   WHERE c.assertion_id=NEW.continuation_assertion_id;
  IF payload->'20' IS DISTINCT FROM expected_authorization OR
   convert_from(NEW.authority_snapshot,'UTF8')::jsonb->>'continuationAssertionId' IS DISTINCT FROM NEW.continuation_assertion_id::text
  THEN RAISE EXCEPTION 'DATA-6021-ATTESTATION-CONTINUATION'; END IF;
 END IF;
 after_state:=openpc.business_cbor(NEW.after_state_preimage);
 IF NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR command.action_intent_id IS DISTINCT FROM openpc.current_action_intent_id()
  OR NEW.receipt_cbor<>attempt.payload_cbor OR NEW.signer_id<>attempt.signer_id OR NEW.signer_trust_digest<>attempt.signer_trust_digest
  OR NEW.selection_version<>attempt.selection_version OR
    (NEW.continuation_assertion_id IS NULL AND (convert_from(NEW.authority_snapshot,'UTF8')::jsonb->'authorities') IS DISTINCT FROM
    (convert_from(command.authorization_snapshot,'UTF8')::jsonb->'authorities'))
  OR payload->'14' IS DISTINCT FROM openpc.business_bytes(sha256(NEW.authority_snapshot))
  OR payload->'18'->'2' IS DISTINCT FROM openpc.business_bytes(sha256(NEW.before_state_preimage))
  OR payload->'19'->'2' IS DISTINCT FROM openpc.business_bytes(sha256(NEW.after_state_preimage))
  OR payload->'19'->'1' IS DISTINCT FROM to_jsonb(NEW.from_revision+1)
  OR provider.from_revision<>NEW.from_revision OR provider.from_state<>rotation.state OR provider.to_state<>NEW.to_state
  OR provider.rotation_id<>NEW.rotation_id OR provider.request->>'method' IS DISTINCT FROM 'SIGN_RECEIPT'
  OR provider.request->>'payloadHex' IS DISTINCT FROM encode(NEW.receipt_cbor,'hex')
  OR provider.request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR provider.request->>'operationId' IS DISTINCT FROM NEW.operation_id::text
  OR (effects->>'eventType' IS NOT NULL) IS DISTINCT FROM (NEW.event_id IS NOT NULL)
  OR (NEW.to_state<>command.to_state AND NEW.to_state NOT IN ('FAILED','RECOVERING'))
 THEN RAISE EXCEPTION 'DATA-6021-ATTESTATION-EXACT-ATTEMPT'; END IF;
 IF EXISTS(SELECT 1 FROM control.signing_rotation_attestation a JOIN control.signing_provider_attempt p USING(attempt_id)
  WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
   AND a.operation_id=NEW.operation_id AND p.state NOT IN ('REJECTED','SUPERSEDED'))
 THEN RAISE EXCEPTION 'DATA-6021-ATTESTATION-ALREADY-PENDING'; END IF;
 IF NEW.receipt_ordinal<>1+coalesce((SELECT max(receipt_ordinal) FROM control.signing_rotation_history
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id),0)
 THEN RAISE EXCEPTION 'DATA-6021-ATTESTATION-ORDINAL'; END IF;
 prospective:=rotation;
 prospective.state:=NEW.to_state;
 prospective.revision:=NEW.from_revision+1;
 IF (effects->>'prepare')::boolean THEN
  SELECT observation->'descriptor'->>'fingerprint' INTO STRICT prospective.new_signer_id
  FROM control.signing_provider_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
   AND operation_id=NEW.operation_id AND request->>'method'='PREPARE' AND state='OBSERVED' AND observation->>'outcome'='SUCCEEDED';
 END IF;
 IF (effects->>'cutover')::boolean
 THEN prospective.cutover_at_ns:=(payload->>'23')::bigint; END IF;
 IF effects->>'kind' IN ('RECOVERY','FORWARD_RECOVERY') THEN
  IF command.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND command.authorization_generation_id IS NOT NULL THEN
   SELECT resume_state,resume_revision INTO STRICT prospective.recovery_from_state,prospective.recovery_from_revision
    FROM control.signing_authorization_generation WHERE generation_id=command.authorization_generation_id AND state='STAGED';
  ELSE
   prospective.recovery_from_state:=coalesce(rotation.recovery_from_state,rotation.state);
   prospective.recovery_from_revision:=coalesce(rotation.recovery_from_revision,rotation.revision);
  END IF;
 ELSE prospective.recovery_from_state:=NULL; prospective.recovery_from_revision:=NULL; END IF;
 attester:=jsonb_build_object('signerId',attempt.signer_id,'keyEpoch',attempt.key_epoch,'trustDigest',encode(attempt.signer_trust_digest,'hex'),
  'selectionVersion',attempt.selection_version,'admissionVersion',attempt.admission_version,'fenceGeneration',attempt.fence_generation);
 expected:=openpc.rotation_history_preimage(prospective,rotation.state,NEW.operation_id,NEW.event_id,NULL,NEW.evidence_record_id,attester,NEW.receipt_ordinal);
 IF expected<>NEW.history_preimage OR after_state->8->'2' IS DISTINCT FROM openpc.business_bytes(sha256(expected))
 THEN RAISE EXCEPTION 'DATA-6021-ATTESTATION-HISTORY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_attestation() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_authority_hold(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_authority_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'CLEARED' OR NEW.cleared_by_operation_id IS DISTINCT FROM openpc.current_operation_id()
   OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1'
   OR (to_jsonb(NEW)-ARRAY['state','cleared_by_operation_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','cleared_by_operation_id'])
   OR NOT EXISTS(SELECT 1 FROM control.signing_authorization_generation g JOIN control.signing_rotation_history h
    ON h.participant_id=g.participant_id AND h.privacy_domain_id=g.privacy_domain_id AND h.operation_id=g.consumed_operation_id
     AND h.revision=g.result_revision WHERE g.participant_id=NEW.participant_id AND g.privacy_domain_id=NEW.privacy_domain_id
      AND g.hold_id=NEW.hold_id AND g.state='CONSUMED' AND g.consumed_operation_id=NEW.cleared_by_operation_id
      AND h.receipt_id IS NOT NULL AND h.event_id IS NULL)
  THEN RAISE EXCEPTION 'DATA-6021-HOLD-GOVERNED-RECOVERY-REQUIRED'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-AUTHORITY-HOLD'; END IF;
 IF NEW.state<>'ACTIVE' OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT EXISTS(SELECT 1 FROM control.signing_continuation c WHERE c.participant_id=NEW.participant_id
   AND c.privacy_domain_id=NEW.privacy_domain_id AND c.operation_id=NEW.operation_id AND c.assertion_id=NEW.continuation_assertion_id
   AND c.state='CONSUMED' AND convert_from(c.context_preimage,'UTF8')::jsonb->>'currentAuthorityStatus'='CHANGED'
   AND convert_from(c.context_preimage,'UTF8')::jsonb->>'rotationId'=NEW.rotation_id::text)
 THEN RAISE EXCEPTION 'DATA-6021-AUTHORITY-HOLD-OWNER'; END IF;
 NEW.created_at_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_authority_hold() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROTATION-COMMAND'; END IF;
 IF TG_OP='UPDATE' AND NEW.state='WRITE_AMBIGUITY' AND NOT EXISTS(
  SELECT 1 FROM control.signing_rotation_observation o WHERE o.participant_id=NEW.participant_id
   AND o.privacy_domain_id=NEW.privacy_domain_id AND o.operation_id=NEW.operation_id AND o.kind='UNRESOLVED')
 THEN RAISE EXCEPTION 'DATA-6021-AMBIGUITY-OBSERVATION-REQUIRED'; END IF;
 IF pg_has_role(current_user,'openpc_control_worker','MEMBER') AND
  (TG_OP<>'UPDATE' OR OLD.state<>'ACCEPTED' OR (NEW.state<>'WRITE_AMBIGUITY' AND NOT (NEW.state='FAILED' AND NEW.result_kind='AUTHORITY_CHANGED_BEFORE_DISPATCH')))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-COMMAND-OWNER'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACCEPTED' THEN RAISE EXCEPTION 'DATA-6021-COMMAND-INITIAL'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND NEW.state IN ('SUCCEEDED','FAILED') AND EXISTS(
  SELECT 1 FROM control.signing_rotation_command recovery WHERE recovery.participant_id=NEW.participant_id
   AND recovery.privacy_domain_id=NEW.privacy_domain_id AND recovery.original_operation_id=NEW.operation_id
   AND recovery.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND recovery.state='ACCEPTED')
 THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-IN-PROGRESS'; END IF;
 IF OLD.recovery_observation_digest IS NOT NULL AND NEW.recovery_observation_digest IS DISTINCT FROM OLD.recovery_observation_digest
 THEN RAISE EXCEPTION 'DATA-6020-RECOVERY-OBSERVATION'; END IF;
 IF NEW.recovery_observation_digest IS NOT NULL AND NOT EXISTS(SELECT 1 FROM control.signing_rotation_observation o
  WHERE o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id
   AND o.operation_id=NEW.original_operation_id AND o.attempt_id=NEW.recovery_attempt_id
   AND o.observation_digest=NEW.recovery_observation_digest AND o.kind IN ('NOT_FOUND','PROVIDER_RESULT'))
 THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-OBSERVATION'; END IF;
 IF NEW.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND NEW.state IN ('SUCCEEDED','FAILED') THEN
  IF NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR
   (NEW.state='SUCCEEDED' AND (NEW.result_kind NOT IN ('NO_NEW_OBSERVATION','NEW_OBSERVATION','AUTHORITY_RENEWED','FORWARD_RECOVERY') OR NEW.result_kind IS NULL)) OR
   (NEW.state='FAILED' AND (NEW.result_kind NOT IN ('LOOKUP_UNAVAILABLE','SIGNATURE_UNAVAILABLE') OR NEW.result_kind IS NULL)) OR
   (NEW.result_kind='NO_NEW_OBSERVATION' AND (NEW.recovery_observation_digest IS DISTINCT FROM NEW.prior_observation_digest OR NEW.result_revision<>NEW.from_revision)) OR
   (NEW.result_kind='NEW_OBSERVATION' AND (NEW.recovery_observation_digest IS NULL OR NEW.recovery_observation_digest=NEW.prior_observation_digest
    OR NEW.result_revision<>NEW.from_revision+1 OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_history h
      WHERE h.participant_id=NEW.participant_id AND h.privacy_domain_id=NEW.privacy_domain_id
       AND h.operation_id=NEW.operation_id AND h.revision=NEW.result_revision AND h.state='RECOVERING' AND h.receipt_id IS NOT NULL))) OR
   (NEW.result_kind IN ('LOOKUP_UNAVAILABLE','SIGNATURE_UNAVAILABLE','NO_NEW_OBSERVATION') AND EXISTS(
    SELECT 1 FROM control.signing_rotation_history h WHERE h.participant_id=NEW.participant_id AND h.privacy_domain_id=NEW.privacy_domain_id AND h.operation_id=NEW.operation_id))
  THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-RESULT'; END IF;
  IF NEW.result_kind IN ('AUTHORITY_RENEWED','FORWARD_RECOVERY') AND NOT EXISTS(SELECT 1 FROM control.signing_authorization_generation g
   JOIN control.signing_rotation_history h ON h.participant_id=g.participant_id AND h.privacy_domain_id=g.privacy_domain_id
    AND h.operation_id=g.consumed_operation_id AND h.revision=g.result_revision
   WHERE g.generation_id=NEW.authorization_generation_id AND g.state='CONSUMED' AND g.consumed_operation_id=NEW.operation_id
    AND h.receipt_id IS NOT NULL AND h.event_id IS NULL AND NEW.result_revision=NEW.from_revision+1
    AND ((NEW.result_kind='AUTHORITY_RENEWED' AND h.state=h.prior_state) OR (NEW.result_kind='FORWARD_RECOVERY' AND h.state='RECOVERING')))
  THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-GENERATION-RESULT'; END IF;
 END IF;
 IF NEW.result_kind IN ('AUTHORITY_CHANGED_BEFORE_DISPATCH','NO_EFFECT_RETRYABLE') AND (NEW.state<>'FAILED'
  OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_operation_evidence e
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=NEW.operation_id AND e.kind=NEW.result_kind AND NEW.result_revision=(convert_from(e.preimage,'UTF8')::jsonb->>'currentRevision')::bigint))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-NO-EFFECT-EVIDENCE'; END IF;
 IF NEW.result_kind='PROVIDER_REJECTED' AND (NEW.state<>'FAILED' OR NOT EXISTS(
  SELECT 1 FROM control.signing_rotation_history h JOIN control.signing_provider_attempt p
   ON p.participant_id=h.participant_id AND p.privacy_domain_id=h.privacy_domain_id AND p.operation_id=h.operation_id
  WHERE h.participant_id=NEW.participant_id AND h.privacy_domain_id=NEW.privacy_domain_id AND h.operation_id=NEW.operation_id
   AND h.state='FAILED' AND h.revision=NEW.result_revision AND h.receipt_id IS NOT NULL
   AND p.request->>'method'<>'SIGN_RECEIPT' AND p.state='REJECTED' AND p.observation->>'outcome'='REJECTED'))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-FAILED-RECEIPT'; END IF;
 IF OLD.state IN ('SUCCEEDED','FAILED') OR
  (to_jsonb(NEW)-ARRAY['state','result_revision','updated_at','recovery_observation_digest','result_kind']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['state','result_revision','updated_at','recovery_observation_digest','result_kind']) THEN RAISE EXCEPTION 'DATA-6020-COMMAND-IDENTITY'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_command() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_command_authorization(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_command_authorization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE snapshot jsonb; bound jsonb; expected jsonb; rotation control.signing_key_rotation%ROWTYPE;
 evidence control.mutation_evidence%ROWTYPE; runtime_payload jsonb; approval control.approval_request%ROWTYPE;
 checker control.approval_decision_record%ROWTYPE; now_ns numeric;
 generation control.signing_authorization_generation%ROWTYPE; effects jsonb;
BEGIN
 snapshot:=convert_from(NEW.authorization_snapshot,'UTF8')::jsonb;
 now_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.from_revision;
 effects:=openpc.signing_transition_effects(NEW.action_intent_id,rotation.state,NEW.to_state);
 IF effects IS NULL OR (effects->>'resumeFrom' IS NOT NULL AND effects->>'resumeFrom' IS DISTINCT FROM rotation.recovery_from_state)
 THEN RAISE EXCEPTION 'DATA-6022-SIGNING-COMMAND-MATRIX'; END IF;
 IF NEW.authorization_generation_id IS NULL THEN
  SELECT generation_id INTO NEW.authorization_generation_id FROM control.signing_authorization_generation
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id
    AND state='CONSUMED' ORDER BY result_revision DESC LIMIT 1;
 END IF;
 IF NEW.authorization_generation_id IS NULL THEN
  NEW.approval_request_id:=rotation.approval_request_id;
  NEW.approval_candidate_digest:=rotation.candidate_digest;
 ELSE
  SELECT * INTO STRICT generation FROM control.signing_authorization_generation WHERE generation_id=NEW.authorization_generation_id
   AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id;
  IF generation.state='STAGED' THEN
   IF generation.action_intent_id<>NEW.action_intent_id OR generation.from_revision<>NEW.from_revision OR generation.input_digest<>NEW.input_digest
    OR generation.target_state<>NEW.to_state OR NOT EXISTS(SELECT 1 FROM control.mutation_candidate candidate
     WHERE candidate.mutation_candidate_id=generation.candidate_id AND candidate.state='APPROVED'
      AND candidate.candidate_document->'context'=openpc.signing_governance_context(NEW.rotation_id,NEW.action_intent_id))
   THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GOVERNANCE-STALE'; END IF;
  ELSIF generation.generation_id IS DISTINCT FROM (SELECT generation_id FROM control.signing_authorization_generation
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id
    AND state='CONSUMED' ORDER BY result_revision DESC LIMIT 1)
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GENERATION-STALE'; END IF;
  SELECT a.approval_request_id,a.subject_digest INTO STRICT NEW.approval_request_id,NEW.approval_candidate_digest
   FROM control.approval_request a WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
    AND a.subject_id=generation.candidate_id AND a.subject_digest=generation.candidate_digest
    AND a.state='APPROVED' AND a.expires_at>clock_timestamp();
 END IF;
 IF NEW.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND generation.state='STAGED' THEN
  IF NEW.original_operation_id IS DISTINCT FROM generation.original_operation_id
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GOVERNANCE-ORIGINAL'; END IF;
 ELSIF NEW.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' THEN
  IF NEW.to_state<>'RECOVERING' OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_command original
   JOIN control.signing_provider_attempt attempt ON attempt.operation_id=original.operation_id
    AND attempt.participant_id=original.participant_id AND attempt.privacy_domain_id=original.privacy_domain_id
   JOIN LATERAL (SELECT o.observation_digest FROM control.signing_rotation_observation o
    WHERE o.participant_id=attempt.participant_id AND o.privacy_domain_id=attempt.privacy_domain_id AND o.attempt_id=attempt.attempt_id
    ORDER BY o.observed_at_ns DESC,o.observation_id DESC LIMIT 1) prior ON true
   WHERE original.participant_id=NEW.participant_id AND original.privacy_domain_id=NEW.privacy_domain_id
    AND original.rotation_id=NEW.rotation_id AND original.operation_id=NEW.original_operation_id
    AND original.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND original.state='WRITE_AMBIGUITY'
    AND attempt.attempt_id=NEW.recovery_attempt_id AND attempt.state IN ('DISPATCHING','OBSERVED')
    AND prior.observation_digest=NEW.prior_observation_digest)
  THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-EXACT-PENDING-ATTEMPT'; END IF;
 ELSE
  IF generation.state IS DISTINCT FROM 'STAGED' AND EXISTS(SELECT 1 FROM control.signing_rotation_command denied WHERE denied.participant_id=NEW.participant_id
   AND denied.privacy_domain_id=NEW.privacy_domain_id AND denied.rotation_id=NEW.rotation_id AND denied.from_revision=NEW.from_revision
   AND denied.state='FAILED' AND denied.result_kind='AUTHORITY_CHANGED_BEFORE_DISPATCH')
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-FRESH-APPROVAL-REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM control.signing_rotation_authority_hold h WHERE h.participant_id=NEW.participant_id
   AND h.privacy_domain_id=NEW.privacy_domain_id AND h.rotation_id=NEW.rotation_id AND h.state='ACTIVE')
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-AUTHORITY-HOLD'; END IF;
  IF NOT openpc.signing_admission_open(NEW.participant_id,NEW.privacy_domain_id,rotation.old_signer_id,NEW.operation_id)
   OR NOT openpc.signing_admission_open(NEW.participant_id,NEW.privacy_domain_id,rotation.new_signer_id,NEW.operation_id)
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-UNRESOLVED-ADMISSION'; END IF;
 END IF;
 SELECT * INTO STRICT evidence FROM control.mutation_evidence WHERE mutation_evidence_id=NEW.authorization_evidence_id
  AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id
  AND principal_id=NEW.principal_id AND action_intent_id=NEW.action_intent_id AND candidate_digest=NEW.input_digest
  AND aggregate_type='signing-key-rotation' AND aggregate_id=NEW.rotation_id AND aggregate_version=NEW.from_revision
  AND evidence_role='AUTHORIZATION_INPUT' AND evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
  AND evidence_digest=sha256(evidence_cbor);
 IF NEW.action_intent_id NOT IN ('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1')
  OR openpc.current_action_intent_id() IS DISTINCT FROM NEW.action_intent_id
  OR openpc.current_operation_id() IS DISTINCT FROM NEW.operation_id
  OR evidence.catalog_operation_id IS DISTINCT FROM (CASE NEW.action_intent_id
   WHEN 'ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' THEN 'OPS-OP-ADVANCE-SIGNING-KEY-ROTATION'
   ELSE 'OPS-OP-RECOVER-SIGNING-KEY-ROTATION' END) THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORIZATION-ACTION'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.idempotency_record i WHERE i.participant_id=NEW.participant_id
  AND i.privacy_domain_id=NEW.privacy_domain_id AND i.operation_id=NEW.operation_id AND i.principal_id=NEW.principal_id
  AND i.idempotency_key=NEW.idempotency_key AND i.input_digest=NEW.input_digest AND i.expected_aggregate_version=NEW.from_revision
  AND i.catalog_operation_id=evidence.catalog_operation_id AND i.action_intent_id=NEW.action_intent_id AND i.terminal_state IS NULL)
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-IDEMPOTENCY-AUTHORIZATION'; END IF;
 IF (effects->>'revoke')::boolean AND NOT EXISTS(
  SELECT 1 FROM control.qualified_receipt_inbox i JOIN control.audit_occurrence a
   ON a.participant_id=i.participant_id AND a.privacy_domain_id=i.privacy_domain_id AND a.receipt_id=i.receipt_id
  JOIN control.business_signing_grant g ON g.participant_id=a.participant_id AND g.privacy_domain_id=a.privacy_domain_id
   AND g.signer_id=a.signer_id AND g.profile_digest=a.profile_digest
  WHERE i.participant_id=NEW.participant_id AND i.privacy_domain_id=NEW.privacy_domain_id AND i.receipt_id=NEW.consumer_receipt_id
   AND i.signer_id=rotation.new_signer_id AND a.signer_id=rotation.new_signer_id
   AND a.environment_id=rotation.environment_id AND a.recorded_at_ns>=rotation.cutover_at_ns
   AND ((rotation.request->>'signerRole'='BUSINESS_EFFECT' AND i.namespace='CONTROL_BUSINESS_TRANSITION_V1' AND a.aggregate_type IN ('indexer-profile','evidence-hold','retention-policy','evidence-deletion','store-retirement','runtime-artifact-disposition','work-item','notification','notification-endpoint','workload-renewal-policy')) OR
    (rotation.request->>'signerRole'='LIFECYCLE_EVIDENCE' AND i.namespace='CONTROL_SIGNING_LIFECYCLE_V1'
      AND a.aggregate_type='signing-key-rotation' AND a.aggregate_id=NEW.rotation_id
      AND openpc.business_cbor(a.after_state_preimage)->8->>'0'='OBSERVING')))
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-REVOKE-REQUIRES-CONSUMER'; END IF;
 IF snapshot IS DISTINCT FROM jsonb_build_object('schema','pc.control.precommit-authority-snapshot.v1',
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'operationId',NEW.operation_id::text,
  'recordedAtNs',snapshot->'recordedAtNs','decision','ALLOW','authorities',snapshot->'authorities','dependencies',snapshot->'dependencies')
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>3
  OR jsonb_typeof(snapshot->'recordedAtNs') IS DISTINCT FROM 'string'
  OR NOT ((snapshot->>'recordedAtNs') ~ '^[0-9]{1,20}$') OR (snapshot->>'recordedAtNs')::numeric>now_ns
  OR snapshot->'dependencies' IS DISTINCT FROM jsonb_build_object('assignment',snapshot->'dependencies'->'assignment','authority_envelope',snapshot->'dependencies'->'authority_envelope','authority_role',snapshot->'dependencies'->'authority_role','credential',snapshot->'dependencies'->'credential','delegation',snapshot->'dependencies'->'delegation','participant',snapshot->'dependencies'->'participant','principal',snapshot->'dependencies'->'principal','privacy_domain',snapshot->'dependencies'->'privacy_domain','session',snapshot->'dependencies'->'session')
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORIZATION-SNAPSHOT'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb)
 INTO expected FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id
  AND owner.assignment_id IN(SELECT (d->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') d);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb)
 INTO expected FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id
  AND owner.authority_envelope_id IN(SELECT (d->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') d);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb)
 INTO expected FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id
  AND owner.authority_role_id IN(SELECT (d->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') d);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb)
 INTO expected FROM control.credential owner WHERE owner.participant_id=NEW.participant_id
  AND owner.credential_id IN(SELECT (d->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') d);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb)
 INTO expected FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id
  AND owner.delegation_id IN(SELECT (d->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') d);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb)
 INTO expected FROM control.participant owner WHERE owner.participant_id=NEW.participant_id
  AND owner.participant_id IN(SELECT (d->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') d);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb)
 INTO expected FROM control.principal owner WHERE owner.participant_id=NEW.participant_id
  AND owner.principal_id IN(SELECT (d->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') d);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb)
 INTO expected FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id
  AND owner.privacy_domain_id IN(SELECT (d->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') d);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb)
 INTO expected FROM control.session owner WHERE owner.participant_id=NEW.participant_id
  AND owner.session_id IN(SELECT (d->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') d);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-ACTUAL-ROW'; END IF;
 runtime_payload:=openpc.business_cbor(evidence.evidence_cbor);
 IF jsonb_typeof(runtime_payload->'8') IS DISTINCT FROM 'number' OR jsonb_typeof(runtime_payload->'9') IS DISTINCT FROM 'number' OR
    (runtime_payload->>'8')::numeric>(snapshot->>'recordedAtNs')::numeric OR
    (runtime_payload->>'9')::numeric<=now_ns THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORIZATION-EXPIRED'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.principal_id::text OR bound->>'actionIntentId' IS DISTINCT FROM NEW.action_intent_id
  OR bound->>'resourceId' IS DISTINCT FROM NEW.rotation_id::text OR bound->>'assignmentId' IS DISTINCT FROM evidence.bound_assignment_id::text
  OR bound->>'authorityEnvelopeId' IS DISTINCT FROM evidence.bound_authority_envelope_id::text
  OR bound->>'authorityEpoch' IS DISTINCT FROM evidence.bound_envelope_epoch::text
  OR bound->>'principalEpoch' IS DISTINCT FROM evidence.bound_principal_epoch::text
  OR bound->>'participantEpoch' IS DISTINCT FROM evidence.bound_participant_epoch::text
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-CALLER-AUTHORIZATION'; END IF;
 SELECT * INTO STRICT approval FROM control.approval_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=NEW.approval_request_id AND state='APPROVED' AND expires_at>clock_timestamp();
 SELECT jsonb_object_agg(key,value) INTO expected FROM jsonb_each(approval.maker_authority)
  WHERE key=ANY(ARRAY['principalId','sessionId','sessionEpoch','participantEpoch','principalEpoch','assignmentId','assignmentRowVersion',
   'authorityEnvelopeId','authorityEpoch','delegationEpoch','privacyDomainId','actionIntentId','resourceId']);
 IF snapshot->'authorities'->1 IS DISTINCT FROM expected OR
  (approval.maker_authority ? 'participantId' AND approval.maker_authority->>'participantId' IS DISTINCT FROM NEW.participant_id::text)
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-MAKER-AUTHORIZATION'; END IF;
 SELECT * INTO STRICT checker FROM control.approval_decision_record WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=approval.approval_request_id AND decision='APPROVE'
  AND approver_principal_id<>approval.maker_principal_id AND candidate_digest=NEW.approval_candidate_digest;
 IF snapshot->'authorities'->2 IS DISTINCT FROM jsonb_build_object('principalId',checker.approver_principal_id::text,
  'sessionId',checker.approver_session_id::text,'sessionEpoch',checker.approver_session_epoch::text,
  'participantEpoch',checker.approver_participant_epoch::text,'principalEpoch',checker.approver_principal_epoch::text,
  'assignmentId',checker.approver_assignment_id::text,'assignmentRowVersion',checker.approver_assignment_row_version::text,
  'authorityEnvelopeId',checker.approver_authority_envelope_id::text,'authorityEpoch',checker.approver_envelope_epoch::text,
  'delegationEpoch',checker.approver_delegation_epoch::text,'privacyDomainId',NEW.privacy_domain_id::text,
  'actionIntentId','ACT-POLICY_APPROVE_REQUEST-V1','resourceId',approval.approval_request_id::text)
 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-CHECKER-AUTHORIZATION'; END IF;
 FOR bound IN SELECT * FROM jsonb_array_elements(snapshot->'authorities') LOOP
  IF bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR
    NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch'))) OR
    NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE'))) OR
    NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',bound->>'principalId','state','ACTIVE','authority_epoch',bound->>'principalEpoch'))) OR
    NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',bound->>'principalId','state','ACTIVE','session_epoch',bound->>'sessionEpoch'))) OR
    NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion'))) OR
    NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
   THEN RAISE EXCEPTION 'DATA-6021-ROTATION-AUTHORITY-LIVE-PATH'; END IF;
 END LOOP;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_signing_command_authorization() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_continuation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_continuation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE context jsonb; now_ns numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-CONTINUATION-IMMUTABLE'; END IF;
 now_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
 context:=convert_from(NEW.context_preimage,'UTF8')::jsonb;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1'
  OR context->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR context->>'providerAttemptId' IS DISTINCT FROM NEW.provider_attempt_id::text
 THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-SCOPE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NOT pg_has_role(current_user,'openpc_signing_continuation_issuer','MEMBER') OR NEW.state<>'ISSUED'
   OR NEW.issued_at_ns>now_ns OR NEW.issued_at_ns<now_ns-1000000000 OR NEW.expires_at_ns<=now_ns
  THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-ISSUER'; END IF;
  PERFORM openpc.check_signing_continuation_context(context);
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','consumed_at_ns','consumed_receipt_id']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['state','consumed_at_ns','consumed_receipt_id']) OR OLD.state<>'ISSUED'
 THEN RAISE EXCEPTION 'DATA-6020-CONTINUATION-IDENTITY'; END IF;
 IF NEW.state='EXPIRED' THEN
  IF NOT pg_has_role(current_user,'openpc_signing_continuation_issuer','MEMBER') OR OLD.expires_at_ns>now_ns
  THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-EXPIRY'; END IF;
 ELSIF NEW.state='CONSUMED' THEN
  IF pg_has_role(current_user,'openpc_control_worker','MEMBER') OR OLD.expires_at_ns<=now_ns OR NEW.consumed_at_ns IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-CONSUMPTION'; END IF;
  IF context->>'resultDisposition'='NO_EFFECT_RETRYABLE' THEN
   IF NEW.consumed_receipt_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_operation_evidence e
    WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=NEW.operation_id
     AND e.continuation_assertion_id=NEW.assertion_id AND e.kind='NO_EFFECT_RETRYABLE')
   THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-NO-EFFECT'; END IF;
  ELSE
   IF NEW.consumed_receipt_id IS NULL OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_attestation a JOIN control.signing_provider_attempt p USING(attempt_id)
    WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.operation_id=NEW.operation_id
     AND a.continuation_assertion_id=NEW.assertion_id AND a.attempt_id=NEW.consumed_receipt_id
     AND p.state='OBSERVED' AND p.observation->>'outcome'='SUCCEEDED')
   THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-CONSUMPTION'; END IF;
  END IF;
  PERFORM openpc.check_signing_continuation_context(context);
  NEW.consumed_at_ns:=now_ns;
 ELSE RAISE EXCEPTION 'DATA-6021-CONTINUATION-TRANSITION';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_continuation() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_generation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_generation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE candidate control.mutation_candidate%ROWTYPE; context jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-SIGNING-GENERATION'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT candidate FROM control.mutation_candidate WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
   AND mutation_candidate_id=NEW.candidate_id AND candidate_digest=NEW.candidate_digest AND action_intent_id=NEW.action_intent_id
   AND resource_id=NEW.rotation_id AND expected_revision=NEW.from_revision AND state IN ('PROPOSED','APPROVAL_REQUESTED','APPROVED') AND expires_at>clock_timestamp();
  context:=openpc.signing_governance_context(NEW.rotation_id,NEW.action_intent_id);
  IF NEW.state<>'STAGED' OR NEW.consumed_operation_id IS NOT NULL OR NEW.result_revision IS NOT NULL
   OR NEW.action_intent_id IS DISTINCT FROM openpc.current_action_intent_id()
   OR candidate.candidate_document IS DISTINCT FROM jsonb_build_object('schema','pc.control.signing-governance-candidate.v1',
    'context',context,'input',candidate.candidate_document->'input','maker',candidate.candidate_document->'maker')
   OR NEW.candidate_digest<>sha256(convert_to(openpc.signing_canonical_json(candidate.candidate_document),'UTF8'))
   OR NEW.input_digest<>sha256(convert_to(openpc.signing_canonical_json(candidate.candidate_document->'input'),'UTF8'))
   OR NEW.original_operation_id::text IS DISTINCT FROM context->>'originalOperationId'
   OR NEW.prior_generation_id::text IS DISTINCT FROM context->>'priorGenerationId'
   OR NEW.hold_id::text IS DISTINCT FROM context->>'holdId' OR NEW.target_state IS DISTINCT FROM context->>'targetState'
   OR NEW.resume_state IS DISTINCT FROM context->>'resumeState' OR NEW.resume_revision::text IS DISTINCT FROM context->>'resumeRevision'
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GENERATION-CANDIDATE'; END IF;
 ELSE
  IF OLD.state<>'STAGED' OR NEW.state<>'CONSUMED' OR NEW.consumed_operation_id IS DISTINCT FROM openpc.current_operation_id()
   OR NEW.result_revision<>NEW.from_revision+1
   OR (to_jsonb(NEW)-ARRAY['state','consumed_operation_id','result_revision']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','consumed_operation_id','result_revision'])
   OR NOT EXISTS(SELECT 1 FROM control.signing_rotation_history h JOIN control.signing_rotation_command c USING(participant_id,privacy_domain_id,operation_id)
    WHERE h.participant_id=NEW.participant_id AND h.privacy_domain_id=NEW.privacy_domain_id AND h.rotation_id=NEW.rotation_id
     AND h.operation_id=NEW.consumed_operation_id AND h.revision=NEW.result_revision AND h.receipt_id IS NOT NULL
     AND c.authorization_generation_id=NEW.generation_id AND c.from_revision=NEW.from_revision AND c.input_digest=NEW.input_digest)
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GENERATION-SIGNED-COMMIT'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_generation() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_observation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.signing_provider_attempt%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM control.signing_provider_attempt WHERE attempt_id=NEW.attempt_id
  AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND rotation_id=NEW.rotation_id AND operation_id=NEW.operation_id;
 IF (NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() AND NOT EXISTS(
  SELECT 1 FROM control.signing_rotation_command c WHERE c.participant_id=NEW.participant_id
   AND c.privacy_domain_id=NEW.privacy_domain_id AND c.operation_id=openpc.current_operation_id()
   AND c.original_operation_id=NEW.operation_id AND c.recovery_attempt_id=NEW.attempt_id
   AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND c.state='ACCEPTED')) OR
  openpc.current_action_intent_id() NOT IN ('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1') OR
  (NEW.kind='NOT_FOUND' AND openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1')
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-OBSERVATION-CONTEXT'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR
  NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() OR
  NEW.observation_preimage IS DISTINCT FROM openpc.signing_observation_preimage(a,NEW.kind) OR
  NEW.observed_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000 OR
  (NEW.kind IN ('UNRESOLVED','NOT_FOUND') AND (a.state<>'DISPATCHING' OR a.observation IS NOT NULL)) OR
  (NEW.kind='PROVIDER_RESULT' AND (a.state NOT IN ('OBSERVED','ACCEPTED','REJECTED') OR a.observation IS NULL))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-OBSERVATION-BINDING'; END IF;
 IF pg_has_role(current_user,'openpc_control_worker','MEMBER') AND
  (a.request->>'method' NOT IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE') OR NEW.kind='NOT_FOUND')
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-OBSERVATION-OWNER'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_observation() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_operation_evidence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_operation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-SIGNING-OPERATION-EVIDENCE'; END IF;
 IF NEW.preimage IS DISTINCT FROM openpc.signing_operation_failure_preimage(NEW.provider_attempt_id,NEW.kind,NEW.continuation_assertion_id)
  OR NOT EXISTS(SELECT 1 FROM control.signing_provider_attempt a WHERE a.participant_id=NEW.participant_id
   AND a.privacy_domain_id=NEW.privacy_domain_id AND a.rotation_id=NEW.rotation_id AND a.operation_id=NEW.operation_id AND a.attempt_id=NEW.provider_attempt_id)
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-OPERATION-EVIDENCE'; END IF;
 NEW.recorded_at_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_operation_evidence() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_provider_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_provider_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE command control.signing_rotation_command%ROWTYPE; rotation control.signing_key_rotation%ROWTYPE; effects jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-PROVIDER-ATTEMPT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT command FROM control.signing_rotation_command WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND operation_id=NEW.operation_id AND state IN ('ACCEPTED','WRITE_AMBIGUITY');
  SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND rotation_id=NEW.rotation_id AND revision=NEW.from_revision AND state=NEW.from_state;
  effects:=openpc.signing_transition_effects(command.action_intent_id,NEW.from_state,NEW.to_state);
  IF effects IS NULL OR (effects->>'resumeFrom' IS NOT NULL AND effects->>'resumeFrom' IS DISTINCT FROM rotation.recovery_from_state)
   OR (NEW.request->>'method'<>'SIGN_RECEIPT' AND NOT (effects->'providerSteps' @> jsonb_build_array(jsonb_build_array(NEW.slot,NEW.request->>'method'))))
   OR (NEW.request->>'method'<>'SIGN_RECEIPT' AND NEW.to_state<>command.to_state)
  THEN RAISE EXCEPTION 'DATA-6022-SIGNING-PROVIDER-MATRIX'; END IF;
  IF NEW.dispatched_at_ns IS NOT NULL THEN RAISE EXCEPTION 'DATA-6021-ATTEMPT-DISPATCH-TIME'; END IF;
  IF NEW.state='DISPATCHING' AND NEW.request->>'method' IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE') THEN RAISE EXCEPTION 'DATA-6021-ATTEMPT-RESERVE-BEFORE-DISPATCH'; END IF;
  IF NEW.state NOT IN ('READY','DISPATCHING') OR NEW.observation IS NOT NULL THEN RAISE EXCEPTION 'DATA-6021-ATTEMPT-INITIAL'; END IF;
  IF NEW.state='DISPATCHING' THEN NEW.dispatched_at_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000; END IF;
  RETURN NEW;
 END IF;
 IF NEW.dispatched_at_ns IS DISTINCT FROM OLD.dispatched_at_ns THEN RAISE EXCEPTION 'DATA-6020-ATTEMPT-DISPATCH-TIME'; END IF;
 IF (to_jsonb(NEW)-ARRAY['state','observation','observation_digest']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['state','observation','observation_digest']) THEN RAISE EXCEPTION 'DATA-6020-ATTEMPT-IDENTITY'; END IF;
 IF pg_has_role(current_user,'openpc_control_worker','MEMBER') AND
  (OLD.request->>'method' NOT IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE') OR NEW.state NOT IN ('DISPATCHING','OBSERVED','CANCELLED'))
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-WORKER-OWNER'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_worker','MEMBER') AND NEW.state='DISPATCHING'
  AND OLD.request->>'method' NOT IN ('PROVE','SIGN_RECEIPT')
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-DISPATCH-OWNER'; END IF;
 IF OLD.state='READY' AND NEW.state='DISPATCHING' AND EXISTS(SELECT 1 FROM control.signing_rotation_command recovery
  WHERE recovery.participant_id=NEW.participant_id AND recovery.privacy_domain_id=NEW.privacy_domain_id
   AND recovery.original_operation_id=NEW.operation_id AND recovery.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1'
   AND recovery.state='ACCEPTED')
 THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-IN-PROGRESS'; END IF;
 IF OLD.state='READY' AND NEW.state='DISPATCHING' AND OLD.request->>'method' IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE') AND EXISTS(
  SELECT 1 FROM control.signing_rotation_command c WHERE c.operation_id=NEW.operation_id AND c.state='WRITE_AMBIGUITY')
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-ATTEMPT-UNRESOLVED-FENCE'; END IF;
 IF OLD.state='READY' AND NEW.state='DISPATCHING' THEN
  IF OLD.request->>'method' IN ('PREPARE','DISTRIBUTE','REVOKE','RETIRE') AND
   NOT coalesce((openpc.signing_attempt_authority_status(OLD.attempt_id)->>'unchangedLive')::boolean,false)
  THEN RAISE EXCEPTION 'DATA-6021-SIGNING-DISPATCH-AUTHORITY-CHANGED'; END IF;
  NEW.dispatched_at_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
 END IF;
 IF OLD.observation IS NOT NULL AND (NEW.observation IS DISTINCT FROM OLD.observation OR
    NEW.observation_digest IS DISTINCT FROM OLD.observation_digest) THEN RAISE EXCEPTION 'DATA-6020-ATTEMPT-OBSERVATION'; END IF;
 IF NEW.state='CANCELLED' THEN
  IF OLD.state<>'READY' OR OLD.dispatched_at_ns IS NOT NULL OR OLD.observation IS NOT NULL OR NOT EXISTS(
   SELECT 1 FROM control.signing_rotation_operation_evidence e WHERE e.participant_id=NEW.participant_id
    AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=NEW.operation_id AND e.kind='AUTHORITY_CHANGED_BEFORE_DISPATCH')
  THEN RAISE EXCEPTION 'DATA-6021-UNDISPATCHED-CANCELLATION'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.state='SUPERSEDED' THEN
  IF OLD.state NOT IN ('READY','DISPATCHING','OBSERVED') OR OLD.request->>'method'<>'SIGN_RECEIPT' OR NOT (EXISTS(
   SELECT 1 FROM control.signing_rotation_command c JOIN control.signing_rotation_history h
    ON h.participant_id=c.participant_id AND h.privacy_domain_id=c.privacy_domain_id AND h.operation_id=c.operation_id
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.operation_id=openpc.current_operation_id() AND c.original_operation_id=NEW.operation_id
    AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND h.state='RECOVERING'
    AND h.receipt_id IS NOT NULL AND h.revision>NEW.from_revision) OR EXISTS(SELECT 1 FROM control.signing_continuation capability
     WHERE capability.participant_id=NEW.participant_id AND capability.privacy_domain_id=NEW.privacy_domain_id
      AND capability.operation_id=NEW.operation_id AND capability.operation_id=openpc.current_operation_id()
      AND capability.state='ISSUED' AND capability.expires_at_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
      AND NOT EXISTS(SELECT 1 FROM control.audit_occurrence a WHERE a.participant_id=NEW.participant_id
       AND a.privacy_domain_id=NEW.privacy_domain_id AND a.receipt_id=NEW.attempt_id)))
  THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-SUPERSESSION'; END IF;
  RETURN NEW;
 END IF;
 IF NOT ((OLD.state='READY' AND NEW.state='DISPATCHING') OR (OLD.state='DISPATCHING' AND NEW.state='OBSERVED') OR (OLD.state='OBSERVED' AND NEW.state IN ('ACCEPTED','REJECTED')))
   THEN RAISE EXCEPTION 'DATA-6022-ATTEMPT-TRANSITION'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_provider_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_signing_rotation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_signing_rotation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE governed boolean:=false; generation control.signing_authorization_generation%ROWTYPE; effects jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROTATION'; END IF;
 IF NEW.recovery_case_id IS NOT NULL OR (TG_OP='UPDATE' AND OLD.recovery_case_id IS NOT NULL) THEN
  PERFORM openpc.guard_identity_envelope_recovery_rotation(NEW,OLD,TG_OP);
  RETURN NEW;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'REQUESTED' OR NEW.revision<>1 THEN RAISE EXCEPTION 'DATA-6021-ROTATION-INITIAL-STATE'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','revision','updated_at','approval_request_id','approved_operation_id','new_signer_id','cutover_at_ns','recovery_from_state','recovery_from_revision'])
   IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','revision','updated_at','approval_request_id','approved_operation_id','new_signer_id','cutover_at_ns','recovery_from_state','recovery_from_revision'])
   OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at THEN RAISE EXCEPTION 'DATA-6020-ROTATION-IDENTITY'; END IF;
 SELECT g.* INTO generation FROM control.signing_rotation_command c JOIN control.signing_authorization_generation g
  ON g.generation_id=c.authorization_generation_id WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND c.rotation_id=NEW.rotation_id AND c.operation_id=openpc.current_operation_id()
   AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND g.state='STAGED';
 IF FOUND THEN
  PERFORM openpc.check_signing_generation_current(generation.generation_id);
  governed:=NEW.state=generation.target_state AND NEW.revision=generation.from_revision+1 AND OLD.state<>'COMPLETE'
   AND (NEW.state=OLD.state OR (OLD.state='FAILED' AND NEW.state='RECOVERING'
    AND NEW.recovery_from_state=generation.resume_state AND NEW.recovery_from_revision=generation.resume_revision));
  IF NOT governed THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GOVERNED-TARGET'; END IF;
 END IF;
 IF NOT governed AND NEW.state<>'RECOVERING' AND EXISTS(SELECT 1 FROM control.signing_rotation_command recovery
  WHERE recovery.participant_id=NEW.participant_id AND recovery.privacy_domain_id=NEW.privacy_domain_id
   AND recovery.rotation_id=NEW.rotation_id AND recovery.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1'
   AND recovery.state='ACCEPTED')
 THEN RAISE EXCEPTION 'DATA-6021-RECOVERY-IN-PROGRESS'; END IF;
 IF OLD.approval_request_id IS NOT NULL AND (NEW.approval_request_id IS DISTINCT FROM OLD.approval_request_id OR
    NEW.approved_operation_id IS DISTINCT FROM OLD.approved_operation_id) THEN RAISE EXCEPTION 'DATA-6020-ROTATION-APPROVAL'; END IF;
 IF OLD.new_signer_id IS NOT NULL AND NEW.new_signer_id IS DISTINCT FROM OLD.new_signer_id THEN RAISE EXCEPTION 'DATA-6020-ROTATION-KEY'; END IF;
 IF OLD.cutover_at_ns IS NOT NULL AND NEW.cutover_at_ns IS DISTINCT FROM OLD.cutover_at_ns THEN RAISE EXCEPTION 'DATA-6020-ROTATION-CUTOVER'; END IF;
 IF NOT (OLD.state='REQUESTED' AND NEW.state='APPROVED') THEN
  effects:=openpc.signing_transition_effects(openpc.current_action_intent_id(),OLD.state,NEW.state);
  IF effects IS NULL OR (effects->>'resumeFrom' IS NOT NULL AND effects->>'resumeFrom' IS DISTINCT FROM OLD.recovery_from_state)
   OR (effects->>'kind' IN ('RENEWAL','FORWARD_RECOVERY') AND NOT governed)
   OR (effects->>'kind'='RECOVERY' AND NOT governed AND
     (NEW.recovery_from_state IS DISTINCT FROM coalesce(OLD.recovery_from_state,OLD.state)
      OR NEW.recovery_from_revision IS DISTINCT FROM coalesce(OLD.recovery_from_revision,OLD.revision)))
  THEN RAISE EXCEPTION 'DATA-6022-ROTATION-TRANSITION'; END IF;
 END IF;
 IF NEW.state='APPROVED' AND NOT governed AND (openpc.current_action_intent_id()<>'ACT-POLICY_APPROVE_REQUEST-V1' OR NOT EXISTS(
  SELECT 1 FROM control.approval_request a JOIN control.mutation_candidate c ON c.participant_id=a.participant_id
   AND c.privacy_domain_id=a.privacy_domain_id AND c.mutation_candidate_id=a.subject_id
  JOIN control.approval_decision_record d ON d.participant_id=a.participant_id AND d.privacy_domain_id=a.privacy_domain_id
   AND d.approval_request_id=a.approval_request_id AND d.decision='APPROVE' AND d.approver_principal_id<>a.maker_principal_id
  WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.approval_request_id=NEW.approval_request_id
   AND a.state='APPROVED' AND c.state='CONSUMED' AND c.consumed_operation_id=NEW.approved_operation_id
   AND c.resource_id=NEW.rotation_id AND c.expected_revision=OLD.revision AND c.candidate_digest=NEW.candidate_digest
   AND a.subject_digest=c.candidate_digest AND d.candidate_digest=c.candidate_digest)) THEN RAISE EXCEPTION 'DATA-6021-ROTATION-CONSUMPTION'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_signing_rotation() OWNER TO openpc_control_owner;

--
-- Name: guard_store_retirement_admission(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_store_retirement_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE attempt jsonb; host jsonb; actual_binding jsonb; policy control.retention_policy;
 previous control.store_retirement_admission; decision_digest bytea; count_decisions integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR current_setting('openpc.operation_id')::uuid IS DISTINCT FROM NEW.operation_id
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1'
  OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 NEW.admitted_at:=clock_timestamp();
 IF NEW.dispatch_not_after_ms<=floor(extract(epoch from NEW.admitted_at)*1000)
  OR NEW.dispatch_not_after_ms>floor(extract(epoch from NEW.admitted_at)*1000)+60000
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.verify_store_retirement_commit(NEW.participant_id,NEW.privacy_domain_id,NEW.host_digest,'SOURCE',
  sha256(NEW.attempt_wire||convert_to(NEW.source_binding_digest,'UTF8')||uuid_send(NEW.operation_id)
   ||uuid_send(NEW.approval_request_id)||int8send(NEW.dispatch_not_after_ms::bigint)),NEW.verification_nonce,NEW.verification_mac);
 attempt:=convert_from(NEW.attempt_wire,'UTF8')::jsonb;
 SELECT convert_from(host_wire,'UTF8')::jsonb INTO STRICT host FROM control.store_retirement_host
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND host_digest=NEW.host_digest
   AND valid_from_ms<=floor(extract(epoch from NEW.admitted_at)*1000) AND valid_until_ms>=NEW.dispatch_not_after_ms;
 SELECT * INTO STRICT policy FROM control.retention_policy WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND retention_policy_id=NEW.retention_policy_id AND active_until IS NULL;
 actual_binding:=openpc.store_retirement_source_binding(NEW.retention_policy_id,
  decode(NEW.source_binding->>'selectionWireHex','hex'),NEW.source_binding->'recordRefs');
 IF NEW.source_binding IS DISTINCT FROM actual_binding
  OR NEW.source_binding_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(actual_binding),'UTF8')),'hex')
  OR attempt->'selection' IS DISTINCT FROM convert_from(decode(actual_binding->>'selectionWireHex','hex'),'UTF8')::jsonb
  OR attempt->'scope' IS DISTINCT FROM host->'scope' OR attempt->>'store' IS DISTINCT FROM host->>'store'
  OR attempt->>'business_intent_id' IS DISTINCT FROM NEW.retirement_id::text OR attempt->>'attempt_id' IS DISTINCT FROM NEW.attempt_id::text
  OR attempt->>'selection_digest' IS DISTINCT FROM NEW.selection_digest
  OR NEW.attempt_digest IS DISTINCT FROM encode(sha256(convert_to('["OPENPC_STORE_RETIREMENT_ATTEMPT_V1",','UTF8')||NEW.attempt_wire||convert_to(']','UTF8')),'hex')
  OR NEW.lifecycle_revision::text IS DISTINCT FROM actual_binding->>'lifecycleRevision'
  OR attempt#>>'{governance,lifecycle_revision}' IS DISTINCT FROM NEW.lifecycle_revision::text
  OR attempt#>>'{governance,retention_policy_digest}' IS DISTINCT FROM substring(policy.policy_digest from 8)
  OR attempt#>>'{governance,archive_manifest_digest}' IS DISTINCT FROM actual_binding->>'archiveManifestDigest'
  OR attempt#>>'{governance,archive_acknowledgement_digest}' IS DISTINCT FROM actual_binding->>'archiveAcknowledgementDigest'
  OR attempt#>>'{governance,retention_not_before_ms}' IS DISTINCT FROM actual_binding->>'retentionNotBeforeMs'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT count(*),decode(min(encode(d.decision_digest,'hex')),'hex') INTO count_decisions,decision_digest
  FROM control.approval_decision_record d JOIN control.approval_request a USING(participant_id,privacy_domain_id,approval_request_id)
  WHERE d.participant_id=NEW.participant_id AND d.privacy_domain_id=NEW.privacy_domain_id AND d.approval_request_id=NEW.approval_request_id
   AND d.decision='APPROVE' AND a.state='APPROVED' AND a.expires_at>NEW.admitted_at
   AND a.maker_principal_id<>d.approver_principal_id AND a.subject_digest=d.candidate_digest
   AND a.subject_version=d.aggregate_version;
 IF count_decisions<>1 OR attempt#>>'{governance,approval_digest}' IS DISTINCT FROM encode(decision_digest,'hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NEW.previous_attempt_id IS NULL THEN
  IF NEW.retirement_id<>NEW.attempt_id THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  SELECT a.* INTO STRICT previous FROM control.store_retirement_admission a JOIN control.store_retirement_outcome o
    USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.attempt_id=NEW.previous_attempt_id
    AND o.state IN ('REJECTED_NO_EFFECT','CANCELLED_NO_EFFECT');
  IF previous.retirement_id<>NEW.retirement_id OR previous.host_digest<>NEW.host_digest OR previous.selection_digest<>NEW.selection_digest
   OR previous.approval_request_id=NEW.approval_request_id THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 -- A fresh idempotency key cannot disguise another unresolved business intent.
 IF EXISTS(SELECT 1 FROM control.store_retirement_admission a LEFT JOIN control.store_retirement_outcome o
   USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.host_digest=NEW.host_digest
    AND (o.state IS NULL OR o.state='APPLIED') AND EXISTS(SELECT 1
      FROM jsonb_array_elements(convert_from(a.attempt_wire,'UTF8')::jsonb->'selection'->'rows') old_row,
       jsonb_array_elements(attempt->'selection'->'rows') new_row WHERE old_row->>'candidate_id'=new_row->>'candidate_id'))
 THEN RAISE EXCEPTION 'PC-DATA-6007-UNRESOLVED-OR-APPLIED'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_store_retirement_admission() OWNER TO openpc_control_owner;

--
-- Name: guard_store_retirement_cancellation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_store_retirement_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.store_retirement_admission; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.store_retirement_admission WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id AND xmin<>pg_current_xact_id()::xid;
 PERFORM openpc.lock_store_retirement_workload(a.host_digest);
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||a.participant_id::text,0));
 IF EXISTS(SELECT 1 FROM control.store_retirement_outcome WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.lifecycle_revision:=openpc.store_retirement_lifecycle_revision(a.participant_id,a.privacy_domain_id);
 IF NEW.lifecycle_revision<>a.lifecycle_revision THEN
  expected:=jsonb_build_object('reason','LIFECYCLE_CHANGED','revision',NEW.lifecycle_revision::text);
 ELSIF a.dispatch_not_after_ms<=floor(extract(epoch from clock_timestamp())*1000) THEN
  expected:=jsonb_build_object('reason','AUTHORITY_EXPIRED','dispatchNotAfterMs',a.dispatch_not_after_ms::text);
 ELSIF EXISTS(SELECT 1 FROM control.store_retirement_delivery WHERE participant_id=a.participant_id
   AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND purpose='REQUEST') THEN
  expected:=jsonb_build_object('reason','RECONCILE_UNKNOWN');
 ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NEW.cause IS DISTINCT FROM expected OR NEW.lifecycle_revision<a.lifecycle_revision THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.committed_digest:=encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','OPENPC_STORE_RETIREMENT_CANCELLATION_V1','participantId',a.participant_id::text,'privacyDomainId',a.privacy_domain_id::text,
  'hostDigest',a.host_digest,'attemptDigest',a.attempt_digest,'cancellationId',NEW.cancellation_id::text,
  'lifecycleRevision',NEW.lifecycle_revision::text,'cause',expected)),'UTF8')),'hex');
 NEW.committed_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_store_retirement_cancellation() OWNER TO openpc_control_owner;

--
-- Name: guard_store_retirement_delivery(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_store_retirement_delivery() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.store_retirement_admission; c control.store_retirement_cancellation;
 claims jsonb; signed jsonb; host jsonb; receipt text; expected jsonb; now_ms numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.store_retirement_admission WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id AND xmin<>pg_current_xact_id()::xid;
 -- Identity locks precede the lifecycle fence. Cancellation has no new execution
 -- authority and can resolve an expired or revoked original grant.
 IF NEW.purpose='REQUEST' THEN PERFORM openpc.lock_store_retirement_authority(a.attempt_id);
 ELSE PERFORM openpc.lock_store_retirement_workload(a.host_digest); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||a.participant_id::text,0));
 PERFORM openpc.verify_store_retirement_commit(a.participant_id,a.privacy_domain_id,a.host_digest,'DELIVERY',
  sha256(sha256(a.attempt_wire)||sha256(NEW.signed_wire)),NEW.verification_nonce,NEW.verification_mac);
 IF EXISTS(SELECT 1 FROM control.store_retirement_outcome WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 signed:=convert_from(NEW.signed_wire,'UTF8')::jsonb; claims:=signed->'claims';
 SELECT convert_from(host_wire,'UTF8')::jsonb INTO STRICT host FROM control.store_retirement_host
  WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND host_digest=a.host_digest;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF NEW.issued_at_ms>now_ms OR NEW.expires_at_ms<=now_ms OR NEW.expires_at_ms-NEW.issued_at_ms NOT BETWEEN 1 AND 60000
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 expected:=jsonb_build_object('version',1,'host',host,'attempt',convert_from(a.attempt_wire,'UTF8')::jsonb,
  'issued_at_ms',NEW.issued_at_ms,'expires_at_ms',NEW.expires_at_ms);
 IF NEW.purpose='REQUEST' THEN
  IF signed->>'purpose' IS DISTINCT FROM 'openpc:store-retirement-request:v1'
   OR NEW.expires_at_ms>a.dispatch_not_after_ms
   OR openpc.store_retirement_source_binding(a.retention_policy_id,decode(a.source_binding->>'selectionWireHex','hex'),a.source_binding->'recordRefs')
     IS DISTINCT FROM a.source_binding
   OR EXISTS(SELECT 1 FROM control.store_retirement_cancellation WHERE participant_id=a.participant_id
     AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT encode(receipt_digest,'hex') INTO STRICT receipt FROM control.audit_occurrence
   WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id
    AND aggregate_type='store-retirement' AND aggregate_id=a.attempt_id AND profile_id='pc.control.store-retirement.admit';
  expected:=expected||jsonb_build_object('admission_receipt_digest',receipt,'committed_admission_digest',openpc.store_retirement_committed_digest(a));
 ELSIF NEW.purpose='CANCEL' THEN
  SELECT * INTO STRICT c FROM control.store_retirement_cancellation WHERE participant_id=a.participant_id
   AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND xmin<>pg_current_xact_id()::xid;
  IF signed->>'purpose' IS DISTINCT FROM 'openpc:store-retirement-cancel:v1' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  expected:=expected||jsonb_build_object('cancellation_id',c.cancellation_id::text,'lifecycle_revision',c.lifecycle_revision,
    'committed_cancellation_digest',c.committed_digest);
 ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF claims IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.committed_at:=clock_timestamp();
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_store_retirement_delivery() OWNER TO openpc_control_owner;

--
-- Name: guard_store_retirement_host(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_store_retirement_host() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE host jsonb:=convert_from(NEW.host_wire,'UTF8')::jsonb;
BEGIN
 IF host IS DISTINCT FROM jsonb_build_object('environment_id',host->>'environment_id','target_id',host->>'target_id',
   'scope',jsonb_build_object('participant_id',NEW.participant_id::text,'privacy_domain_id',NEW.privacy_domain_id::text),'store',host->>'store')
  OR coalesce(host->>'environment_id','')!~'^[!-~]{1,160}$' OR coalesce(host->>'target_id','')!~'^[!-~]{1,160}$'
  OR coalesce(host->>'store','') NOT IN ('openpc_facts','openpc_candidate_index')
  OR encode(substring(NEW.control_spki from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  OR encode(substring(NEW.target_spki from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
   AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
   AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER') AND NOT pg_has_role(r.oid,'openpc_control_key_governor','MEMBER'))
  OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
   WHERE c.participant_id=NEW.participant_id AND c.credential_id=NEW.workload_credential_id
    AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC') AND c.state='ACTIVE' AND c.credential_epoch=NEW.workload_credential_epoch
    AND w.kind='WORKLOAD' AND w.state='ACTIVE' AND c.valid_from<=clock_timestamp()
    AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
    AND c.public_key_digest IS DISTINCT FROM sha256(NEW.control_spki) AND c.public_key_digest IS DISTINCT FROM sha256(NEW.target_spki))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_store_retirement_host() OWNER TO openpc_control_owner;

--
-- Name: guard_store_retirement_outcome(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_store_retirement_outcome() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a control.store_retirement_admission; signed jsonb; claims jsonb; effect jsonb; host jsonb; expected jsonb; selected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.store_retirement_admission WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id AND xmin<>pg_current_xact_id()::xid;
 PERFORM openpc.lock_store_retirement_workload(a.host_digest);
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||a.participant_id::text,0));
 PERFORM openpc.verify_store_retirement_commit(a.participant_id,a.privacy_domain_id,a.host_digest,'OUTCOME',
  sha256(sha256(a.attempt_wire)||sha256(NEW.signed_wire)),NEW.verification_nonce,NEW.verification_mac);
 signed:=convert_from(NEW.signed_wire,'UTF8')::jsonb; claims:=signed->'claims'; effect:=claims->'outcome'->'effect';
 SELECT convert_from(host_wire,'UTF8')::jsonb INTO STRICT host FROM control.store_retirement_host
  WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND host_digest=a.host_digest;
 expected:=jsonb_build_object('version',1,'host',host,'business_intent_id',a.retirement_id::text,'attempt_id',a.attempt_id::text,
  'outcome',jsonb_build_object('attempt_digest',a.attempt_digest,'effect',effect),'completed_at_ms',NEW.completed_at_ms);
 IF signed->>'purpose' IS DISTINCT FROM 'openpc:store-retirement-outcome:v1' OR claims IS DISTINCT FROM expected
  OR effect->>'state' IS DISTINCT FROM NEW.state THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NEW.state='APPLIED' THEN
  selected:=convert_from(a.attempt_wire,'UTF8')::jsonb->'selection'->'rows';
  IF effect IS DISTINCT FROM jsonb_build_object('state','APPLIED','retired_rows',jsonb_array_length(selected),
    'retired_payload_bytes',(SELECT sum((row->>'payload_bytes')::numeric) FROM jsonb_array_elements(selected) row),
    'retained_lineage_digest',effect->>'retained_lineage_digest','outbox_event_digest',effect->>'outbox_event_digest')
   OR coalesce(effect->>'retained_lineage_digest','')!~'^[0-9a-f]{64}$'
   OR coalesce(effect->>'outbox_event_digest','')!~'^[0-9a-f]{64}$'
   OR NOT EXISTS(SELECT 1 FROM control.store_retirement_delivery WHERE participant_id=a.participant_id
    AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND purpose='REQUEST') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSIF NEW.state='CANCELLED_NO_EFFECT' THEN
  IF effect IS DISTINCT FROM jsonb_build_object('state','CANCELLED_NO_EFFECT')
   OR NOT EXISTS(SELECT 1 FROM control.store_retirement_cancellation WHERE participant_id=a.participant_id
    AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSIF NEW.state='REJECTED_NO_EFFECT' THEN
  IF effect IS DISTINCT FROM jsonb_build_object('state','REJECTED_NO_EFFECT','rejection',effect->>'rejection')
   OR coalesce(effect->>'rejection','') NOT IN ('SOURCE_CHANGED','GENERATION_CHANGED','REORG_FENCED','CHECKPOINT_INCOMPLETE',
    'READINESS_PROTECTED','PUBLICATION_PROTECTED','REFERENCES_PROTECTED','RETENTION_NOT_ELAPSED','ARCHIVE_MISMATCH','GOVERNANCE_CHANGED')
   OR NOT EXISTS(SELECT 1 FROM control.store_retirement_delivery WHERE participant_id=a.participant_id
    AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND purpose='REQUEST') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.recorded_at:=clock_timestamp();
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_store_retirement_outcome() OWNER TO openpc_control_owner;

--
-- Name: guard_transferred_contract(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_transferred_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.transaction_policy IS DISTINCT FROM OLD.transaction_policy THEN
  RAISE EXCEPTION 'PC-AUTH-0002-TRANSACTION-POLICY-IMMUTABLE';
 END IF;
 IF NEW.state='BOUND' AND EXISTS(SELECT 1 FROM control.contract_administration_transfer
   WHERE logical_contract_id=NEW.logical_contract_id AND participant_id=NEW.participant_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-ADMINISTRATION-TRANSFERRED';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_transferred_contract() OWNER TO openpc_control_owner;

--
-- Name: guard_typed_argument_rule_version_registration(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_typed_argument_rule_version_registration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected text;
BEGIN
 IF TG_TABLE_SCHEMA<>'control' OR TG_TABLE_NAME<>'typed_argument_rule_version' OR TG_OP NOT IN ('INSERT','UPDATE')
 THEN RAISE EXCEPTION 'DATA-6004-CONTRACT-REGISTRATION-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'DATA-6001-CONTEXT-INVALID'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.participant_id IS DISTINCT FROM OLD.participant_id OR NEW.privacy_domain_id IS DISTINCT FROM OLD.privacy_domain_id
    OR NEW.policy_generation_digest IS DISTINCT FROM OLD.policy_generation_digest
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-IMMUTABLE'; END IF;
 ELSE
  expected:=openpc.configuration_policy_provenance(NEW.participant_id,NEW.privacy_domain_id);
  IF NEW.policy_generation_digest IS DISTINCT FROM expected
  THEN RAISE EXCEPTION 'DATA-6007-CONTRACT-REGISTRATION-PROVENANCE'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_typed_argument_rule_version_registration() OWNER TO openpc_control_owner;

--
-- Name: guard_wallet_binding_transition(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_wallet_binding_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-RETAINED'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR NEW.binding_epoch<>1 OR NEW.row_version<>1 THEN
   RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-INITIAL-STATE';
  END IF;
 ELSE
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.binding_epoch<>OLD.binding_epoch+1
   OR NEW.row_version<>OLD.row_version+1 OR NEW.last_operation_id=OLD.last_operation_id
   OR (to_jsonb(NEW)-ARRAY['state','binding_epoch','row_version','last_operation_id','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','binding_epoch','row_version','last_operation_id','updated_at']) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-TRANSITION';
  END IF;
 END IF;
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.last_operation_id<>current_setting('openpc.operation_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' THEN
  RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-CONTEXT';
 END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM control.principal subject JOIN control.participant participant USING(participant_id)
  JOIN control.privacy_domain privacy ON privacy.participant_id=subject.participant_id AND privacy.privacy_domain_id=NEW.privacy_domain_id
  WHERE subject.participant_id=NEW.participant_id AND subject.principal_id=NEW.subject_id
    AND subject.kind IN ('USER','WALLET','WORKLOAD') AND subject.state='ACTIVE'
    AND participant.state='ACTIVE' AND participant.archived_at IS NULL AND privacy.state='ACTIVE') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-SUBJECT';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_wallet_binding_transition() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_credential_family(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_credential_family() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'workload instance history is immutable'; END IF;
 IF (NEW.participant_id,NEW.privacy_domain_id,NEW.family_id,NEW.principal_id,NEW.workload_id,
     NEW.instance_id,NEW.instance_generation,NEW.instance_admission_operation_id)
   IS DISTINCT FROM (OLD.participant_id,OLD.privacy_domain_id,OLD.family_id,OLD.principal_id,OLD.workload_id,
     OLD.instance_id,OLD.instance_generation,OLD.instance_admission_operation_id)
   OR NEW.security_epoch<OLD.security_epoch OR NEW.row_version<=OLD.row_version
   OR (OLD.state<>'ACTIVE' AND NEW.state<>OLD.state)
   OR (NEW.current_credential_id=OLD.current_credential_id AND
       (NEW.generation<>OLD.generation OR NEW.current_fingerprint<>OLD.current_fingerprint))
   OR (NEW.current_credential_id<>OLD.current_credential_id AND NEW.generation<>OLD.generation+1)
 THEN RAISE EXCEPTION 'workload family transition rejected'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_workload_credential_family() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_handover_generation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_handover_generation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE snapshot jsonb; expected jsonb; bound jsonb; source_document jsonb; generation_document jsonb;
 owner_row control.workload_signing_handover; parent control.workload_signing_handover_generation;
 key_document jsonb; descriptor jsonb; proof_row control.workload_signing_handover_attempt; prior text; seen_fingerprints text[]:=array[]::text[]; seen_references text[]:=array[]::text[];
BEGIN

 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id() OR NEW.authority_snapshot_digest<>sha256(NEW.authority_snapshot)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-PREPARATION'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR snapshot->>'decision' IS DISTINCT FROM 'ALLOW'
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>1
  OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
 FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
 (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
 FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
 (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
 FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
 (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
 FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
 (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
 FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
 (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
 FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
 (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
 FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
 (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
 FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
 (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
 FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
 (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR bound->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id() OR bound->>'resourceId' IS DISTINCT FROM '*'
  OR NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch')))
  OR NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE')))
  OR NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',NEW.maker_principal_id::text,'state','ACTIVE','authority_epoch',bound->>'principalEpoch')))
  OR NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',NEW.maker_principal_id::text,'state','ACTIVE','session_epoch',bound->>'sessionEpoch')))
  OR NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion')))
  OR NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-BOUND-PATH'; END IF;
 IF current_setting('transaction_isolation')<>'serializable' OR NOT EXISTS(
  WITH RECURSIVE path AS (
   SELECT a.principal_id terminal_principal_id,a.delegation_epoch,a.onward_delegation_depth remaining_depth,
    null::uuid delegation_id,array[]::uuid[] delegation_ids,array[a.principal_id] principal_ids
   FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.assignment_id=(bound->>'assignmentId')::uuid
    AND a.state='ACTIVE' AND a.row_version::text=bound->>'assignmentRowVersion'
    AND a.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND a.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(a.action_intent_ids) AND NEW.privacy_domain_id::text=any(a.privacy_domain_ids)
    AND openpc.assignment_role_permits(a.participant_id,a.role_id,openpc.current_action_intent_id())
    AND openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
    AND openpc.administration_resource_permits(a.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,(bound->>'authorityEnvelopeId')::uuid)
   UNION ALL
   SELECT d.delegate_principal_id,d.delegation_epoch,d.onward_delegation_depth,d.delegation_id,
    path.delegation_ids||d.delegation_id,path.principal_ids||d.delegate_principal_id
   FROM path JOIN control.delegation d ON d.participant_id=NEW.participant_id
    AND ((path.delegation_id IS NULL AND d.parent_assignment_id=(bound->>'assignmentId')::uuid) OR d.parent_delegation_id=path.delegation_id)
    AND d.grantor_principal_id=path.terminal_principal_id AND d.state='ACTIVE' AND d.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(d.action_intent_ids) AND NEW.privacy_domain_id::text=any(d.privacy_domain_ids)
    AND '*'=any(d.resource_ids) AND d.onward_delegation_depth<path.remaining_depth
   WHERE path.remaining_depth>0 AND cardinality(path.delegation_ids)<32 AND NOT d.delegation_id=any(path.delegation_ids)
  ) SELECT 1 FROM path JOIN control.authority_envelope e ON e.participant_id=NEW.participant_id
   AND e.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND e.state='ACTIVE' AND e.authority_epoch::text=bound->>'authorityEpoch'
   AND ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      ))) AND e.valid_from<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>clock_timestamp())
   AND openpc.current_action_intent_id()=any(e.action_intent_ids) AND NEW.privacy_domain_id::text=any(e.privacy_domain_ids)
   AND openpc.administration_resource_permits(e.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,e.authority_envelope_id)
   JOIN control.principal actor ON actor.participant_id=NEW.participant_id AND actor.principal_id=NEW.maker_principal_id
    AND actor.state='ACTIVE' AND actor.authority_epoch::text=bound->>'principalEpoch' AND actor.kind IN('USER','PLATFORM_OPERATOR')
   JOIN control.session session ON session.participant_id=NEW.participant_id AND session.session_id=(bound->>'sessionId')::uuid
    AND session.principal_id=NEW.maker_principal_id AND session.state='ACTIVE' AND session.session_epoch::text=bound->>'sessionEpoch'
    AND session.participant_epoch::text=bound->>'participantEpoch' AND session.authority_epoch::text=bound->>'principalEpoch'
    AND session.delegation_epoch::text=bound->>'delegationEpoch' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
   WHERE path.terminal_principal_id=NEW.maker_principal_id AND path.delegation_epoch::text=bound->>'delegationEpoch'
    AND NOT EXISTS(SELECT 1 FROM unnest(path.principal_ids) dependency(id) WHERE NOT EXISTS(
      SELECT 1 FROM control.principal principal WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=dependency.id AND principal.state='ACTIVE'))
    AND NOT EXISTS(SELECT 1 FROM control.recovery_principal recovery WHERE recovery.participant_id=NEW.participant_id AND recovery.principal_id=NEW.maker_principal_id)
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-LIVE-AUTHORITY'; END IF;

 SELECT * INTO STRICT owner_row FROM control.workload_signing_handover WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id AND maker_principal_id=NEW.maker_principal_id;
 source_document:=owner_row.source; generation_document:=NEW.document;

 IF source_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.source.v1'
  OR source_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR source_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NOT EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal USING(participant_id,principal_id)
   JOIN control.participant participant USING(participant_id)
   WHERE credential.participant_id=NEW.participant_id AND credential.credential_id=(source_document->'issuer'->>'workloadCredentialId')::uuid
    AND credential.principal_id=(source_document->'issuer'->>'workloadPrincipalId')::uuid
    AND credential.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
    AND participant.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND credential.credential_epoch::text=source_document->'issuer'->>'workloadCredentialEpoch'
    AND principal.authority_epoch::text=source_document->'issuer'->>'workloadPrincipalEpoch'
    AND participant.authority_epoch::text=source_document->'issuer'->>'workloadParticipantEpoch')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-CURRENT-ISSUER'; END IF;

 IF NEW.request_canonical<>convert_to(openpc.signing_canonical_json(NEW.request),'UTF8')
  OR NEW.request_digest<>sha256(convert_to('pc.identity.workload-signing-handover.possession-generation-request.v1','UTF8')||decode('00','hex')||NEW.request_canonical)
  OR NEW.document_canonical<>convert_to(openpc.signing_canonical_json(generation_document),'UTF8')
  OR NEW.document_digest<>sha256(convert_to('pc.identity.workload-signing-handover.possession-generation.v1','UTF8')||decode('00','hex')||NEW.document_canonical)
  OR NEW.request-ARRAY['schemaVersion','supersedesGenerationId','reason']<>'{}'::jsonb
  OR NOT NEW.request ?& ARRAY['schemaVersion','supersedesGenerationId','reason']
  OR NEW.request->>'schemaVersion' IS DISTINCT FROM '1'
  OR NEW.request->>'supersedesGenerationId' IS DISTINCT FROM NEW.supersedes_generation_id::text
  OR jsonb_typeof(NEW.request->'reason') IS DISTINCT FROM 'string' OR char_length(NEW.request->>'reason') NOT BETWEEN 12 AND 1024
  OR generation_document-ARRAY['schema','participantId','privacyDomainId','environmentId','handoverId','sourceDigest','generationId','operationId','makerPrincipalId','supersedesGenerationId','issuedAtNs','expiresAtNs','issuer','keys']<>'{}'::jsonb
  OR NOT generation_document ?& ARRAY['schema','participantId','privacyDomainId','environmentId','handoverId','sourceDigest','generationId','operationId','makerPrincipalId','supersedesGenerationId','issuedAtNs','expiresAtNs','issuer','keys']
  OR generation_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.possession-generation.v1'
  OR generation_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR generation_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR generation_document->>'environmentId' IS DISTINCT FROM owner_row.environment_id
  OR generation_document->>'handoverId' IS DISTINCT FROM NEW.handover_id::text
  OR generation_document->>'generationId' IS DISTINCT FROM NEW.generation_id::text
  OR generation_document->>'operationId' IS DISTINCT FROM NEW.operation_id::text
  OR generation_document->>'makerPrincipalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR generation_document->>'supersedesGenerationId' IS DISTINCT FROM NEW.supersedes_generation_id::text
  OR generation_document->>'sourceDigest' IS DISTINCT FROM 'sha256:'||encode(owner_row.source_digest,'hex')
  OR generation_document->'issuer' IS DISTINCT FROM source_document->'issuer'
  OR generation_document->>'issuedAtNs' !~ '^[1-9][0-9]{0,19}$' OR generation_document->>'expiresAtNs' !~ '^[1-9][0-9]{0,19}$'
  OR mod((generation_document->>'issuedAtNs')::numeric,1000)<>0 OR mod((generation_document->>'expiresAtNs')::numeric,1000)<>0
  OR (generation_document->>'issuedAtNs')::numeric>NEW.recorded_at_ns
  OR (generation_document->>'expiresAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000
  OR (generation_document->>'expiresAtNs')::numeric<=(generation_document->>'issuedAtNs')::numeric
  OR (generation_document->>'expiresAtNs')::numeric-(generation_document->>'issuedAtNs')::numeric>300000000000
  OR (generation_document->>'expiresAtNs')::numeric>18446744073709551615
  OR (generation_document->>'issuedAtNs')::numeric<(source_document->'issuer'->>'credentialValidFromNs')::numeric
  OR (source_document->'issuer'->>'credentialValidUntilNs' IS NOT NULL AND (generation_document->>'expiresAtNs')::numeric>(source_document->'issuer'->>'credentialValidUntilNs')::numeric)
  OR jsonb_typeof(generation_document->'keys') IS DISTINCT FROM 'array'
  OR jsonb_array_length(generation_document->'keys')<>jsonb_array_length(source_document->'keys')
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-CUSTODY'; END IF;
 prior:='';
 FOR key_document IN SELECT value FROM jsonb_array_elements(generation_document->'keys') LOOP
  descriptor:=key_document->'observation'->'descriptor';
  IF key_document-ARRAY['binding','attempt','observation']<>'{}'::jsonb OR NOT key_document ?& ARRAY['binding','attempt','observation']
   OR key_document->'binding'->>'handoverId' IS DISTINCT FROM NEW.handover_id::text
   OR key_document->'binding'->>'sourceDigest' IS DISTINCT FROM 'sha256:'||encode(owner_row.source_digest,'hex')
   OR key_document->'binding'->'replacement'->>'oldFingerprint' IS NULL
   OR key_document->'binding'->'replacement'->>'oldFingerprint'<=prior
   OR key_document->'observation'->>'outcome' IS DISTINCT FROM 'SUCCEEDED'
   OR (key_document->'observation'->>'recordedAtNs')::numeric>(generation_document->>'issuedAtNs')::numeric
   OR jsonb_typeof(descriptor) IS DISTINCT FROM 'object' OR descriptor->>'state' IS DISTINCT FROM 'ACTIVE'
   OR descriptor->'revokedAtNs' IS DISTINCT FROM 'null'::jsonb OR descriptor->'retiredAtNs' IS DISTINCT FROM 'null'::jsonb
   OR (descriptor->>'validFromNs')::numeric>(generation_document->>'issuedAtNs')::numeric
   OR (descriptor->>'validUntilNs')::numeric<(generation_document->>'expiresAtNs')::numeric
   OR descriptor->>'fingerprint'=any(seen_fingerprints) OR descriptor->>'reference'=any(seen_references)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(source_document->'keys') old_key WHERE old_key->>'oldFingerprint'=descriptor->>'fingerprint')
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-KEY'; END IF;
  prior:=key_document->'binding'->'replacement'->>'oldFingerprint';
  seen_fingerprints:=array_append(seen_fingerprints,descriptor->>'fingerprint');seen_references:=array_append(seen_references,descriptor->>'reference');
 END LOOP;

 FOR key_document IN SELECT value FROM jsonb_array_elements(generation_document->'keys') LOOP
  IF NOT EXISTS(SELECT 1 FROM control.workload_signing_handover_attempt a
   JOIN control.workload_signing_handover_dispatch d USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
    AND a.handover_id=(generation_document->>'handoverId')::uuid AND a.stage='PREPARATION'
    AND a.attempt_id=(key_document->'attempt'->'request'->>'attemptId')::uuid
    AND a.binding=key_document->'binding' AND a.attempt=key_document->'attempt'
    AND EXISTS(SELECT 1 FROM control.workload_signing_handover_observation o
     WHERE o.participant_id=a.participant_id AND o.privacy_domain_id=a.privacy_domain_id AND o.attempt_id=a.attempt_id
      AND o.result->>'state'='OBSERVED' AND o.result->'observation'=key_document->'observation')
    AND NOT EXISTS(SELECT 1 FROM control.workload_signing_handover_observation o
     WHERE o.participant_id=a.participant_id AND o.privacy_domain_id=a.privacy_domain_id AND o.attempt_id=a.attempt_id
      AND o.result->>'state'='OBSERVED' AND o.result->'observation' IS DISTINCT FROM key_document->'observation'))
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-PREPARATION-CONFLICT'; END IF;
 END LOOP;

 IF NEW.supersedes_generation_id IS NOT NULL THEN
  SELECT * INTO STRICT parent FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND generation_id=NEW.supersedes_generation_id
   AND handover_id=NEW.handover_id AND maker_principal_id=NEW.maker_principal_id;
  IF (parent.document->>'expiresAtNs')::numeric>(generation_document->>'issuedAtNs')::numeric
   OR EXISTS(SELECT 1 FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND supersedes_generation_id=parent.generation_id)
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-REFRESH'; END IF;
  FOR proof_row IN SELECT * FROM control.workload_signing_handover_attempt WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND generation_id=parent.generation_id AND stage='POSSESSION' LOOP
   IF NOT EXISTS(SELECT 1 FROM control.workload_signing_handover_observation o
    WHERE o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id AND o.attempt_id=proof_row.attempt_id
     AND o.result->>'state'='OBSERVED' AND o.result->'observation'->>'outcome'='SUCCEEDED')
    OR (SELECT count(DISTINCT result->'observation') FROM control.workload_signing_handover_observation
     WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=proof_row.attempt_id AND result->>'state'='OBSERVED')<>1
   THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-UNSETTLED'; END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_workload_handover_generation() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_handover_generation_complete(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_handover_generation_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE snapshot jsonb; expected jsonb; bound jsonb; source_document jsonb;
BEGIN

 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id() OR NEW.authority_snapshot_digest<>sha256(NEW.authority_snapshot)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-PREPARATION'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR snapshot->>'decision' IS DISTINCT FROM 'ALLOW'
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>1
  OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
 FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
 (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
 FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
 (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
 FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
 (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
 FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
 (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
 FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
 (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
 FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
 (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
 FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
 (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
 FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
 (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
 FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
 (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR bound->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id() OR bound->>'resourceId' IS DISTINCT FROM '*'
  OR NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch')))
  OR NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE')))
  OR NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',NEW.maker_principal_id::text,'state','ACTIVE','authority_epoch',bound->>'principalEpoch')))
  OR NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',NEW.maker_principal_id::text,'state','ACTIVE','session_epoch',bound->>'sessionEpoch')))
  OR NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion')))
  OR NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-BOUND-PATH'; END IF;
 IF current_setting('transaction_isolation')<>'serializable' OR NOT EXISTS(
  WITH RECURSIVE path AS (
   SELECT a.principal_id terminal_principal_id,a.delegation_epoch,a.onward_delegation_depth remaining_depth,
    null::uuid delegation_id,array[]::uuid[] delegation_ids,array[a.principal_id] principal_ids
   FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.assignment_id=(bound->>'assignmentId')::uuid
    AND a.state='ACTIVE' AND a.row_version::text=bound->>'assignmentRowVersion'
    AND a.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND a.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(a.action_intent_ids) AND NEW.privacy_domain_id::text=any(a.privacy_domain_ids)
    AND openpc.assignment_role_permits(a.participant_id,a.role_id,openpc.current_action_intent_id())
    AND openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
    AND openpc.administration_resource_permits(a.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,(bound->>'authorityEnvelopeId')::uuid)
   UNION ALL
   SELECT d.delegate_principal_id,d.delegation_epoch,d.onward_delegation_depth,d.delegation_id,
    path.delegation_ids||d.delegation_id,path.principal_ids||d.delegate_principal_id
   FROM path JOIN control.delegation d ON d.participant_id=NEW.participant_id
    AND ((path.delegation_id IS NULL AND d.parent_assignment_id=(bound->>'assignmentId')::uuid) OR d.parent_delegation_id=path.delegation_id)
    AND d.grantor_principal_id=path.terminal_principal_id AND d.state='ACTIVE' AND d.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(d.action_intent_ids) AND NEW.privacy_domain_id::text=any(d.privacy_domain_ids)
    AND '*'=any(d.resource_ids) AND d.onward_delegation_depth<path.remaining_depth
   WHERE path.remaining_depth>0 AND cardinality(path.delegation_ids)<32 AND NOT d.delegation_id=any(path.delegation_ids)
  ) SELECT 1 FROM path JOIN control.authority_envelope e ON e.participant_id=NEW.participant_id
   AND e.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND e.state='ACTIVE' AND e.authority_epoch::text=bound->>'authorityEpoch'
   AND ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      ))) AND e.valid_from<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>clock_timestamp())
   AND openpc.current_action_intent_id()=any(e.action_intent_ids) AND NEW.privacy_domain_id::text=any(e.privacy_domain_ids)
   AND openpc.administration_resource_permits(e.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,e.authority_envelope_id)
   JOIN control.principal actor ON actor.participant_id=NEW.participant_id AND actor.principal_id=NEW.maker_principal_id
    AND actor.state='ACTIVE' AND actor.authority_epoch::text=bound->>'principalEpoch' AND actor.kind IN('USER','PLATFORM_OPERATOR')
   JOIN control.session session ON session.participant_id=NEW.participant_id AND session.session_id=(bound->>'sessionId')::uuid
    AND session.principal_id=NEW.maker_principal_id AND session.state='ACTIVE' AND session.session_epoch::text=bound->>'sessionEpoch'
    AND session.participant_epoch::text=bound->>'participantEpoch' AND session.authority_epoch::text=bound->>'principalEpoch'
    AND session.delegation_epoch::text=bound->>'delegationEpoch' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
   WHERE path.terminal_principal_id=NEW.maker_principal_id AND path.delegation_epoch::text=bound->>'delegationEpoch'
    AND NOT EXISTS(SELECT 1 FROM unnest(path.principal_ids) dependency(id) WHERE NOT EXISTS(
      SELECT 1 FROM control.principal principal WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=dependency.id AND principal.state='ACTIVE'))
    AND NOT EXISTS(SELECT 1 FROM control.recovery_principal recovery WHERE recovery.participant_id=NEW.participant_id AND recovery.principal_id=NEW.maker_principal_id)
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-LIVE-AUTHORITY'; END IF;

 SELECT source INTO STRICT source_document FROM control.workload_signing_handover WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id;

 IF source_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.source.v1'
  OR source_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR source_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NOT EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal USING(participant_id,principal_id)
   JOIN control.participant participant USING(participant_id)
   WHERE credential.participant_id=NEW.participant_id AND credential.credential_id=(source_document->'issuer'->>'workloadCredentialId')::uuid
    AND credential.principal_id=(source_document->'issuer'->>'workloadPrincipalId')::uuid
    AND credential.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
    AND participant.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND credential.credential_epoch::text=source_document->'issuer'->>'workloadCredentialEpoch'
    AND principal.authority_epoch::text=source_document->'issuer'->>'workloadPrincipalEpoch'
    AND participant.authority_epoch::text=source_document->'issuer'->>'workloadParticipantEpoch')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-CURRENT-ISSUER'; END IF;

 IF (NEW.document->>'expiresAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000
  OR (SELECT count(*) FROM control.workload_signing_handover_attempt WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id AND generation_id=NEW.generation_id AND stage='POSSESSION')<>jsonb_array_length(NEW.document->'keys')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.document->'keys') key_document WHERE NOT EXISTS(
   SELECT 1 FROM control.workload_signing_handover_attempt command WHERE command.participant_id=NEW.participant_id
    AND command.privacy_domain_id=NEW.privacy_domain_id AND command.handover_id=NEW.handover_id AND command.generation_id=NEW.generation_id
    AND command.stage='POSSESSION' AND command.predecessor_fingerprint=key_document->'binding'->'replacement'->>'oldFingerprint'))
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-INCOMPLETE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.guard_workload_handover_generation_complete() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_handover_possession_attempt(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_handover_possession_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE snapshot jsonb; expected jsonb; bound jsonb; source_document jsonb; generation_document jsonb;
 generation_row control.workload_signing_handover_generation; key_document jsonb; request_document jsonb; request_domain text;
BEGIN

 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id() OR NEW.authority_snapshot_digest<>sha256(NEW.authority_snapshot)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-PREPARATION'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR snapshot->>'decision' IS DISTINCT FROM 'ALLOW'
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>1
  OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
 FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
 (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
 FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
 (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
 FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
 (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
 FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
 (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
 FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
 (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
 FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
 (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
 FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
 (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
 FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
 (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
 FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
 (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR bound->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id() OR bound->>'resourceId' IS DISTINCT FROM '*'
  OR NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch')))
  OR NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE')))
  OR NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',NEW.maker_principal_id::text,'state','ACTIVE','authority_epoch',bound->>'principalEpoch')))
  OR NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',NEW.maker_principal_id::text,'state','ACTIVE','session_epoch',bound->>'sessionEpoch')))
  OR NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion')))
  OR NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-BOUND-PATH'; END IF;
 IF current_setting('transaction_isolation')<>'serializable' OR NOT EXISTS(
  WITH RECURSIVE path AS (
   SELECT a.principal_id terminal_principal_id,a.delegation_epoch,a.onward_delegation_depth remaining_depth,
    null::uuid delegation_id,array[]::uuid[] delegation_ids,array[a.principal_id] principal_ids
   FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.assignment_id=(bound->>'assignmentId')::uuid
    AND a.state='ACTIVE' AND a.row_version::text=bound->>'assignmentRowVersion'
    AND a.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND a.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(a.action_intent_ids) AND NEW.privacy_domain_id::text=any(a.privacy_domain_ids)
    AND openpc.assignment_role_permits(a.participant_id,a.role_id,openpc.current_action_intent_id())
    AND openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
    AND openpc.administration_resource_permits(a.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,(bound->>'authorityEnvelopeId')::uuid)
   UNION ALL
   SELECT d.delegate_principal_id,d.delegation_epoch,d.onward_delegation_depth,d.delegation_id,
    path.delegation_ids||d.delegation_id,path.principal_ids||d.delegate_principal_id
   FROM path JOIN control.delegation d ON d.participant_id=NEW.participant_id
    AND ((path.delegation_id IS NULL AND d.parent_assignment_id=(bound->>'assignmentId')::uuid) OR d.parent_delegation_id=path.delegation_id)
    AND d.grantor_principal_id=path.terminal_principal_id AND d.state='ACTIVE' AND d.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(d.action_intent_ids) AND NEW.privacy_domain_id::text=any(d.privacy_domain_ids)
    AND '*'=any(d.resource_ids) AND d.onward_delegation_depth<path.remaining_depth
   WHERE path.remaining_depth>0 AND cardinality(path.delegation_ids)<32 AND NOT d.delegation_id=any(path.delegation_ids)
  ) SELECT 1 FROM path JOIN control.authority_envelope e ON e.participant_id=NEW.participant_id
   AND e.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND e.state='ACTIVE' AND e.authority_epoch::text=bound->>'authorityEpoch'
   AND ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      ))) AND e.valid_from<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>clock_timestamp())
   AND openpc.current_action_intent_id()=any(e.action_intent_ids) AND NEW.privacy_domain_id::text=any(e.privacy_domain_ids)
   AND openpc.administration_resource_permits(e.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,e.authority_envelope_id)
   JOIN control.principal actor ON actor.participant_id=NEW.participant_id AND actor.principal_id=NEW.maker_principal_id
    AND actor.state='ACTIVE' AND actor.authority_epoch::text=bound->>'principalEpoch' AND actor.kind IN('USER','PLATFORM_OPERATOR')
   JOIN control.session session ON session.participant_id=NEW.participant_id AND session.session_id=(bound->>'sessionId')::uuid
    AND session.principal_id=NEW.maker_principal_id AND session.state='ACTIVE' AND session.session_epoch::text=bound->>'sessionEpoch'
    AND session.participant_epoch::text=bound->>'participantEpoch' AND session.authority_epoch::text=bound->>'principalEpoch'
    AND session.delegation_epoch::text=bound->>'delegationEpoch' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
   WHERE path.terminal_principal_id=NEW.maker_principal_id AND path.delegation_epoch::text=bound->>'delegationEpoch'
    AND NOT EXISTS(SELECT 1 FROM unnest(path.principal_ids) dependency(id) WHERE NOT EXISTS(
      SELECT 1 FROM control.principal principal WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=dependency.id AND principal.state='ACTIVE'))
    AND NOT EXISTS(SELECT 1 FROM control.recovery_principal recovery WHERE recovery.participant_id=NEW.participant_id AND recovery.principal_id=NEW.maker_principal_id)
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-LIVE-AUTHORITY'; END IF;

 SELECT * INTO STRICT generation_row FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND generation_id=NEW.generation_id AND handover_id=NEW.handover_id
  AND operation_id=NEW.operation_id AND maker_principal_id=NEW.maker_principal_id;
 generation_document:=generation_row.document;
 SELECT source INTO STRICT source_document FROM control.workload_signing_handover WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id;

 IF source_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.source.v1'
  OR source_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR source_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NOT EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal USING(participant_id,principal_id)
   JOIN control.participant participant USING(participant_id)
   WHERE credential.participant_id=NEW.participant_id AND credential.credential_id=(source_document->'issuer'->>'workloadCredentialId')::uuid
    AND credential.principal_id=(source_document->'issuer'->>'workloadPrincipalId')::uuid
    AND credential.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
    AND participant.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND credential.credential_epoch::text=source_document->'issuer'->>'workloadCredentialEpoch'
    AND principal.authority_epoch::text=source_document->'issuer'->>'workloadPrincipalEpoch'
    AND participant.authority_epoch::text=source_document->'issuer'->>'workloadParticipantEpoch')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-CURRENT-ISSUER'; END IF;

 SELECT value INTO STRICT key_document FROM jsonb_array_elements(generation_document->'keys') WHERE value->'binding'->'replacement'->>'oldFingerprint'=NEW.predecessor_fingerprint;
 request_document:=NEW.attempt->'request';request_domain:=CASE WHEN NEW.attempt->>'purpose'='pc.cose.identity-authority-envelope.v1' THEN 'pc.identity.envelope-key-rotation-request.v1' ELSE 'pc.control.signing-provider-request.v1' END;
 IF NEW.stage<>'POSSESSION' OR NEW.recorded_at_ns<generation_row.recorded_at_ns
  OR NEW.authority_snapshot_digest<>generation_row.authority_snapshot_digest
  OR NEW.authority_snapshot<>generation_row.authority_snapshot
  OR (generation_document->>'expiresAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000
  OR NEW.preparation_attempt_id::text IS DISTINCT FROM key_document->'attempt'->'request'->>'attemptId'
  OR NEW.binding IS DISTINCT FROM key_document->'binding'
  OR NEW.binding_canonical<>convert_to(openpc.signing_canonical_json(NEW.binding),'UTF8')
  OR NEW.binding_digest<>sha256(convert_to('pc.identity.workload-signing-handover.provider-binding.v1','UTF8')||decode('00','hex')||NEW.binding_canonical)
  OR NEW.attempt_canonical<>convert_to(openpc.signing_canonical_json(NEW.attempt),'UTF8')
  OR NEW.attempt_digest<>sha256(convert_to('pc.identity.workload-signing-handover.possession-attempt.v1','UTF8')||decode('00','hex')||NEW.attempt_canonical)
  OR NEW.attempt-ARRAY['schemaVersion','stage','handoverId','sourceDigest','predecessorFingerprint','providerId','bindingDigest','requestDigest','generationId','generationDigest','preparationAttemptId','preparationAttemptDigest','preparationObservationDigest','challengeNonceHex','purpose','signerRole','request']<>'{}'::jsonb
  OR NEW.attempt->>'schemaVersion' IS DISTINCT FROM '1' OR NEW.attempt->>'stage' IS DISTINCT FROM 'POSSESSION'
  OR NEW.attempt->>'handoverId' IS DISTINCT FROM NEW.handover_id::text
  OR NEW.attempt->>'sourceDigest' IS DISTINCT FROM generation_document->>'sourceDigest'
  OR NEW.attempt->>'generationId' IS DISTINCT FROM NEW.generation_id::text
  OR NEW.attempt->>'generationDigest' IS DISTINCT FROM 'sha256:'||encode(generation_row.document_digest,'hex')
  OR NEW.attempt->>'predecessorFingerprint' IS DISTINCT FROM NEW.predecessor_fingerprint
  OR NEW.attempt->>'providerId' IS DISTINCT FROM NEW.provider_id OR NEW.provider_id IS DISTINCT FROM NEW.binding->>'providerId'
  OR NEW.attempt->>'bindingDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.binding_digest,'hex')
  OR NEW.attempt->>'preparationAttemptId' IS DISTINCT FROM NEW.preparation_attempt_id::text
  OR NEW.attempt->>'preparationAttemptDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.identity.workload-signing-handover.provider-attempt.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(key_document->'attempt'),'UTF8')),'hex')
  OR NEW.attempt->>'preparationObservationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.identity.workload-signing-handover.provider-observation.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(key_document->'observation'),'UTF8')),'hex')
  OR NEW.attempt->>'challengeNonceHex' IS NULL OR NEW.attempt->>'challengeNonceHex' !~ '^[0-9a-f]{64}$'
  OR NEW.attempt->>'purpose' IS DISTINCT FROM key_document->'attempt'->>'purpose'
  OR NEW.attempt->>'signerRole' IS DISTINCT FROM key_document->'attempt'->>'signerRole'
  OR NEW.attempt->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(request_domain,'UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(request_document),'UTF8')),'hex')
  OR request_document->>'method' IS DISTINCT FROM 'PROVE'
  OR request_document->>'operationId' IS DISTINCT FROM NEW.operation_id::text
  OR request_document->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
  OR request_document->>'rotationId' IS DISTINCT FROM NEW.handover_id::text
  OR request_document->>'expectedFingerprint' IS DISTINCT FROM key_document->'observation'->'descriptor'->>'fingerprint'
  OR request_document->>'challengeHex' IS DISTINCT FROM encode(sha256(convert_to('pc.identity.workload-signing-handover.possession-challenge.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json((NEW.attempt-ARRAY['purpose','signerRole','request','requestDigest'])||jsonb_build_object('operationId',NEW.operation_id::text,'attemptId',NEW.attempt_id::text,'issuedAtNs',generation_document->>'issuedAtNs','expiresAtNs',generation_document->>'expiresAtNs')),'UTF8')),'hex')
  OR request_document ? 'recoveryPredecessor'
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-POSSESSION-CUSTODY'; END IF;
 expected:=key_document->'attempt'->'request';
 IF NEW.attempt->>'purpose'='pc.cose.identity-authority-envelope.v1' THEN
  expected:=(expected-'method')||jsonb_build_object('method','PROVE','operationId',NEW.operation_id::text,'attemptId',NEW.attempt_id::text,'expectedFingerprint',key_document->'observation'->'descriptor'->>'fingerprint','challengeHex',request_document->>'challengeHex','challengeIssuedAtNs',generation_document->>'issuedAtNs','challengeExpiresAtNs',generation_document->>'expiresAtNs','governanceDigest','sha256:'||encode(generation_row.document_digest,'hex'));
 ELSE
  expected:=expected||jsonb_build_object('method','PROVE','operationId',NEW.operation_id::text,'attemptId',NEW.attempt_id::text,'rotationId',NEW.handover_id::text,'expectedFingerprint',key_document->'observation'->'descriptor'->>'fingerprint','challengeHex',request_document->>'challengeHex');
 END IF;
 IF request_document IS DISTINCT FROM expected THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-POSSESSION-REQUEST'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_workload_handover_possession_attempt() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_renewal_original(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_renewal_original() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'renewal original history is immutable'; END IF;
 IF (NEW.participant_id,NEW.privacy_domain_id,NEW.renewal_id,NEW.family_id,NEW.operation_id,
     NEW.credential_id,NEW.original,NEW.request_bytes,NEW.request_digest,NEW.family_security_epoch,
     NEW.admission_operation_id,NEW.attestation_evidence,NEW.attestation_valid_until,NEW.renewal_deadline,NEW.created_at)
   IS DISTINCT FROM
    (OLD.participant_id,OLD.privacy_domain_id,OLD.renewal_id,OLD.family_id,OLD.operation_id,
     OLD.credential_id,OLD.original,OLD.request_bytes,OLD.request_digest,OLD.family_security_epoch,
     OLD.admission_operation_id,OLD.attestation_evidence,OLD.attestation_valid_until,OLD.renewal_deadline,OLD.created_at)
   OR NEW.lease_fence<OLD.lease_fence OR NEW.row_version<OLD.row_version
   OR (OLD.provider_outcome='ISSUED' AND NEW.provider_outcome<>'ISSUED')
   OR (OLD.certificate_der IS NOT NULL AND (NEW.certificate_der,NEW.certificate_fingerprint)
       IS DISTINCT FROM (OLD.certificate_der,OLD.certificate_fingerprint))
 THEN RAISE EXCEPTION 'renewal original or monotonic fence changed'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_workload_renewal_original() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_renewal_policy(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_renewal_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'renewal policy provenance is immutable'; END IF;
 RAISE EXCEPTION 'renewal policy revisions are immutable';
END $$;


ALTER FUNCTION openpc.guard_workload_renewal_policy() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_renewal_policy_head(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_renewal_policy_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6007-RENEWAL-HISTORY'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.current_revision<>1 OR NEW.row_version<>1 OR NEW.state<>'ACTIVE' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  IF (NEW.participant_id,NEW.privacy_domain_id,NEW.policy_id,NEW.principal_id,NEW.workload_id) IS DISTINCT FROM
   (OLD.participant_id,OLD.privacy_domain_id,OLD.policy_id,OLD.principal_id,OLD.workload_id)
   OR NEW.current_revision<>OLD.current_revision+1 OR NEW.row_version<>OLD.row_version+1 OR OLD.state='REVOKED'
  THEN RAISE EXCEPTION 'PC-DATA-6007-RENEWAL-CURRENT-CAS'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.workload_renewal_policy p WHERE p.participant_id=NEW.participant_id
  AND p.privacy_domain_id=NEW.privacy_domain_id AND p.policy_id=NEW.policy_id AND p.revision=NEW.current_revision
  AND p.state=NEW.state AND p.principal_id=NEW.principal_id AND p.workload_id=NEW.workload_id
  AND p.governance_operation_id=current_setting('openpc.operation_id')::uuid)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-CURRENT-OWNER'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_workload_renewal_policy_head() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_renewal_policy_insert(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_renewal_policy_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE d jsonb:=NEW.definition; lifetime numeric; reserve numeric; overlap numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.governance_operation_id<>current_setting('openpc.operation_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.definition_canonical IS DISTINCT FROM convert_to(openpc.signing_canonical_json(d),'UTF8')
  OR (d-ARRAY['version','participantId','privacyDomainId','policyId','principalId','workloadId','issuerProfileDigest','providerQualificationDigest',
   'attestationProfileDigest','managedAttestorScopeDigest','maximumInstances','maximumEnrollmentsPerMinute','certificateLifetimeSeconds',
   'recoveryReserveSeconds','maximumOverlapSeconds','validFrom','validUntil'])<>'{}'::jsonb
  OR d->'version' IS DISTINCT FROM '1'::jsonb OR d->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR d->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR d->>'policyId' IS DISTINCT FROM NEW.policy_id::text
  OR d->>'principalId' IS DISTINCT FROM NEW.principal_id::text OR d->>'workloadId' IS DISTINCT FROM NEW.workload_id
  OR NEW.workload_id!~'^urn:openpc:workload:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR d->>'attestationProfileDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.attestation_profile_digest,'hex')
  OR d->>'issuerProfileDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.issuer_profile_digest,'hex')
  OR d->>'providerQualificationDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.provider_qualification_digest,'hex')
  OR coalesce(d->>'managedAttestorScopeDigest','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(d->>'validFrom','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
  OR coalesce(d->>'validUntil','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
  OR (d->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from OR (d->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
 THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-POLICY-OWNER'; END IF;
 IF jsonb_typeof(d->'maximumInstances') IS DISTINCT FROM 'number' OR coalesce(d->>'maximumInstances','')!~'^[1-9][0-9]{0,3}$'
  OR (d->>'maximumInstances')::numeric NOT BETWEEN 1 AND 1024
  OR jsonb_typeof(d->'maximumEnrollmentsPerMinute') IS DISTINCT FROM 'number' OR coalesce(d->>'maximumEnrollmentsPerMinute','')!~'^[1-9][0-9]{0,3}$'
  OR (d->>'maximumEnrollmentsPerMinute')::numeric NOT BETWEEN 1 AND 1024
  OR jsonb_typeof(d->'certificateLifetimeSeconds') IS DISTINCT FROM 'number' OR coalesce(d->>'certificateLifetimeSeconds','')!~'^[1-9][0-9]{0,4}$'
  OR jsonb_typeof(d->'recoveryReserveSeconds') IS DISTINCT FROM 'number' OR coalesce(d->>'recoveryReserveSeconds','')!~'^[1-9][0-9]{0,4}$'
  OR jsonb_typeof(d->'maximumOverlapSeconds') IS DISTINCT FROM 'number' OR coalesce(d->>'maximumOverlapSeconds','')!~'^[1-9][0-9]{0,2}$'
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 lifetime:=(d->>'certificateLifetimeSeconds')::numeric;reserve:=(d->>'recoveryReserveSeconds')::numeric;overlap:=(d->>'maximumOverlapSeconds')::numeric;
 IF lifetime NOT BETWEEN 1 AND 86400 OR reserve NOT BETWEEN 1 AND 86400 OR overlap NOT BETWEEN 1 AND 300
  OR NOT (overlap<reserve AND reserve<lifetime-least(lifetime/2,43200) AND lifetime-least(lifetime/2,43200)<lifetime)
  OR NOT EXISTS(SELECT 1 FROM control.principal p WHERE p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id AND p.kind='WORKLOAD'
   AND (NEW.state<>'ACTIVE' OR (p.state='ACTIVE' AND NEW.valid_until>clock_timestamp()))
   AND EXISTS(SELECT 1 FROM control.credential c WHERE c.participant_id=p.participant_id AND c.principal_id=p.principal_id AND c.kind='WORKLOAD_MTLS' AND c.subject=NEW.workload_id))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-RENEWAL-POLICY-BOUNDS'; END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_workload_renewal_policy_insert() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_renewal_signing_selection(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_renewal_signing_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-RENEWAL-SIGNING-SELECTION'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_key_governor','MEMBER') AND NOT pg_has_role(current_user,'openpc_control_owner','MEMBER') THEN
  RAISE EXCEPTION 'DATA-6021-RENEWAL-SIGNING-INSTALLATION-AUTHORITY';
 END IF;
 IF NEW.profile_digest<>decode('bba6435c44c28f630d498d0d43cb4968fb2cef2828fb831908b7e7bff5cf39df','hex') OR NEW.admission_version<>1
  OR NOT EXISTS(SELECT 1 FROM control.workload_renewal_signing_grant g
   JOIN control.business_signing_key k USING(participant_id,privacy_domain_id,signer_id,signing_purpose_code)
   JOIN control.business_signing_key_state state USING(participant_id,privacy_domain_id,signer_id)
   JOIN control.workload_credential_family f ON f.participant_id=g.participant_id AND f.privacy_domain_id=g.privacy_domain_id AND f.family_id=g.family_id
   JOIN control.credential c ON c.participant_id=f.participant_id AND c.credential_id=f.current_credential_id
   JOIN control.principal p ON p.participant_id=f.participant_id AND p.principal_id=f.principal_id
   JOIN control.privacy_domain d ON d.participant_id=f.participant_id AND d.privacy_domain_id=f.privacy_domain_id
   WHERE g.participant_id=NEW.participant_id AND g.privacy_domain_id=NEW.privacy_domain_id AND g.signer_id=NEW.signer_id
    AND g.profile_digest=NEW.profile_digest AND k.environment_id=NEW.environment_id AND k.signing_purpose_code=376
    AND state.state='ACTIVE' AND state.row_version=g.key_security_generation
    AND f.state='ACTIVE' AND f.principal_id=g.principal_id AND f.workload_id=g.workload_id AND f.security_epoch=g.family_security_epoch
    AND c.kind='WORKLOAD_MTLS' AND c.state='ACTIVE' AND c.principal_id=f.principal_id AND c.audience=f.workload_id
    AND c.secret_fingerprint=f.current_fingerprint AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
    AND p.kind='WORKLOAD' AND p.state='ACTIVE' AND d.state='ACTIVE'
    AND k.valid_from_ns<=floor(extract(epoch FROM clock_timestamp())*1000000)*1000
    AND k.valid_until_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
    FOR SHARE OF state) THEN
  RAISE EXCEPTION 'DATA-6021-RENEWAL-SIGNING-CURRENT-KEY';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_workload_renewal_signing_selection() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_signing_handover_dispatch(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_signing_handover_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE snapshot jsonb; expected jsonb; bound jsonb; source_document jsonb;
 command control.workload_signing_handover_attempt; owner_row control.workload_signing_handover;
 generation_row control.workload_signing_handover_generation; generation_document jsonb; key_document jsonb;
BEGIN

 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id() OR NEW.authority_snapshot_digest<>sha256(NEW.authority_snapshot)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-PREPARATION'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR snapshot->>'decision' IS DISTINCT FROM 'ALLOW'
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>1
  OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
 FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
 (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
 FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
 (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
 FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
 (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
 FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
 (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
 FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
 (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
 FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
 (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
 FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
 (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
 FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
 (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
 FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
 (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR bound->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id() OR bound->>'resourceId' IS DISTINCT FROM '*'
  OR NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch')))
  OR NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE')))
  OR NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',NEW.maker_principal_id::text,'state','ACTIVE','authority_epoch',bound->>'principalEpoch')))
  OR NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',NEW.maker_principal_id::text,'state','ACTIVE','session_epoch',bound->>'sessionEpoch')))
  OR NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion')))
  OR NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-BOUND-PATH'; END IF;
 IF current_setting('transaction_isolation')<>'serializable' OR NOT EXISTS(
  WITH RECURSIVE path AS (
   SELECT a.principal_id terminal_principal_id,a.delegation_epoch,a.onward_delegation_depth remaining_depth,
    null::uuid delegation_id,array[]::uuid[] delegation_ids,array[a.principal_id] principal_ids
   FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.assignment_id=(bound->>'assignmentId')::uuid
    AND a.state='ACTIVE' AND a.row_version::text=bound->>'assignmentRowVersion'
    AND a.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND a.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(a.action_intent_ids) AND NEW.privacy_domain_id::text=any(a.privacy_domain_ids)
    AND openpc.assignment_role_permits(a.participant_id,a.role_id,openpc.current_action_intent_id())
    AND openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
    AND openpc.administration_resource_permits(a.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,(bound->>'authorityEnvelopeId')::uuid)
   UNION ALL
   SELECT d.delegate_principal_id,d.delegation_epoch,d.onward_delegation_depth,d.delegation_id,
    path.delegation_ids||d.delegation_id,path.principal_ids||d.delegate_principal_id
   FROM path JOIN control.delegation d ON d.participant_id=NEW.participant_id
    AND ((path.delegation_id IS NULL AND d.parent_assignment_id=(bound->>'assignmentId')::uuid) OR d.parent_delegation_id=path.delegation_id)
    AND d.grantor_principal_id=path.terminal_principal_id AND d.state='ACTIVE' AND d.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(d.action_intent_ids) AND NEW.privacy_domain_id::text=any(d.privacy_domain_ids)
    AND '*'=any(d.resource_ids) AND d.onward_delegation_depth<path.remaining_depth
   WHERE path.remaining_depth>0 AND cardinality(path.delegation_ids)<32 AND NOT d.delegation_id=any(path.delegation_ids)
  ) SELECT 1 FROM path JOIN control.authority_envelope e ON e.participant_id=NEW.participant_id
   AND e.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND e.state='ACTIVE' AND e.authority_epoch::text=bound->>'authorityEpoch'
   AND ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      ))) AND e.valid_from<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>clock_timestamp())
   AND openpc.current_action_intent_id()=any(e.action_intent_ids) AND NEW.privacy_domain_id::text=any(e.privacy_domain_ids)
   AND openpc.administration_resource_permits(e.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,e.authority_envelope_id)
   JOIN control.principal actor ON actor.participant_id=NEW.participant_id AND actor.principal_id=NEW.maker_principal_id
    AND actor.state='ACTIVE' AND actor.authority_epoch::text=bound->>'principalEpoch' AND actor.kind IN('USER','PLATFORM_OPERATOR')
   JOIN control.session session ON session.participant_id=NEW.participant_id AND session.session_id=(bound->>'sessionId')::uuid
    AND session.principal_id=NEW.maker_principal_id AND session.state='ACTIVE' AND session.session_epoch::text=bound->>'sessionEpoch'
    AND session.participant_epoch::text=bound->>'participantEpoch' AND session.authority_epoch::text=bound->>'principalEpoch'
    AND session.delegation_epoch::text=bound->>'delegationEpoch' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
   WHERE path.terminal_principal_id=NEW.maker_principal_id AND path.delegation_epoch::text=bound->>'delegationEpoch'
    AND NOT EXISTS(SELECT 1 FROM unnest(path.principal_ids) dependency(id) WHERE NOT EXISTS(
      SELECT 1 FROM control.principal principal WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=dependency.id AND principal.state='ACTIVE'))
    AND NOT EXISTS(SELECT 1 FROM control.recovery_principal recovery WHERE recovery.participant_id=NEW.participant_id AND recovery.principal_id=NEW.maker_principal_id)
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-LIVE-AUTHORITY'; END IF;

 SELECT * INTO STRICT command FROM control.workload_signing_handover_attempt
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id;
 SELECT * INTO STRICT owner_row FROM control.workload_signing_handover
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id;
 IF command.handover_id<>NEW.handover_id OR command.maker_principal_id<>NEW.maker_principal_id
  OR owner_row.maker_principal_id<>NEW.maker_principal_id OR NEW.attempt_digest<>command.attempt_digest
  OR NEW.source_digest<>owner_row.source_digest
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-DISPATCH-CUSTODY'; END IF;
 source_document:=owner_row.source;

 IF source_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.source.v1'
  OR source_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR source_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NOT EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal USING(participant_id,principal_id)
   JOIN control.participant participant USING(participant_id)
   WHERE credential.participant_id=NEW.participant_id AND credential.credential_id=(source_document->'issuer'->>'workloadCredentialId')::uuid
    AND credential.principal_id=(source_document->'issuer'->>'workloadPrincipalId')::uuid
    AND credential.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
    AND participant.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND credential.credential_epoch::text=source_document->'issuer'->>'workloadCredentialEpoch'
    AND principal.authority_epoch::text=source_document->'issuer'->>'workloadPrincipalEpoch'
    AND participant.authority_epoch::text=source_document->'issuer'->>'workloadParticipantEpoch')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-CURRENT-ISSUER'; END IF;

 IF command.stage='POSSESSION' THEN
  SELECT * INTO STRICT generation_row FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND generation_id=command.generation_id AND handover_id=NEW.handover_id;
  generation_document:=generation_row.document;
  IF (generation_document->>'expiresAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000
   OR EXISTS(SELECT 1 FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND supersedes_generation_id=generation_row.generation_id)
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-POSSESSION-DISPATCH-EXPIRED'; END IF;

 FOR key_document IN SELECT value FROM jsonb_array_elements(generation_document->'keys') LOOP
  IF NOT EXISTS(SELECT 1 FROM control.workload_signing_handover_attempt a
   JOIN control.workload_signing_handover_dispatch d USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
    AND a.handover_id=(generation_document->>'handoverId')::uuid AND a.stage='PREPARATION'
    AND a.attempt_id=(key_document->'attempt'->'request'->>'attemptId')::uuid
    AND a.binding=key_document->'binding' AND a.attempt=key_document->'attempt'
    AND EXISTS(SELECT 1 FROM control.workload_signing_handover_observation o
     WHERE o.participant_id=a.participant_id AND o.privacy_domain_id=a.privacy_domain_id AND o.attempt_id=a.attempt_id
      AND o.result->>'state'='OBSERVED' AND o.result->'observation'=key_document->'observation')
    AND NOT EXISTS(SELECT 1 FROM control.workload_signing_handover_observation o
     WHERE o.participant_id=a.participant_id AND o.privacy_domain_id=a.privacy_domain_id AND o.attempt_id=a.attempt_id
      AND o.result->>'state'='OBSERVED' AND o.result->'observation' IS DISTINCT FROM key_document->'observation'))
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-GENERATION-PREPARATION-CONFLICT'; END IF;
 END LOOP;

 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.guard_workload_signing_handover_dispatch() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_signing_handover_observation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_signing_handover_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE dispatch control.workload_signing_handover_dispatch; command control.workload_signing_handover_attempt;
 previous control.workload_signing_handover_observation; observation jsonb; descriptor jsonb; expected jsonb;
 generation_document jsonb; key_document jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id()
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-OBSERVATION-SCOPE'; END IF;
 SELECT * INTO STRICT dispatch FROM control.workload_signing_handover_dispatch
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND dispatch_id=NEW.dispatch_id;
 SELECT * INTO STRICT command FROM control.workload_signing_handover_attempt
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id;
 IF dispatch.attempt_id<>NEW.attempt_id OR dispatch.handover_id<>NEW.handover_id
  OR command.handover_id<>NEW.handover_id OR dispatch.attempt_digest<>command.attempt_digest
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-OWNER'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('pc.identity.workload-signing-handover.observation:'||NEW.attempt_id::text,0));
 SELECT * INTO previous FROM control.workload_signing_handover_observation
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id
  ORDER BY sequence DESC LIMIT 1;
 IF NEW.sequence IS DISTINCT FROM coalesce(previous.sequence,0)+1
  OR NEW.previous_digest IS DISTINCT FROM previous.entry_digest
  OR (previous.recorded_at_ns IS NOT NULL AND NEW.recorded_at_ns<previous.recorded_at_ns)
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-SEQUENCE'; END IF;
 expected:=jsonb_build_object('schemaVersion',1,'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
  'handoverId',NEW.handover_id::text,'attemptId',NEW.attempt_id::text,'dispatchId',NEW.dispatch_id::text,
  'observationId',NEW.observation_id::text,'operationId',NEW.operation_id::text,'sequence',NEW.sequence,
  'previousDigest',CASE WHEN NEW.previous_digest IS NULL THEN NULL ELSE 'sha256:'||encode(NEW.previous_digest,'hex') END,
  'resultDigest','sha256:'||encode(NEW.result_digest,'hex'),'recordedAtNs',NEW.recorded_at_ns::text);
 IF NEW.entry_canonical<>convert_to(openpc.signing_canonical_json(expected),'UTF8')
  OR NEW.entry_digest<>sha256(convert_to('pc.identity.workload-signing-handover.observation-entry.v1','UTF8')||decode('00','hex')||NEW.entry_canonical)
  OR NEW.result_canonical<>convert_to(openpc.signing_canonical_json(NEW.result),'UTF8')
  OR NEW.result_digest<>sha256(convert_to('pc.identity.workload-signing-handover.provider-result.v1','UTF8')||decode('00','hex')||NEW.result_canonical)
  OR jsonb_typeof(NEW.result) IS DISTINCT FROM 'object' OR NEW.result->>'state' IS NULL
  OR NEW.result->>'via' IS NULL OR NEW.result->>'via' NOT IN('DISPATCH','LOOKUP')
 THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-CUSTODY'; END IF;
 CASE NEW.result->>'state'
 WHEN 'UNKNOWN' THEN
  IF NEW.result-ARRAY['state','via','reason']<>'{}'::jsonb
   OR NEW.result->>'reason' IS DISTINCT FROM 'TRANSPORT_OR_PROTOCOL_UNKNOWN'
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-UNKNOWN'; END IF;
 WHEN 'UNOBSERVED' THEN
  IF NEW.result-ARRAY['state','via','reason']<>'{}'::jsonb OR NEW.result->>'via'<>'LOOKUP'
   OR NEW.result->>'reason' IS NULL OR NEW.result->>'reason' NOT IN('ABSENT','NOT_FOUND','UNKNOWN')
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-UNOBSERVED'; END IF;
 WHEN 'OBSERVED' THEN
  observation:=NEW.result->'observation'; descriptor:=observation->'descriptor';
  IF NEW.result-ARRAY['state','via','observation']<>'{}'::jsonb OR jsonb_typeof(observation) IS DISTINCT FROM 'object'
   OR observation-ARRAY['schemaVersion','providerId','attemptId','operationId','requestDigest','method','recordedAtNs','outcome','reason','descriptor','resultHex']<>'{}'::jsonb
   OR observation->>'schemaVersion' IS DISTINCT FROM '1'
   OR observation->>'providerId' IS DISTINCT FROM command.provider_id
   OR observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR observation->>'operationId' IS DISTINCT FROM command.operation_id::text
   OR observation->>'requestDigest' IS DISTINCT FROM command.attempt->>'requestDigest'
   OR observation->>'method' IS DISTINCT FROM command.attempt->'request'->>'method'
   OR observation->>'recordedAtNs' IS NULL OR observation->>'recordedAtNs' !~ '^[1-9][0-9]{0,19}$'
   OR mod((observation->>'recordedAtNs')::numeric,1000)<>0
   OR (observation->>'recordedAtNs')::numeric>18446744073709551615
   OR observation->>'outcome' IS NULL OR observation->>'outcome' NOT IN('SUCCEEDED','REJECTED')
   OR (command.stage='PREPARATION' AND observation->'resultHex' IS DISTINCT FROM 'null'::jsonb)
   OR (command.stage='POSSESSION' AND observation->>'outcome'='SUCCEEDED' AND (observation->>'resultHex' IS NULL OR observation->>'resultHex' !~ '^[0-9a-f]{128}$'))
   OR (observation->>'outcome'='REJECTED' AND observation->'resultHex' IS DISTINCT FROM 'null'::jsonb)
   OR NOT observation ?& ARRAY['reason','descriptor']
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-BINDING'; END IF;
  IF observation->>'outcome'='REJECTED' THEN
   IF observation->>'reason' IS NULL OR observation->>'reason' NOT IN('KEY_NOT_FOUND','REVOKED','EXPIRED','WRONG_SCOPE','FINGERPRINT_MISMATCH','INVALID_REQUEST','ATTEMPT_CONFLICT','NOT_APPLIED')
   THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-REJECTION'; END IF;
  ELSIF observation->'reason' IS DISTINCT FROM 'null'::jsonb OR jsonb_typeof(descriptor) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-DESCRIPTOR';
  END IF;
  IF descriptor IS DISTINCT FROM 'null'::jsonb THEN
   IF descriptor->>'participantId' IS DISTINCT FROM NEW.participant_id::text
    OR descriptor->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
    OR descriptor->>'environmentId' IS DISTINCT FROM command.binding->>'environmentId'
    OR descriptor->>'workloadCredentialId' IS DISTINCT FROM command.binding->>'successorCredentialId'
    OR descriptor->>'reference' IS DISTINCT FROM command.attempt->'request'->>'reference'
    OR descriptor->>'version' IS DISTINCT FROM command.attempt->'request'->>'version'
    OR descriptor->>'purpose' IS DISTINCT FROM command.attempt->>'purpose'
    OR descriptor->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
    OR descriptor->>'algorithm' IS DISTINCT FROM 'ES256'
    OR descriptor->>'publicKeySpkiHex' IS NULL OR descriptor->>'publicKeySpkiHex' !~ '^([0-9a-f]{2})+$'
    OR descriptor->>'fingerprint' IS DISTINCT FROM 'sha256:'||encode(sha256(decode(descriptor->>'publicKeySpkiHex','hex')),'hex')
   THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-DESCRIPTOR-SCOPE'; END IF;
   IF command.attempt->>'purpose'='pc.cose.identity-authority-envelope.v1' AND (
    descriptor->>'workloadCredentialEpoch' IS DISTINCT FROM command.attempt->'request'->>'workloadCredentialEpoch'
    OR descriptor->>'purposeCode' IS DISTINCT FROM '371' OR descriptor->>'schemaId' IS DISTINCT FROM '24034'
    OR descriptor->>'schemaVersion' IS DISTINCT FROM '1'
    OR descriptor->>'schemaDefinitionDigest' IS DISTINCT FROM command.attempt->'request'->>'schemaDefinitionDigest'
    OR descriptor->>'profileId' IS DISTINCT FROM command.attempt->'request'->>'profileId'
    OR descriptor->>'profileVersion' IS DISTINCT FROM '1'
    OR descriptor->>'profileDigest' IS DISTINCT FROM command.attempt->'request'->>'profileDigest')
   THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-ENVELOPE'; END IF;
  END IF;
  IF command.stage='POSSESSION' AND observation->>'outcome'='SUCCEEDED' THEN
   SELECT document INTO STRICT generation_document FROM control.workload_signing_handover_generation WHERE participant_id=NEW.participant_id
    AND privacy_domain_id=NEW.privacy_domain_id AND generation_id=command.generation_id;
   SELECT value INTO STRICT key_document FROM jsonb_array_elements(generation_document->'keys') WHERE value->'binding'->'replacement'->>'oldFingerprint'=command.predecessor_fingerprint;
   IF descriptor IS DISTINCT FROM key_document->'observation'->'descriptor'
    OR (observation->>'recordedAtNs')::numeric<(generation_document->>'issuedAtNs')::numeric
    OR (observation->>'recordedAtNs')::numeric>=(generation_document->>'expiresAtNs')::numeric
   THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-POSSESSION-OBSERVATION'; END IF;
  END IF;
 ELSE RAISE EXCEPTION 'DATA-6021-HANDOVER-OBSERVATION-STATE';
 END CASE;
 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_workload_signing_handover_observation() OWNER TO openpc_control_owner;

--
-- Name: guard_workload_signing_handover_preparation(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.guard_workload_signing_handover_preparation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE snapshot jsonb; expected jsonb; bound jsonb; source_document jsonb;
 owner_row control.workload_signing_handover; key_document jsonb; request_document jsonb; request_domain text;
BEGIN

 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id()<>'ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.operation_id<>openpc.current_operation_id() OR NEW.authority_snapshot_digest<>sha256(NEW.authority_snapshot)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-PREPARATION'; END IF;
 snapshot:=convert_from(NEW.authority_snapshot,'UTF8')::jsonb;
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR snapshot->>'decision' IS DISTINCT FROM 'ALLOW'
  OR jsonb_typeof(snapshot->'authorities') IS DISTINCT FROM 'array' OR jsonb_array_length(snapshot->'authorities')<>1
  OR (snapshot->>'recordedAtNs')::numeric>NEW.recorded_at_ns
  OR NEW.recorded_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'participant') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb) INTO expected
 FROM control.participant owner WHERE owner.participant_id=NEW.participant_id AND owner.participant_id IN
 (SELECT (dependency->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') dependency);
 IF snapshot->'dependencies'->'participant' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'privacy_domain') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb) INTO expected
 FROM control.privacy_domain owner WHERE owner.participant_id=NEW.participant_id AND owner.privacy_domain_id IN
 (SELECT (dependency->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') dependency);
 IF snapshot->'dependencies'->'privacy_domain' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'principal') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb) INTO expected
 FROM control.principal owner WHERE owner.participant_id=NEW.participant_id AND owner.principal_id IN
 (SELECT (dependency->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') dependency);
 IF snapshot->'dependencies'->'principal' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_role') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb) INTO expected
 FROM control.authority_role owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_role_id IN
 (SELECT (dependency->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') dependency);
 IF snapshot->'dependencies'->'authority_role' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'session') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb) INTO expected
 FROM control.session owner WHERE owner.participant_id=NEW.participant_id AND owner.session_id IN
 (SELECT (dependency->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') dependency);
 IF snapshot->'dependencies'->'session' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'authority_envelope') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb) INTO expected
 FROM control.authority_envelope owner WHERE owner.participant_id=NEW.participant_id AND owner.authority_envelope_id IN
 (SELECT (dependency->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') dependency);
 IF snapshot->'dependencies'->'authority_envelope' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'assignment') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb) INTO expected
 FROM control.assignment owner WHERE owner.participant_id=NEW.participant_id AND owner.assignment_id IN
 (SELECT (dependency->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') dependency);
 IF snapshot->'dependencies'->'assignment' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'delegation') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb) INTO expected
 FROM control.delegation owner WHERE owner.participant_id=NEW.participant_id AND owner.delegation_id IN
 (SELECT (dependency->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') dependency);
 IF snapshot->'dependencies'->'delegation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;

 IF jsonb_typeof(snapshot->'dependencies'->'credential') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb) INTO expected
 FROM control.credential owner WHERE owner.participant_id=NEW.participant_id AND owner.credential_id IN
 (SELECT (dependency->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') dependency);
 IF snapshot->'dependencies'->'credential' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-SNAPSHOT-ROW'; END IF;
 bound:=snapshot->'authorities'->0;
 IF bound->>'principalId' IS DISTINCT FROM NEW.maker_principal_id::text
  OR bound->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR bound->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id() OR bound->>'resourceId' IS DISTINCT FROM '*'
  OR NOT (snapshot->'dependencies'->'participant' @> jsonb_build_array(jsonb_build_object('participant_id',NEW.participant_id::text,'state','ACTIVE','authority_epoch',bound->>'participantEpoch')))
  OR NOT (snapshot->'dependencies'->'privacy_domain' @> jsonb_build_array(jsonb_build_object('privacy_domain_id',NEW.privacy_domain_id::text,'state','ACTIVE')))
  OR NOT (snapshot->'dependencies'->'principal' @> jsonb_build_array(jsonb_build_object('principal_id',NEW.maker_principal_id::text,'state','ACTIVE','authority_epoch',bound->>'principalEpoch')))
  OR NOT (snapshot->'dependencies'->'session' @> jsonb_build_array(jsonb_build_object('session_id',bound->>'sessionId','principal_id',NEW.maker_principal_id::text,'state','ACTIVE','session_epoch',bound->>'sessionEpoch')))
  OR NOT (snapshot->'dependencies'->'assignment' @> jsonb_build_array(jsonb_build_object('assignment_id',bound->>'assignmentId','state','ACTIVE','row_version',bound->>'assignmentRowVersion')))
  OR NOT (snapshot->'dependencies'->'authority_envelope' @> jsonb_build_array(jsonb_build_object('authority_envelope_id',bound->>'authorityEnvelopeId','state','ACTIVE','authority_epoch',bound->>'authorityEpoch')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-BOUND-PATH'; END IF;
 IF current_setting('transaction_isolation')<>'serializable' OR NOT EXISTS(
  WITH RECURSIVE path AS (
   SELECT a.principal_id terminal_principal_id,a.delegation_epoch,a.onward_delegation_depth remaining_depth,
    null::uuid delegation_id,array[]::uuid[] delegation_ids,array[a.principal_id] principal_ids
   FROM control.assignment a WHERE a.participant_id=NEW.participant_id AND a.assignment_id=(bound->>'assignmentId')::uuid
    AND a.state='ACTIVE' AND a.row_version::text=bound->>'assignmentRowVersion'
    AND a.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND a.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(a.action_intent_ids) AND NEW.privacy_domain_id::text=any(a.privacy_domain_ids)
    AND openpc.assignment_role_permits(a.participant_id,a.role_id,openpc.current_action_intent_id())
    AND openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
    AND openpc.administration_resource_permits(a.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,(bound->>'authorityEnvelopeId')::uuid)
   UNION ALL
   SELECT d.delegate_principal_id,d.delegation_epoch,d.onward_delegation_depth,d.delegation_id,
    path.delegation_ids||d.delegation_id,path.principal_ids||d.delegate_principal_id
   FROM path JOIN control.delegation d ON d.participant_id=NEW.participant_id
    AND ((path.delegation_id IS NULL AND d.parent_assignment_id=(bound->>'assignmentId')::uuid) OR d.parent_delegation_id=path.delegation_id)
    AND d.grantor_principal_id=path.terminal_principal_id AND d.state='ACTIVE' AND d.valid_during @> clock_timestamp()
    AND openpc.current_action_intent_id()=any(d.action_intent_ids) AND NEW.privacy_domain_id::text=any(d.privacy_domain_ids)
    AND '*'=any(d.resource_ids) AND d.onward_delegation_depth<path.remaining_depth
   WHERE path.remaining_depth>0 AND cardinality(path.delegation_ids)<32 AND NOT d.delegation_id=any(path.delegation_ids)
  ) SELECT 1 FROM path JOIN control.authority_envelope e ON e.participant_id=NEW.participant_id
   AND e.authority_envelope_id=(bound->>'authorityEnvelopeId')::uuid AND e.state='ACTIVE' AND e.authority_epoch::text=bound->>'authorityEpoch'
   AND ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      ))) AND e.valid_from<=clock_timestamp() AND (e.valid_until IS NULL OR e.valid_until>clock_timestamp())
   AND openpc.current_action_intent_id()=any(e.action_intent_ids) AND NEW.privacy_domain_id::text=any(e.privacy_domain_ids)
   AND openpc.administration_resource_permits(e.resource_ids,'*',openpc.current_action_intent_id(),NEW.participant_id,NEW.maker_principal_id,(bound->>'sessionId')::uuid,e.authority_envelope_id)
   JOIN control.principal actor ON actor.participant_id=NEW.participant_id AND actor.principal_id=NEW.maker_principal_id
    AND actor.state='ACTIVE' AND actor.authority_epoch::text=bound->>'principalEpoch' AND actor.kind IN('USER','PLATFORM_OPERATOR')
   JOIN control.session session ON session.participant_id=NEW.participant_id AND session.session_id=(bound->>'sessionId')::uuid
    AND session.principal_id=NEW.maker_principal_id AND session.state='ACTIVE' AND session.session_epoch::text=bound->>'sessionEpoch'
    AND session.participant_epoch::text=bound->>'participantEpoch' AND session.authority_epoch::text=bound->>'principalEpoch'
    AND session.delegation_epoch::text=bound->>'delegationEpoch' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
   WHERE path.terminal_principal_id=NEW.maker_principal_id AND path.delegation_epoch::text=bound->>'delegationEpoch'
    AND NOT EXISTS(SELECT 1 FROM unnest(path.principal_ids) dependency(id) WHERE NOT EXISTS(
      SELECT 1 FROM control.principal principal WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=dependency.id AND principal.state='ACTIVE'))
    AND NOT EXISTS(SELECT 1 FROM control.recovery_principal recovery WHERE recovery.participant_id=NEW.participant_id AND recovery.principal_id=NEW.maker_principal_id)
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-LIVE-AUTHORITY'; END IF;

 IF TG_TABLE_NAME='workload_signing_handover' THEN
  source_document:=NEW.source;
  IF NEW.request_canonical<>convert_to(openpc.signing_canonical_json(NEW.request),'UTF8')
   OR NEW.source_canonical<>convert_to(openpc.signing_canonical_json(NEW.source),'UTF8')
   OR NEW.request_digest<>sha256(convert_to('pc.identity.workload-signing-handover.request.v1','UTF8')||decode('00','hex')||NEW.request_canonical)
   OR NEW.source_digest<>sha256(convert_to('pc.identity.workload-signing-handover.source.v1','UTF8')||decode('00','hex')||NEW.source_canonical)
   OR NEW.request->>'actionIntentId' IS DISTINCT FROM openpc.current_action_intent_id()
   OR NEW.request->>'actionIntentDigest' IS DISTINCT FROM (SELECT 'sha256:'||encode(semantic_digest,'hex') FROM control.action_intent WHERE action_intent_id=openpc.current_action_intent_id())
   OR NEW.request->>'environmentId' IS DISTINCT FROM NEW.environment_id
   OR NEW.request->>'predecessorCredentialId' IS DISTINCT FROM NEW.predecessor_credential_id::text
   OR NEW.request->>'successorCredentialId' IS DISTINCT FROM NEW.successor_credential_id::text
   OR source_document->'issuer'->>'workloadCredentialId' IS DISTINCT FROM NEW.successor_credential_id::text
   OR source_document->'issuer'->>'workloadPrincipalId' IS DISTINCT FROM NEW.workload_principal_id::text
   OR source_document->'provenance'->>'predecessorCredentialId' IS DISTINCT FROM NEW.predecessor_credential_id::text
   OR source_document->'provenance'->>'successorCredentialId' IS DISTINCT FROM NEW.successor_credential_id::text
   OR source_document->'provenance'->>'credentialRotationOperationId' IS DISTINCT FROM NEW.request->>'credentialRotationOperationId'
   OR jsonb_array_length(source_document->'keys')<>jsonb_array_length(NEW.request->'replacements')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.request->'replacements') replacement
    WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source_document->'keys') old_key
      WHERE old_key-ARRAY['oldTrustPreimageBase64','oldCredentialEpoch','oldKeyValidFromNs','oldKeyValidUntilNs']=replacement))
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-REQUEST-CUSTODY'; END IF;
 ELSE
  IF NEW.stage<>'PREPARATION' OR NEW.generation_id IS NOT NULL OR NEW.preparation_attempt_id IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-PREPARATION-STAGE'; END IF;
  SELECT * INTO STRICT owner_row FROM control.workload_signing_handover
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND handover_id=NEW.handover_id
    AND maker_principal_id=NEW.maker_principal_id;
  source_document:=owner_row.source;
  SELECT value INTO STRICT key_document FROM jsonb_array_elements(source_document->'keys')
   WHERE value->>'oldFingerprint'=NEW.predecessor_fingerprint;
  request_document:=NEW.attempt->'request';
  request_domain:=CASE WHEN NEW.attempt->>'purpose'='pc.cose.identity-authority-envelope.v1'
    THEN 'pc.identity.envelope-key-rotation-request.v1' ELSE 'pc.control.signing-provider-request.v1' END;
  IF NEW.binding_canonical<>convert_to(openpc.signing_canonical_json(NEW.binding),'UTF8')
   OR NEW.attempt_canonical<>convert_to(openpc.signing_canonical_json(NEW.attempt),'UTF8')
   OR NEW.binding_digest<>sha256(convert_to('pc.identity.workload-signing-handover.provider-binding.v1','UTF8')||decode('00','hex')||NEW.binding_canonical)
   OR NEW.attempt_digest<>sha256(convert_to('pc.identity.workload-signing-handover.provider-attempt.v1','UTF8')||decode('00','hex')||NEW.attempt_canonical)
   OR NEW.binding->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR NEW.binding->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR NEW.binding->>'environmentId' IS DISTINCT FROM owner_row.environment_id
   OR NEW.binding->>'handoverId' IS DISTINCT FROM NEW.handover_id::text
   OR NEW.binding->>'sourceDigest' IS DISTINCT FROM 'sha256:'||encode(owner_row.source_digest,'hex')
   OR NEW.binding->>'successorCredentialId' IS DISTINCT FROM owner_row.successor_credential_id::text
   OR NEW.binding->>'successorCredentialEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadCredentialEpoch'
   OR NEW.binding->>'participantEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadParticipantEpoch'
   OR NEW.binding->>'principalEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadPrincipalEpoch'
   OR NEW.binding->>'providerId' IS DISTINCT FROM NEW.provider_id
   OR NEW.binding->'replacement' IS DISTINCT FROM key_document-ARRAY['oldTrustPreimageBase64','oldCredentialEpoch','oldKeyValidFromNs','oldKeyValidUntilNs']
   OR NEW.attempt->>'handoverId' IS DISTINCT FROM NEW.handover_id::text
   OR NEW.attempt->>'sourceDigest' IS DISTINCT FROM 'sha256:'||encode(owner_row.source_digest,'hex')
   OR NEW.attempt->>'predecessorFingerprint' IS DISTINCT FROM NEW.predecessor_fingerprint
   OR NEW.attempt->>'providerId' IS DISTINCT FROM NEW.provider_id
   OR NEW.attempt->>'bindingDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.binding_digest,'hex')
   OR NEW.attempt->>'signerRole' IS DISTINCT FROM key_document->>'signerRole'
   OR NEW.attempt->>'purpose' IS DISTINCT FROM key_document->>'purpose'
   OR NEW.attempt->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(request_domain,'UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(request_document),'UTF8')),'hex')
   OR request_document->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR request_document->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR request_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR request_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR request_document->>'environmentId' IS DISTINCT FROM owner_row.environment_id
   OR request_document->>'workloadCredentialId' IS DISTINCT FROM owner_row.successor_credential_id::text
   OR request_document->>'callerWorkloadCredentialId' IS DISTINCT FROM owner_row.successor_credential_id::text
   OR request_document->>'reference' IS DISTINCT FROM key_document->>'newReference'
   OR request_document->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
   OR request_document->>'purpose' IS DISTINCT FROM key_document->>'purpose'
   OR (request_document->>'reference') IS DISTINCT FROM regexp_replace(request_document->>'reference','#[^#]+$','')||'#'||(request_document->>'version')
   OR (NEW.attempt->>'purpose'='pc.cose.identity-authority-envelope.v1' AND (
     request_document->>'method' IS DISTINCT FROM 'PREPARE' OR request_document->>'rotationId' IS DISTINCT FROM NEW.handover_id::text
     OR request_document->>'workloadCredentialEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadCredentialEpoch'
     OR request_document->>'issuerParticipantEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadParticipantEpoch'
     OR request_document->>'issuerPrincipalEpoch' IS DISTINCT FROM source_document->'issuer'->>'workloadPrincipalEpoch'
     OR request_document->>'governanceDigest' IS DISTINCT FROM 'sha256:'||encode(owner_row.source_digest,'hex')))
   OR (NEW.attempt->>'purpose'<>'pc.cose.identity-authority-envelope.v1' AND request_document->>'method' IS DISTINCT FROM 'INSPECT')
  THEN RAISE EXCEPTION 'DATA-6021-HANDOVER-ATTEMPT-CUSTODY'; END IF;
 END IF;

 IF source_document->>'schema' IS DISTINCT FROM 'pc.identity.workload-signing-handover.source.v1'
  OR source_document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR source_document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NOT EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal USING(participant_id,principal_id)
   JOIN control.participant participant USING(participant_id)
   WHERE credential.participant_id=NEW.participant_id AND credential.credential_id=(source_document->'issuer'->>'workloadCredentialId')::uuid
    AND credential.principal_id=(source_document->'issuer'->>'workloadPrincipalId')::uuid
    AND credential.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
    AND participant.state='ACTIVE' AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND credential.credential_epoch::text=source_document->'issuer'->>'workloadCredentialEpoch'
    AND principal.authority_epoch::text=source_document->'issuer'->>'workloadPrincipalEpoch'
    AND participant.authority_epoch::text=source_document->'issuer'->>'workloadParticipantEpoch')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-HANDOVER-CURRENT-ISSUER'; END IF;

 RETURN NEW;
END $_$;


ALTER FUNCTION openpc.guard_workload_signing_handover_preparation() OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_activation_authority_current(uuid, uuid, jsonb, text, uuid, boolean); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_activation_authority_current(p_participant uuid, p_privacy uuid, p_captured jsonb, p_action text, p_resource uuid, p_live_session boolean) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb:=p_captured->'binding'; d jsonb:=p_captured->'durable';
 a control.assignment%ROWTYPE; e control.authority_envelope%ROWTYPE; r control.authority_role%ROWTYPE;
 pr control.principal%ROWTYPE; privacy control.privacy_domain%ROWTYPE; role_document jsonb; expected jsonb;
BEGIN
 IF b->>'participantId' IS DISTINCT FROM p_participant::text
  OR d#>>'{grant,privacyDomainId}' IS DISTINCT FROM p_privacy::text
  OR d#>>'{grant,actionIntentId}' IS DISTINCT FROM p_action
  OR d#>>'{grant,resourceId}' IS DISTINCT FROM p_resource::text THEN RETURN false; END IF;
 SELECT * INTO a FROM control.assignment WHERE participant_id=p_participant
  AND assignment_id=(b->>'assignmentId')::uuid;
 SELECT * INTO e FROM control.authority_envelope WHERE participant_id=p_participant
  AND authority_envelope_id=(b->>'authorityEnvelopeId')::uuid;
 SELECT * INTO r FROM control.authority_role WHERE participant_id=p_participant AND role_id=b->>'roleId';
 SELECT * INTO pr FROM control.principal WHERE participant_id=p_participant
  AND principal_id=(b->>'principalId')::uuid;
 SELECT * INTO privacy FROM control.privacy_domain WHERE participant_id=p_participant AND privacy_domain_id=p_privacy;
 IF a.assignment_id IS NULL OR e.authority_envelope_id IS NULL OR r.authority_role_id IS NULL
  OR pr.principal_id IS NULL OR privacy.privacy_domain_id IS NULL
  OR a.principal_id IS DISTINCT FROM pr.principal_id OR a.authority_envelope_id IS DISTINCT FROM e.authority_envelope_id
  OR a.role_id IS DISTINCT FROM r.role_id OR a.row_version::text IS DISTINCT FROM b->>'assignmentVersion'
  OR a.delegation_epoch::text IS DISTINCT FROM b->>'delegationEpoch' OR a.state<>'ACTIVE'
  OR NOT (a.valid_during @> clock_timestamp()) OR NOT a.maker_checker_required
  OR NOT (p_action=ANY(a.action_intent_ids)) OR NOT (p_privacy::text=ANY(a.privacy_domain_ids))
  OR NOT openpc.administration_resource_permits(a.resource_ids,p_resource::text,p_action,p_participant,pr.principal_id,(b->>'sessionId')::uuid,e.authority_envelope_id)
  OR NOT openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
  OR e.state<>'ACTIVE' OR e.valid_from>clock_timestamp() OR (e.valid_until IS NOT NULL AND e.valid_until<=clock_timestamp())
  OR NOT ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      )))
  OR e.authority_epoch::text IS DISTINCT FROM b->>'authorityEpoch' OR NOT e.maker_checker_required
  OR NOT (p_action=ANY(e.action_intent_ids)) OR NOT (p_privacy::text=ANY(e.privacy_domain_ids))
  OR NOT openpc.administration_resource_permits(e.resource_ids,p_resource::text,p_action,p_participant,pr.principal_id,(b->>'sessionId')::uuid,e.authority_envelope_id)
  OR NOT EXISTS(SELECT 1 FROM control.action_intent action WHERE action.action_intent_id=p_action
    AND action.risk_class=ANY(a.risk_classes) AND action.risk_class=ANY(e.risk_classes))
  OR NOT (e.principal_id=pr.principal_id OR (e.representation='TYPED_V1' AND e.principal_id IS NULL))
  OR r.state<>'ACTIVE' OR r.row_version::text IS DISTINCT FROM b->>'roleVersion' OR NOT (p_action=ANY(r.action_intent_ids))
  OR pr.state<>'ACTIVE' OR pr.kind<>'PLATFORM_OPERATOR' OR pr.authority_epoch::text IS DISTINCT FROM b->>'principalEpoch'
  OR privacy.state<>'ACTIVE'
  OR NOT EXISTS(SELECT 1 FROM control.participant p WHERE p.participant_id=p_participant
    AND p.state='ACTIVE' AND p.authority_epoch::text=b->>'participantEpoch')
 THEN RETURN false; END IF;
 expected:=jsonb_build_object('principalId',b->'principalId','participantEpoch',b->'participantEpoch',
  'principalEpoch',b->'principalEpoch','assignmentId',b->'assignmentId','assignmentRowVersion',b->'assignmentVersion',
  'authorityEnvelopeId',b->'authorityEnvelopeId','authorityEpoch',b->'authorityEpoch','delegationEpoch',b->'delegationEpoch',
  'privacyDomainId',p_privacy::text,'actionIntentId',p_action,'resourceId',p_resource::text);
 IF (d->'grant')-'catalogOperationId' IS DISTINCT FROM expected THEN RETURN false; END IF;
 expected:=jsonb_build_object('path',jsonb_build_object('delegationIds','[]'::jsonb,
   'principalIds',jsonb_build_array(pr.principal_id::text),'roleId',r.authority_role_id::text),
  'principals',jsonb_build_array(jsonb_build_array(pr.principal_id::text,pr.authority_epoch::text)),
  'privacy',privacy.row_version::text,'role',r.row_version::text,'delegations',NULL);
 IF d->'dependencies' IS DISTINCT FROM expected THEN RETURN false; END IF;
 role_document:=jsonb_build_object('roleId',r.role_id,'version',r.row_version::text,'actions',to_jsonb(r.action_intent_ids),
  'origin',r.origin,'createdByPrincipalId',r.created_by_principal_id::text,'creatorParticipantId',r.creator_participant_id::text,
  'bootstrapMandateId',r.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',r.bootstrap_platform_participant_id::text);
 IF b->>'roleDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.envelope-role-binding.v1','participantId',p_participant::text,'role',role_document)),'UTF8')),'hex')
  OR b->>'authorityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.envelope-authority-binding.v1','binding',b-'authorityDigest',
   'authority',(d->'grant')||jsonb_build_object('sessionId',b->'sessionId','sessionEpoch',b->'sessionEpoch'),'durable',d)),'UTF8')),'hex')
 THEN RETURN false; END IF;
 IF p_live_session AND NOT EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=p_participant
  AND s.session_id=(b->>'sessionId')::uuid AND s.principal_id=pr.principal_id AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
  AND s.state='ACTIVE' AND s.session_epoch::text=b->>'sessionEpoch' AND s.participant_epoch::text=b->>'participantEpoch'
  AND s.authority_epoch::text=b->>'principalEpoch' AND s.delegation_epoch::text=b->>'delegationEpoch'
  AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp())
 THEN RETURN false; END IF;
 RETURN true;
END $$;


ALTER FUNCTION openpc.identity_envelope_activation_authority_current(p_participant uuid, p_privacy uuid, p_captured jsonb, p_action text, p_resource uuid, p_live_session boolean) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_activation_intent_current(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_activation_intent_current(p_participant uuid, p_privacy uuid, p_candidate uuid, p_approval uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
   AND a.subject_type='CONFIGURATION_CANDIDATE' AND a.subject_id=c.mutation_candidate_id
   AND a.subject_digest=c.candidate_digest AND a.subject_version=c.expected_revision
   AND a.action_intent_id=c.action_intent_id AND a.maker_principal_id=c.maker_principal_id
  WHERE c.participant_id=p_participant AND c.privacy_domain_id=p_privacy
   AND c.mutation_candidate_id=p_candidate AND a.approval_request_id=p_approval
   AND c.action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND c.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
   AND c.operation_class='ACTIVATE' AND c.resource_type='participant' AND c.expected_revision=3
   AND c.candidate_document=jsonb_build_object('envelopeId',c.resource_id::text)
   AND c.state='APPROVED' AND c.consumed_operation_id IS NULL AND c.expires_at>clock_timestamp()
   AND a.state='APPROVED' AND a.expires_at>clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM control.mutation_candidate successor
    WHERE successor.participant_id=c.participant_id AND successor.privacy_domain_id=c.privacy_domain_id
     AND successor.predecessor_candidate_id=c.mutation_candidate_id))
$$;


ALTER FUNCTION openpc.identity_envelope_activation_intent_current(p_participant uuid, p_privacy uuid, p_candidate uuid, p_approval uuid) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_actor_wire(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_actor_wire(p_value jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('1',openpc.identity_envelope_authority_wire(p_value->'authority'),
  '2',openpc.business_uuid((p_value->>'stepUpChallengeId')::uuid),
  '3',openpc.business_bytes(decode(substr(p_value->>'stepUpEvidenceDigest',8),'hex')),
  '4',openpc.business_uuid((p_value->>'signerCredentialId')::uuid),
  '5',(p_value->>'signerCredentialEpoch')::numeric)
$$;


ALTER FUNCTION openpc.identity_envelope_actor_wire(p_value jsonb) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_authority_wire(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_authority_wire(p_value jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('1',openpc.business_uuid((p_value->>'participantId')::uuid),'2',to_jsonb((p_value->>'participantEpoch')::numeric),'3',openpc.business_uuid((p_value->>'principalId')::uuid),'4',to_jsonb((p_value->>'principalEpoch')::numeric),'5',openpc.business_uuid((p_value->>'sessionId')::uuid),'6',to_jsonb((p_value->>'sessionEpoch')::numeric),'7',openpc.business_uuid((p_value->>'assignmentId')::uuid),'8',to_jsonb((p_value->>'assignmentVersion')::numeric),'9',openpc.business_uuid((p_value->>'authorityEnvelopeId')::uuid),'10',to_jsonb((p_value->>'authorityEpoch')::numeric),'11',to_jsonb((p_value->>'delegationEpoch')::numeric),'12',to_jsonb(p_value->>'roleId'),'13',to_jsonb((p_value->>'roleVersion')::numeric),'14',openpc.business_bytes(decode(substr(p_value->>'roleDigest',8),'hex')),'15',openpc.business_bytes(decode(substr(p_value->>'authorityDigest',8),'hex')))
$$;


ALTER FUNCTION openpc.identity_envelope_authority_wire(p_value jsonb) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_binding_current(uuid, jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_binding_current(p_enrollment uuid, p_intent jsonb, p_binding jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT p_binding->>'schema'='pc.identity.identity-envelope-recovery-lease' AND p_binding->>'schemaVersion'='1'
  AND p_binding->>'purpose'='IDENTITY_ENVELOPE_SIGNER_REPAIR_ONLY' AND p_binding->'postReviewRequired'='true'::jsonb
  AND p_binding-ARRAY['schema','schemaVersion','purpose','recoveryId','enrollmentId','enrollmentDigest','intentDigest','rotationId',
    'creationOperationId','activationOperationId','executorPrincipalId','issuer','oldTrustDigest','selectionAdmissionVersion',
    'proofIds','proofEvidenceDigest','validFrom','validUntil','postReviewRequired','lifetimes']='{}'::jsonb
  AND p_binding->'lifetimes' IS NOT DISTINCT FROM p_intent->'lifetimes'
  AND (NOT (p_binding ? 'lifetimes') OR p_binding#>>'{lifetimes,profile}'='LOCAL_QA_10X')
  AND p_binding->>'recoveryId'=p_intent->>'recoveryId' AND p_binding->>'enrollmentId'=p_intent->>'enrollmentId'
  AND p_binding->>'enrollmentDigest'=p_intent->>'enrollmentDigest'
  AND p_binding->>'intentDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p_intent),'UTF8')),'hex')
  AND p_binding->>'rotationId'=p_intent->>'rotationId' AND p_binding->>'creationOperationId'=p_intent->>'creationOperationId'
  AND p_binding->>'oldTrustDigest'=p_intent->>'oldTrustDigest' AND p_binding->>'selectionAdmissionVersion'=p_intent->>'selectionAdmissionVersion'
  AND (p_binding->>'validFrom')::timestamptz>=(p_intent->>'validFrom')::timestamptz
  AND (p_binding->>'validFrom')::timestamptz<=clock_timestamp() AND (p_binding->>'validUntil')::timestamptz>clock_timestamp()
  AND (p_binding->>'validUntil')::timestamptz<=(p_intent->>'validUntil')::timestamptz
  AND (p_binding->>'validUntil')::timestamptz<=(p_binding->>'validFrom')::timestamptz+coalesce((p_binding#>>'{lifetimes,leaseMs}')::bigint,900000)*interval '1 millisecond'
  AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
   JOIN control.principal issuer ON issuer.participant_id=e.participant_id AND issuer.principal_id::text=e.document->>'issuerPrincipalId'
    AND issuer.state='ACTIVE' AND issuer.kind='WORKLOAD' AND issuer.authority_epoch=(p_intent->>'sourceIssuerPrincipalEpoch')::numeric+1
   JOIN control.participant participant ON participant.participant_id=e.participant_id AND participant.state='ACTIVE'
    AND participant.authority_epoch=(p_intent->>'sourceParticipantEpoch')::numeric
   JOIN control.credential credential ON credential.participant_id=e.participant_id AND credential.principal_id=issuer.principal_id
    AND credential.credential_id::text=e.document#>>'{request,workloadCredentialId}' AND credential.kind='WORKLOAD_MTLS'
    AND credential.state='ACTIVE' AND credential.credential_epoch=(p_intent->>'sourceIssuerCredentialEpoch')::numeric
    AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>=(p_binding->>'validUntil')::timestamptz)
   WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
    AND e.enrollment_id::text=p_binding->>'enrollmentId' AND e.document_digest=decode(substr(p_binding->>'enrollmentDigest',8),'hex')
    AND e.state='ACTIVE' AND e.row_version=1 AND e.valid_until>=(p_binding->>'validUntil')::timestamptz
    AND openpc.identity_envelope_recovery_source_current(e.enrollment_id)
    AND openpc.identity_envelope_recovery_rotation_selection_current(e.enrollment_id,p_binding)
    AND p_binding->>'executorPrincipalId'=e.document#>>'{recoveryPrincipal,principalId}'
    AND p_binding->'issuer'=jsonb_build_object('participantId',e.participant_id::text,'privacyDomainId',e.privacy_domain_id::text,
      'workloadCredentialId',credential.credential_id::text,'workloadPrincipalId',issuer.principal_id::text,
      'workloadParticipantEpoch',participant.authority_epoch::text,'workloadPrincipalEpoch',issuer.authority_epoch::text,
      'workloadCredentialEpoch',credential.credential_epoch::text,'workloadPublicKeyDigest','sha256:'||encode(credential.public_key_digest,'hex'),
      'credentialValidFromNs',(floor(extract(epoch FROM credential.valid_from)*1000000)*1000)::text,
      'credentialValidUntilNs',(floor(extract(epoch FROM credential.valid_until)*1000000)*1000)::text)
    AND NOT EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=e.participant_id AND s.principal_id=issuer.principal_id
      AND s.state IN ('ACTIVE','STEP_UP_REQUIRED') AND s.authority_epoch<= (p_intent->>'sourceIssuerPrincipalEpoch')::numeric)
    AND jsonb_array_length(p_binding->'proofIds')=4
    AND p_binding->>'proofEvidenceDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
      (SELECT jsonb_agg(jsonb_build_object('proofId',proof.proof_id::text,'principalId',proof.principal_id::text,
        'principalEpoch',proof.principal_epoch::text,'credentialId',proof.credential_id::text,'credentialEpoch',proof.credential_epoch::text,
        'sessionId',proof.session_id::text,'sessionEpoch',proof.session_epoch::text,'phase',proof.phase,
        'intentDigest','sha256:'||encode(proof.intent_digest,'hex'),
        'verifiedAt',to_char(proof.verified_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'assertionDigest','sha256:'||encode(proof.assertion_digest,'hex')) ORDER BY names.ordinality)
       FROM jsonb_array_elements_text(p_binding->'proofIds') WITH ORDINALITY names(proof_id,ordinality)
       JOIN control.platform_recovery_proof proof ON proof.proof_id::text=names.proof_id
        AND proof.participant_id=e.participant_id AND proof.privacy_domain_id=e.privacy_domain_id
        AND proof.recovery_id::text=p_binding->>'recoveryId')),'UTF8')),'hex')
    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_binding->'proofIds'))=4
    AND (SELECT count(*) FROM control.platform_recovery_proof proof WHERE proof.participant_id=e.participant_id
      AND proof.privacy_domain_id=e.privacy_domain_id AND proof.recovery_id::text=p_binding->>'recoveryId'
      AND proof.intent_digest=decode(substr(p_binding->>'intentDigest',8),'hex'))=4
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_binding->'proofIds') supplied(proof_id)
      WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
       JOIN control.principal human ON human.participant_id=proof.participant_id AND human.principal_id=proof.principal_id
        AND human.state='ACTIVE' AND human.authority_epoch=proof.principal_epoch
       JOIN control.credential authenticator ON authenticator.participant_id=human.participant_id AND authenticator.principal_id=human.principal_id
        AND authenticator.credential_id=proof.credential_id AND authenticator.credential_epoch=proof.credential_epoch
        AND authenticator.state='ACTIVE' AND authenticator.kind='WEBAUTHN'
       JOIN control.session s ON s.participant_id=human.participant_id AND s.principal_id=human.principal_id AND s.session_id=proof.session_id
        AND s.authority_epoch=human.authority_epoch AND s.participant_epoch=participant.authority_epoch AND s.session_epoch=proof.session_epoch
        AND s.state='ACTIVE' AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
       WHERE proof.proof_id::text=supplied.proof_id AND proof.participant_id=e.participant_id AND proof.privacy_domain_id=e.privacy_domain_id
        AND proof.recovery_id::text=p_binding->>'recoveryId' AND proof.intent_digest=decode(substr(p_binding->>'intentDigest',8),'hex')
        AND s.idle_expires_at>=(p_binding->>'validUntil')::timestamptz AND s.absolute_expires_at>=(p_binding->>'validUntil')::timestamptz
        AND authenticator.valid_from<=clock_timestamp() AND (authenticator.valid_until IS NULL OR authenticator.valid_until>=(p_binding->>'validUntil')::timestamptz)
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_build_array(e.document->'recoveryPrincipal')||e.document->'custodians') actor
          WHERE actor->>'principalId'=human.principal_id::text AND actor->>'credentialId'=authenticator.credential_id::text
           AND actor->>'principalEpoch'=human.authority_epoch::text AND actor->>'credentialEpoch'=authenticator.credential_epoch::text)
        AND (e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator hardware
          WHERE hardware.participant_id=human.participant_id AND hardware.principal_id=human.principal_id AND hardware.credential_id=authenticator.credential_id)))))
$$;


ALTER FUNCTION openpc.identity_envelope_recovery_binding_current(p_enrollment uuid, p_intent jsonb, p_binding jsonb) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_installation_source_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_installation_source_current(p_enrollment uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 RETURN current_user='openpc_control_owner'
 AND pg_has_role(session_user,'openpc_control_owner','MEMBER')
 AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
 AND openpc.current_action_intent_id() IN ('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment enrollment
  JOIN control.identity_envelope_recovery_custody_trust trust ON trust.custody_trust_id=enrollment.custody_trust_id
   AND trust.participant_id=enrollment.participant_id AND trust.privacy_domain_id=enrollment.privacy_domain_id
   AND trust.platform_context_id=enrollment.platform_context_id AND trust.document_digest=enrollment.custody_trust_digest
   AND trust.state='ACTIVE' AND trust.row_version=1
   AND trust.valid_from<=enrollment.valid_from AND trust.valid_until>=enrollment.valid_until
  JOIN control.platform_context root ON root.platform_context_id=enrollment.platform_context_id
   AND root.owner_participant_id=enrollment.participant_id AND root.state='ACTIVE'
   AND root.authority_epoch::text=enrollment.document->>'rootEpoch'
   AND root.row_version::text=enrollment.document->>'rootRevision'
  JOIN (
   SELECT platform_context_id,owner_participant_id,installation_privacy_domain_id,
    platform_authority_epoch,environment_id,installation_digest,admission_digest FROM control.platform_envelope_scope
   UNION ALL
   SELECT platform_context_id,owner_participant_id,installation_privacy_domain_id,
    platform_authority_epoch,environment_id,installation_digest,admission_digest FROM control.platform_envelope_scope_successor
   UNION ALL SELECT platform_context_id,owner_participant_id,installation_privacy_domain_id,platform_authority_epoch,environment_id,installation_digest,admission_digest FROM control.root_expiry_recovery_scope
  ) scope ON scope.platform_context_id=root.platform_context_id AND scope.owner_participant_id=enrollment.participant_id
   AND scope.installation_privacy_domain_id=enrollment.privacy_domain_id AND scope.platform_authority_epoch=root.authority_epoch
   AND 'sha256:'||encode(scope.admission_digest,'hex')=enrollment.document->>'rootDigest'
   AND scope.environment_id=enrollment.document->>'installationEnvironmentId'
   AND scope.installation_digest=enrollment.document->>'installationDigest'
  JOIN control.operations_installation installation ON installation.participant_id=enrollment.participant_id
   AND installation.privacy_domain_id=enrollment.privacy_domain_id AND installation.environment_id=scope.environment_id
   AND installation.installation_digest=scope.installation_digest AND installation.state='ACTIVE'
  WHERE enrollment.enrollment_id=p_enrollment AND openpc.matches_participant(enrollment.participant_id)
   AND openpc.matches_privacy(enrollment.privacy_domain_id) AND enrollment.state='ACTIVE' AND enrollment.row_version=1
   AND enrollment.document->>'schema'='pc.identity.identity-envelope-recovery-enrollment'
   AND enrollment.document->>'purpose'='pc.installation.identity-envelope-repair-custody.v1'
   AND trust.document->>'purpose'=enrollment.document->>'purpose'
   AND trust.document->>'installationEnvironmentId'=scope.environment_id
   AND trust.document->>'installationDigest'=scope.installation_digest
   AND trust.document->>'profile'=enrollment.document->>'profile'
   AND enrollment.document_digest=sha256(convert_to(openpc.signing_canonical_json(enrollment.document),'UTF8'))
   AND trust.document_digest=sha256(convert_to(openpc.signing_canonical_json(trust.document),'UTF8'))
   AND installation.installation_bytes=convert_to(openpc.signing_canonical_json(installation.installation),'UTF8')
   AND installation.installation_digest='sha256:'||encode(sha256(installation.installation_bytes),'hex')
   AND openpc.operations_source_authentication_valid(installation.installation)
   AND enrollment.valid_from<=clock_timestamp() AND enrollment.valid_until>clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement replacement
    WHERE replacement.platform_context_id=root.platform_context_id AND replacement.state='WITHDRAWING'));
END $$;


ALTER FUNCTION openpc.identity_envelope_recovery_installation_source_current(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_lease_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_lease_current(p_recovery uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery
  AND c.state='ACTIVE' AND c.signer_repair_enrollment_id IS NOT NULL
  AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)
  AND c.activation_operation_id::text=c.lease_bindings->>'activationOperationId'
  AND c.activation_evidence_digest=sha256(c.activation_evidence_cbor) AND octet_length(c.activation_cose)>0
  AND openpc.identity_envelope_recovery_binding_current(c.signer_repair_enrollment_id,c.intent,c.lease_bindings));
$$;


ALTER FUNCTION openpc.identity_envelope_recovery_lease_current(p_recovery uuid) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_old_selection_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_old_selection_current(p_enrollment uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=e.participant_id
   AND selection.privacy_domain_id=e.privacy_domain_id AND selection.environment_id=e.document#>>'{request,environmentId}'
   AND selection.signer_id=e.document#>>'{request,oldFingerprint}' AND selection.admission_version::text=e.document->>'selectionAdmissionVersion'
   AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  JOIN control.identity_envelope_signing_grant grant_row ON grant_row.participant_id=selection.participant_id
   AND grant_row.privacy_domain_id=selection.privacy_domain_id AND grant_row.signer_id=selection.signer_id
   AND grant_row.profile_digest=selection.profile_digest AND grant_row.signing_purpose_code=371
  JOIN control.business_signing_key key ON key.participant_id=selection.participant_id AND key.privacy_domain_id=selection.privacy_domain_id
   AND key.signer_id=selection.signer_id AND key.signing_purpose_code=371 AND key.secret_reference=e.document#>>'{request,oldReference}'
   AND key.environment_id=selection.environment_id AND (
    (key.workload_credential_id::text=e.document#>>'{request,workloadCredentialId}'
     AND key.workload_credential_epoch::text=e.document->>'issuerCredentialEpoch')
    OR EXISTS (
    SELECT 1 FROM control.credential predecessor
    JOIN control.credential successor ON successor.participant_id=predecessor.participant_id
      AND successor.rotated_from_credential_id=predecessor.credential_id
      AND successor.principal_id=predecessor.principal_id AND successor.audience=predecessor.audience
    JOIN control.mutation_candidate candidate ON candidate.participant_id=predecessor.participant_id
      AND candidate.privacy_domain_id=e.privacy_domain_id
      AND candidate.resource_id=predecessor.credential_id
      AND candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
      AND candidate.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
      AND candidate.state='CONSUMED' AND candidate.consumed_operation_id IS NOT NULL
      AND candidate.candidate_document=jsonb_build_object('replacedCredentialId',predecessor.credential_id::text,
        'credentialId',successor.credential_id::text,
        'publicKeySpkiDer',replace(encode(successor.public_key_spki_der,'base64'),E'\n',''))
      AND candidate.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(candidate.candidate_document),'UTF8'))
    JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id
      AND approval.privacy_domain_id=candidate.privacy_domain_id AND approval.subject_type='CONFIGURATION_CANDIDATE'
      AND approval.subject_id=candidate.mutation_candidate_id AND approval.subject_digest=candidate.candidate_digest
      AND approval.maker_principal_id=candidate.maker_principal_id AND approval.state='APPROVED'
      AND approval.subject_version=candidate.expected_revision AND approval.action_intent_id=candidate.action_intent_id
    JOIN control.approval_decision_record decision ON decision.participant_id=approval.participant_id
      AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
      AND decision.decision='APPROVE' AND decision.candidate_digest=candidate.candidate_digest
      AND decision.approver_principal_id<>approval.maker_principal_id AND decision.cose_sign1 IS NOT NULL
      AND decision.aggregate_version=approval.subject_version
    JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
      AND evidence.privacy_domain_id=candidate.privacy_domain_id AND evidence.operation_id=candidate.consumed_operation_id
      AND evidence.action_intent_id=candidate.action_intent_id AND evidence.catalog_operation_id=candidate.catalog_operation_id
      AND evidence.aggregate_type='workload-credential' AND evidence.aggregate_id=predecessor.credential_id
      AND evidence.candidate_digest=candidate.candidate_digest AND evidence.principal_id=approval.maker_principal_id
      AND evidence.checker_principal_id=decision.approver_principal_id AND evidence.approval_request_id=approval.approval_request_id
      AND evidence.evidence_digest=sha256(evidence.evidence_cbor) AND evidence.cose_sign1 IS NOT NULL
      AND evidence.evidence_cbor=decision.evidence_cbor AND evidence.cose_sign1=decision.cose_sign1
      AND evidence.signer_credential_id=decision.signer_credential_id
      AND evidence.webauthn_assertion_binding_digest IS NOT NULL AND evidence.mfa_challenge_id IS NOT NULL
    JOIN control.idempotency_record committed ON committed.participant_id=evidence.participant_id
      AND committed.privacy_domain_id=evidence.privacy_domain_id AND committed.operation_id=evidence.operation_id
      AND committed.action_intent_id=evidence.action_intent_id AND committed.catalog_operation_id=evidence.catalog_operation_id
      AND committed.principal_id=evidence.principal_id
      AND committed.terminal_state='COMMITTED' AND committed.input_digest=evidence.candidate_digest
      AND committed.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
      AND committed.result_payload->>'credentialId'=successor.credential_id::text
      AND committed.result_payload->>'replacedCredentialId'=predecessor.credential_id::text
      AND committed.result_payload->>'principalId'=successor.principal_id::text
      AND committed.result_payload->>'workloadId'=successor.audience
      AND committed.result_payload->>'workloadEpoch'=successor.credential_epoch::text
      AND committed.result_payload->>'state'='ACTIVE'
    JOIN control.outbox_event event ON event.participant_id=evidence.participant_id
      AND event.privacy_domain_id=evidence.privacy_domain_id AND event.aggregate_type=evidence.aggregate_type
      AND event.aggregate_id=evidence.aggregate_id AND event.payload_cbor=evidence.evidence_cbor
      AND event.event_type='openpc.identity.workload-credential.mutation.committed.v1'
      AND event.payload_digest=evidence.evidence_digest AND event.cose_sign1=evidence.cose_sign1
      AND event.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
    WHERE predecessor.participant_id=e.participant_id
      AND predecessor.credential_id=key.workload_credential_id AND successor.credential_id=(e.document#>>'{request,workloadCredentialId}')::uuid
      AND predecessor.kind='WORKLOAD_MTLS' AND predecessor.state='REVOKED'
      AND successor.kind='WORKLOAD_MTLS' AND successor.state='ACTIVE'
      AND predecessor.credential_epoch=key.workload_credential_epoch+1
      AND successor.credential_epoch=predecessor.credential_epoch
      AND successor.credential_epoch=(e.document->>'issuerCredentialEpoch')::numeric
      AND successor.valid_from<=clock_timestamp() AND successor.valid_until>clock_timestamp()

  ))
   AND 'sha256:'||encode(key.trust_digest,'hex')=e.document->>'oldTrustDigest'
  JOIN control.business_signing_key_state lifecycle ON lifecycle.participant_id=key.participant_id
   AND lifecycle.privacy_domain_id=key.privacy_domain_id AND lifecycle.signer_id=key.signer_id AND lifecycle.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant receipt WHERE receipt.participant_id=key.participant_id
    AND receipt.privacy_domain_id=key.privacy_domain_id AND receipt.signer_id=key.signer_id));
$$;


ALTER FUNCTION openpc.identity_envelope_recovery_old_selection_current(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: platform_recovery_case; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.platform_recovery_case (
    recovery_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    enrollment_id uuid,
    enrollment_revision numeric(20,0) NOT NULL,
    enrollment_digest bytea NOT NULL,
    intent jsonb NOT NULL,
    intent_digest bytea NOT NULL,
    planned_record_ids jsonb NOT NULL,
    lease_bindings jsonb,
    state text DEFAULT 'DRAFT'::text NOT NULL,
    row_version numeric(20,0) DEFAULT 1 NOT NULL,
    valid_from timestamp(6) with time zone NOT NULL,
    valid_until timestamp(6) with time zone NOT NULL,
    activated_at timestamp(6) with time zone,
    activation_operation_id uuid,
    activation_evidence_cbor bytea,
    activation_evidence_digest bytea,
    activation_cose bytea,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    completion_operation_id uuid,
    completion_result jsonb,
    signer_repair_enrollment_id uuid,
    reviewed_by_principal_id uuid,
    reviewed_at timestamp(6) with time zone,
    review_operation_id uuid,
    review_note_digest bytea,
    CONSTRAINT platform_recovery_case_activation_ck CHECK ((((activated_at IS NULL) AND (activation_operation_id IS NULL) AND (activation_evidence_cbor IS NULL) AND (activation_evidence_digest IS NULL) AND (activation_cose IS NULL) AND (lease_bindings IS NULL) AND (state <> ALL (ARRAY['ACTIVE'::text, 'COMPLETED'::text]))) OR ((activated_at IS NOT NULL) AND (activation_operation_id IS NOT NULL) AND (activation_evidence_cbor IS NOT NULL) AND (activation_evidence_digest IS NOT NULL) AND (activation_cose IS NOT NULL) AND (lease_bindings IS NOT NULL)))),
    CONSTRAINT platform_recovery_case_completion_ck CHECK ((((completion_operation_id IS NULL) AND (completion_result IS NULL)) OR ((state = 'COMPLETED'::text) AND ((intent ->> 'schema'::text) = ANY (ARRAY['pc.identity.discovery-certificate-recovery-intent'::text, 'pc.identity.identity-envelope-recovery-intent'::text])) AND (completion_operation_id IS NOT NULL) AND (completion_result IS NOT NULL) AND (jsonb_typeof(completion_result) = 'object'::text)))),
    CONSTRAINT platform_recovery_case_digests_ck CHECK (((octet_length(enrollment_digest) = 32) AND (octet_length(intent_digest) = 32) AND ((activation_evidence_digest IS NULL) OR (octet_length(activation_evidence_digest) = 32)))),
    CONSTRAINT platform_recovery_case_enrollment_purpose_ck CHECK ((((enrollment_id IS NOT NULL) AND (signer_repair_enrollment_id IS NULL) AND ((intent ->> 'schema'::text) = ANY (ARRAY['pc.identity.platform-recovery-intent'::text, 'pc.identity.discovery-certificate-recovery-intent'::text]))) OR ((enrollment_id IS NULL) AND (signer_repair_enrollment_id IS NOT NULL) AND ((intent ->> 'schema'::text) = 'pc.identity.identity-envelope-recovery-intent'::text)))),
    CONSTRAINT platform_recovery_case_post_review_ck CHECK (((num_nonnulls(reviewed_by_principal_id, reviewed_at, review_operation_id, review_note_digest) = 0) OR ((num_nonnulls(reviewed_by_principal_id, reviewed_at, review_operation_id, review_note_digest) = 4) AND (signer_repair_enrollment_id IS NOT NULL) AND (activated_at IS NOT NULL) AND (state = ANY (ARRAY['COMPLETED'::text, 'REVOKED'::text, 'EXPIRED'::text])) AND (reviewed_at >= activated_at) AND (octet_length(review_note_digest) = 32)))),
    CONSTRAINT platform_recovery_case_state_ck CHECK (((state = ANY (ARRAY['DRAFT'::text, 'REQUESTED'::text, 'ACTIVE'::text, 'COMPLETED'::text, 'REVOKED'::text, 'EXPIRED'::text])) AND (row_version > (0)::numeric) AND (enrollment_revision > (0)::numeric))),
    CONSTRAINT platform_recovery_case_supersession_ck CHECK (((NOT (intent ? 'supersession'::text)) OR ((jsonb_typeof((intent -> 'supersession'::text)) = 'object'::text) AND ((intent #>> '{supersession,recoveryId}'::text[]) <> (recovery_id)::text) AND ((intent #>> '{supersession,replacementId}'::text[]) = (intent #>> '{preparation,supersedes,replacementId}'::text[])) AND ((intent #>> '{supersession,expectedRevision}'::text[]) = (intent #>> '{preparation,supersedes,expectedRevision}'::text[])) AND ((intent #>> '{supersession,successorDigest}'::text[]) = (intent #>> '{preparation,supersedes,successorDigest}'::text[]))))),
    CONSTRAINT platform_recovery_case_window_ck CHECK (((valid_until > valid_from) AND (valid_until <= (valid_from +
CASE
    WHEN ((intent #>> '{lifetimes,profile}'::text[]) = 'LOCAL_QA_10X'::text) THEN '2 days'::interval
    WHEN (((intent ->> 'schema'::text) <> 'pc.identity.identity-envelope-recovery-intent'::text) AND ((intent #>> '{lifetimes,profile}'::text[]) = 'LOCAL_QA'::text)) THEN '01:00:00'::interval
    ELSE '00:15:00'::interval
END)))),
    CONSTRAINT platform_recovery_continuation_purpose_ck CHECK (((NOT (intent ? 'continuation'::text)) OR (((intent ->> 'schema'::text) = 'pc.identity.platform-recovery-intent'::text) AND (jsonb_typeof((intent -> 'continuation'::text)) = 'object'::text) AND (NOT (intent ? 'supersession'::text)) AND ((NOT ((intent -> 'preparation'::text) ? 'supersedes'::text)) OR COALESCE(((intent ->> 'completionSourceDigest'::text) ~ '^sha256:[0-9a-f]{64}$'::text), false)) AND ((intent #>> '{continuation,recoveryId}'::text[]) <> (recovery_id)::text) AND ((intent #>> '{continuation,enrollmentId}'::text[]) <> (enrollment_id)::text) AND ((intent #>> '{continuation,replacementId}'::text[]) = (intent #>> '{preparation,replacementId}'::text[])))))
);

ALTER TABLE ONLY control.platform_recovery_case FORCE ROW LEVEL SECURITY;


ALTER TABLE control.platform_recovery_case OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_proofs_current(control.platform_recovery_case, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_proofs_current(p_case control.platform_recovery_case, p_activation uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
 SELECT p_case.signer_repair_enrollment_id IS NOT NULL
 AND openpc.matches_participant(p_case.participant_id) AND openpc.matches_privacy(p_case.privacy_domain_id)
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  WHERE e.enrollment_id=p_case.signer_repair_enrollment_id AND e.participant_id=p_case.participant_id
   AND e.privacy_domain_id=p_case.privacy_domain_id AND e.state='ACTIVE' AND e.row_version=p_case.enrollment_revision
   AND e.document_digest=p_case.enrollment_digest AND openpc.identity_envelope_recovery_source_current(e.enrollment_id)
   AND jsonb_array_length(e.document->'custodians')=2
   AND (SELECT count(*) FROM control.platform_recovery_proof proof WHERE proof.participant_id=e.participant_id
    AND proof.recovery_id=p_case.recovery_id)=4
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(
    jsonb_build_array(jsonb_build_object('signer',e.document->'recoveryPrincipal','phase','REQUEST'),
     jsonb_build_object('signer',e.document->'recoveryPrincipal','phase','ACTIVATE')) ||
     (SELECT jsonb_agg(jsonb_build_object('signer',custodian,'phase','APPROVE')) FROM jsonb_array_elements(e.document->'custodians') custodian)) required
    WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
     JOIN control.platform_recovery_challenge h ON h.participant_id=proof.participant_id AND h.recovery_id=proof.recovery_id
      AND h.challenge_id=proof.challenge_id AND h.proof_id=proof.proof_id AND h.consumed_at IS NOT NULL
     JOIN control.principal p ON p.participant_id=proof.participant_id AND p.principal_id=proof.principal_id
      AND p.state='ACTIVE' AND p.kind IN ('USER','PLATFORM_OPERATOR') AND p.authority_epoch=proof.principal_epoch
     JOIN control.credential c ON c.participant_id=p.participant_id AND c.principal_id=p.principal_id
      AND c.credential_id=proof.credential_id AND c.credential_epoch=proof.credential_epoch AND c.kind='WEBAUTHN' AND c.state='ACTIVE'
      AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
     JOIN control.session s ON s.participant_id=p.participant_id AND s.principal_id=p.principal_id
      AND s.session_id=proof.session_id AND s.session_epoch=proof.session_epoch AND s.authority_epoch=p.authority_epoch
      AND s.participant_epoch=(p_case.intent->>'sourceParticipantEpoch')::numeric AND s.state='ACTIVE'
      AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
      AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp()
     WHERE proof.participant_id=p_case.participant_id AND proof.privacy_domain_id=p_case.privacy_domain_id
      AND proof.recovery_id=p_case.recovery_id AND proof.intent_digest=p_case.intent_digest
      AND proof.phase=required->>'phase' AND proof.principal_id::text=required#>>'{signer,principalId}'
      AND proof.credential_id::text=required#>>'{signer,credentialId}'
      AND proof.principal_epoch::text=required#>>'{signer,principalEpoch}' AND proof.credential_epoch::text=required#>>'{signer,credentialEpoch}'
      AND (proof.phase<>'ACTIVATE' OR proof.proof_id=p_activation)
      AND proof.verified_at>=p_case.valid_from AND proof.verified_at<=clock_timestamp()
      AND proof.verified_at>clock_timestamp()-make_interval(secs=>h.verified_proof_max_age_ms/1000.0)
      AND (h.verified_proof_max_age_ms=300000 OR (h.verified_proof_max_age_ms=3000000
        AND h.duration_profile='LOCAL_QA_10X' AND s.duration_profile='LOCAL_QA_10X' AND h.expires_at>clock_timestamp()))
      AND (e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator hardware
        WHERE hardware.participant_id=c.participant_id AND hardware.principal_id=c.principal_id AND hardware.credential_id=c.credential_id))))
 );
$$;


ALTER FUNCTION openpc.identity_envelope_recovery_proofs_current(p_case control.platform_recovery_case, p_activation uuid) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_rotation_selection_current(uuid, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_rotation_selection_current(p_enrollment uuid, p_binding jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 IF openpc.identity_envelope_recovery_old_selection_current(p_enrollment) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.signing_key_rotation r ON r.participant_id=e.participant_id AND r.privacy_domain_id=e.privacy_domain_id
    AND r.rotation_id::text=p_binding->>'rotationId' AND r.recovery_case_id::text=p_binding->>'recoveryId'
    AND r.old_signer_id=e.document#>>'{request,oldFingerprint}' AND r.approval_request_id IS NULL
    AND r.state IN('CUTOVER_FENCED','OBSERVING','OLD_REVOKED','OLD_RETIRED','COMPLETE')
  JOIN control.identity_envelope_rotation_step cutover ON cutover.participant_id=r.participant_id AND cutover.privacy_domain_id=r.privacy_domain_id
    AND cutover.rotation_id=r.rotation_id AND cutover.recovery_id=r.recovery_case_id AND cutover.state='COMMITTED'
    AND cutover.from_revision=5 AND cutover.from_state='VERIFIED' AND cutover.to_state='CUTOVER_FENCED'
    AND cutover.authority_binding=jsonb_build_object('kind','IDENTITY_ENVELOPE_SIGNER_RECOVERY','enrollment',e.document,'lease',p_binding)
    AND cutover.evidence_digest=sha256(cutover.evidence_cbor) AND octet_length(cutover.cose_sign1)>0
  JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id
    AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
    AND selection.admission_version=(p_binding->>'selectionAdmissionVersion')::numeric+1
    AND selection.admission_version::text=cutover.result->>'selectionAdmissionVersion'
    AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  JOIN control.business_signing_key k ON k.participant_id=selection.participant_id AND k.privacy_domain_id=selection.privacy_domain_id
    AND k.signer_id=selection.signer_id AND k.signing_purpose_code=371 AND k.environment_id=selection.environment_id
    AND 'sha256:'||encode(k.trust_digest,'hex')=cutover.result->>'trustDigest'
  JOIN control.business_signing_key_state life ON life.participant_id=k.participant_id AND life.privacy_domain_id=k.privacy_domain_id
    AND life.signer_id=k.signer_id AND life.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
    AND k.workload_credential_id::text=p_binding#>>'{issuer,workloadCredentialId}'
    AND k.workload_credential_epoch::text=p_binding#>>'{issuer,workloadCredentialEpoch}'
    AND k.envelope_workload_participant_epoch::text=p_binding#>>'{issuer,workloadParticipantEpoch}'
    AND k.envelope_workload_principal_epoch::text=p_binding#>>'{issuer,workloadPrincipalEpoch}'
    AND k.valid_from_ns<=floor(extract(epoch from clock_timestamp())*1000000)*1000 AND k.valid_until_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
    AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=k.participant_id AND ordinary.privacy_domain_id=k.privacy_domain_id AND ordinary.signer_id=k.signer_id));
END $$;


ALTER FUNCTION openpc.identity_envelope_recovery_rotation_selection_current(p_enrollment uuid, p_binding jsonb) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_source_current(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_recovery_source_current(p_enrollment uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 RETURN openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.identity_envelope_recovery_custody_trust t ON t.custody_trust_id=e.custody_trust_id
   AND t.participant_id=e.participant_id AND t.privacy_domain_id=e.privacy_domain_id
   AND t.platform_context_id=e.platform_context_id AND t.document_digest=e.custody_trust_digest
   AND t.state='ACTIVE' AND t.row_version=1 AND t.valid_from<=e.valid_from AND t.valid_until>=e.valid_until
  JOIN control.platform_context p ON p.platform_context_id=e.platform_context_id
   AND p.owner_participant_id=e.participant_id AND p.state='ACTIVE'
   AND p.authority_epoch::text=e.document->>'rootEpoch' AND p.row_version::text=e.document->>'rootRevision'
  JOIN control.operations_installation i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
   AND i.environment_id=e.document->>'installationEnvironmentId' AND i.installation_digest=e.document->>'installationDigest'
   AND i.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND e.state='ACTIVE' AND e.row_version=1 AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp()
   AND e.document_digest=sha256(convert_to(openpc.signing_canonical_json(e.document),'UTF8'))
   AND t.document_digest=sha256(convert_to(openpc.signing_canonical_json(t.document),'UTF8'))
   AND i.installation_bytes=convert_to(openpc.signing_canonical_json(i.installation),'UTF8')
   AND i.installation_digest='sha256:'||encode(sha256(i.installation_bytes),'hex')
   AND openpc.operations_source_authentication_valid(i.installation)
   AND NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.platform_context_id=p.platform_context_id AND r.state='WITHDRAWING'));
END $$;


ALTER FUNCTION openpc.identity_envelope_recovery_source_current(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_rotation_step; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.identity_envelope_rotation_step (
    operation_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    rotation_id uuid NOT NULL,
    recovery_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    from_revision numeric(20,0) NOT NULL,
    from_state text NOT NULL,
    to_state text NOT NULL,
    authority_binding jsonb NOT NULL,
    authority_digest bytea NOT NULL,
    state text DEFAULT 'READY'::text NOT NULL,
    result jsonb,
    evidence_cbor bytea,
    evidence_digest bytea,
    cose_sign1 bytea,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp(6) with time zone,
    completed_at timestamp(6) with time zone,
    consumer_activation_operation_id uuid,
    consumer_observation_operation_id uuid,
    CONSTRAINT identity_envelope_rotation_step_consumer_ck CHECK ((((from_state = 'CUTOVER_FENCED'::text) AND (from_revision = (6)::numeric) AND (to_state = 'OBSERVING'::text) AND (consumer_activation_operation_id IS NOT NULL)) OR ((from_state <> 'CUTOVER_FENCED'::text) AND (consumer_activation_operation_id IS NULL)))),
    CONSTRAINT identity_envelope_rotation_step_consumer_observation_ck CHECK ((((from_state = ANY (ARRAY['OBSERVING'::text, 'OLD_REVOKED'::text, 'OLD_RETIRED'::text])) AND (consumer_observation_operation_id IS NOT NULL)) OR ((from_state <> ALL (ARRAY['OBSERVING'::text, 'OLD_REVOKED'::text, 'OLD_RETIRED'::text])) AND (consumer_observation_operation_id IS NULL)))),
    CONSTRAINT identity_envelope_rotation_step_digest_ck CHECK (((octet_length(authority_digest) = 32) AND (from_revision > (0)::numeric))),
    CONSTRAINT identity_envelope_rotation_step_evidence_ck CHECK ((((state = ANY (ARRAY['READY'::text, 'STARTED'::text, 'WRITE_AMBIGUITY'::text])) AND (result IS NULL) AND (evidence_cbor IS NULL) AND (evidence_digest IS NULL) AND (cose_sign1 IS NULL) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['COMMITTED'::text, 'FAILED'::text])) AND (result IS NOT NULL) AND (octet_length(evidence_cbor) > 0) AND (octet_length(evidence_digest) = 32) AND (octet_length(cose_sign1) > 0) AND (completed_at IS NOT NULL)))),
    CONSTRAINT identity_envelope_rotation_step_start_ck CHECK ((((state = 'READY'::text) AND (started_at IS NULL)) OR ((state <> 'READY'::text) AND (started_at IS NOT NULL)))),
    CONSTRAINT identity_envelope_rotation_step_state_ck CHECK ((state = ANY (ARRAY['READY'::text, 'STARTED'::text, 'COMMITTED'::text, 'WRITE_AMBIGUITY'::text, 'FAILED'::text])))
);

ALTER TABLE ONLY control.identity_envelope_rotation_step FORCE ROW LEVEL SECURITY;


ALTER TABLE control.identity_envelope_rotation_step OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_rotation_step_bound(control.identity_envelope_rotation_step); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_rotation_step_bound(p_step control.identity_envelope_rotation_step) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control'
    AS $$
 SELECT openpc.matches_participant(p_step.participant_id) AND openpc.matches_privacy(p_step.privacy_domain_id)
  AND EXISTS(SELECT 1 FROM control.signing_key_rotation r JOIN control.platform_recovery_case c
   ON c.recovery_id=r.recovery_case_id AND c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
   JOIN control.identity_envelope_recovery_enrollment e ON e.enrollment_id=c.signer_repair_enrollment_id
    AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
   WHERE r.rotation_id=p_step.rotation_id AND r.participant_id=p_step.participant_id AND r.privacy_domain_id=p_step.privacy_domain_id
    AND c.recovery_id=p_step.recovery_id AND c.activated_at IS NOT NULL
    AND r.request=e.document->'request' AND r.approval_request_id IS NULL
    AND r.rotation_id::text=c.lease_bindings->>'rotationId'
    AND p_step.principal_id::text=c.lease_bindings->>'executorPrincipalId'
    AND p_step.authority_binding=jsonb_build_object('kind','IDENTITY_ENVELOPE_SIGNER_RECOVERY','enrollment',e.document,'lease',c.lease_bindings)
    AND p_step.authority_digest=sha256(convert_to(openpc.signing_canonical_json(p_step.authority_binding),'UTF8')));
$$;


ALTER FUNCTION openpc.identity_envelope_rotation_step_bound(p_step control.identity_envelope_rotation_step) OWNER TO openpc_control_owner;

