--
-- Name: identity_envelope_scope_valid(bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_envelope_scope_valid(p_bytes bytea) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE scope jsonb; module jsonb; items jsonb; item jsonb; previous bytea; current_bytes bytea;
 dimension integer; module_id integer; value text;
BEGIN
 scope:=openpc.business_cbor(p_bytes);
 IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(scope) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
 FOR dimension IN 3..7 LOOP
  IF jsonb_typeof(scope->dimension::text)<>'number' OR (scope->>dimension::text)!~'^(0|[1-9][0-9]{0,19})$' THEN RETURN false; END IF;
 END LOOP;
 IF (scope->>'3')::numeric>18446744073709551615 OR (scope->>'4')::numeric>18446744073709551615
   OR (scope->>'4')::numeric<=(scope->>'3')::numeric OR mod((scope->>'3')::numeric,1000)<>0
   OR mod((scope->>'4')::numeric,1000)<>0 OR (scope->>'5')::numeric NOT IN(0,1)
   OR (scope->>'6')::numeric NOT IN(0,1) OR (scope->>'7')::numeric>32 THEN RETURN false; END IF;
 FOR module_id IN 1..2 LOOP
  module:=scope->module_id::text;
  IF jsonb_typeof(module) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(module) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
  FOR dimension IN 1..7 LOOP
   items:=module->dimension::text; previous:=NULL;
   IF jsonb_typeof(items)<>'array' OR jsonb_array_length(items)>256 THEN RETURN false; END IF;
   FOR item IN SELECT v FROM jsonb_array_elements(items) v LOOP
    IF dimension IN(1,2) THEN
     IF jsonb_typeof(item)<>'object' OR jsonb_typeof(item->'bytes') IS DISTINCT FROM 'string' OR item<>jsonb_build_object('bytes',item->>'bytes')
       OR (item->>'bytes')!~'^[0-9a-f]{12}[1-8][0-9a-f]{3}[89ab][0-9a-f]{15}$' THEN RETURN false; END IF;
     current_bytes:=decode(item->>'bytes','hex');
    ELSE
     IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF;
     value:=item#>>'{}'; current_bytes:=convert_to(value,'UTF8');
     IF octet_length(current_bytes) NOT BETWEEN 1 AND 160 OR value!~'^[A-Za-z0-9][A-Za-z0-9:._/-]*$' THEN RETURN false; END IF;
     IF dimension=6 AND value NOT IN('BREAK_GLASS','HIGH','LOW','STANDARD') THEN RETURN false; END IF;
     IF dimension=7 AND module_id=1 AND value!~'^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN RETURN false; END IF;
     IF dimension=7 AND module_id=2 AND value NOT IN('CALL_RESULT_DISCLOSURE','GAS_ESTIMATE_DISCLOSURE','ACCESS_LIST_DISCLOSURE',
       'UNSIGNED_TRANSACTION_PREPARATION','SIGNED_TRANSACTION_SUBMISSION','OPERATION_STATUS_DISCLOSURE','MULTI_CALL_SIMULATION_DISCLOSURE') THEN RETURN false; END IF;
    END IF;
    IF previous IS NOT NULL AND current_bytes<=previous THEN RETURN false; END IF;
    previous:=current_bytes;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN true;
END $_$;


ALTER FUNCTION openpc.identity_envelope_scope_valid(p_bytes bytea) OWNER TO openpc_control_owner;

--
-- Name: identity_runtime_cose_key_id(bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.identity_runtime_cose_key_id(evidence bytea, cose bytea) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE outer_item jsonb; fields jsonb; header jsonb; envelope jsonb; key_id text;
BEGIN
 IF octet_length(cose)=0 OR get_byte(cose,0)<>210 THEN RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-COSE-TAG'; END IF;
 outer_item:=openpc.business_cbor_item(cose,1,0);
 IF (outer_item->>'next')::integer<>octet_length(cose) THEN RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-COSE-TRAILING'; END IF;
 fields:=outer_item->'value';
 IF jsonb_typeof(fields) IS DISTINCT FROM 'array' OR jsonb_array_length(fields)<>4 OR
    fields->1 IS DISTINCT FROM '{}'::jsonb OR length(fields->3->>'bytes') IS DISTINCT FROM 128 THEN
  RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-COSE-BINDING'; END IF;
 envelope:=openpc.business_cbor(decode(fields->2->>'bytes','hex'));
 IF envelope IS DISTINCT FROM jsonb_build_object('0',1,'1',3002,'2',2,'3',openpc.business_cbor(evidence)) THEN
  RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-COSE-BINDING'; END IF;
 header:=openpc.business_cbor(decode(fields->0->>'bytes','hex'));
 IF header IS DISTINCT FROM jsonb_build_object('1',-8,'2',jsonb_build_array(100,101,102,103),'3','application/pc+cbor',
    '4',header->'4','100',3002,'101',2,'102','pc.cose.identity-runtime.v2','103',2) OR
    length(header->'4'->>'bytes') IS DISTINCT FROM 142 THEN
  RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-TYPED-PURPOSE-BINDING'; END IF;
 key_id:=convert_from(decode(header->'4'->>'bytes','hex'),'UTF8');
 IF key_id !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'DATA-6021-AUTHORIZATION-KEY-ID'; END IF;
 RETURN key_id;
END $_$;


ALTER FUNCTION openpc.identity_runtime_cose_key_id(evidence bytea, cose bytea) OWNER TO openpc_control_owner;

--
-- Name: index_candidate_archive_parts(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.index_candidate_archive_parts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE item jsonb; index integer:=0;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.manifest->'chunks') LOOP
  INSERT INTO control.evidence_candidate_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
   VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,item->>'recordId');
  index:=index+1;
 END LOOP;
 INSERT INTO control.evidence_candidate_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
  VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,NEW.record_id);
 RETURN NULL;
END $$;


