ALTER FUNCTION openpc.lock_fact_workload_context() OWNER TO openpc_control_owner;

--
-- Name: lock_fact_workload_context(boolean); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_fact_workload_context(p_fail_fast boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-FACT_ARTIFACTS_UPDATE_RESOURCE-V1' OR p_fail_fast IS NULL THEN
  RAISE EXCEPTION 'PC-AUTH-0005-FACT-SOURCE';
 END IF;
 IF p_fail_fast THEN
  PERFORM 1 FROM control.participant
   WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' AND archived_at IS NULL FOR UPDATE NOWAIT;
 ELSE
  PERFORM 1 FROM control.participant
   WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' AND archived_at IS NULL FOR UPDATE;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-FACT-SOURCE'; END IF;
 IF p_fail_fast THEN
  PERFORM 1 FROM control.privacy_domain WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND state='ACTIVE' FOR SHARE NOWAIT;
 ELSE
  PERFORM 1 FROM control.privacy_domain WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND state='ACTIVE' FOR SHARE;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-FACT-SOURCE'; END IF;
EXCEPTION WHEN lock_not_available THEN
 IF p_fail_fast THEN RAISE EXCEPTION 'PC-DATA-6007'; ELSE RAISE; END IF;
END $$;


ALTER FUNCTION openpc.lock_fact_workload_context(p_fail_fast boolean) OWNER TO openpc_control_owner;

--
-- Name: identity_envelope_recovery_enrollment; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.identity_envelope_recovery_enrollment (
    enrollment_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid CONSTRAINT identity_envelope_recovery_enrollmen_privacy_domain_id_not_null NOT NULL,
    custody_trust_id uuid NOT NULL,
    custody_trust_digest bytea CONSTRAINT identity_envelope_recovery_enroll_custody_trust_digest_not_null NOT NULL,
    platform_context_id uuid CONSTRAINT identity_envelope_recovery_enrollm_platform_context_id_not_null NOT NULL,
    document jsonb NOT NULL,
    document_digest bytea NOT NULL,
    signature bytea NOT NULL,
    state text DEFAULT 'ACTIVE'::text NOT NULL,
    row_version numeric(20,0) DEFAULT 1 NOT NULL,
    valid_from timestamp(6) with time zone NOT NULL,
    valid_until timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp(6) with time zone,
    revocation_reason_digest bytea,
    CONSTRAINT identity_envelope_recovery_enrollment_digest_ck CHECK (((octet_length(document_digest) = 32) AND (octet_length(custody_trust_digest) = 32) AND (octet_length(signature) = 64) AND ((revocation_reason_digest IS NULL) OR (octet_length(revocation_reason_digest) = 32)))),
    CONSTRAINT identity_envelope_recovery_enrollment_state_ck CHECK (((state = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text])) AND (row_version > (0)::numeric))),
    CONSTRAINT identity_envelope_recovery_enrollment_time_ck CHECK (((valid_until > valid_from) AND (((state = 'ACTIVE'::text) AND (revoked_at IS NULL) AND (revocation_reason_digest IS NULL)) OR ((state = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revocation_reason_digest IS NOT NULL)))))
);

ALTER TABLE ONLY control.identity_envelope_recovery_enrollment FORCE ROW LEVEL SECURITY;


ALTER TABLE control.identity_envelope_recovery_enrollment OWNER TO openpc_control_owner;

--
-- Name: lock_identity_envelope_recovery_enrollment(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_identity_envelope_recovery_enrollment(p_enrollment uuid) RETURNS SETOF control.identity_envelope_recovery_enrollment
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.platform_context p JOIN control.identity_envelope_recovery_enrollment e
  ON e.platform_context_id=p.platform_context_id AND e.participant_id=p.owner_participant_id
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND p.state='ACTIVE' FOR SHARE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.identity_envelope_recovery_custody_trust t
  JOIN control.identity_envelope_recovery_enrollment e ON e.custody_trust_id=t.custody_trust_id
   AND e.participant_id=t.participant_id AND e.privacy_domain_id=t.privacy_domain_id AND e.custody_trust_digest=t.document_digest
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  FOR SHARE OF t;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 -- Declare the affected issuer write before session/credential children. The
 -- parent Participant write serializes same-Participant recovery/cutover.
 PERFORM 1 FROM control.principal issuer JOIN control.identity_envelope_recovery_enrollment e
  ON e.participant_id=issuer.participant_id AND issuer.principal_id::text=e.document->>'issuerPrincipalId'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND issuer.state='ACTIVE' AND issuer.kind='WORKLOAD' FOR UPDATE OF issuer;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 RETURN QUERY SELECT e.* FROM control.identity_envelope_recovery_enrollment e
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  FOR SHARE;
END $$;


ALTER FUNCTION openpc.lock_identity_envelope_recovery_enrollment(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: lock_indexer_dispatch_source(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_indexer_dispatch_source(p_target_id uuid, p_capsule_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE v_source_id uuid; v_plan_id uuid; v_provider_id uuid; v_configuration_digest text;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_READ_RPC-V1'
   OR p_capsule_digest !~ '^sha256:[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-INDEXER-SOURCE';
 END IF;
 PERFORM openpc.lock_cigl_publication_participant();
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('module-admission:'||
   openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0));
 SELECT generation.projection_plan_id,generation.provider_profile_id,work.configuration_digest
  INTO STRICT v_plan_id,v_provider_id,v_configuration_digest
 FROM control.runtime_target target
 JOIN control.runtime_activation_observation observation
  ON observation.runtime_target_id=target.runtime_target_id
   AND observation.participant_id=target.participant_id AND observation.privacy_domain_id=target.privacy_domain_id
   AND observation.capsule_digest=target.active_generation_digest
 JOIN control.runtime_configuration_generation generation
  ON generation.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
   AND generation.participant_id=target.participant_id AND generation.privacy_domain_id=target.privacy_domain_id
   AND generation.runtime_target_id=target.runtime_target_id AND generation.generation_digest=observation.generation_digest
 JOIN control.configuration_work work ON work.configuration_work_id=observation.configuration_work_id
  AND work.participant_id=target.participant_id AND work.privacy_domain_id=target.privacy_domain_id
  AND work.runtime_target_id=target.runtime_target_id
  AND work.runtime_configuration_generation_id=generation.runtime_configuration_generation_id
  AND work.generation_digest=generation.generation_digest
  AND work.policy_generation_digest=generation.policy_generation_digest
  AND work.predecessor_digest IS NOT DISTINCT FROM generation.predecessor_digest
  AND work.xds_version_digest=observation.xds_version_digest
  AND work.operation_id=observation.operation_id AND work.execution_attempt_id=observation.execution_attempt_id
  AND work.result_receipt_digest=observation.activation_receipt_digest
 WHERE target.runtime_target_id=p_target_id
  AND openpc.matches_participant(target.participant_id) AND openpc.matches_privacy(target.privacy_domain_id)
  AND target.state='ACTIVE_MATCHED' AND target.active_generation_digest=p_capsule_digest
  AND target.desired_generation_digest=p_capsule_digest AND target.xds_version_digest=observation.xds_version_digest
  AND target.policy_generation_digest=generation.policy_generation_digest
  AND generation.state='ACTIVE' AND work.state='COMPLETED' AND work.work_kind='RUNTIME_ACTIVATION'
  AND work.execution_started_at IS NOT NULL
 FOR SHARE OF target,generation,work;
 SELECT projection.indexer_profile_id INTO STRICT v_source_id FROM control.projection_plan projection
 WHERE projection.projection_plan_id=v_plan_id
  AND openpc.matches_participant(projection.participant_id) AND openpc.matches_privacy(projection.privacy_domain_id)
 FOR SHARE;
 PERFORM 1 FROM control.indexer_profile source WHERE source.indexer_profile_id=v_source_id
  AND openpc.matches_participant(source.participant_id) AND openpc.matches_privacy(source.privacy_domain_id)
 FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-INDEXER-SOURCE'; END IF;
 PERFORM 1 FROM control.provider_profile provider
 JOIN control.provider_probe_observation observation ON observation.observation_id=provider.qualification_observation_id
  AND observation.provider_profile_id=provider.provider_profile_id
  AND observation.participant_id=provider.participant_id AND observation.privacy_domain_id=provider.privacy_domain_id
 WHERE provider.provider_profile_id=v_provider_id
  AND openpc.matches_participant(provider.participant_id) AND openpc.matches_privacy(provider.privacy_domain_id)
 FOR SHARE OF provider,observation;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-INDEXER-SOURCE'; END IF;
 PERFORM 1 FROM control.runtime_configuration_input input
 WHERE openpc.matches_participant(input.participant_id) AND openpc.matches_privacy(input.privacy_domain_id)
  AND input.configuration_digest=decode(substr(v_configuration_digest,8),'hex') AND input.selected
 FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-INDEXER-SOURCE'; END IF;
 RETURN v_plan_id;
END $_$;


ALTER FUNCTION openpc.lock_indexer_dispatch_source(p_target_id uuid, p_capsule_digest text) OWNER TO openpc_control_owner;

--
-- Name: lock_indexer_qualified_provider(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_indexer_qualified_provider(p_provider_id uuid, p_artifact_digest text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    AS $_$
DECLARE expiry_ns bigint;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF openpc.current_action_intent_id() NOT IN ('ACT-RUNTIME_READ_RPC-V1','ACT-CANDIDATE_WRITE-V1','ACT-FACT_ARTIFACTS_UPDATE_RESOURCE-V1')
  OR p_artifact_digest !~ '^sha256:[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-INDEXER-PROVIDER';
 END IF;
 SELECT (extract(epoch from observation.valid_until)*1000000000)::bigint INTO STRICT expiry_ns
 FROM control.provider_profile provider
 JOIN control.provider_probe_observation observation ON observation.observation_id=provider.qualification_observation_id
  AND observation.provider_profile_id=provider.provider_profile_id
  AND observation.participant_id=provider.participant_id AND observation.privacy_domain_id=provider.privacy_domain_id
 JOIN control.configuration_work qualification ON qualification.resource_id=provider.provider_profile_id
  AND qualification.participant_id=provider.participant_id AND qualification.privacy_domain_id=provider.privacy_domain_id
  AND qualification.work_kind='PROVIDER_QUALIFICATION' AND qualification.state='COMPLETED'
 WHERE provider.provider_profile_id=p_provider_id AND provider.behavior_fingerprint=p_artifact_digest
  AND openpc.matches_participant(provider.participant_id) AND openpc.matches_privacy(provider.privacy_domain_id)
  AND provider.state IN ('QUALIFIED','ACTIVE') AND provider.revision=observation.observed_revision+2
  AND observation.state='OBSERVED' AND observation.input_digest=provider.behavior_fingerprint
  AND observation.observation_id::text=qualification.result_receipt->>'liveObservationId'
  AND observation.observation_digest=qualification.result_receipt->>'liveObservationDigest'
  AND observation.observation=qualification.result_receipt->'liveObservation'
  AND qualification.result_receipt->>'artifactDigest'=provider.behavior_fingerprint
  AND observation.valid_until>clock_timestamp()
 FOR SHARE OF provider,observation,qualification;
 RETURN expiry_ns;
EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL;
END $_$;


ALTER FUNCTION openpc.lock_indexer_qualified_provider(p_provider_id uuid, p_artifact_digest text) OWNER TO openpc_control_owner;

--
-- Name: lock_native_value_authority(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_native_value_authority(wallet_id uuid, actor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-DEPLOYMENT_SUBMISSIONS_CREATE_RESOURCE-V1' OR pg_trigger_depth()=0 THEN
  RAISE EXCEPTION 'PC-AUTH-0002-NATIVE-VALUE-CUSTODY';
 END IF;
 PERFORM 1 FROM control.wallet_binding wallet
 JOIN control.participant participant USING(participant_id)
 JOIN control.principal principal ON principal.participant_id=wallet.participant_id AND principal.principal_id=actor_id
 WHERE wallet.wallet_binding_id=wallet_id AND wallet.subject_id=actor_id
  AND openpc.matches_participant(wallet.participant_id) AND openpc.matches_privacy(wallet.privacy_domain_id)
 FOR SHARE OF wallet,participant,principal;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0002-NATIVE-VALUE-CUSTODY'; END IF;
 PERFORM 1 FROM control.credential credential WHERE openpc.matches_participant(credential.participant_id)
  AND credential.principal_id=actor_id AND credential.kind='WORKLOAD_MTLS' FOR SHARE;
END $$;


ALTER FUNCTION openpc.lock_native_value_authority(wallet_id uuid, actor_id uuid) OWNER TO openpc_control_owner;

--
-- Name: lock_platform_recovery_completion_assignment_read(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_platform_recovery_completion_assignment_read(pid uuid, privacy uuid, actor uuid, envelope_id uuid, assignment_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE selected_recovery uuid; selected_until timestamptz;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(pid) OR NOT openpc.matches_privacy(privacy)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_READ_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ADMINISTRATION-ASSIGNMENT-READ'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.authority_envelope e JOIN control.platform_recovery_case c
   ON c.participant_id=e.participant_id AND c.recovery_id=e.recovery_case_id
   WHERE e.participant_id=pid AND e.authority_envelope_id=envelope_id AND c.intent ? 'completionSourceDigest')
 THEN RETURN NULL; END IF;
 SELECT recovery.recovery_id,recovery.valid_until INTO selected_recovery,selected_until
 FROM control.authority_envelope envelope
 JOIN control.platform_recovery_case recovery ON recovery.participant_id=envelope.participant_id
  AND recovery.recovery_id=envelope.recovery_case_id
 JOIN control.platform_recovery_enrollment enrollment ON enrollment.participant_id=recovery.participant_id
  AND enrollment.privacy_domain_id=recovery.privacy_domain_id AND enrollment.enrollment_id=recovery.enrollment_id
 JOIN control.platform_scope_replacement replacement ON replacement.participant_id=recovery.participant_id
  AND replacement.privacy_domain_id=recovery.privacy_domain_id
  AND replacement.replacement_id::text=recovery.intent#>>'{preparation,replacementId}'
  AND replacement.state='WITHDRAWING' AND replacement.candidate=recovery.intent->'preparation'
 JOIN control.platform_context root ON root.platform_context_id=replacement.platform_context_id
  AND root.owner_participant_id=pid AND root.state='ACTIVE'
  AND root.authority_epoch=replacement.predecessor_epoch AND root.row_version=replacement.expected_root_revision
 WHERE envelope.participant_id=pid AND recovery.privacy_domain_id=privacy
  AND envelope.principal_id=actor AND envelope.authority_envelope_id=envelope_id
  AND envelope.representation='RECOVERY_V1' AND recovery.state='ACTIVE'
  AND recovery.valid_from<=clock_timestamp() AND recovery.valid_until>clock_timestamp()
  AND recovery.intent->>'schema'='pc.identity.platform-recovery-intent'
  AND enrollment.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION'
  AND enrollment.document->>'schemaVersion'='3'
  AND enrollment.document#>>'{source,activatedHandoff,schemaVersion}'='1'
  AND recovery.intent->>'completionSourceDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(enrollment.document#>'{source,activatedHandoff}'),'UTF8')),'hex')
  AND openpc.platform_recovery_envelope_current(envelope.authority_envelope_id)
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(recovery.intent#>'{preparation,administrators}') administrator
    WHERE administrator->>'principalId'=actor::text)
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(recovery.intent#>'{preparation,administrators}') administrator
    WHERE administrator->>'assignmentId'=assignment_id::text)
 FOR SHARE OF root,enrollment,recovery,replacement NOWAIT;
 IF NOT FOUND THEN RETURN false; END IF;
 -- Locks serialize closure and replacement commit; recheck lease freshness after acquisition.
 RETURN selected_until>clock_timestamp() AND openpc.platform_recovery_envelope_current(envelope_id);
END $$;


ALTER FUNCTION openpc.lock_platform_recovery_completion_assignment_read(pid uuid, privacy uuid, actor uuid, envelope_id uuid, assignment_id uuid) OWNER TO openpc_control_owner;

--
-- Name: platform_recovery_enrollment; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.platform_recovery_enrollment (
    enrollment_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    platform_context_id uuid NOT NULL,
    expired_replacement_id uuid,
    root_epoch numeric(20,0) NOT NULL,
    root_revision numeric(20,0) NOT NULL,
    root_digest bytea NOT NULL,
    document jsonb NOT NULL,
    document_digest bytea NOT NULL,
    state text DEFAULT 'ACTIVE'::text NOT NULL,
    row_version numeric(20,0) DEFAULT 1 NOT NULL,
    valid_from timestamp(6) with time zone NOT NULL,
    valid_until timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp(6) with time zone,
    revocation_reason_digest bytea,
    source_purpose text DEFAULT 'EXPIRED_REPLACEMENT'::text NOT NULL,
    root_expiry_recovery_id uuid,
    CONSTRAINT platform_recovery_enrollment_digests_ck CHECK (((octet_length(root_digest) = 32) AND (octet_length(document_digest) = 32) AND ((revocation_reason_digest IS NULL) OR (octet_length(revocation_reason_digest) = 32)))),
    CONSTRAINT platform_recovery_enrollment_source_purpose_ck CHECK (COALESCE((((source_purpose = 'EXPIRED_REPLACEMENT'::text) AND (expired_replacement_id IS NOT NULL) AND (root_expiry_recovery_id IS NULL) AND ((document ->> 'schemaVersion'::text) = '1'::text) AND (NOT (document ? 'source'::text))) OR ((source_purpose = 'ROOT_EXPIRY_RECOVERY'::text) AND (expired_replacement_id IS NULL) AND (root_expiry_recovery_id IS NOT NULL) AND ((document ->> 'schema'::text) = ANY (ARRAY['pc.identity.platform-recovery-enrollment'::text, 'pc.identity.discovery-certificate-recovery-enrollment'::text])) AND ((document ->> 'schemaVersion'::text) = '2'::text) AND ((document #>> '{source,kind}'::text[]) = 'ROOT_EXPIRY_RECOVERY'::text) AND ((document #>> '{source,recoveryId}'::text[]) = (root_expiry_recovery_id)::text) AND (NOT (document ? 'expiredReplacementId'::text))) OR ((source_purpose = 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text) AND (expired_replacement_id IS NULL) AND (root_expiry_recovery_id IS NOT NULL) AND ((document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((document ->> 'schemaVersion'::text) = '3'::text) AND ((document #>> '{source,kind}'::text[]) = 'ROOT_EXPIRY_RECOVERY'::text) AND ((document #>> '{source,recoveryId}'::text[]) = (root_expiry_recovery_id)::text) AND (jsonb_typeof((document #> '{source,continuation}'::text[])) = 'object'::text) AND ((document #>> '{source,continuation,schema}'::text[]) = 'pc.identity.platform-pending-recovery-continuation'::text) AND ((document #>> '{source,continuation,schemaVersion}'::text[]) = '1'::text) AND (NOT (document ? 'expiredReplacementId'::text))) OR ((source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND (expired_replacement_id IS NULL) AND (root_expiry_recovery_id IS NOT NULL) AND ((document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((document ->> 'schemaVersion'::text) = '4'::text) AND ((document #>> '{source,kind}'::text[]) = 'ROOT_EXPIRY_RECOVERY'::text) AND ((document #>> '{source,recoveryId}'::text[]) = (root_expiry_recovery_id)::text) AND (jsonb_typeof((document #> '{source,pendingExpiry}'::text[])) = 'object'::text) AND ((document #>> '{source,pendingExpiry,schema}'::text[]) = 'pc.identity.platform-pending-administration-expiry'::text) AND ((document #>> '{source,pendingExpiry,schemaVersion}'::text[]) = ANY (ARRAY['1'::text, '2'::text])) AND (NOT (document ? 'expiredReplacementId'::text)))), false)),
    CONSTRAINT platform_recovery_enrollment_state_ck CHECK (((state = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text])) AND (row_version > (0)::numeric) AND (root_epoch > (0)::numeric) AND (root_revision > (0)::numeric))),
    CONSTRAINT platform_recovery_enrollment_time_ck CHECK (((valid_until > valid_from) AND (((state = 'ACTIVE'::text) AND (revoked_at IS NULL) AND (revocation_reason_digest IS NULL)) OR ((state = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revocation_reason_digest IS NOT NULL)))))
);

ALTER TABLE ONLY control.platform_recovery_enrollment FORCE ROW LEVEL SECURITY;


ALTER TABLE control.platform_recovery_enrollment OWNER TO openpc_control_owner;

--
-- Name: lock_platform_recovery_enrollment(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_platform_recovery_enrollment(p_enrollment_id uuid) RETURNS SETOF control.platform_recovery_enrollment
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 -- Recovery activation writes recipient epochs and session families. Declare the
 -- common Participant write fence first, rather than upgrading child share locks.
 PERFORM 1 FROM control.participant p WHERE p.participant_id=openpc.current_participant_id() AND p.state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN QUERY SELECT e.* FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=p_enrollment_id
  AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id) FOR UPDATE OF e;
END $$;


ALTER FUNCTION openpc.lock_platform_recovery_enrollment(p_enrollment_id uuid) OWNER TO openpc_control_owner;

--
-- Name: platform_context; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.platform_context (
    platform_context_id uuid NOT NULL,
    owner_participant_id uuid NOT NULL,
    state text NOT NULL,
    authority_epoch numeric(20,0) NOT NULL,
    row_version numeric(20,0) NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT platform_context_epoch_ck CHECK ((((authority_epoch >= (0)::numeric) AND (authority_epoch <= '18446744073709551615'::numeric)) AND ((row_version >= (1)::numeric) AND (row_version <= '18446744073709551615'::numeric)))),
    CONSTRAINT platform_context_id_ck CHECK (("substring"((platform_context_id)::text, 15, 1) = '7'::text)),
    CONSTRAINT platform_context_state_ck CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'RETIRED'::text])))
);

ALTER TABLE ONLY control.platform_context FORCE ROW LEVEL SECURITY;


ALTER TABLE control.platform_context OWNER TO openpc_control_owner;

--
-- Name: lock_platform_scope_context(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_platform_scope_context(p_root_id uuid) RETURNS SETOF control.platform_context
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(false);
 RETURN QUERY SELECT p.* FROM control.platform_context p
 WHERE p.platform_context_id=p_root_id AND p.state='ACTIVE'
 AND EXISTS(SELECT 1 FROM control.authority_envelope e
   WHERE e.platform_context_id=p.platform_context_id
     AND e.participant_id=openpc.current_participant_id())
 FOR SHARE OF p;
END $$;


ALTER FUNCTION openpc.lock_platform_scope_context(p_root_id uuid) OWNER TO openpc_control_owner;

--
-- Name: lock_provider_retry_probe_source(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_provider_retry_probe_source(p_reference jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE pid uuid; privacy uuid; p control.provider_profile; o control.provider_probe_observation;
 w control.configuration_work; input_id uuid; installation_id uuid; current_generation_id uuid; history jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('role') NOT IN ('openpc_control_owner','openpc_operations_qualification_owner')
  OR current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR current_setting('openpc.context_mode',true) IS DISTINCT FROM 'PARTICIPANT'
  OR NOT (openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1')
  OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_CONTEXT'; END IF;
 IF jsonb_typeof(p_reference) IS DISTINCT FROM 'object' OR octet_length(p_reference::text)>4096
  OR (SELECT count(*) FROM jsonb_object_keys(p_reference))<>10
  OR NOT p_reference ?& ARRAY['providerProfileId','observationId','qualificationWorkId','operationId','resultEventId','artifactDigest','configurationDigest','observationDigest','resultReceiptDigest','authorizationEvidenceDigest']
  OR EXISTS(SELECT 1 FROM jsonb_each(p_reference) item WHERE jsonb_typeof(item.value)<>'string')
  OR coalesce(p_reference->>'providerProfileId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(p_reference->>'observationId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(p_reference->>'qualificationWorkId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(p_reference->>'operationId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(p_reference->>'resultEventId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(p_reference->>'artifactDigest','') !~ '^sha256:[0-9a-f]{64}$'
  OR coalesce(p_reference->>'configurationDigest','') !~ '^sha256:[0-9a-f]{64}$'
  OR coalesce(p_reference->>'observationDigest','') !~ '^sha256:[0-9a-f]{64}$'
  OR coalesce(p_reference->>'resultReceiptDigest','') !~ '^sha256:[0-9a-f]{64}$'
  OR coalesce(p_reference->>'authorizationEvidenceDigest','') !~ '^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_REFERENCE'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 -- Parent roots precede native source rows. NOWAIT/try-lock fail closed when an
 -- outer generation/qualification consumer already owns a different fence.
 PERFORM 1 FROM control.participant WHERE participant_id=pid AND state='ACTIVE' AND archived_at IS NULL FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 PERFORM 1 FROM control.privacy_domain WHERE participant_id=pid AND privacy_domain_id=privacy AND state='ACTIVE' FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT p FROM control.provider_profile WHERE provider_profile_id=(p_reference->>'providerProfileId')::uuid
  AND participant_id=pid AND privacy_domain_id=privacy FOR SHARE NOWAIT;
 SELECT * INTO STRICT o FROM control.provider_probe_observation WHERE observation_id=(p_reference->>'observationId')::uuid
  AND participant_id=pid AND privacy_domain_id=privacy FOR SHARE NOWAIT;
 SELECT * INTO STRICT w FROM control.configuration_work WHERE configuration_work_id=(p_reference->>'qualificationWorkId')::uuid
  AND participant_id=pid AND privacy_domain_id=privacy FOR SHARE NOWAIT;
 IF p.state NOT IN ('QUALIFIED','ACTIVE') OR p.qualification_observation_id IS DISTINCT FROM o.observation_id
  OR p.behavior_fingerprint IS DISTINCT FROM o.input_digest OR p.revision IS DISTINCT FROM o.observed_revision+2
  OR w.state IS DISTINCT FROM 'COMPLETED' OR o.valid_until<=clock_timestamp()
  OR (SELECT count(*) FROM control.configuration_work q WHERE q.participant_id=pid AND q.privacy_domain_id=privacy
      AND q.resource_id=p.provider_profile_id AND q.work_kind='PROVIDER_QUALIFICATION' AND q.state='COMPLETED'
      AND q.result_receipt->>'liveObservationId'=o.observation_id::text
      AND q.result_receipt->>'liveObservationDigest'=o.observation_digest)<>1
 THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 SELECT c.runtime_configuration_input_id,c.module_installation_id,c.module_configuration_generation_id
  INTO STRICT input_id,installation_id,current_generation_id FROM control.runtime_configuration_input_current_metadata c
  WHERE c.participant_id=pid AND c.privacy_domain_id=privacy AND c.active
   AND 'sha256:'||encode(c.configuration_digest,'hex')=w.configuration_digest;
 PERFORM 1 FROM control.module_installation WHERE module_installation_id=installation_id
  AND participant_id=pid AND privacy_domain_id=privacy AND state='ENABLED' FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 PERFORM 1 FROM control.module_configuration_generation WHERE generation_id=current_generation_id
  AND module_installation_id=installation_id AND participant_id=pid AND privacy_domain_id=privacy AND active FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 PERFORM 1 FROM control.runtime_configuration_input WHERE runtime_configuration_input_id=input_id
  AND participant_id=pid AND privacy_domain_id=privacy AND selected FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 -- Re-read the existing current view after all physical fences are held.
 PERFORM 1 FROM control.runtime_configuration_input_current_metadata WHERE runtime_configuration_input_id=input_id
  AND participant_id=pid AND privacy_domain_id=privacy AND module_installation_id=installation_id
  AND module_configuration_generation_id=current_generation_id AND 'sha256:'||encode(configuration_digest,'hex')=w.configuration_digest;
 IF NOT FOUND OR o.valid_until<=clock_timestamp() THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 history:=openpc.read_provider_retry_probe_source(p_reference);
 IF o.valid_until<=clock_timestamp() THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE'; END IF;
 RETURN jsonb_build_object('history',history,'configurationInputId',input_id,
  'moduleInstallationId',installation_id,'moduleConfigurationGenerationId',current_generation_id);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN RAISE EXCEPTION 'OPS_PROVIDER_PROBE_SOURCE_UNAVAILABLE';
 WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $_$;


ALTER FUNCTION openpc.lock_provider_retry_probe_source(p_reference jsonb) OWNER TO openpc_control_owner;

--
-- Name: lock_root_expiry_pending_source(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_root_expiry_pending_source(context_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE target uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||context_id::text,0))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-PENDING'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-PENDING'; END IF;
 PERFORM 1 FROM control.platform_context WHERE platform_context_id=context_id
  AND owner_participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-PENDING'; END IF;
 PERFORM 1 FROM control.platform_scope_replacement WHERE platform_context_id=context_id
  AND openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND state='WITHDRAWING' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-PENDING'; END IF;
 FOR target IN SELECT q.runtime_target_id FROM control.platform_scope_target_withdrawal q JOIN control.platform_scope_replacement r
  ON r.replacement_id=q.replacement_id AND r.participant_id=q.participant_id AND r.privacy_domain_id=q.privacy_domain_id
  WHERE r.platform_context_id=context_id AND r.state='WITHDRAWING' ORDER BY q.runtime_target_id LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||openpc.current_participant_id()::text||':'||
    openpc.current_privacy_domain_id()::text||':'||target::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  PERFORM 1 FROM control.runtime_target WHERE runtime_target_id=target AND openpc.matches_participant(participant_id)
    AND openpc.matches_privacy(privacy_domain_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-PENDING'; END IF;
 END LOOP;
END $$;


ALTER FUNCTION openpc.lock_root_expiry_pending_source(context_id uuid) OWNER TO openpc_control_owner;

--
-- Name: root_expiry_recovery_enrollment; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.root_expiry_recovery_enrollment (
    enrollment_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    custody_trust_id uuid NOT NULL,
    custody_trust_digest bytea NOT NULL,
    platform_context_id uuid NOT NULL,
    document jsonb NOT NULL,
    document_digest bytea NOT NULL,
    signature bytea NOT NULL,
    state text DEFAULT 'ACTIVE'::text NOT NULL,
    row_version numeric(20,0) DEFAULT 1 NOT NULL,
    valid_from timestamp(6) with time zone NOT NULL,
    valid_until timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp(6) with time zone,
    revocation_reason_digest bytea,
    CONSTRAINT root_expiry_recovery_enrollment_digest_ck CHECK (((octet_length(document_digest) = 32) AND (octet_length(custody_trust_digest) = 32) AND (octet_length(signature) = 64) AND ((revocation_reason_digest IS NULL) OR (octet_length(revocation_reason_digest) = 32)))),
    CONSTRAINT root_expiry_recovery_enrollment_purpose_ck CHECK (COALESCE(((((document ->> 'schemaVersion'::text) = '1'::text) AND ((document ->> 'purpose'::text) = 'pc.installation.local-root-expiry-recovery-custody.v1'::text) AND (NOT (document ? 'pending'::text))) OR (((document ->> 'schemaVersion'::text) = '2'::text) AND ((document ->> 'purpose'::text) = 'pc.installation.local-root-expiry-pending-recovery-custody.v2'::text) AND (jsonb_typeof((document -> 'pending'::text)) = 'object'::text)) OR (((document ->> 'schemaVersion'::text) = '3'::text) AND ((document ->> 'purpose'::text) = 'pc.installation.local-root-expiry-pending-ancestry-custody.v3'::text) AND (jsonb_typeof((document -> 'pending'::text)) = 'object'::text) AND (jsonb_typeof((document -> 'rootAncestry'::text)) = 'object'::text))), false)),
    CONSTRAINT root_expiry_recovery_enrollment_state_ck CHECK (((state = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text])) AND (row_version > (0)::numeric))),
    CONSTRAINT root_expiry_recovery_enrollment_time_ck CHECK (((valid_until > valid_from) AND (((state = 'ACTIVE'::text) AND (revoked_at IS NULL) AND (revocation_reason_digest IS NULL)) OR ((state = 'REVOKED'::text) AND (revoked_at IS NOT NULL) AND (revocation_reason_digest IS NOT NULL)))))
);

ALTER TABLE ONLY control.root_expiry_recovery_enrollment FORCE ROW LEVEL SECURITY;


ALTER TABLE control.root_expiry_recovery_enrollment OWNER TO openpc_control_owner;

--
-- Name: lock_root_expiry_recovery_enrollment(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_root_expiry_recovery_enrollment(p_enrollment uuid) RETURNS SETOF control.root_expiry_recovery_enrollment
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE source control.root_expiry_recovery_enrollment; declared record;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 PERFORM 1 FROM control.platform_context p JOIN control.root_expiry_recovery_enrollment e ON e.platform_context_id=p.platform_context_id
  AND e.participant_id=p.owner_participant_id WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id)
   AND openpc.matches_privacy(e.privacy_domain_id) AND p.state='ACTIVE' FOR UPDATE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 IF EXISTS(SELECT 1 FROM control.root_expiry_recovery_enrollment e WHERE e.enrollment_id=p_enrollment
   AND e.document->>'schemaVersion' IN ('2','3'))
   AND NOT EXISTS(SELECT 1 FROM control.root_expiry_recovery_case c WHERE c.enrollment_id=p_enrollment
     AND c.state='COMPLETED' AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)) THEN
  PERFORM openpc.lock_root_expiry_pending_source((SELECT e.platform_context_id FROM control.root_expiry_recovery_enrollment e WHERE e.enrollment_id=p_enrollment));
 END IF;
 SELECT * INTO STRICT source FROM control.root_expiry_recovery_enrollment e WHERE e.enrollment_id=p_enrollment
  AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id) FOR SHARE;
 -- Revocation must not race verification of the current or historical custody.
 -- Runtime callers have no UPDATE privilege on these installation tables.
 PERFORM 1 FROM control.root_expiry_recovery_trust t WHERE t.custody_trust_id=source.custody_trust_id
  AND t.participant_id=source.participant_id AND t.privacy_domain_id=source.privacy_domain_id
  AND t.document_digest=source.custody_trust_digest FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
 IF source.document->>'schemaVersion'='3' THEN
  IF jsonb_typeof(source.document#>'{rootAncestry,receipts}') IS DISTINCT FROM 'array'
    OR jsonb_array_length(source.document#>'{rootAncestry,receipts}') NOT BETWEEN 1 AND 32
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
  FOR declared IN SELECT value FROM jsonb_array_elements(source.document#>'{rootAncestry,receipts}') LOOP
   PERFORM 1 FROM control.root_expiry_recovery_enrollment e
    JOIN control.root_expiry_recovery_trust t ON t.custody_trust_id=e.custody_trust_id
      AND t.participant_id=e.participant_id AND t.privacy_domain_id=e.privacy_domain_id
      AND t.document_digest=e.custody_trust_digest
    JOIN control.root_expiry_recovery_case c ON c.enrollment_id=e.enrollment_id
      AND c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
      AND c.enrollment_digest=e.document_digest AND c.state='COMPLETED'
    WHERE e.enrollment_id::text=declared.value->>'enrollmentId'
      AND c.recovery_id::text=declared.value->>'recoveryId' AND c.operation_id::text=declared.value->>'activationOperationId'
      AND e.participant_id=source.participant_id AND e.privacy_domain_id=source.privacy_domain_id
      AND e.platform_context_id=source.platform_context_id
      AND 'sha256:'||encode(e.document_digest,'hex')=declared.value->>'enrollmentDigest'
      AND 'sha256:'||encode(c.intent_digest,'hex')=declared.value->>'intentDigest'
      AND 'sha256:'||encode(c.evidence_digest,'hex')=declared.value->>'receiptDigest'
      AND e.state='ACTIVE' AND e.row_version=1 AND t.state='ACTIVE' AND t.row_version=1 FOR SHARE OF e,t;
   IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-ROOT-EXPIRY-RECOVERY'; END IF;
  END LOOP;
 END IF;
 RETURN QUERY SELECT e.* FROM control.root_expiry_recovery_enrollment e WHERE e.enrollment_id=p_enrollment
  AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id) FOR SHARE OF e;
END $$;


ALTER FUNCTION openpc.lock_root_expiry_recovery_enrollment(p_enrollment uuid) OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_artifact_disposition(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_artifact_disposition() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND NOT rolbypassrls)
  OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
  OR NOT pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR openpc.current_action_intent_id() NOT IN
   ('ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1','ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1',
    'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||openpc.current_participant_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-release-catalog',0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
 THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='RUNTIME-DISPOSITION-PRODUCER-CONTENTION'; END IF;
END $$;


ALTER FUNCTION openpc.lock_runtime_artifact_disposition() OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_artifact_originals(uuid, uuid, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_artifact_originals(pid uuid, privacy uuid, configuration bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR pid IS NULL OR privacy IS NULL OR configuration IS NULL OR octet_length(configuration)<>32
  OR current_setting('transaction_isolation')<>'serializable'
  OR current_setting('session_replication_role')<>'origin'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
 THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='PC-DATA-6007'; END IF;
 PERFORM input.runtime_configuration_input_id FROM control.runtime_configuration_input input
  WHERE input.participant_id=pid AND input.privacy_domain_id=privacy AND input.configuration_digest=configuration
  ORDER BY input.runtime_configuration_input_id FOR SHARE NOWAIT;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='PC-DATA-6007';
END $$;


ALTER FUNCTION openpc.lock_runtime_artifact_originals(pid uuid, privacy uuid, configuration bytea) OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_artifact_source_custody(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_artifact_source_custody() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND NOT rolbypassrls)
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||openpc.current_participant_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-release-catalog',0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $$;


ALTER FUNCTION openpc.lock_runtime_artifact_source_custody() OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_discovery_authority(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_discovery_authority(target uuid, certificate_digest text) RETURNS TABLE(credential_id uuid, credential_epoch bigint, principal_epoch bigint, valid_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE pid uuid; privacy uuid; selected_credential uuid; selected_principal uuid; candidates uuid[];
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
  OR certificate_digest !~ '^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-CONTEXT-INVALID'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 PERFORM 1 FROM control.participant p WHERE p.participant_id=pid AND p.state='ACTIVE' AND p.archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-PARTICIPANT-INVALID'; END IF;
 PERFORM 1 FROM control.privacy_domain p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy AND p.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-PRIVACY-INVALID'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target AND t.requires_authenticated_discovery)
 THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-TARGET-INVALID'; END IF;
 SELECT array_agg(c.credential_id ORDER BY c.credential_id) INTO candidates FROM control.credential c
  WHERE c.participant_id=pid AND c.kind='WORKLOAD_MTLS' AND c.state='ACTIVE'
   AND c.subject='urn:openpc:participant:'||pid::text||':workload:'||target::text
   AND c.audience='urn:openpc:workload:'||target::text
   AND c.secret_fingerprint=decode(substring(certificate_digest from 8),'hex');
 IF coalesce(cardinality(candidates),0)<>1 THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-CREDENTIAL-CARDINALITY'; END IF;
 selected_credential:=candidates[1];
 SELECT c.principal_id INTO selected_principal FROM control.credential c WHERE c.credential_id=selected_credential AND c.participant_id=pid;
 PERFORM 1 FROM control.principal p WHERE p.participant_id=pid AND p.principal_id=selected_principal
  AND p.kind='WORKLOAD' AND p.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-PRINCIPAL-INVALID'; END IF;
 PERFORM 1 FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=selected_credential FOR SHARE;
 RETURN QUERY SELECT c.credential_id,c.credential_epoch::bigint,p.authority_epoch::bigint,c.valid_until
  FROM control.credential c JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
  WHERE c.participant_id=pid AND c.credential_id=selected_credential AND c.principal_id=selected_principal
   AND c.kind='WORKLOAD_MTLS' AND c.state='ACTIVE' AND c.credential_epoch>0
   AND c.subject='urn:openpc:participant:'||pid::text||':workload:'||target::text
   AND c.audience='urn:openpc:workload:'||target::text
   AND c.secret_fingerprint=decode(substring(certificate_digest from 8),'hex')
   AND c.certificate_der IS NOT NULL AND sha256(c.certificate_der)=c.secret_fingerprint
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
   AND p.kind='WORKLOAD' AND p.state='ACTIVE' AND p.authority_epoch>0;
 IF NOT FOUND THEN RAISE EXCEPTION 'DATA-6001-DISCOVERY-CREDENTIAL-INVALID'; END IF;
END $_$;


ALTER FUNCTION openpc.lock_runtime_discovery_authority(target uuid, certificate_digest text) OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_target_current_sources(uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_target_current_sources(target uuid, expected_source jsonb, proof jsonb, operation text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE pid uuid; privacy uuid; original control.configuration_work;
 input control.runtime_configuration_input; binding jsonb; current_identity_expiry numeric;
 workload_principals uuid[]; workload_principal uuid; current_policy control.policy_generation;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed' OR target IS NULL
  OR jsonb_typeof(expected_source) IS DISTINCT FROM 'object' OR jsonb_typeof(proof) IS DISTINCT FROM 'object'
  OR operation IS NULL OR operation NOT IN ('RESTORE','CONFIRM')
  OR proof->>'targetId' IS DISTINCT FROM target::text
  OR proof->>'sourceMode' IS NULL OR proof->>'sourceMode' NOT IN ('FACT_FREE','FACT_BOUND')
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-CONTEXT'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 -- All advisory fences are fail-fast before row locks. A held competing owner
 -- produces retryable contention, never an ordinary business failure or wait cycle.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 -- The policy workload and the target transport are different identities.
 -- Revalidate the actual policy workload; the authenticated request still needs
 -- its own concrete credential/authority checks at the runtime decision owner.
 SELECT array_agg(DISTINCT c.principal_id ORDER BY c.principal_id) INTO workload_principals
  FROM control.credential c WHERE c.participant_id=pid AND c.kind='WORKLOAD_MTLS'
   AND c.audience=proof->>'workloadId' AND c.state='ACTIVE' AND c.credential_epoch>0
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp();
 IF coalesce(cardinality(workload_principals),0)<>1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-AMBIGUOUS'; END IF;
 workload_principal:=workload_principals[1];
 PERFORM 1 FROM control.principal p WHERE p.participant_id=pid AND p.principal_id=workload_principal
  AND p.kind='WORKLOAD' AND p.state='ACTIVE' AND p.authority_epoch>0 FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-WITHDRAWN'; END IF;
 PERFORM 1 FROM control.credential c WHERE c.participant_id=pid AND c.principal_id=workload_principal
  AND c.kind='WORKLOAD_MTLS' AND c.audience=proof->>'workloadId' AND c.state='ACTIVE'
  AND c.credential_epoch>0 AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND c.certificate_der IS NOT NULL AND sha256(c.certificate_der)=c.secret_fingerprint
  ORDER BY c.credential_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-CREDENTIAL'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w
  WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.configuration_work_id=(expected_source->>'original_work_id')::uuid
   AND w.operation_id::text=expected_source->>'original_operation_id'
   AND w.execution_attempt_id::text=expected_source->>'original_execution_attempt_id'
   AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION'
   AND (w.state='COMPLETED' OR (operation='CONFIRM' AND w.state IN ('LEASED','RECONCILING')))
   AND w.execution_started_at IS NOT NULL
   AND w.runtime_configuration_generation_id::text=expected_source->>'runtime_configuration_generation_id'
   AND w.configuration_digest='sha256:'||(expected_source->>'configuration_digest')
   AND w.xds_version_digest='sha256:'||(expected_source->>'xds_version_digest')
   AND w.predecessor_digest IS NOT DISTINCT FROM 'sha256:'||(expected_source->>'predecessor_capsule_digest')
   AND w.policy_generation_digest='sha256:'||(proof->>'policyGenerationDigest') FOR SHARE NOWAIT;
 PERFORM 1 FROM control.runtime_activation_observation o
  WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.configuration_work_id=original.configuration_work_id
   AND o.operation_id=original.operation_id AND o.execution_attempt_id=original.execution_attempt_id
   AND o.runtime_target_id=target AND o.runtime_configuration_generation_id=original.runtime_configuration_generation_id
   AND o.generation_digest=original.generation_digest AND o.xds_version_digest=original.xds_version_digest
   AND (original.state<>'COMPLETED' OR o.activation_receipt_digest=original.result_receipt_digest)
   AND encode(sha256(decode(o.activation_receipt->>'activationReceiptCoseHex','hex')),'hex')=proof->>'originalReceiptDigest'
   AND o.capsule_digest='sha256:'||(expected_source->>'capsule_digest')
   AND o.capsule_digest='sha256:'||(proof->>'capsuleDigest');
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-OBSERVATION'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=(expected_source->>'runtime_configuration_input_id')::uuid
   AND i.configuration_digest=decode(expected_source->>'configuration_digest','hex')
   AND i.module_installation_id::text=expected_source->>'module_installation_id'
   AND i.module_configuration_generation_id::text=expected_source->>'module_configuration_generation_id'
   AND i.selected FOR SHARE NOWAIT;
 -- Lock each mutable source before re-evaluating the shared canonical view.
 -- A source's signature/digest alone does not establish its current admission.
 FOR binding IN SELECT value FROM jsonb_array_elements(input.resource_bindings) ORDER BY value->>'kind',value->>'id' LOOP
  CASE binding->>'kind'
   WHEN 'ProviderProfile' THEN
    PERFORM 1 FROM control.provider_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.provider_profile_id=(binding->>'id')::uuid AND p.behavior_fingerprint=binding->>'digest'
     AND p.chain_id=binding->>'chainId' AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'ClientIndexerProfile' THEN
    PERFORM 1 FROM control.indexer_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.indexer_profile_id=(binding->>'id')::uuid AND p.method_profile_digest=binding->>'digest'
     AND p.engine_version=binding->>'engineVersion' AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'ProjectionPlan' THEN
    PERFORM 1 FROM control.projection_plan p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.projection_plan_id=(binding->>'id')::uuid AND p.plan_digest=binding->>'digest'
     AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'CiglSettings' THEN
    PERFORM 1 FROM control.cigl_settings p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.cigl_settings_id=(binding->>'id')::uuid;
   ELSE RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-KIND';
  END CASE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-RESTRICTED'; END IF;
 END LOOP;
 PERFORM 1 FROM control.runtime_configuration_input_current_metadata i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=input.runtime_configuration_input_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-WITHDRAWN'; END IF;
 SELECT g.* INTO STRICT current_policy FROM control.policy_generation g JOIN control.policy_version v
  ON v.participant_id=g.participant_id AND v.privacy_domain_id=g.privacy_domain_id AND v.policy_version_id=g.policy_version_id
  JOIN control.policy_artifact a ON a.participant_id=g.participant_id AND a.privacy_domain_id=g.privacy_domain_id
   AND a.semantic_digest=v.semantic_digest AND a.payload_digest=g.artifact_digest
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND ((g.active AND g.state='ACTIVE') OR (operation='CONFIRM' AND EXISTS(
    SELECT 1 FROM control.policy_activation_occurrence_target ot
     JOIN control.policy_activation_occurrence oc ON oc.participant_id=ot.participant_id
      AND oc.privacy_domain_id=ot.privacy_domain_id AND oc.activation_occurrence_id=ot.activation_occurrence_id
     JOIN control.policy_activation a ON a.participant_id=oc.participant_id
      AND a.privacy_domain_id=oc.privacy_domain_id AND a.policy_activation_id=oc.activation_occurrence_id
    WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id
     AND ((ot.phase='FORWARD' AND oc.policy_generation_id=g.policy_generation_id AND g.state='PREPARED')
       OR (ot.phase='ROLLBACK' AND a.state='ACTIVE' AND a.prior_generation_digest=g.generation_digest AND g.state='RETIRED')))))
   AND g.generation_digest=decode(proof->>'policyGenerationDigest','hex') FOR SHARE OF g NOWAIT;
 SELECT s.expires_at_ns INTO STRICT current_identity_expiry FROM control.identity_runtime_snapshot_head h
  JOIN control.identity_runtime_snapshot s ON s.snapshot_id=h.snapshot_id AND s.participant_id=h.participant_id
   AND s.privacy_domain_id=h.privacy_domain_id AND s.target_runtime_id=h.target_runtime_id
  WHERE h.participant_id=pid AND h.privacy_domain_id=privacy AND h.target_runtime_id=target
   AND s.manifest_digest=decode(proof->>'identityManifestDigest','hex')
   AND s.expires_at_ns>extract(epoch from clock_timestamp())*1000000000 FOR SHARE OF h NOWAIT;
 -- The proof may shorten, never extend, the original Identity publication.
 IF (proof->>'capsuleValidUntilNs')::numeric>current_identity_expiry
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY-EXPIRY'; END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $_$;


ALTER FUNCTION openpc.lock_runtime_target_current_sources(target uuid, expected_source jsonb, proof jsonb, operation text) OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_target_disposition_issuance(uuid, bigint, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_target_disposition_issuance(target uuid, wanted_revision bigint, wanted_digest text, worker text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE pid uuid; privacy uuid; head control.runtime_target_disposition_admission; latest text;
 original control.configuration_work; cause control.configuration_work; current_target control.runtime_target;
 authority record; principal uuid; proof jsonb; action text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed' OR target IS NULL
  OR wanted_revision IS NULL OR wanted_revision<1 OR wanted_digest IS NULL
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF head.revision IS DISTINCT FROM wanted_revision OR head.admission_digest IS DISTINCT FROM wanted_digest
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-HEAD'; END IF;
 action:=head.binding->>'action';
 IF action IN ('ConfirmActivation','Restore') THEN
  PERFORM 1 FROM control.platform_context root JOIN control.platform_scope_replacement replacement
    ON replacement.platform_context_id=root.platform_context_id
    WHERE replacement.participant_id=pid AND replacement.privacy_domain_id=privacy AND replacement.state='WITHDRAWING'
    FOR SHARE OF root;
  IF FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-PLATFORM-WITHDRAWING'; END IF;
  IF worker IS NOT NULL THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
  proof:=CASE action WHEN 'ConfirmActivation' THEN head.activation_proof ELSE head.restoration_proof END;
  PERFORM openpc.lock_runtime_target_current_sources(target,head.binding->'source',proof,
   CASE action WHEN 'ConfirmActivation' THEN 'CONFIRM' ELSE 'RESTORE' END);
 ELSIF action='Withdraw' THEN
  IF coalesce(worker,'')='' THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-ACTION'; END IF;
 -- Re-read only after the original Control fences have been reacquired.
 SELECT admission_digest INTO STRICT latest FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF latest IS DISTINCT FROM wanted_digest THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-HEAD'; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,
  'sha256:'||(head.binding->'target'->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF head.binding->'target' IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',authority.credential_id::text,'principal_id',principal::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',head.binding->'target'->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->'source'->>'original_work_id')::uuid FOR SHARE NOWAIT;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF action='ConfirmActivation' THEN
  IF NOT coalesce(((original.state='COMPLETED' AND current_target.active_generation_digest='sha256:'||(proof->>'capsuleDigest'))
   OR (original.state IN ('LEASED','RECONCILING') AND openpc.runtime_work_predecessor_matches(original.configuration_work_id)
    AND current_target.desired_generation_digest=original.generation_digest)),false)
   OR head.binding->'cause' IS DISTINCT FROM jsonb_build_object('kind','Activation','work_id',original.configuration_work_id::text,
    'operation_id',original.operation_id::text,'execution_attempt_id',original.execution_attempt_id::text)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-TARGET'; END IF;
 ELSIF action='Withdraw' AND (openpc.expired_denial_issuance_matches(target,wanted_revision,head.admission_digest,worker)
  OR openpc.expired_handover_issuance_matches(target,wanted_revision,head.admission_digest,worker)
  OR openpc.expired_credential_handover_issuance_matches(target,wanted_revision,head.admission_digest,worker)) THEN
  -- The separate native proof admits this exact negative source only.
  RETURN;
 ELSIF action='Withdraw' AND head.binding->'cause'->>'kind'='Dependency'
   AND head.binding->'cause'->>'owner'='Platform' THEN
  IF original.state<>'COMPLETED' OR original.work_kind<>'RUNTIME_ACTIVATION'
    OR original.operation_id::text IS DISTINCT FROM head.binding->'source'->>'original_operation_id'
    OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->'source'->>'original_execution_attempt_id'
    OR current_target.active_generation_digest IS DISTINCT FROM 'sha256:'||(head.binding->'source'->>'capsule_digest')
    OR NOT EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q
      JOIN control.platform_scope_replacement r ON r.replacement_id=q.replacement_id
        AND r.participant_id=q.participant_id AND r.privacy_domain_id=q.privacy_domain_id
      JOIN control.platform_context p ON p.platform_context_id=r.platform_context_id
        AND p.owner_participant_id=r.participant_id AND p.authority_epoch=r.predecessor_epoch
        AND p.row_version=r.expected_root_revision AND p.state='ACTIVE'
      WHERE q.participant_id=pid AND q.privacy_domain_id=privacy AND q.runtime_target_id=target
        AND q.replacement_id::text=head.binding->'cause'->>'resource_id'
        AND r.state='WITHDRAWING' AND r.row_version=1
        AND head.binding->'cause'=jsonb_build_object('kind','Dependency','owner','Platform',
          'resource_id',r.replacement_id::text,'operation_id',r.prepare_operation_id::text,'revision',1)
        AND q.source->>'originalWorkId'=original.configuration_work_id::text
        AND q.source->>'originalAttemptId'=original.execution_attempt_id::text
        AND q.source->>'capsuleDigest'=current_target.active_generation_digest
        AND q.source->>'activationReceiptDigest'=original.result_receipt_digest)
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
      AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN('PENDING','LEASED','RECONCILING'))
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 ELSE
  IF head.binding->'cause'->>'kind'='UnsignedWithdrawalRecovery' AND (
   action IS DISTINCT FROM 'Withdraw'
   OR head.revision IS DISTINCT FROM (head.binding->'cause'->>'abandoned_revision')::bigint+1
   OR head.binding->'previous_revision' IS DISTINCT FROM to_jsonb(head.revision-2)
   OR NOT openpc.runtime_unsigned_withdrawal_recoverable(target,(head.revision-1)::bigint,
    'sha256:'||(head.binding->'cause'->>'abandoned_admission_digest')))
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RECOVERY-BINDING'; END IF;
  SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->'cause'->>'work_id')::uuid FOR SHARE NOWAIT;
  IF cause.work_kind<>'RUNTIME_ACTIVATION' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
   OR cause.operation_id::text IS DISTINCT FROM head.binding->'cause'->>'operation_id'
   OR (head.binding->'cause'->>'kind' IN ('Activation','UnsignedWithdrawalRecovery')) IS NOT TRUE
   OR (CASE WHEN head.binding->'cause'->>'kind'='UnsignedWithdrawalRecovery'
    THEN head.binding->'cause' ? 'execution_attempt_id'
    ELSE head.binding->'cause'->'execution_attempt_id' IS DISTINCT FROM 'null'::jsonb END)
   OR (original.state<>'COMPLETED' AND NOT coalesce((action='Withdraw' AND cause.denied_predecessor_work_id=original.configuration_work_id
    AND original.state='FAILED' AND original.result_receipt->>'outcome'='EXPIRED_OBSERVED_DENIED'
    AND openpc.runtime_work_predecessor_matches(cause.configuration_work_id)),false)) OR original.work_kind<>'RUNTIME_ACTIVATION'
   OR original.operation_id::text IS DISTINCT FROM head.binding->'source'->>'original_operation_id'
   OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->'source'->>'original_execution_attempt_id'
   OR (current_target.active_generation_digest IS DISTINCT FROM 'sha256:'||(head.binding->'source'->>'capsule_digest') AND NOT coalesce((action='Withdraw' AND cause.denied_predecessor_work_id=original.configuration_work_id
    AND original.state='FAILED' AND original.result_receipt->>'outcome'='EXPIRED_OBSERVED_DENIED'
    AND openpc.runtime_work_predecessor_matches(cause.configuration_work_id)),false))
   OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CAUSE'; END IF;
  IF action='Restore' THEN
   IF cause.state<>'FAILED' OR cause.completed_at IS NULL OR current_target.state<>'FAILED'
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
     AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN ('PENDING','LEASED','RECONCILING'))
   THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-CAUSE'; END IF;
  ELSIF cause.state<>'LEASED' OR cause.lease_owner IS DISTINCT FROM worker OR cause.lease_until<=clock_timestamp()
   OR NOT openpc.runtime_work_predecessor_matches(cause.configuration_work_id) OR current_target.state<>'STAGING'
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $$;


ALTER FUNCTION openpc.lock_runtime_target_disposition_issuance(target uuid, wanted_revision bigint, wanted_digest text, worker text) OWNER TO openpc_control_owner;

--
-- Name: lock_runtime_target_restore_sources(uuid, jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_runtime_target_restore_sources(target uuid, expected_source jsonb, proof jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
 PERFORM openpc.lock_runtime_target_current_sources(target,expected_source,proof,'RESTORE');
END $$;


ALTER FUNCTION openpc.lock_runtime_target_restore_sources(target uuid, expected_source jsonb, proof jsonb) OWNER TO openpc_control_owner;

--
-- Name: lock_store_retirement_authority(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_store_retirement_authority(wanted uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE a control.store_retirement_admission; host control.store_retirement_host; snapshot jsonb; dependency record; actual jsonb; retained jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT a FROM control.store_retirement_admission
  WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id()
   AND attempt_id=wanted AND xmin<>pg_current_xact_id()::xid;
 SELECT * INTO STRICT host FROM control.store_retirement_host WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND host_digest=a.host_digest;
 IF session_user<>host.database_role OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_RECONCILE_STORE_BATCH-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT convert_from(authority_snapshot,'UTF8')::jsonb INTO STRICT snapshot FROM control.audit_occurrence
  WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id
   AND aggregate_id=a.attempt_id AND aggregate_type='store-retirement' AND profile_id='pc.control.store-retirement.admit'
   AND catalog_operation_id='CFG-OP-ADMIT-STORE-RETIREMENT';
 IF snapshot->>'schema' IS DISTINCT FROM 'pc.control.precommit-authority-snapshot.v1'
  OR jsonb_array_length(snapshot->'authorities') IS DISTINCT FROM 3
  OR snapshot->>'participantId' IS DISTINCT FROM a.participant_id::text
  OR snapshot->>'privacyDomainId' IS DISTINCT FROM a.privacy_domain_id::text
  OR snapshot->>'operationId' IS DISTINCT FROM a.operation_id::text
  OR a.dispatch_not_after_ms<=floor(extract(epoch from clock_timestamp())*1000)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 FOR dependency IN SELECT DISTINCT * FROM (SELECT 'participant'::text AS owner, 'participant_id'::text AS identity,
 0 AS rank,(row->>'participant_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'participant') row
UNION ALL
SELECT 'privacy_domain'::text AS owner, 'privacy_domain_id'::text AS identity,
 1 AS rank,(row->>'privacy_domain_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') row
UNION ALL
SELECT 'principal'::text AS owner, 'principal_id'::text AS identity,
 2 AS rank,(row->>'principal_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'principal') row
UNION ALL
SELECT 'authority_role'::text AS owner, 'authority_role_id'::text AS identity,
 2 AS rank,(row->>'authority_role_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') row
UNION ALL
SELECT 'session'::text AS owner, 'session_id'::text AS identity,
 3 AS rank,(row->>'session_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'session') row
UNION ALL
SELECT 'authority_envelope'::text AS owner, 'authority_envelope_id'::text AS identity,
 2 AS rank,(row->>'authority_envelope_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') row
UNION ALL
SELECT 'assignment'::text AS owner, 'assignment_id'::text AS identity,
 2 AS rank,(row->>'assignment_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') row
UNION ALL
SELECT 'delegation'::text AS owner, 'delegation_id'::text AS identity,
 3 AS rank,(row->>'delegation_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') row
UNION ALL
SELECT 'credential'::text AS owner, 'credential_id'::text AS identity,
 3 AS rank,(row->>'credential_id')::uuid AS id FROM jsonb_array_elements(snapshot->'dependencies'->'credential') row
 UNION ALL SELECT 'credential','credential_id',3,host.workload_credential_id
 UNION ALL SELECT 'principal','principal_id',2,c.principal_id FROM control.credential c
  WHERE c.participant_id=a.participant_id AND c.credential_id=host.workload_credential_id
 ) dependencies ORDER BY rank,id,owner LOOP
  EXECUTE format('SELECT to_jsonb(%I) FROM control.%I WHERE participant_id=$1 AND %I=$2 FOR SHARE',dependency.identity,dependency.owner,dependency.identity)
   INTO STRICT actual USING a.participant_id,dependency.id;
 END LOOP;
 PERFORM openpc.lock_store_retirement_workload(a.host_digest);

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'participant') LOOP
  SELECT jsonb_build_object('participant_id',v.participant_id::text,'state',v.state::text,'authority_epoch',v.authority_epoch::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.participant v
   WHERE v.participant_id=a.participant_id AND v.participant_id=(retained->>'participant_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'



  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') LOOP
  SELECT jsonb_build_object('privacy_domain_id',v.privacy_domain_id::text,'participant_id',v.participant_id::text,'state',v.state::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.privacy_domain v
   WHERE v.participant_id=a.participant_id AND v.privacy_domain_id=(retained->>'privacy_domain_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'



  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'principal') LOOP
  SELECT jsonb_build_object('principal_id',v.principal_id::text,'participant_id',v.participant_id::text,'kind',v.kind::text,'state',v.state::text,'authority_epoch',v.authority_epoch::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.principal v
   WHERE v.participant_id=a.participant_id AND v.principal_id=(retained->>'principal_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'



  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') LOOP
  SELECT jsonb_build_object('authority_role_id',v.authority_role_id::text,'participant_id',v.participant_id::text,'role_id',v.role_id::text,'action_intent_ids',v.action_intent_ids::text,'state',v.state::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.authority_role v
   WHERE v.participant_id=a.participant_id AND v.authority_role_id=(retained->>'authority_role_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'



  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'session') LOOP
  SELECT jsonb_build_object('session_id',v.session_id::text,'participant_id',v.participant_id::text,'principal_id',v.principal_id::text,'state',v.state::text,'participant_epoch',v.participant_epoch::text,'authority_epoch',v.authority_epoch::text,'delegation_epoch',v.delegation_epoch::text,'session_epoch',v.session_epoch::text,'issued_at',v.issued_at::text,'idle_expires_at',v.idle_expires_at::text,'absolute_expires_at',v.absolute_expires_at::text,'step_up_verified_at',v.step_up_verified_at::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.session v
   WHERE v.participant_id=a.participant_id AND v.session_id=(retained->>'session_id')::uuid;
  IF (retained-ARRAY['idle_expires_at','row_version','step_up_verified_at']) IS DISTINCT FROM (actual-ARRAY['idle_expires_at','row_version','step_up_verified_at']) OR actual->>'state' IS DISTINCT FROM 'ACTIVE'
   OR (retained->>'idle_expires_at')::timestamptz<=clock_timestamp()
     OR (actual->>'idle_expires_at')::timestamptz<=clock_timestamp() OR (actual->>'absolute_expires_at')::timestamptz<=clock_timestamp()


  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') LOOP
  SELECT jsonb_build_object('authority_envelope_id',v.authority_envelope_id::text,'participant_id',v.participant_id::text,'principal_id',v.principal_id::text,'maker_principal_id',v.maker_principal_id::text,'checker_principal_id',v.checker_principal_id::text,'authority_epoch',v.authority_epoch::text,'delegation_epoch',v.delegation_epoch::text,'state',v.state::text,'valid_from',v.valid_from::text,'valid_until',v.valid_until::text,'semantic_digest',v.semantic_digest::text,'privacy_domain_ids',v.privacy_domain_ids::text,'action_intent_ids',v.action_intent_ids::text,'runtime_capability_ids',v.runtime_capability_ids::text,'resource_ids',v.resource_ids::text,'risk_classes',v.risk_classes::text,'maker_checker_required',v.maker_checker_required::text,'step_up_required',v.step_up_required::text,'onward_delegation_depth',v.onward_delegation_depth::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.authority_envelope v
   WHERE v.participant_id=a.participant_id AND v.authority_envelope_id=(retained->>'authority_envelope_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'


   OR (actual->>'valid_from')::timestamptz>clock_timestamp()
     OR (actual->>'valid_until' IS NOT NULL AND (actual->>'valid_until')::timestamptz<=clock_timestamp())
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') LOOP
  SELECT jsonb_build_object('assignment_id',v.assignment_id::text,'participant_id',v.participant_id::text,'principal_id',v.principal_id::text,'authority_group_id',v.authority_group_id::text,'role_id',v.role_id::text,'authority_envelope_id',v.authority_envelope_id::text,'delegation_epoch',v.delegation_epoch::text,'scope_digest',v.scope_digest::text,'privacy_domain_ids',v.privacy_domain_ids::text,'action_intent_ids',v.action_intent_ids::text,'runtime_capability_ids',v.runtime_capability_ids::text,'resource_ids',v.resource_ids::text,'risk_classes',v.risk_classes::text,'maker_checker_required',v.maker_checker_required::text,'step_up_required',v.step_up_required::text,'onward_delegation_depth',v.onward_delegation_depth::text,'valid_during',v.valid_during::text,'state',v.state::text,'created_by_principal_id',v.created_by_principal_id::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.assignment v
   WHERE v.participant_id=a.participant_id AND v.assignment_id=(retained->>'assignment_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'

   OR NOT ((actual->>'valid_during')::tstzrange @> clock_timestamp())

  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') LOOP
  SELECT jsonb_build_object('delegation_id',v.delegation_id::text,'participant_id',v.participant_id::text,'parent_assignment_id',v.parent_assignment_id::text,'parent_delegation_id',v.parent_delegation_id::text,'grantor_principal_id',v.grantor_principal_id::text,'delegate_principal_id',v.delegate_principal_id::text,'delegation_epoch',v.delegation_epoch::text,'scope_digest',v.scope_digest::text,'privacy_domain_ids',v.privacy_domain_ids::text,'action_intent_ids',v.action_intent_ids::text,'runtime_capability_ids',v.runtime_capability_ids::text,'resource_ids',v.resource_ids::text,'risk_classes',v.risk_classes::text,'maker_checker_required',v.maker_checker_required::text,'step_up_required',v.step_up_required::text,'onward_delegation_depth',v.onward_delegation_depth::text,'valid_during',v.valid_during::text,'state',v.state::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.delegation v
   WHERE v.participant_id=a.participant_id AND v.delegation_id=(retained->>'delegation_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'

   OR NOT ((actual->>'valid_during')::tstzrange @> clock_timestamp())

  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;

 FOR retained IN SELECT value FROM jsonb_array_elements(snapshot->'dependencies'->'credential') LOOP
  SELECT jsonb_build_object('credential_id',v.credential_id::text,'participant_id',v.participant_id::text,'principal_id',v.principal_id::text,'kind',v.kind::text,'state',v.state::text,'credential_epoch',v.credential_epoch::text,'valid_from',v.valid_from::text,'valid_until',v.valid_until::text,'public_key_digest',v.public_key_digest::text,'row_version',v.row_version::text) INTO STRICT actual FROM control.credential v
   WHERE v.participant_id=a.participant_id AND v.credential_id=(retained->>'credential_id')::uuid;
  IF retained IS DISTINCT FROM actual OR actual->>'state' IS DISTINCT FROM 'ACTIVE'


   OR (actual->>'valid_from')::timestamptz>clock_timestamp()
     OR (actual->>'valid_until' IS NOT NULL AND (actual->>'valid_until')::timestamptz<=clock_timestamp())
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END LOOP;
END $_$;


ALTER FUNCTION openpc.lock_store_retirement_authority(wanted uuid) OWNER TO openpc_control_owner;

--
-- Name: lock_store_retirement_workload(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.lock_store_retirement_workload(host text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE t control.store_retirement_host; now_ms numeric:=floor(extract(epoch from clock_timestamp())*1000);
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_RECONCILE_STORE_BATCH-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT t FROM control.store_retirement_host WHERE host_digest=host
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id();
 IF session_user<>t.database_role OR now_ms<t.valid_from_ms OR now_ms>=t.valid_until_ms THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.participant p WHERE p.participant_id=t.participant_id AND p.state='ACTIVE' AND p.archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.privacy_domain p WHERE p.participant_id=t.participant_id AND p.privacy_domain_id=t.privacy_domain_id AND p.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
  WHERE c.participant_id=t.participant_id AND c.credential_id=t.workload_credential_id
   AND c.credential_epoch=t.workload_credential_epoch AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
   AND c.state='ACTIVE' AND w.kind='WORKLOAD' AND w.state='ACTIVE'
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND c.public_key_digest IS DISTINCT FROM sha256(t.control_spki) AND c.public_key_digest IS DISTINCT FROM sha256(t.target_spki)
  FOR SHARE OF c,w;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;


ALTER FUNCTION openpc.lock_store_retirement_workload(host text) OWNER TO openpc_control_owner;

