--
-- Name: notification_async_initial_disposition(uuid, text, numeric); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_async_initial_disposition(source_event uuid, worker_installation text, qualified_deadline numeric) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE pid uuid:=openpc.current_participant_id();privacy uuid:=openpc.current_privacy_domain_id();
 event control.outbox_event%ROWTYPE;o control.notification_occurrence%ROWTYPE;
 prep control.notification_occurrence_preparation%ROWTYPE;w control.installed_notification_worker%ROWTYPE;
 ep control.notification_endpoint%ROWTYPE;route control.installed_notification_routing%ROWTYPE;
 channel control.installed_notification_channel%ROWTYPE;wm jsonb;lock_name text;why text;now_ms numeric;
BEGIN
 PERFORM openpc.assert_notification_async_worker_owner();
 lock_name:='evidence-lifecycle:'||pid::text;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ExclusiveLock'
  AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
  AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid
  AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-FENCE'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-work-effect:'||pid::text||':'||privacy::text||':'||source_event::text,0))
 OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-worker:'||pid::text||':'||privacy::text,0))
 OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-installation:'||pid::text||':'||privacy::text,0))
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-BUSY'; END IF;
 SELECT * INTO STRICT event FROM control.outbox_event WHERE participant_id=pid AND privacy_domain_id=privacy AND event_id=source_event;
 PERFORM openpc.check_notification_delivery_requested_event(event);
 SELECT * INTO STRICT o FROM control.notification_occurrence WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=event.aggregate_id;
 SELECT p.* INTO STRICT prep FROM control.notification_occurrence_preparation p
 JOIN control.notification_occurrence_observation r USING(participant_id,privacy_domain_id,preparation_id)
 WHERE p.participant_id=pid AND p.privacy_domain_id=privacy AND r.operation_id=event.correlation_id;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=pid AND privacy_domain_id=privacy AND installation_digest=worker_installation;
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF prep.family<>'NotificationDeliveryRequestedReceiptV1' OR prep.state<>'OBSERVED'
 OR prep.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(prep.preparation),'UTF8')
 OR prep.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(prep.preparation_bytes),'hex')
 OR prep.preparation->'workerProfile'->>'environmentId' IS DISTINCT FROM wm->>'1'
 OR prep.preparation->'workerProfile'->>'routingProfileDigest' IS DISTINCT FROM w.routing_profile_digest
 OR w.state<>'ACTIVE' OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR qualified_deadline IS NULL OR qualified_deadline<=floor(extract(epoch from event.occurred_at)*1000)
 OR qualified_deadline>9007199254740991
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-SOURCE'; END IF;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=pid AND privacy_domain_id=privacy AND endpoint_id=o.endpoint_id FOR SHARE;
 SELECT * INTO STRICT route FROM control.installed_notification_routing WHERE participant_id=pid AND privacy_domain_id=privacy AND signed_profile_digest=w.routing_profile_digest;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-routing:'||pid::text||':'||privacy::text||':'||route.profile_id::text,0))
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-BUSY'; END IF;
 -- Re-read after the owner's route fence, never treat missing rows as withdrawal.
 SELECT * INTO STRICT route FROM control.installed_notification_routing WHERE participant_id=pid AND privacy_domain_id=privacy AND signed_profile_digest=w.routing_profile_digest;
 SELECT * INTO STRICT channel FROM control.installed_notification_channel WHERE participant_id=pid AND privacy_domain_id=privacy AND credential_ref=o.credential_ref;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF qualified_deadline<=now_ms THEN why:='INITIAL_DOMAIN_DEADLINE';
 ELSIF ep.state<>'ACTIVE' OR ep.revision IS DISTINCT FROM o.endpoint_revision OR ep.verification_id IS DISTINCT FROM o.verification_id
 OR ep.credential_ref IS DISTINCT FROM o.credential_ref OR ep.channel IS DISTINCT FROM o.channel
 OR ep.destination_ref IS DISTINCT FROM o.destination_ref OR ep.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR route.state<>'ACTIVE' OR route.endpoint_id IS DISTINCT FROM o.endpoint_id
 OR prep.preparation->'workerProfile'->>'producerTrustDigest' IS DISTINCT FROM 'sha256:'||(wm->'16'->>'bytes')
 OR prep.preparation->'workerProfile'->>'kmsInstallationDigest' IS DISTINCT FROM 'sha256:'||(wm->'18'->>'bytes')
 OR now_ms>=(openpc.business_cbor(decode(route.installation->'signed'->>'payloadHex','hex'))->>'7')::numeric
 OR channel.state<>'ACTIVE' OR channel.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR channel.credential->>'state' IS DISTINCT FROM 'ACTIVE'
 OR (channel.credential->>'validUntilMs')::numeric<=now_ms
 OR now_ms>=(openpc.business_cbor(decode(channel.channel_signed->>'payloadHex','hex'))->>'7')::numeric
 THEN why:='INITIAL_SOURCE_WITHDRAWN';
 ELSE RETURN NULL;
 END IF;
 -- A prior budget, signer request or any delivery intent is not an unqueued
 -- no-effect original. Preserve all such uncertainty for its existing owner.
 IF EXISTS(SELECT 1 FROM control.notification_delivery WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_preparation WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_signing s JOIN control.notification_delivery_preparation p USING(participant_id,privacy_domain_id,operation_id) WHERE p.participant_id=pid AND p.privacy_domain_id=privacy AND p.notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_start WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_dispatch_intent WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_outcome WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_outcome_signing WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 OR EXISTS(SELECT 1 FROM control.notification_cancellation_signing WHERE participant_id=pid AND privacy_domain_id=privacy AND notification_occurrence_id=o.notification_occurrence_id)
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-DISPOSITION-ORIGINAL-UNRESOLVED'; END IF;
 RETURN why;
END $$;


ALTER FUNCTION openpc.notification_async_initial_disposition(source_event uuid, worker_installation text, qualified_deadline numeric) OWNER TO openpc_control_owner;

--
-- Name: notification_async_pre_effect_phase(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_async_pre_effect_phase(source_event uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w control.notification_async_work%ROWTYPE;p control.notification_delivery_preparation%ROWTYPE;
 d control.notification_delivery%ROWTYPE;s control.notification_delivery_signing%ROWTYPE;
 event control.outbox_event%ROWTYPE;lock_name text;now_ms numeric;has_delivery boolean;has_signing boolean;
BEGIN
 PERFORM openpc.assert_notification_async_worker_owner();
 SELECT * INTO STRICT w FROM control.notification_async_work WHERE participant_id=openpc.current_participant_id()
 AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=source_event;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||w.participant_id::text,
  'notification-work-effect:'||w.participant_id::text||':'||w.privacy_domain_id::text||':'||w.event_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ExclusiveLock'
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid
   AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
  THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-PRE-EFFECT-FENCE'; END IF;
 END LOOP;
 SELECT * INTO STRICT event FROM control.outbox_event WHERE participant_id=w.participant_id AND privacy_domain_id=w.privacy_domain_id AND event_id=w.event_id;
 -- Includes both actual source inboxes and their original cursor/effect binding.
 PERFORM openpc.check_notification_delivery_requested_event(event);
 PERFORM openpc.assert_notification_delivery_signing_owner();
 SELECT * INTO d FROM control.notification_delivery WHERE participant_id=w.participant_id AND privacy_domain_id=w.privacy_domain_id
 AND notification_occurrence_id=w.notification_occurrence_id FOR UPDATE;
 has_delivery:=FOUND;
 IF EXISTS(SELECT 1 FROM control.notification_cancellation_signing WHERE participant_id=w.participant_id AND privacy_domain_id=w.privacy_domain_id
  AND notification_occurrence_id=w.notification_occurrence_id) OR (has_delivery AND d.cancel_requested)
 THEN RETURN 'HANDED_OFF'; END IF;
 SELECT * INTO p FROM control.notification_delivery_preparation WHERE participant_id=w.participant_id AND privacy_domain_id=w.privacy_domain_id
 AND notification_occurrence_id=w.notification_occurrence_id ORDER BY attempt_number DESC LIMIT 1;
 IF NOT FOUND THEN
  IF has_delivery AND (d.state<>'PENDING' OR d.attempt_count<>0 OR d.last_started_at_ms IS NOT NULL)
  THEN RETURN 'HANDED_OFF'; END IF;
  IF EXISTS(SELECT 1 FROM control.notification_delivery_start WHERE participant_id=w.participant_id AND privacy_domain_id=w.privacy_domain_id AND notification_occurrence_id=w.notification_occurrence_id)
  THEN RETURN 'HANDED_OFF'; END IF;
  IF w.deadline_at_ms<=floor(extract(epoch from clock_timestamp())*1000) THEN RETURN 'STALE_PREPARED'; END IF;
  RETURN 'UNPREPARED';
 END IF;
 IF NOT has_delivery OR p.source_event_id<>w.event_id OR p.worker_installation_digest<>w.worker_installation_digest
 OR p.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p.preparation),'UTF8')
 OR p.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(p.preparation_bytes),'hex')
 OR p.preparation->>'operationId' IS DISTINCT FROM p.operation_id::text
 OR p.preparation->'attempt'->>'attemptId' IS DISTINCT FROM p.attempt_id::text
 OR p.preparation->'attempt'->'attemptNumber' IS DISTINCT FROM to_jsonb(p.attempt_number)
 OR p.preparation->'source'->>'eventId' IS DISTINCT FROM w.event_id::text
 THEN RAISE EXCEPTION 'NOTIFICATION-ASYNC-PRE-EFFECT-ORIGINAL'; END IF;
 IF d.attempt_count<>p.attempt_number-1 OR d.state NOT IN ('PENDING','RETRY_WAIT')
 OR EXISTS(SELECT 1 FROM control.notification_delivery_start WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id AND operation_id=p.operation_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_dispatch_intent WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id AND operation_id=p.operation_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_outcome_signing WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id AND start_operation_id=p.operation_id)
 THEN RETURN 'HANDED_OFF'; END IF;
 SELECT * INTO s FROM control.notification_delivery_signing WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id AND operation_id=p.operation_id FOR UPDATE;
 has_signing:=FOUND;
 IF has_signing THEN
  PERFORM openpc.check_notification_delivery_signing_original(s);
  IF s.state<>'PREPARED' OR s.dispatch_token IS NOT NULL OR s.dispatched_at_ms IS NOT NULL
   OR s.observation IS NOT NULL OR s.observation_bytes IS NOT NULL
  THEN RETURN 'HANDED_OFF'; END IF;
 END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF least((p.preparation->'attempt'->>'deadlineAtMs')::numeric,(p.preparation->>'authorityValidUntilMs')::numeric,w.deadline_at_ms)<=now_ms
 OR d.attempt_limit<p.attempt_number OR p.preparation->>'generationId' IS DISTINCT FROM w.generation_id::text
 OR (p.preparation->'before'->>'revision')::numeric<>d.revision
 THEN RETURN 'STALE_PREPARED'; END IF;
 RETURN CASE WHEN has_signing THEN 'SIGNING_PREPARED' ELSE 'PREPARED' END;
END $$;


ALTER FUNCTION openpc.notification_async_pre_effect_phase(source_event uuid) OWNER TO openpc_control_owner;

--
-- Name: notification_business_projection(control.notification); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_business_projection(item control.notification) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',(item).severity,'1',(item).state,'2',(item).message_key,
  '3',CASE WHEN (item).resource_ref IS NULL THEN 0 ELSE 1 END,
  '5',openpc.business_bytes(decode(substr((item).candidate_digest,8),'hex')))
  || CASE WHEN (item).resource_ref IS NULL THEN '{}'::jsonb
     ELSE jsonb_build_object('4',(item).resource_ref) END
$$;


ALTER FUNCTION openpc.notification_business_projection(item control.notification) OWNER TO openpc_control_owner;

--
-- Name: notification_completion_phase_binding(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_completion_phase_binding(event uuid, phase text) RETURNS TABLE(installation_digest text, authority_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
BEGIN
 PERFORM openpc.require_notification_completion_disposition_authority(event,phase);
 RETURN QUERY SELECT a.proof->>'installationDigest',a.proof->>'authorityDigest'
 FROM control.notification_completion_phase_admission a WHERE a.database_role=session_user
  AND a.transaction_id=pg_current_xact_id()::text AND a.backend_pid=pg_backend_pid()
  AND a.participant_id=openpc.current_participant_id() AND a.privacy_domain_id=openpc.current_privacy_domain_id()
  AND a.event_id=event AND a.phase=$2;
END $_$;


ALTER FUNCTION openpc.notification_completion_phase_binding(event uuid, phase text) OWNER TO openpc_control_owner;

--
-- Name: notification_completion_remediation_projection(control.notification_completion_disposition); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_completion_remediation_projection(item control.notification_completion_disposition) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb:=item.transition->'receipt';w control.installed_notification_completion_worker%ROWTYPE;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR item.disposition IS DISTINCT FROM 'QUARANTINED' OR r->>'workItemKind' IS DISTINCT FROM 'REMEDIATION'
 OR r->>'workItemId' IS DISTINCT FROM item.receipt_id::text OR r->>'sourceEventId' IS DISTINCT FROM item.event_id::text
 THEN RAISE EXCEPTION 'COMPLETION-REMEDIATION-BINDING'; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=r->>'workerInstallationDigest';
 RETURN jsonb_build_object('0','REMEDIATION','1','OPEN','2','urn:openpc:resource:'||item.event_id::text,
 '3',openpc.business_bytes(sha256(item.receipt_payload)),
 '4',openpc.business_bytes(sha256(convert_to('Notification completion could not be processed.','UTF8'))),
 '5',openpc.business_uuid(w.principal_id),'6',0,'8',0,'10',0);
END $$;


ALTER FUNCTION openpc.notification_completion_remediation_projection(item control.notification_completion_disposition) OWNER TO openpc_control_owner;

--
-- Name: notification_completion_source_envelope(control.outbox_event); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_completion_source_envelope(e control.outbox_event) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('participantId',e.participant_id,'privacyDomainId',e.privacy_domain_id,'eventId',e.event_id,'eventType',e.event_type,'aggregateType',e.aggregate_type,'aggregateId',e.aggregate_id,
 'sequence',e.business_sequence::text,'aggregateSequence',e.aggregate_sequence::text,'proofKind',e.proof_kind,'namespace',e.sequence_namespace,'source',e.source,'subject',e.subject,
 'correlationId',e.correlation_id,'causationId',e.causation_id,'dataSchema',e.data_schema_uri,'payloadHex',encode(e.payload_cbor,'hex'),
 'payloadDigest',encode(e.payload_digest,'hex'),'occurredAtUs',floor(extract(epoch from e.occurred_at)*1000000)::text,
 'receiptId',e.receipt_id,'coseHex',encode(e.cose_sign1,'hex'),'authorityGenerationHex',encode(e.authority_generation,'hex'),'webauthnAssertionBindingDigest',encode(e.webauthn_assertion_binding_digest,'hex'));
$$;


ALTER FUNCTION openpc.notification_completion_source_envelope(e control.outbox_event) OWNER TO openpc_control_owner;

--
-- Name: notification_completion_verified_receipt(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_completion_verified_receipt(event uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE verified jsonb;
BEGIN
 PERFORM openpc.require_notification_completion_disposition_authority(event,phase);
 IF phase IS NULL OR phase NOT IN ('OBSERVE','PUBLISH') THEN RAISE EXCEPTION 'NOTIFICATION-COMPLETION-NATIVE-RECEIPT'; END IF;
 SELECT a.receipt_binding INTO STRICT verified FROM control.notification_completion_phase_admission a
  WHERE a.database_role=session_user AND a.transaction_id=pg_current_xact_id()::text AND a.backend_pid=pg_backend_pid()
   AND a.participant_id=openpc.current_participant_id() AND a.privacy_domain_id=openpc.current_privacy_domain_id()
   AND a.event_id=event AND a.phase=$2 AND a.receipt_binding=a.proof->'receiptBinding';
 IF verified IS NULL THEN RAISE EXCEPTION 'NOTIFICATION-COMPLETION-NATIVE-RECEIPT'; END IF;
 RETURN verified;
END $_$;


ALTER FUNCTION openpc.notification_completion_verified_receipt(event uuid, phase text) OWNER TO openpc_control_owner;

--
-- Name: notification_endpoint; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.notification_endpoint (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    endpoint_id uuid NOT NULL,
    channel text NOT NULL,
    destination_ref text NOT NULL,
    channel_profile_digest text NOT NULL,
    credential_ref text NOT NULL,
    state text DEFAULT 'DISABLED'::text NOT NULL,
    arbitrary_egress boolean DEFAULT false NOT NULL,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    candidate_digest text NOT NULL,
    verification_id uuid,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT notification_endpoint_candidate_ck CHECK ((candidate_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT notification_endpoint_channel_ck CHECK ((channel = ANY (ARRAY['WEBHOOK'::text, 'EMAIL'::text, 'OPERATIONS_QUEUE'::text]))),
    CONSTRAINT notification_endpoint_credential_ck CHECK ((credential_ref ~ '^urn:openpc:[a-z][a-z0-9-]{0,62}:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT notification_endpoint_destination_ck CHECK ((destination_ref ~ '^urn:openpc:[a-z][a-z0-9-]{0,62}:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT notification_endpoint_profile_ck CHECK ((channel_profile_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT notification_endpoint_revision_ck CHECK (((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric))),
    CONSTRAINT notification_endpoint_state_ck CHECK (((state = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text, 'QUARANTINED'::text, 'RETIRED'::text])) AND ((state = 'ACTIVE'::text) = (verification_id IS NOT NULL)) AND ((revision <> (1)::numeric) OR (state = 'DISABLED'::text)) AND (NOT arbitrary_egress)))
);

ALTER TABLE ONLY control.notification_endpoint FORCE ROW LEVEL SECURITY;


ALTER TABLE control.notification_endpoint OWNER TO openpc_control_owner;

--
-- Name: notification_endpoint_business_projection(control.notification_endpoint); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_endpoint_business_projection(item control.notification_endpoint) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',(item).channel,'1',(item).state,'2',(item).destination_ref,
   '3',openpc.business_bytes(decode(substr((item).channel_profile_digest,8),'hex')),'4',(item).credential_ref,
   '5',0,'6',openpc.business_bytes(decode(substr((item).candidate_digest,8),'hex')),
   '7',CASE WHEN (item).verification_id IS NULL THEN 0 ELSE 1 END)
   || CASE WHEN (item).verification_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('8',(item).verification_id::text) END
$$;


ALTER FUNCTION openpc.notification_endpoint_business_projection(item control.notification_endpoint) OWNER TO openpc_control_owner;

--
-- Name: notification_failure_initial_projection(control.notification_delivery_outcome); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_failure_initial_projection(o control.notification_delivery_outcome) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w control.installed_notification_worker%ROWTYPE;
BEGIN
 PERFORM openpc.check_notification_outcome_publication_receipt(o);
 IF o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'FAILED' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-NOT-FAILED'; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND installation_digest=o.worker_installation_digest;
 RETURN jsonb_build_object('0','DELIVERY_FAILURE','1','OPEN','2','urn:openpc:resource:'||o.notification_occurrence_id::text,'3',openpc.business_bytes(decode(substr(o.receipt_digest,8),'hex')),
 '4',openpc.business_bytes(sha256(convert_to('Notification delivery failed.','UTF8'))),'5',openpc.business_uuid(w.principal_id),'6',0,'8',0,'10',0);
END $$;


ALTER FUNCTION openpc.notification_failure_initial_projection(o control.notification_delivery_outcome) OWNER TO openpc_control_owner;

--
-- Name: notification_occurrence_metadata_preparation(control.notification); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.notification_occurrence_metadata_preparation(item control.notification) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op control.notification_occurrence_preparation%ROWTYPE; dp control.notification_occurrence_preparation%ROWTYPE;
 original control.notification_occurrence_observation%ROWTYPE; proof control.notification_occurrence_observation%ROWTYPE;
 source control.evidence_export_completion%ROWTYPE; m jsonb; o jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR item.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT p.* INTO STRICT op FROM control.notification_occurrence_preparation p
 JOIN control.notification_occurrence_observation r USING(participant_id,privacy_domain_id,preparation_id)
 WHERE p.participant_id=item.participant_id AND p.privacy_domain_id=item.privacy_domain_id
 AND p.family='NotificationOccurrenceReceiptV1' AND p.state='OBSERVED'
 AND openpc.business_cbor(r.receipt_payload)->'6'=openpc.business_uuid(item.notification_id);
 SELECT * INTO STRICT original FROM control.notification_occurrence_observation
 WHERE participant_id=op.participant_id AND privacy_domain_id=op.privacy_domain_id AND preparation_id=op.preparation_id;
 SELECT * INTO STRICT dp FROM control.notification_occurrence_preparation
 WHERE participant_id=op.participant_id AND privacy_domain_id=op.privacy_domain_id
 AND key_preparation_id=op.key_preparation_id AND family='NotificationDeliveryRequestedReceiptV1' AND state='OBSERVED';
 SELECT * INTO STRICT proof FROM control.notification_occurrence_observation
 WHERE participant_id=dp.participant_id AND privacy_domain_id=dp.privacy_domain_id AND preparation_id=dp.preparation_id;
 m:=openpc.business_cbor(proof.receipt_payload);o:=openpc.business_cbor(original.receipt_payload);
 PERFORM openpc.archive_cose_binding(proof.receipt_payload,proof.cose_sign1,'sha256:'||(m->'24'->>'bytes'),24020,357);
 PERFORM openpc.archive_cose_binding(original.receipt_payload,original.cose_sign1,'sha256:'||(o->'24'->>'bytes'),24019,356);
 IF original.receipt_payload IS DISTINCT FROM decode(op.preparation->>'payloadHex','hex')
 OR proof.receipt_payload IS DISTINCT FROM decode(dp.preparation->>'payloadHex','hex')
 OR original.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(original.receipt_payload),'hex')
 OR m->'25' IS DISTINCT FROM jsonb_build_object('bytes',encode(sha256(original.receipt_payload),'hex'))
 OR m->'1' IS DISTINCT FROM o->'1'
 OR m->'2' IS DISTINCT FROM o->'2'
 OR m->'3' IS DISTINCT FROM o->'3'
 OR m->'6' IS DISTINCT FROM o->'6'
 OR m->'7' IS DISTINCT FROM o->'7'
 OR m->'8' IS DISTINCT FROM o->'8'
 OR m->'9' IS DISTINCT FROM o->'9'
 OR m->'10' IS DISTINCT FROM o->'10'
 OR m->'11' IS DISTINCT FROM o->'11'
 OR m->'12' IS DISTINCT FROM o->'12'
 OR m->'13' IS DISTINCT FROM o->'13'
 OR m->'16' IS DISTINCT FROM o->'16'
 OR m->'17' IS DISTINCT FROM o->'17'
 OR m->'18' IS DISTINCT FROM o->'18'
 OR m->'19' IS DISTINCT FROM o->'19'
 OR m->'20' IS DISTINCT FROM o->'20'
 OR m->'21' IS DISTINCT FROM o->'21'
 OR m->'22' IS DISTINCT FROM o->'22'
 OR m->'4' IS NOT DISTINCT FROM o->'4' OR m->'5' IS NOT DISTINCT FROM o->'5'
 OR (m->>'23')::numeric<(o->>'23')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-METADATA-PAIR'; END IF;
 SELECT * INTO STRICT source FROM control.evidence_export_completion
 WHERE participant_id=op.participant_id AND privacy_domain_id=op.privacy_domain_id AND event_id=op.source_event_id;
 IF item.severity IS DISTINCT FROM 'INFO' OR item.state IS DISTINCT FROM 'UNREAD' OR item.revision IS DISTINCT FROM 1::numeric
 OR item.message_key IS DISTINCT FROM 'evidence.export.completed'
 OR item.resource_ref IS DISTINCT FROM 'urn:openpc:resource:'||source.evidence_export_id::text
 OR item.candidate_digest IS DISTINCT FROM original.receipt_digest
 OR source.state IS DISTINCT FROM 'PUBLISHED'
 OR source.receipt_payload_digest IS DISTINCT FROM 'sha256:'||(o->'12'->>'bytes')
 OR o->'10' IS DISTINCT FROM openpc.business_uuid(source.event_id)
 OR o->'2' IS DISTINCT FROM openpc.business_uuid(item.participant_id)
 OR o->'3' IS DISTINCT FROM openpc.business_uuid(item.privacy_domain_id)
 THEN RAISE EXCEPTION 'NOTIFICATION-OCCURRENCE-METADATA'; END IF;
 RETURN dp.preparation_id;
END $$;


ALTER FUNCTION openpc.notification_occurrence_metadata_preparation(item control.notification) OWNER TO openpc_control_owner;

--
-- Name: observe_oidc_identity_claim(); Type: FUNCTION; Schema: openpc; Owner: openpc_identity_binding_owner
--

CREATE FUNCTION openpc.observe_oidc_identity_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE local_subject uuid; existing control.identity_oidc_binding%ROWTYPE; qualified boolean;
BEGIN
 IF TG_OP='UPDATE' AND OLD.kind='OIDC_SUBJECT' AND
   (OLD.kind,OLD.participant_id,OLD.principal_id,OLD.issuer,OLD.subject,OLD.audience) IS DISTINCT FROM
   (NEW.kind,NEW.participant_id,NEW.principal_id,NEW.issuer,NEW.subject,NEW.audience) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-OIDC-CLAIM-IMMUTABLE';
 END IF;
 -- Invalid legacy accounts remain unusable for proof resolution; ordinary scoped login retains its checks.
 IF NEW.kind<>'OIDC_SUBJECT' OR NEW.issuer IS NULL OR NEW.subject IS NULL OR NEW.audience IS NULL
   OR length(NEW.issuer)=0 OR length(NEW.subject) NOT BETWEEN 1 AND 255 OR length(NEW.audience)=0 THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(NEW.issuer,NEW.subject,NEW.audience)::text,713));
 SELECT membership.identity_subject_id INTO local_subject FROM control.participant_membership membership
  WHERE membership.participant_id=NEW.participant_id AND membership.membership_id=NEW.principal_id;
 qualified:=local_subject IS NOT NULL AND NEW.state='ACTIVE' AND NEW.credential_epoch>0
   AND NEW.valid_from<=clock_timestamp() AND (NEW.valid_until IS NULL OR NEW.valid_until>clock_timestamp());
 SELECT * INTO existing FROM control.identity_oidc_binding
  WHERE issuer=NEW.issuer AND subject=NEW.subject AND audience=NEW.audience FOR UPDATE;
 IF NOT FOUND THEN
  INSERT INTO control.identity_oidc_binding(issuer,subject,audience,identity_subject_id,state)
   VALUES(NEW.issuer,NEW.subject,NEW.audience,CASE WHEN qualified THEN local_subject ELSE NULL END,
    CASE WHEN qualified THEN 'UNVERIFIED_LEGACY' ELSE 'AMBIGUOUS_LEGACY' END);
 ELSIF existing.state='BOUND' THEN
  -- Local revocation cannot revoke a global identity. A different local subject cannot claim it.
  IF existing.identity_subject_id IS DISTINCT FROM local_subject THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-OIDC-IDENTITY-CONFLICT';
  END IF;
 ELSIF existing.state='UNVERIFIED_LEGACY' AND (NOT qualified OR existing.identity_subject_id IS DISTINCT FROM local_subject) THEN
  UPDATE control.identity_oidc_binding SET state='AMBIGUOUS_LEGACY',identity_subject_id=NULL
   WHERE issuer=NEW.issuer AND subject=NEW.subject AND audience=NEW.audience;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.observe_oidc_identity_claim() OWNER TO openpc_identity_binding_owner;

--
-- Name: observe_runtime_artifact_references(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.observe_runtime_artifact_references(p_input uuid, p_digest text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE lock_key text; expected_mode text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR current_setting('session_replication_role')<>'origin' OR openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR (p_digest ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true OR p_input IS NULL
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-OBSERVATION-CONTEXT'; END IF;
 -- Exactly the existing lockModuleLifecycleReferences order; the application
 -- obtains these before this read. Never upgrade/acquire after owner row locks.
 FOREACH lock_key IN ARRAY ARRAY['evidence-lifecycle:'||openpc.current_participant_id()::text,'module-release-catalog','module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,
 'openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text] LOOP
  expected_mode:=case when lock_key like 'module-admission:%' or lock_key like 'evidence-lifecycle:%' then 'ExclusiveLock' else 'ShareLock' end;
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode=expected_mode
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND l.classid=((hashtextextended(lock_key,0)>>32)&4294967295)::oid
   AND l.objid=(hashtextextended(lock_key,0)&4294967295)::oid AND l.objsubid=1)
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-OBSERVATION-FENCE'; END IF;
 END LOOP;
 -- All branches use one SQL statement snapshot and original tables, including
 -- terminal rows. The cap produces unresolved coverage, never an empty proof.
 RETURN (select jsonb_build_object('participantId',openpc.current_participant_id()::text,'privacyDomainId',openpc.current_privacy_domain_id()::text,
 'root', (select jsonb_build_object('kind','INPUT','id',(runtime_configuration_input_id)::text,'participantId',participant_id::text,'privacyDomainId',privacy_domain_id::text,'revision',null,'state',case when selected then 'SELECTED' else 'RETAINED' end,'digests',jsonb_build_object('configuration','sha256:'||encode(configuration_digest,'hex'),'bindings','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(resource_bindings),'UTF8')),'hex')),'references',((select coalesce(jsonb_agg(value),'[]'::jsonb) from jsonb_array_elements(jsonb_build_array(case when module_configuration_generation_id is null then null else jsonb_build_object('kind','MODULE_CONFIGURATION','id',(module_configuration_generation_id)::text,'required',true) end,case when module_installation_id is null then null else jsonb_build_object('kind','MODULE_INSTALLATION','id',(module_installation_id)::text,'required',true) end)) where value<>'null'::jsonb)||(select coalesce(jsonb_agg(jsonb_build_object('kind',case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end,'id',binding->>'id','required',true)),'[]'::jsonb)
 from jsonb_array_elements(resource_bindings) binding where (case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end) is not null)),'tokens',(select coalesce(jsonb_agg(value),'[]'::jsonb) from jsonb_array_elements(jsonb_build_array(case when 'sha256:'||encode(configuration_digest,'hex') is null then null else jsonb_build_object('kind','CONFIGURATION','digest','sha256:'||encode(configuration_digest,'hex')) end)) where value<>'null'::jsonb),'checks',jsonb_build_object('bytesMatch',(openpc.runtime_artifact_input_information(runtime_configuration_input_id)->>'bytesMatch')::boolean,'bindingsKnown',not exists(select 1 from jsonb_array_elements(resource_bindings) binding where (case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end) is null)),'details',jsonb_build_object('byteLength',openpc.runtime_artifact_input_information(runtime_configuration_input_id)->>'byteLength','createdAt',to_char(created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))) from control.runtime_configuration_input where participant_id=openpc.current_participant_id()
  and privacy_domain_id=openpc.current_privacy_domain_id() and runtime_configuration_input_id=p_input and configuration_digest=decode(substr(p_digest,8),'hex')),
 'runtimeProducerFencesObserved',not exists(select 1 from unnest(array['runtime_configuration_input','configuration_work','runtime_configuration_generation','runtime_target','policy_activation_occurrence','policy_activation_occurrence_target','runtime_activation_observation','runtime_target_connection','runtime_route_publication','provider_probe_observation','runtime_target_disposition_admission','runtime_target_disposition_delivery','runtime_target_disposition_acknowledgement']) expected(table_name)
 where not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
 join pg_namespace n on n.oid=c.relnamespace join pg_roles co on co.oid=c.relowner
 join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace
 join pg_roles po on po.oid=p.proowner join pg_language lang on lang.oid=p.prolang
 where n.nspname='control' and c.relname=expected.table_name and co.rolname='openpc_control_owner'
 and c.relkind='r' and c.relrowsecurity and not c.relispartition
 and not exists(select 1 from pg_inherits i where i.inhparent=c.oid or i.inhrelid=c.oid)
 and t.tgname='artifact_lifecycle_fence' and t.tgtype=62 and t.tgenabled in ('O','A') and not t.tgisinternal
 and t.tgconstraint=0 and t.tgparentid=0 and not t.tgdeferrable and not t.tginitdeferred
 and t.tgnargs=0 and octet_length(t.tgargs)=0 and t.tgattr::text='' and t.tgqual is null
 and t.tgoldtable is null and t.tgnewtable is null
 and pn.nspname='openpc' and po.rolname='openpc_control_owner' and p.proname='guard_runtime_artifact_lifecycle_fence'
 and lang.lanname='plpgsql' and p.prokind='f' and p.provolatile='v' and not p.prosecdef and not p.proisstrict
 and not p.proleakproof and p.proparallel='u' and not p.proretset and p.prosupport=0
 and p.prorettype='pg_catalog.trigger'::regtype and p.pronargs=0 and p.pronargdefaults=0 and p.provariadic=0 and p.proargmodes is null
 and p.proconfig=array['search_path=pg_catalog']::text[] and p.prosrc='
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
   OR TG_OP=''TRUNCATE'' OR current_setting(''session_replication_role'')<>''origin''
 THEN RAISE EXCEPTION USING ERRCODE=''P0001'',MESSAGE=''PC-DATA-6004''; END IF;
 -- Producers can already own module, policy, target or occurrence locks.
 -- Never wait in the reverse order. Use the exclusive lock also used by
 -- evidence publication, avoiding shared-to-exclusive upgrade deadlocks.
