ALTER FUNCTION openpc.observe_runtime_artifact_references(p_input uuid, p_digest text) OWNER TO openpc_control_owner;

--
-- Name: operations_generation_missing(text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_generation_missing(p_environment text, p_generation uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM control.operations_generation
 WHERE environment_id=p_environment AND generation_id=p_generation)
 THEN '["GENERATION:MISSING"]'::jsonb
 ELSE coalesce(jsonb_agg(requirement ORDER BY requirement),'[]'::jsonb) END
 FROM control.operations_generation g CROSS JOIN LATERAL jsonb_array_elements_text(g.requirements) requirement
 WHERE g.environment_id=p_environment AND g.generation_id=p_generation
 AND CASE WHEN requirement='SOURCE:C17_AUTHENTICATION'
 THEN NOT openpc.operations_generation_source_authenticated(p_environment,p_generation)
 WHEN requirement='QUALIFICATION:provider.read_retry_limit'
 THEN NOT coalesce(openpc.operations_provider_retry_qualification_bound(p_environment,p_generation),false)
 ELSE NOT EXISTS(SELECT 1 FROM control.operations_generation_binding b
 WHERE b.environment_id=g.environment_id AND b.generation_id=g.generation_id AND b.requirement_id=requirement
 AND b.participant_id=g.participant_id AND b.privacy_domain_id=g.privacy_domain_id AND b.state='CURRENT'
 AND b.valid_until_ms>floor(extract(epoch from clock_timestamp())*1000)
 AND b.effective_digest=g.candidate->'configuration'->'generation'->>'contentDigest') END;
$$;


ALTER FUNCTION openpc.operations_generation_missing(p_environment text, p_generation uuid) OWNER TO openpc_control_owner;

--
-- Name: operations_generation_requirements(jsonb, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_generation_requirements(p_schema jsonb, p_configuration jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT jsonb_agg(requirement ORDER BY requirement) FROM (
 SELECT 'SOURCE:C17_AUTHENTICATION' requirement
 UNION SELECT 'QUALIFICATION:'||key FROM jsonb_object_keys(p_configuration->'qualificationInputBindings') key
 UNION SELECT 'SECRET:'||section.key||'.'||field.key
 FROM jsonb_each(p_schema->'properties') section CROSS JOIN LATERAL jsonb_each(section.value->'properties') field
 WHERE field.value->>'$ref'='#/$defs/SecretRef'
 UNION SELECT phase||':'||component
 FROM jsonb_array_elements(p_schema->'x-openpc-settingCatalog') setting
 CROSS JOIN LATERAL jsonb_array_elements_text(setting->'componentRefs') component
 CROSS JOIN (VALUES('CONSUMER_STAGED'),('CONSUMER_EFFECTIVE')) phases(phase)
 UNION SELECT phase||':'||unit FROM (VALUES
 ('DU-PC-WORKBENCH'),('DU-PC-CONTROL'),('DU-PC-COMPILER'),('DU-PC-FLEET-CONTROL'),
 ('DU-PC-RUNTIME'),('DU-PC-FACT-BRIDGE'),('DU-ENVOY'),('DU-OTEL-COLLECTOR')) units(unit)
 CROSS JOIN (VALUES('UNIT_STAGED'),('UNIT_EFFECTIVE')) phases(phase)
 ) required;
$_$;


ALTER FUNCTION openpc.operations_generation_requirements(p_schema jsonb, p_configuration jsonb) OWNER TO openpc_control_owner;

--
-- Name: operations_generation_source_authenticated(text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_generation_source_authenticated(p_environment text, p_generation uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE installed control.operations_installation%ROWTYPE; candidate control.operations_generation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_request_context(true);
 -- Source truth is also consumed by existing SECURITY DEFINER read owners
 -- (for example current_notification_delivery_limit). Do not require their
 -- current role/action to equal an installation mutation's role/action. EXECUTE
 -- grants, request scope and actual rows remain enforced; commit admission is
 -- still a separate guarded operation on its own same transaction client.
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed'
  OR current_setting('row_security') IS DISTINCT FROM 'on'
  OR current_setting('openpc.context_mode',true) IS DISTINCT FROM 'PARTICIPANT'
 THEN RETURN false; END IF;
 SELECT * INTO installed FROM control.operations_installation WHERE environment_id=p_environment;
 SELECT * INTO candidate FROM control.operations_generation WHERE environment_id=p_environment AND generation_id=p_generation;
 IF installed.environment_id IS NULL OR candidate.generation_id IS NULL
  OR installed.state<>'ACTIVE' OR candidate.state<>'STAGED'
  OR installed.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR installed.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR candidate.participant_id IS DISTINCT FROM installed.participant_id
  OR candidate.privacy_domain_id IS DISTINCT FROM installed.privacy_domain_id
  OR installed.installation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(installed.installation_bytes),'hex')
  OR installed.installation IS DISTINCT FROM convert_from(installed.installation_bytes,'UTF8')::jsonb
  OR installed.installation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(installed.installation),'UTF8')
  OR installed.installation->'pins'->>'environmentId' IS DISTINCT FROM p_environment
  OR candidate.candidate_digest IS DISTINCT FROM 'sha256:'||encode(sha256(candidate.candidate_bytes),'hex')
  OR candidate.candidate IS DISTINCT FROM convert_from(candidate.candidate_bytes,'UTF8')::jsonb
  OR candidate.candidate_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(candidate.candidate),'UTF8')
  OR candidate.candidate->'configuration'->>'environmentId' IS DISTINCT FROM p_environment
  OR candidate.candidate->'configuration'->>'profile' IS DISTINCT FROM installed.installation->'pins'->>'profile'
  OR candidate.candidate->'configuration'->'generation'->>'generationId' IS DISTINCT FROM 'urn:openpc:generation:'||p_generation::text
  OR candidate.candidate->'configuration'->'generation'->>'baseGenerationId' IS DISTINCT FROM 'urn:openpc:generation:'||candidate.base_generation_id::text
 THEN RETURN false; END IF;
 RETURN openpc.operations_source_authentication_valid(installed.installation);
END $$;


ALTER FUNCTION openpc.operations_generation_source_authenticated(p_environment text, p_generation uuid) OWNER TO openpc_control_owner;

--
-- Name: operations_observer_backend_start(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_observer_backend_start() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT backend_start::text FROM pg_catalog.pg_stat_activity
 WHERE pid=pg_catalog.pg_backend_pid() AND usesysid=session_user::regrole
$$;


ALTER FUNCTION openpc.operations_observer_backend_start() OWNER TO openpc_control_owner;

--
-- Name: operations_provider_retry_qualification_bound(text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_provider_retry_qualification_bound(p_environment text, p_generation uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b control.operations_provider_retry_qualification%ROWTYPE;
 root control.operations_qualification_root%ROWTYPE; current_state control.operations_qualification_state%ROWTYPE;
 issuance control.operations_qualification_state%ROWTYPE; g control.operations_generation%ROWTYPE;
 installed control.operations_installation%ROWTYPE; i jsonb; r jsonb; doc jsonb; kd jsonb; rd jsonb; ikd jsonb; ird jsonb;
 evidence jsonb; key_entry jsonb; claims jsonb; purpose text; issued numeric; expiry numeric; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('operations-generation:'||p_environment,0));
 SELECT * INTO b FROM control.operations_provider_retry_qualification WHERE environment_id=p_environment AND generation_id=p_generation;
 IF b.generation_id IS NULL THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('operations-qualification:'||p_environment||':'||b.authority_id,0));
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 SELECT * INTO root FROM control.operations_qualification_root WHERE environment_id=p_environment AND authority_id=b.authority_id ORDER BY root_epoch DESC LIMIT 1 FOR SHARE;
 SELECT * INTO current_state FROM control.operations_qualification_state WHERE environment_id=p_environment AND authority_id=b.authority_id ORDER BY sequence DESC LIMIT 1;
 SELECT * INTO issuance FROM control.operations_qualification_state WHERE environment_id=p_environment AND authority_id=b.authority_id AND sequence=b.issuance_sequence;
 SELECT * INTO g FROM control.operations_generation WHERE environment_id=p_environment AND generation_id=p_generation FOR SHARE;
 SELECT * INTO installed FROM control.operations_installation WHERE environment_id=p_environment FOR SHARE;
 IF root.authority_id IS NULL OR current_state.authority_id IS NULL OR issuance.authority_id IS NULL
 OR root.state<>'ACTIVE' OR root.valid_from_ms>now_ms OR root.valid_until_ms<=now_ms
 OR current_state.root_epoch<>root.root_epoch OR current_state.valid_until_ms<=now_ms OR b.valid_until_ms<=now_ms
 OR g.state IS DISTINCT FROM 'STAGED' OR installed.state IS DISTINCT FROM 'ACTIVE'
 OR NOT openpc.operations_generation_source_authenticated(p_environment,p_generation)
 OR NOT EXISTS(SELECT 1 FROM control.operations_qualification_root WHERE environment_id=p_environment AND authority_id=b.authority_id AND root_epoch=issuance.root_epoch AND state='ACTIVE')
 THEN RETURN false; END IF;
 i:=openpc.business_cbor(decode(b.custody->'input'->>'payloadHex','hex'));
 i:=openpc.provider_retry_claims('input',decode(b.custody->'input'->>'payloadHex','hex'),decode(b.custody->'input'->>'coseHex','hex'),'sha256:'||(i->'18'->>'bytes'));
 r:=openpc.business_cbor(decode(b.custody->'receipt'->>'payloadHex','hex'));
 r:=openpc.provider_retry_claims('receipt',decode(b.custody->'receipt'->>'payloadHex','hex'),decode(b.custody->'receipt'->>'coseHex','hex'),'sha256:'||(r->'11'->>'bytes'));
 doc:=convert_from(decode(b.custody->'receipt'->>'documentHex','hex'),'UTF8')::jsonb;
 kd:=convert_from(decode(current_state.custody->'keyset'->>'documentHex','hex'),'UTF8')::jsonb;
 rd:=convert_from(decode(current_state.custody->'revocations'->>'documentHex','hex'),'UTF8')::jsonb;
 ikd:=convert_from(decode(issuance.custody->'keyset'->>'documentHex','hex'),'UTF8')::jsonb;
 ird:=convert_from(decode(issuance.custody->'revocations'->>'documentHex','hex'),'UTF8')::jsonb;
 IF i->>'environmentId'<>p_environment OR i->>'authorityId'<>b.authority_id
 OR i->>'profile' IS DISTINCT FROM g.candidate->'configuration'->>'profile'
 OR i->>'configurationSchemaDigest' IS DISTINCT FROM installed.installation->'pins'->>'configurationSchemaDigest'
 OR i->>'namedProfileDigest' IS DISTINCT FROM installed.installation->'pins'->>'namedProfileDigest'
 OR i->>'slot' IS DISTINCT FROM installed.installation->'namedProfile'->'requiredSettingInputs'->>'provider.read_retry_limit'
 OR i->'value' IS DISTINCT FROM g.candidate->'configuration'->'settings'->'provider.read_retry_limit'
 OR r->>'qualificationRef' IS DISTINCT FROM g.candidate->'configuration'->'qualificationInputBindings'->>'provider.read_retry_limit'
 OR (i->>'validFromMs')::numeric>now_ms OR (i->>'validUntilMs')::numeric<=now_ms
 OR (r->>'issuedAtMs')::numeric>now_ms OR (r->>'expiresAtMs')::numeric<=now_ms
 OR r->>'keysetPayloadDigest'<>issuance.keyset_digest OR r->>'revocationPayloadDigest'<>issuance.revocations_digest
 THEN RETURN false; END IF;
 FOR claims,purpose,issued,expiry IN SELECT i,'pc.cose.operations-qualification-input.v1',(i->>'validFromMs')::numeric,(i->>'validUntilMs')::numeric
 UNION ALL SELECT r,'pc.cose.operations-qualification-executed-receipt.v1',(r->>'issuedAtMs')::numeric,(r->>'expiresAtMs')::numeric LOOP
  SELECT key INTO key_entry FROM jsonb_array_elements(kd->'keys') key WHERE key->>'keyId'=claims->>'issuerKeyId' AND key->>'epoch'=claims->>'issuerEpoch' AND key->>'purpose'=purpose;
  IF key_entry IS NULL OR key_entry->>'state' NOT IN ('ACTIVE','RETIRED') OR (key_entry->>'validFromMs')::numeric>issued OR (key_entry->>'validUntilMs')::numeric<expiry
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ikd->'keys') key WHERE key->>'keyId'=claims->>'issuerKeyId' AND key->>'epoch'=claims->>'issuerEpoch' AND key->>'purpose'=purpose AND key->>'state'='ACTIVE' AND key-'state'=key_entry-'state')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(rd->'revocations') rev WHERE rev->>'keyId'=claims->>'issuerKeyId' AND rev->>'keyEpoch'=claims->>'issuerEpoch' AND (rev->>'effectiveAt')::timestamptz<=clock_timestamp())
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(ird->'revocations') rev WHERE rev->>'keyId'=claims->>'issuerKeyId' AND rev->>'keyEpoch'=claims->>'issuerEpoch' AND extract(epoch from (rev->>'effectiveAt')::timestamptz)*1000<=(r->>'issuedAtMs')::numeric)
  THEN RETURN false; END IF;
 END LOOP;
 evidence:=openpc.require_provider_retry_evidence(p_environment,p_generation,b.input_digest,r->>'receiptDocumentDigest');
 RETURN evidence->'input'=i AND evidence->'receiptDocument'=doc;
END $$;


ALTER FUNCTION openpc.operations_provider_retry_qualification_bound(p_environment text, p_generation uuid) OWNER TO openpc_control_owner;

--
-- Name: operations_secret_association_bound(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_secret_association_bound(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.operations_secret_association%ROWTYPE; r jsonb; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' THEN RETURN false; END IF;
 SELECT * INTO a FROM control.operations_secret_association WHERE association_id=p_id FOR SHARE;
 IF a.association_id IS NULL OR a.state<>'ACTIVE' OR NOT openpc.matches_participant(a.participant_id)
  OR NOT openpc.matches_privacy(a.privacy_domain_id) THEN RETURN false; END IF;
 r:=a.association; now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('operations-generation:'||a.environment_id,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF now_ms<(r->>'issuerValidFromMs')::numeric OR now_ms>=(r->>'issuerValidUntilMs')::numeric THEN RETURN false; END IF;
 PERFORM 1 FROM control.participant p JOIN control.privacy_domain d ON d.participant_id=p.participant_id
 JOIN control.principal principal ON principal.participant_id=p.participant_id
 JOIN control.credential c ON c.participant_id=p.participant_id AND c.principal_id=principal.principal_id
 WHERE p.participant_id=a.participant_id AND d.privacy_domain_id=a.privacy_domain_id
 AND principal.principal_id=(r->>'principalId')::uuid AND c.credential_id=(r->>'workloadCredentialId')::uuid
 AND p.state='ACTIVE' AND d.state='ACTIVE' AND principal.state='ACTIVE' AND principal.kind='WORKLOAD'
 AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch=(r->>'workloadCredentialEpoch')::numeric
 AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() FOR SHARE OF p,d,principal,c;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('secret-recipient:'||a.participant_id::text||':'||a.privacy_domain_id::text,0));
 PERFORM 1 FROM control.operations_installation i JOIN control.operations_generation g USING(environment_id)
 JOIN control.installed_secret_recipient s ON s.participant_id=a.participant_id AND s.privacy_domain_id=a.privacy_domain_id
 WHERE i.environment_id=a.environment_id AND g.generation_id=a.generation_id
 AND i.state='ACTIVE' AND g.state='STAGED' AND i.installation_digest=r->>'operationsInstallationDigest'
 AND g.candidate_digest=r->>'candidateDigest' AND i.installation->'pins'->>'profile'='test'
 AND g.candidate->'configuration'->'postgres'->>'candidateIndexDsnSecretRef'=r->>'reference'
 AND s.state='ACTIVE' AND s.consumer_id='LS-FACT-BRIDGE' AND s.store_id='STORE-CANDIDATE-INDEX-PG'
 AND s.binding_digest=r->>'recipientBindingDigest' AND s.installation_digest=r->>'recipientInstallationDigest'
 AND s.generation=(r->>'recipientGeneration')::numeric AND s.payload=decode(r->>'recipientPayloadHex','hex')
 AND s.cose=decode(r->>'recipientCoseHex','hex') AND s.issuer_spki=decode(r->>'recipientIssuerSpkiHex','hex')
 AND s.workload_credential_id=(r->>'workloadCredentialId')::uuid
 AND s.workload_credential_epoch=(r->>'workloadCredentialEpoch')::numeric FOR SHARE OF i,g,s;
 RETURN FOUND;
END $$;


ALTER FUNCTION openpc.operations_secret_association_bound(p_id uuid) OWNER TO openpc_control_owner;

--
-- Name: operations_source_authentication_valid(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.operations_source_authentication_valid(p_installation jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE custody jsonb; selected jsonb; profile_name text; manifest jsonb; entry jsonb;
 schema_bytes bytea; profile_bytes bytea; manifest_bytes bytea;
 profiles CONSTANT jsonb := '{"local":{"path":"SPECIFICATIONS/OPERATIONS/profiles/local.yaml","digest":"sha256:aad2b9f62d1659cec987be45b5e2e7c8d504a706f8583819675118bef14eaa0c","bytes":3014,"canonicalDigest":"sha256:deaa78277144b603295fb75bc2aaf21e8400504aa67680e83981c01822ca2d9a"},"development":{"path":"SPECIFICATIONS/OPERATIONS/profiles/development.yaml","digest":"sha256:e20a644061a759c38d2c09d29a74adb43c8cc683da852a33ade726b4ae5f989f","bytes":3122,"canonicalDigest":"sha256:50bdcd6777e07c9a6cc688c54bf5d14962fbec68f7ccb2fe94854d7b978e94f5"},"test":{"path":"SPECIFICATIONS/OPERATIONS/profiles/test.yaml","digest":"sha256:fc48ee6b68c13821f0fd5b88222629851ad30a21027c69c9cd4a968a301f3c37","bytes":3121,"canonicalDigest":"sha256:e7bf9922e9141cd358f28d79b0cbc70e553e0998c296f610e09a3e846a613997"},"staging":{"path":"SPECIFICATIONS/OPERATIONS/profiles/staging.yaml","digest":"sha256:386955e70c3eb1af05f926fb6385ef523cb96a2b1ac4624f3b8cbbb8a09d252b","bytes":3026,"canonicalDigest":"sha256:8c8c997bd3a2292713973595fbdefedfef01c9a38292da366be7caa48d859d95"},"production":{"path":"SPECIFICATIONS/OPERATIONS/profiles/production.yaml","digest":"sha256:53bd65338e2e8d1334d4ecb3519769ce32a8e706e683f731a0d27263a9d2902a","bytes":3134,"canonicalDigest":"sha256:493d8802e490ce0d088f5c4c119f434a7267c15075dc777e48937c4503649f71"}}'::jsonb;
 public_profiles CONSTANT jsonb := '{"local":{"path":"config/profiles/local.yaml","digest":"sha256:aad2b9f62d1659cec987be45b5e2e7c8d504a706f8583819675118bef14eaa0c","bytes":3014,"canonicalDigest":"sha256:deaa78277144b603295fb75bc2aaf21e8400504aa67680e83981c01822ca2d9a"},"development":{"path":"config/profiles/development.yaml","digest":"sha256:e20a644061a759c38d2c09d29a74adb43c8cc683da852a33ade726b4ae5f989f","bytes":3122,"canonicalDigest":"sha256:50bdcd6777e07c9a6cc688c54bf5d14962fbec68f7ccb2fe94854d7b978e94f5"},"test":{"path":"config/profiles/test.yaml","digest":"sha256:fc48ee6b68c13821f0fd5b88222629851ad30a21027c69c9cd4a968a301f3c37","bytes":3121,"canonicalDigest":"sha256:e7bf9922e9141cd358f28d79b0cbc70e553e0998c296f610e09a3e846a613997"},"staging":{"path":"config/profiles/staging.yaml","digest":"sha256:386955e70c3eb1af05f926fb6385ef523cb96a2b1ac4624f3b8cbbb8a09d252b","bytes":3026,"canonicalDigest":"sha256:8c8c997bd3a2292713973595fbdefedfef01c9a38292da366be7caa48d859d95"},"production":{"path":"config/profiles/production.yaml","digest":"sha256:53bd65338e2e8d1334d4ecb3519769ce32a8e706e683f731a0d27263a9d2902a","bytes":3134,"canonicalDigest":"sha256:493d8802e490ce0d088f5c4c119f434a7267c15075dc777e48937c4503649f71"}}'::jsonb;
BEGIN
 IF jsonb_typeof(p_installation) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 -- Materialize the same JSONB object once for this call's repeated field reads.
 p_installation := p_installation #> '{}'::text[];
 custody:=p_installation->'sourceAuthentication';
 profile_name:=p_installation->'pins'->>'profile'; selected:=profiles->profile_name;
 IF selected IS NULL OR jsonb_typeof(custody) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 IF custody->'version'='2'::jsonb THEN
  selected:=public_profiles->profile_name;
  IF selected IS NULL OR (SELECT count(*) FROM jsonb_object_keys(custody))<>5
   OR NOT custody ?& ARRAY['version','sourceProfile','inventoryHex','schemaHex','profileHex']
   OR custody->>'sourceProfile' IS DISTINCT FROM 'PUBLIC_OPERATIONS_SOURCE_V1'
   OR jsonb_typeof(custody->'inventoryHex') IS DISTINCT FROM 'string'
   OR jsonb_typeof(custody->'schemaHex') IS DISTINCT FROM 'string'
   OR jsonb_typeof(custody->'profileHex') IS DISTINCT FROM 'string'
  THEN RETURN false; END IF;
  IF length(custody->>'inventoryHex')<>2378
   OR length(custody->>'schemaHex')<>93796
   OR length(custody->>'profileHex')<>(selected->>'bytes')::integer*2
   OR custody->>'inventoryHex' !~ '^[0-9a-f]+$'
   OR custody->>'schemaHex' !~ '^[0-9a-f]+$'
   OR custody->>'profileHex' !~ '^[0-9a-f]+$'
  THEN RETURN false; END IF;
  manifest_bytes:=decode(custody->>'inventoryHex','hex');
  schema_bytes:=decode(custody->>'schemaHex','hex');
  profile_bytes:=decode(custody->>'profileHex','hex');
  IF 'sha256:'||encode(sha256(manifest_bytes),'hex') IS DISTINCT FROM 'sha256:e467be325380375f53f5ae7a91cb56c24c2dbe02c383156aed97ffa8350547e6'
   OR 'sha256:'||encode(sha256(schema_bytes),'hex') IS DISTINCT FROM 'sha256:350280220fae0d2fb0c360cb1c5a9011e8c46218e7b10b9a269fba78078496cd'
   OR 'sha256:'||encode(sha256(profile_bytes),'hex') IS DISTINCT FROM selected->>'digest'
  THEN RETURN false; END IF;
  manifest:=convert_from(manifest_bytes,'UTF8')::jsonb;
  IF manifest->>'schema' IS DISTINCT FROM 'pc.operations.public-source-inventory'
   OR manifest->'schemaVersion' IS DISTINCT FROM '1'::jsonb
   OR manifest->>'sourceProfile' IS DISTINCT FROM 'PUBLIC_OPERATIONS_SOURCE_V1'
   OR jsonb_typeof(manifest->'files') IS DISTINCT FROM 'array'
   OR jsonb_array_length(manifest->'files')<>6
  THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(manifest->'files') f
   WHERE f->>'path'='config/schema/effective-configuration.schema.json' AND f->>'digest'='sha256:350280220fae0d2fb0c360cb1c5a9011e8c46218e7b10b9a269fba78078496cd'
    AND f->'bytes'='46898'::jsonb)<>1
  THEN RETURN false; END IF;
  FOR entry IN SELECT value FROM jsonb_each(public_profiles) LOOP
   IF (SELECT count(*) FROM jsonb_array_elements(manifest->'files') f
    WHERE f->>'path'=entry->>'path' AND f->>'digest'=entry->>'digest'
     AND f->'bytes'=entry->'bytes')<>1
   THEN RETURN false; END IF;
  END LOOP;
 ELSE
 IF (SELECT count(*) FROM jsonb_object_keys(custody))<>6
  OR NOT custody ?& ARRAY['version','receiptId','archiveDigest','manifestHex','schemaHex','profileHex']
  OR custody->'version' IS DISTINCT FROM '1'::jsonb
  OR custody->>'receiptId' IS DISTINCT FROM 'OPENPC-C17-FINAL-DELIVERY-20260827-01'
  OR custody->>'archiveDigest' IS DISTINCT FROM 'sha256:36242402f8ace4b1cff124385b0be45e8e2a2c1fed9ceb980be2644052309ed5'
  OR jsonb_typeof(custody->'manifestHex') IS DISTINCT FROM 'string'
  OR jsonb_typeof(custody->'schemaHex') IS DISTINCT FROM 'string'
  OR jsonb_typeof(custody->'profileHex') IS DISTINCT FROM 'string'
 THEN RETURN false; END IF;
 -- Bound before decoding. The independently pinned archive manifest, not a
 -- self-consistent caller digest pair, supplies exact original membership.
 IF length(custody->>'manifestHex')<>296548
  OR length(custody->>'schemaHex')<>93796
  OR length(custody->>'profileHex')<>(selected->>'bytes')::integer*2
  OR custody->>'manifestHex' !~ '^[0-9a-f]+$'
  OR custody->>'schemaHex' !~ '^[0-9a-f]+$'
  OR custody->>'profileHex' !~ '^[0-9a-f]+$'
 THEN RETURN false; END IF;
 manifest_bytes:=decode(custody->>'manifestHex','hex');
 schema_bytes:=decode(custody->>'schemaHex','hex');
 profile_bytes:=decode(custody->>'profileHex','hex');
 IF 'sha256:'||encode(sha256(manifest_bytes),'hex') IS DISTINCT FROM 'sha256:39800a6f39f3b989f9230844404099d44908c3bfa31d442964c9d947f7885609'
  OR 'sha256:'||encode(sha256(schema_bytes),'hex') IS DISTINCT FROM 'sha256:350280220fae0d2fb0c360cb1c5a9011e8c46218e7b10b9a269fba78078496cd'
  OR 'sha256:'||encode(sha256(profile_bytes),'hex') IS DISTINCT FROM selected->>'digest'
 THEN RETURN false; END IF;
 manifest:=convert_from(manifest_bytes,'UTF8')::jsonb;
 IF manifest->>'packageId' IS DISTINCT FROM 'OPENPC-C17-RECEIVING-AUTHORITY-COHERENCE-20260827-01' THEN RETURN false; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(manifest->'files') f
  WHERE f->>'path'='SPECIFICATIONS/OPERATIONS/configuration.schema.json' AND f->>'class'='NORMATIVE_MACHINE_CONTRACT'
   AND f->>'sha256'='350280220fae0d2fb0c360cb1c5a9011e8c46218e7b10b9a269fba78078496cd' AND f->'bytes'='46898'::jsonb)<>1
 THEN RETURN false; END IF;
 FOR entry IN SELECT value FROM jsonb_each(profiles) LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(manifest->'files') f
   WHERE f->>'path'=entry->>'path' AND f->>'class'='NORMATIVE_MACHINE_CONTRACT'
    AND f->>'sha256'=substring(entry->>'digest' from 8) AND f->'bytes'=entry->'bytes')<>1
  THEN RETURN false; END IF;
 END LOOP;
 END IF;
 -- Pins alone do not authenticate a changed parsed installation. JSON schema
 -- is parsed from the authenticated bytes; YAML uses its independently derived
 -- canonical parsed identity, from the same accepted all-five source mapping.
 IF p_installation->'pins'->>'configurationSchemaDigest' IS DISTINCT FROM 'sha256:350280220fae0d2fb0c360cb1c5a9011e8c46218e7b10b9a269fba78078496cd'
  OR p_installation->'pins'->>'namedProfileDigest' IS DISTINCT FROM selected->>'digest'
  OR p_installation->'schema' IS DISTINCT FROM convert_from(schema_bytes,'UTF8')::jsonb
  OR p_installation->'namedProfile'->>'profile' IS DISTINCT FROM profile_name
  OR 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p_installation->'namedProfile'),'UTF8')),'hex')
     IS DISTINCT FROM selected->>'canonicalDigest'
 THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;


ALTER FUNCTION openpc.operations_source_authentication_valid(p_installation jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_context_scoped_read_current(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_context_scoped_read_current(p_root uuid, p_owner uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
BEGIN
 IF current_user='openpc_control_owner' AND openpc.matches_participant(p_owner) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM control.authority_envelope envelope
  WHERE envelope.platform_context_id=p_root AND openpc.matches_participant(envelope.participant_id));
END $$;


ALTER FUNCTION openpc.platform_context_scoped_read_current(p_root uuid, p_owner uuid) OWNER TO openpc_control_owner;

--
-- Name: platform_history_approval_request_case_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_approval_request_case_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $_$
DECLARE r control.approval_request;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.approval_request,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((openpc.matches_participant(r."participant_id") and openpc.matches_privacy(r."privacy_domain_id")
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=r."privacy_domain_id"
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4')
            or (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
              and jsonb_typeof(source.document->'uneffectedPredecessor')='object'
              and source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
              and source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY'
      and source.document->>'schemaVersion'='4'
      and exists(select 1 from control.platform_recovery_case historical
        where historical.participant_id=source.participant_id
          and historical.privacy_domain_id=source.privacy_domain_id
          and ((not (source.document#>'{source}' ? 'closedApproval')
    and historical.enrollment_id=source.enrollment_id
    and historical.enrollment_revision=source.row_version and historical.enrollment_digest=source.document_digest
    and historical.state='EXPIRED' and historical.valid_until<=clock_timestamp())
   or (source.document#>>'{source,closedApproval,schema}'='pc.identity.closed-platform-approval-source'
    and source.document#>>'{source,closedApproval,schemaVersion}'='1'
    and historical.enrollment_id::text=source.document#>>'{source,closedApproval,enrollmentId}'
    and historical.enrollment_id<>source.enrollment_id
    and 'sha256:'||encode(historical.enrollment_digest,'hex')=source.document#>>'{source,closedApproval,enrollmentDigest}'
    and historical.recovery_id::text=source.document#>>'{source,closedApproval,approval,recoveryId}'
    and 'sha256:'||encode(historical.intent_digest,'hex')=source.document#>>'{source,closedApproval,approval,intentDigest}'
    and historical.state in ('REVOKED','EXPIRED')
    and historical.state=source.document#>>'{source,closedApproval,closure,state}'))
          and historical.intent->'pendingExpiry'=source.document#>'{source,pendingExpiry}'
          and (not (historical.intent ? 'approvalContinuation') or (
    historical.intent#>>'{approvalContinuation,schema}'='pc.identity.platform-prepare-approval-continuation'
    and historical.intent#>>'{approvalContinuation,schemaVersion}'='1'
    and historical.intent#>>'{approvalContinuation,recoveryId}'<>historical.recovery_id::text
    and historical.intent#>>'{approvalContinuation,recoveryId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,approvalId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateDigest}'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')
    and historical.intent#>>'{approvalContinuation,attempt}' ~ '^[1-9][0-9]{0,19}$'
  ))
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and historical.activation_operation_id is not null
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and octet_length(historical.activation_cose)>0
          and (r."subject_type"='CONFIGURATION_CANDIDATE'
            and r."action_intent_id"='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
            and r."maker_principal_id"::text=historical.intent#>>'{preparation,administrators,0,principalId}'
            and r."checker_principal_id"::text=historical.intent#>>'{preparation,administrators,1,principalId}'
            and exists(select 1 from control.mutation_candidate original
              where original.participant_id=historical.participant_id
                and original.privacy_domain_id=historical.privacy_domain_id
                and original.mutation_candidate_id=r."subject_id"
                and original.candidate_document=historical.intent->'preparation'
                and original.candidate_digest=r."subject_digest"
                and original.expected_revision=r."subject_version"
                and exists(select 1 from jsonb_array_elements(historical.lease_bindings) binding
                  where binding->>'envelopeId'=original.maker_authority_envelope_id::text
                    and binding->>'assignmentId'=original.maker_assignment_id::text
                    and binding->>'principalId'=original.maker_principal_id::text
                    and binding->>'principalEpoch'=original.maker_principal_epoch::text))))))),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $_$;


ALTER FUNCTION openpc.platform_history_approval_request_case_read(p_row jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_history_approval_request_pending_effect_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_approval_request_pending_effect_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE r control.approval_request;candidate_resource uuid; pending_document jsonb; binding_found boolean:=false;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.approval_request,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 IF (r.subject_type='CONFIGURATION_CANDIDATE'
  AND openpc.matches_participant(r.participant_id) AND openpc.matches_privacy(r.privacy_domain_id)
  AND openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND current_setting('openpc.local_qa_runtime',true) IS NOT DISTINCT FROM '1') IS NOT TRUE THEN RETURN false; END IF;
 <<candidate_binding>>
 FOR candidate_resource IN SELECT c.resource_id FROM control.mutation_candidate c
  WHERE c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
   AND c.mutation_candidate_id=r.subject_id LOOP
  FOR pending_document IN SELECT pending.candidate FROM control.platform_scope_replacement pending
   WHERE pending.participant_id=r.participant_id AND pending.privacy_domain_id=r.privacy_domain_id
    AND pending.state='WITHDRAWING' AND pending.row_version=1 AND pending.superseded_by IS NULL
    AND num_nonnulls(pending.commit_operation_id,pending.commit_candidate_id,pending.commit_approval_id,pending.readiness_digest,pending.committed_at)=0 LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(pending_document->'administrators')='array'
       THEN pending_document->'administrators' ELSE '[]'::jsonb END) administrator
      WHERE candidate_resource::text=administrator->>'envelopeId') THEN
    binding_found:=true; EXIT candidate_binding;
   END IF;
  END LOOP;
 END LOOP;
 IF NOT binding_found THEN RETURN false; END IF;
 RETURN coalesce((openpc.matches_participant(r."participant_id") and openpc.matches_privacy(r."privacy_domain_id")
      and openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
      and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
      and exists(select 1 from control.platform_scope_replacement pending
        join control.platform_context root on root.platform_context_id=pending.platform_context_id
          and root.owner_participant_id=pending.participant_id and root.state='ACTIVE'
          and ((root.authority_epoch=pending.predecessor_epoch and root.row_version=pending.expected_root_revision)
            or openpc.root_expiry_pending_ancestry(pending.platform_context_id,to_jsonb(pending)) is not null)
        join (select platform_context_id,platform_authority_epoch,scope_cbor,admission_digest from control.platform_envelope_scope
          union all select platform_context_id,platform_authority_epoch,scope_cbor,admission_digest from control.platform_envelope_scope_successor
          union all select platform_context_id,platform_authority_epoch,scope_cbor,admission_digest from control.root_expiry_recovery_scope) scope
          on scope.platform_context_id=root.platform_context_id and scope.platform_authority_epoch=pending.predecessor_epoch
            and scope.admission_digest=pending.predecessor_digest
        where pending.participant_id=r."participant_id" and pending.privacy_domain_id=r."privacy_domain_id"
          and pending.state='WITHDRAWING' and pending.row_version=1 and pending.superseded_by is null
          and num_nonnulls(pending.commit_operation_id,pending.commit_candidate_id,pending.commit_approval_id,pending.readiness_digest,pending.committed_at)=0
          and pending.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(pending.candidate),'UTF8'))
          and pending.successor_digest=sha256(pending.successor_preimage)
          and (openpc.business_cbor(scope.scope_cbor)->>'4')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
          and pending.candidate#>'{successorScope,runtime}'=openpc.platform_scope_document(scope.scope_cbor)->'runtime'
          and jsonb_array_length(pending.candidate->'administrators')=2
          and not exists(select 1 from jsonb_array_elements(pending.candidate->'administrators') administrator
            where (administrator#>>'{usable,validUntilNs}')::numeric>floor(extract(epoch from clock_timestamp())*1000000000)
              or (administrator#>>'{grantable,validUntilNs}')::numeric>floor(extract(epoch from clock_timestamp())*1000000000))
          and r."subject_type"='CONFIGURATION_CANDIDATE'
            and exists(select 1 from control.mutation_candidate partial_candidate
              where partial_candidate.participant_id=pending.participant_id
                and partial_candidate.privacy_domain_id=pending.privacy_domain_id
                and partial_candidate.mutation_candidate_id=r."subject_id"
                and exists(select 1 from jsonb_array_elements(pending.candidate->'administrators') administrator
                  where partial_candidate.resource_id::text=administrator->>'envelopeId')))),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;


ALTER FUNCTION openpc.platform_history_approval_request_pending_effect_read(p_row jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_history_assignment_uneffected_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_assignment_uneffected_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE r control.assignment;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.assignment,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((openpc.matches_participant(r."participant_id") and openpc.matches_privacy(openpc.current_privacy_domain_id())
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=openpc.current_privacy_domain_id()
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4')
            or (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
              and jsonb_typeof(source.document->'uneffectedPredecessor')='object'
              and source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
              and source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
      and exists(select 1 from control.platform_recovery_case historical
        cross join lateral jsonb_array_elements(historical.intent#>'{preparation,administrators}') uneffected_administrator
        where historical.participant_id=source.participant_id and historical.privacy_domain_id=source.privacy_domain_id
          and historical.recovery_id::text=source.document#>>'{uneffectedPredecessor,recoveryId}'
          and historical.enrollment_id::text=source.document#>>'{uneffectedPredecessor,enrollmentId}'
          and historical.state='EXPIRED' and historical.valid_until<=source.valid_from
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and 'sha256:'||encode(historical.intent_digest,'hex')=source.document#>>'{uneffectedPredecessor,intentDigest}'
          and historical.activation_operation_id::text=source.document#>>'{uneffectedPredecessor,activationOperationId}'
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and 'sha256:'||encode(historical.activation_evidence_digest,'hex')=source.document#>>'{uneffectedPredecessor,activationReceiptDigest}'
          and octet_length(historical.activation_cose)>0
          and historical.intent#>>'{preparation,replacementId}'=source.document#>>'{uneffectedPredecessor,replacementId}'
          and 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')=source.document#>>'{uneffectedPredecessor,preparationDigest}'
          and (r."assignment_id"::text=uneffected_administrator->>'assignmentId'))))),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;


ALTER FUNCTION openpc.platform_history_assignment_uneffected_read(p_row jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_history_authority_envelope_uneffected_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_authority_envelope_uneffected_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE r control.authority_envelope;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.authority_envelope,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((openpc.matches_participant(r."participant_id") and openpc.matches_privacy(openpc.current_privacy_domain_id())
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=openpc.current_privacy_domain_id()
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4')
            or (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
              and jsonb_typeof(source.document->'uneffectedPredecessor')='object'
              and source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
              and source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
      and exists(select 1 from control.platform_recovery_case historical
        cross join lateral jsonb_array_elements(historical.intent#>'{preparation,administrators}') uneffected_administrator
        where historical.participant_id=source.participant_id and historical.privacy_domain_id=source.privacy_domain_id
          and historical.recovery_id::text=source.document#>>'{uneffectedPredecessor,recoveryId}'
          and historical.enrollment_id::text=source.document#>>'{uneffectedPredecessor,enrollmentId}'
          and historical.state='EXPIRED' and historical.valid_until<=source.valid_from
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and 'sha256:'||encode(historical.intent_digest,'hex')=source.document#>>'{uneffectedPredecessor,intentDigest}'
          and historical.activation_operation_id::text=source.document#>>'{uneffectedPredecessor,activationOperationId}'
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and 'sha256:'||encode(historical.activation_evidence_digest,'hex')=source.document#>>'{uneffectedPredecessor,activationReceiptDigest}'
          and octet_length(historical.activation_cose)>0
          and historical.intent#>>'{preparation,replacementId}'=source.document#>>'{uneffectedPredecessor,replacementId}'
          and 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')=source.document#>>'{uneffectedPredecessor,preparationDigest}'
          and (r."authority_envelope_id"::text=uneffected_administrator->>'envelopeId'))))),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;


ALTER FUNCTION openpc.platform_history_authority_envelope_uneffected_read(p_row jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_history_idempotency_record_resume_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_idempotency_record_resume_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $_$
DECLARE r control.idempotency_record;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.idempotency_record,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 RETURN coalesce((case when ((r."catalog_operation_id"='LEGACY' and r."action_intent_id"='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1') or (r."catalog_operation_id"='ID-OP-WEBAUTHN-VERIFY' and r."action_intent_id"='ACT-IDENTITY_UPDATE_STEP_UP-V1')) then (openpc.matches_participant(r."participant_id") and openpc.matches_privacy(r."privacy_domain_id")
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=r."privacy_domain_id"
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4')
            or (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
              and jsonb_typeof(source.document->'uneffectedPredecessor')='object'
              and source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
              and source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY'
      and source.document->>'schemaVersion'='4'
      and exists(select 1 from control.platform_recovery_case historical
        where historical.participant_id=source.participant_id
          and historical.privacy_domain_id=source.privacy_domain_id
          and ((not (source.document#>'{source}' ? 'closedApproval')
    and historical.enrollment_id=source.enrollment_id
    and historical.enrollment_revision=source.row_version and historical.enrollment_digest=source.document_digest
    and historical.state='EXPIRED' and historical.valid_until<=clock_timestamp())
   or (source.document#>>'{source,closedApproval,schema}'='pc.identity.closed-platform-approval-source'
    and source.document#>>'{source,closedApproval,schemaVersion}'='1'
    and historical.enrollment_id::text=source.document#>>'{source,closedApproval,enrollmentId}'
    and historical.enrollment_id<>source.enrollment_id
    and 'sha256:'||encode(historical.enrollment_digest,'hex')=source.document#>>'{source,closedApproval,enrollmentDigest}'
    and historical.recovery_id::text=source.document#>>'{source,closedApproval,approval,recoveryId}'
    and 'sha256:'||encode(historical.intent_digest,'hex')=source.document#>>'{source,closedApproval,approval,intentDigest}'
    and historical.state in ('REVOKED','EXPIRED')
    and historical.state=source.document#>>'{source,closedApproval,closure,state}'))
          and historical.intent->'pendingExpiry'=source.document#>'{source,pendingExpiry}'
          and (not (historical.intent ? 'approvalContinuation') or (
    historical.intent#>>'{approvalContinuation,schema}'='pc.identity.platform-prepare-approval-continuation'
    and historical.intent#>>'{approvalContinuation,schemaVersion}'='1'
    and historical.intent#>>'{approvalContinuation,recoveryId}'<>historical.recovery_id::text
    and historical.intent#>>'{approvalContinuation,recoveryId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,approvalId}' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and historical.intent#>>'{approvalContinuation,candidateDigest}'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')
    and historical.intent#>>'{approvalContinuation,attempt}' ~ '^[1-9][0-9]{0,19}$'
  ))
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and historical.activation_operation_id is not null
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and octet_length(historical.activation_cose)>0
          and (exists(select 1 from control.mutation_candidate resume_candidate
      where resume_candidate.participant_id=historical.participant_id
        and resume_candidate.privacy_domain_id=historical.privacy_domain_id
        and resume_candidate.catalog_operation_id='ID-OP-PLATFORM-SCOPE-PREPARE'
        and resume_candidate.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
        and resume_candidate.resource_type='participant' and resume_candidate.operation_class='UPDATE'
        and resume_candidate.expected_revision=0
        and resume_candidate.resource_id::text=historical.intent#>>'{preparation,replacementId}'
        and resume_candidate.candidate_document=historical.intent->'preparation'
        and resume_candidate.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(resume_candidate.candidate_document),'UTF8'))
        and resume_candidate.maker_principal_id::text=historical.intent#>>'{preparation,administrators,0,principalId}'
        and resume_candidate.predecessor_candidate_id::text=historical.intent#>>'{approvalContinuation,candidateId}'
        and resume_candidate.predecessor_approval_id::text=historical.intent#>>'{approvalContinuation,approvalId}'
        and resume_candidate.idempotency_key=historical.intent#>>'{approvalContinuation,businessKey}'
        and resume_candidate.attempt=(historical.intent#>>'{approvalContinuation,attempt}')::numeric+1
        and resume_candidate.state in ('PROPOSED','APPROVAL_REQUESTED','APPROVED')
        and resume_candidate.expires_at<=clock_timestamp() and resume_candidate.consumed_operation_id is null
        and resume_candidate.resume_operation_id is not null
        and resume_candidate.resume_request->>'command'='RESUME'
        and exists(select 1 from jsonb_array_elements(historical.lease_bindings) binding
          where binding->>'envelopeId'=resume_candidate.maker_authority_envelope_id::text
            and binding->>'assignmentId'=resume_candidate.maker_assignment_id::text
            and binding->>'principalId'=resume_candidate.maker_principal_id::text
            and binding->>'principalEpoch'=resume_candidate.maker_principal_epoch::text)
        and (r."terminal_state"='COMMITTED' and r."principal_id"=resume_candidate.maker_principal_id
          and ((r."operation_id"=resume_candidate.resume_operation_id
            and r."catalog_operation_id"='LEGACY'
            and r."action_intent_id"='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          or (exists(select 1 from control.mutation_evidence receiving_verification
            join control.mfa_challenge receiving_challenge on receiving_challenge.participant_id=receiving_verification.participant_id
              and receiving_challenge.mfa_challenge_id=receiving_verification.mfa_challenge_id
            where receiving_verification.participant_id=resume_candidate.participant_id
              and receiving_verification.privacy_domain_id=resume_candidate.privacy_domain_id
              and receiving_verification.operation_id=r."operation_id"
              and ((receiving_challenge.used_at is null and receiving_challenge.used_operation_id is null)
                or (receiving_challenge.used_operation_id=resume_candidate.resume_operation_id and receiving_challenge.used_at is not null))
              and receiving_challenge.resource_id=resume_candidate.predecessor_approval_id::text
              and receiving_challenge.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
              and receiving_challenge.resource_digest=sha256(convert_to(openpc.signing_canonical_json(resume_candidate.resume_request),'UTF8'))
              and receiving_challenge.principal_id=resume_candidate.maker_principal_id
              and receiving_challenge.session_id=resume_candidate.maker_session_id)
            and r."catalog_operation_id"='ID-OP-WEBAUTHN-VERIFY'
            and r."action_intent_id"='ACT-IDENTITY_UPDATE_STEP_UP-V1'))))))))) else false end),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $_$;


ALTER FUNCTION openpc.platform_history_idempotency_record_resume_read(p_row jsonb) OWNER TO openpc_control_owner;

--
-- Name: platform_history_idempotency_record_uneffected_read(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.platform_history_idempotency_record_uneffected_read(p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE r control.idempotency_record;
BEGIN
 IF p_row IS NULL OR jsonb_typeof(p_row)<>'object' THEN RETURN false; END IF;
 r:=jsonb_populate_record(NULL::control.idempotency_record,p_row);
 IF to_jsonb(r) IS DISTINCT FROM p_row THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_enrollment source
  WHERE source.participant_id=r.participant_id AND source.privacy_domain_id=r.privacy_domain_id
   AND source.source_purpose='ROOT_EXPIRY_RECOVERY' AND source.document->>'schemaVersion'='2'
   AND source.document->>'schema'='pc.identity.platform-recovery-enrollment'
   AND jsonb_typeof(source.document->'uneffectedPredecessor')='object'
   AND source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
   AND source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'
   AND source.state='ACTIVE' AND source.row_version=1
   AND source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
   AND source.valid_from<=clock_timestamp() AND source.valid_until>clock_timestamp())
 THEN RETURN false; END IF;
 RETURN coalesce((openpc.matches_participant(r."participant_id") and openpc.matches_privacy(r."privacy_domain_id")
      and exists(select 1 from control.platform_recovery_enrollment source
        where source.participant_id=r."participant_id" and source.privacy_domain_id=r."privacy_domain_id"
          and openpc.platform_recovery_continuation_root_matches(source.platform_context_id,source.participant_id,source.root_epoch,source.root_revision)
          and ((source.source_purpose='ROOT_EXPIRY_RECOVERY_CONTINUATION' and source.document->>'schemaVersion'='3')
            or (source.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='4')
            or (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
              and jsonb_typeof(source.document->'uneffectedPredecessor')='object'
              and source.document#>>'{uneffectedPredecessor,schema}'='pc.identity.platform-expired-uneffected-recovery'
              and source.document#>>'{uneffectedPredecessor,schemaVersion}'='1'))
          and source.document->>'schema'='pc.identity.platform-recovery-enrollment' and source.state='ACTIVE' and source.row_version=1
          and source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'
          and current_setting('openpc.local_qa_runtime',true) is not distinct from '1'
          and source.valid_from<=clock_timestamp() and source.valid_until>clock_timestamp()
          and openpc.current_action_intent_id() in ('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1', 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1', 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1', 'ACT-IDENTITY_CREATE_SESSION-V1', 'ACT-IDENTITY_DELETE_SESSION-V1', 'ACT-IDENTITY_UPDATE_STEP_UP-V1', 'ACT-OPERATIONS_READ_OPERATION-V1', 'ACT-PARTICIPANTS_READ_RESOURCE-V1', 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1', 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1', 'ACT-PARTICIPANT_CREATE_MEMBER-V1', 'ACT-POLICY_APPROVE_REQUEST-V1', 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1', 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1')
          and (source.source_purpose='ROOT_EXPIRY_RECOVERY' and source.document->>'schemaVersion'='2'
      and exists(select 1 from control.platform_recovery_case historical
        cross join lateral jsonb_array_elements(historical.intent#>'{preparation,administrators}') uneffected_administrator
        where historical.participant_id=source.participant_id and historical.privacy_domain_id=source.privacy_domain_id
          and historical.recovery_id::text=source.document#>>'{uneffectedPredecessor,recoveryId}'
          and historical.enrollment_id::text=source.document#>>'{uneffectedPredecessor,enrollmentId}'
          and historical.state='EXPIRED' and historical.valid_until<=source.valid_from
          and historical.intent_digest=sha256(convert_to(openpc.signing_canonical_json(historical.intent),'UTF8'))
          and 'sha256:'||encode(historical.intent_digest,'hex')=source.document#>>'{uneffectedPredecessor,intentDigest}'
          and historical.activation_operation_id::text=source.document#>>'{uneffectedPredecessor,activationOperationId}'
          and historical.activation_evidence_digest=sha256(historical.activation_evidence_cbor)
          and 'sha256:'||encode(historical.activation_evidence_digest,'hex')=source.document#>>'{uneffectedPredecessor,activationReceiptDigest}'
          and octet_length(historical.activation_cose)>0
          and historical.intent#>>'{preparation,replacementId}'=source.document#>>'{uneffectedPredecessor,replacementId}'
          and 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(historical.intent->'preparation'),'UTF8')),'hex')=source.document#>>'{uneffectedPredecessor,preparationDigest}'
          and (exists(select 1 from control.mutation_candidate attempted
          where attempted.participant_id=r."participant_id" and attempted.privacy_domain_id=r."privacy_domain_id"
            and attempted.resource_id::text in (uneffected_administrator->>'envelopeId',uneffected_administrator->>'assignmentId')
            and attempted.catalog_operation_id=r."catalog_operation_id" and attempted.idempotency_key=r."idempotency_key")))))),false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;


ALTER FUNCTION openpc.platform_history_idempotency_record_uneffected_read(p_row jsonb) OWNER TO openpc_control_owner;

