--
-- Name: release_cigl_dependency_claims(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.release_cigl_dependency_claims() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  UPDATE control.cigl_method_grant_dependency_claims SET state='RELEASED',released_operation_id=NEW.publication_operation_id,released_at=clock_timestamp()
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND source_grant_id=NEW.grant_id AND state='ACTIVE' AND source_grant_revision<NEW.revision;
  UPDATE control.cigl_method_grant_dependency_claims SET state='INVALIDATED',released_operation_id=NEW.publication_operation_id,released_at=clock_timestamp()
   WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND required_grant_id=NEW.grant_id AND state='ACTIVE' AND required_grant_revision<NEW.revision;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.release_cigl_dependency_claims() OWNER TO openpc_control_owner;

--
-- Name: remote_archive_covers(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.remote_archive_covers(pid uuid, privacy uuid, stream text, segment uuid, sink text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.evidence_remote_archive_intent i
  JOIN control.evidence_remote_archive_attempt a USING(participant_id,privacy_domain_id,intent_id)
  JOIN control.evidence_archive_receipt r USING(participant_id,privacy_domain_id,attempt_id)
  JOIN control.evidence_archive_outbox o USING(participant_id,privacy_domain_id,receipt_id)
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.stream_id=stream AND i.segment_id=segment AND i.sink_id=sink
   AND a.state='OBSERVED' AND a.binding->'protection'->'rules'=openpc.remote_archive_rules(pid,privacy,stream,segment)
   AND NOT EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer
    WHERE newer.participant_id=i.participant_id AND newer.privacy_domain_id=i.privacy_domain_id
     AND newer.intent_id=i.intent_id AND (newer.binding->'protection'->>'revision')::numeric>(a.binding->'protection'->>'revision')::numeric))
$$;


ALTER FUNCTION openpc.remote_archive_covers(pid uuid, privacy uuid, stream text, segment uuid, sink text) OWNER TO openpc_control_owner;

--
-- Name: evidence_segment; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.evidence_segment (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    stream_id text NOT NULL,
    segment_id uuid NOT NULL,
    first_sequence numeric(20,0) NOT NULL,
    through_sequence numeric(20,0) NOT NULL,
    previous_segment_digest text,
    object_digest text NOT NULL,
    key_id text NOT NULL,
    retention_until timestamp(6) with time zone NOT NULL,
    admitted_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT evidence_segment_digest_ck CHECK ((object_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT evidence_segment_range_ck CHECK (((first_sequence > (0)::numeric) AND ((through_sequence >= first_sequence) AND (through_sequence <= '18446744073709551615'::numeric)) AND ((through_sequence - first_sequence) < (128)::numeric)))
);

ALTER TABLE ONLY control.evidence_segment FORCE ROW LEVEL SECURITY;


ALTER TABLE control.evidence_segment OWNER TO openpc_control_owner;

