-- Name: remote_archive_rules(control.evidence_segment); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.remote_archive_rules(s control.evidence_segment) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT openpc.remote_archive_rules((s).participant_id,(s).privacy_domain_id,(s).stream_id,(s).segment_id)
$$;


ALTER FUNCTION openpc.remote_archive_rules(s control.evidence_segment) OWNER TO openpc_control_owner;

--
-- Name: remote_archive_rules(uuid, uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.remote_archive_rules(pid uuid, privacy uuid, stream text, segment uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('holdId',h.retention_hold_id::text,
  'selectorDigest',h.selector_digest,'creationOperationId',h.creation_operation_id::text,
  'releaseOperationId',h.release_operation_id::text,'state',h.state,'revision',h.revision::text)
  ORDER BY h.retention_hold_id),'[]'::jsonb)
 FROM control.retention_hold h WHERE h.participant_id=pid
  AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=privacy)
  AND openpc.evidence_hold_requires_coverage(h,stream,segment)
$$;


ALTER FUNCTION openpc.remote_archive_rules(pid uuid, privacy uuid, stream text, segment uuid) OWNER TO openpc_control_owner;

