CREATE FUNCTION openpc.require_archive_commit_nonce(receipt control.evidence_archive_receipt) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_commit_nonce n WHERE n.participant_id=receipt.participant_id
   AND n.privacy_domain_id=receipt.privacy_domain_id AND n.receipt_id=receipt.receipt_id
   AND n.receipt_digest=receipt.receipt_digest AND n.nonce=receipt.commit_nonce)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $$;


ALTER FUNCTION openpc.require_archive_commit_nonce(receipt control.evidence_archive_receipt) OWNER TO openpc_control_owner;

--
-- Name: require_archive_profile(text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_archive_profile(wanted text, stream text) RETURNS control.evidence_archive_profile
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p control.evidence_archive_profile; t control.evidence_archive_trust; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT p FROM control.evidence_archive_profile WHERE profile_digest=wanted
  AND participant_id=current_setting('openpc.participant_id')::uuid
  AND privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid;
 SELECT * INTO STRICT t FROM control.evidence_archive_trust WHERE participant_id=p.participant_id
  AND privacy_domain_id=p.privacy_domain_id AND environment_id=p.environment_id AND sink_id=p.sink_id;
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 IF current_user<>t.database_role OR session_user<>t.database_role
  OR NOT (p.claims->'streamIds' ? stream) OR now_ms<(p.claims->>'validFromMs')::numeric
  OR now_ms>=(p.claims->>'validUntilMs')::numeric OR now_ms<t.valid_from_ms OR now_ms>=t.valid_until_ms
  OR EXISTS(SELECT 1 FROM control.evidence_archive_profile newer WHERE newer.participant_id=p.participant_id
   AND newer.privacy_domain_id=p.privacy_domain_id AND newer.environment_id=p.environment_id
   AND newer.sink_id=p.sink_id AND newer.revision>p.revision)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.lock_archive_workload(p.profile_digest);
 RETURN p;
END $$;


ALTER FUNCTION openpc.require_archive_profile(wanted text, stream text) OWNER TO openpc_control_owner;

--
-- Name: require_bootstrap_custody_change(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_bootstrap_custody_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE original_mode text:=current_setting('openpc.context_mode');
 original_participant uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 original_privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 operation uuid:=current_setting('openpc.operation_id')::uuid;
 action text:=current_setting('openpc.action_intent_id');
 candidate_document jsonb; changed boolean:=NEW.custody_generation<>OLD.custody_generation;
BEGIN
 IF NOT changed AND NEW.state<>'CANCELLED' THEN RETURN NULL; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.platform_participant_id,(NEW.issuance_authority->>'privacyDomainId')::uuid,operation,action,true);
 SELECT candidate.candidate_document INTO candidate_document
 FROM control.mutation_candidate candidate
 JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id AND evidence.operation_id=candidate.consumed_operation_id
   AND evidence.candidate_digest=candidate.candidate_digest AND evidence.principal_id=NEW.maker_principal_id AND evidence.checker_principal_id=NEW.checker_principal_id
 JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id AND receipt.operation_id=candidate.consumed_operation_id
   AND receipt.terminal_state='COMMITTED' AND receipt.result_payload->>'operationId'=operation::text
   AND receipt.result_payload#>>'{result,mandateId}'=NEW.mandate_id::text
   AND receipt.result_payload#>>'{result,custodyGeneration}'=NEW.custody_generation::text
 WHERE candidate.participant_id=NEW.platform_participant_id AND candidate.resource_id=NEW.participant_id
   AND candidate.consumed_operation_id=operation AND candidate.state='CONSUMED'
   AND candidate.catalog_operation_id=CASE WHEN changed THEN 'ID-OP-PARTICIPANT-FIRST-ADMIN-ROTATE' ELSE 'ID-OP-PARTICIPANT-FIRST-ADMIN-REVOKE' END
   AND candidate.candidate_document->>'participantId'=NEW.participant_id::text
   AND candidate.candidate_document->>'mandateId'=NEW.mandate_id::text
   AND candidate.candidate_document->>'invitationId'=NEW.invitation_id::text
   AND candidate.candidate_document->>'custodyGeneration'=OLD.custody_generation::text
   AND candidate.candidate_document->>'tokenVersion'=OLD.custody_generation::text
   AND candidate.candidate_document->>'expectedRevision'=evidence.aggregate_version::text
   AND candidate.candidate_document#>>'{change,mutation}'=CASE WHEN changed THEN 'ROTATE' ELSE 'REVOKE' END;
 IF candidate_document IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0002-BOOTSTRAP-CHANGE-PROVENANCE'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,(NEW.candidate->>'privacyDomainId')::uuid,operation,action,true);
 IF NOT EXISTS(SELECT 1 FROM control.participant_invitation invitation JOIN control.participant_invitation_token token
   ON token.participant_id=invitation.participant_id AND token.invitation_id=invitation.invitation_id AND token.token_version=invitation.token_version
   WHERE invitation.participant_id=NEW.participant_id AND invitation.invitation_id=NEW.invitation_id
     AND invitation.expires_at=NEW.expires_at AND invitation.last_mutation_operation_id=operation
     AND invitation.token_version=NEW.custody_generation
     AND ((changed AND invitation.state='PENDING' AND token.operation_id=operation
       AND 'sha256:'||encode(token.token_digest,'hex')=candidate_document#>>'{change,tokenDigest}')
       OR (NOT changed AND invitation.state='REVOKED')))
   OR (OLD.candidate_session_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM control.session WHERE participant_id=NEW.participant_id
      AND session_id=OLD.candidate_session_id AND state='REVOKED'
      AND revoked_reason=CASE WHEN changed THEN 'first-administrator-custody-rotated' ELSE 'first-administrator-custody-revoked' END))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-BOOTSTRAP-CHANGE-EFFECT'; END IF;
 PERFORM openpc.set_request_context(original_mode,original_participant,original_privacy,operation,action,original_privacy IS NOT NULL);
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_bootstrap_custody_change() OWNER TO openpc_control_owner;

--
-- Name: require_bootstrap_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_bootstrap_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE original_mode text:=current_setting('openpc.context_mode');
 original_participant uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 original_privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 original_operation uuid:=current_setting('openpc.operation_id')::uuid;
 original_action text:=current_setting('openpc.action_intent_id');
 valid_source boolean; valid_target boolean;
BEGIN
 IF NEW.candidate_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.candidate),'UTF8'))
   OR NEW.configuration_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.candidate->'configuration'),'UTF8'))
   OR NEW.first_admin_invite_ttl_ms<>(NEW.candidate#>>'{configuration,participant.first_admin_invite_ttl}')::integer
   OR NEW.platform_participant_id::text IS DISTINCT FROM NEW.issuance_authority->>'participantId'
   OR NEW.maker_principal_id::text IS DISTINCT FROM NEW.issuance_authority#>>'{signers,0,principalId}'
   OR NEW.checker_principal_id::text IS DISTINCT FROM NEW.issuance_authority#>>'{signers,1,principalId}'
   OR NEW.created_operation_id::text IS DISTINCT FROM NEW.issuance_authority->>'operationId'
   OR NEW.mandate_id::text IS DISTINCT FROM NEW.candidate->>'mandateId'
   OR NEW.invitation_id::text IS DISTINCT FROM NEW.candidate->>'invitationId' THEN RAISE EXCEPTION 'PC-AUTH-0002-BOOTSTRAP-PROVENANCE'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.platform_participant_id,(NEW.issuance_authority->>'privacyDomainId')::uuid,original_operation,original_action,true);
 SELECT EXISTS(
  SELECT 1 FROM control.mutation_candidate candidate
  JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id AND evidence.privacy_domain_id=candidate.privacy_domain_id
    AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
    AND evidence.principal_id=NEW.maker_principal_id AND evidence.checker_principal_id=NEW.checker_principal_id
    AND evidence.approval_request_id=(NEW.issuance_authority->>'approvalRequestId')::uuid
  JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id AND receipt.operation_id=candidate.consumed_operation_id
    AND receipt.terminal_state='COMMITTED' AND receipt.result_payload#>>'{result,bootstrap,issuanceAuthorityDigest}'=
      'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.issuance_authority),'UTF8')),'hex')
  WHERE candidate.participant_id=NEW.platform_participant_id AND candidate.resource_id=NEW.participant_id
    AND candidate.candidate_document->>'participantId'=NEW.participant_id::text
    AND candidate.candidate_document->'firstAdministrator'=NEW.candidate
    AND candidate.candidate_digest=decode(substr(NEW.issuance_authority->>'candidateDigest',8),'hex')
    AND candidate.consumed_operation_id=NEW.created_operation_id AND candidate.state='CONSUMED'
    AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-CREATE'
 ) INTO valid_source;
 IF NOT coalesce(valid_source,false) THEN
  PERFORM openpc.set_request_context(original_mode,original_participant,original_privacy,original_operation,original_action,original_privacy IS NOT NULL);
  RAISE EXCEPTION 'PC-AUTH-0002-BOOTSTRAP-SOURCE-PROVENANCE';
 END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,(NEW.candidate->>'privacyDomainId')::uuid,original_operation,original_action,true);
 SELECT EXISTS(
  SELECT 1 FROM control.participant_invitation invitation JOIN control.authority_role role
    ON role.participant_id=invitation.participant_id AND role.authority_role_id=invitation.intended_role_id
      AND role.authority_role_id=(NEW.candidate->>'roleId')::uuid AND role.bootstrap_mandate_id=NEW.mandate_id
      AND role.bootstrap_platform_participant_id=NEW.platform_participant_id
      AND to_jsonb(role.action_intent_ids)=NEW.candidate->'actionIntentIds'
  WHERE invitation.participant_id=NEW.participant_id AND invitation.invitation_id=NEW.invitation_id
    AND invitation.bootstrap_mandate_id=NEW.mandate_id AND invitation.bootstrap_platform_participant_id=NEW.platform_participant_id
    AND invitation.privacy_domain_id=(NEW.candidate->>'privacyDomainId')::uuid
    AND invitation.recipient_issuer=NEW.candidate->>'recipientIssuer'
    AND invitation.recipient_subject=NEW.candidate->>'recipientSubject'
    AND invitation.recipient_audience=NEW.candidate->>'recipientAudience'
 ) INTO valid_target;
 PERFORM openpc.set_request_context(original_mode,original_participant,original_privacy,original_operation,original_action,original_privacy IS NOT NULL);
 IF NOT coalesce(valid_source AND valid_target,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-BOOTSTRAP-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_bootstrap_provenance() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_activation_selection(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_activation_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.cigl_profile_selection IS NULL THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.configuration_work work
  JOIN control.mutation_evidence evidence ON evidence.operation_id=work.operation_id
   AND evidence.participant_id=work.participant_id AND evidence.privacy_domain_id=work.privacy_domain_id
  JOIN control.mutation_candidate candidate ON candidate.consumed_operation_id=evidence.operation_id
   AND candidate.participant_id=evidence.participant_id AND candidate.privacy_domain_id=evidence.privacy_domain_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  JOIN control.runtime_target target ON target.runtime_target_id=NEW.runtime_target_id
   AND target.participant_id=NEW.participant_id AND target.privacy_domain_id=NEW.privacy_domain_id
  WHERE work.runtime_configuration_generation_id=NEW.runtime_configuration_generation_id
   AND work.participant_id=NEW.participant_id AND work.privacy_domain_id=NEW.privacy_domain_id
   AND work.work_kind='RUNTIME_ACTIVATION' AND work.runtime_target_id=NEW.runtime_target_id AND work.resource_id=NEW.runtime_target_id
   AND work.generation_digest=NEW.generation_digest AND work.predecessor_digest=NEW.predecessor_digest
   AND work.policy_generation_digest=NEW.policy_generation_digest AND work.input_digest='sha256:'||encode(candidate.candidate_digest,'hex')
   AND evidence.catalog_operation_id='CFG-OP-ACTIVATE-CIGL-PROFILES' AND evidence.action_intent_id='ACT-CIGL_PROFILES_ACTIVATE_RESOURCE-V1'
   AND evidence.aggregate_type='runtime-targets' AND evidence.aggregate_id=NEW.runtime_target_id
   AND evidence.aggregate_version=candidate.expected_revision+1 AND candidate.resource_id=NEW.runtime_target_id AND candidate.state='CONSUMED'
   AND candidate.candidate_document->>'targetRef'='urn:openpc:resource:'||NEW.runtime_target_id::text
   AND candidate.candidate_document->>'expectedGenerationDigest'=NEW.predecessor_digest
   AND (jsonb_build_object('participantEpoch',candidate.candidate_document->'participantEpoch','profiles',candidate.candidate_document->'profiles') || CASE WHEN candidate.candidate_document ? 'policyRenewal' THEN jsonb_build_object('policyRenewal',candidate.candidate_document->'policyRenewal') ELSE '{}'::jsonb END)=NEW.cigl_profile_selection
   AND NEW.generation_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
      'purpose','openpc.runtime.cigl-profile-selection.v1','baseCapsuleDigest',candidate.candidate_document->>'expectedGenerationDigest',
      'selection',NEW.cigl_profile_selection)),'UTF8')),'hex')
   AND (TG_OP<>'INSERT' OR (target.state='STAGING' AND target.revision=candidate.expected_revision+1 AND target.desired_generation_digest=NEW.generation_digest))
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id AND event.privacy_domain_id=NEW.privacy_domain_id
    AND event.aggregate_id=NEW.runtime_target_id AND event.aggregate_type='runtime-targets'
    AND event.event_type='openpc.cigl.profile.activation-requested.v1'
    AND event.payload_digest=sha256(event.payload_cbor)
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(candidate.candidate_digest,'hex')
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'revision'=evidence.aggregate_version::text
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(evidence.evidence_digest,'hex'))) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ACTIVATION-PROVENANCE'; END IF;
 IF NEW.cigl_profile_selection ? 'policyRenewal' AND NOT EXISTS(
  SELECT 1 FROM control.policy_activation_occurrence occurrence
  JOIN control.policy_activation_occurrence_target cohort ON cohort.activation_occurrence_id=occurrence.activation_occurrence_id
   AND cohort.participant_id=occurrence.participant_id AND cohort.privacy_domain_id=occurrence.privacy_domain_id
  JOIN control.configuration_work work ON work.configuration_work_id=cohort.configuration_work_id
   AND work.participant_id=cohort.participant_id AND work.privacy_domain_id=cohort.privacy_domain_id
  WHERE occurrence.participant_id=NEW.participant_id AND occurrence.privacy_domain_id=NEW.privacy_domain_id
   AND 'urn:openpc:resource:'||occurrence.activation_occurrence_id::text=NEW.cigl_profile_selection->'policyRenewal'->>'activationOccurrenceRef'
   AND cohort.runtime_target_id=NEW.runtime_target_id AND cohort.phase='FORWARD'
   AND cohort.runtime_configuration_generation_id=NEW.runtime_configuration_generation_id
   AND work.runtime_configuration_generation_id=NEW.runtime_configuration_generation_id
   AND work.policy_generation_digest=NEW.policy_generation_digest
   AND occurrence.target_generation_digest=decode(substring(NEW.policy_generation_digest from 8),'hex')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-RENEWAL-PROVENANCE'; END IF;
 IF NEW.state='ACTIVE' AND NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation observation
  JOIN control.configuration_work work ON work.configuration_work_id=observation.configuration_work_id
  JOIN control.runtime_target target ON target.runtime_target_id=NEW.runtime_target_id
  WHERE observation.runtime_configuration_generation_id=NEW.runtime_configuration_generation_id
   AND observation.generation_digest=NEW.generation_digest AND observation.capsule_digest=target.active_generation_digest
   AND target.active_generation_digest=target.desired_generation_digest AND target.state='ACTIVE_MATCHED' AND work.state='COMPLETED') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ACTIVATION-EFFECT'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_activation_selection() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_analysis_publication(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_analysis_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE operation text:=CASE NEW.revision WHEN 1 THEN 'CFG-OP-CREATE-CIGL-ANALYSIS' WHEN 2 THEN 'CFG-OP-UPDATE-CIGL-ANALYSIS' ELSE 'CFG-OP-REVIEW-CIGL-ANALYSIS' END;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id AND receipt.privacy_domain_id=evidence.privacy_domain_id
   AND receipt.operation_id=evidence.operation_id AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id AND candidate.privacy_domain_id=evidence.privacy_domain_id
   AND candidate.consumed_operation_id=evidence.operation_id AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id AND evidence.operation_id=NEW.publication_operation_id
   AND evidence.aggregate_type='cigl-analysis' AND evidence.aggregate_id=NEW.analysis_id AND evidence.catalog_operation_id=operation
   AND evidence.action_intent_id=CASE NEW.revision WHEN 1 THEN 'ACT-CIGL_ANALYSES_CREATE_RESOURCE-V1' WHEN 2 THEN 'ACT-CIGL_ANALYSES_UPDATE_RESOURCE-V1' ELSE 'ACT-CIGL_ANALYSES_REVIEW_RESOURCE-V1' END
   AND NEW.publication_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.analysis_id AND candidate.state='CONSUMED' AND candidate.expected_revision=NEW.revision-1
   AND ((NEW.revision=1 AND candidate.candidate_document->'definition'=NEW.definition)
    OR (NEW.revision=2 AND candidate.candidate_document->>'targetRef'='urn:openpc:resource:'||NEW.analysis_id::text
      AND candidate.candidate_document->>'expectedRevision'='1'
      AND candidate.candidate_document->>'signedReceipt'='0x'||encode(NEW.signed_receipt,'hex'))
    OR (NEW.revision=3 AND candidate.candidate_document->>'targetRef'='urn:openpc:resource:'||NEW.analysis_id::text
      AND candidate.candidate_document->>'expectedRevision'='2' AND candidate.candidate_document->'review'=NEW.review_definition))
   AND receipt.terminal_state='COMMITTED' AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.analysis_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id AND event.privacy_domain_id=NEW.privacy_domain_id
    AND event.aggregate_id=NEW.analysis_id AND event.aggregate_type='cigl-analysis' AND event.aggregate_sequence=NEW.revision
    AND event.event_type=CASE NEW.revision WHEN 1 THEN 'openpc.cigl.analysis.created.v1' WHEN 2 THEN 'openpc.cigl.analysis.observed.v1' ELSE 'openpc.cigl.analysis.reviewed.v1' END)) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-ANALYSIS-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_analysis_publication() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_dependency_bundle(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_dependency_bundle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE document jsonb; bundle jsonb; item jsonb; selected control.cigl_method_grant_dependency_claims;
BEGIN
 IF NEW.origin<>'SHARED' OR NEW.revision=1 THEN RETURN NULL; END IF;
 SELECT candidate.candidate_document INTO STRICT document FROM control.mutation_candidate candidate
  WHERE candidate.participant_id=NEW.participant_id AND candidate.privacy_domain_id=NEW.privacy_domain_id
   AND candidate.resource_id=NEW.grant_id AND candidate.consumed_operation_id=NEW.publication_operation_id
   AND candidate.catalog_operation_id='CFG-OP-UPDATE-CIGL-GRANT' AND candidate.state='CONSUMED';
 bundle:=document->'dependencyBundle';
 IF bundle IS NULL THEN
  IF EXISTS(SELECT 1 FROM control.cigl_grant_history WHERE grant_id=NEW.grant_id AND revision=NEW.revision-1 AND status=NEW.status) THEN
   RAISE EXCEPTION 'PC-DATA-6007-CIGL-GRANT-NO-CHANGE'; END IF;
  IF EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims WHERE source_grant_id=NEW.grant_id AND publication_operation_id=NEW.publication_operation_id) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-UNREVIEWED'; END IF;
  RETURN NULL;
 END IF;
 IF NEW.status<>'ACTIVE' OR jsonb_typeof(bundle->'dependencies') IS DISTINCT FROM 'array'
  OR (SELECT count(DISTINCT value->>'actionDigest') FROM jsonb_array_elements(bundle->'dependencies'))<>jsonb_array_length(bundle->'dependencies')
  OR (SELECT count(*) FROM control.cigl_method_grant_dependency_claims WHERE source_grant_id=NEW.grant_id AND source_grant_revision=NEW.revision AND publication_operation_id=NEW.publication_operation_id)
    <>jsonb_array_length(bundle->'dependencies')
  OR jsonb_array_length(bundle->'dependencies')<>(SELECT count(*) FROM control.cigl_profile_dependency_path path
    JOIN control.cigl_profile_version version ON version.profile_id=path.profile_id AND version.revision=path.profile_revision
    WHERE version.profile_id::text=substring(bundle->>'profileId' from 21) AND version.revision::text=bundle->>'profileRevision'
     AND version.participant_id=NEW.participant_id AND version.privacy_domain_id=NEW.privacy_domain_id AND version.profile_digest=bundle->>'profileDigest') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-COMPLETENESS'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(bundle->'dependencies') LOOP
  SELECT claim.* INTO selected FROM control.cigl_method_grant_dependency_claims claim
   JOIN control.cigl_profile_dependency_path path_row ON path_row.profile_id=claim.profile_id AND path_row.profile_revision=claim.profile_revision AND path_row.ordinal=claim.ordinal
   WHERE claim.source_grant_id=NEW.grant_id AND claim.source_grant_revision=NEW.revision AND claim.publication_operation_id=NEW.publication_operation_id
    AND 'sha256:'||(path_row.document->>'actionDigest')=item->>'actionDigest';
  IF NOT FOUND OR selected.state<>'ACTIVE' OR selected.capability IS DISTINCT FROM bundle->>'capability'
   OR selected.graph_digest IS DISTINCT FROM bundle->>'graphDigest' OR selected.policy_generation_digest IS DISTINCT FROM bundle->>'policyGenerationDigest'
   OR selected.participant_epoch::text IS DISTINCT FROM bundle->>'participantEpoch'
   OR selected.profile_id::text IS DISTINCT FROM substring(bundle->>'profileId' from 21) OR selected.profile_revision::text IS DISTINCT FROM bundle->>'profileRevision'
   OR NOT EXISTS(SELECT 1 FROM control.cigl_method_access_grants required WHERE required.grant_id=selected.required_grant_id
    AND ((item->'grant'->>'kind'='SHARED' AND 'urn:openpc:resource:'||required.grant_id::text=item->'grant'->>'grantId'
      AND selected.required_grant_revision::text=item->'grant'->>'expectedRevision')
     OR (item->'grant'='{"kind":"GENERATE"}'::jsonb AND required.origin='GENERATED' AND required.generated_by_grant_id=NEW.grant_id
      AND required.publication_operation_id=NEW.publication_operation_id AND required.revision=1))) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-EXACT-BUNDLE'; END IF;
 END LOOP;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_dependency_bundle() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_dependency_claim(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_dependency_claim() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM control.mutation_candidate candidate
  JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id AND evidence.privacy_domain_id=candidate.privacy_domain_id
   AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
   AND evidence.catalog_operation_id=candidate.catalog_operation_id AND evidence.aggregate_id=candidate.resource_id
  JOIN control.cigl_profile_dependency_path path ON path.profile_id=NEW.profile_id AND path.profile_revision=NEW.profile_revision AND path.ordinal=NEW.ordinal
  JOIN control.cigl_profile_version version ON version.profile_id=path.profile_id AND version.revision=path.profile_revision
  WHERE candidate.participant_id=NEW.participant_id AND candidate.privacy_domain_id=NEW.privacy_domain_id
   AND candidate.resource_id=NEW.source_grant_id AND candidate.state='CONSUMED' AND candidate.catalog_operation_id='CFG-OP-UPDATE-CIGL-GRANT'
   AND candidate.consumed_operation_id=NEW.publication_operation_id AND evidence.aggregate_version=NEW.source_grant_revision
   AND candidate.candidate_document->'dependencyBundle'->>'profileId'='urn:openpc:resource:'||NEW.profile_id::text
   AND candidate.candidate_document->'dependencyBundle'->>'profileRevision'=NEW.profile_revision::text
   AND candidate.candidate_document->'dependencyBundle'->>'profileDigest'=version.profile_digest
   AND candidate.candidate_document->'dependencyBundle'->>'capability'=NEW.capability
   AND candidate.candidate_document->'dependencyBundle'->>'graphDigest'=NEW.graph_digest
   AND candidate.candidate_document->'dependencyBundle'->>'policyGenerationDigest'=NEW.policy_generation_digest
   AND candidate.candidate_document->'dependencyBundle'->>'participantEpoch'=NEW.participant_epoch::text
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(candidate.candidate_document->'dependencyBundle'->'dependencies') item
     WHERE item->>'actionDigest'='sha256:'||(path.document->>'actionDigest')
      AND ((item->'grant'->>'kind'='SHARED' AND item->'grant'->>'grantId'='urn:openpc:resource:'||NEW.required_grant_id::text AND item->'grant'->>'expectedRevision'=NEW.required_grant_revision::text)
       OR (item->'grant'='{"kind":"GENERATE"}'::jsonb AND EXISTS(SELECT 1 FROM control.cigl_method_access_grants required
        WHERE required.grant_id=NEW.required_grant_id AND required.origin='GENERATED' AND required.generated_by_grant_id=NEW.source_grant_id AND required.publication_operation_id=NEW.publication_operation_id))))) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-DEPENDENCY-PROVENANCE'; END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM control.cigl_method_access_grants required WHERE required.grant_id=NEW.required_grant_id
   AND required.origin='GENERATED' AND required.status='ACTIVE'
   AND NOT EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims claim WHERE claim.required_grant_id=required.grant_id AND claim.state='ACTIVE')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GENERATED-ORPHAN'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_dependency_claim() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_grant_publication(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_grant_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE operation text:=CASE WHEN NEW.revision=1 THEN 'CFG-OP-CREATE-CIGL-GRANT' ELSE 'CFG-OP-UPDATE-CIGL-GRANT' END;
BEGIN
 IF NEW.origin='GENERATED' THEN RETURN NULL; END IF; -- Exact derived ownership is checked by require_generated_cigl_grant.
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id AND receipt.privacy_domain_id=evidence.privacy_domain_id
   AND receipt.operation_id=evidence.operation_id AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id AND candidate.privacy_domain_id=evidence.privacy_domain_id
   AND candidate.consumed_operation_id=evidence.operation_id AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id AND evidence.operation_id=NEW.publication_operation_id
   AND evidence.aggregate_type='cigl-grant' AND evidence.aggregate_id=NEW.grant_id AND evidence.catalog_operation_id=operation
   AND evidence.aggregate_version=NEW.revision
   AND evidence.action_intent_id=CASE WHEN NEW.revision=1 THEN 'ACT-CIGL_GRANTS_CREATE_RESOURCE-V1' ELSE 'ACT-CIGL_GRANTS_UPDATE_RESOURCE-V1' END
   AND NEW.publication_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.grant_id AND candidate.state='CONSUMED' AND candidate.expected_revision=NEW.revision-1
   AND candidate.action_intent_id=evidence.action_intent_id AND receipt.action_intent_id=evidence.action_intent_id
   AND receipt.expected_aggregate_version=candidate.expected_revision
   AND ((NEW.revision=1 AND candidate.candidate_document->'definition'=NEW.definition
     AND candidate.candidate_document->>'expectedRuntimeBindingRevision'=NEW.binding_revision::text
     AND candidate.candidate_document->>'expectedMethodRevision'=NEW.method_revision::text)
    OR (NEW.revision>1 AND candidate.candidate_document->>'status'=NEW.status
      AND candidate.candidate_document->>'targetRef'='urn:openpc:resource:'||NEW.grant_id::text))
   AND receipt.terminal_state='COMMITTED' AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.grant_id::text
   AND receipt.result_payload->>'revision'=NEW.revision::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id AND event.privacy_domain_id=NEW.privacy_domain_id
     AND event.aggregate_id=NEW.grant_id AND event.aggregate_type='cigl-grant' AND event.aggregate_sequence=NEW.revision
     AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'=NEW.publication_authority_digest
     AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(candidate.candidate_digest,'hex')
     AND event.event_type=CASE WHEN NEW.revision=1 THEN 'openpc.cigl.grant.created.v1' ELSE 'openpc.cigl.grant.status.v1' END)) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GRANT-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_grant_publication() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_profile_owner(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_profile_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.cigl_profile_version version WHERE version.profile_id=NEW.profile_id
  AND version.participant_id=NEW.participant_id AND version.privacy_domain_id=NEW.privacy_domain_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-OWNER-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_profile_owner() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_profile_result(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_profile_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE version_number bigint;
BEGIN
 IF TG_TABLE_NAME='cigl_profile_version' THEN version_number:=NEW.revision;
 ELSE version_number:=NEW.profile_revision; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.cigl_profile_version version JOIN control.configuration_work work
   ON work.configuration_work_id=version.configuration_work_id AND work.participant_id=version.participant_id AND work.privacy_domain_id=version.privacy_domain_id
   WHERE version.profile_id=NEW.profile_id AND version.revision=version_number AND version.participant_id=NEW.participant_id
    AND version.privacy_domain_id=NEW.privacy_domain_id AND version.state='COMPILED' AND work.state='COMPLETED') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-ATOMIC-RESULT'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_profile_result() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_profile_work(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_profile_work() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.work_kind<>'CIGL_PROFILE_COMPILATION' THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.cigl_analysis analysis JOIN control.cigl_profile_version version
   ON version.analysis_id=analysis.analysis_id AND version.participant_id=analysis.participant_id AND version.privacy_domain_id=analysis.privacy_domain_id
   JOIN control.mutation_evidence evidence ON evidence.operation_id=analysis.publication_operation_id
    AND evidence.participant_id=analysis.participant_id AND evidence.privacy_domain_id=analysis.privacy_domain_id
   JOIN control.mutation_candidate candidate ON candidate.consumed_operation_id=evidence.operation_id
    AND candidate.participant_id=evidence.participant_id AND candidate.privacy_domain_id=evidence.privacy_domain_id
    AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
   WHERE analysis.analysis_id=NEW.resource_id AND analysis.participant_id=NEW.participant_id AND analysis.privacy_domain_id=NEW.privacy_domain_id
    AND analysis.state='REVIEWED' AND analysis.revision=3 AND analysis.publication_operation_id=NEW.operation_id
    AND evidence.catalog_operation_id='CFG-OP-REVIEW-CIGL-ANALYSIS' AND candidate.resource_id=analysis.analysis_id
    AND candidate.state='CONSUMED' AND candidate.expected_revision=2 AND candidate.candidate_document->'review'=analysis.review_definition
    AND NEW.input_digest='sha256:'||encode(candidate.candidate_digest,'hex') AND version.configuration_work_id=NEW.configuration_work_id
    AND version.review_digest=analysis.review_digest AND NEW.runtime_target_id=analysis.runtime_target_id
    AND NEW.generation_digest=analysis.definition->>'expectedGenerationDigest' AND NEW.policy_generation_digest=analysis.policy_generation_digest
    AND EXISTS(SELECT 1 FROM control.runtime_activation_observation observation JOIN control.configuration_work prior
      ON prior.configuration_work_id=observation.configuration_work_id WHERE observation.participant_id=analysis.participant_id
      AND observation.privacy_domain_id=analysis.privacy_domain_id AND observation.runtime_target_id=analysis.runtime_target_id
      AND observation.capsule_digest=analysis.capsule_digest AND observation.capsule_digest=NEW.generation_digest
      AND prior.participant_id=observation.participant_id AND prior.privacy_domain_id=observation.privacy_domain_id
      AND prior.work_kind='RUNTIME_ACTIVATION' AND prior.runtime_target_id=observation.runtime_target_id
      AND prior.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
      AND prior.generation_digest=observation.generation_digest
      AND prior.configuration_digest=NEW.configuration_digest)) THEN RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-PROVENANCE'; END IF;
 IF NEW.state='COMPLETED' AND NOT EXISTS(SELECT 1 FROM control.cigl_analysis analysis JOIN control.runtime_target target
   ON target.runtime_target_id=analysis.runtime_target_id AND target.participant_id=analysis.participant_id AND target.privacy_domain_id=analysis.privacy_domain_id
   WHERE analysis.analysis_id=NEW.resource_id AND analysis.expires_at>clock_timestamp()
    AND target.state='ACTIVE_MATCHED' AND target.active_generation_digest=NEW.generation_digest
    AND target.desired_generation_digest=NEW.generation_digest) THEN
  RAISE EXCEPTION 'PC-DATA-6007-CIGL-PROFILE-CURRENTNESS'; END IF;
 IF NEW.state IN ('COMPLETED','FAILED') AND NOT EXISTS(SELECT 1 FROM control.outbox_event event
    JOIN control.cigl_profile_version version ON version.configuration_work_id=NEW.configuration_work_id
    WHERE event.event_id=NEW.result_event_id AND event.participant_id=NEW.participant_id AND event.privacy_domain_id=NEW.privacy_domain_id
     AND event.aggregate_type='cigl-analysis' AND event.aggregate_id=NEW.resource_id
     AND ((NEW.state='COMPLETED' AND version.state='COMPILED' AND event.event_type='openpc.cigl.profile.compiled.v1')
       OR (NEW.state='FAILED' AND version.state='PENDING' AND event.event_type='openpc.cigl.profile.compilation-failed.v1'))) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-PROFILE-EFFECT'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_profile_work() OWNER TO openpc_control_owner;

--
-- Name: require_cigl_settings_publication(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_cigl_settings_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=NEW.publication_operation_id AND evidence.aggregate_type='cigl-settings'
   AND evidence.aggregate_id=NEW.cigl_settings_id AND evidence.catalog_operation_id='CFG-OP-CREATE-CIGL-SETTINGS'
   AND evidence.action_intent_id='ACT-CIGL_SETTINGS_CREATE_RESOURCE-V1'
   AND NEW.publication_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.cigl_settings_id AND candidate.state='CONSUMED' AND candidate.expected_revision=0
   AND candidate.candidate_document->'definition'=NEW.definition
   AND receipt.terminal_state='COMMITTED'
   AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.cigl_settings_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_id=NEW.cigl_settings_id
    AND event.aggregate_type='cigl-settings' AND event.event_type='openpc.cigl.settings.staged.v1')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CIGL-SETTINGS-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_cigl_settings_publication() OWNER TO openpc_control_owner;

--
-- Name: require_complete_security_record(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_complete_security_record() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE row_document jsonb := to_jsonb(NEW);
BEGIN
  IF TG_TABLE_NAME = 'idempotency_record' AND (
    row_document->>'catalog_operation_id' IN ('ID-OP-WEBAUTHN-VERIFY','POL-OP-ACTIVATE')
    AND row_document->>'webauthn_assertion_binding_digest' IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  IF TG_TABLE_NAME = 'approval_decision_record' AND (
    row_document->>'approver_principal_epoch' IS NULL
    OR row_document->>'approver_authority_envelope_id' IS NULL
    OR row_document->>'approver_envelope_epoch' IS NULL
    OR row_document->>'approver_assignment_id' IS NULL
    OR row_document->>'signer_credential_id' IS NULL
    OR row_document->>'aggregate_version' IS NULL
    OR row_document->>'candidate_digest' IS NULL OR row_document->>'evidence_cbor' IS NULL
    OR (row_document->>'mfa_challenge_id' IS NOT NULL AND (
      row_document->>'approver_participant_epoch' IS NULL
      OR row_document->>'approver_assignment_row_version' IS NULL
      OR row_document->>'approver_delegation_epoch' IS NULL
    ))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  IF TG_TABLE_NAME = 'mutation_evidence' AND (
    row_document->>'evidence_role'='IDENTITY_PROOF_INPUT' OR row_document->>'catalog_operation_id'='ID-OP-INVITATION-ACCEPT'
  ) THEN
    IF NOT coalesce((row_document->>'evidence_role'='IDENTITY_PROOF_INPUT'
      AND row_document->>'evidence_format'='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
      AND row_document->>'catalog_operation_id'='ID-OP-INVITATION-ACCEPT'
      AND row_document->>'action_intent_id'='ACT-PARTICIPANT_CREATE_MEMBER-V1'
      AND row_document->>'aggregate_type'='invitation-redemption'
      AND row_document->>'aggregate_version' IS NOT NULL
      AND row_document->>'bound_participant_epoch' IS NOT NULL AND row_document->>'bound_principal_epoch' IS NOT NULL
      AND octet_length((row_document->>'candidate_digest')::bytea)=32
      AND (row_document->>'evidence_digest')::bytea=sha256((row_document->>'evidence_cbor')::bytea)
      AND row_document->>'checker_principal_id' IS NULL AND row_document->>'approval_request_id' IS NULL
      AND row_document->>'mfa_challenge_id' IS NULL AND row_document->>'signer_credential_id' IS NULL
      AND row_document->>'webauthn_assertion_binding_digest' IS NULL
      AND row_document->>'bound_authority_envelope_id' IS NULL AND row_document->>'bound_envelope_epoch' IS NULL
      AND row_document->>'bound_assignment_id' IS NULL),false) THEN
      RAISE EXCEPTION 'DATA-6021-INCOMPLETE-IDENTITY-PROOF';
    END IF;
  ELSIF TG_TABLE_NAME = 'mutation_evidence' AND row_document->>'catalog_operation_id'='ID-OP-PARTICIPANT-FIRST-ADMIN-ACCEPT' THEN
    IF NOT coalesce((row_document->>'evidence_role'='AUTHORIZATION_INPUT'
      AND row_document->>'evidence_format'='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
      AND row_document->>'action_intent_id'='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'
      AND row_document->>'aggregate_type'='participant'
      AND row_document->>'aggregate_id'=row_document->>'participant_id'
      AND octet_length((row_document->>'webauthn_assertion_binding_digest')::bytea)=32
      AND (row_document->>'evidence_digest')::bytea=sha256((row_document->>'evidence_cbor')::bytea)
      AND row_document->>'bound_authority_envelope_id' IS NULL AND row_document->>'bound_assignment_id' IS NULL
      AND EXISTS (
        SELECT 1 FROM control.participant_bootstrap_custody custody
        JOIN control.mfa_challenge challenge ON challenge.participant_id=custody.participant_id
          AND challenge.principal_id=custody.candidate_membership_id AND challenge.session_id=custody.candidate_session_id
          AND challenge.mfa_challenge_id=(row_document->>'mfa_challenge_id')::uuid
          AND challenge.action_intent_id=row_document->>'action_intent_id'
          AND challenge.resource_digest=(row_document->>'candidate_digest')::bytea
          AND challenge.used_at IS NULL AND challenge.consumed_at IS NULL AND challenge.expires_at>clock_timestamp()
        JOIN control.credential credential ON credential.participant_id=custody.participant_id
          AND credential.principal_id=custody.candidate_membership_id AND credential.credential_id=(row_document->>'signer_credential_id')::uuid
          AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE'
        WHERE custody.participant_id=(row_document->>'participant_id')::uuid
          AND custody.candidate_membership_id=(row_document->>'principal_id')::uuid
          AND custody.state='CLAIM_PENDING' AND custody.expires_at>clock_timestamp()
          AND custody.participant_epoch=(row_document->>'bound_participant_epoch')::numeric
          AND custody.participant_epoch=(row_document->>'aggregate_version')::numeric
      )),false) THEN RAISE EXCEPTION 'DATA-6021-INCOMPLETE-FIRST-ADMIN-CUSTODY'; END IF;
  ELSIF TG_TABLE_NAME = 'mutation_evidence' AND (
    row_document->>'catalog_operation_id' = 'LEGACY'
    OR row_document->>'aggregate_version' IS NULL
    OR row_document->>'bound_authority_envelope_id' IS NULL
    OR row_document->>'bound_envelope_epoch' IS NULL
    OR row_document->>'bound_assignment_id' IS NULL
    OR (row_document->>'catalog_operation_id' IN ('ID-OP-WEBAUTHN-VERIFY','POL-OP-ACTIVATE')
        AND (row_document->>'webauthn_assertion_binding_digest' IS NULL
             OR row_document->>'signer_credential_id' IS NULL))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  IF TG_TABLE_NAME = 'outbox_event' AND (
    row_document->>'aggregate_type' IN ('webauthn-verification','policy-activation')
    AND row_document->>'webauthn_assertion_binding_digest' IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  IF TG_TABLE_NAME = 'credential' AND row_document->>'kind' = 'WEBAUTHN'
     AND row_document->>'state' IN ('ACTIVE','ROTATING')
     AND row_document->>'public_key_spki_der' IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION openpc.require_complete_security_record() OWNER TO openpc_control_owner;

--
-- Name: require_completed_mutation_resume(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_completed_mutation_resume() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE stored control.mutation_candidate;
BEGIN
 IF NEW.resume_request->>'command'='DISCOVERY_PREAPPROVAL_CONTINUE' THEN
  PERFORM openpc.assert_discovery_preapproval_continuation(NEW);
  RETURN NULL;
 END IF;
 IF NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE' AND NEW.resume_request->>'command'='RESUME' THEN
  PERFORM openpc.assert_discovery_approval_resume(NEW);
 END IF;
 IF NEW.resume_request ? 'platformReceivingProof' THEN
  SELECT * INTO STRICT stored FROM control.mutation_candidate WHERE mutation_candidate_id=NEW.mutation_candidate_id;
  PERFORM openpc.assert_platform_recovery_approval_resume(stored);
 END IF;
 IF NEW.predecessor_candidate_id IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM control.idempotency_record r JOIN control.approval_request a
    ON a.participant_id=r.participant_id AND a.privacy_domain_id=r.privacy_domain_id
    AND a.subject_id=NEW.mutation_candidate_id AND a.subject_type='CONFIGURATION_CANDIDATE'
   JOIN control.approval_request prior ON prior.approval_request_id=NEW.predecessor_approval_id
   WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
     AND r.operation_id=NEW.resume_operation_id AND r.terminal_state='COMMITTED'
     AND r.principal_id=NEW.maker_principal_id AND r.action_intent_id='ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'
     AND r.catalog_operation_id='LEGACY' AND r.expected_aggregate_version=prior.row_version
     AND r.input_digest=sha256(convert_to(openpc.signing_canonical_json(CASE WHEN NEW.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
       AND NEW.resume_request ? 'discoveryReceivingProof' THEN NEW.resume_request-'discoveryReceivingProof'
       WHEN NEW.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE' AND NEW.resume_request ? 'platformReceivingProof'
         THEN NEW.resume_request-'platformReceivingProof' ELSE NEW.resume_request END),'UTF8'))
     AND r.result_payload->>'resourceRef'='urn:openpc:resource:'||a.approval_request_id::text
     AND a.subject_digest=NEW.candidate_digest AND a.subject_version=NEW.expected_revision
     AND a.maker_principal_id=NEW.maker_principal_id AND a.checker_principal_id=prior.checker_principal_id
     AND a.state='OPEN' AND a.expires_at=NEW.expires_at
 ) THEN RAISE EXCEPTION 'PC-POLICY-2004'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_completed_mutation_resume() OWNER TO openpc_control_owner;

--
-- Name: require_contract_transfer_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_contract_transfer_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE mode text:=current_setting('openpc.context_mode');
 owner uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op uuid:=current_setting('openpc.operation_id')::uuid;
 action text:=current_setting('openpc.action_intent_id');
 transition control.participant_lifecycle_transition%ROWTYPE; valid boolean;
BEGIN
 IF NEW.source_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.prior_definition-'contentDigest'),'UTF8')),'hex')
   OR NEW.prior_definition->>'contentDigest'<>NEW.source_digest OR jsonb_array_length(NEW.binding_map)<>jsonb_array_length(NEW.prior_definition->'bindings')
   OR (SELECT count(DISTINCT mapping->>'sourceBindingId') FROM jsonb_array_elements(NEW.binding_map) mapping)<>jsonb_array_length(NEW.binding_map)
   OR (SELECT count(DISTINCT mapping->>'successorBindingId') FROM jsonb_array_elements(NEW.binding_map) mapping)<>jsonb_array_length(NEW.binding_map) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-TRANSFER-DEFINITION';
 END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,op,action,true);
 SELECT * INTO transition FROM control.participant_lifecycle_transition WHERE participant_id=NEW.participant_id
  AND operation_id=NEW.operation_id AND mutation='TRANSFER';
 IF NOT FOUND OR EXISTS(SELECT 1 FROM control.contract_runtime_binding WHERE logical_contract_id=NEW.logical_contract_id AND state='BOUND') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-TRANSFER-SOURCE';
 END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',transition.source_participant_id,transition.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c WHERE c.participant_id=transition.source_participant_id
  AND c.consumed_operation_id=NEW.operation_id AND c.state='CONSUMED' AND c.catalog_operation_id='ID-OP-PARTICIPANT-TRANSFER'
  AND c.candidate_document->>'logicalContractId'=NEW.logical_contract_id::text
  AND c.candidate_document->>'contentDigest'=NEW.source_digest
  AND c.candidate_document->>'successorParticipantId'=NEW.successor_participant_id::text
  AND c.candidate_document->>'successorPrivacyDomainId'=NEW.successor_privacy_domain_id::text
  AND c.candidate_document->>'successorLogicalContractId'=NEW.successor_logical_contract_id::text
  AND (c.candidate_document->>'expectedSuccessorEpoch')::numeric+1=NEW.successor_epoch::numeric) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-TRANSFER-CANDIDATE'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.successor_participant_id,NEW.successor_privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.participant p JOIN control.logical_contract_asset asset ON asset.participant_id=p.participant_id
  WHERE p.participant_id=NEW.successor_participant_id AND p.authority_epoch=NEW.successor_epoch::numeric AND p.state='ACTIVE'
   AND asset.logical_contract_id=NEW.successor_logical_contract_id AND asset.privacy_domain_id=NEW.successor_privacy_domain_id) INTO valid;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.binding_map) mapping WHERE NOT EXISTS(
   SELECT 1 FROM control.contract_runtime_binding binding JOIN control.abi_artifact artifact ON artifact.abi_artifact_id=binding.abi_artifact_id
    JOIN jsonb_array_elements(NEW.prior_definition->'bindings') prior ON prior->>'runtime_binding_id'=mapping->>'sourceBindingId'
    JOIN jsonb_array_elements(NEW.prior_definition->'abiArtifacts') abi ON abi->>'abi_artifact_id'=prior->>'abi_artifact_id'
   WHERE binding.participant_id=NEW.successor_participant_id AND binding.privacy_domain_id=NEW.successor_privacy_domain_id
    AND binding.logical_contract_id=NEW.successor_logical_contract_id AND binding.runtime_binding_id::text=mapping->>'successorBindingId'
    AND binding.abi_artifact_id::text=mapping->>'successorAbiArtifactId' AND binding.contract_address=prior->>'contract_address'
    AND binding.chain_id=prior->>'chain_id' AND binding.network_id=prior->>'network_id' AND binding.code_digest=prior->>'code_digest'
    AND binding.genesis_digest=prior->>'genesis_digest' AND binding.abi_version=prior->>'abi_version'
    AND binding.proxy_address IS NOT DISTINCT FROM prior->>'proxy_address'
    AND binding.implementation_address IS NOT DISTINCT FROM prior->>'implementation_address'
    AND binding.implementation_code_digest IS NOT DISTINCT FROM prior->>'implementation_code_digest'
    AND coalesce(binding.transaction_policy,'null'::jsonb)=coalesce(prior->'transaction_policy','null'::jsonb)
    AND artifact.canonical_abi_bytes=(abi->>'canonical_abi_bytes')::bytea
    AND artifact.abi_digest=abi->>'abi_digest' AND artifact.canonical_abi=abi->'canonical_abi' AND binding.state='BOUND')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-TRANSFER-BINDINGS';
 END IF;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-CONTRACT-TRANSFER-SUCCESSOR'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_contract_transfer_provenance() OWNER TO openpc_control_owner;

--
-- Name: require_deployment_intent_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_deployment_intent_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE document jsonb; source jsonb; captured jsonb;
BEGIN
 document:=convert_from(NEW.preparation_bytes,'UTF8')::jsonb;
 source:=convert_from(NEW.publication_bytes,'UTF8')::jsonb;
 captured:=document->'context';
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  JOIN control.deployment_policy policy ON policy.deployment_policy_id=NEW.deployment_policy_id
   AND policy.participant_id=NEW.participant_id AND policy.privacy_domain_id=NEW.privacy_domain_id
  JOIN control.wallet_binding wallet ON wallet.wallet_binding_id=NEW.wallet_binding_id
   AND wallet.participant_id=NEW.participant_id AND wallet.privacy_domain_id=NEW.privacy_domain_id
   AND wallet.subject_id=coalesce(NEW.execution_principal_id,NEW.actor_principal_id) AND wallet.state='ACTIVE'
   AND wallet.binding_epoch::text=captured->>'walletBindingEpoch'
   AND wallet.chain_id::text=policy.definition->>'chainId' AND wallet.wallet_address=document->'intent'->>'sender'
  JOIN control.runtime_target target ON target.runtime_target_id=NEW.runtime_target_id
   AND target.participant_id=NEW.participant_id AND target.privacy_domain_id=NEW.privacy_domain_id
   AND target.state='ACTIVE_MATCHED' AND target.active_generation_digest=target.desired_generation_digest
   AND target.policy_generation_digest='sha256:'||(captured->>'policyGenerationDigest')
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=NEW.creation_operation_id AND evidence.aggregate_type='deployment-intent'
   AND evidence.aggregate_id=NEW.deployment_intent_id AND evidence.catalog_operation_id='CFG-OP-CREATE-DEPLOYMENT-INTENT'
   AND evidence.action_intent_id='ACT-DEPLOYMENT_INTENTS_CREATE_RESOURCE-V1'
   AND NEW.creation_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.deployment_intent_id AND candidate.state='CONSUMED' AND candidate.expected_revision=0
   AND candidate.maker_principal_id=NEW.actor_principal_id
   AND candidate.candidate_document->>'deploymentPolicyId'='urn:openpc:resource:'||NEW.deployment_policy_id::text
   AND candidate.candidate_document->>'runtimeTargetId'='urn:openpc:resource:'||NEW.runtime_target_id::text
   AND candidate.candidate_document->>'walletBindingId'='urn:openpc:resource:'||NEW.wallet_binding_id::text
   AND (candidate.candidate_document->>'executionWorkloadId') IS NOT DISTINCT FROM NEW.execution_workload_id
   AND candidate.candidate_document->>'signingPayload'=document->>'signingPayload'
   AND ((candidate.candidate_document->>'nativeValueAuthorizationId' IS NULL
     AND captured->>'nativeValueAuthorizationBytes' IS NULL AND document->'intent'->>'nativeValueAuthorizationDigest' IS NULL
     AND document->'intent'->>'valueWei'='0')
    OR EXISTS(SELECT 1 FROM control.native_value_authorization issued_grant
     WHERE 'urn:openpc:resource:'||issued_grant.native_value_authorization_id::text=candidate.candidate_document->>'nativeValueAuthorizationId'
      AND issued_grant.participant_id=NEW.participant_id AND issued_grant.privacy_domain_id=NEW.privacy_domain_id
      AND issued_grant.wallet_binding_id=NEW.wallet_binding_id AND issued_grant.wallet_binding_epoch::text=captured->>'walletBindingEpoch'
      AND issued_grant.actor_principal_id=coalesce(NEW.execution_principal_id,NEW.actor_principal_id)
      AND issued_grant.execution_workload_id IS NOT DISTINCT FROM NEW.execution_workload_id
      AND '0x'||encode(issued_grant.document_bytes,'hex')=captured->>'nativeValueAuthorizationBytes'
      AND issued_grant.valid_until>clock_timestamp() AND issued_grant.valid_until>=NEW.expires_at
      AND (document->'intent'->>'valueWei'='0' OR issued_grant.semantic_digest='sha256:'||(document->'intent'->>'nativeValueAuthorizationDigest'))
      AND NOT EXISTS(SELECT 1 FROM control.deployment_address_reservation reservation
       WHERE reservation.native_value_authorization_id=issued_grant.native_value_authorization_id AND reservation.state='HANDOFF')))
   AND source=jsonb_build_object('deploymentPolicyId',policy.deployment_policy_id::text,
    'participantId',policy.participant_id::text,'privacyDomainId',policy.privacy_domain_id::text,
    'definition',policy.definition,'definitionDigest',policy.definition_digest,'artifactDigest',policy.artifact_digest,
    'initCodeHash',policy.init_code_hash,'abiDigest',policy.abi_digest,'publicationOperationId',policy.publication_operation_id::text,
    'publicationAuthorityDigest',policy.publication_authority_digest,'factoryBinding',
     (SELECT jsonb_build_object('runtimeBindingId',factory.runtime_binding_id::text,'chainId',factory.chain_id,
       'networkId',factory.network_id,'genesisDigest',factory.genesis_digest,'contractAddress',factory.contract_address,
       'codeDigest',factory.code_digest,'abiDigest',factory_abi.abi_digest,'canonicalAbi',factory_abi.canonical_abi)
      FROM control.contract_runtime_binding factory JOIN control.abi_artifact factory_abi
       ON factory_abi.participant_id=factory.participant_id AND factory_abi.privacy_domain_id=factory.privacy_domain_id
       AND factory_abi.abi_artifact_id=factory.abi_artifact_id
      WHERE factory.participant_id=policy.participant_id AND factory.privacy_domain_id=policy.privacy_domain_id
       AND factory.runtime_binding_id=policy.factory_runtime_binding_id AND factory.state='BOUND'
       AND factory.chain_id=policy.definition->>'chainId' AND factory.network_id=policy.definition->>'networkId'
       AND factory.genesis_digest=policy.definition->>'genesisDigest'
       AND factory.proxy_address IS NULL AND factory.implementation_address IS NULL
       AND factory.implementation_code_digest IS NULL))
   AND (policy.definition->'route'->>'mechanism'='TRANSACTION_CREATE')=(policy.factory_runtime_binding_id IS NULL)
   AND (policy.definition->>'expiresAt')::timestamptz>=NEW.expires_at
   AND receipt.terminal_state='COMMITTED'
   AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.deployment_intent_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_id=NEW.deployment_intent_id
    AND event.aggregate_type='deployment-intent' AND event.event_type='openpc.deployment.intent.prepared.v1')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-DEPLOYMENT-INTENT-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_deployment_intent_provenance() OWNER TO openpc_control_owner;

--
-- Name: require_deployment_policy_publication(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_deployment_policy_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  JOIN control.abi_artifact abi ON abi.participant_id=NEW.participant_id AND abi.privacy_domain_id=NEW.privacy_domain_id
   AND abi.abi_artifact_id=NEW.abi_artifact_id AND abi.abi_digest=NEW.abi_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=NEW.publication_operation_id AND evidence.aggregate_type='deployment-policy'
   AND evidence.aggregate_id=NEW.deployment_policy_id AND evidence.catalog_operation_id='CFG-OP-CREATE-DEPLOYMENT-POLICY'
   AND evidence.action_intent_id='ACT-DEPLOYMENT_POLICIES_CREATE_RESOURCE-V1'
   AND NEW.publication_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.deployment_policy_id AND candidate.state='CONSUMED' AND candidate.expected_revision=0
   AND candidate.candidate_document->'definition'=NEW.definition
   AND NEW.definition->>'abiArtifactId'='urn:openpc:resource:'||NEW.abi_artifact_id::text
   AND NEW.artifact_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
    'mode',NEW.definition->'artifact'->>'mode','initCodeHash',NEW.init_code_hash,
    'runtimeCodeHash',NEW.definition->'artifact'->>'runtimeCodeHash')),'UTF8')),'hex')
   AND ((NEW.definition->'route'->>'mechanism'='TRANSACTION_CREATE' AND NEW.factory_runtime_binding_id IS NULL)
    OR (NEW.definition->'route'->>'mechanism' IN ('CREATE','CREATE2','CREATE3')
     AND NEW.definition->'route'->>'runtimeBindingId'='urn:openpc:resource:'||NEW.factory_runtime_binding_id::text
     AND EXISTS(SELECT 1 FROM control.contract_runtime_binding factory WHERE factory.participant_id=NEW.participant_id
      AND factory.privacy_domain_id=NEW.privacy_domain_id AND factory.runtime_binding_id=NEW.factory_runtime_binding_id
      AND factory.state='BOUND' AND factory.chain_id=NEW.definition->>'chainId'
      AND factory.network_id=NEW.definition->>'networkId' AND factory.genesis_digest=NEW.definition->>'genesisDigest'
      AND factory.proxy_address IS NULL AND factory.implementation_address IS NULL AND factory.implementation_code_digest IS NULL)))
   AND receipt.terminal_state='COMMITTED'
   AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.deployment_policy_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_id=NEW.deployment_policy_id
    AND event.aggregate_type='deployment-policy' AND event.event_type='openpc.deployment.policy.staged.v1')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-DEPLOYMENT-PUBLICATION-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_deployment_policy_publication() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_checkpoint_hold_coverage(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_checkpoint_hold_coverage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF NEW.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1' THEN
  PERFORM openpc.assert_remote_archive_checkpoint(NEW);
  RETURN NEW;
 END IF;
 IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=NEW.participant_id
  AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=NEW.privacy_domain_id)
  AND openpc.evidence_hold_requires_coverage(h,NEW.stream_id,NEW.segment_id)
  AND NOT EXISTS(SELECT 1 FROM control.evidence_hold_coverage c WHERE c.participant_id=h.participant_id
   AND c.privacy_domain_id=NEW.privacy_domain_id AND c.retention_hold_id=h.retention_hold_id AND c.hold_revision=h.revision
   AND c.segment_id=NEW.segment_id AND c.sink_id=NEW.sink_id AND c.object_digest=NEW.object_digest))
 THEN RAISE EXCEPTION 'PC-DATA-6007-EVIDENCE-HOLD-COVERAGE'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.require_evidence_checkpoint_hold_coverage() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_deletion_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_deletion_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.deletion_job j LEFT JOIN control.evidence_deletion_item item
  USING(participant_id,privacy_domain_id,deletion_job_id)
  LEFT JOIN control.evidence_projection_retirement retired USING(participant_id,privacy_domain_id,deletion_job_id)
  JOIN control.mutation_evidence e ON e.participant_id=j.participant_id AND e.privacy_domain_id=j.privacy_domain_id
   AND e.aggregate_id=j.deletion_job_id AND e.operation_id=j.operation_id AND e.aggregate_type='evidence-deletion'
  JOIN control.mutation_candidate c ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
   AND c.resource_id=e.aggregate_id AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.audit_occurrence receipt ON receipt.participant_id=e.participant_id AND receipt.privacy_domain_id=e.privacy_domain_id
   AND receipt.operation_id=e.operation_id AND receipt.aggregate_id=e.aggregate_id AND receipt.aggregate_type='evidence-deletion'
  WHERE j.participant_id=NEW.participant_id AND j.privacy_domain_id=NEW.privacy_domain_id AND j.deletion_job_id=NEW.deletion_job_id
   AND j.state='SUCCEEDED' AND j.revision=1 AND j.deleted_count=1
   AND CASE WHEN j.target_data_class IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') THEN
    item.deletion_job_id IS NULL AND retired.deletion_job_id IS NOT NULL AND openpc.projection_deletion_effect_matches(j,retired)
   ELSE retired.deletion_job_id IS NULL AND j.deleted_bytes=item.ciphertext_bytes
    AND j.after_digest=openpc.evidence_deletion_after_digest(j.target_selector_digest)
    AND CASE WHEN j.target_data_class='RAW_SOURCE_BODY' THEN openpc.raw_proof_deletion_effect_matches(j,item)
    ELSE j.target_data_class='AUDIT_EVIDENCE' AND j.segment_id=item.segment_id AND j.selection->>'objectDigest'=item.object_digest
     AND NOT EXISTS(SELECT 1 FROM control.evidence_segment_payload p WHERE p.participant_id=j.participant_id
      AND p.privacy_domain_id=j.privacy_domain_id AND p.segment_id=j.segment_id)
     AND EXISTS(SELECT 1 FROM control.evidence_stream s WHERE s.participant_id=j.participant_id
      AND s.privacy_domain_id=j.privacy_domain_id AND s.stream_id=j.stream_id AND s.used_bytes=j.after_used_bytes) END END
   AND e.approval_request_id=j.approval_request_id AND e.catalog_operation_id=openpc.evidence_deletion_operation(j.selection)
   AND e.action_intent_id=openpc.evidence_deletion_action(j.selection) AND c.catalog_operation_id=e.catalog_operation_id
   AND c.action_intent_id=e.action_intent_id AND c.state='CONSUMED' AND c.expected_revision=0
   AND c.candidate_document->'selection'=j.selection AND c.candidate_document->>'beforeDigest'=j.before_digest
   AND receipt.catalog_operation_id=e.catalog_operation_id AND receipt.action_intent_id=e.action_intent_id
   AND receipt.profile_version=openpc.evidence_deletion_profile_version(j.selection)
   AND receipt.before_existence=0 AND receipt.before_revision=0 AND receipt.after_existence=1 AND receipt.after_revision=1
   AND openpc.business_cbor(receipt.before_state_preimage)->8='{}'::jsonb
   AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.evidence_deletion_state_projection(j)
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=receipt.participant_id
    AND event.privacy_domain_id=receipt.privacy_domain_id AND event.receipt_id=receipt.receipt_id
    AND event.aggregate_type=receipt.aggregate_type AND event.aggregate_id=receipt.aggregate_id
    AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
    AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND event.payload_digest=sha256(event.payload_cbor)))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-DELETION-SIGNED-EFFECT'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_evidence_deletion_command() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_export_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_export_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action text; catalog text; expected numeric;
BEGIN
 IF TG_OP='UPDATE' AND OLD.state<>'REQUESTED' THEN RETURN NULL; END IF;
 IF TG_OP='INSERT' THEN action:='ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1';catalog:='CFG-OP-CREATE-EVIDENCE-EXPORT';expected:=0;
 ELSIF NEW.state='REQUESTED' THEN action:='ACT-EVIDENCE_EXPORTS_UPDATE_RESOURCE-V1';catalog:='CFG-OP-UPDATE-EVIDENCE-EXPORT';expected:=OLD.revision;
 ELSE action:='ACT-EVIDENCE_EXPORT_RECORDS-V1';catalog:='CFG-OP-START-EVIDENCE-EXPORT';expected:=OLD.revision; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence e JOIN control.idempotency_record i
  ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id AND i.operation_id=e.operation_id
   AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
  WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.operation_id=NEW.last_operation_id AND e.aggregate_type='evidence-export' AND e.aggregate_id=NEW.evidence_export_id
   AND e.catalog_operation_id=catalog AND e.action_intent_id=action AND i.terminal_state='COMMITTED'
   AND i.expected_aggregate_version=expected AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.evidence_export_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=e.participant_id
    AND event.privacy_domain_id=e.privacy_domain_id AND event.aggregate_type=e.aggregate_type AND event.aggregate_id=e.aggregate_id
    AND event.event_type=CASE catalog WHEN 'CFG-OP-CREATE-EVIDENCE-EXPORT' THEN 'openpc.evidence.export.requested.v1'
      WHEN 'CFG-OP-UPDATE-EVIDENCE-EXPORT' THEN 'openpc.evidence.export.updated.v1' ELSE 'openpc.evidence.export.started.v1' END
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'revision'=NEW.revision::text
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex')
    AND event.payload_digest=sha256(event.payload_cbor))
   AND (NEW.state<>'RUNNING' OR EXISTS(SELECT 1 FROM control.mutation_candidate c
    WHERE c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
     AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
     AND c.action_intent_id=action AND c.catalog_operation_id=catalog AND c.operation_class='EXPORT'
     AND c.state='CONSUMED' AND c.candidate_document->>'inputDigest'=NEW.request_digest)))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-EVIDENCE-EXPORT-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_evidence_export_command() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_export_completion(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_export_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_export_request r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.stream_id=NEW.stream_id AND r.evidence_export_id=NEW.evidence_export_id
  AND r.state='SUCCEEDED' AND r.output_digest=NEW.output_digest)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_evidence_export_completion() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_hold_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_hold_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE operation uuid; approval uuid; catalog text; action text; expected numeric;
BEGIN
 IF TG_OP='INSERT' THEN
  operation:=NEW.creation_operation_id;approval:=NEW.approval_request_id;catalog:='CFG-OP-CREATE-EVIDENCE-HOLD';
  action:='ACT-EVIDENCE_HOLDS_CREATE_RESOURCE-V1';expected:=0;
 ELSE
  operation:=NEW.release_operation_id;approval:=NEW.release_approval_request_id;catalog:='CFG-OP-RELEASE-EVIDENCE-HOLD';
  action:='ACT-EVIDENCE_HOLDS_RELEASE_RESOURCE-V1';expected:=1;
 END IF;
 IF NEW.selector_type='PARTICIPANT' THEN
  catalog:=CASE WHEN TG_OP='INSERT' THEN 'CFG-OP-CREATE-PARTICIPANT-EVIDENCE-HOLD' ELSE 'CFG-OP-RELEASE-PARTICIPANT-EVIDENCE-HOLD' END;
  action:=CASE WHEN TG_OP='INSERT' THEN 'ACT-EVIDENCE_HOLDS_CREATE_PARTICIPANT-V1' ELSE 'ACT-EVIDENCE_HOLDS_RELEASE_PARTICIPANT-V1' END;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence e JOIN control.idempotency_record i
  ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id AND i.operation_id=e.operation_id
   AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
  JOIN control.mutation_candidate c ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
   AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
   AND a.subject_id=c.mutation_candidate_id AND a.approval_request_id=approval
  WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.operation_id=operation AND e.aggregate_type='evidence-hold' AND e.aggregate_id=NEW.retention_hold_id
   AND e.catalog_operation_id=catalog AND e.action_intent_id=action AND i.terminal_state='COMMITTED'
   AND i.expected_aggregate_version=expected AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.retention_hold_id::text
   AND c.catalog_operation_id=catalog AND c.action_intent_id=action AND c.resource_id=NEW.retention_hold_id
   AND c.state='CONSUMED' AND c.expected_revision=expected
   AND (TG_OP<>'INSERT' OR (c.candidate_document->'selector'=NEW.selector AND c.candidate_document->>'holdKind'=NEW.hold_kind))
   AND EXISTS(SELECT 1 FROM control.outbox_event event JOIN control.audit_occurrence receipt
    ON receipt.participant_id=event.participant_id AND receipt.privacy_domain_id=event.privacy_domain_id
    AND receipt.receipt_id=event.receipt_id WHERE event.participant_id=e.participant_id
    AND event.privacy_domain_id=e.privacy_domain_id AND event.aggregate_id=e.aggregate_id AND event.aggregate_type=e.aggregate_type
    AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
    AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND receipt.operation_id=operation
    AND event.payload_digest=sha256(event.payload_cbor))) THEN RAISE EXCEPTION 'PC-AUTH-0002-EVIDENCE-HOLD-PROVENANCE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.audit_occurrence receipt WHERE receipt.participant_id=NEW.participant_id
  AND receipt.privacy_domain_id=NEW.privacy_domain_id AND receipt.operation_id=operation
  AND receipt.aggregate_type='evidence-hold' AND receipt.aggregate_id=NEW.retention_hold_id
  AND receipt.catalog_operation_id=catalog AND receipt.action_intent_id=action
  AND receipt.before_existence=CASE WHEN TG_OP='INSERT' THEN 0 ELSE 1 END
  AND receipt.before_revision=expected AND receipt.after_existence=1 AND receipt.after_revision=NEW.revision
  AND openpc.business_cbor(receipt.before_state_preimage)->8=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE openpc.evidence_hold_state_projection(OLD) END
  AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.evidence_hold_state_projection(NEW))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-EVIDENCE-HOLD-SIGNED-TRANSITION'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_evidence_hold_command() OWNER TO openpc_control_owner;

--
-- Name: require_evidence_payload(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_evidence_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_segment_payload p WHERE p.participant_id=NEW.participant_id
  AND p.privacy_domain_id=NEW.privacy_domain_id AND p.stream_id=NEW.stream_id AND p.segment_id=NEW.segment_id
  AND NEW.object_digest='sha256:'||encode(sha256(p.encrypted_segment),'hex')) THEN
  RAISE EXCEPTION 'PC-DATA-6004-EVIDENCE-PAYLOAD';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_evidence_payload() OWNER TO openpc_control_owner;

--
-- Name: require_explorer_profile_evidence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_explorer_profile_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE
 operation uuid; catalog text; action text; expected_event_type text; expected bigint;
BEGIN
 IF TG_OP='INSERT' THEN
  operation:=NEW.publication_operation_id; catalog:='CFG-OP-CREATE-EXPLORER-PROFILE';
  action:='ACT-PRIVACY_EXPLORER_PROFILES_CREATE_RESOURCE-V1'; expected_event_type:='openpc.privacy-explorer.profile.registered.v1'; expected:=0;
 ELSE
  operation:=NEW.revocation_operation_id; catalog:='CFG-OP-REVOKE-EXPLORER-PROFILE';
  action:='ACT-PRIVACY_EXPLORER_PROFILES_REVOKE_RESOURCE-V1'; expected_event_type:='openpc.privacy-explorer.profile.revoked.v1'; expected:=OLD.revision;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=operation AND evidence.aggregate_type='privacy-explorer-profile'
   AND evidence.aggregate_id=NEW.registration_id AND evidence.catalog_operation_id=catalog AND evidence.action_intent_id=action
   AND candidate.resource_id=NEW.registration_id AND candidate.state='CONSUMED' AND candidate.expected_revision=expected
   AND (TG_OP<>'INSERT' OR (candidate.candidate_document->'profile'=NEW.profile
    AND NEW.publication_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')))
   AND receipt.terminal_state='COMMITTED' AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.registration_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_id=NEW.registration_id
    AND event.aggregate_type='privacy-explorer-profile' AND event.event_type=expected_event_type)) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-EXPLORER-PROFILE-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_explorer_profile_evidence() OWNER TO openpc_control_owner;

--
-- Name: fact_consumer_profile; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.fact_consumer_profile (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    consumer_id text NOT NULL,
    profile_id text NOT NULL,
    revision numeric(20,0) NOT NULL,
    profile_digest text NOT NULL,
    issuer_spki bytea NOT NULL,
    database_role text NOT NULL,
    workload_credential_id uuid NOT NULL,
    workload_credential_epoch numeric(20,0) NOT NULL,
    claims jsonb NOT NULL,
    payload bytea NOT NULL,
    cose bytea NOT NULL,
    admission_reference text NOT NULL,
    admitted_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT fact_consumer_profile_bytes_ck CHECK (((profile_digest = ('sha256:'::text || encode(sha256(cose), 'hex'::text))) AND ((octet_length(payload) >= 1) AND (octet_length(payload) <= 65536)) AND ((octet_length(cose) >= 65) AND (octet_length(cose) <= 66560)) AND (octet_length(issuer_spki) = 91))),
    CONSTRAINT fact_consumer_profile_id_ck CHECK (((consumer_id = ANY (ARRAY['LS-CONTROL-WORK'::text, 'LS-FLEET-CONTROL'::text])) AND ((revision >= (1)::numeric) AND (revision <= '18446744073709551615'::numeric)) AND ((workload_credential_epoch >= (0)::numeric) AND (workload_credential_epoch <= '18446744073709551615'::numeric)))),
    CONSTRAINT fact_consumer_profile_reference_ck CHECK (((length(admission_reference) >= 1) AND (length(admission_reference) <= 256)))
);

ALTER TABLE ONLY control.fact_consumer_profile FORCE ROW LEVEL SECURITY;


ALTER TABLE control.fact_consumer_profile OWNER TO openpc_control_owner;

--
-- Name: require_fact_consumer_profile(text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_fact_consumer_profile(wanted_consumer text) RETURNS control.fact_consumer_profile
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE p control.fact_consumer_profile; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-OPERATIONS_READ_OPERATION-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('fact-consumer-profile:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text||':'||wanted_consumer,0));
 SELECT * INTO STRICT p FROM control.fact_consumer_profile WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND consumer_id=wanted_consumer ORDER BY revision DESC LIMIT 1;
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 IF session_user<>p.database_role OR now_ms<(p.claims->>'validFromMs')::numeric OR now_ms>=(p.claims->>'validUntilMs')::numeric
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.participant v WHERE v.participant_id=p.participant_id AND v.state='ACTIVE' AND v.archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.privacy_domain v WHERE v.participant_id=p.participant_id AND v.privacy_domain_id=p.privacy_domain_id AND v.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
  WHERE c.participant_id=p.participant_id AND c.credential_id=p.workload_credential_id AND c.credential_epoch=p.workload_credential_epoch
   AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC') AND c.state='ACTIVE' AND w.kind='WORKLOAD' AND w.state='ACTIVE'
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND c.public_key_digest IS DISTINCT FROM sha256(p.issuer_spki) FOR SHARE OF c,w;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN p;
END $$;


ALTER FUNCTION openpc.require_fact_consumer_profile(wanted_consumer text) OWNER TO openpc_control_owner;

--
-- Name: fact_consumer_failure_signer; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.fact_consumer_failure_signer (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    consumer_id text NOT NULL,
    signer_key_id text NOT NULL,
    public_key_spki bytea NOT NULL,
    environment_id text NOT NULL,
    database_role text NOT NULL,
    workload_credential_id uuid NOT NULL,
    workload_credential_epoch numeric(20,0) NOT NULL,
    signer_role text NOT NULL,
    purpose_code numeric(20,0) NOT NULL,
    valid_from_ms numeric(20,0) NOT NULL,
    valid_until_ms numeric(20,0) NOT NULL,
    state text DEFAULT 'ACTIVE'::text NOT NULL,
    admission_reference text NOT NULL,
    CONSTRAINT fact_failure_signer_key_ck CHECK (((signer_key_id = ('sha256:'::text || encode(sha256(public_key_spki), 'hex'::text))) AND (octet_length(public_key_spki) = 91))),
    CONSTRAINT fact_failure_signer_reference_ck CHECK (((length(admission_reference) >= 1) AND (length(admission_reference) <= 256))),
    CONSTRAINT fact_failure_signer_scope_ck CHECK (((consumer_id = ANY (ARRAY['LS-FLEET-CONTROL'::text, 'LS-CONTROL-WORK'::text])) AND (signer_role = 'FACT_CONSUMER_FAILURE'::text) AND (purpose_code = (344)::numeric) AND (state = ANY (ARRAY['ACTIVE'::text, 'REVOKED'::text])) AND ((workload_credential_epoch >= (0)::numeric) AND (workload_credential_epoch <= '18446744073709551615'::numeric)))),
    CONSTRAINT fact_failure_signer_time_ck CHECK ((((valid_from_ms >= (0)::numeric) AND (valid_from_ms <= ('9007199254740991'::bigint)::numeric)) AND ((valid_until_ms >= (valid_from_ms + (1)::numeric)) AND (valid_until_ms <= ('9007199254740991'::bigint)::numeric))))
);

ALTER TABLE ONLY control.fact_consumer_failure_signer FORCE ROW LEVEL SECURITY;


ALTER TABLE control.fact_consumer_failure_signer OWNER TO openpc_control_owner;

--
-- Name: require_fact_failure_signer(control.fact_consumer_profile, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_fact_failure_signer(p control.fact_consumer_profile, wanted_signer text) RETURNS control.fact_consumer_failure_signer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s control.fact_consumer_failure_signer; now_ms numeric;
BEGIN
 SELECT * INTO s FROM control.fact_consumer_failure_signer WHERE participant_id=p.participant_id
  AND privacy_domain_id=p.privacy_domain_id AND consumer_id=p.consumer_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF s.signer_key_id IS DISTINCT FROM wanted_signer OR s.environment_id IS DISTINCT FROM p.claims->>'environmentId'
  OR s.database_role IS DISTINCT FROM session_user OR s.database_role IS DISTINCT FROM p.database_role
  OR s.workload_credential_id IS DISTINCT FROM p.workload_credential_id OR s.workload_credential_epoch IS DISTINCT FROM p.workload_credential_epoch
  OR s.signer_role<>'FACT_CONSUMER_FAILURE' OR s.purpose_code<>344
  OR now_ms<s.valid_from_ms OR now_ms>=s.valid_until_ms OR s.public_key_spki=p.issuer_spki
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN s;
END $$;


ALTER FUNCTION openpc.require_fact_failure_signer(p control.fact_consumer_profile, wanted_signer text) OWNER TO openpc_control_owner;

--
-- Name: require_first_admin_handoff(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_first_admin_handoff() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.state='ACCEPTED' AND NOT EXISTS (
  SELECT 1 FROM control.participant participant
  JOIN control.principal principal ON principal.participant_id=participant.participant_id AND principal.principal_id=NEW.accepted_membership_id AND principal.state='ACTIVE'
  JOIN control.participant_membership member ON member.participant_id=principal.participant_id AND member.membership_id=principal.principal_id
  JOIN control.assignment assignment ON assignment.participant_id=participant.participant_id AND assignment.principal_id=principal.principal_id
    AND assignment.bootstrap_mandate_id=NEW.mandate_id AND assignment.state='ACTIVE' AND assignment.last_mutation_operation_id=NEW.accepted_operation_id
  JOIN control.authority_envelope envelope ON envelope.participant_id=assignment.participant_id AND envelope.authority_envelope_id=assignment.authority_envelope_id
    AND envelope.state='ACTIVE' AND envelope.bootstrap_mandate_id=NEW.mandate_id AND envelope.last_mutation_operation_id=NEW.accepted_operation_id
  JOIN control.mutation_evidence evidence ON evidence.participant_id=participant.participant_id AND evidence.operation_id=NEW.accepted_operation_id
    AND evidence.principal_id=NEW.accepted_membership_id AND evidence.catalog_operation_id='ID-OP-PARTICIPANT-FIRST-ADMIN-ACCEPT'
    AND evidence.candidate_digest=NEW.accepted_intent_digest
  JOIN control.outbox_event event ON event.participant_id=participant.participant_id AND event.aggregate_id=participant.participant_id
    AND event.event_type='openpc.identity.first-administrator.accepted.v1' AND event.payload_digest=evidence.evidence_digest
  WHERE participant.participant_id=NEW.participant_id AND participant.state='ACTIVE' AND participant.authority_epoch=NEW.participant_epoch+1
    AND NEW.acceptance_result IS NOT NULL AND NEW.closed_at IS NOT NULL
 ) THEN RAISE EXCEPTION 'PC-AUTH-0002'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_first_admin_handoff() OWNER TO openpc_control_owner;

--
-- Name: require_generated_cigl_grant(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_generated_cigl_grant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NEW.origin<>'GENERATED' THEN RETURN NULL; END IF;
 IF NEW.status='ACTIVE' THEN
  IF NOT EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims claim
    JOIN control.cigl_profile_dependency_path path ON path.profile_id=claim.profile_id AND path.profile_revision=claim.profile_revision AND path.ordinal=claim.ordinal
    JOIN control.mutation_candidate candidate ON candidate.participant_id=claim.participant_id AND candidate.privacy_domain_id=claim.privacy_domain_id
     AND candidate.resource_id=claim.source_grant_id AND candidate.consumed_operation_id=claim.publication_operation_id AND candidate.state='CONSUMED'
     AND candidate.catalog_operation_id='CFG-OP-UPDATE-CIGL-GRANT'
    WHERE claim.required_grant_id=NEW.grant_id AND claim.state='ACTIVE'
     AND claim.publication_operation_id=NEW.publication_operation_id AND claim.source_grant_id=NEW.generated_by_grant_id
     AND EXISTS(SELECT 1 FROM jsonb_array_elements(candidate.candidate_document->'dependencyBundle'->'dependencies') item
       WHERE item->'grant'='{"kind":"GENERATE"}'::jsonb AND item->>'actionDigest'='sha256:'||(path.document->>'actionDigest'))) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GENERATED-UNOWNED'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims WHERE required_grant_id=NEW.grant_id AND state='ACTIVE')
   OR NOT EXISTS(SELECT 1 FROM control.cigl_method_grant_dependency_claims WHERE required_grant_id=NEW.grant_id AND released_operation_id=NEW.publication_operation_id)
   OR NOT EXISTS(SELECT 1 FROM control.mutation_evidence WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
     AND operation_id=NEW.publication_operation_id AND catalog_operation_id='CFG-OP-UPDATE-CIGL-GRANT') THEN
   RAISE EXCEPTION 'PC-AUTH-0002-CIGL-GENERATED-RELEASE'; END IF;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_generated_cigl_grant() OWNER TO openpc_control_owner;

--
-- Name: require_identity_envelope_proposal(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_identity_envelope_proposal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE original_mode text; original_participant uuid; original_privacy uuid;
 operation uuid; action text;
	 p control.identity_envelope_proposal%ROWTYPE; envelope control.authority_envelope%ROWTYPE;
	 valid_source boolean; activation_cose bytea;
BEGIN
 IF TG_TABLE_NAME='authority_envelope' THEN
  -- Recovery provenance is enforced by guard_platform_recovery_envelope and
  -- its immutable signed case bindings. It has no ordinary typed issuer or
  -- proposal sidecar; typed envelopes must retain the checks below.
  IF NEW.representation IN ('LEGACY','RECOVERY_V1') THEN RETURN NULL; END IF;
 END IF;
 -- Legacy initialization has no typed governance context. Typed rows still
 -- require every ordinary context field before any scoped lookup or switch.
 original_mode:=current_setting('openpc.context_mode');
 original_participant:=openpc.current_participant_id(); original_privacy:=openpc.current_privacy_domain_id();
 operation:=openpc.current_operation_id(); action:=openpc.current_action_intent_id();
 IF TG_TABLE_NAME='authority_envelope' THEN
  -- Resolve only the envelope's immutable original issuer; no tenant OR-policy.
  PERFORM openpc.set_request_context('PARTICIPANT',NEW.issuer_participant_id,NEW.issuer_privacy_domain_id,operation,action,true);
  SELECT * INTO p FROM control.identity_envelope_proposal WHERE participant_id=NEW.issuer_participant_id
    AND privacy_domain_id=NEW.issuer_privacy_domain_id AND envelope_id=NEW.authority_envelope_id;
 ELSE
  PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,operation,action,true);
  SELECT * INTO p FROM control.identity_envelope_proposal WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND envelope_id=NEW.envelope_id;
 END IF;
 IF p.envelope_id IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIDECAR'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',p.participant_id,p.privacy_domain_id,operation,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate candidate
   JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id AND evidence.privacy_domain_id=candidate.privacy_domain_id
     AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
     AND evidence.principal_id=p.maker_principal_id AND evidence.approval_request_id=p.create_approval_id
   JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id AND receipt.privacy_domain_id=candidate.privacy_domain_id
     AND receipt.operation_id=candidate.consumed_operation_id AND receipt.terminal_state='COMMITTED'
     AND receipt.result_payload->>'id'=p.envelope_id::text
     AND receipt.result_payload->>'semanticDigest'='sha256:'||encode(p.proposal_digest,'hex')
   WHERE candidate.participant_id=p.participant_id AND candidate.privacy_domain_id=p.privacy_domain_id
     AND candidate.mutation_candidate_id=p.create_candidate_id AND candidate.consumed_operation_id=p.create_operation_id
     AND candidate.state='CONSUMED' AND candidate.catalog_operation_id='ID-OP-ENVELOPE-CREATE'
     AND candidate.resource_id=p.envelope_id AND candidate.maker_principal_id=p.maker_principal_id
     AND candidate.candidate_document->>'schema'='pc.identity.authority-envelope-proposal'
     AND candidate.candidate_document->>'envelopeId'=p.envelope_id::text
     AND candidate.candidate_document->>'participantId'=p.target_participant_id::text
     AND candidate.maker_session_id::text=p.issuer_authority#>>'{binding,sessionId}'
     AND candidate.maker_session_epoch::text=p.issuer_authority#>>'{binding,sessionEpoch}'
     AND candidate.maker_participant_epoch::text=p.issuer_authority#>>'{binding,participantEpoch}'
     AND candidate.maker_principal_epoch::text=p.issuer_authority#>>'{binding,principalEpoch}'
     AND candidate.maker_assignment_id::text=p.issuer_authority#>>'{binding,assignmentId}'
     AND candidate.maker_assignment_row_version::text=p.issuer_authority#>>'{binding,assignmentVersion}'
     AND candidate.maker_authority_envelope_id::text=p.issuer_authority#>>'{binding,authorityEnvelopeId}'
     AND candidate.maker_authority_epoch::text=p.issuer_authority#>>'{binding,authorityEpoch}'
     AND candidate.maker_delegation_epoch::text=p.issuer_authority#>>'{binding,delegationEpoch}') INTO valid_source;
 IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-CREATE-PROVENANCE'; END IF;
 IF p.state<>'DRAFT' THEN
  SELECT EXISTS(SELECT 1 FROM control.approval_request request
    JOIN control.idempotency_record receipt ON receipt.participant_id=request.participant_id AND receipt.privacy_domain_id=request.privacy_domain_id
      AND receipt.operation_id=p.submission_operation_id AND receipt.input_digest=p.submission_intent_digest
      AND receipt.action_intent_id='ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1' AND receipt.terminal_state='COMMITTED'
      AND receipt.principal_id=p.maker_principal_id AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||request.approval_request_id::text
    JOIN control.mfa_challenge challenge ON challenge.participant_id=request.participant_id AND challenge.principal_id=p.maker_principal_id
      AND challenge.mfa_challenge_id=(p.submission_maker->>'stepUpChallengeId')::uuid
      AND challenge.session_id=(p.submission_maker#>>'{authority,sessionId}')::uuid
      AND challenge.action_intent_id='ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1' AND challenge.resource_digest=p.submission_intent_digest
      AND challenge.resource_id=p.envelope_id::text
      AND challenge.used_operation_id=p.submission_operation_id AND challenge.used_at IS NOT NULL
      AND challenge.used_at>=challenge.consumed_at AND challenge.used_at<challenge.expires_at
      AND challenge.used_at<challenge.consumed_at+interval '5 minutes'
    JOIN control.mutation_evidence verification ON verification.participant_id=challenge.participant_id
      AND verification.privacy_domain_id=p.privacy_domain_id AND verification.principal_id=p.maker_principal_id
      AND verification.mfa_challenge_id=challenge.mfa_challenge_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
      AND verification.evidence_digest=decode(substr(p.submission_maker->>'stepUpEvidenceDigest',8),'hex')
      AND verification.signer_credential_id=(p.submission_maker->>'signerCredentialId')::uuid
      AND challenge.signer_credential_id=verification.signer_credential_id
      AND challenge.signer_credential_epoch::text=p.submission_maker->>'signerCredentialEpoch'
    WHERE request.participant_id=p.participant_id AND request.privacy_domain_id=p.privacy_domain_id
      AND request.approval_request_id=p.submission_approval_id AND request.subject_type='AUTHORITY_ENVELOPE'
      AND request.subject_id=p.envelope_id AND request.subject_digest=p.proposal_digest AND request.subject_version=1
      AND request.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' AND request.maker_principal_id=p.maker_principal_id
      AND p.submission_maker->'authority'=p.issuer_authority->'binding'
      AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=p.participant_id AND event.privacy_domain_id=p.privacy_domain_id
        AND event.aggregate_type='authority-envelope' AND event.aggregate_id=p.envelope_id
        AND event.event_type='openpc.identity.authority-envelope.submitted.v1' AND event.payload_digest=verification.evidence_digest
        AND event.payload_cbor=verification.evidence_cbor AND event.cose_sign1=verification.cose_sign1)
      AND ((p.state='SUBMITTED' AND request.state='OPEN') OR (p.state='APPROVED' AND request.state='APPROVED'))) INTO valid_source;
  IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SUBMISSION-PROVENANCE'; END IF;
 END IF;
 IF p.state='APPROVED' THEN
  SELECT EXISTS(SELECT 1 FROM control.approval_decision_record decision
    JOIN control.mfa_challenge challenge ON challenge.participant_id=decision.participant_id AND challenge.mfa_challenge_id=decision.mfa_challenge_id
      AND challenge.principal_id=decision.approver_principal_id AND challenge.action_intent_id='ACT-POLICY_APPROVE_REQUEST-V1'
      AND challenge.session_id=decision.approver_session_id
      AND challenge.resource_digest=decision.decision_digest AND challenge.used_at IS NOT NULL
      AND challenge.resource_id=decision.approval_request_id::text
      AND challenge.signer_credential_id=decision.signer_credential_id
      AND challenge.signer_credential_epoch=decision.signer_credential_epoch
      AND challenge.used_at>=challenge.consumed_at AND challenge.used_at<challenge.expires_at
      AND challenge.used_at<challenge.consumed_at+interval '5 minutes'
    JOIN control.mutation_evidence verification ON verification.participant_id=decision.participant_id
      AND verification.privacy_domain_id=decision.privacy_domain_id AND verification.principal_id=decision.approver_principal_id
      AND verification.mfa_challenge_id=challenge.mfa_challenge_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
      AND verification.bound_participant_epoch=decision.approver_participant_epoch
      AND verification.bound_principal_epoch=decision.approver_principal_epoch
      AND verification.signer_credential_id=decision.signer_credential_id
      AND verification.evidence_cbor=decision.evidence_cbor AND verification.cose_sign1=decision.cose_sign1
    WHERE decision.participant_id=p.participant_id AND decision.privacy_domain_id=p.privacy_domain_id
      AND decision.approval_request_id=p.submission_approval_id AND decision.decision='APPROVE'
      AND decision.candidate_digest=p.proposal_digest AND decision.aggregate_version=1
      AND decision.approver_principal_id<>p.maker_principal_id
      AND decision.approver_principal_id::text=p.submission_checker#>>'{authority,principalId}'
      AND decision.participant_id::text=p.submission_checker#>>'{authority,participantId}'
      AND decision.approver_participant_epoch::text=p.submission_checker#>>'{authority,participantEpoch}'
      AND decision.approver_principal_epoch::text=p.submission_checker#>>'{authority,principalEpoch}'
      AND decision.approver_session_id::text=p.submission_checker#>>'{authority,sessionId}'
      AND decision.approver_session_epoch::text=p.submission_checker#>>'{authority,sessionEpoch}'
      AND decision.approver_assignment_id::text=p.submission_checker#>>'{authority,assignmentId}'
      AND decision.approver_assignment_row_version::text=p.submission_checker#>>'{authority,assignmentVersion}'
      AND decision.approver_authority_envelope_id::text=p.submission_checker#>>'{authority,authorityEnvelopeId}'
      AND decision.approver_envelope_epoch::text=p.submission_checker#>>'{authority,authorityEpoch}'
      AND decision.approver_delegation_epoch::text=p.submission_checker#>>'{authority,delegationEpoch}'
      AND p.submission_checker_authority->'binding'=p.submission_checker->'authority'
      AND p.submission_checker_authority#>'{durable,grant}' @> jsonb_build_object(
        'principalId',decision.approver_principal_id::text,'participantEpoch',decision.approver_participant_epoch::text,
        'principalEpoch',decision.approver_principal_epoch::text,'assignmentId',decision.approver_assignment_id::text,
        'assignmentRowVersion',decision.approver_assignment_row_version::text,'authorityEnvelopeId',decision.approver_authority_envelope_id::text,
        'authorityEpoch',decision.approver_envelope_epoch::text,'delegationEpoch',decision.approver_delegation_epoch::text,
        'privacyDomainId',p.privacy_domain_id::text,'actionIntentId','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','resourceId',p.envelope_id::text)
      AND decision.mfa_challenge_id::text=p.submission_checker->>'stepUpChallengeId'
      AND decision.mfa_challenge_id::text<>p.submission_maker->>'stepUpChallengeId'
      AND decision.signer_credential_id::text=p.submission_checker->>'signerCredentialId'
      AND decision.signer_credential_epoch::text=p.submission_checker->>'signerCredentialEpoch'
      AND sha256(decision.evidence_cbor)=decode(substr(p.submission_checker->>'stepUpEvidenceDigest',8),'hex')
      AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=p.participant_id AND event.privacy_domain_id=p.privacy_domain_id
        AND event.aggregate_type='authority-envelope' AND event.aggregate_id=p.envelope_id
        AND event.event_type='openpc.identity.authority-envelope.approved.v1' AND event.payload_digest=sha256(decision.evidence_cbor)
        AND event.payload_cbor=decision.evidence_cbor AND event.cose_sign1=decision.cose_sign1)) INTO valid_source;
	  IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-APPROVAL-PROVENANCE'; END IF;
	 END IF;
	 IF p.state='APPROVED' THEN
	  SELECT activation.cose_sign1 INTO activation_cose
	    FROM control.identity_envelope_activation activation
	   WHERE activation.participant_id=p.participant_id AND activation.privacy_domain_id=p.privacy_domain_id
	     AND activation.envelope_id=p.envelope_id AND activation.operation_id=operation
	     AND activation.state='COMMITTED' AND activation.row_version=4;
	 END IF;
	 PERFORM openpc.set_request_context('PARTICIPANT',p.target_participant_id,NULL,operation,action,false);
 SELECT * INTO envelope FROM control.authority_envelope WHERE participant_id=p.target_participant_id AND authority_envelope_id=p.envelope_id;
 IF envelope.representation IS DISTINCT FROM 'TYPED_V1' OR envelope.issuer_participant_id IS DISTINCT FROM p.participant_id
   OR envelope.issuer_privacy_domain_id IS DISTINCT FROM p.privacy_domain_id
	 OR envelope.maker_principal_id IS DISTINCT FROM p.maker_principal_id OR envelope.semantic_cbor IS DISTINCT FROM p.proposal_cbor
	 OR envelope.semantic_digest IS DISTINCT FROM p.proposal_digest
	 OR NOT (
	   (envelope.state::text=p.state AND envelope.row_version=p.row_version)
	   OR (p.state='APPROVED' AND envelope.state='ACTIVE' AND envelope.row_version=p.row_version+1
	     AND octet_length(envelope.cose_sign1)>0
	     AND activation_cose=envelope.cose_sign1)
	 )
	 OR (p.state='APPROVED' AND envelope.checker_principal_id::text IS DISTINCT FROM p.submission_checker#>>'{authority,principalId}')
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TARGET-BINDING'; END IF;
 PERFORM openpc.set_request_context(original_mode,original_participant,original_privacy,operation,action,original_privacy IS NOT NULL);
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_identity_envelope_proposal() OWNER TO openpc_control_owner;

--
-- Name: require_invitation_acceptance_evidence(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_invitation_acceptance_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM control.mutation_evidence evidence
   JOIN control.participant_invitation invitation ON invitation.invitation_id=NEW.invitation_id
   JOIN control.outbox_event event ON event.participant_id=evidence.participant_id AND event.privacy_domain_id=evidence.privacy_domain_id
    AND event.aggregate_type='invitation-redemption' AND event.aggregate_id=NEW.invitation_id
    AND event.event_type='openpc.identity.invitation.accepted.v1'
    AND event.payload_cbor=NEW.evidence_cbor AND event.payload_digest=NEW.evidence_digest AND event.cose_sign1=NEW.cose_sign1
   WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
    AND evidence.operation_id=NEW.operation_id AND evidence.principal_id=NEW.membership_id
    AND evidence.action_intent_id='ACT-PARTICIPANT_CREATE_MEMBER-V1' AND evidence.catalog_operation_id='ID-OP-INVITATION-ACCEPT'
    AND evidence.aggregate_type='invitation-redemption' AND evidence.aggregate_id=NEW.invitation_id
    AND evidence.aggregate_version=invitation.row_version-CASE WHEN invitation.bootstrap_mandate_id IS NULL THEN 1 ELSE 0 END
    AND evidence.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(NEW.result),'UTF8'))
    AND evidence.evidence_role='IDENTITY_PROOF_INPUT' AND evidence.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
    AND evidence.evidence_cbor=NEW.evidence_cbor AND evidence.evidence_digest=NEW.evidence_digest AND evidence.cose_sign1=NEW.cose_sign1) THEN
  RAISE EXCEPTION 'PC-AUTH-0002';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_invitation_acceptance_evidence() OWNER TO openpc_control_owner;

--
-- Name: require_invitation_current_token(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_invitation_current_token() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM control.participant_invitation invitation
   JOIN control.participant_invitation_token token
    ON token.participant_id=invitation.participant_id AND token.privacy_domain_id=invitation.privacy_domain_id
     AND token.invitation_id=invitation.invitation_id AND token.token_version=invitation.token_version
     AND token.expires_at=invitation.expires_at
   WHERE invitation.participant_id=NEW.participant_id AND invitation.privacy_domain_id=NEW.privacy_domain_id
    AND invitation.invitation_id=NEW.invitation_id) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-INVITATION-CURRENT-TOKEN';
 END IF;
 IF EXISTS (SELECT 1 FROM control.participant_invitation invitation WHERE invitation.invitation_id=NEW.invitation_id AND invitation.state='ACCEPTED'
   AND NOT EXISTS (SELECT 1 FROM control.participant_invitation_acceptance acceptance
    WHERE acceptance.participant_id=invitation.participant_id AND acceptance.privacy_domain_id=invitation.privacy_domain_id
      AND acceptance.invitation_id=invitation.invitation_id AND acceptance.token_version=invitation.token_version
      AND (acceptance.operation_id=invitation.last_mutation_operation_id OR EXISTS (
        SELECT 1 FROM control.participant_bootstrap_custody custody WHERE custody.participant_id=invitation.participant_id
          AND custody.invitation_id=invitation.invitation_id AND custody.mandate_id=invitation.bootstrap_mandate_id
          AND custody.state='ACCEPTED' AND custody.accepted_membership_id=acceptance.membership_id
          AND custody.accepted_operation_id=invitation.last_mutation_operation_id)))) THEN
  RAISE EXCEPTION 'PC-AUTH-0002';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_invitation_current_token() OWNER TO openpc_control_owner;

--
-- Name: require_native_value_issuance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_native_value_issuance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE document jsonb:=convert_from(NEW.document_bytes,'UTF8')::jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  JOIN control.wallet_binding wallet ON wallet.participant_id=NEW.participant_id AND wallet.privacy_domain_id=NEW.privacy_domain_id
   AND wallet.wallet_binding_id=NEW.wallet_binding_id AND wallet.binding_epoch=NEW.wallet_binding_epoch
   AND wallet.subject_id=NEW.actor_principal_id AND wallet.state='ACTIVE' AND wallet.chain_id::text=document->>'chainId'
  JOIN control.participant participant ON participant.participant_id=NEW.participant_id
   AND participant.authority_epoch=(document->>'participantEpoch')::numeric
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=NEW.creation_operation_id AND evidence.aggregate_type='native-value-authorization'
   AND evidence.aggregate_id=NEW.native_value_authorization_id AND evidence.catalog_operation_id='CFG-OP-CREATE-NATIVE-VALUE-AUTHORIZATION'
   AND evidence.action_intent_id='ACT-NATIVE_VALUE_AUTHORIZATIONS_CREATE_RESOURCE-V1'
   AND NEW.creation_authority_digest='sha256:'||encode(evidence.evidence_digest,'hex')
   AND candidate.resource_id=NEW.native_value_authorization_id AND candidate.state='CONSUMED' AND candidate.expected_revision=0
   AND ((NEW.execution_workload_id IS NULL AND candidate.maker_principal_id=NEW.actor_principal_id)
    OR (NEW.execution_workload_id IS NOT NULL AND EXISTS(
     SELECT 1 FROM control.principal principal JOIN control.credential credential USING(participant_id,principal_id)
     WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=NEW.actor_principal_id
      AND principal.kind='WORKLOAD' AND principal.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS'
      AND credential.audience=NEW.execution_workload_id AND credential.state='ACTIVE'
      AND credential.valid_from<=clock_timestamp() AND credential.valid_until>clock_timestamp())
     AND NOT EXISTS(SELECT 1 FROM control.principal other JOIN control.credential credential USING(participant_id,principal_id)
      WHERE other.participant_id=NEW.participant_id AND other.principal_id<>NEW.actor_principal_id
       AND other.kind='WORKLOAD' AND other.state='ACTIVE' AND credential.kind='WORKLOAD_MTLS'
       AND credential.audience=NEW.execution_workload_id AND credential.state='ACTIVE'
       AND credential.valid_from<=clock_timestamp() AND credential.valid_until>clock_timestamp())))
   AND candidate.candidate_document->>'walletBindingId'='urn:openpc:resource:'||NEW.wallet_binding_id::text
   AND (candidate.candidate_document->>'executionWorkloadId') IS NOT DISTINCT FROM NEW.execution_workload_id
   AND candidate.candidate_document->>'chainId'=document->>'chainId'
   AND concat(candidate.candidate_document->>'chainId',':',candidate.candidate_document->>'networkId',':',candidate.candidate_document->>'genesisDigest')=document->>'chainEnvironmentId'
   AND candidate.candidate_document->>'genesisDigest'='sha256:'||(document->>'genesisHash')
   AND candidate.candidate_document->>'amountMode'=document->>'amountMode'
   AND candidate.candidate_document->>'maxAmountWei'=document->>'maxAmountWei'
   AND candidate.candidate_document->>'validUntil'=document->>'validUntil'
   AND receipt.terminal_state='COMMITTED'
   AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.native_value_authorization_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_id=NEW.native_value_authorization_id
    AND event.aggregate_type='native-value-authorization' AND event.event_type='openpc.native-value.authorization.issued.v1')) THEN
  RAISE EXCEPTION 'PC-AUTH-0002-NATIVE-VALUE-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_native_value_issuance() OWNER TO openpc_control_owner;

--
-- Name: require_notification_completion_disposition_authority(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_notification_completion_disposition_authority(event uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE original jsonb;
BEGIN
 PERFORM openpc.assert_notification_completion_admission_owner();
 SELECT a.proof INTO STRICT original FROM control.notification_completion_phase_admission a
 WHERE a.database_role=session_user AND a.transaction_id=pg_current_xact_id()::text AND a.backend_pid=pg_backend_pid()
  AND a.participant_id=openpc.current_participant_id() AND a.privacy_domain_id=openpc.current_privacy_domain_id()
  AND a.event_id=event AND a.phase=$2;
 PERFORM openpc.check_notification_completion_phase_proof(original);
END $_$;


ALTER FUNCTION openpc.require_notification_completion_disposition_authority(event uuid, phase text) OWNER TO openpc_control_owner;

--
-- Name: require_participant_lifecycle_history(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_participant_lifecycle_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE mode text:=current_setting('openpc.context_mode');
 owner uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op uuid:=current_setting('openpc.operation_id')::uuid;
 action text:=current_setting('openpc.action_intent_id'); valid boolean;
BEGIN
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.participant p JOIN control.outbox_event event ON event.participant_id=p.participant_id
   AND event.event_id=NEW.operation_id AND event.event_type='openpc.identity.participant.epoch.advanced.v1'
   WHERE p.participant_id=NEW.participant_id AND p.authority_epoch=NEW.new_epoch AND p.row_version=NEW.revision
    AND p.root_privacy_domain_id=NEW.privacy_domain_id
    AND (p.archived_at IS NOT NULL)=(NEW.mutation='ARCHIVE')) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-EFFECT'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.source_participant_id,NEW.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate candidate JOIN control.mutation_evidence evidence
   ON evidence.participant_id=candidate.participant_id AND evidence.operation_id=candidate.consumed_operation_id
    AND evidence.candidate_digest=candidate.candidate_digest AND evidence.catalog_operation_id=candidate.catalog_operation_id
   JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
    AND receipt.operation_id=NEW.operation_id AND receipt.terminal_state='COMMITTED'
   WHERE candidate.participant_id=NEW.source_participant_id AND candidate.privacy_domain_id=NEW.source_privacy_domain_id
    AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=NEW.operation_id
    AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||NEW.mutation AND candidate.resource_id=NEW.participant_id
    AND candidate.candidate_document->>'privacyDomainId'=NEW.privacy_domain_id::text
    AND candidate.candidate_document->>'expectedEpoch'=NEW.prior_epoch::text
    AND candidate.expected_revision=NEW.revision-1 AND receipt.result_payload#>>'{result,epoch}'=NEW.new_epoch::text)
 INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_participant_lifecycle_history() OWNER TO openpc_control_owner;

--
-- Name: require_participant_lifecycle_transition(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_participant_lifecycle_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE transition control.participant_lifecycle_transition%ROWTYPE;
 mode text; owner uuid; privacy uuid; op uuid; action text;
 valid boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-HISTORY-RETAINED'; END IF;
 IF NEW.archived_at IS NOT DISTINCT FROM OLD.archived_at THEN RETURN NULL; END IF;
 mode:=current_setting('openpc.context_mode');
 owner:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op:=current_setting('openpc.operation_id')::uuid;
 action:=current_setting('openpc.action_intent_id');
 IF NOT ((OLD.state='ACTIVE' AND NEW.state='SUSPENDED' AND OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL)
      OR (OLD.state='SUSPENDED' AND NEW.state='ACTIVE' AND OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL))
    OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1 THEN
  RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-TRANSITION';
 END IF;
 PERFORM openpc.set_request_context('PLATFORM',NEW.participant_id,null,op,action,false);
 SELECT * INTO transition FROM control.participant_lifecycle_transition
  WHERE participant_id=NEW.participant_id AND new_epoch=NEW.authority_epoch AND prior_epoch=OLD.authority_epoch
   AND revision=NEW.row_version AND mutation=CASE WHEN NEW.archived_at IS NULL THEN 'RESTORE' ELSE 'ARCHIVE' END;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-HISTORY'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',transition.source_participant_id,transition.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(
  SELECT 1 FROM control.mutation_candidate candidate
  JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
   AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
   AND evidence.catalog_operation_id=candidate.catalog_operation_id AND evidence.principal_id<>evidence.checker_principal_id
  JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
   AND receipt.operation_id=candidate.consumed_operation_id AND receipt.terminal_state='COMMITTED'
  WHERE candidate.participant_id=transition.source_participant_id AND candidate.privacy_domain_id=transition.source_privacy_domain_id
   AND candidate.consumed_operation_id=transition.operation_id AND candidate.state='CONSUMED'
   AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||transition.mutation
   AND candidate.resource_id=NEW.participant_id AND candidate.candidate_document->>'participantId'=NEW.participant_id::text
   AND candidate.candidate_document->>'expectedEpoch'=OLD.authority_epoch::text
   AND candidate.expected_revision=OLD.row_version
   AND receipt.result_payload#>>'{result,epoch}'=NEW.authority_epoch::text
 ) INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_participant_lifecycle_transition() OWNER TO openpc_control_owner;

--
-- Name: require_platform_recovery_continuation_enrollment(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_platform_recovery_continuation_enrollment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original_preparation jsonb;
BEGIN
 IF NEW.source_purpose='ROOT_EXPIRY_RECOVERY' AND NEW.document ? 'uneffectedPredecessor' THEN
  SELECT c.intent->'preparation' INTO STRICT original_preparation FROM control.platform_recovery_case c
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.recovery_id::text=NEW.document#>>'{uneffectedPredecessor,recoveryId}'
    AND c.enrollment_id::text=NEW.document#>>'{uneffectedPredecessor,enrollmentId}';
  IF openpc.platform_recovery_uneffected_source_current(NEW.participant_id,NEW.enrollment_id,
    NEW.document->'uneffectedPredecessor',original_preparation) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  RETURN NULL;
 END IF;
 IF NEW.source_purpose NOT IN ('ROOT_EXPIRY_RECOVERY_CONTINUATION','PENDING_ADMINISTRATION_EXPIRY_RECOVERY') THEN RETURN NULL; END IF;
 SELECT c.intent->'preparation' INTO STRICT original_preparation FROM control.platform_recovery_case c
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND c.recovery_id::text=coalesce(NEW.document#>>'{source,continuation,recoveryId}',NEW.document#>>'{source,pendingExpiry,preparation,recoveryId}')
   AND c.enrollment_id::text=coalesce(NEW.document#>>'{source,continuation,enrollmentId}',NEW.document#>>'{source,pendingExpiry,preparation,enrollmentId}');
 IF NEW.source_purpose='PENDING_ADMINISTRATION_EXPIRY_RECOVERY' THEN
  IF NEW.document#>'{source}' ? 'closedApproval' AND
    openpc.platform_recovery_closed_approval_source_current(NEW.participant_id,NEW.enrollment_id,null::uuid) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF openpc.platform_recovery_pending_expiry_source_current(NEW.participant_id,NEW.enrollment_id,
    NEW.document#>'{source,pendingExpiry,preparation}',original_preparation) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  RETURN NULL;
 END IF;
 IF openpc.platform_recovery_continuation_current(NEW.participant_id,NEW.enrollment_id,
    NEW.document#>'{source,continuation}',original_preparation) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NEW.document#>'{source}' ? 'activatedHandoff' AND
  openpc.platform_recovery_completion_admission_current(NEW.participant_id,NEW.enrollment_id) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_platform_recovery_continuation_enrollment() OWNER TO openpc_control_owner;

--
-- Name: require_platform_scope_replacement_provenance(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_platform_scope_replacement_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'control'
    AS $$
DECLARE r control.platform_scope_replacement; phase text; operation uuid; candidate uuid; approval uuid; valid boolean;
BEGIN
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=NEW.replacement_id;
 IF TG_OP='UPDATE' AND NEW.state='SUPERSEDED' THEN
  -- Deferred: both rows and the successor's ordinary PREPARE provenance must
  -- commit together. The old intent, approvals and target evidence stay intact.
  IF NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement successor
    WHERE successor.replacement_id=r.superseded_by AND successor.participant_id=r.participant_id
      AND successor.privacy_domain_id=r.privacy_domain_id AND successor.platform_context_id=r.platform_context_id
      AND ((successor.predecessor_epoch=r.predecessor_epoch AND successor.expected_root_revision=r.expected_root_revision
        AND successor.predecessor_digest=r.predecessor_digest)
        OR openpc.platform_scope_pending_root_bridge_current(r,successor.predecessor_epoch,successor.expected_root_revision,successor.predecessor_digest))
      AND successor.prepare_operation_id=openpc.current_operation_id()
      AND successor.candidate->'supersedes'=jsonb_build_object('replacementId',r.replacement_id::text,
        'expectedRevision','1','successorDigest','sha256:'||encode(r.successor_digest,'hex')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION-PROVENANCE'; END IF;
  RETURN NULL;
 END IF;
 phase:=CASE WHEN TG_OP='INSERT' THEN 'PREPARE' ELSE 'COMMIT' END;
 operation:=CASE WHEN phase='PREPARE' THEN r.prepare_operation_id ELSE r.commit_operation_id END;
 candidate:=CASE WHEN phase='PREPARE' THEN r.prepare_candidate_id ELSE r.commit_candidate_id END;
 approval:=CASE WHEN phase='PREPARE' THEN r.prepare_approval_id ELSE r.commit_approval_id END;
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
    AND a.approval_request_id=approval AND a.subject_type='CONFIGURATION_CANDIDATE'
    AND a.subject_id=c.mutation_candidate_id AND a.subject_digest=c.candidate_digest
    AND a.subject_version=c.expected_revision AND a.state='APPROVED'
  JOIN control.mutation_evidence e ON e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND e.operation_id=operation AND e.catalog_operation_id=c.catalog_operation_id
    AND e.aggregate_type='platform-scope-replacement' AND e.aggregate_id=r.replacement_id
    AND e.candidate_digest=c.candidate_digest AND e.approval_request_id=approval
    AND e.principal_id=c.maker_principal_id AND e.checker_principal_id<>e.principal_id
    AND e.mfa_challenge_id IS NOT NULL AND e.webauthn_assertion_binding_digest IS NOT NULL
  JOIN control.idempotency_record receipt ON receipt.participant_id=c.participant_id AND receipt.privacy_domain_id=c.privacy_domain_id
    AND receipt.operation_id=operation AND receipt.terminal_state='COMMITTED'
    AND receipt.result_payload->>'replacementId'=r.replacement_id::text
    AND receipt.result_payload->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
  WHERE c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
    AND c.mutation_candidate_id=candidate AND c.consumed_operation_id=operation AND c.state='CONSUMED'
    AND c.catalog_operation_id='ID-OP-PLATFORM-SCOPE-'||phase AND c.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
    AND c.resource_id=r.replacement_id AND c.expected_revision=CASE WHEN phase='PREPARE' THEN 0 ELSE 1 END
    AND ((phase='PREPARE' AND c.candidate_document=r.candidate AND c.candidate_digest=r.candidate_digest)
      OR (phase='COMMIT' AND c.candidate_document->>'readinessDigest'='sha256:'||encode(r.readiness_digest,'hex')
        AND c.candidate_document->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
        AND c.candidate_document->>'predecessorEpoch'=r.predecessor_epoch::text
        AND c.candidate_document->>'expectedRootRevision'=r.expected_root_revision::text))) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PROVENANCE'; END IF;
 IF phase='PREPARE' AND (
  (SELECT count(*) FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id)<>jsonb_array_length(r.candidate->'affectedTargets')
  OR EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND NOT (r.candidate->'affectedTargets' @> jsonb_build_array(q.source))))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 IF phase='COMMIT' AND NOT EXISTS(SELECT 1 FROM control.platform_context p
    JOIN control.platform_envelope_scope_successor s ON s.platform_context_id=p.platform_context_id
      AND s.platform_authority_epoch=p.authority_epoch AND s.replacement_id=r.replacement_id
    WHERE p.platform_context_id=r.platform_context_id AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE'
      AND p.authority_epoch=r.predecessor_epoch+1 AND p.row_version=r.expected_root_revision+1)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-EFFECT'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_platform_scope_replacement_provenance() OWNER TO openpc_control_owner;

--
-- Name: require_protected_proof_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_protected_proof_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE op uuid; rid uuid; action text; catalog text; aggregate text; document jsonb; expected numeric;
 e control.mutation_evidence; c control.mutation_candidate; original control.mutation_evidence;
BEGIN
 IF TG_TABLE_NAME='protected_proof_object' THEN
  op:=NEW.creation_operation_id;rid:=NEW.object_id;action:='ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1';
  catalog:='CFG-OP-RETAIN-PROTECTED-PROOF';aggregate:='protected-proof';expected:=0;
  document:=jsonb_build_object('source',NEW.source,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'retainUntil',to_char(NEW.retain_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  IF NOT EXISTS(SELECT 1 FROM control.protected_proof_payload WHERE object_id=rid AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSIF TG_OP='INSERT' THEN
  op:=NEW.creation_operation_id;rid:=NEW.access_id;action:='ACT-PROTECTED_PROOF_ACCESS_CREATE_RESOURCE-V1';
  catalog:='CFG-OP-REQUEST-PROTECTED-ACCESS';aggregate:='protected-proof-access';expected:=0;
  document:=jsonb_build_object('object',NEW.object_binding,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'recipientPrincipalId',NEW.recipient_principal_id::text,'expiresAt',to_char(NEW.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 ELSE
  op:=NEW.consumption_operation_id;rid:=NEW.access_id;action:='ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1';
  catalog:='CFG-OP-CONSUME-PROTECTED-ACCESS';aggregate:='protected-proof-access';expected:=1;document:=NEW.consumption_request;
 END IF;
 SELECT proof.* INTO e FROM control.mutation_evidence proof JOIN control.idempotency_record i
  ON i.participant_id=proof.participant_id AND i.privacy_domain_id=proof.privacy_domain_id AND i.operation_id=proof.operation_id
   AND i.principal_id=proof.principal_id AND i.action_intent_id=proof.action_intent_id AND i.catalog_operation_id=proof.catalog_operation_id
   AND i.input_digest=proof.candidate_digest AND i.terminal_state='COMMITTED' AND i.expected_aggregate_version=expected
   AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||rid::text
  WHERE proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id
   AND proof.operation_id=op AND proof.action_intent_id=action AND proof.catalog_operation_id=catalog
   AND proof.aggregate_type=aggregate AND proof.aggregate_id=rid;
 IF e.operation_id IS NULL OR NOT EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=e.participant_id
  AND event.privacy_domain_id=e.privacy_domain_id AND event.aggregate_type=aggregate AND event.aggregate_id=rid
  AND event.event_type=CASE catalog WHEN 'CFG-OP-RETAIN-PROTECTED-PROOF' THEN 'openpc.evidence.protected.retained.v1'
   WHEN 'CFG-OP-REQUEST-PROTECTED-ACCESS' THEN 'openpc.evidence.protected.access-requested.v1' ELSE 'openpc.evidence.protected.consumed.v1' END
  AND event.payload_digest=sha256(event.payload_cbor)
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF expected=0 THEN
  SELECT candidate.* INTO c FROM control.mutation_candidate candidate JOIN control.approval_request a
   ON a.participant_id=candidate.participant_id AND a.privacy_domain_id=candidate.privacy_domain_id
    AND a.subject_id=candidate.mutation_candidate_id AND a.approval_request_id=e.approval_request_id
   WHERE candidate.participant_id=e.participant_id AND candidate.privacy_domain_id=e.privacy_domain_id
    AND candidate.consumed_operation_id=op AND candidate.state='CONSUMED' AND candidate.candidate_digest=e.candidate_digest
    AND candidate.action_intent_id=action AND candidate.catalog_operation_id=catalog AND candidate.resource_id=rid
    AND candidate.maker_principal_id=e.principal_id AND candidate.expected_revision=0;
  IF c.mutation_candidate_id IS NULL OR e.checker_principal_id IS NULL OR e.checker_principal_id=e.principal_id
   OR NEW.approval_request_id IS DISTINCT FROM e.approval_request_id
   OR c.candidate_document-ARRAY['participantId','actionIntentId','actionIntentDigest','reason'] IS DISTINCT FROM document
   OR NOT EXISTS(SELECT 1 FROM control.mfa_challenge m WHERE m.participant_id=e.participant_id AND m.mfa_challenge_id=e.mfa_challenge_id
    AND m.principal_id=e.principal_id AND m.used_operation_id=op AND m.action_intent_id=action AND m.resource_digest=e.candidate_digest
    AND m.consumed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 ELSE
  IF e.candidate_digest<>sha256(convert_to(openpc.signing_canonical_json(document),'UTF8')) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO original FROM control.mutation_evidence WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.creation_operation_id;
  IF original.operation_id IS NULL OR (original.principal_id,original.bound_participant_epoch,original.bound_principal_epoch,
    original.bound_authority_envelope_id,original.bound_envelope_epoch,original.bound_assignment_id) IS DISTINCT FROM
   (e.principal_id,e.bound_participant_epoch,e.bound_principal_epoch,e.bound_authority_envelope_id,e.bound_envelope_epoch,e.bound_assignment_id)
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 IF TG_TABLE_NAME='protected_proof_access' THEN
  IF NEW.recipient_principal_id<>e.principal_id OR NOT EXISTS(SELECT 1 FROM control.session s
   WHERE s.participant_id=NEW.participant_id AND s.session_id=NEW.sender_session_id AND s.principal_id=e.principal_id
    AND s.privacy_domain_id=NEW.privacy_domain_id AND s.state='ACTIVE' AND s.absolute_expires_at>clock_timestamp()
    AND s.idle_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  IF expected=0 AND NOT EXISTS(SELECT 1 FROM control.mfa_challenge m WHERE m.participant_id=e.participant_id
   AND m.mfa_challenge_id=e.mfa_challenge_id AND m.session_id=NEW.sender_session_id) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_protected_proof_command() OWNER TO openpc_control_owner;

--
-- Name: require_provider_retry_evidence(text, uuid, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_provider_retry_evidence(p_environment text, p_generation uuid, p_input text, p_receipt text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF to_regprocedure('openpc.operations_provider_retry_evidence_current(text,uuid,text,text)') IS NULL
 THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_EVIDENCE_OWNER_UNBOUND'; END IF;
 EXECUTE 'select openpc.operations_provider_retry_evidence_current($1,$2,$3,$4)' INTO result USING p_environment,p_generation,p_input,p_receipt;
 IF result IS NULL OR jsonb_typeof(result)<>'object' OR NOT result ?& ARRAY['input','receiptDocument'] OR (SELECT count(*) FROM jsonb_object_keys(result))<>2
 THEN RAISE EXCEPTION 'OPS_PROVIDER_RETRY_UNQUALIFIED'; END IF;
 RETURN result;
END $_$;


ALTER FUNCTION openpc.require_provider_retry_evidence(p_environment text, p_generation uuid, p_input text, p_receipt text) OWNER TO openpc_control_owner;

--
-- Name: require_retention_policy_command(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.require_retention_policy_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE operation uuid; approval uuid; catalog text; action text; expected numeric;
BEGIN
 IF TG_OP='INSERT' THEN
  operation:=NEW.activation_operation_id;approval:=NEW.approval_request_id;catalog:='CFG-OP-ACTIVATE-RETENTION-POLICY';
  action:='ACT-RETENTION_POLICIES_CREATE_RESOURCE-V1';expected:=0;
 ELSE
  operation:=NEW.retirement_operation_id;approval:=NEW.retirement_approval_request_id;catalog:='CFG-OP-RETIRE-RETENTION-POLICY';
  action:='ACT-RETENTION_POLICIES_RETIRE_RESOURCE-V1';expected:=1;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence e JOIN control.mutation_candidate c
  ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
   AND c.resource_id=e.aggregate_id AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.audit_occurrence receipt ON receipt.participant_id=e.participant_id AND receipt.privacy_domain_id=e.privacy_domain_id
   AND receipt.operation_id=e.operation_id AND receipt.aggregate_id=e.aggregate_id AND receipt.aggregate_type='retention-policy'
  WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=operation
   AND e.approval_request_id=approval AND e.aggregate_type='retention-policy' AND e.aggregate_id=NEW.retention_policy_id
   AND e.catalog_operation_id=catalog AND e.action_intent_id=action
   AND c.catalog_operation_id=catalog AND c.action_intent_id=action AND c.state='CONSUMED' AND c.expected_revision=expected
   AND (TG_OP<>'INSERT' OR (c.candidate_document->'policy'=openpc.retention_policy_definition(NEW)
    AND c.candidate_document->'predecessorPolicyId'=coalesce(to_jsonb('urn:openpc:resource:'||NEW.predecessor_policy_id::text),'null'::jsonb)))
   AND receipt.catalog_operation_id=catalog AND receipt.action_intent_id=action
   AND receipt.before_existence=CASE WHEN TG_OP='INSERT' THEN 0 ELSE 1 END
   AND receipt.before_revision=expected AND receipt.after_existence=1 AND receipt.after_revision=NEW.revision
   AND openpc.business_cbor(receipt.before_state_preimage)->8=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE openpc.retention_policy_state_projection(OLD) END
   AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.retention_policy_state_projection(NEW)
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=receipt.participant_id
    AND event.privacy_domain_id=receipt.privacy_domain_id AND event.receipt_id=receipt.receipt_id
    AND event.aggregate_type=receipt.aggregate_type AND event.aggregate_id=receipt.aggregate_id
    AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
    AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND event.payload_digest=sha256(event.payload_cbor)))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-RETENTION-SIGNED-TRANSITION'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.require_retention_policy_command() OWNER TO openpc_control_owner;

