--
-- Name: runtime_artifact_retirement_digest(control.runtime_artifact_retirement); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_retirement_digest(r control.runtime_artifact_retirement) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.runtime-artifact-retirement.v1','deletionJobId',(r).deletion_job_id::text,'source',jsonb_build_object('participantId',(r).participant_id::text,
 'privacyDomainId',(r).privacy_domain_id::text,'runtimeConfigurationInputId',(r).runtime_configuration_input_id::text,
 'moduleInstallationId',(r).module_installation_id::text,'moduleConfigurationGenerationId',(r).module_configuration_generation_id::text,
 'configurationDigest',(r).configuration_digest,'configurationBytes',(r).configuration_bytes,
 'resourceBindingsDigest',(r).resource_bindings_digest,
 'createdAt',to_char((r).source_created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))),'UTF8')),'hex')
$$;


ALTER FUNCTION openpc.runtime_artifact_retirement_digest(r control.runtime_artifact_retirement) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_retirement_input_identity(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_retirement_input_identity(input_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source record; info jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT participant_id,privacy_domain_id,runtime_configuration_input_id,module_installation_id,
  module_configuration_generation_id,configuration_digest,resource_bindings,created_at INTO STRICT source
  FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 info:=openpc.runtime_artifact_input_information(input_id);
 IF info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 RETURN jsonb_build_object('participantId',source.participant_id::text,'privacyDomainId',source.privacy_domain_id::text,
  'runtimeConfigurationInputId',input_id::text,'moduleInstallationId',source.module_installation_id::text,
  'moduleConfigurationGenerationId',source.module_configuration_generation_id::text,
  'configurationDigest','sha256:'||encode(source.configuration_digest,'hex'),'configurationBytes',(info->>'byteLength')::integer,
  'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(source.resource_bindings),'UTF8')),'hex'),
  'createdAt',to_char(source.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $$;


ALTER FUNCTION openpc.runtime_artifact_retirement_input_identity(input_id uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_retirement_plan(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_retirement_plan(policy_id uuid, previous_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selection jsonb; blocker text; next_job uuid; prior control.deletion_job; retired control.runtime_artifact_retirement;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF previous_id IS NOT NULL THEN
  SELECT * INTO STRICT prior FROM control.deletion_job WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND deletion_job_id=previous_id AND target_data_class='RUNTIME_ARTIFACT';
  SELECT * INTO STRICT retired FROM control.runtime_artifact_retirement WHERE participant_id=prior.participant_id
   AND privacy_domain_id=prior.privacy_domain_id AND deletion_job_id=prior.deletion_job_id;
  PERFORM openpc.assert_runtime_artifact_retirement_committed(retired);
  SELECT deletion_job_id INTO next_job FROM control.deletion_job WHERE participant_id=prior.participant_id
   AND privacy_domain_id=prior.privacy_domain_id AND previous_deletion_job_id=previous_id;
  IF next_job IS NOT NULL OR prior.selection->'nextInput'='null'::jsonb THEN
   RETURN jsonb_build_object('selection',null,'beforeDigest',null,'eligible',false,'blockers','[]'::jsonb,
    'continuationState',CASE WHEN next_job IS NULL THEN 'COMPLETE' ELSE 'ADVANCED' END,
    'nextDeletionJobId',CASE WHEN next_job IS NULL THEN NULL ELSE 'urn:openpc:resource:'||next_job::text END,'authority','NONE');
  END IF;
 END IF;
 BEGIN
  selection:=openpc.runtime_artifact_retirement_selection(policy_id,previous_id);
 EXCEPTION WHEN no_data_found THEN blocker:='STALE_SELECTION';
 WHEN raise_exception THEN
  blocker:=regexp_replace(SQLERRM,'^RUNTIME-(DISPOSITION|RETIREMENT)-','');
  blocker:=CASE blocker WHEN 'INCOMPLETE_REFERENCES' THEN 'INCOMPLETE_REFERENCE_COVERAGE'
    WHEN 'SOURCE_UNPROVEN' THEN 'SOURCE_REDELIVERY_UNPROVEN' WHEN 'ARCHIVE_UNPROVEN' THEN 'RUNTIME_CUSTODY_UNPROVEN' ELSE blocker END;
  IF blocker NOT IN ('STALE_SELECTION','SELECTED_INPUT','REFERENCES','ACTIVE_HOLD','SINK_QUORUM','RETENTION_NOT_ELAPSED',
   'INCOMPLETE_REFERENCE_COVERAGE','SOURCE_REDELIVERY_UNPROVEN','RUNTIME_CUSTODY_UNPROVEN','GOVERNED_DISPOSITION_REQUIRED','ALREADY_DELETED') THEN RAISE; END IF;
 END;
 RETURN jsonb_build_object('selection',selection,'beforeDigest',CASE WHEN selection IS NULL THEN NULL
  ELSE openpc.runtime_artifact_retirement_before(selection->'source') END,'eligible',selection IS NOT NULL,
  'blockers',CASE WHEN blocker IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(blocker) END,
  'continuationState',CASE WHEN selection IS NULL THEN 'BLOCKED' ELSE 'READY' END,'nextDeletionJobId',null,'authority','NONE');
END $$;


ALTER FUNCTION openpc.runtime_artifact_retirement_plan(policy_id uuid, previous_id uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_retirement_selection(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_retirement_selection(policy_id uuid, previous_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 prior control.deletion_job; retired control.runtime_artifact_retirement; admission control.runtime_artifact_source_disposition;
 denied control.runtime_artifact_source_denial; receipt control.audit_occurrence;
 input_id uuid; next_id uuid; selected jsonb; source jsonb; next_source jsonb; successor jsonb:='null'::jsonb;
 cursor jsonb:='null'::jsonb; expected jsonb; root_digest text;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF openpc.current_action_intent_id() NOT IN ('ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF previous_id IS NOT NULL THEN
  SELECT * INTO STRICT prior FROM control.deletion_job WHERE participant_id=p AND privacy_domain_id=d
   AND deletion_job_id=previous_id AND target_data_class='RUNTIME_ARTIFACT' AND state='SUCCEEDED' AND revision=1;
  SELECT * INTO STRICT retired FROM control.runtime_artifact_retirement WHERE participant_id=p AND privacy_domain_id=d AND deletion_job_id=previous_id;
  PERFORM openpc.assert_runtime_artifact_retirement_committed(retired);
  IF EXISTS(SELECT 1 FROM control.deletion_job WHERE participant_id=p AND privacy_domain_id=d AND previous_deletion_job_id=previous_id
    AND operation_id IS DISTINCT FROM openpc.current_operation_id())
   OR prior.selection->'nextInput'='null'::jsonb THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
  expected:=prior.selection->'nextInput'; input_id:=(expected->>'runtimeConfigurationInputId')::uuid;
  SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=p AND privacy_domain_id=d
   AND operation_id=prior.operation_id AND aggregate_id=previous_id AND aggregate_type='evidence-deletion';
  cursor:=jsonb_build_object('deletionJobId','urn:openpc:resource:'||previous_id::text,
   'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'));
 ELSE
  -- A committed predecessor with a promised successor cannot be bypassed by
  -- opening another chain or changing only the request key.
  IF EXISTS(SELECT 1 FROM control.deletion_job j WHERE j.participant_id=p AND j.privacy_domain_id=d
    AND j.target_data_class='RUNTIME_ARTIFACT' AND j.state='SUCCEEDED' AND j.selection->'nextInput'<>'null'::jsonb
    AND NOT EXISTS(SELECT 1 FROM control.deletion_job n WHERE n.participant_id=p AND n.privacy_domain_id=d AND n.previous_deletion_job_id=j.deletion_job_id))
   THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
  SELECT runtime_configuration_input_id INTO input_id FROM control.runtime_configuration_input
   WHERE participant_id=p AND privacy_domain_id=d ORDER BY runtime_configuration_input_id LIMIT 1;
 END IF;
 IF input_id IS NULL THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-ALREADY_DELETED'; END IF;
 IF input_id IS DISTINCT FROM (SELECT runtime_configuration_input_id FROM control.runtime_configuration_input
  WHERE participant_id=p AND privacy_domain_id=d ORDER BY runtime_configuration_input_id LIMIT 1)
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
 source:=openpc.runtime_artifact_retirement_input_identity(input_id);
 IF expected IS NOT NULL AND expected IS DISTINCT FROM jsonb_build_object('runtimeConfigurationInputId',input_id::text,
  'configurationDigest',source->>'configurationDigest','beforeDigest',openpc.runtime_artifact_retirement_before(source))
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
 SELECT * INTO admission FROM control.runtime_artifact_source_disposition WHERE participant_id=p AND privacy_domain_id=d
  AND runtime_configuration_input_id=input_id AND configuration_digest=decode(substring(source->>'configurationDigest' from 8),'hex');
 IF NOT FOUND THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-GOVERNED_DISPOSITION_REQUIRED'; END IF;
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(admission);
 SELECT * INTO denied FROM control.runtime_artifact_source_denial WHERE participant_id=p AND privacy_domain_id=d
  AND disposition_id=admission.disposition_id AND source_owner_id=admission.source_owner_id;
 IF NOT FOUND OR denied.denial_digest IS DISTINCT FROM sha256(denied.signed_denial)
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-RUNTIME_CUSTODY_UNPROVEN'; END IF;
 selected:=openpc.runtime_artifact_source_observation(input_id,policy_id);
 root_digest:=selected->>'sourceRootDigest';
 IF selected->>'sourceOwnerId' IS DISTINCT FROM admission.source_owner_id::text
  OR root_digest IS DISTINCT FROM admission.selection->>'sourceRootDigest'
  OR selected->'observation'->'source' IS DISTINCT FROM source
  OR selected->>'archivePendingDigest' IS DISTINCT FROM admission.selection->>'archivePendingDigest'
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-RUNTIME_CUSTODY_UNPROVEN'; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=p AND privacy_domain_id=d
  AND operation_id=admission.operation_id AND aggregate_id=admission.disposition_id AND aggregate_type='runtime-artifact-disposition';
 SELECT runtime_configuration_input_id INTO next_id FROM control.runtime_configuration_input
  WHERE participant_id=p AND privacy_domain_id=d AND runtime_configuration_input_id>input_id ORDER BY runtime_configuration_input_id LIMIT 1;
 IF next_id IS NOT NULL THEN
  next_source:=openpc.runtime_artifact_retirement_input_identity(next_id);
  successor:=jsonb_build_object('runtimeConfigurationInputId',next_id::text,'configurationDigest',next_source->>'configurationDigest',
   'beforeDigest',openpc.runtime_artifact_retirement_before(next_source));
 END IF;
 RETURN selected->'observation'||jsonb_build_object('priorCursor',cursor,'nextInput',successor,'disposition',jsonb_build_object(
  'dispositionId',admission.disposition_id::text,'operationId',admission.operation_id::text,
  'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'),'nativeDenialDigest','sha256:'||encode(denied.denial_digest,'hex'),
  'sourceOwnerId',admission.source_owner_id::text,'sourceRootDigest',root_digest));
END $$;


ALTER FUNCTION openpc.runtime_artifact_retirement_selection(policy_id uuid, previous_id uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_retirement_source(control.runtime_artifact_retirement); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_retirement_source(r control.runtime_artifact_retirement) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('participantId',(r).participant_id::text,
 'privacyDomainId',(r).privacy_domain_id::text,'runtimeConfigurationInputId',(r).runtime_configuration_input_id::text,
 'moduleInstallationId',(r).module_installation_id::text,'moduleConfigurationGenerationId',(r).module_configuration_generation_id::text,
 'configurationDigest',(r).configuration_digest,'configurationBytes',(r).configuration_bytes,
 'resourceBindingsDigest',(r).resource_bindings_digest,
 'createdAt',to_char((r).source_created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
$$;


ALTER FUNCTION openpc.runtime_artifact_retirement_source(r control.runtime_artifact_retirement) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_admission(control.runtime_artifact_source_disposition); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_source_admission(a control.runtime_artifact_source_disposition) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s control.runtime_artifact_source; receipt control.audit_occurrence;
BEGIN
 -- This assertion belongs to the governed mutation owner. Missing registration,
 -- grants or admission validation is an error, never an empty custody inventory.
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(a);
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND source_owner_id=a.source_owner_id;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id AND aggregate_id=a.disposition_id
  AND aggregate_type='runtime-artifact-disposition' AND profile_id='pc.control.runtime-artifact.disposition'
  AND catalog_operation_id='CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE';
 RETURN jsonb_build_object('installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'disposition_id',a.disposition_id::text,
  'operation_id',a.operation_id::text,'input_id',a.runtime_configuration_input_id::text,
  'configuration_digest',encode(a.configuration_digest,'hex'),
  'admission_receipt_digest',encode(receipt.receipt_digest,'hex'),'selection_digest',encode(a.selection_digest,'hex'));
END $$;


ALTER FUNCTION openpc.runtime_artifact_source_admission(a control.runtime_artifact_source_disposition) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_denial_claims_bytes(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_source_denial_claims_bytes(value jsonb) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT convert_to((CASE WHEN jsonb_typeof(value)='object' AND (value) ?& ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]
    AND (value)-ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]='{}'::jsonb THEN '{'||'"version":'||(CASE WHEN jsonb_typeof((value->'version'))='number' AND ((value->'version'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND ((value->'version'))::numeric BETWEEN 0 AND 18446744073709551615 THEN ((value->'version'))::text END)||','||'"admission":'||(CASE WHEN jsonb_typeof((value->'admission'))='object' AND ((value->'admission')) ?& ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]
    AND ((value->'admission'))-ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]='{}'::jsonb THEN '{'||'"installation":'||(CASE WHEN jsonb_typeof(((value->'admission')->'installation'))='object' AND (((value->'admission')->'installation')) ?& ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]
    AND (((value->'admission')->'installation'))-ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]='{}'::jsonb THEN '{'||'"participant_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'participant_id'))='string' THEN ((((value->'admission')->'installation')->'participant_id'))::text END)||','||'"privacy_domain_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'privacy_domain_id'))='string' THEN ((((value->'admission')->'installation')->'privacy_domain_id'))::text END)||','||'"source_owner_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'source_owner_id'))='string' THEN ((((value->'admission')->'installation')->'source_owner_id'))::text END)||','||'"source_file_binding":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'source_file_binding'))='string' THEN ((((value->'admission')->'installation')->'source_file_binding'))::text END)||'}' END)||','||'"disposition_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'disposition_id'))='string' THEN (((value->'admission')->'disposition_id'))::text END)||','||'"operation_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'operation_id'))='string' THEN (((value->'admission')->'operation_id'))::text END)||','||'"input_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'input_id'))='string' THEN (((value->'admission')->'input_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'configuration_digest'))='string' THEN (((value->'admission')->'configuration_digest'))::text END)||','||'"admission_receipt_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'admission_receipt_digest'))='string' THEN (((value->'admission')->'admission_receipt_digest'))::text END)||','||'"selection_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'selection_digest'))='string' THEN (((value->'admission')->'selection_digest'))::text END)||'}' END)||','||'"sequence":'||(CASE WHEN jsonb_typeof((value->'sequence'))='number' AND ((value->'sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND ((value->'sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN ((value->'sequence'))::text END)||','||'"previous_denial_digest":'||(CASE WHEN (value->'previous_denial_digest')='null'::jsonb THEN 'null' ELSE (CASE WHEN jsonb_typeof((value->'previous_denial_digest'))='string' THEN ((value->'previous_denial_digest'))::text END) END)||','||'"recovery":'||(CASE WHEN jsonb_typeof((value->'recovery'))='string' THEN ((value->'recovery'))::text END)||','||'"custody":'||(CASE WHEN jsonb_typeof((value->'custody'))='object' AND ((value->'custody')) ?& ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]
    AND ((value->'custody'))-ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]='{}'::jsonb THEN '{'||'"profile":'||(CASE WHEN jsonb_typeof(((value->'custody')->'profile'))='string' THEN (((value->'custody')->'profile'))::text END)||','||'"binding":'||(CASE WHEN jsonb_typeof(((value->'custody')->'binding'))='object' AND (((value->'custody')->'binding')) ?& ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]
    AND (((value->'custody')->'binding'))-ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]='{}'::jsonb THEN '{'||'"generation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'generation_id'))='string' THEN ((((value->'custody')->'binding')->'generation_id'))::text END)||','||'"journal_binding":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'journal_binding'))='string' THEN ((((value->'custody')->'binding')->'journal_binding'))::text END)||','||'"retained_root_binding":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'retained_root_binding'))='string' THEN ((((value->'custody')->'binding')->'retained_root_binding'))::text END)||','||'"consumer_profile":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'consumer_profile'))='string' THEN ((((value->'custody')->'binding')->'consumer_profile'))::text END)||','||'"database":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'database'))='object' AND ((((value->'custody')->'binding')->'database')) ?& ARRAY['system_identifier','database_oid']::text[]
    AND ((((value->'custody')->'binding')->'database'))-ARRAY['system_identifier','database_oid']::text[]='{}'::jsonb THEN '{'||'"system_identifier":'||(CASE WHEN jsonb_typeof(((((value->'custody')->'binding')->'database')->'system_identifier'))='string' THEN (((((value->'custody')->'binding')->'database')->'system_identifier'))::text END)||','||'"database_oid":'||(CASE WHEN jsonb_typeof(((((value->'custody')->'binding')->'database')->'database_oid'))='string' THEN (((((value->'custody')->'binding')->'database')->'database_oid'))::text END)||'}' END)||'}' END)||','||'"input":'||(CASE WHEN jsonb_typeof(((value->'custody')->'input'))='object' AND (((value->'custody')->'input')) ?& ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]
    AND (((value->'custody')->'input'))-ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]='{}'::jsonb THEN '{'||'"input_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'input_id'))='string' THEN ((((value->'custody')->'input')->'input_id'))::text END)||','||'"module_installation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'module_installation_id'))='string' THEN ((((value->'custody')->'input')->'module_installation_id'))::text END)||','||'"module_configuration_generation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'module_configuration_generation_id'))='string' THEN ((((value->'custody')->'input')->'module_configuration_generation_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'configuration_digest'))='string' THEN ((((value->'custody')->'input')->'configuration_digest'))::text END)||'}' END)||','||'"pending_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'pending_digest'))='string' THEN (((value->'custody')->'pending_digest'))::text END)||','||'"committed_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'committed_digest'))='string' THEN (((value->'custody')->'committed_digest'))::text END)||','||'"history_sequence":'||(CASE WHEN jsonb_typeof(((value->'custody')->'history_sequence'))='number' AND (((value->'custody')->'history_sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND (((value->'custody')->'history_sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN (((value->'custody')->'history_sequence'))::text END)||','||'"history_head_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'history_head_digest'))='string' THEN (((value->'custody')->'history_head_digest'))::text END)||','||'"retained_head_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'retained_head_digest'))='string' THEN (((value->'custody')->'retained_head_digest'))::text END)||','||'"consumers":'||(CASE WHEN jsonb_typeof(((value->'custody')->'consumers'))='array' AND NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements(((value->'custody')->'consumers')) item WHERE jsonb_typeof(item)<>'string')
      THEN openpc.signing_canonical_json(((value->'custody')->'consumers')) END)||'}' END)||'}' END),'UTF8')
$_$;


ALTER FUNCTION openpc.runtime_artifact_source_denial_claims_bytes(value jsonb) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_denial_envelope_bytes(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_source_denial_envelope_bytes(value jsonb) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT convert_to((CASE WHEN jsonb_typeof(value)='object' AND (value) ?& ARRAY['purpose','claims','claims_digest','signature_p1363_hex']::text[]
    AND (value)-ARRAY['purpose','claims','claims_digest','signature_p1363_hex']::text[]='{}'::jsonb THEN '{'||'"purpose":'||(CASE WHEN jsonb_typeof((value->'purpose'))='string' THEN ((value->'purpose'))::text END)||','||'"claims":'||(CASE WHEN jsonb_typeof((value->'claims'))='object' AND ((value->'claims')) ?& ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]
    AND ((value->'claims'))-ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]='{}'::jsonb THEN '{'||'"version":'||(CASE WHEN jsonb_typeof(((value->'claims')->'version'))='number' AND (((value->'claims')->'version'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND (((value->'claims')->'version'))::numeric BETWEEN 0 AND 18446744073709551615 THEN (((value->'claims')->'version'))::text END)||','||'"admission":'||(CASE WHEN jsonb_typeof(((value->'claims')->'admission'))='object' AND (((value->'claims')->'admission')) ?& ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]
    AND (((value->'claims')->'admission'))-ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]='{}'::jsonb THEN '{'||'"installation":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'installation'))='object' AND ((((value->'claims')->'admission')->'installation')) ?& ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]
    AND ((((value->'claims')->'admission')->'installation'))-ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]='{}'::jsonb THEN '{'||'"participant_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'admission')->'installation')->'participant_id'))='string' THEN (((((value->'claims')->'admission')->'installation')->'participant_id'))::text END)||','||'"privacy_domain_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'admission')->'installation')->'privacy_domain_id'))='string' THEN (((((value->'claims')->'admission')->'installation')->'privacy_domain_id'))::text END)||','||'"source_owner_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'admission')->'installation')->'source_owner_id'))='string' THEN (((((value->'claims')->'admission')->'installation')->'source_owner_id'))::text END)||','||'"source_file_binding":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'admission')->'installation')->'source_file_binding'))='string' THEN (((((value->'claims')->'admission')->'installation')->'source_file_binding'))::text END)||'}' END)||','||'"disposition_id":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'disposition_id'))='string' THEN ((((value->'claims')->'admission')->'disposition_id'))::text END)||','||'"operation_id":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'operation_id'))='string' THEN ((((value->'claims')->'admission')->'operation_id'))::text END)||','||'"input_id":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'input_id'))='string' THEN ((((value->'claims')->'admission')->'input_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'configuration_digest'))='string' THEN ((((value->'claims')->'admission')->'configuration_digest'))::text END)||','||'"admission_receipt_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'admission_receipt_digest'))='string' THEN ((((value->'claims')->'admission')->'admission_receipt_digest'))::text END)||','||'"selection_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'admission')->'selection_digest'))='string' THEN ((((value->'claims')->'admission')->'selection_digest'))::text END)||'}' END)||','||'"sequence":'||(CASE WHEN jsonb_typeof(((value->'claims')->'sequence'))='number' AND (((value->'claims')->'sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND (((value->'claims')->'sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN (((value->'claims')->'sequence'))::text END)||','||'"previous_denial_digest":'||(CASE WHEN ((value->'claims')->'previous_denial_digest')='null'::jsonb THEN 'null' ELSE (CASE WHEN jsonb_typeof(((value->'claims')->'previous_denial_digest'))='string' THEN (((value->'claims')->'previous_denial_digest'))::text END) END)||','||'"recovery":'||(CASE WHEN jsonb_typeof(((value->'claims')->'recovery'))='string' THEN (((value->'claims')->'recovery'))::text END)||','||'"custody":'||(CASE WHEN jsonb_typeof(((value->'claims')->'custody'))='object' AND (((value->'claims')->'custody')) ?& ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]
    AND (((value->'claims')->'custody'))-ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]='{}'::jsonb THEN '{'||'"profile":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'profile'))='string' THEN ((((value->'claims')->'custody')->'profile'))::text END)||','||'"binding":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'binding'))='object' AND ((((value->'claims')->'custody')->'binding')) ?& ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]
    AND ((((value->'claims')->'custody')->'binding'))-ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]='{}'::jsonb THEN '{'||'"generation_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'binding')->'generation_id'))='string' THEN (((((value->'claims')->'custody')->'binding')->'generation_id'))::text END)||','||'"journal_binding":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'binding')->'journal_binding'))='string' THEN (((((value->'claims')->'custody')->'binding')->'journal_binding'))::text END)||','||'"retained_root_binding":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'binding')->'retained_root_binding'))='string' THEN (((((value->'claims')->'custody')->'binding')->'retained_root_binding'))::text END)||','||'"consumer_profile":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'binding')->'consumer_profile'))='string' THEN (((((value->'claims')->'custody')->'binding')->'consumer_profile'))::text END)||','||'"database":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'binding')->'database'))='object' AND (((((value->'claims')->'custody')->'binding')->'database')) ?& ARRAY['system_identifier','database_oid']::text[]
    AND (((((value->'claims')->'custody')->'binding')->'database'))-ARRAY['system_identifier','database_oid']::text[]='{}'::jsonb THEN '{'||'"system_identifier":'||(CASE WHEN jsonb_typeof((((((value->'claims')->'custody')->'binding')->'database')->'system_identifier'))='string' THEN ((((((value->'claims')->'custody')->'binding')->'database')->'system_identifier'))::text END)||','||'"database_oid":'||(CASE WHEN jsonb_typeof((((((value->'claims')->'custody')->'binding')->'database')->'database_oid'))='string' THEN ((((((value->'claims')->'custody')->'binding')->'database')->'database_oid'))::text END)||'}' END)||'}' END)||','||'"input":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'input'))='object' AND ((((value->'claims')->'custody')->'input')) ?& ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]
    AND ((((value->'claims')->'custody')->'input'))-ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]='{}'::jsonb THEN '{'||'"input_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'input')->'input_id'))='string' THEN (((((value->'claims')->'custody')->'input')->'input_id'))::text END)||','||'"module_installation_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'input')->'module_installation_id'))='string' THEN (((((value->'claims')->'custody')->'input')->'module_installation_id'))::text END)||','||'"module_configuration_generation_id":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'input')->'module_configuration_generation_id'))='string' THEN (((((value->'claims')->'custody')->'input')->'module_configuration_generation_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof(((((value->'claims')->'custody')->'input')->'configuration_digest'))='string' THEN (((((value->'claims')->'custody')->'input')->'configuration_digest'))::text END)||'}' END)||','||'"pending_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'pending_digest'))='string' THEN ((((value->'claims')->'custody')->'pending_digest'))::text END)||','||'"committed_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'committed_digest'))='string' THEN ((((value->'claims')->'custody')->'committed_digest'))::text END)||','||'"history_sequence":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'history_sequence'))='number' AND ((((value->'claims')->'custody')->'history_sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND ((((value->'claims')->'custody')->'history_sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN ((((value->'claims')->'custody')->'history_sequence'))::text END)||','||'"history_head_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'history_head_digest'))='string' THEN ((((value->'claims')->'custody')->'history_head_digest'))::text END)||','||'"retained_head_digest":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'retained_head_digest'))='string' THEN ((((value->'claims')->'custody')->'retained_head_digest'))::text END)||','||'"consumers":'||(CASE WHEN jsonb_typeof((((value->'claims')->'custody')->'consumers'))='array' AND NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements((((value->'claims')->'custody')->'consumers')) item WHERE jsonb_typeof(item)<>'string')
      THEN openpc.signing_canonical_json((((value->'claims')->'custody')->'consumers')) END)||'}' END)||'}' END)||','||'"claims_digest":'||(CASE WHEN jsonb_typeof((value->'claims_digest'))='string' THEN ((value->'claims_digest'))::text END)||','||'"signature_p1363_hex":'||(CASE WHEN jsonb_typeof((value->'signature_p1363_hex'))='string' THEN ((value->'signature_p1363_hex'))::text END)||'}' END),'UTF8')
$_$;


ALTER FUNCTION openpc.runtime_artifact_source_denial_envelope_bytes(value jsonb) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_key_installed(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_source_key_installed(source_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.runtime_artifact_source_verifier_key k JOIN control.runtime_artifact_source s
  USING(participant_id,privacy_domain_id,source_owner_id) WHERE k.participant_id=openpc.current_participant_id()
  AND k.privacy_domain_id=openpc.current_privacy_domain_id() AND k.source_owner_id=source_id AND s.database_role=session_user)
$$;


ALTER FUNCTION openpc.runtime_artifact_source_key_installed(source_id uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_artifact_source_observation(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_artifact_source_observation(input_id uuid, policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s control.runtime_artifact_source; a control.evidence_runtime_artifact_archive; rule control.retention_policy;
 input record; part record; observed jsonb; segments jsonb:='[]'::jsonb; sinks jsonb; ack_micros numeric;
 eligible numeric; p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin' OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.lock_runtime_artifact_disposition();
 s:=openpc.runtime_artifact_materialization_source();
 IF s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2' OR s.archive_custody IS NULL
  THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SOURCE_UNPROVEN'; END IF;
 PERFORM openpc.assert_runtime_artifact_materialization_boundary();
 SELECT runtime_configuration_input_id,module_installation_id,module_configuration_generation_id,configuration_digest,resource_bindings,selected,created_at,
  openpc.runtime_artifact_input_information(runtime_configuration_input_id) info INTO STRICT input
  FROM control.runtime_configuration_input WHERE participant_id=p AND privacy_domain_id=d AND runtime_configuration_input_id=input_id;
 IF input.selected OR input.info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SELECTED_INPUT'; END IF;
 observed:=openpc.observe_runtime_artifact_references(input_id,'sha256:'||encode(input.configuration_digest,'hex'));
 PERFORM openpc.assert_runtime_artifact_unused_references(observed,input_id);
 SELECT * INTO STRICT a FROM control.evidence_runtime_artifact_archive WHERE participant_id=p AND privacy_domain_id=d
  AND runtime_configuration_input_id=input_id AND stream_id=s.archive_custody->>'stream_id';
 IF a.source_pending_original IS NULL OR a.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex')
  OR a.manifest->'identity' IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
   'runtimeConfigurationInputId',input_id::text,'moduleInstallationId',input.module_installation_id::text,
   'moduleConfigurationGenerationId',input.module_configuration_generation_id::text,'configurationDigest','sha256:'||encode(input.configuration_digest,'hex'),
   'configurationBytes',(input.info->>'byteLength')::integer,'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(input.resource_bindings),'UTF8')),'hex'),
   'createdAt',to_char(input.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
  OR (SELECT count(*) FROM control.evidence_runtime_artifact_archive_part entry
   JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
   JOIN control.evidence_segment seg USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE entry.participant_id=p AND entry.privacy_domain_id=d AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id
    AND entry.ordinal BETWEEN 0 AND jsonb_array_length(a.manifest->'chunks')
    AND entry.record_id=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks') THEN a.record_id
     ELSE a.manifest->'chunks'->entry.ordinal->>'recordId' END
    AND c.receipt_digest=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks') THEN a.manifest_digest
     ELSE a.manifest->'chunks'->entry.ordinal->>'digest' END
    AND c.evidence_class='EFFECT' AND c.source_format=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks')
     THEN 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1' ELSE 'OPENPC_RUNTIME_ARTIFACT_CHUNK_V1' END
    AND c.occurred_at=input.created_at AND c.sequence BETWEEN seg.first_sequence AND seg.through_sequence) IS DISTINCT FROM jsonb_array_length(a.manifest->'chunks')+1
  OR openpc.runtime_artifact_archive_payloads_match(input_id) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d AND retention_policy_id=policy_id
  AND data_class='RUNTIME_ARTIFACT' AND deletion_mode='ROW_DELETE' AND active_until IS NULL;
 eligible:=floor(extract(epoch from input.created_at)*1000000)+rule.retention_period_ms*1000;
 FOR part IN SELECT DISTINCT seg.segment_id,seg.object_digest,seg.first_sequence,seg.through_sequence,seg.admitted_at
  FROM control.evidence_runtime_artifact_archive_part entry JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment seg USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE entry.participant_id=p AND entry.privacy_domain_id=d AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id
  ORDER BY seg.first_sequence LOOP
  IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=p AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=d)
   AND h.state='ACTIVE' AND openpc.evidence_hold_matches(h.selector,p,d,a.stream_id,part.segment_id))
   THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ACTIVE_HOLD'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',ack.sink_id,'checkpointDigest',ack.checkpoint_digest,
    'receiptDigest',ack.receipt_digest,'acknowledgedAtMicros',ack.micros::text) ORDER BY ack.micros,ack.sink_id),'[]'::jsonb),max(ack.micros)
   INTO sinks,ack_micros FROM (SELECT c.sink_id,c.checkpoint_digest,c.receipt_digest,floor(extract(epoch from c.acknowledged_at)*1000000) micros
    FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.stream_id=a.stream_id
     AND c.segment_id=part.segment_id AND c.object_digest=part.object_digest AND c.through_sequence=part.through_sequence
     AND c.receipt->>'receiptDigest'=c.receipt_digest
     AND ((NOT c.receipt ? 'kind' AND c.receipt->>'assurance'='LOCAL_FSYNC_READBACK'
       AND c.receipt->'object'->>'objectDigest'=part.object_digest
       AND c.receipt_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(c.receipt-'receiptDigest'),'UTF8')),'hex'))
      OR (c.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1'
       AND openpc.remote_archive_covers(p,d,a.stream_id,part.segment_id,c.sink_id)))
    ORDER BY c.acknowledged_at,c.sink_id LIMIT greatest(1,rule.sink_quorum)) ack;
  IF jsonb_array_length(sinks)<>greatest(1,rule.sink_quorum) THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SINK_QUORUM'; END IF;
  eligible:=greatest(eligible,ack_micros+rule.local_grace_ms*1000);
  segments:=segments||jsonb_build_array(jsonb_build_object('segmentId',part.segment_id::text,'objectDigest',part.object_digest,
   'firstSequence',part.first_sequence::text,'throughSequence',part.through_sequence::text,'sinkReceipts',sinks));
 END LOOP;
 IF jsonb_array_length(segments) NOT BETWEEN 1 AND 65 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 IF eligible>floor(extract(epoch from clock_timestamp())*1000000) THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-RETENTION_NOT_ELAPSED'; END IF;
 RETURN jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_SOURCE_DISPOSITION_V1','sourceOwnerId',s.source_owner_id::text,
  'sourceRootDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(s.custody_root),'UTF8')),'hex'),
  'archivePendingDigest','sha256:'||encode(sha256(a.source_pending_original),'hex'),
  'observation',jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1','participantId','urn:openpc:participant:'||p::text,
   'privacyDomainId',d::text,'retentionPolicyId','urn:openpc:resource:'||policy_id::text,'policyDigest',rule.policy_digest,
   'targetDatabase','openpc_control','dataClass','RUNTIME_ARTIFACT','deletionMode','ROW_DELETE','source',a.manifest->'identity',
   'streamId',a.stream_id,'manifestRecordId',a.record_id,'manifestDigest',a.manifest_digest,'archiveSegments',segments,
   'referenceObservationDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(observed),'UTF8')),'hex'),
   'eligibleAfterMicros',eligible::text,'priorCursor',null));
END $$;


ALTER FUNCTION openpc.runtime_artifact_source_observation(input_id uuid, policy_id uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_configuration_bindings_current(uuid, uuid, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_configuration_bindings_current(p_participant uuid, p_privacy uuid, p_bindings jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'control', 'openpc'
    AS $$
 SELECT openpc.matches_participant(p_participant) AND openpc.matches_privacy(p_privacy)
   AND jsonb_typeof(p_bindings)='array' AND jsonb_array_length(p_bindings)>0
   AND NOT EXISTS (
     SELECT 1 FROM jsonb_array_elements(p_bindings) binding
     WHERE CASE binding->>'kind'
       WHEN 'ProviderProfile' THEN NOT EXISTS (
         SELECT 1 FROM control.provider_profile p WHERE p.participant_id=p_participant
           AND p.privacy_domain_id=p_privacy AND p.provider_profile_id::text=binding->>'id'
           AND p.behavior_fingerprint=binding->>'digest' AND p.chain_id=binding->>'chainId' AND p.state<>'RETIRED')
       WHEN 'ClientIndexerProfile' THEN NOT EXISTS (
         SELECT 1 FROM control.indexer_profile p WHERE p.participant_id=p_participant
           AND p.privacy_domain_id=p_privacy AND p.indexer_profile_id::text=binding->>'id'
           AND p.method_profile_digest=binding->>'digest' AND p.engine_version=binding->>'engineVersion' AND p.state<>'RETIRED')
       WHEN 'ProjectionPlan' THEN NOT EXISTS (
         SELECT 1 FROM control.projection_plan p WHERE p.participant_id=p_participant
           AND p.privacy_domain_id=p_privacy AND p.projection_plan_id::text=binding->>'id'
           AND p.plan_digest=binding->>'digest' AND p.state<>'RETIRED')
       WHEN 'CiglSettings' THEN NOT EXISTS (
         SELECT 1 FROM control.cigl_settings p WHERE p.participant_id=p_participant
           AND p.privacy_domain_id=p_privacy AND p.cigl_settings_id::text=binding->>'id')
       ELSE true END
   )
$$;


ALTER FUNCTION openpc.runtime_configuration_bindings_current(p_participant uuid, p_privacy uuid, p_bindings jsonb) OWNER TO openpc_control_owner;

--
-- Name: runtime_denied_predecessor; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.runtime_denied_predecessor (
    configuration_work_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    runtime_target_id uuid NOT NULL,
    capsule_digest text NOT NULL,
    last_confirmed_capsule_digest text CONSTRAINT runtime_denied_predecessor_last_confirmed_capsule_dige_not_null NOT NULL,
    xds_version_digest text NOT NULL,
    capsule_generation bigint NOT NULL,
    denial_revision bigint NOT NULL,
    delivery_digest text NOT NULL,
    acknowledgement_digest text NOT NULL,
    result_event_id uuid NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL
);

ALTER TABLE ONLY control.runtime_denied_predecessor FORCE ROW LEVEL SECURITY;


ALTER TABLE control.runtime_denied_predecessor OWNER TO openpc_control_owner;

--
-- Name: runtime_denied_predecessor(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_denied_predecessor(target uuid) RETURNS SETOF control.runtime_denied_predecessor
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result control.runtime_denied_predecessor; found_count integer:=0;
BEGIN
 PERFORM openpc.assert_request_context(false);
 FOR result IN SELECT c.* FROM control.runtime_denied_predecessor c
 JOIN control.runtime_target t USING(participant_id,privacy_domain_id,runtime_target_id)
 JOIN control.configuration_work w ON w.configuration_work_id=c.configuration_work_id
  AND w.participant_id=c.participant_id AND w.privacy_domain_id=c.privacy_domain_id
 JOIN control.runtime_target_disposition_admission a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
  AND a.runtime_target_id=c.runtime_target_id AND a.revision=(SELECT max(h.revision)
   FROM control.runtime_target_disposition_admission h WHERE h.participant_id=c.participant_id
    AND h.privacy_domain_id=c.privacy_domain_id AND h.runtime_target_id=c.runtime_target_id)
 WHERE c.participant_id=openpc.current_participant_id() AND c.privacy_domain_id=openpc.current_privacy_domain_id()
  AND c.runtime_target_id=target AND t.active_generation_digest=c.last_confirmed_capsule_digest AND w.state='FAILED'
  AND w.result_receipt->>'outcome'='EXPIRED_OBSERVED_DENIED'
  AND a.binding->>'action'='Withdraw' AND a.binding->'source'->>'capsule_digest'=substring(c.capsule_digest from 8)
  AND a.binding->'source'->>'original_work_id'=w.configuration_work_id::text
  AND NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation newer
   WHERE newer.participant_id=c.participant_id AND newer.privacy_domain_id=c.privacy_domain_id
    AND newer.runtime_target_id=c.runtime_target_id AND newer.configuration_work_id<>c.configuration_work_id
    AND newer.observed_at>c.created_at)
 LOOP
  found_count:=found_count+1;
  IF found_count>1 THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-CARDINALITY'; END IF;
  RETURN NEXT result;
 END LOOP;
END $$;


ALTER FUNCTION openpc.runtime_denied_predecessor(target uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_discovery_credential_predecessor(uuid, text, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_discovery_credential_predecessor(target uuid, certificate text, source jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE pid uuid; privacy uuid; authority record; current_credential control.credential; head jsonb;
 previous jsonb; predecessor_identity jsonb; matches integer;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,certificate);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT current_credential FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 SELECT a.binding->'target' INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF head IS NULL THEN RETURN NULL; END IF;
 matches:=0;
 FOR predecessor_identity IN SELECT jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',predecessor.credential_id::text,'principal_id',predecessor.principal_id::text,
  'credential_epoch',(recovery.intent#>>'{certificateRecovery,predecessorEpoch}')::numeric,
  'principal_epoch',(recovery.intent#>>'{certificateRecovery,workloadPrincipalEpoch}')::numeric,
  'certificate_digest',encode(predecessor.secret_fingerprint,'hex'))
 FROM control.discovery_certificate_issuance issuance
 JOIN control.platform_recovery_case recovery ON recovery.participant_id=issuance.participant_id
  AND recovery.privacy_domain_id=issuance.privacy_domain_id AND recovery.recovery_id=issuance.recovery_id
  AND recovery.state='COMPLETED' AND recovery.completion_operation_id=issuance.committed_operation_id
  AND recovery.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
 JOIN control.platform_recovery_enrollment enrollment ON enrollment.participant_id=recovery.participant_id
  AND enrollment.privacy_domain_id=recovery.privacy_domain_id AND enrollment.enrollment_id=recovery.enrollment_id
  AND enrollment.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
  AND enrollment.document->'certificateRecovery'=recovery.intent->'certificateRecovery'
  AND enrollment.document_digest=recovery.enrollment_digest
  AND enrollment.document_digest=sha256(convert_to(openpc.signing_canonical_json(enrollment.document),'UTF8'))
 JOIN control.credential predecessor ON predecessor.participant_id=issuance.participant_id
  AND predecessor.credential_id=issuance.predecessor_credential_id
  AND predecessor.credential_id=current_credential.rotated_from_credential_id
  AND predecessor.principal_id=current_credential.principal_id AND predecessor.audience=current_credential.audience
  -- The old source issuer stays immutable. The enrolled key's new certificate
  -- is verified by the current installed issuer/profile at claim and commit;
  -- an expired predecessor CA cannot become current through equality here.
  AND predecessor.issuer=recovery.intent#>>'{certificateRecovery,issuer}'
  AND predecessor.certificate_der IS NOT NULL AND sha256(predecessor.certificate_der)=predecessor.secret_fingerprint
  AND 'sha256:'||encode(predecessor.secret_fingerprint,'hex')=recovery.intent#>>'{certificateRecovery,predecessorFingerprint}'
  AND 'sha256:'||encode(predecessor.public_key_digest,'hex')=recovery.intent#>>'{certificateRecovery,predecessorPublicKeyDigest}'
 JOIN control.discovery_certificate_issuer_attempt attempt ON attempt.participant_id=issuance.participant_id
  AND attempt.privacy_domain_id=issuance.privacy_domain_id AND attempt.issuance_id=issuance.issuance_id
  AND attempt.state='OBSERVED' AND attempt.certificate_fingerprint=issuance.certificate_fingerprint
 JOIN control.mutation_candidate mutation ON mutation.participant_id=issuance.participant_id
  AND mutation.privacy_domain_id=issuance.privacy_domain_id AND mutation.mutation_candidate_id=issuance.mutation_candidate_id
  AND mutation.state='CONSUMED' AND mutation.consumed_operation_id=issuance.committed_operation_id
  AND mutation.candidate_digest=issuance.candidate_digest AND mutation.idempotency_key=attempt.idempotency_key
  AND mutation.maker_principal_id=attempt.maker_principal_id AND mutation.maker_session_id=attempt.maker_session_id
  AND mutation.maker_principal_id::text=recovery.intent#>>'{administrators,0,principalId}'
 JOIN control.approval_request approval ON approval.participant_id=mutation.participant_id
  AND approval.privacy_domain_id=mutation.privacy_domain_id AND approval.approval_request_id=issuance.approval_request_id
  AND approval.subject_id=mutation.mutation_candidate_id AND approval.subject_digest=mutation.candidate_digest
  AND approval.subject_version=mutation.expected_revision AND approval.state='APPROVED'
 JOIN control.approval_decision_record decision ON decision.participant_id=approval.participant_id
  AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
  AND decision.decision='APPROVE' AND decision.approver_principal_id::text=recovery.intent#>>'{administrators,1,principalId}'
  AND decision.approver_principal_id<>mutation.maker_principal_id AND decision.candidate_digest=mutation.candidate_digest
  AND decision.evidence_cbor=attempt.authorization_evidence_cbor AND decision.cose_sign1=attempt.authorization_cose
  AND sha256(attempt.authorization_evidence_cbor)=attempt.authorization_evidence_digest
 JOIN control.mfa_challenge challenge ON challenge.participant_id=mutation.participant_id
  AND challenge.principal_id=mutation.maker_principal_id AND challenge.session_id=mutation.maker_session_id
  AND challenge.resource_digest=mutation.candidate_digest AND challenge.action_intent_id=mutation.action_intent_id
  AND challenge.consumed_at IS NOT NULL AND challenge.used_operation_id=issuance.committed_operation_id
 JOIN control.mutation_evidence verification ON verification.participant_id=challenge.participant_id
  AND verification.privacy_domain_id=mutation.privacy_domain_id AND verification.principal_id=challenge.principal_id
  AND verification.mfa_challenge_id=challenge.mfa_challenge_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
  AND verification.aggregate_type='webauthn-verification' AND verification.aggregate_id=challenge.session_id
  AND verification.webauthn_assertion_binding_digest=attempt.webauthn_assertion_binding_digest
 JOIN control.idempotency_record verified ON verified.participant_id=verification.participant_id
  AND verified.privacy_domain_id=verification.privacy_domain_id AND verified.operation_id=verification.operation_id
  AND verified.input_digest=verification.candidate_digest AND verified.terminal_state='COMMITTED'
  AND verified.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
 JOIN control.outbox_event verified_event ON verified_event.participant_id=verification.participant_id
  AND verified_event.privacy_domain_id=verification.privacy_domain_id AND verified_event.aggregate_type=verification.aggregate_type
  AND verified_event.aggregate_id=verification.aggregate_id AND verified_event.payload_cbor=verification.evidence_cbor
  AND verified_event.payload_digest=verification.evidence_digest AND verified_event.cose_sign1=verification.cose_sign1
  AND verified_event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
  AND verified_event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
 WHERE issuance.participant_id=pid AND issuance.privacy_domain_id=privacy AND issuance.state='COMMITTED'
  AND issuance.successor_credential_id=current_credential.credential_id AND issuance.certificate_der=current_credential.certificate_der
  AND issuance.certificate_fingerprint=current_credential.secret_fingerprint AND sha256(issuance.certificate_der)=issuance.certificate_fingerprint
  AND octet_length(issuance.issuer_profile_digest)=32 AND issuance.replay_profile IN ('READBACK_REQUIRED','IMMUTABLE_REQUEST_RESPONSE')
  AND (issuance.replay_profile<>'IMMUTABLE_REQUEST_RESPONSE' OR (current_setting('openpc.local_qa_runtime',true)='1'
    AND enrollment.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'))
  AND issuance.request_digest=sha256(convert_to(openpc.signing_canonical_json(issuance.request),'UTF8'))
  AND issuance.request=jsonb_build_object('credentialId',current_credential.credential_id::text,'participantId',pid::text,
   'principalId',current_credential.principal_id::text,'workloadId','urn:openpc:workload:'||target::text,
   'publicKeySpkiDer',replace(encode(current_credential.public_key_spki_der,'base64'),E'
',''))
  AND recovery.intent#>>'{certificateRecovery,targetId}'=target::text
  AND recovery.intent#>>'{certificateRecovery,workloadPrincipalId}'=current_credential.principal_id::text
  AND (recovery.intent#>>'{certificateRecovery,workloadPrincipalEpoch}')::numeric=authority.principal_epoch
  AND recovery.completion_result=jsonb_build_object('issuanceId',issuance.issuance_id::text,'operationId',issuance.committed_operation_id::text,
   'predecessorCredentialId',predecessor.credential_id::text,'successorCredentialId',current_credential.credential_id::text,
   'certificateFingerprint','sha256:'||encode(current_credential.secret_fingerprint,'hex'))
  AND EXISTS (
    SELECT 1 FROM control.credential predecessor
    JOIN control.credential successor ON successor.participant_id=predecessor.participant_id
      AND successor.rotated_from_credential_id=predecessor.credential_id
      AND successor.principal_id=predecessor.principal_id AND successor.audience=predecessor.audience
    JOIN control.mutation_candidate candidate ON candidate.participant_id=predecessor.participant_id
      AND candidate.privacy_domain_id=privacy
      AND candidate.resource_id=predecessor.credential_id
      AND candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
      AND candidate.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
      AND candidate.state='CONSUMED' AND candidate.consumed_operation_id IS NOT NULL
      AND candidate.candidate_document=jsonb_build_object('replacedCredentialId',predecessor.credential_id::text,
        'credentialId',successor.credential_id::text,
        'publicKeySpkiDer',replace(encode(successor.public_key_spki_der,'base64'),E'\n',''))
      AND candidate.candidate_digest=sha256(convert_to(openpc.signing_canonical_json(candidate.candidate_document),'UTF8'))
    JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id
      AND approval.privacy_domain_id=candidate.privacy_domain_id AND approval.subject_type='CONFIGURATION_CANDIDATE'
      AND approval.subject_id=candidate.mutation_candidate_id AND approval.subject_digest=candidate.candidate_digest
      AND approval.maker_principal_id=candidate.maker_principal_id AND approval.state='APPROVED'
      AND approval.subject_version=candidate.expected_revision AND approval.action_intent_id=candidate.action_intent_id
    JOIN control.approval_decision_record decision ON decision.participant_id=approval.participant_id
      AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
      AND decision.decision='APPROVE' AND decision.candidate_digest=candidate.candidate_digest
      AND decision.approver_principal_id<>approval.maker_principal_id AND decision.cose_sign1 IS NOT NULL
      AND decision.aggregate_version=approval.subject_version
    JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
      AND evidence.privacy_domain_id=candidate.privacy_domain_id AND evidence.operation_id=candidate.consumed_operation_id
      AND evidence.action_intent_id=candidate.action_intent_id AND evidence.catalog_operation_id=candidate.catalog_operation_id
      AND evidence.aggregate_type='workload-credential' AND evidence.aggregate_id=predecessor.credential_id
      AND evidence.candidate_digest=candidate.candidate_digest AND evidence.principal_id=approval.maker_principal_id
      AND evidence.checker_principal_id=decision.approver_principal_id AND evidence.approval_request_id=approval.approval_request_id
      AND evidence.evidence_digest=sha256(evidence.evidence_cbor) AND evidence.cose_sign1 IS NOT NULL
      AND evidence.evidence_cbor=decision.evidence_cbor AND evidence.cose_sign1=decision.cose_sign1
      AND evidence.signer_credential_id=decision.signer_credential_id
      AND evidence.webauthn_assertion_binding_digest IS NOT NULL AND evidence.mfa_challenge_id IS NOT NULL
    JOIN control.idempotency_record committed ON committed.participant_id=evidence.participant_id
      AND committed.privacy_domain_id=evidence.privacy_domain_id AND committed.operation_id=evidence.operation_id
      AND committed.action_intent_id=evidence.action_intent_id AND committed.catalog_operation_id=evidence.catalog_operation_id
      AND committed.principal_id=evidence.principal_id
      AND committed.terminal_state='COMMITTED' AND committed.input_digest=evidence.candidate_digest
      AND committed.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
      AND committed.result_payload->>'credentialId'=successor.credential_id::text
      AND committed.result_payload->>'replacedCredentialId'=predecessor.credential_id::text
      AND committed.result_payload->>'principalId'=successor.principal_id::text
      AND committed.result_payload->>'workloadId'=successor.audience
      AND committed.result_payload->>'workloadEpoch'=successor.credential_epoch::text
      AND committed.result_payload->>'state'='ACTIVE'
    JOIN control.outbox_event event ON event.participant_id=evidence.participant_id
      AND event.privacy_domain_id=evidence.privacy_domain_id AND event.aggregate_type=evidence.aggregate_type
      AND event.aggregate_id=evidence.aggregate_id AND event.payload_cbor=evidence.evidence_cbor
      AND event.event_type='openpc.identity.workload-credential.mutation.committed.v1'
      AND event.payload_digest=evidence.evidence_digest AND event.cose_sign1=evidence.cose_sign1
      AND event.webauthn_assertion_binding_digest=evidence.webauthn_assertion_binding_digest
    WHERE predecessor.participant_id=pid
      AND predecessor.credential_id=issuance.predecessor_credential_id AND successor.credential_id=issuance.successor_credential_id
      AND predecessor.kind='WORKLOAD_MTLS' AND predecessor.state='REVOKED'
      AND successor.kind='WORKLOAD_MTLS' AND successor.state='ACTIVE'
      AND predecessor.credential_epoch=(recovery.intent#>>'{certificateRecovery,predecessorEpoch}')::numeric+1
      AND successor.credential_epoch=predecessor.credential_epoch
      AND successor.credential_epoch=authority.credential_epoch
      AND successor.valid_from<=clock_timestamp() AND successor.valid_until>clock_timestamp()
      AND evidence.operation_id=issuance.committed_operation_id
  )
  AND EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission original
   JOIN control.runtime_target_disposition_delivery delivery ON delivery.participant_id=original.participant_id
    AND delivery.privacy_domain_id=original.privacy_domain_id AND delivery.runtime_target_id=original.runtime_target_id
    AND delivery.revision=original.revision
    AND delivery.claims=original.binding||jsonb_build_object('committed_admission_digest',substring(original.admission_digest from 8))
    AND delivery.delivery_digest='sha256:'||encode(sha256(delivery.signed_delivery),'hex')
   JOIN control.runtime_target_disposition_acknowledgement ack ON ack.participant_id=delivery.participant_id
    AND ack.privacy_domain_id=delivery.privacy_domain_id AND ack.runtime_target_id=delivery.runtime_target_id
    AND ack.delivery_digest=delivery.delivery_digest AND ack.claims->'target'=original.binding->'target'
    AND ack.acknowledgement_digest='sha256:'||encode(sha256(ack.signed_acknowledgement),'hex')
   WHERE original.participant_id=pid AND original.privacy_domain_id=privacy AND original.runtime_target_id=target
    AND original.binding->'source'=runtime_discovery_credential_predecessor.source
    AND original.binding->'target'=jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
     'target_id',target::text,'credential_id',predecessor.credential_id::text,'principal_id',predecessor.principal_id::text,
     'credential_epoch',(recovery.intent#>>'{certificateRecovery,predecessorEpoch}')::numeric,
     'principal_epoch',(recovery.intent#>>'{certificateRecovery,workloadPrincipalEpoch}')::numeric,
     'certificate_digest',encode(predecessor.secret_fingerprint,'hex')))
 LOOP
  matches:=matches+1; previous:=predecessor_identity;
 END LOOP;
 IF matches=1 THEN RETURN previous; END IF;
 IF matches<>0 OR head IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',current_credential.credential_id::text,'principal_id',current_credential.principal_id::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',substring(certificate from 8))
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CREDENTIAL-SUCCESSOR'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION openpc.runtime_discovery_credential_predecessor(target uuid, certificate text, source jsonb) OWNER TO openpc_control_owner;

--
-- Name: configuration_work; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.configuration_work (
    configuration_work_id uuid DEFAULT uuidv7() NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    work_kind text NOT NULL,
    resource_id uuid NOT NULL,
    input_digest text NOT NULL,
    configuration_digest text NOT NULL,
    runtime_configuration_generation_id uuid,
    runtime_target_id uuid,
    generation_digest text,
    predecessor_digest text,
    policy_generation_digest text,
    xds_version_digest text,
    state text DEFAULT 'PENDING'::text NOT NULL,
    attempt_count bigint DEFAULT 0 NOT NULL,
    lease_owner text,
    lease_until timestamp(6) with time zone,
    result_receipt jsonb,
    result_receipt_digest text,
    result_event_id uuid,
    last_error_code text,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp(6) with time zone,
    execution_attempt_id uuid,
    execution_started_at timestamp(6) with time zone,
    reconcile_after timestamp(6) with time zone,
    denied_predecessor_work_id uuid,
    CONSTRAINT configuration_work_attempt_count_ck CHECK ((attempt_count >= 0)),
    CONSTRAINT configuration_work_configuration_digest_ck CHECK ((configuration_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT configuration_work_error_ck CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^PC-[A-Z]+-[0-9]{4}$'::text))),
    CONSTRAINT configuration_work_execution_ck CHECK ((((execution_started_at IS NULL) = (execution_attempt_id IS NULL)) AND ((state <> 'RECONCILING'::text) OR ((execution_attempt_id IS NOT NULL) AND (execution_started_at IS NOT NULL) AND (reconcile_after IS NOT NULL))))),
    CONSTRAINT configuration_work_generation_digest_ck CHECK (((generation_digest IS NULL) OR (generation_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT configuration_work_input_digest_ck CHECK ((input_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT configuration_work_kind_ck CHECK ((work_kind = ANY (ARRAY['PROVIDER_QUALIFICATION'::text, 'INDEXER_ADMISSION'::text, 'PROJECTION_VALIDATION'::text, 'RUNTIME_ACTIVATION'::text, 'CIGL_PROFILE_COMPILATION'::text]))),
    CONSTRAINT configuration_work_lease_ck CHECK (((state = 'LEASED'::text) = ((lease_owner IS NOT NULL) AND (lease_until IS NOT NULL)))),
    CONSTRAINT configuration_work_policy_digest_ck CHECK ((policy_generation_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT configuration_work_policy_provenance_ck CHECK (((policy_generation_digest IS NOT NULL) OR (work_kind = ANY (ARRAY['PROVIDER_QUALIFICATION'::text, 'INDEXER_ADMISSION'::text, 'PROJECTION_VALIDATION'::text])))),
    CONSTRAINT configuration_work_predecessor_digest_ck CHECK (((predecessor_digest IS NULL) OR (predecessor_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT configuration_work_receipt_ck CHECK (((state = ANY (ARRAY['COMPLETED'::text, 'FAILED'::text])) = ((result_receipt IS NOT NULL) AND (result_receipt_digest IS NOT NULL) AND (result_event_id IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT configuration_work_receipt_digest_ck CHECK (((result_receipt_digest IS NULL) OR (result_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT configuration_work_runtime_binding_ck CHECK (((work_kind = 'RUNTIME_ACTIVATION'::text) = ((runtime_configuration_generation_id IS NOT NULL) AND (runtime_target_id IS NOT NULL) AND (generation_digest IS NOT NULL) AND (policy_generation_digest IS NOT NULL) AND (xds_version_digest IS NOT NULL)))),
    CONSTRAINT configuration_work_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'RECONCILING'::text, 'COMPLETED'::text, 'FAILED'::text]))),
    CONSTRAINT configuration_work_xds_digest_ck CHECK (((xds_version_digest IS NULL) OR (xds_version_digest ~ '^sha256:[0-9a-f]{64}$'::text)))
);


ALTER TABLE control.configuration_work OWNER TO openpc_control_owner;

--
-- Name: runtime_configuration_generation; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.runtime_configuration_generation (
    runtime_configuration_generation_id uuid DEFAULT uuidv7() CONSTRAINT runtime_configuration_gener_runtime_configuration_gene_not_null NOT NULL,
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    runtime_target_id uuid NOT NULL,
    projection_plan_id uuid NOT NULL,
    predecessor_digest text,
    generation_digest text NOT NULL,
    policy_generation_digest text CONSTRAINT runtime_configuration_generat_policy_generation_digest_not_null NOT NULL,
    state text DEFAULT 'STAGED'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    activated_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    provider_profile_id uuid NOT NULL,
    cigl_profile_selection jsonb,
    CONSTRAINT runtime_configuration_generation_cigl_selection_ck CHECK (((cigl_profile_selection IS NULL) OR ((jsonb_typeof(cigl_profile_selection) = 'object'::text) AND (octet_length((cigl_profile_selection)::text) <= 65536) AND (jsonb_typeof((cigl_profile_selection -> 'profiles'::text)) = 'array'::text) AND ((jsonb_array_length((cigl_profile_selection -> 'profiles'::text)) >= 1) AND (jsonb_array_length((cigl_profile_selection -> 'profiles'::text)) <= 64)) AND ((cigl_profile_selection ->> 'participantEpoch'::text) ~ '^[1-9][0-9]{0,19}$'::text) AND ((cigl_profile_selection - ARRAY['participantEpoch'::text, 'profiles'::text, 'policyRenewal'::text]) = '{}'::jsonb) AND ((NOT (cigl_profile_selection ? 'policyRenewal'::text)) OR ((jsonb_typeof((cigl_profile_selection -> 'policyRenewal'::text)) = 'object'::text) AND ((cigl_profile_selection -> 'policyRenewal'::text) ?& ARRAY['activationOccurrenceRef'::text, 'expectedRevision'::text, 'policyGenerationDigest'::text]) AND (((cigl_profile_selection -> 'policyRenewal'::text) - ARRAY['activationOccurrenceRef'::text, 'expectedRevision'::text, 'policyGenerationDigest'::text]) = '{}'::jsonb) AND (((cigl_profile_selection -> 'policyRenewal'::text) ->> 'activationOccurrenceRef'::text) ~ '^urn:openpc:resource:[0-9a-f-]{36}$'::text) AND (((cigl_profile_selection -> 'policyRenewal'::text) ->> 'expectedRevision'::text) ~ '^[1-9][0-9]{0,18}$'::text) AND (((cigl_profile_selection -> 'policyRenewal'::text) ->> 'policyGenerationDigest'::text) ~ '^sha256:[0-9a-f]{64}$'::text)))))),
    CONSTRAINT runtime_configuration_generation_digest_ck CHECK ((generation_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT runtime_configuration_generation_policy_digest_ck CHECK ((policy_generation_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT runtime_configuration_generation_predecessor_digest_ck CHECK (((predecessor_digest IS NULL) OR (predecessor_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT runtime_configuration_generation_revision_ck CHECK ((revision > 0)),
    CONSTRAINT runtime_configuration_generation_state_ck CHECK ((state = ANY (ARRAY['STAGED'::text, 'ACTIVATING'::text, 'ACTIVE'::text, 'QUARANTINED'::text, 'FAILED'::text])))
);


ALTER TABLE control.runtime_configuration_generation OWNER TO openpc_control_owner;

--
-- Name: runtime_generation_retry_failure_payload(control.runtime_configuration_generation, control.configuration_work); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_generation_retry_failure_payload(prior control.runtime_configuration_generation, work control.configuration_work) RETURNS bytea
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE payload bytea;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF prior.runtime_configuration_generation_id IS NULL OR work.configuration_work_id IS NULL
  OR prior.runtime_target_id IS NULL OR prior.generation_digest IS NULL
  OR prior.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR prior.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR prior.state IS DISTINCT FROM 'FAILED' OR prior.activated_at IS NOT NULL OR prior.cigl_profile_selection IS NOT NULL
  OR work.participant_id IS DISTINCT FROM prior.participant_id
  OR work.privacy_domain_id IS DISTINCT FROM prior.privacy_domain_id
  OR work.runtime_configuration_generation_id IS DISTINCT FROM prior.runtime_configuration_generation_id
  OR work.operation_id IS NULL OR work.last_error_code IS NULL
  OR work.state IS DISTINCT FROM 'FAILED' OR work.work_kind IS DISTINCT FROM 'RUNTIME_ACTIVATION'
  OR work.runtime_target_id IS DISTINCT FROM prior.runtime_target_id OR work.resource_id IS DISTINCT FROM prior.runtime_target_id
  OR work.generation_digest IS DISTINCT FROM prior.generation_digest
  OR work.predecessor_digest IS DISTINCT FROM prior.predecessor_digest
  OR work.execution_started_at IS NOT NULL OR work.execution_attempt_id IS NOT NULL
  OR work.lease_owner IS NOT NULL OR work.lease_until IS NOT NULL OR work.reconcile_after IS NOT NULL
  OR work.completed_at IS NULL OR work.result_event_id IS NULL
  OR work.result_receipt IS DISTINCT FROM jsonb_build_object('errorCode',work.last_error_code,
    'resourceId',work.resource_id::text,'terminal',true,'workKind','RUNTIME_ACTIVATION')
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 payload:=convert_to(openpc.signing_canonical_json(work.result_receipt),'UTF8');
 IF work.result_receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(payload),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 RETURN payload;
END $$;


ALTER FUNCTION openpc.runtime_generation_retry_failure_payload(prior control.runtime_configuration_generation, work control.configuration_work) OWNER TO openpc_control_owner;

--
-- Name: runtime_installed_predecessor(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_installed_predecessor(target uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE installed text; confirmed text;
BEGIN
 SELECT c.capsule_digest INTO installed FROM openpc.runtime_denied_predecessor(target) c;
 IF FOUND THEN RETURN installed; END IF;
 SELECT t.active_generation_digest INTO STRICT confirmed FROM control.runtime_target t
  WHERE t.participant_id=openpc.current_participant_id() AND t.privacy_domain_id=openpc.current_privacy_domain_id()
   AND t.runtime_target_id=target;
 -- A missing current cursor is not proof the old confirmed capsule is installed.
 -- Only a genuinely completed later effect can supersede the physical denial.
 IF EXISTS(SELECT 1 FROM control.runtime_denied_predecessor c
  WHERE c.participant_id=openpc.current_participant_id() AND c.privacy_domain_id=openpc.current_privacy_domain_id()
   AND c.runtime_target_id=target AND NOT EXISTS(
    SELECT 1 FROM control.configuration_work w JOIN control.runtime_activation_observation o
     USING(configuration_work_id,participant_id,privacy_domain_id,runtime_target_id,execution_attempt_id)
    WHERE w.participant_id=c.participant_id AND w.privacy_domain_id=c.privacy_domain_id AND w.runtime_target_id=c.runtime_target_id
     AND w.state='COMPLETED' AND w.completed_at>c.created_at AND o.observed_at>c.created_at
     AND o.capsule_digest=confirmed AND w.result_event_id IS NOT NULL))
 THEN RAISE EXCEPTION 'DENIED-PREDECESSOR-UNAVAILABLE'; END IF;
 RETURN confirmed;
END $$;


ALTER FUNCTION openpc.runtime_installed_predecessor(target uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_target_discovery_current(uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_target_discovery_current(pid uuid, privacy uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce((SELECT NOT t.requires_authenticated_discovery OR EXISTS(
  SELECT 1 FROM control.runtime_target_connection observation
  JOIN control.credential credential ON credential.participant_id=observation.participant_id
   AND credential.credential_id=observation.credential_id
  JOIN control.principal principal ON principal.participant_id=credential.participant_id
   AND principal.principal_id=credential.principal_id
  JOIN control.participant participant ON participant.participant_id=principal.participant_id
  JOIN control.privacy_domain privacy_domain ON privacy_domain.participant_id=observation.participant_id
   AND privacy_domain.privacy_domain_id=observation.privacy_domain_id
  WHERE observation.participant_id=pid AND observation.privacy_domain_id=privacy
   AND observation.runtime_target_id=target AND observation.connected
   AND observation.observed_at<=clock_timestamp() AND observation.valid_until>clock_timestamp()
   AND credential.kind='WORKLOAD_MTLS' AND credential.state='ACTIVE'
   AND credential.credential_epoch=observation.credential_epoch
   AND credential.valid_from<=clock_timestamp() AND credential.valid_until>clock_timestamp()
   AND credential.subject='urn:openpc:participant:'||pid::text||':workload:'||target::text
   AND credential.audience='urn:openpc:workload:'||target::text
   AND credential.secret_fingerprint=decode(substring(observation.certificate_digest from 8),'hex')
   AND credential.certificate_der IS NOT NULL AND sha256(credential.certificate_der)=credential.secret_fingerprint
   AND principal.kind='WORKLOAD' AND principal.state='ACTIVE' AND principal.authority_epoch=observation.principal_epoch
   AND participant.state='ACTIVE' AND participant.archived_at IS NULL AND privacy_domain.state='ACTIVE')
  FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
   AND t.runtime_target_id=target AND pid=openpc.current_participant_id() AND privacy=openpc.current_privacy_domain_id()),false)
$$;


ALTER FUNCTION openpc.runtime_target_discovery_current(pid uuid, privacy uuid, target uuid) OWNER TO openpc_control_owner;

--
-- Name: runtime_unsigned_withdrawal_recoverable(uuid, bigint, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_unsigned_withdrawal_recoverable(target uuid, wanted_revision bigint, wanted_digest text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE pid uuid; privacy uuid; abandoned control.runtime_target_disposition_admission;
 previous control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 failed control.configuration_work; generation control.runtime_configuration_generation; payload bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 IF target IS NULL OR wanted_revision IS NULL OR wanted_revision<2 OR wanted_digest IS NULL
  OR openpc.current_action_intent_id() NOT IN ('ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1',
   'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1') THEN RETURN false; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT a.* INTO abandoned FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision AND a.admission_digest=wanted_digest FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->>'action' IS DISTINCT FROM 'Withdraw'
  OR abandoned.activation_proof IS NOT NULL OR abandoned.restoration_proof IS NOT NULL
  OR abandoned.binding->'cause'->>'kind' IS DISTINCT FROM 'Activation'
  OR abandoned.binding->'cause'->'execution_attempt_id' IS DISTINCT FROM 'null'::jsonb
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_delivery d WHERE d.participant_id=pid
   AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision)
 THEN RETURN false; END IF;
 SELECT a.* INTO previous FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.revision=wanted_revision-1 FOR SHARE NOWAIT;
 IF NOT FOUND OR previous.binding->>'action' IS DISTINCT FROM 'ConfirmActivation'
  OR previous.binding->'target' IS DISTINCT FROM abandoned.binding->'target'
  OR previous.binding->'source' IS DISTINCT FROM abandoned.binding->'source'
  OR abandoned.binding->'previous_revision' IS DISTINCT FROM to_jsonb(previous.revision)
 THEN RETURN false; END IF;
 SELECT d.* INTO delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=previous.revision;
 IF NOT FOUND OR abandoned.binding->>'previous_delivery_digest' IS DISTINCT FROM substring(delivery.delivery_digest from 8)
  OR NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement k
   WHERE k.participant_id=pid AND k.privacy_domain_id=privacy AND k.runtime_target_id=target
    AND k.delivery_digest=delivery.delivery_digest AND k.claims->>'installed_state'='ActivationConfirmed')
 THEN RETURN false; END IF;
 SELECT w.* INTO failed FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id::text=abandoned.binding->'cause'->>'work_id' FOR SHARE NOWAIT;
 IF NOT FOUND OR abandoned.binding->'cause' IS DISTINCT FROM jsonb_build_object('kind','Activation',
  'work_id',failed.configuration_work_id::text,'operation_id',failed.operation_id::text,'execution_attempt_id',NULL)
  OR failed.state IS DISTINCT FROM 'FAILED' OR failed.work_kind IS DISTINCT FROM 'RUNTIME_ACTIVATION'
  OR failed.execution_started_at IS NOT NULL OR failed.execution_attempt_id IS NOT NULL
  OR failed.predecessor_digest IS DISTINCT FROM 'sha256:'||(abandoned.binding->'source'->>'capsule_digest')
  OR failed.configuration_work_id::text=abandoned.binding->'source'->>'original_work_id'
 THEN RETURN false; END IF;
 SELECT g.* INTO generation FROM control.runtime_configuration_generation g
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND g.runtime_configuration_generation_id=failed.runtime_configuration_generation_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RETURN false; END IF;
 payload:=openpc.runtime_generation_retry_failure_payload(generation,failed);
 IF NOT EXISTS(SELECT 1 FROM control.outbox_event e JOIN control.mutation_evidence a
  ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
   AND a.operation_id=failed.operation_id AND a.aggregate_id=target
   AND a.action_intent_id='ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'
   AND a.catalog_operation_id='CFG-OP-UPDATE-RUNTIME-TARGET'
   AND a.evidence_role='AUTHORIZATION_INPUT' AND a.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
  JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
   AND i.operation_id=a.operation_id AND i.input_digest=a.candidate_digest AND i.terminal_state='COMMITTED'
   AND i.result_payload->>'state'='FAILED' AND i.result_payload->>'truthState'='FAILED'
  WHERE e.participant_id=pid AND e.privacy_domain_id=privacy AND e.event_id=failed.result_event_id
   AND e.aggregate_id=target AND e.aggregate_type='runtime-targets' AND e.event_type='runtime-target.activation-failed.v1'
   AND e.payload_cbor=payload AND e.payload_digest=sha256(payload) AND e.cose_sign1=a.cose_sign1
   AND octet_length(a.cose_sign1)>0 AND a.evidence_digest=sha256(a.evidence_cbor))
  OR EXISTS(SELECT 1 FROM control.runtime_activation_observation o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.policy_activation_occurrence_target o
   WHERE o.configuration_work_id=failed.configuration_work_id OR o.runtime_configuration_generation_id=generation.runtime_configuration_generation_id)
  OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
   WHERE a.runtime_target_id=target AND (a.binding->'source'->>'original_work_id'=failed.configuration_work_id::text
    OR a.binding->'source'->>'runtime_configuration_generation_id'=generation.runtime_configuration_generation_id::text))
 THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $$;


ALTER FUNCTION openpc.runtime_unsigned_withdrawal_recoverable(target uuid, wanted_revision bigint, wanted_digest text) OWNER TO openpc_control_owner;

--
-- Name: runtime_work_predecessor_matches(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.runtime_work_predecessor_matches(wanted uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN w.denied_predecessor_work_id IS NULL THEN t.active_generation_digest IS NOT DISTINCT FROM w.predecessor_digest
 ELSE EXISTS(SELECT 1 FROM control.runtime_denied_predecessor c
  JOIN control.configuration_work original ON original.configuration_work_id=c.configuration_work_id
   AND original.participant_id=c.participant_id AND original.privacy_domain_id=c.privacy_domain_id
  WHERE c.configuration_work_id=w.denied_predecessor_work_id AND c.participant_id=w.participant_id
   AND c.privacy_domain_id=w.privacy_domain_id AND c.runtime_target_id=w.runtime_target_id
   AND c.capsule_digest=w.predecessor_digest AND c.last_confirmed_capsule_digest=t.active_generation_digest
   AND w.created_at>=c.created_at AND original.state='FAILED'
   AND original.result_receipt->>'outcome'='EXPIRED_OBSERVED_DENIED'
   AND NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation newer
    WHERE newer.participant_id=c.participant_id AND newer.privacy_domain_id=c.privacy_domain_id
     AND newer.runtime_target_id=c.runtime_target_id AND newer.observed_at>c.created_at
     AND newer.configuration_work_id<>w.configuration_work_id)
   AND EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
    WHERE a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id AND a.runtime_target_id=c.runtime_target_id
     AND a.revision=(SELECT max(h.revision) FROM control.runtime_target_disposition_admission h
      WHERE h.participant_id=c.participant_id AND h.privacy_domain_id=c.privacy_domain_id AND h.runtime_target_id=c.runtime_target_id)
     AND ((a.binding->>'action'='Withdraw' AND a.binding->'source'->>'capsule_digest'=substring(c.capsule_digest from 8)
       AND a.binding->'source'->>'original_work_id'=c.configuration_work_id::text
       AND (a.revision=c.denial_revision OR a.binding->'cause'->>'work_id'=w.configuration_work_id::text))
      OR(a.binding->>'action'='ConfirmActivation' AND a.binding->'source'->>'original_work_id'=w.configuration_work_id::text
       AND a.binding->'cause'->>'execution_attempt_id'=w.execution_attempt_id::text)))) END
 FROM control.configuration_work w JOIN control.runtime_target t USING(participant_id,privacy_domain_id,runtime_target_id)
 WHERE w.configuration_work_id=wanted AND w.participant_id=openpc.current_participant_id()
  AND w.privacy_domain_id=openpc.current_privacy_domain_id()
$$;


ALTER FUNCTION openpc.runtime_work_predecessor_matches(wanted uuid) OWNER TO openpc_control_owner;

--
-- Name: select_identity_envelope_recovery_trust(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.select_identity_envelope_recovery_trust() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'control'
    SET row_security TO 'on'
    AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation;
 selected control.identity_envelope_signing_selection; next_key control.business_signing_key; changed integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND openpc.matches_participant(s.participant_id) AND openpc.matches_privacy(s.privacy_domain_id)
  AND s.from_revision=5 AND s.from_state='VERIFIED' AND s.to_state='CUTOVER_FENCED' AND s.state='COMMITTED';
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id AND r.privacy_domain_id=step.privacy_domain_id
  AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id AND r.state='CUTOVER_FENCED' AND r.revision=6;
 SELECT * INTO STRICT selected FROM control.identity_envelope_signing_selection s WHERE s.participant_id=step.participant_id AND s.privacy_domain_id=step.privacy_domain_id
  AND s.environment_id=rotation.environment_id AND s.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  AND s.signer_id=rotation.old_signer_id AND s.admission_version::text=step.authority_binding#>>'{lease,selectionAdmissionVersion}' FOR UPDATE;
 SELECT k.* INTO STRICT next_key FROM control.business_signing_key k JOIN control.identity_envelope_signing_grant g USING(participant_id,privacy_domain_id,signer_id)
  WHERE k.participant_id=step.participant_id AND k.privacy_domain_id=step.privacy_domain_id AND k.signer_id=rotation.new_signer_id AND k.signing_purpose_code=371
   AND g.signing_purpose_code=371 AND g.profile_digest=selected.profile_digest AND k.environment_id=selected.environment_id
   AND k.trust_digest=decode(substr(step.result->>'trustDigest',8),'hex');
 UPDATE control.business_signing_key_state SET state='ACTIVE',row_version=row_version+1,
  changed_at_ns=floor(extract(epoch from clock_timestamp())*1000000)*1000,change_reference='urn:openpc:resource:'||rotation.rotation_id::text,change_digest=step.evidence_digest
  WHERE participant_id=step.participant_id AND privacy_domain_id=step.privacy_domain_id AND signer_id=next_key.signer_id AND state='ADMITTED' AND row_version=1;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER-LIFECYCLE'; END IF;
 UPDATE control.identity_envelope_signing_selection SET signer_id=next_key.signer_id,admission_version=admission_version+1
  WHERE participant_id=selected.participant_id AND privacy_domain_id=selected.privacy_domain_id AND environment_id=selected.environment_id
   AND profile_digest=selected.profile_digest AND signer_id=selected.signer_id AND admission_version=selected.admission_version;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER-SELECTION'; END IF;
 RETURN jsonb_build_object('signerId',next_key.signer_id,'trustDigest','sha256:'||encode(next_key.trust_digest,'hex'),
  'selectionAdmissionVersion',(selected.admission_version+1)::text,'state','SELECTED');
END $$;


ALTER FUNCTION openpc.select_identity_envelope_recovery_trust() OWNER TO openpc_control_owner;

--
-- Name: session_step_up_valid_until(uuid, uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.session_step_up_valid_until(p_participant uuid, p_session uuid, p_principal uuid) RETURNS timestamp with time zone
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN session.step_up_mfa_challenge_id IS NULL THEN session.step_up_verified_at+interval '5 minutes'
  ELSE (SELECT least(challenge.consumed_at+make_interval(secs=>challenge.verified_proof_max_age_ms/1000.0),
    challenge.expires_at,session.idle_expires_at,session.absolute_expires_at,credential.valid_until)
   FROM control.mfa_challenge challenge JOIN control.credential credential
    ON credential.participant_id=challenge.participant_id AND credential.principal_id=challenge.principal_id
    AND credential.credential_id=challenge.signer_credential_id AND credential.credential_epoch=challenge.signer_credential_epoch
    AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
    AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
   WHERE challenge.participant_id=session.participant_id AND challenge.principal_id=session.principal_id
    AND challenge.session_id=session.session_id AND challenge.mfa_challenge_id=session.step_up_mfa_challenge_id
    AND challenge.consumed_at=session.step_up_verified_at AND challenge.created_at<=challenge.consumed_at
    AND challenge.consumed_at<=clock_timestamp()
    AND (challenge.verified_proof_max_age_ms=300000 OR
      (challenge.verified_proof_max_age_ms=3000000 AND session.duration_profile='LOCAL_QA_10X'))) END
 FROM control.session session
 JOIN control.participant participant ON participant.participant_id=session.participant_id
  AND participant.state='ACTIVE' AND participant.authority_epoch=session.participant_epoch
 JOIN control.principal principal ON principal.participant_id=session.participant_id
  AND principal.principal_id=session.principal_id AND principal.state='ACTIVE'
  AND principal.authority_epoch=session.authority_epoch
 WHERE session.participant_id=p_participant AND session.session_id=p_session AND session.principal_id=p_principal
  AND session.state='ACTIVE' AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
$$;


ALTER FUNCTION openpc.session_step_up_valid_until(p_participant uuid, p_session uuid, p_principal uuid) OWNER TO openpc_control_owner;

--
-- Name: set_request_context(text, uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.set_request_context(p_mode text, p_participant_id uuid, p_privacy_domain_id uuid, p_operation_id uuid, p_action_intent_id text, p_require_privacy boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'openpc'
    AS $_$
BEGIN
  IF p_mode NOT IN ('PARTICIPANT', 'PLATFORM') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6001-CONTEXT-INVALID', DETAIL = 'openpc.context_mode';
  END IF;
  IF p_operation_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR p_action_intent_id !~ '^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6001-CONTEXT-INVALID';
  END IF;
  IF p_mode = 'PLATFORM' AND NOT (
    current_user = 'openpc_control_platform_runtime'
    OR pg_has_role(current_user, 'openpc_control_platform_runtime', 'MEMBER')
    OR pg_has_role(current_user, 'openpc_control_migrator', 'MEMBER')
    OR pg_has_role(current_user, 'openpc_control_maintenance', 'MEMBER')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6002-PLATFORM-CONTEXT-FORBIDDEN';
  END IF;
  IF p_require_privacy AND p_privacy_domain_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6000-CONTEXT-MISSING', DETAIL = 'privacy_domain_id';
  END IF;
  PERFORM set_config('openpc.context_mode', p_mode, true);
  PERFORM set_config('openpc.participant_id', p_participant_id::text, true);
  PERFORM set_config('openpc.privacy_domain_id', coalesce(p_privacy_domain_id::text, ''), true);
  PERFORM set_config('openpc.operation_id', p_operation_id::text, true);
  PERFORM set_config('openpc.action_intent_id', p_action_intent_id, true);
  PERFORM set_config('openpc.context_scope', 'TRANSACTION_LOCAL', true);
END $_$;


ALTER FUNCTION openpc.set_request_context(p_mode text, p_participant_id uuid, p_privacy_domain_id uuid, p_operation_id uuid, p_action_intent_id text, p_require_privacy boolean) OWNER TO openpc_control_owner;

--
-- Name: signing_admission_open(uuid, uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_admission_open(p_participant uuid, p_privacy uuid, p_signer text, p_operation uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r JOIN control.signing_rotation_command c
  ON c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id AND c.rotation_id=r.rotation_id
  WHERE r.participant_id=p_participant AND r.privacy_domain_id=p_privacy AND p_signer IN(r.old_signer_id,r.new_signer_id)
   AND c.state='WRITE_AMBIGUITY' AND c.operation_id<>p_operation AND NOT EXISTS(
    SELECT 1 FROM control.signing_rotation_command recovery WHERE recovery.participant_id=c.participant_id
     AND recovery.privacy_domain_id=c.privacy_domain_id AND recovery.rotation_id=c.rotation_id
     AND recovery.operation_id=p_operation AND recovery.original_operation_id=c.operation_id
     AND recovery.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND recovery.state='ACCEPTED'))
$$;


ALTER FUNCTION openpc.signing_admission_open(p_participant uuid, p_privacy uuid, p_signer text, p_operation uuid) OWNER TO openpc_control_owner;

--
-- Name: signing_attempt_authority_status(uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_signing_authority_locker
--

CREATE FUNCTION openpc.signing_attempt_authority_status(p_attempt uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE command control.signing_rotation_command%ROWTYPE; snapshot jsonb; dependency record;
 actual jsonb; current_rows jsonb:='{}'::jsonb; unchanged boolean:=true; live boolean; approval jsonb; locked_count bigint;
BEGIN
 SELECT c.* INTO STRICT command FROM control.signing_rotation_command c JOIN control.signing_provider_attempt a
  ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id AND a.operation_id=c.operation_id
  WHERE a.attempt_id=p_attempt AND c.participant_id=openpc.current_participant_id()
   AND c.privacy_domain_id=openpc.current_privacy_domain_id()
   AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1';
 snapshot:=convert_from(command.authorization_snapshot,'UTF8')::jsonb;
 IF sha256(command.authorization_snapshot)<>command.authorization_snapshot_digest
  OR snapshot->>'schema'<>'pc.control.precommit-authority-snapshot.v1'
  OR snapshot->>'operationId'<>command.operation_id::text OR snapshot->>'decision'<>'ALLOW'
 THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-RETAINED-AUTHORITY'; END IF;
 FOR dependency IN SELECT * FROM (SELECT 'assignment'::text table_name,'assignment_id'::text column_name,
 2 rank,(d->>'assignment_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') d
UNION ALL
SELECT 'authority_envelope'::text table_name,'authority_envelope_id'::text column_name,
 2 rank,(d->>'authority_envelope_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') d
UNION ALL
SELECT 'authority_role'::text table_name,'authority_role_id'::text column_name,
 undefined rank,(d->>'authority_role_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') d
UNION ALL
SELECT 'credential'::text table_name,'credential_id'::text column_name,
 3 rank,(d->>'credential_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'credential') d
UNION ALL
SELECT 'delegation'::text table_name,'delegation_id'::text column_name,
 3 rank,(d->>'delegation_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') d
UNION ALL
SELECT 'participant'::text table_name,'participant_id'::text column_name,
 0 rank,(d->>'participant_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'participant') d
UNION ALL
SELECT 'principal'::text table_name,'principal_id'::text column_name,
 2 rank,(d->>'principal_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'principal') d
UNION ALL
SELECT 'privacy_domain'::text table_name,'privacy_domain_id'::text column_name,
 1 rank,(d->>'privacy_domain_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') d
UNION ALL
SELECT 'session'::text table_name,'session_id'::text column_name,
 3 rank,(d->>'session_id')::uuid id
 FROM jsonb_array_elements(snapshot->'dependencies'->'session') d) dependencies ORDER BY rank,id,table_name LOOP
  EXECUTE format('SELECT %I FROM control.%I WHERE participant_id=$1 AND %I=$2 FOR SHARE',
   dependency.column_name,dependency.table_name,dependency.column_name) USING command.participant_id,dependency.id;
  GET DIAGNOSTICS locked_count=ROW_COUNT;
  IF locked_count<>1 THEN RAISE EXCEPTION 'DATA-6021-CONTINUATION-MISSING-AUTHORITY'; END IF;
 END LOOP;

 SELECT coalesce(jsonb_agg(jsonb_build_object('assignment_id',owner.assignment_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'authority_group_id',owner.authority_group_id::text,'role_id',owner.role_id::text,'authority_envelope_id',owner.authority_envelope_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'created_by_principal_id',owner.created_by_principal_id::text,'row_version',owner.row_version::text) ORDER BY owner.assignment_id),'[]'::jsonb)
 INTO actual FROM control.assignment owner WHERE owner.participant_id=command.participant_id
 AND owner.assignment_id IN(SELECT (d->>'assignment_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') d);

 -- An immutable pre-migration snapshot omitted runtime grants. Preserve its
 -- comparison/digest shape only while the actual owner still grants none.
 SELECT coalesce(jsonb_agg(CASE WHEN current_row->>'runtime_capability_ids'='{}'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'assignment') retained
     WHERE retained->>'assignment_id'=current_row->>'assignment_id' AND NOT retained ? 'runtime_capability_ids')
   THEN current_row-'runtime_capability_ids' ELSE current_row END ORDER BY current_row->>'assignment_id'),'[]'::jsonb)
 INTO actual FROM jsonb_array_elements(actual) current_row;

 current_rows:=current_rows||jsonb_build_object('assignment',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'assignment'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_envelope_id',owner.authority_envelope_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'maker_principal_id',owner.maker_principal_id::text,'checker_principal_id',owner.checker_principal_id::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'state',owner.state::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'semantic_digest',owner.semantic_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'row_version',owner.row_version::text) ORDER BY owner.authority_envelope_id),'[]'::jsonb)
 INTO actual FROM control.authority_envelope owner WHERE owner.participant_id=command.participant_id
 AND owner.authority_envelope_id IN(SELECT (d->>'authority_envelope_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') d);

 -- An immutable pre-migration snapshot omitted runtime grants. Preserve its
 -- comparison/digest shape only while the actual owner still grants none.
 SELECT coalesce(jsonb_agg(CASE WHEN current_row->>'runtime_capability_ids'='{}'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'authority_envelope') retained
     WHERE retained->>'authority_envelope_id'=current_row->>'authority_envelope_id' AND NOT retained ? 'runtime_capability_ids')
   THEN current_row-'runtime_capability_ids' ELSE current_row END ORDER BY current_row->>'authority_envelope_id'),'[]'::jsonb)
 INTO actual FROM jsonb_array_elements(actual) current_row;

 current_rows:=current_rows||jsonb_build_object('authority_envelope',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'authority_envelope'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('authority_role_id',owner.authority_role_id::text,'participant_id',owner.participant_id::text,'role_id',owner.role_id::text,'action_intent_ids',owner.action_intent_ids::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.authority_role_id),'[]'::jsonb)
 INTO actual FROM control.authority_role owner WHERE owner.participant_id=command.participant_id
 AND owner.authority_role_id IN(SELECT (d->>'authority_role_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'authority_role') d);

 current_rows:=current_rows||jsonb_build_object('authority_role',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'authority_role'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('credential_id',owner.credential_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'kind',owner.kind::text,'state',owner.state::text,'credential_epoch',owner.credential_epoch::text,'valid_from',owner.valid_from::text,'valid_until',owner.valid_until::text,'public_key_digest',owner.public_key_digest::text,'row_version',owner.row_version::text) ORDER BY owner.credential_id),'[]'::jsonb)
 INTO actual FROM control.credential owner WHERE owner.participant_id=command.participant_id
 AND owner.credential_id IN(SELECT (d->>'credential_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'credential') d);

 current_rows:=current_rows||jsonb_build_object('credential',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'credential' AND NOT (
  jsonb_array_length(actual)=jsonb_array_length(snapshot->'dependencies'->'credential') AND NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'credential') retained WHERE NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(actual) current_row WHERE (retained-'row_version')=(current_row-'row_version')
     AND (current_row->>'row_version')::bigint>=(retained->>'row_version')::bigint)))
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('delegation_id',owner.delegation_id::text,'participant_id',owner.participant_id::text,'parent_assignment_id',owner.parent_assignment_id::text,'parent_delegation_id',owner.parent_delegation_id::text,'grantor_principal_id',owner.grantor_principal_id::text,'delegate_principal_id',owner.delegate_principal_id::text,'delegation_epoch',owner.delegation_epoch::text,'scope_digest',owner.scope_digest::text,'privacy_domain_ids',owner.privacy_domain_ids::text,'action_intent_ids',owner.action_intent_ids::text,'runtime_capability_ids',owner.runtime_capability_ids::text,'resource_ids',owner.resource_ids::text,'risk_classes',owner.risk_classes::text,'maker_checker_required',owner.maker_checker_required::text,'step_up_required',owner.step_up_required::text,'onward_delegation_depth',owner.onward_delegation_depth::text,'valid_during',owner.valid_during::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.delegation_id),'[]'::jsonb)
 INTO actual FROM control.delegation owner WHERE owner.participant_id=command.participant_id
 AND owner.delegation_id IN(SELECT (d->>'delegation_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') d);

 -- An immutable pre-migration snapshot omitted runtime grants. Preserve its
 -- comparison/digest shape only while the actual owner still grants none.
 SELECT coalesce(jsonb_agg(CASE WHEN current_row->>'runtime_capability_ids'='{}'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'delegation') retained
     WHERE retained->>'delegation_id'=current_row->>'delegation_id' AND NOT retained ? 'runtime_capability_ids')
   THEN current_row-'runtime_capability_ids' ELSE current_row END ORDER BY current_row->>'delegation_id'),'[]'::jsonb)
 INTO actual FROM jsonb_array_elements(actual) current_row;

 current_rows:=current_rows||jsonb_build_object('delegation',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'delegation'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('participant_id',owner.participant_id::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.participant_id),'[]'::jsonb)
 INTO actual FROM control.participant owner WHERE owner.participant_id=command.participant_id
 AND owner.participant_id IN(SELECT (d->>'participant_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'participant') d);

 current_rows:=current_rows||jsonb_build_object('participant',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'participant'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('principal_id',owner.principal_id::text,'participant_id',owner.participant_id::text,'kind',owner.kind::text,'state',owner.state::text,'authority_epoch',owner.authority_epoch::text,'row_version',owner.row_version::text) ORDER BY owner.principal_id),'[]'::jsonb)
 INTO actual FROM control.principal owner WHERE owner.participant_id=command.participant_id
 AND owner.principal_id IN(SELECT (d->>'principal_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'principal') d);

 current_rows:=current_rows||jsonb_build_object('principal',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'principal'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('privacy_domain_id',owner.privacy_domain_id::text,'participant_id',owner.participant_id::text,'state',owner.state::text,'row_version',owner.row_version::text) ORDER BY owner.privacy_domain_id),'[]'::jsonb)
 INTO actual FROM control.privacy_domain owner WHERE owner.participant_id=command.participant_id
 AND owner.privacy_domain_id IN(SELECT (d->>'privacy_domain_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'privacy_domain') d);

 current_rows:=current_rows||jsonb_build_object('privacy_domain',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'privacy_domain'
 THEN unchanged:=false; END IF;

 SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',owner.session_id::text,'participant_id',owner.participant_id::text,'principal_id',owner.principal_id::text,'state',owner.state::text,'participant_epoch',owner.participant_epoch::text,'authority_epoch',owner.authority_epoch::text,'delegation_epoch',owner.delegation_epoch::text,'session_epoch',owner.session_epoch::text,'issued_at',owner.issued_at::text,'idle_expires_at',owner.idle_expires_at::text,'absolute_expires_at',owner.absolute_expires_at::text,'step_up_verified_at',owner.step_up_verified_at::text,'row_version',owner.row_version::text) ORDER BY owner.session_id),'[]'::jsonb)
 INTO actual FROM control.session owner WHERE owner.participant_id=command.participant_id
 AND owner.session_id IN(SELECT (d->>'session_id')::uuid FROM jsonb_array_elements(snapshot->'dependencies'->'session') d);

 current_rows:=current_rows||jsonb_build_object('session',actual);
 IF actual IS DISTINCT FROM snapshot->'dependencies'->'session' AND NOT (
  jsonb_array_length(actual)=jsonb_array_length(snapshot->'dependencies'->'session') AND NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(snapshot->'dependencies'->'session') retained WHERE NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(actual) current_row WHERE
     (retained-ARRAY['idle_expires_at','row_version'])=(current_row-ARRAY['idle_expires_at','row_version'])
     AND (current_row->>'row_version')::bigint>=(retained->>'row_version')::bigint
     AND (current_row->>'idle_expires_at')::timestamptz>=(retained->>'idle_expires_at')::timestamptz)))
 THEN unchanged:=false; END IF;
 SELECT NOT EXISTS(
  SELECT 1 FROM control.session s WHERE s.participant_id=command.participant_id
   AND s.session_id IN(SELECT (d->>'session_id')::uuid FROM jsonb_array_elements(current_rows->'session') d)
   AND (s.state<>'ACTIVE' OR s.issued_at>clock_timestamp() OR s.idle_expires_at<=clock_timestamp() OR s.absolute_expires_at<=clock_timestamp())
  UNION ALL SELECT 1 FROM control.authority_envelope e WHERE e.participant_id=command.participant_id
   AND e.authority_envelope_id IN(SELECT (d->>'authority_envelope_id')::uuid FROM jsonb_array_elements(current_rows->'authority_envelope') d)
   AND (e.state<>'ACTIVE' OR e.valid_from>clock_timestamp() OR e.valid_until<=clock_timestamp())
  UNION ALL SELECT 1 FROM control.assignment a WHERE a.participant_id=command.participant_id
   AND a.assignment_id IN(SELECT (d->>'assignment_id')::uuid FROM jsonb_array_elements(current_rows->'assignment') d)
   AND (a.state<>'ACTIVE' OR NOT a.valid_during @> clock_timestamp())
  UNION ALL SELECT 1 FROM control.delegation d WHERE d.participant_id=command.participant_id
   AND d.delegation_id IN(SELECT (r->>'delegation_id')::uuid FROM jsonb_array_elements(current_rows->'delegation') r)
   AND (d.state<>'ACTIVE' OR NOT d.valid_during @> clock_timestamp())
  UNION ALL SELECT 1 FROM control.credential c WHERE c.participant_id=command.participant_id
   AND c.credential_id IN(SELECT (d->>'credential_id')::uuid FROM jsonb_array_elements(current_rows->'credential') d)
   AND (c.state<>'ACTIVE' OR c.valid_from>clock_timestamp() OR c.valid_until<=clock_timestamp())
 ) INTO live;
 SELECT jsonb_build_object('approvalRequestId',a.approval_request_id::text,'state',a.state,
  'expiresAt',a.expires_at::text,'candidateDigest',encode(a.subject_digest,'hex'),
  'live',a.state='APPROVED' AND a.expires_at>clock_timestamp()) INTO STRICT approval
 FROM control.approval_request a
 WHERE a.participant_id=command.participant_id AND a.privacy_domain_id=command.privacy_domain_id
  AND a.approval_request_id=command.approval_request_id AND a.subject_digest=command.approval_candidate_digest
 FOR SHARE OF a;
 RETURN jsonb_build_object('unchangedLive',unchanged AND live AND (approval->>'live')::boolean,
  'dependencies',current_rows,'approval',approval);
END $_$;


ALTER FUNCTION openpc.signing_attempt_authority_status(p_attempt uuid) OWNER TO openpc_signing_authority_locker;

--
-- Name: signing_canonical_json(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE encoded text;
BEGIN
 CASE jsonb_typeof(p_value)
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||openpc.signing_canonical_json(value),',' ORDER BY key COLLATE "C"),'')||'}'
  INTO encoded FROM jsonb_each(p_value);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(openpc.signing_canonical_json(value),',' ORDER BY ordinal),'')||']'
  INTO encoded FROM jsonb_array_elements(p_value) WITH ORDINALITY entries(value,ordinal);
 ELSE encoded:=p_value::text;
 END CASE;
 RETURN encoded;
END $$;


ALTER FUNCTION openpc.signing_canonical_json(p_value jsonb) OWNER TO openpc_control_owner;

--
-- Name: signing_continuation_authority_digest(jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_continuation_authority_digest(p_status jsonb) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT sha256(convert_to(jsonb_set(jsonb_set(p_status,'{dependencies,session}',
  (SELECT coalesce(jsonb_agg(value-ARRAY['idle_expires_at','row_version'] ORDER BY value->>'session_id'),'[]'::jsonb)
   FROM jsonb_array_elements(p_status->'dependencies'->'session') value)),'{dependencies,credential}',
  (SELECT coalesce(jsonb_agg(value-'row_version' ORDER BY value->>'credential_id'),'[]'::jsonb)
   FROM jsonb_array_elements(p_status->'dependencies'->'credential') value))::text,'UTF8'))
$$;


ALTER FUNCTION openpc.signing_continuation_authority_digest(p_status jsonb) OWNER TO openpc_control_owner;

--
-- Name: signing_governance_context(uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_governance_context(p_rotation uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rotation control.signing_key_rotation%ROWTYPE; original control.signing_rotation_command%ROWTYPE;
 hold control.signing_rotation_authority_hold%ROWTYPE; prior_generation uuid; attempts jsonb; selections jsonb;
 authority jsonb; session_rows jsonb; first_attempt uuid; target text; resume_state text; resume_revision bigint; effects jsonb;
BEGIN
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND rotation_id=p_rotation;
 IF NOT openpc.signing_governance_required(rotation.participant_id,rotation.privacy_domain_id,p_rotation,p_action)
 THEN RAISE EXCEPTION 'DATA-6021-SIGNING-GOVERNANCE-NOT-REQUIRED'; END IF;
 SELECT * INTO hold FROM control.signing_rotation_authority_hold WHERE participant_id=rotation.participant_id
  AND privacy_domain_id=rotation.privacy_domain_id AND rotation_id=p_rotation AND state='ACTIVE';
 SELECT c.* INTO STRICT original FROM control.signing_rotation_command c WHERE c.participant_id=rotation.participant_id
  AND c.privacy_domain_id=rotation.privacy_domain_id AND c.rotation_id=p_rotation AND c.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1'
  AND ((hold.hold_id IS NOT NULL AND c.operation_id=hold.operation_id) OR
   (hold.hold_id IS NULL AND rotation.state='FAILED' AND c.state='FAILED' AND c.result_revision=rotation.revision AND c.result_kind='PROVIDER_REJECTED') OR
   (hold.hold_id IS NULL AND p_action='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1'
    AND c.state='FAILED' AND c.from_revision=rotation.revision AND c.result_kind='AUTHORITY_CHANGED_BEFORE_DISPATCH'))
  ORDER BY c.updated_at DESC,c.operation_id DESC LIMIT 1;
 SELECT attempt_id INTO STRICT first_attempt FROM control.signing_provider_attempt WHERE participant_id=rotation.participant_id
  AND privacy_domain_id=rotation.privacy_domain_id AND operation_id=original.operation_id AND request->>'method'<>'SIGN_RECEIPT'
  ORDER BY attempt_id LIMIT 1;
 authority:=openpc.signing_attempt_authority_status(first_attempt);
 SELECT coalesce(jsonb_agg(value-ARRAY['idle_expires_at','row_version'] ORDER BY value->>'session_id'),'[]'::jsonb)
  INTO session_rows FROM jsonb_array_elements(authority->'dependencies'->'session') value;
 authority:=jsonb_set(authority,'{dependencies,session}',session_rows);
 SELECT coalesce(jsonb_agg(value-'row_version' ORDER BY value->>'credential_id'),'[]'::jsonb)
  INTO session_rows FROM jsonb_array_elements(authority->'dependencies'->'credential') value;
 authority:=jsonb_set(authority,'{dependencies,credential}',session_rows);
 SELECT generation_id INTO prior_generation FROM control.signing_authorization_generation WHERE participant_id=rotation.participant_id
  AND privacy_domain_id=rotation.privacy_domain_id AND rotation_id=p_rotation AND state='CONSUMED' ORDER BY result_revision DESC LIMIT 1;
 SELECT jsonb_agg(jsonb_build_object('attemptId',a.attempt_id,'method',a.request->>'method','state',a.state,
  'requestDigest',encode(a.request_digest,'hex'),'observationDigest',encode(a.observation_digest,'hex'),
  'dispatchedAtNs',a.dispatched_at_ns::text,'latestObservationDigest',encode(o.observation_digest,'hex')) ORDER BY a.attempt_id)
 INTO attempts FROM control.signing_provider_attempt a LEFT JOIN LATERAL(SELECT observation_digest FROM control.signing_rotation_observation
  WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id
  ORDER BY observed_at_ns DESC,observation_id DESC LIMIT 1) o ON true
 WHERE a.participant_id=rotation.participant_id AND a.privacy_domain_id=rotation.privacy_domain_id AND a.operation_id=original.operation_id
  AND a.request->>'method'<>'SIGN_RECEIPT';
 SELECT jsonb_agg(jsonb_build_object('profileDigest',encode(s.profile_digest,'hex'),'signerId',s.signer_id,
  'selectionVersion',s.row_version::text,'admissionVersion',s.admission_version::text,'fenceGeneration',s.fence_generation::text,'fencedOperationId',s.fenced_operation_id)
  ORDER BY s.profile_digest) INTO selections FROM control.business_signing_selection s JOIN control.business_signing_key k
  USING(participant_id,privacy_domain_id,signer_id) WHERE s.participant_id=rotation.participant_id AND s.privacy_domain_id=rotation.privacy_domain_id
  AND s.environment_id=rotation.environment_id AND k.workload_credential_id=rotation.workload_credential_id;
 IF p_action='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' THEN target:=original.to_state;
 ELSIF rotation.state='FAILED' THEN
  target:='RECOVERING';
  SELECT from_state,from_revision INTO STRICT resume_state,resume_revision FROM control.signing_provider_attempt
   WHERE attempt_id=first_attempt;
 ELSE target:=rotation.state; resume_state:=rotation.recovery_from_state; resume_revision:=rotation.recovery_from_revision;
 END IF;
 effects:=openpc.signing_transition_effects(p_action,rotation.state,target);
 IF effects IS NULL THEN RAISE EXCEPTION 'DATA-6022-SIGNING-GOVERNANCE-MATRIX'; END IF;
 RETURN jsonb_build_object('schema','pc.control.signing-governance-context.v1','participantId',rotation.participant_id,
  'privacyDomainId',rotation.privacy_domain_id,'rotationId',p_rotation,'actionIntentId',p_action,'revision',rotation.revision::text,
  'state',rotation.state,'cutoverAtNs',rotation.cutover_at_ns::text,'newFingerprint',rotation.new_signer_id,
  'holdId',hold.hold_id,'holdReason',hold.reason,'originalOperationId',original.operation_id,
  'originalInputDigest',encode(original.input_digest,'hex'),'originalAuthorityDigest',encode(original.authorization_snapshot_digest,'hex'),
  'originalApprovalId',original.approval_request_id,'originalApprovalDigest',encode(original.approval_candidate_digest,'hex'),
  'originalAuthority',authority,'attempts',attempts,'selections',selections,'priorGenerationId',prior_generation,
  'targetState',target,'resumeState',resume_state,'resumeRevision',resume_revision::text);
END $$;


ALTER FUNCTION openpc.signing_governance_context(p_rotation uuid, p_action text) OWNER TO openpc_control_owner;

--
-- Name: signing_governance_required(uuid, uuid, uuid, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_governance_required(p_participant uuid, p_privacy uuid, p_rotation uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM control.signing_key_rotation r WHERE r.participant_id=p_participant AND r.privacy_domain_id=p_privacy
  AND r.rotation_id=p_rotation AND ((p_action='ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1' AND
   (r.state='FAILED' OR EXISTS(SELECT 1 FROM control.signing_rotation_authority_hold h
     WHERE h.participant_id=r.participant_id AND h.privacy_domain_id=r.privacy_domain_id AND h.rotation_id=r.rotation_id AND h.state='ACTIVE')))
   OR (p_action='ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1' AND EXISTS(SELECT 1 FROM control.signing_rotation_command c
    WHERE c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id AND c.rotation_id=r.rotation_id
     AND c.from_revision=r.revision AND c.state='FAILED' AND c.result_kind='AUTHORITY_CHANGED_BEFORE_DISPATCH'))))
$$;


ALTER FUNCTION openpc.signing_governance_required(p_participant uuid, p_privacy uuid, p_rotation uuid, p_action text) OWNER TO openpc_control_owner;

--
-- Name: signing_provider_attempt; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.signing_provider_attempt (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    rotation_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    from_revision bigint NOT NULL,
    from_state text NOT NULL,
    slot text NOT NULL,
    to_state text NOT NULL,
    request jsonb NOT NULL,
    request_digest bytea NOT NULL,
    observation jsonb,
    observation_digest bytea,
    dispatched_at_ns numeric(20,0),
    state text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT signing_attempt_digest_ck CHECK (((octet_length(request_digest) = 32) AND (from_revision > 0))),
    CONSTRAINT signing_attempt_observation_ck CHECK ((((state = ANY (ARRAY['READY'::text, 'DISPATCHING'::text, 'SUPERSEDED'::text, 'CANCELLED'::text])) AND (observation IS NULL) AND (observation_digest IS NULL)) OR ((state <> ALL (ARRAY['READY'::text, 'DISPATCHING'::text, 'CANCELLED'::text])) AND (observation IS NOT NULL) AND (octet_length(observation_digest) = 32)))),
    CONSTRAINT signing_attempt_state_ck CHECK ((state = ANY (ARRAY['READY'::text, 'DISPATCHING'::text, 'OBSERVED'::text, 'ACCEPTED'::text, 'REJECTED'::text, 'SUPERSEDED'::text, 'CANCELLED'::text])))
);

ALTER TABLE ONLY control.signing_provider_attempt FORCE ROW LEVEL SECURITY;


ALTER TABLE control.signing_provider_attempt OWNER TO openpc_control_owner;

--
-- Name: signing_observation_preimage(control.signing_provider_attempt, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_observation_preimage(a control.signing_provider_attempt, p_kind text) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT convert_to(jsonb_build_object('schema','pc.control.signing-observation.v1',
  'participantId',a.participant_id,'privacyDomainId',a.privacy_domain_id,'rotationId',a.rotation_id,
  'operationId',a.operation_id,'attemptId',a.attempt_id,'method',a.request->>'method',
  'requestDigest',encode(a.request_digest,'hex'),'kind',p_kind,
  'providerObservationDigest',CASE WHEN p_kind='PROVIDER_RESULT' THEN encode(a.observation_digest,'hex') ELSE NULL END)::text,'UTF8')
$$;


ALTER FUNCTION openpc.signing_observation_preimage(a control.signing_provider_attempt, p_kind text) OWNER TO openpc_control_owner;

--
-- Name: signing_operation_failure_preimage(uuid, text, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_operation_failure_preimage(p_attempt uuid, p_kind text, p_assertion uuid) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a control.signing_provider_attempt%ROWTYPE; c control.signing_rotation_command%ROWTYPE;
 authority jsonb; assertion control.signing_continuation%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM control.signing_provider_attempt WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND attempt_id=p_attempt;
 SELECT * INTO STRICT c FROM control.signing_rotation_command WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id;
 IF c.operation_id IS DISTINCT FROM openpc.current_operation_id() OR c.action_intent_id<>'ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1'
  OR openpc.current_action_intent_id()<>c.action_intent_id THEN RAISE EXCEPTION 'DATA-6021-NO-EFFECT-CONTEXT'; END IF;
 IF p_kind='AUTHORITY_CHANGED_BEFORE_DISPATCH' THEN
  authority:=openpc.signing_attempt_authority_status(p_attempt);
  IF p_assertion IS NOT NULL OR (authority->>'unchangedLive')::boolean OR a.dispatched_at_ns IS NOT NULL
   OR EXISTS(SELECT 1 FROM control.signing_provider_attempt other WHERE other.participant_id=a.participant_id
    AND other.privacy_domain_id=a.privacy_domain_id AND other.operation_id=a.operation_id
    AND (other.state NOT IN ('READY','CANCELLED') OR other.dispatched_at_ns IS NOT NULL OR other.observation IS NOT NULL))
  THEN RAISE EXCEPTION 'DATA-6021-UNDISPATCHED-AUTHORITY-FAILURE'; END IF;
 ELSIF p_kind='NO_EFFECT_RETRYABLE' THEN
  SELECT * INTO STRICT assertion FROM control.signing_continuation WHERE participant_id=a.participant_id
   AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id AND provider_attempt_id=a.attempt_id
   AND assertion_id=p_assertion AND state IN ('ISSUED','CONSUMED');
  IF a.state NOT IN ('OBSERVED','REJECTED') OR a.dispatched_at_ns IS NULL OR a.observation->>'outcome' IS DISTINCT FROM 'REJECTED'
   OR a.observation->>'reason' IS DISTINCT FROM 'NOT_APPLIED'
   OR convert_from(assertion.context_preimage,'UTF8')::jsonb->>'resultDisposition' IS DISTINCT FROM 'NO_EFFECT_RETRYABLE'
  THEN RAISE EXCEPTION 'DATA-6021-PROVIDER-NO-EFFECT-GUARANTEE'; END IF;
 ELSE RAISE EXCEPTION 'DATA-6021-NO-EFFECT-KIND'; END IF;
 RETURN convert_to(jsonb_build_object('schema','pc.control.signing-rotation-operation-result.v1','participantId',a.participant_id,
  'privacyDomainId',a.privacy_domain_id,'rotationId',a.rotation_id,'operationId',c.operation_id,'kind',p_kind,
  'candidateDigest',encode(c.input_digest,'hex'),'revision',c.from_revision,'currentRevision',(SELECT r.revision FROM control.signing_key_rotation r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.rotation_id=c.rotation_id),'providerAttemptId',a.attempt_id,
  'providerRequestDigest',encode(a.request_digest,'hex'),'dispatchedAtNs',a.dispatched_at_ns,
  'providerObservationDigest',encode(a.observation_digest,'hex'),'originalAuthoritySnapshotDigest',encode(c.authorization_snapshot_digest,'hex'),
  'currentAuthority',authority,'continuationAssertionId',p_assertion,'continuationAssertionDigest',encode(assertion.assertion_digest,'hex'))::text,'UTF8');
END $$;


ALTER FUNCTION openpc.signing_operation_failure_preimage(p_attempt uuid, p_kind text, p_assertion uuid) OWNER TO openpc_control_owner;

--
-- Name: signing_transition_effects(text, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.signing_transition_effects(p_action text, p_prior text, p_target text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
