 SELECT effects::jsonb FROM (VALUES ('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','APPROVED','PREPARED','{"kind":"ADVANCE","providerSteps":[["new","PREPARE"]],"prepare":true,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','PREPARED','{"kind":"ADVANCE","providerSteps":[["new","PREPARE"]],"prepare":true,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"APPROVED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','APPROVED','APPROVED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','APPROVED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','PREPARED','DISTRIBUTED','{"kind":"ADVANCE","providerSteps":[["new","DISTRIBUTE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','DISTRIBUTED','{"kind":"ADVANCE","providerSteps":[["new","DISTRIBUTE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"PREPARED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','PREPARED','PREPARED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','PREPARED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','DISTRIBUTED','VERIFIED','{"kind":"ADVANCE","providerSteps":[["old","PROVE"],["new","PROVE"]],"prepare":false,"admitTrust":true,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','VERIFIED','{"kind":"ADVANCE","providerSteps":[["old","PROVE"],["new","PROVE"]],"prepare":false,"admitTrust":true,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"DISTRIBUTED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','DISTRIBUTED','DISTRIBUTED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','DISTRIBUTED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','VERIFIED','CUTOVER_FENCED','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":true,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','CUTOVER_FENCED','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":true,"revoke":false,"eventType":null,"resumeFrom":"VERIFIED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','VERIFIED','VERIFIED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','VERIFIED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','CUTOVER_FENCED','OBSERVING','{"kind":"ADVANCE","providerSteps":[["effective","PROVE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OBSERVING','{"kind":"ADVANCE","providerSteps":[["effective","PROVE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"CUTOVER_FENCED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','CUTOVER_FENCED','CUTOVER_FENCED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','CUTOVER_FENCED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OBSERVING','OLD_REVOKED','{"kind":"ADVANCE","providerSteps":[["old","REVOKE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":true,"eventType":"io.openpc.ops.secret.revoked.v1","resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OLD_REVOKED','{"kind":"ADVANCE","providerSteps":[["old","REVOKE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":true,"eventType":"io.openpc.ops.secret.revoked.v1","resumeFrom":"OBSERVING"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OBSERVING','OBSERVING','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OBSERVING','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_REVOKED','OLD_RETIRED','{"kind":"ADVANCE","providerSteps":[["old","RETIRE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OLD_RETIRED','{"kind":"ADVANCE","providerSteps":[["old","RETIRE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"OLD_REVOKED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_REVOKED','OLD_REVOKED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_REVOKED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_RETIRED','COMPLETE','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":"io.openpc.ops.secret.rotated.v1","resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','COMPLETE','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":"io.openpc.ops.secret.rotated.v1","resumeFrom":"OLD_RETIRED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_RETIRED','OLD_RETIRED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_RETIRED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','APPROVED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','PREPARED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','DISTRIBUTED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','VERIFIED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','CUTOVER_FENCED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OBSERVING','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_REVOKED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_RETIRED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','RECOVERING','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','FAILED','RECOVERING','{"kind":"FORWARD_RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}')) matrix(action,prior,target,effects)
 WHERE action=p_action AND prior=p_prior AND target=p_target
$$;


ALTER FUNCTION openpc.signing_transition_effects(p_action text, p_prior text, p_target text) OWNER TO openpc_control_owner;

--
-- Name: store_retirement_admission; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.store_retirement_admission (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    verification_nonce bytea NOT NULL,
    verification_mac bytea NOT NULL,
    retirement_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    previous_attempt_id uuid,
    host_digest text NOT NULL,
    retention_policy_id uuid NOT NULL,
    approval_request_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    attempt_wire bytea NOT NULL,
    attempt_digest text NOT NULL,
    selection_digest text NOT NULL,
    source_binding jsonb NOT NULL,
    source_binding_digest text NOT NULL,
    lifecycle_revision numeric(20,0) NOT NULL,
    dispatch_not_after_ms numeric(20,0) NOT NULL,
    revision numeric(20,0) DEFAULT '1'::numeric NOT NULL,
    admitted_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT store_retirement_admission_revision_ck CHECK ((((lifecycle_revision >= (1)::numeric) AND (lifecycle_revision <= ('9223372036854775807'::bigint)::numeric)) AND (revision = (1)::numeric) AND (previous_attempt_id IS DISTINCT FROM attempt_id) AND (dispatch_not_after_ms > floor((EXTRACT(epoch FROM admitted_at) * (1000)::numeric))) AND (dispatch_not_after_ms <= (floor((EXTRACT(epoch FROM admitted_at) * (1000)::numeric)) + (60000)::numeric)))),
    CONSTRAINT store_retirement_admission_source_ck CHECK (((jsonb_typeof(source_binding) = 'object'::text) AND ((octet_length((source_binding)::text) >= 1) AND (octet_length((source_binding)::text) <= 1048576)) AND (source_binding_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT store_retirement_admission_verifier_ck CHECK (((octet_length(verification_nonce) = 32) AND (octet_length(verification_mac) = 32))),
    CONSTRAINT store_retirement_admission_wire_ck CHECK ((((octet_length(attempt_wire) >= 1) AND (octet_length(attempt_wire) <= 1048576)) AND (attempt_digest ~ '^[0-9a-f]{64}$'::text) AND (selection_digest ~ '^[0-9a-f]{64}$'::text)))
);

ALTER TABLE ONLY control.store_retirement_admission FORCE ROW LEVEL SECURITY;


ALTER TABLE control.store_retirement_admission OWNER TO openpc_control_owner;

--
-- Name: store_retirement_committed_digest(control.store_retirement_admission); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.store_retirement_committed_digest(a control.store_retirement_admission) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt text;
BEGIN
 SELECT encode(receipt_digest,'hex') INTO STRICT receipt FROM control.audit_occurrence
  WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id
   AND aggregate_type='store-retirement' AND aggregate_id=a.attempt_id AND profile_id='pc.control.store-retirement.admit';
 RETURN encode(sha256(convert_to('["OPENPC_STORE_RETIREMENT_COMMITTED_V1",'||to_json(a.host_digest)::text||','||
  to_json(a.attempt_digest)::text||','||to_json(receipt)::text||','||to_json(substring(a.source_binding_digest from 8))::text||','||
  a.dispatch_not_after_ms::text||']','UTF8')),'hex');
END $$;


ALTER FUNCTION openpc.store_retirement_committed_digest(a control.store_retirement_admission) OWNER TO openpc_control_owner;

--
-- Name: store_retirement_lifecycle_revision(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.store_retirement_lifecycle_revision(p uuid, d uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT 1+coalesce((SELECT sum(revision) FROM control.retention_hold
  WHERE participant_id=p AND (selector_type='PARTICIPANT' OR privacy_domain_id=d)),0)
  +coalesce((SELECT sum(revision) FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d),0)
$$;


ALTER FUNCTION openpc.store_retirement_lifecycle_revision(p uuid, d uuid) OWNER TO openpc_control_owner;

--
-- Name: store_retirement_source_binding(uuid, bytea, jsonb); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.store_retirement_source_binding(policy_id uuid, selection_wire bytea, record_refs jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 rule control.retention_policy; selection jsonb; refs jsonb:='[]'::jsonb; manifest jsonb:='[]'::jsonb;
 acknowledgements jsonb:='[]'::jsonb; selected jsonb; ref jsonb; actual record; sinks jsonb;
 ack_ms numeric; eligible_ms numeric:=0; row_index integer:=0; latest numeric;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF octet_length(selection_wire) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 selection:=convert_from(selection_wire,'UTF8')::jsonb;
 IF selection->>'class'='CANDIDATE_PROJECTION' THEN
  RETURN openpc.candidate_retirement_source_binding(policy_id,selection_wire,record_refs);
 END IF;
 IF selection->>'class' IS DISTINCT FROM 'ADMITTED_FACT' THEN RAISE EXCEPTION 'PC-DATA-6007-UNSUPPORTED-SOURCE'; END IF;
 IF jsonb_typeof(selection->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(selection->'rows') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(record_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(record_refs)<>jsonb_array_length(selection->'rows') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d
  AND retention_policy_id=policy_id AND data_class='ADMITTED_FACT' AND deletion_mode='ROW_DELETE' AND active_until IS NULL;
 FOR selected IN SELECT value FROM jsonb_array_elements(selection->'rows') LOOP
  ref:=record_refs->row_index;
  IF ref IS DISTINCT FROM jsonb_build_object('candidateId',selected->>'candidate_id','evidenceId',ref->>'evidenceId')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT c.evidence_id,c.stream_id,c.record_id,c.sequence,c.receipt_digest,c.occurred_at,
   s.segment_id,s.object_digest,s.first_sequence,s.through_sequence,s.admitted_at
  INTO STRICT actual FROM control.evidence_catalogue c JOIN control.evidence_segment s
   USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_stream h USING(participant_id,privacy_domain_id,stream_id)
  WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.evidence_id=(ref->>'evidenceId')::uuid
   AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
   AND c.receipt_digest='sha256:'||(selected->>'signed_fact_digest')
   AND c.sequence BETWEEN s.first_sequence AND s.through_sequence AND h.last_sequence>=s.through_sequence;
  IF EXISTS(SELECT 1 FROM control.retention_hold hold WHERE hold.participant_id=p
   AND (hold.selector_type='PARTICIPANT' OR hold.privacy_domain_id=d) AND hold.state='ACTIVE'
   AND openpc.evidence_hold_matches(hold.selector,p,d,actual.stream_id,actual.segment_id))
   THEN RAISE EXCEPTION 'PC-DATA-6007-ACTIVE-HOLD'; END IF;
  -- A complete original checkpoint remains required even for a zero-quorum
  -- policy. This never changes the independent archive's retention deadline.
  IF NOT EXISTS(SELECT 1 FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
   AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
   AND c.through_sequence=actual.through_sequence) THEN RAISE EXCEPTION 'PC-DATA-6007-CHECKPOINT'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',s.sink_id,'checkpointDigest',s.checkpoint_digest,
   'receiptDigest',s.receipt_digest,'acknowledgedAtMicros',s.ack_micros::text) ORDER BY s.ack_micros,s.sink_id),'[]'::jsonb),
   max(ceil(s.ack_micros/1000)) INTO sinks,ack_ms FROM (
    SELECT c.sink_id,c.checkpoint_digest,c.receipt_digest,floor(extract(epoch from c.acknowledged_at)*1000000) ack_micros
     FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
      AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
      AND c.through_sequence=actual.through_sequence AND c.receipt->>'receiptDigest'=c.receipt_digest
      AND c.receipt->'object'->>'objectDigest'=actual.object_digest
     ORDER BY c.acknowledged_at,c.sink_id LIMIT rule.sink_quorum
   ) s;
  IF jsonb_array_length(sinks)<>rule.sink_quorum THEN RAISE EXCEPTION 'PC-DATA-6007-SINK-QUORUM'; END IF;
  latest:=greatest(ceil(extract(epoch from actual.occurred_at)*1000)+rule.retention_period_ms,
    coalesce(ack_ms,ceil(extract(epoch from actual.admitted_at)*1000))+rule.local_grace_ms);
  eligible_ms:=greatest(eligible_ms,latest);
  refs:=refs||jsonb_build_array(ref);
  manifest:=manifest||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id',
    'evidenceId',actual.evidence_id::text,'streamId',actual.stream_id,'recordId',actual.record_id,
    'sequence',actual.sequence::text,'recordDigest',actual.receipt_digest,'segmentId',actual.segment_id::text,
    'objectDigest',actual.object_digest));
  acknowledgements:=acknowledgements||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id','sinkReceipts',sinks));
  row_index:=row_index+1;
 END LOOP;
 IF eligible_ms>floor(extract(epoch from clock_timestamp())*1000) OR eligible_ms>9223372036854775807
  THEN RAISE EXCEPTION 'PC-DATA-6007-RETENTION'; END IF;
 RETURN jsonb_build_object('version','OPENPC_STORE_RETIREMENT_SOURCE_V1','selectionWireHex',encode(selection_wire,'hex'),
  'recordRefs',refs,'manifest',manifest,'acknowledgements',acknowledgements,
  'archiveManifestDigest',encode(sha256(convert_to(openpc.signing_canonical_json(manifest),'UTF8')),'hex'),
  'archiveAcknowledgementDigest',encode(sha256(convert_to(openpc.signing_canonical_json(acknowledgements),'UTF8')),'hex'),
  'retentionNotBeforeMs',eligible_ms::text,'lifecycleRevision',openpc.store_retirement_lifecycle_revision(p,d)::text);
END $$;


ALTER FUNCTION openpc.store_retirement_source_binding(policy_id uuid, selection_wire bytea, record_refs jsonb) OWNER TO openpc_control_owner;

--
-- Name: store_retirement_state_projection(control.store_retirement_admission); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.store_retirement_state_projection(a control.store_retirement_admission) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',openpc.business_bytes(decode((a).host_digest,'hex')),
  '1',openpc.business_bytes(decode((a).attempt_digest,'hex')),
  '2',openpc.business_bytes(decode((a).selection_digest,'hex')),
  '3',openpc.business_bytes(decode(substring((a).source_binding_digest from 8),'hex')),
  '4',openpc.business_uuid((a).retention_policy_id),'5',openpc.business_uuid((a).approval_request_id),
  '6',openpc.business_uuid((a).operation_id),'7',openpc.business_uuid((a).retirement_id),
  '8',CASE WHEN (a).previous_attempt_id IS NULL THEN openpc.business_bytes(''::bytea) ELSE openpc.business_uuid((a).previous_attempt_id) END,
  '9',(a).lifecycle_revision,'10',floor(extract(epoch from (a).admitted_at)*1000000)*1000,
  '11',(a).dispatch_not_after_ms)
$$;


ALTER FUNCTION openpc.store_retirement_state_projection(a control.store_retirement_admission) OWNER TO openpc_control_owner;

--
-- Name: sync_deployment_address_claims(); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.sync_deployment_address_claims() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id) THEN
  RAISE EXCEPTION 'PC-DATA-6004';
 END IF;
 IF TG_OP='INSERT' AND NEW.predecessor_command_id IS NULL THEN
  INSERT INTO control.deployment_address_claim
   (attempt_id,participant_id,privacy_domain_id,chain_id,genesis_digest,address,active)
   SELECT NEW.attempt_id,NEW.participant_id,NEW.privacy_domain_id,NEW.chain_id,NEW.genesis_digest,address,true
   FROM unnest(ARRAY[NEW.contract_address,NEW.helper_address]) claimed(address)
   WHERE address IS NOT NULL ORDER BY address;
 ELSIF NEW.state='EXPIRED' THEN
  UPDATE control.deployment_address_claim SET active=false
   WHERE attempt_id=NEW.attempt_id AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION openpc.sync_deployment_address_claims() OWNER TO openpc_control_owner;

--
-- Name: deployment_result; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.deployment_result (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid NOT NULL,
    command_id uuid NOT NULL,
    sequence numeric(20,0) NOT NULL,
    signed_bytes bytea NOT NULL,
    result_digest text NOT NULL,
    created_at timestamp(6) with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT deployment_result_bytes_ck CHECK (((octet_length(signed_bytes) >= 1) AND (octet_length(signed_bytes) <= 16384))),
    CONSTRAINT deployment_result_digest_ck CHECK ((result_digest = ('sha256:'::text || encode(sha256(signed_bytes), 'hex'::text)))),
    CONSTRAINT deployment_result_sequence_ck CHECK (((sequence >= (1)::numeric) AND (sequence <= '18446744073709551615'::numeric)))
);


ALTER TABLE control.deployment_result OWNER TO openpc_control_owner;

--
-- Name: validate_deployment_rejection(control.deployment_result); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.validate_deployment_rejection(result control.deployment_result) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE claims jsonb; expected jsonb; issued_at timestamptz; expires_at timestamptz;
BEGIN
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.lock_deployment_command(result.command_id);
 claims:=convert_from(result.signed_bytes,'UTF8')::jsonb->'claims';
 IF NOT openpc.matches_participant(result.participant_id) OR NOT openpc.matches_privacy(result.privacy_domain_id)
  OR result.sequence<>1 OR claims->>'schema' IS DISTINCT FROM 'PC-DEPLOYMENT-RESERVATION-REJECTION-1'
  OR NOT coalesce(claims->>'reason' IN ('CUSTODY_CONFLICT','PREPARATION_EXPIRED','MODULE_GENERATION_UNAVAILABLE'),false)
  OR NOT coalesce(claims->'binding'->>'transactionHash' ~ '^0x[0-9a-f]{64}$',false)
  OR EXISTS(SELECT 1 FROM control.deployment_address_reservation WHERE command_id=result.command_id)
  OR EXISTS(SELECT 1 FROM control.deployment_result prior WHERE prior.command_id=result.command_id)
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF claims->>'reason'='MODULE_GENERATION_UNAVAILABLE' THEN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('module-admission:'||result.participant_id::text||':'||result.privacy_domain_id::text,0));
  IF EXISTS(SELECT 1 FROM control.deployment_intent i WHERE i.participant_id=result.participant_id
   AND i.privacy_domain_id=result.privacy_domain_id
   AND i.preparation_digest='sha256:'||(claims->'binding'->>'preparationDigest')
   AND i.module_generation_digest IS NOT NULL
   AND i.module_generation_digest=openpc.deployment_module_generation(i.participant_id,i.privacy_domain_id))
  THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 END IF;
 SELECT jsonb_build_object(
   'targetRuntimeId',intent.runtime_target_id::text,
   'owner',jsonb_build_object('participant_id',candidate.participant_id::text,
     'privacy_domain_id',candidate.privacy_domain_id::text,'actor_principal_id',intent.execution_principal_id::text,
     'workload_id',intent.execution_workload_id),
   'commandId',candidate.consumed_operation_id::text,'attemptId',candidate.resource_id::text,
   'intentDigest',substring(intent.intent_digest from 8),'preparationDigest',substring(intent.preparation_digest from 8),
   'chainId',prepared.document->'intent'->>'chainId','genesisDigest',prepared.document->'intent'->>'genesisHash',
   'transactionHash',claims->'binding'->>'transactionHash'),candidate.created_at,intent.expires_at
 INTO STRICT expected,issued_at,expires_at
 FROM control.mutation_candidate candidate
 JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
  AND receipt.privacy_domain_id=candidate.privacy_domain_id AND receipt.operation_id=candidate.consumed_operation_id
  AND receipt.catalog_operation_id=candidate.catalog_operation_id AND receipt.input_digest=candidate.candidate_digest
  AND receipt.principal_id=candidate.maker_principal_id AND receipt.terminal_state='COMMITTED'
 JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
  AND evidence.privacy_domain_id=candidate.privacy_domain_id AND evidence.operation_id=candidate.consumed_operation_id
  AND evidence.catalog_operation_id=candidate.catalog_operation_id AND evidence.candidate_digest=candidate.candidate_digest
  AND evidence.aggregate_id=candidate.resource_id AND evidence.aggregate_type='deployment-submission'
 JOIN control.deployment_intent intent ON intent.participant_id=candidate.participant_id
  AND intent.privacy_domain_id=candidate.privacy_domain_id AND intent.actor_principal_id=candidate.maker_principal_id
  AND candidate.candidate_document->>'deploymentIntentId'='urn:openpc:resource:'||intent.deployment_intent_id::text
 CROSS JOIN LATERAL (SELECT convert_from(intent.preparation_bytes,'UTF8')::jsonb document) prepared
 WHERE candidate.participant_id=result.participant_id AND candidate.privacy_domain_id=result.privacy_domain_id
  AND candidate.consumed_operation_id=result.command_id AND candidate.state='CONSUMED'
  AND candidate.catalog_operation_id='CFG-OP-SUBMIT-DEPLOYMENT'
  AND candidate.action_intent_id='ACT-DEPLOYMENT_SUBMISSIONS_CREATE_RESOURCE-V1'
  AND candidate.resource_type='deployment-submission' AND candidate.operation_class='CREATE'
  AND encode(candidate.candidate_digest,'hex')=claims->>'candidateDigest'
  AND encode(evidence.evidence_digest,'hex')=claims->>'authorizationEvidenceDigest';
 IF claims->'binding' IS DISTINCT FROM expected OR claims->>'observedAt' IS NULL
  OR (claims->>'observedAt')::timestamptz<issued_at
  OR (claims->>'observedAt')::timestamptz>clock_timestamp()+interval '5 seconds'
  OR (claims->>'reason'='PREPARATION_EXPIRED' AND
    (expires_at>clock_timestamp() OR (claims->>'observedAt')::timestamptz<expires_at))
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
END $_$;


ALTER FUNCTION openpc.validate_deployment_rejection(result control.deployment_result) OWNER TO openpc_control_owner;

--
-- Name: verify_fleet_delivery_capability(bytea, bytea, bytea, text, text); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.verify_fleet_delivery_capability(material bytea, nonce bytea, mac bytea, profile_digest text, purpose text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE secret bytea; expected bytea; difference integer:=0; value jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL OR octet_length(material) NOT BETWEEN 1 AND 65536
  OR octet_length(nonce)<>32 OR octet_length(mac)<>32 OR coalesce(profile_digest,'')!~'^sha256:[0-9a-f]{64}$'
  OR openpc.current_action_intent_id()<>'ACT-OPERATIONS_READ_OPERATION-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to(purpose,'UTF8')||decode(substring(profile_digest from 8),'hex')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP difference:=difference | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 value:=convert_from(material,'UTF8')::jsonb;
 IF convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(value)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN value;
END $_$;


ALTER FUNCTION openpc.verify_fleet_delivery_capability(material bytea, nonce bytea, mac bytea, profile_digest text, purpose text) OWNER TO openpc_control_owner;

--
-- Name: verify_runtime_artifact_source_commit(uuid, bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.verify_runtime_artifact_source_commit(source_id uuid, wire bytea, nonce bytea, mac bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF octet_length(nonce) IS DISTINCT FROM 32 OR octet_length(mac) IS DISTINCT FROM 32
  OR octet_length(wire) NOT BETWEEN 1 AND 8192 OR wire IS NULL
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1'
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT k.verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key k
  JOIN control.runtime_artifact_source s USING(participant_id,privacy_domain_id,source_owner_id)
  WHERE k.participant_id=openpc.current_participant_id() AND k.privacy_domain_id=openpc.current_privacy_domain_id()
   AND k.source_owner_id=source_id AND s.database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_SOURCE_DENIAL_COMMIT_V1'||pg_current_xact_id()::text
  ||encode(sha256(wire),'hex'),'UTF8')||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;


ALTER FUNCTION openpc.verify_runtime_artifact_source_commit(source_id uuid, wire bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

--
-- Name: verify_store_retirement_commit(uuid, uuid, text, text, bytea, bytea, bytea); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.verify_store_retirement_commit(p uuid, d uuid, host text, domain text, binding bytea, nonce bytea, mac bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF p IS DISTINCT FROM current_setting('openpc.participant_id')::uuid
  OR d IS DISTINCT FROM current_setting('openpc.privacy_domain_id')::uuid
  OR domain NOT IN ('SOURCE','DELIVERY','OUTCOME') OR domain IS NULL
  OR octet_length(nonce) IS DISTINCT FROM 32 OR octet_length(mac) IS DISTINCT FROM 32
  OR octet_length(binding) IS DISTINCT FROM 32 OR host!~'^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF domain='SOURCE' THEN
  IF NOT pg_has_role(session_user,'openpc_control_runtime','USAGE')
   OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 ELSE PERFORM openpc.lock_store_retirement_workload(host); END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.store_retirement_verifier_key
  WHERE participant_id=p AND privacy_domain_id=d AND host_digest=host;
 expected:=public.hmac(convert_to('OPENPC_STORE_RETIREMENT_'||domain||'_COMMIT_V1','UTF8')
  ||uuid_send(p)||uuid_send(d)||decode(host,'hex')||binding||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $_$;


ALTER FUNCTION openpc.verify_store_retirement_commit(p uuid, d uuid, host text, domain text, binding bytea, nonce bytea, mac bytea) OWNER TO openpc_control_owner;

--
-- Name: work_item_business_projection(control.work_item); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.work_item_business_projection(item control.work_item) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',(item).kind,'1',(item).state,
  '2',(item).resource_ref,'3',openpc.business_bytes((item).payload_digest),
  '4',openpc.business_bytes(sha256(convert_to((item).reason,'UTF8'))),
  '5',openpc.business_uuid((item).created_by_principal_id),
  '6',CASE WHEN (item).assignee_principal_id IS NULL THEN 0 ELSE 1 END,
  '8',CASE WHEN (item).claimed_by_principal_id IS NULL THEN 0 ELSE 1 END,
  '10',CASE WHEN (item).completed_by_principal_id IS NULL THEN 0 ELSE 1 END)
  || CASE WHEN (item).assignee_principal_id IS NULL THEN '{}'::jsonb
     ELSE jsonb_build_object('7',openpc.business_uuid((item).assignee_principal_id)) END
  || CASE WHEN (item).claimed_by_principal_id IS NULL THEN '{}'::jsonb
     ELSE jsonb_build_object('9',openpc.business_uuid((item).claimed_by_principal_id)) END
  || CASE WHEN (item).completed_by_principal_id IS NULL THEN '{}'::jsonb
     ELSE jsonb_build_object('11',openpc.business_uuid((item).completed_by_principal_id)) END
$$;


ALTER FUNCTION openpc.work_item_business_projection(item control.work_item) OWNER TO openpc_control_owner;

--
-- Name: workload_renewal_participant_security_epoch(uuid, uuid); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.workload_renewal_participant_security_epoch(wanted_participant uuid, wanted_privacy uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE history_oid oid; history_owner text; enabled boolean; forced boolean; policies jsonb; epoch numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=current_user AND NOT r.rolsuper AND NOT r.rolbypassrls)
   OR NOT (pg_has_role(current_user,'openpc_control_runtime','USAGE')
    OR pg_has_role(current_user,'openpc_control_worker','USAGE')
    OR pg_has_role(current_user,'openpc_control_reader','USAGE')
    OR pg_has_role(current_user,'openpc_control_platform_runtime','USAGE'))
   OR pg_has_role(current_user,'openpc_control_owner','MEMBER')
   OR pg_has_role(current_user,'openpc_control_key_governor','MEMBER')
   OR pg_has_role(current_user,'openpc_control_maintenance','MEMBER')
   OR current_setting('row_security')<>'on'
   OR openpc.current_participant_id() IS DISTINCT FROM wanted_participant
   OR openpc.current_privacy_domain_id() IS DISTINCT FROM wanted_privacy THEN
  RAISE EXCEPTION 'DATA-6021-RENEWAL-SECURITY-HISTORY-VISIBILITY';
 END IF;
 SELECT c.oid,owner.rolname,c.relrowsecurity,c.relforcerowsecurity INTO STRICT history_oid,history_owner,enabled,forced
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles owner ON owner.oid=c.relowner
 WHERE n.nspname='control' AND c.relname='participant_lifecycle_transition' AND c.relkind='r';
 SELECT jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,'command',p.polcmd,
  'roles',(SELECT jsonb_agg(r.rolname::text ORDER BY r.rolname) FROM pg_roles r WHERE r.oid=ANY(p.polroles)),
  'using',pg_get_expr(p.polqual,p.polrelid)) ORDER BY p.polname) INTO policies
 FROM pg_policy p WHERE p.polrelid=history_oid;
 IF history_owner<>'openpc_control_owner' OR NOT enabled OR NOT forced OR NOT has_table_privilege(current_user,history_oid,'SELECT')
  OR policies IS DISTINCT FROM '[{"name":"participant_isolation","permissive":true,"command":"*","roles":["openpc_control_platform_runtime","openpc_control_reader","openpc_control_runtime","openpc_control_worker"],"using":"openpc.matches_participant(participant_id)"}]'::jsonb THEN
  RAISE EXCEPTION 'DATA-6021-RENEWAL-SECURITY-HISTORY-VISIBILITY';
 END IF;
 IF EXISTS(SELECT 1 FROM control.participant_lifecycle_transition t WHERE t.participant_id=wanted_participant
   AND t.mutation NOT IN ('ARCHIVE','RESTORE','SHRINK','TRANSFER')) THEN
  RAISE EXCEPTION 'DATA-6021-RENEWAL-SECURITY-HISTORY-UNKNOWN';
 END IF;
 SELECT coalesce((SELECT t.new_epoch FROM control.participant_lifecycle_transition t
   WHERE t.participant_id=p.participant_id AND t.mutation='ARCHIVE' ORDER BY t.new_epoch DESC LIMIT 1),0)
 INTO STRICT epoch FROM control.participant p JOIN control.privacy_domain d ON d.participant_id=p.participant_id
 WHERE p.participant_id=wanted_participant AND p.state='ACTIVE' AND d.privacy_domain_id=wanted_privacy AND d.state='ACTIVE';
 IF epoch NOT BETWEEN 0 AND 18446744073709551615 THEN RAISE EXCEPTION 'DATA-6021-RENEWAL-SECURITY-HISTORY-INVALID'; END IF;
 RETURN epoch;
END $$;


ALTER FUNCTION openpc.workload_renewal_participant_security_epoch(wanted_participant uuid, wanted_privacy uuid) OWNER TO openpc_control_owner;

--
-- Name: workload_renewal_policy_projection(control.workload_renewal_policy); Type: FUNCTION; Schema: openpc; Owner: openpc_control_owner
--

CREATE FUNCTION openpc.workload_renewal_policy_projection(policy control.workload_renewal_policy) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('0',openpc.business_bytes((policy).digest),'1',openpc.business_uuid((policy).principal_id),
  '2',(policy).workload_id,'3',(policy).state,'4',openpc.business_uuid((policy).governance_operation_id),
  '5',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json((policy).business_ancestors),'UTF8'))),
  '6',floor(extract(epoch from (policy).valid_from)*1000000)*1000,
  '7',floor(extract(epoch from (policy).valid_until)*1000000)*1000)
$$;


ALTER FUNCTION openpc.workload_renewal_policy_projection(policy control.workload_renewal_policy) OWNER TO openpc_control_owner;

