    CONSTRAINT action_intent_payload_ck CHECK ((payload_disclosure = ANY (ARRAY['NONE'::text, 'REDACTED'::text, 'AUTHORIZED_FULL'::text, 'AUTHORIZED_MINIMAL'::text]))),
