    CONSTRAINT authority_envelope_bootstrap_provenance_ck CHECK ((((bootstrap_mandate_id IS NULL) = (bootstrap_platform_participant_id IS NULL)) AND ((bootstrap_mandate_id IS NULL) OR ((cardinality(runtime_capability_ids) = 0) AND (onward_delegation_depth = 0))))),
    CONSTRAINT authority_envelope_depth_ck CHECK (((onward_delegation_depth >= 0) AND (onward_delegation_depth <= 32))),
    CONSTRAINT authority_envelope_maker_checker_ck CHECK (((checker_principal_id IS NULL) OR (checker_principal_id <> maker_principal_id))),
    CONSTRAINT authority_envelope_platform_binding_ck CHECK ((((platform_context_id IS NULL) AND (platform_authority_epoch IS NULL)) OR ((platform_context_id IS NOT NULL) AND (platform_authority_epoch IS NOT NULL) AND ((platform_authority_epoch >= (0)::numeric) AND (platform_authority_epoch <= '18446744073709551615'::numeric))))),
    CONSTRAINT authority_envelope_recovery_issuer_ck CHECK (((representation <> 'RECOVERY_V1'::text) OR ((issuer_participant_id IS NULL) AND (issuer_privacy_domain_id IS NULL)))),
    CONSTRAINT authority_envelope_representation_ck CHECK ((((representation = 'LEGACY'::text) AND (recovery_case_id IS NULL) AND (principal_id IS NOT NULL) AND (issuer_participant_id IS NULL) AND (issuer_privacy_domain_id IS NULL)) OR ((representation = 'TYPED_V1'::text) AND (recovery_case_id IS NULL) AND (principal_id IS NULL) AND (issuer_participant_id IS NOT NULL) AND (issuer_privacy_domain_id IS NOT NULL) AND (bootstrap_mandate_id IS NULL) AND (bootstrap_platform_participant_id IS NULL)) OR ((representation = 'RECOVERY_V1'::text) AND (recovery_case_id IS NOT NULL) AND (principal_id IS NOT NULL) AND (issuer_participant_id IS NULL) AND (issuer_privacy_domain_id IS NULL) AND (platform_context_id IS NOT NULL) AND (platform_authority_epoch IS NOT NULL) AND (valid_until IS NOT NULL) AND (cardinality(runtime_capability_ids) = 0) AND maker_checker_required AND step_up_required AND (onward_delegation_depth = 0) AND (bootstrap_mandate_id IS NULL) AND (bootstrap_platform_participant_id IS NULL)))),
    CONSTRAINT authority_envelope_row_version_ck CHECK ((row_version > (0)::numeric)),
    CONSTRAINT authority_envelope_runtime_capabilities_ck CHECK (((cardinality(runtime_capability_ids) <= 7) AND (runtime_capability_ids <@ ARRAY['CALL_RESULT_DISCLOSURE'::text, 'GAS_ESTIMATE_DISCLOSURE'::text, 'ACCESS_LIST_DISCLOSURE'::text, 'UNSIGNED_TRANSACTION_PREPARATION'::text, 'SIGNED_TRANSACTION_SUBMISSION'::text, 'OPERATION_STATUS_DISCLOSURE'::text, 'MULTI_CALL_SIMULATION_DISCLOSURE'::text]) AND (array_position(runtime_capability_ids, NULL::text) IS NULL))),
    CONSTRAINT authority_envelope_validity_ck CHECK (((valid_until IS NULL) OR (valid_until > valid_from)))
);

