    CONSTRAINT deployment_sender_nonce_ck CHECK (((sender_nonce IS NULL) OR ((sender_nonce ~ '^(0|[1-9][0-9]{0,19})$'::text) AND ((sender_nonce)::numeric < ((2)::numeric ^ (64)::numeric)))))
);


