    privacy_domain_id uuid NOT NULL,
    handover_id uuid NOT NULL,
    generation_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    maker_principal_id uuid CONSTRAINT workload_signing_handover_generatio_maker_principal_id_not_null NOT NULL,
    idempotency_key text NOT NULL,
    supersedes_generation_id uuid,
    request jsonb NOT NULL,
    request_canonical bytea NOT NULL,
    request_digest bytea NOT NULL,
    document jsonb NOT NULL,
    document_canonical bytea CONSTRAINT workload_signing_handover_generatio_document_canonical_not_null NOT NULL,
    document_digest bytea NOT NULL,
    authority_snapshot bytea CONSTRAINT workload_signing_handover_generatio_authority_snapshot_not_null NOT NULL,
    authority_snapshot_digest bytea CONSTRAINT workload_signing_handover_ge_authority_snapshot_digest_not_null NOT NULL,
    recorded_at_ns numeric(20,0) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workload_handover_generation_digest_ck CHECK (((octet_length(request_digest) = 32) AND (octet_length(document_digest) = 32) AND (octet_length(authority_snapshot_digest) = 32))),
    CONSTRAINT workload_handover_generation_size_ck CHECK ((((octet_length(request_canonical) >= 1) AND (octet_length(request_canonical) <= 8192)) AND ((octet_length(document_canonical) >= 1) AND (octet_length(document_canonical) <= 1048576)) AND ((octet_length(authority_snapshot) >= 1) AND (octet_length(authority_snapshot) <= 65536)))),
    CONSTRAINT workload_handover_generation_time_ck CHECK (((recorded_at_ns > (0)::numeric) AND (mod(recorded_at_ns, (1000)::numeric) = (0)::numeric) AND ((supersedes_generation_id IS NULL) OR (supersedes_generation_id <> generation_id))))
);

ALTER TABLE ONLY control.workload_signing_handover_generation FORCE ROW LEVEL SECURITY;


ALTER TABLE control.workload_signing_handover_generation OWNER TO openpc_control_owner;

--
-- Name: workload_signing_handover_observation; Type: TABLE; Schema: control; Owner: openpc_control_owner
--

CREATE TABLE control.workload_signing_handover_observation (
    participant_id uuid NOT NULL,
    privacy_domain_id uuid CONSTRAINT workload_signing_handover_observatio_privacy_domain_id_not_null NOT NULL,
    handover_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    dispatch_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    sequence integer NOT NULL,
    result jsonb NOT NULL,
    result_canonical bytea NOT NULL,
    result_digest bytea NOT NULL,
    previous_digest bytea,
    entry_canonical bytea NOT NULL,
    entry_digest bytea NOT NULL,
    recorded_at_ns numeric(20,0) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workload_handover_observation_digest_ck CHECK (((octet_length(result_digest) = 32) AND (octet_length(entry_digest) = 32) AND ((previous_digest IS NULL) OR (octet_length(previous_digest) = 32)))),
    CONSTRAINT workload_handover_observation_size_ck CHECK ((((octet_length(result_canonical) >= 1) AND (octet_length(result_canonical) <= 262144)) AND ((octet_length(entry_canonical) >= 1) AND (octet_length(entry_canonical) <= 8192)))),
    CONSTRAINT workload_handover_observation_time_ck CHECK (((recorded_at_ns > (0)::numeric) AND (mod(recorded_at_ns, (1000)::numeric) = (0)::numeric) AND (sequence > 0)))
);

ALTER TABLE ONLY control.workload_signing_handover_observation FORCE ROW LEVEL SECURITY;


ALTER TABLE control.workload_signing_handover_observation OWNER TO openpc_control_owner;

