--
-- Name: authentication_occurrence authentication_occurrence_initial_enrollment_source; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY authentication_occurrence_initial_enrollment_source ON control.authentication_occurrence FOR SELECT TO openpc_control_runtime, openpc_control_platform_runtime USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (current_setting('openpc.action_intent_id'::text, true) = 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text) AND (method = 'OIDC_CODE_PKCE_S256'::text) AND (context_mode = 'PLATFORM'::text) AND (current_setting('openpc.local_qa_runtime'::text, true) = '1'::text) AND ((session_id)::text = current_setting('openpc.initial_enrollment_session_id'::text, true)) AND ((principal_id)::text = current_setting('openpc.initial_enrollment_principal_id'::text, true)) AND (EXISTS ( SELECT 1
   FROM ((((control.webauthn_enrollment enrollment
     JOIN control.session session ON (((session.participant_id = enrollment.participant_id) AND (session.session_id = enrollment.session_id) AND (session.principal_id = enrollment.principal_id))))
     JOIN control.governed_initial_enrollment_profile profile ON (((profile.participant_id = enrollment.participant_id) AND (profile.profile_digest = enrollment.governed_initial_profile_digest) AND (profile.privacy_domain_id = authentication_occurrence.privacy_domain_id) AND (profile.state = 'ACTIVE'::text) AND (profile.valid_from <= clock_timestamp()) AND (profile.valid_until > clock_timestamp()) AND (('sha256:'::text || encode(profile.profile_digest, 'hex'::text)) = current_setting('openpc.initial_enrollment_profile_digest'::text, true)) AND ((profile.document ->> 'origin'::text) = enrollment.origin))))
     JOIN control.credential credential ON (((credential.participant_id = authentication_occurrence.participant_id) AND (credential.credential_id = authentication_occurrence.credential_id) AND (credential.principal_id = authentication_occurrence.principal_id) AND (credential.kind = 'OIDC_SUBJECT'::control.credential_kind) AND (credential.state = 'ACTIVE'::control.credential_state))))
     CROSS JOIN LATERAL jsonb_array_elements((profile.document -> 'accounts'::text)) account(value))
  WHERE ((enrollment.participant_id = authentication_occurrence.participant_id) AND (enrollment.principal_id = authentication_occurrence.principal_id) AND (enrollment.session_id = authentication_occurrence.session_id) AND ((enrollment.enrollment_id)::text = current_setting('openpc.initial_enrollment_id'::text, true)) AND ((account.value ->> 'principalId'::text) = (authentication_occurrence.principal_id)::text) AND ((account.value ->> 'issuer'::text) = credential.issuer) AND ((account.value ->> 'subject'::text) = credential.subject) AND ((account.value ->> 'audience'::text) = credential.audience) AND (enrollment.replaced_credential_id IS NULL) AND (enrollment.consumed_at IS NULL) AND (enrollment.expires_at > clock_timestamp()) AND (session.state = 'ACTIVE'::control.session_state) AND (session.context_mode = 'PLATFORM'::control.session_context_mode) AND (session.step_up_verified_at IS NULL) AND (session.idle_expires_at > clock_timestamp()) AND (session.absolute_expires_at > clock_timestamp()))))));


