CREATE POLICY authentication_occurrence_preservation_source ON control.authentication_occurrence FOR SELECT TO openpc_control_runtime USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (current_setting('openpc.action_intent_id'::text, true) = ANY (ARRAY['ACT-EVIDENCE_HOLDS_READ_RESOURCE-V1'::text, 'ACT-EVIDENCE_HOLDS_READ_COLLECTION-V1'::text, 'ACT-EVIDENCE_RECORDS_READ_COLLECTION-V1'::text, 'ACT-EVIDENCE_DELETIONS_CREATE_RESOURCE-V1'::text, 'ACT-EVIDENCE_DELETIONS_CREATE_BATCH-V1'::text, 'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1'::text, 'ACT-EVIDENCE_DELETIONS_READ_COLLECTION-V1'::text]))));


--
-- Name: authentication_occurrence authentication_occurrence_protected_source; Type: POLICY; Schema: control; Owner: openpc_control_owner
