CREATE POLICY authentication_occurrence_read ON control.authentication_occurrence FOR SELECT TO openpc_control_worker, openpc_control_reader USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)));


--
-- Name: authentication_occurrence authentication_occurrence_step_up_source; Type: POLICY; Schema: control; Owner: openpc_control_owner
