--
-- Name: mutation_candidate discovery_approval_resume_stored_child_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY discovery_approval_resume_stored_child_read ON control.mutation_candidate FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND ((catalog_operation_id)::text = 'ID-OP-WORKLOAD-ROTATE'::text) AND ((action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND ((resume_request ->> 'command'::text) = 'RESUME'::text) AND (resume_request ? 'discoveryReceivingProof'::text) AND (predecessor_candidate_id IS NOT NULL) AND (state = ANY (ARRAY['PROPOSED'::control.mutation_candidate_state, 'APPROVAL_REQUESTED'::control.mutation_candidate_state])) AND (consumed_operation_id IS NULL) AND (EXISTS ( SELECT 1
   FROM (control.platform_recovery_case c
     JOIN control.platform_recovery_enrollment e ON (((e.enrollment_id = c.enrollment_id) AND (e.participant_id = c.participant_id) AND (e.privacy_domain_id = c.privacy_domain_id))))
  WHERE ((c.participant_id = mutation_candidate.participant_id) AND (c.privacy_domain_id = mutation_candidate.privacy_domain_id) AND (c.recovery_id = ( SELECT e2.recovery_case_id
           FROM control.authority_envelope e2
          WHERE ((e2.participant_id = mutation_candidate.participant_id) AND (e2.authority_envelope_id = mutation_candidate.maker_authority_envelope_id) AND (e2.principal_id = mutation_candidate.maker_principal_id) AND (e2.representation = 'RECOVERY_V1'::text)))) AND (c.state = 'ACTIVE'::text) AND (c.valid_from <= clock_timestamp()) AND (c.valid_until > clock_timestamp()) AND (e.state = 'ACTIVE'::text) AND (e.row_version = c.enrollment_revision) AND (e.document_digest = c.enrollment_digest) AND ((c.intent ->> 'schema'::text) = 'pc.identity.discovery-certificate-recovery-intent'::text) AND ((e.document ->> 'assurance'::text) = 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'::text) AND (current_setting('openpc.local_qa_runtime'::text, true) = '1'::text) AND ((c.intent -> 'certificateRecovery'::text) = (e.document -> 'certificateRecovery'::text)) AND ((mutation_candidate.resource_id)::text = (c.intent #>> '{certificateRecovery,predecessorCredentialId}'::text[])) AND (mutation_candidate.candidate_document = jsonb_build_object('replacedCredentialId', (mutation_candidate.resource_id)::text, 'credentialId', (c.intent #>> '{certificateRecovery,successorCredentialId}'::text[]), 'publicKeySpkiDer', (c.intent #>> '{certificateRecovery,successorPublicKeySpkiDer}'::text[]))))))));


