--
-- Name: authority_role discovery_recovery_role_source_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY discovery_recovery_role_source_read ON control.authority_role FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (EXISTS ( SELECT 1
   FROM (control.platform_recovery_enrollment e
     JOIN control.platform_scope_replacement original ON (((original.replacement_id = e.expired_replacement_id) AND (original.participant_id = e.participant_id) AND (original.privacy_domain_id = e.privacy_domain_id) AND (original.state = 'COMMITTED'::text))))
  WHERE ((e.participant_id = authority_role.participant_id) AND openpc.matches_privacy(e.privacy_domain_id) AND (e.state = 'ACTIVE'::text) AND ((e.document ->> 'schema'::text) = 'pc.identity.discovery-certificate-recovery-enrollment'::text) AND openpc.platform_recovery_installation_source_current(e.enrollment_id) AND (EXISTS ( SELECT 1
           FROM jsonb_array_elements((original.candidate -> 'administrators'::text)) administrator(value)
          WHERE ((administrator.value ->> 'roleId'::text) = (authority_role.authority_role_id)::text))))))));


--
-- Name: runtime_target discovery_recovery_target_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY discovery_recovery_target_read ON control.runtime_target FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (EXISTS ( SELECT 1
   FROM control.platform_recovery_enrollment e
  WHERE ((e.participant_id = runtime_target.participant_id) AND (e.privacy_domain_id = runtime_target.privacy_domain_id) AND (e.state = 'ACTIVE'::text) AND ((e.document ->> 'schema'::text) = 'pc.identity.discovery-certificate-recovery-enrollment'::text) AND ((e.document #>> '{certificateRecovery,targetId}'::text[]) = (runtime_target.runtime_target_id)::text) AND openpc.platform_recovery_installation_source_current(e.enrollment_id))))));


