--
-- Name: business_signing_key_state identity_envelope_recovery_installation_source_lock; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY identity_envelope_recovery_installation_source_lock ON control.business_signing_key_state FOR UPDATE TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM control.identity_envelope_recovery_enrollment enrollment
  WHERE ((enrollment.participant_id = business_signing_key_state.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.state = 'ACTIVE'::text) AND (enrollment.row_version = (1)::numeric) AND openpc.identity_envelope_recovery_installation_source_current(enrollment.enrollment_id) AND (enrollment.valid_from <= clock_timestamp()) AND (enrollment.valid_until > clock_timestamp()) AND (enrollment.privacy_domain_id = business_signing_key_state.privacy_domain_id) AND ((enrollment.document #>> '{request,oldFingerprint}'::text[]) = business_signing_key_state.signer_id)))))) WITH CHECK (false);


--
-- Name: credential identity_envelope_recovery_installation_source_lock; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY identity_envelope_recovery_installation_source_lock ON control.credential FOR UPDATE TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM control.identity_envelope_recovery_enrollment enrollment
  WHERE ((enrollment.participant_id = credential.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.state = 'ACTIVE'::text) AND (enrollment.row_version = (1)::numeric) AND openpc.identity_envelope_recovery_installation_source_current(enrollment.enrollment_id) AND (enrollment.valid_from <= clock_timestamp()) AND (enrollment.valid_until > clock_timestamp()) AND ((EXISTS ( SELECT 1
           FROM jsonb_array_elements((jsonb_build_array((enrollment.document -> 'recoveryPrincipal'::text)) || (enrollment.document -> 'custodians'::text))) actor(value)
          WHERE ((actor.value ->> 'credentialId'::text) = (credential.credential_id)::text))) OR ((enrollment.document #>> '{request,workloadCredentialId}'::text[]) = (credential.credential_id)::text))))))) WITH CHECK (false);


--
-- Name: identity_envelope_signing_selection identity_envelope_recovery_installation_source_lock; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY identity_envelope_recovery_installation_source_lock ON control.identity_envelope_signing_selection FOR UPDATE TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM control.identity_envelope_recovery_enrollment enrollment
  WHERE ((enrollment.participant_id = identity_envelope_signing_selection.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.state = 'ACTIVE'::text) AND (enrollment.row_version = (1)::numeric) AND openpc.identity_envelope_recovery_installation_source_current(enrollment.enrollment_id) AND (enrollment.valid_from <= clock_timestamp()) AND (enrollment.valid_until > clock_timestamp()) AND (enrollment.privacy_domain_id = identity_envelope_signing_selection.privacy_domain_id) AND ((enrollment.document #>> '{request,oldFingerprint}'::text[]) = identity_envelope_signing_selection.signer_id)))))) WITH CHECK (false);


--
-- Name: principal identity_envelope_recovery_installation_source_lock; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY identity_envelope_recovery_installation_source_lock ON control.principal FOR UPDATE TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM control.identity_envelope_recovery_enrollment enrollment
  WHERE ((enrollment.participant_id = principal.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.state = 'ACTIVE'::text) AND (enrollment.row_version = (1)::numeric) AND openpc.identity_envelope_recovery_installation_source_current(enrollment.enrollment_id) AND (enrollment.valid_from <= clock_timestamp()) AND (enrollment.valid_until > clock_timestamp()) AND ((EXISTS ( SELECT 1
           FROM jsonb_array_elements((jsonb_build_array((enrollment.document -> 'recoveryPrincipal'::text)) || (enrollment.document -> 'custodians'::text))) actor(value)
          WHERE ((actor.value ->> 'principalId'::text) = (principal.principal_id)::text))) OR ((enrollment.document ->> 'issuerPrincipalId'::text) = (principal.principal_id)::text))))))) WITH CHECK (false);


--
-- Name: assignment identity_envelope_recovery_installation_source_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY identity_envelope_recovery_installation_source_read ON control.assignment FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM control.identity_envelope_recovery_enrollment enrollment
  WHERE ((enrollment.participant_id = assignment.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.state = 'ACTIVE'::text) AND (enrollment.row_version = (1)::numeric) AND openpc.identity_envelope_recovery_installation_source_current(enrollment.enrollment_id) AND (enrollment.valid_from <= clock_timestamp()) AND (enrollment.valid_until > clock_timestamp()) AND ((enrollment.document #>> '{recoveryPrincipal,principalId}'::text[]) = (assignment.principal_id)::text))))));


