--
-- Name: mutation_candidate platform_prepare_approval_continuation_history_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY platform_prepare_approval_continuation_history_read ON control.mutation_candidate FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (EXISTS ( SELECT 1
   FROM control.platform_recovery_enrollment source
  WHERE ((source.participant_id = mutation_candidate.participant_id) AND (source.privacy_domain_id = mutation_candidate.privacy_domain_id) AND openpc.platform_recovery_continuation_root_matches(source.platform_context_id, source.participant_id, source.root_epoch, source.root_revision) AND (((source.source_purpose = 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text) AND ((source.document ->> 'schemaVersion'::text) = '3'::text)) OR ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '4'::text)) OR ((source.source_purpose = 'ROOT_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '2'::text) AND (jsonb_typeof((source.document -> 'uneffectedPredecessor'::text)) = 'object'::text) AND ((source.document #>> '{uneffectedPredecessor,schema}'::text[]) = 'pc.identity.platform-expired-uneffected-recovery'::text) AND ((source.document #>> '{uneffectedPredecessor,schemaVersion}'::text[]) = '1'::text))) AND ((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND (source.state = 'ACTIVE'::text) AND (source.row_version = (1)::numeric) AND ((source.document ->> 'assurance'::text) = 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'::text) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (source.valid_from <= clock_timestamp()) AND (source.valid_until > clock_timestamp()) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1'::text, 'ACT-IDENTITY_CREATE_SESSION-V1'::text, 'ACT-IDENTITY_DELETE_SESSION-V1'::text, 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text, 'ACT-OPERATIONS_READ_OPERATION-V1'::text, 'ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text, 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text, 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text, 'ACT-POLICY_APPROVE_REQUEST-V1'::text, 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'::text, 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'::text])) AND ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '4'::text) AND (EXISTS ( SELECT 1
           FROM control.platform_recovery_case historical
          WHERE ((historical.participant_id = source.participant_id) AND (historical.privacy_domain_id = source.privacy_domain_id) AND (((NOT ((source.document #> '{source}'::text[]) ? 'closedApproval'::text)) AND (historical.enrollment_id = source.enrollment_id) AND (historical.enrollment_revision = source.row_version) AND (historical.enrollment_digest = source.document_digest) AND (historical.state = 'EXPIRED'::text) AND (historical.valid_until <= clock_timestamp())) OR (((source.document #>> '{source,closedApproval,schema}'::text[]) = 'pc.identity.closed-platform-approval-source'::text) AND ((source.document #>> '{source,closedApproval,schemaVersion}'::text[]) = '1'::text) AND ((historical.enrollment_id)::text = (source.document #>> '{source,closedApproval,enrollmentId}'::text[])) AND (historical.enrollment_id <> source.enrollment_id) AND (('sha256:'::text || encode(historical.enrollment_digest, 'hex'::text)) = (source.document #>> '{source,closedApproval,enrollmentDigest}'::text[])) AND ((historical.recovery_id)::text = (source.document #>> '{source,closedApproval,approval,recoveryId}'::text[])) AND (('sha256:'::text || encode(historical.intent_digest, 'hex'::text)) = (source.document #>> '{source,closedApproval,approval,intentDigest}'::text[])) AND (historical.state = ANY (ARRAY['REVOKED'::text, 'EXPIRED'::text])) AND (historical.state = (source.document #>> '{source,closedApproval,closure,state}'::text[])))) AND ((historical.intent -> 'pendingExpiry'::text) = (source.document #> '{source,pendingExpiry}'::text[])) AND ((NOT (historical.intent ? 'approvalContinuation'::text)) OR (((historical.intent #>> '{approvalContinuation,schema}'::text[]) = 'pc.identity.platform-prepare-approval-continuation'::text) AND ((historical.intent #>> '{approvalContinuation,schemaVersion}'::text[]) = '1'::text) AND ((historical.intent #>> '{approvalContinuation,recoveryId}'::text[]) <> (historical.recovery_id)::text) AND ((historical.intent #>> '{approvalContinuation,recoveryId}'::text[]) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND ((historical.intent #>> '{approvalContinuation,candidateId}'::text[]) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND ((historical.intent #>> '{approvalContinuation,approvalId}'::text[]) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND ((historical.intent #>> '{approvalContinuation,candidateDigest}'::text[]) = ('sha256:'::text || encode(sha256(convert_to(openpc.signing_canonical_json((historical.intent -> 'preparation'::text)), 'UTF8'::name)), 'hex'::text))) AND ((historical.intent #>> '{approvalContinuation,attempt}'::text[]) ~ '^[1-9][0-9]{0,19}$'::text))) AND (historical.intent_digest = sha256(convert_to(openpc.signing_canonical_json(historical.intent), 'UTF8'::name))) AND (historical.activation_operation_id IS NOT NULL) AND (historical.activation_evidence_digest = sha256(historical.activation_evidence_cbor)) AND (octet_length(historical.activation_cose) > 0) AND (((mutation_candidate.catalog_operation_id)::text = 'ID-OP-PLATFORM-SCOPE-PREPARE'::text) AND ((mutation_candidate.action_intent_id)::text = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (mutation_candidate.resource_type = 'participant'::text) AND (mutation_candidate.operation_class = 'UPDATE'::text) AND (mutation_candidate.expected_revision = 0) AND ((mutation_candidate.resource_id)::text = (historical.intent #>> '{preparation,replacementId}'::text[])) AND (mutation_candidate.candidate_document = (historical.intent -> 'preparation'::text)) AND (mutation_candidate.candidate_digest = sha256(convert_to(openpc.signing_canonical_json(mutation_candidate.candidate_document), 'UTF8'::name))) AND ((mutation_candidate.maker_principal_id)::text = (historical.intent #>> '{preparation,administrators,0,principalId}'::text[])) AND ((EXISTS ( SELECT 1
                   FROM jsonb_array_elements(historical.lease_bindings) binding(value)
                  WHERE (((binding.value ->> 'envelopeId'::text) = (mutation_candidate.maker_authority_envelope_id)::text) AND ((binding.value ->> 'assignmentId'::text) = (mutation_candidate.maker_assignment_id)::text) AND ((binding.value ->> 'principalId'::text) = (mutation_candidate.maker_principal_id)::text) AND ((binding.value ->> 'principalEpoch'::text) = (mutation_candidate.maker_principal_epoch)::text)))) OR (EXISTS ( SELECT 1
                   FROM control.platform_recovery_case fresh
                  WHERE ((fresh.participant_id = historical.participant_id) AND (fresh.privacy_domain_id = historical.privacy_domain_id) AND (fresh.enrollment_id = source.enrollment_id) AND (fresh.state = 'ACTIVE'::text) AND (fresh.valid_from <= clock_timestamp()) AND (fresh.valid_until > clock_timestamp()) AND ((fresh.intent -> 'preparation'::text) = (historical.intent -> 'preparation'::text)) AND ((fresh.intent #>> '{approvalContinuation,recoveryId}'::text[]) = (historical.recovery_id)::text) AND ((fresh.intent #>> '{approvalContinuation,candidateId}'::text[]) = (mutation_candidate.predecessor_candidate_id)::text) AND ((fresh.intent #>> '{approvalContinuation,approvalId}'::text[]) = (mutation_candidate.predecessor_approval_id)::text) AND ((fresh.intent #>> '{approvalContinuation,businessKey}'::text[]) = (mutation_candidate.idempotency_key)::text) AND ((((fresh.intent #>> '{approvalContinuation,attempt}'::text[]))::numeric + (1)::numeric) = (mutation_candidate.attempt)::numeric) AND (mutation_candidate.resume_operation_id IS NOT NULL) AND ((mutation_candidate.resume_request ->> 'command'::text) = 'RESUME'::text) AND (EXISTS ( SELECT 1
                           FROM jsonb_array_elements(fresh.lease_bindings) binding(value)
                          WHERE (((binding.value ->> 'envelopeId'::text) = (mutation_candidate.maker_authority_envelope_id)::text) AND ((binding.value ->> 'assignmentId'::text) = (mutation_candidate.maker_assignment_id)::text) AND ((binding.value ->> 'principalId'::text) = (mutation_candidate.maker_principal_id)::text) AND ((binding.value ->> 'principalEpoch'::text) = (mutation_candidate.maker_principal_epoch)::text))))))))))))))))));


