CREATE POLICY platform_scope_replacement_read ON control.platform_scope_replacement FOR SELECT TO openpc_control_owner, openpc_control_runtime, openpc_control_worker, openpc_control_platform_runtime, openpc_control_reader USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)));


--
-- Name: platform_context platform_scope_replacement_root_commit; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY platform_scope_replacement_root_commit ON control.platform_context FOR UPDATE TO openpc_control_owner USING ((openpc.matches_participant(owner_participant_id) AND (openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text))) WITH CHECK ((openpc.matches_participant(owner_participant_id) AND (openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (state = 'ACTIVE'::text) AND (EXISTS ( SELECT 1
   FROM control.platform_scope_replacement r
  WHERE ((r.platform_context_id = platform_context.platform_context_id) AND (r.participant_id = platform_context.owner_participant_id) AND (r.state = 'COMMITTED'::text) AND (r.commit_operation_id = openpc.current_operation_id()) AND ((r.predecessor_epoch + (1)::numeric) = platform_context.authority_epoch) AND ((r.expected_root_revision + (1)::numeric) = platform_context.row_version))))));


