--
-- Name: platform_envelope_scope_successor platform_scope_successor_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY platform_scope_successor_read ON control.platform_envelope_scope_successor FOR SELECT TO openpc_control_owner, openpc_control_runtime, openpc_control_worker, openpc_control_platform_runtime, openpc_control_reader USING ((EXISTS ( SELECT 1
   FROM control.authority_envelope e
  WHERE ((e.platform_context_id = platform_envelope_scope_successor.platform_context_id) AND openpc.matches_participant(e.participant_id) AND ((openpc.current_privacy_domain_id())::text = ANY (e.privacy_domain_ids))))));


--
-- Name: credential platform_scope_target_identity_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY platform_scope_target_identity_read ON control.credential FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM ((control.platform_scope_replacement replacement
     JOIN control.platform_scope_target_withdrawal cohort ON (((cohort.replacement_id = replacement.replacement_id) AND (cohort.participant_id = replacement.participant_id) AND (cohort.privacy_domain_id = replacement.privacy_domain_id))))
     JOIN control.runtime_target_disposition_admission disposition ON (((disposition.participant_id = cohort.participant_id) AND (disposition.privacy_domain_id = cohort.privacy_domain_id) AND (disposition.runtime_target_id = cohort.runtime_target_id))))
  WHERE ((replacement.participant_id = credential.participant_id) AND openpc.matches_privacy(replacement.privacy_domain_id) AND (replacement.state = 'WITHDRAWING'::text) AND ((disposition.binding ->> 'action'::text) = 'Withdraw'::text) AND ((disposition.binding -> 'cause'::text) = jsonb_build_object('kind', 'Dependency', 'owner', 'Platform', 'resource_id', (replacement.replacement_id)::text, 'operation_id', (replacement.prepare_operation_id)::text, 'revision', 1)) AND (credential.credential_id = ((disposition.binding #>> '{target,credential_id}'::text[]))::uuid))))));


--
-- Name: principal platform_scope_target_identity_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY platform_scope_target_identity_read ON control.principal FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM ((control.platform_scope_replacement replacement
     JOIN control.platform_scope_target_withdrawal cohort ON (((cohort.replacement_id = replacement.replacement_id) AND (cohort.participant_id = replacement.participant_id) AND (cohort.privacy_domain_id = replacement.privacy_domain_id))))
     JOIN control.runtime_target_disposition_admission disposition ON (((disposition.participant_id = cohort.participant_id) AND (disposition.privacy_domain_id = cohort.privacy_domain_id) AND (disposition.runtime_target_id = cohort.runtime_target_id))))
  WHERE ((replacement.participant_id = principal.participant_id) AND openpc.matches_privacy(replacement.privacy_domain_id) AND (replacement.state = 'WITHDRAWING'::text) AND ((disposition.binding ->> 'action'::text) = 'Withdraw'::text) AND ((disposition.binding -> 'cause'::text) = jsonb_build_object('kind', 'Dependency', 'owner', 'Platform', 'resource_id', (replacement.replacement_id)::text, 'operation_id', (replacement.prepare_operation_id)::text, 'revision', 1)) AND (principal.principal_id = ((disposition.binding #>> '{target,principal_id}'::text[]))::uuid))))));


