--

CREATE POLICY root_expiry_admin_receipt_prerequisite_read ON control.outbox_event FOR SELECT TO openpc_control_owner, openpc_control_runtime, openpc_control_platform_runtime USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (EXISTS ( SELECT 1
   FROM (control.platform_recovery_enrollment source
     JOIN control.platform_recovery_case lease ON (((lease.enrollment_id = source.enrollment_id) AND (lease.participant_id = source.participant_id) AND (lease.privacy_domain_id = source.privacy_domain_id) AND (lease.enrollment_revision = source.row_version) AND (lease.enrollment_digest = source.document_digest))))
  WHERE ((source.participant_id = outbox_event.participant_id) AND (source.privacy_domain_id = outbox_event.privacy_domain_id) AND (source.source_purpose = ANY (ARRAY['ROOT_EXPIRY_RECOVERY'::text, 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text, 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text])) AND (source.expired_replacement_id IS NULL) AND (source.root_expiry_recovery_id IS NOT NULL) AND (source.state = 'ACTIVE'::text) AND (source.row_version = (1)::numeric) AND ((source.document ->> 'schema'::text) = ANY (ARRAY['pc.identity.platform-recovery-enrollment'::text, 'pc.identity.discovery-certificate-recovery-enrollment'::text])) AND (((source.source_purpose = 'ROOT_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '2'::text)) OR ((source.source_purpose = 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text) AND ((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((source.document ->> 'schemaVersion'::text) = '3'::text)) OR ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((source.document ->> 'schemaVersion'::text) = '4'::text) AND (jsonb_typeof((source.document #> '{source,pendingExpiry}'::text[])) = 'object'::text))) AND ((source.document ->> 'assurance'::text) = 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'::text) AND (source.valid_from <= clock_timestamp()) AND (source.valid_until > clock_timestamp()) AND ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) = (lease.intent ? 'pendingExpiry'::text)) AND ((source.source_purpose <> 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) OR ((lease.intent -> 'pendingExpiry'::text) = (source.document #> '{source,pendingExpiry}'::text[]))) AND ((((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((lease.intent ->> 'schema'::text) = 'pc.identity.platform-recovery-intent'::text) AND ((openpc.current_action_int