    WHEN ((aggregate_type = 'local-root-expiry-recovery'::text) AND (aggregate_sequence = 1) AND (event_type = 'openpc.identity.local-root-expiry-recovery.completed.v1'::text)) THEN (openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (EXISTS ( SELECT 1
       FROM control.root_expiry_recovery_case receipt
      WHERE ((receipt.participant_id = outbox_event.participant_id) AND (receipt.privacy_domain_id = outbox_event.privacy_domain_id) AND (receipt.state = 'COMPLETED'::text) AND (outbox_event.aggregate_type = 'local-root-expiry-recovery'::text) AND (outbox_event.aggregate_id = receipt.recovery_id) AND (outbox_event.aggregate_sequence = 1) AND (outbox_event.event_id = receipt.operation_id) AND (outbox_event.event_type = 'openpc.identity.local-root-expiry-recovery.completed.v1'::text) AND (outbox_event.payload_cbor = receipt.evidence_cbor) AND (outbox_event.payload_digest = receipt.evidence_digest) AND (outbox_event.cose_sign1 = receipt.evidence_cose) AND (((CURRENT_USER = 'openpc_control_owner'::name) AND (EXISTS ( SELECT 1
               FROM (control.platform_scope_replacement pending
                 CROSS JOIN LATERAL jsonb_array_elements((openpc.root_expiry_pending_ancestry(pending.platform_context_id, to_jsonb(pending.*)) -> 'receipts'::text)) declared(value))
              WHERE ((pending.participant_id = receipt.participant_id) AND (pending.privacy_domain_id = receipt.privacy_domain_id) AND (pending.state = 'WITHDRAWING'::text) AND (pending.row_version = (1)::numeric) AND ((declared.value ->> 'recoveryId'::text) = (receipt.recovery_id)::text) AND ((declared.value ->> 'enrollmentId'::text) = (receipt.enrollment_id)::text) AND ((declared.value ->> 'activationOperationId'::text) = (receipt.operation_id)::text) AND ((declared.value ->> 'enrollmentDigest'::text) = ('sha256:'::text || encode(receipt.enrollment_digest, 'hex'::text))) AND ((declared.value ->> 'intentDigest'::text) = ('sha256:'::text || encode(receipt.intent_digest, 'hex'::text))) AND ((declared.value ->> 'receiptDigest'::text) = ('sha256:'::text || encode(receipt.evidence_digest, 'hex'::text))))))) OR (EXISTS ( SELECT 1
               FROM (control.root_expiry_recovery_enrollment source
                 LEFT JOIN control.root_expiry_recovery_case ceremony ON (((ceremony.enrollment_id = source.enrollment_id) AND (ceremony.participant_id = source.participant_id) AND (ceremony.privacy_domain_id = source.privacy_domain_id) AND (ceremony.enrollment_digest = source.document_digest) AND (ceremony.enrollment_revision = source.row_version) AND ((ceremony.intent -> 'rootAncestry'::text) = (source.document -> 'rootAncestry'::text)))))
              WHERE ((source.participant_id = receipt.participant_id) AND (source.privacy_domain_id = receipt.privacy_domain_id) AND (source.state = 'ACTIVE'::text) AND (source.row_version = (1)::numeric) AND ((source.document ->> 'schemaVersion'::text) = '3'::text) AND ((source.document ->> 'purpose'::text) = 'pc.installation.local-root-expiry-pending-ancestry-custody.v3'::text) AND (source.document_digest = sha256(convert_to(openpc.signing_canonical_json(source.document), 'UTF8'::name))) AND ((((ceremony.recovery_id IS NULL) OR (ceremony.state = ANY (ARRAY['DRAFT'::text, 'REQUESTED'::text]))) AND (source.valid_from <= clock_timestamp()) AND (source.valid_until > clock_timestamp()) AND ((ceremony.recovery_id IS NULL) OR (ceremony.valid_until > clock_timestamp())) AND (EXISTS ( SELECT 1
                       FROM control.platform_context root
                      WHERE ((root.platform_context_id = source.platform_context_id) AND (root.owner_participant_id = source.participant_id) AND (root.state = 'ACTIVE'::text) AND ((root.authority_epoch)::text = (source.document ->> 'rootEpoch'::text)) AND ((root.row_version)::text = (source.document ->> 'rootRevision'::text)))))) OR ((ceremony.state = 'COMPLETED'::text) AND (ceremony.operation_id IS NOT NULL) AND (ceremony.evidence_digest = sha256(ceremony.evidence_cbor)) AND (octet_length(ceremony.evidence_cose) > 0))) AND ((jsonb_array_length((source.document #> '{rootAncestry,receipts}'::text[])) >= 1) AND (jsonb_array_length((source.document #> '{rootAncestry,receipts}'::text[])) <= 32)) AND (EXISTS ( SELECT 1
                       FROM jsonb_array_elements((source.document #> '{rootAncestry,receipts}'::text[])) declared(value)
                      WHERE (((declared.value ->> 'recoveryId'::text) = (receipt.recovery_id)::text) AND ((declared.value ->> 'enrollmentId'::text) = (receipt.enrollment_id)::text) AND ((declared.value ->> 'activationOperationId'::text) = (receipt.operation_id)::text) AND ((declared.value ->> 'enrollmentDigest'::text) = ('sha256:'::text || encode(receipt.enrollment_digest, 'hex'::text))) AND ((declared.value ->> 'intentDigest'::text) = ('sha256:'::text || encode(receipt.intent_digest, 'hex'::text))) AND ((declared.value ->> 'receiptDigest'::text) = ('sha256:'::text || encode(receipt.evidence_digest, 'hex'::text))))))))))))))
    ELSE false
END);


--
-- Name: approval_request root_expiry_pending_effect_source_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY root_expiry_pending_effect_source_read ON control.approval_request FOR SELECT TO openpc_control_owner USING (openpc.platform_history_approval_request_pending_effect_read(to_jsonb(approval_request.*)));


--
-- Name: mutation_candidate root_expiry_pending_effect_source_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY root_expiry_pending_effect_source_read ON control.mutation_candidate FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (EXISTS ( SELECT 1
   FROM ((control.platform_scope_replacement pending
     JOIN control.platform_context root ON (((root.platform_context_id = pending.platform_context_id) AND (root.owner_participant_id = pending.participant_id) AND (root.state = 'ACTIVE'::text) AND (((root.authority_epoch = pending.predecessor_epoch) AND (root.row_version = pending.expected_root_revision)) OR (openpc.root_expiry_pending_ancestry(pending.platform_context_id, to_jsonb(pending.*)) IS NOT NULL)))))
     JOIN ( SELECT platform_envelope_scope.platform_context_id,
            platform_envelope_scope.platform_authority_epoch,
            platform_envelope_scope.scope_cbor,
            platform_envelope_scope.admission_digest
           FROM control.platform_envelope_scope
        UNION ALL
         SELECT platform_envelope_scope_successor.platform_context_id,
            platform_envelope_scope_successor.platform_authority_epoch,
            platform_envelope_scope_successor.scope_cbor,
            platform_envelope_scope_successor.admission_digest
           FROM control.platform_envelope_scope_successor
        UNION ALL
         SELECT root_expiry_recovery_scope.platform_context_id,
            root_expiry_recovery_scope.platform_authority_epoch,
            root_expiry_recovery_scope.scope_cbor,
            root_expiry_recovery_scope.admission_digest
           FROM control.root_expiry_recovery_scope) scope ON (((scope.platform_context_id = root.platform_context_id) AND (scope.platform_authority_epoch = pending.predecessor_epoch) AND (scope.admission_digest = pending.predecessor_digest))))
  WHERE ((pending.participant_id = mutation_candidate.participant_id) AND (pending.privacy_domain_id = mutation_candidate.privacy_domain_id) AND (pending.state = 'WITHDRAWING'::text) AND (pending.row_version = (1)::numeric) AND (pending.superseded_by IS NULL) AND (num_nonnulls(pending.commit_operation_id, pending.commit_candidate_id, pending.commit_approval_id, pending.readiness_digest, pending.committed_at) = 0) AND (pending.candidate_digest = sha256(convert_to(openpc.signing_canonical_json(pending.candidate), 'UTF8'::name))) AND (pending.successor_digest = sha256(pending.successor_preimage)) AND (((openpc.business_cbor(scope.scope_cbor) ->> '4'::text))::numeric <= floor((EXTRACT(epoch FROM clock_timestamp()) * (1000000000)::numeric))) AND ((pending.candidate #> '{successorScope,runtime}'::text[]) = (openpc.platform_scope_document(scope.scope_cbor) -> 'runtime'::text)) AND (jsonb_array_length((pending.candidate -> 'administrators'::text)) = 2) AND (NOT (EXISTS ( SELECT 1
           FROM jsonb_array_elements((pending.candidate -> 'administrators'::text)) administrator(value)
          WHERE ((((administrator.value #>> '{usable,validUntilNs}'::text[]))::numeric > floor((EXTRACT(epoch FROM clock_timestamp()) * (1000000000)::numeric))) OR (((administrator.value #>> '{grantable,validUntilNs}'::text[]))::numeric > floor((EXTRACT(epoch FROM clock_timestamp()) * (1000000000)::numeric))))))) AND (EXISTS ( SELECT 1
           FROM jsonb_array_elements((pending.candidate -> 'administrators'::text)) administrator(value)
          WHERE ((mutation_candidate.resource_id)::text = (administrator.value ->> 'envelopeId'::text)))))))));


--
-- Name: outbox_event root_expiry_pending_preparation_outbox_source_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY root_expiry_pending_preparation_outbox_source_read ON control.outbox_event FOR SELECT TO openpc_control_owner USING (
CASE
    WHEN (openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (aggregate_type = 'platform-scope-replacement'::text) AND (event_type = 'openpc.platform-scope-replacement.mutation.committed.v1'::text)) THEN openpc.platform_history_outbox_event_pending_preparation_read(to_jsonb(outbox_event.*))
    ELSE false
END);


