   FROM (control.root_expiry_recovery_proof proof
     JOIN control.root_expiry_recovery_case recovery ON (((recovery.recovery_id = proof.recovery_id) AND (recovery.participant_id = proof.participant_id) AND (recovery.privacy_domain_id = proof.privacy_domain_id))))
