-- Name: root_expiry_recovery_scope root_expiry_scope_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY root_expiry_scope_read ON control.root_expiry_recovery_scope FOR SELECT TO openpc_control_owner, openpc_control_runtime, openpc_control_worker, openpc_control_platform_runtime, openpc_control_reader USING (
CASE
    WHEN ((CURRENT_USER = 'openpc_control_owner'::name) AND openpc.matches_participant(owner_participant_id) AND openpc.matches_privacy(installation_privacy_domain_id) AND ((openpc.current_action_intent_id() = 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text) OR (openpc.matches_participant(owner_participant_id) AND openpc.matches_privacy(installation_privacy_domain_id) AND (NOT (current_setting('openpc.local_qa_runtime'::text, true) IS DISTINCT FROM '1'::text)) AND (EXISTS ( SELECT 1
       FROM (control.platform_recovery_enrollment source
         JOIN control.platform_recovery_case lease ON (((lease.enrollment_id = source.enrollment_id) AND (lease.participant_id = source.participant_id) AND (lease.privacy_domain_id = source.privacy_domain_id) AND (lease.enrollment_revision = source.row_version) AND (lease.enrollment_digest = source.document_digest))))
      WHERE ((source.participant_id = root_expiry_recovery_scope.owner_participant_id) AND (source.privacy_domain_id = root_expiry_recovery_scope.installation_privacy_domain_id) AND (source.source_purpose = ANY (ARRAY['ROOT_EXPIRY_RECOVERY'::text, 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text, 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text])) AND (source.expired_replacement_id IS NULL) AND (source.root_expiry_recovery_id IS NOT NULL) AND (source.state = 'ACTIVE'::text) AND (source.row_version = (1)::numeric) AND ((source.document ->> 'schema'::text) = ANY (ARRAY['pc.identity.platform-recovery-enrollment'::text, 'pc.identity.discovery-certificate-recovery-enrollment'::text])) AND (((source.source_purpose = 'ROOT_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '2'::text)) OR ((source.source_purpose = 'ROOT_EXPIRY_RECOVERY_CONTINUATION'::text) AND ((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((source.document ->> 'schemaVersion'::text) = '3'::text)) OR ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((source.document ->> 'schemaVersion'::text) = '4'::text) AND (jsonb_typeof((source.document #> '{source,pendingExpiry}'::text[])) = 'object'::text))) AND ((source.document ->> 'assurance'::text) = 'LOCAL_QA_VIRTUAL_AUTHENTICATOR'::text) AND (source.valid_from <= clock_timestamp()) AND (source.valid_until > clock_timestamp()) AND ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) = (lease.intent ? 'pendingExpiry'::text)) AND ((source.source_purpose <> 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) OR ((lease.intent -> 'pendingExpiry'::text) = (source.document #> '{source,pendingExpiry}'::text[]))) AND ((((source.document ->> 'schema'::text) = 'pc.identity.platform-recovery-enrollment'::text) AND ((lease.intent ->> 'schema'::text) = 'pc.identity.platform-recovery-intent'::text) AND ((openpc.current_action_intent_id() = ANY (ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1'::text, 'ACT-IDENTITY_CREATE_SESSION-V1'::text, 'ACT-IDENTITY_DELETE_SESSION-V1'::text, 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text, 'ACT-OPERATIONS_READ_OPERATION-V1'::text, 'ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text, 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text, 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text, 'ACT-POLICY_APPROVE_REQUEST-V1'::text, 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'::text])) OR (((source.document ->> 'schemaVersion'::text) = '3'::text) AND (lease.intent ? 'continuation'::text) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1'::text, 'ACT-IDENTITY_CREATE_SESSION-V1'::text, 'ACT-IDENTITY_DELETE_SESSION-V1'::text, 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text, 'ACT-OPERATIONS_READ_OPERATION-V1'::text, 'ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text, 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text, 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text, 'ACT-POLICY_APPROVE_REQUEST-V1'::text, 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'::text, 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'::text]))) OR ((source.source_purpose = 'PENDING_ADMINISTRATION_EXPIRY_RECOVERY'::text) AND ((source.document ->> 'schemaVersion'::text) = '4'::text) AND ((lease.intent -> 'pendingExpiry'::text) = (source.document #> '{source,pendingExpiry}'::text[])) AND ((openpc.current_action_intent_id() = ANY (ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_COLLECTION-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1'::text, 'ACT-IDENTITY_CREATE_SESSION-V1'::text, 'ACT-IDENTITY_DELETE_SESSION-V1'::text, 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text, 'ACT-OPERATIONS_READ_OPERATION-V1'::text, 'ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text, 'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'::text, 'ACT-PARTICIPANT_CREATE_MEMBER-V1'::text, 'ACT-POLICY_APPROVE_REQUEST-V1'::text, 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'::text])) OR ((lease.intent ? 'approvalContinuation'::text) AND (openpc.current_action_intent_id() = 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'::text)))))) OR (((source.document ->> 'schema'::text) = 'pc.identity.discovery-certificate-recovery-enrollment'::text) AND ((lease.intent ->> 'schema'::text) = 'pc.identity.discovery-certificate-recovery-intent'::text) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1'::text, 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'::text, 'ACT-IDENTITY_CREATE_SESSION-V1'::text, 'ACT-IDENTITY_DELETE_SESSION-V1'::text, 'ACT-IDENTITY_UPDATE_STEP_UP-V1'::text, 'ACT-OPERATIONS_READ_OPERATION-V1'::text, 'ACT-PARTICIPANTS_READ_RESOURCE-V1'::text, 'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'::text, 'ACT-POLICY_APPROVE_REQUEST-V1'::text, 'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'::text])) AND ((openpc.current_action_intent_id() <> 'ACT-APPROVAL_REQUESTS_UPDATE_RESOURCE-V1'::text) OR ((lease.intent ->> 'schemaVersion'::text) = '2'::text)))) AND (lease.state = 'ACTIVE'::text) AND (lease.valid_from <= clock_timestamp()) AND (lease.valid_until > clock_timestamp()) AND (lease.activation_operation_id IS NOT NULL) AND (lease.activation_evidence_cbor IS NOT NULL) AND (lease.activation_evidence_digest IS NOT NULL) AND (lease.activation_cose IS NOT NULL) AND (jsonb_typeof(lease.lease_bindings) = 'array'::text) AND (jsonb_array_length(lease.lease_bindings) = 2) AND (((source.root_expiry_recovery_id = root_expiry_recovery_scope.recovery_id) AND (source.platform_context_id = root_expiry_recovery_scope.platform_context_id) AND (source.root_epoch = root_expiry_recovery_scope.platform_authority_epoch) AND (source.root_digest = root_expiry_recovery_scope.admission_digest) AND ((source.document #>> '{source,activationOperationId}'::text[]) = (root_expiry_recovery_scope.activation_operation_id)::text)) OR (((jsonb_array_length((source.document #> '{source,ancestorReceipts}'::text[])) >= 1) AND (jsonb_array_length((source.document #> '{source,ancestorReceipts}'::text[])) <= 31)) AND (EXISTS ( SELECT 1
               FROM jsonb_array_elements((source.document #> '{source,ancestorReceipts}'::text[])) declared(value)
              WHERE (((declared.value ->> 'recoveryId'::text) = (root_expiry_recovery_scope.recovery_id)::text) AND (source.platform_context_id = root_expiry_recovery_scope.platform_context_id) AND (root_expiry_recovery_scope.platform_authority_epoch < source.root_epoch) AND ((declared.value ->> 'activationOperationId'::text) = (root_expiry_recovery_scope.activation_operation_id)::text)))))))))))) THEN false
    ELSE (EXISTS ( SELECT 1
       FROM control.authority_envelope e
      WHERE ((e.platform_context_id = root_expiry_recovery_scope.platform_context_id) AND openpc.matches_participant(e.participant_id) AND ((openpc.current_privacy_domain_id())::text = ANY (e.privacy_domain_ids)))))
END);


