--
-- Name: idempotency_record runtime_unsigned_withdrawal_provenance_read; Type: POLICY; Schema: control; Owner: openpc_control_owner
--

CREATE POLICY runtime_unsigned_withdrawal_provenance_read ON control.idempotency_record FOR SELECT TO openpc_control_owner USING ((openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND (openpc.current_action_intent_id() = ANY (ARRAY['ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'::text, 'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'::text])) AND (EXISTS ( SELECT 1
   FROM (control.configuration_work w
     JOIN control.runtime_target_disposition_admission a ON (((a.participant_id = w.participant_id) AND (a.privacy_domain_id = w.privacy_domain_id) AND (a.runtime_target_id = w.runtime_target_id) AND ((a.binding -> 'cause'::text) = jsonb_build_object('kind', 'Activation', 'work_id', (w.configuration_work_id)::text, 'operation_id', (w.operation_id)::text, 'execution_attempt_id', NULL::unknown)))))
  WHERE ((w.participant_id = idempotency_record.participant_id) AND (w.privacy_domain_id = idempotency_record.privacy_domain_id) AND (w.work_kind = 'RUNTIME_ACTIVATION'::text) AND (w.state = 'FAILED'::text) AND (w.execution_started_at IS NULL) AND (w.execution_attempt_id IS NULL) AND ((a.binding ->> 'action'::text) = 'Withdraw'::text) AND (a.activation_proof IS NULL) AND (a.restoration_proof IS NULL) AND (((a.binding -> 'source'::text) ->> 'original_work_id'::text) <> (w.configuration_work_id)::text) AND (w.predecessor_digest = ('sha256:'::text || ((a.binding -> 'source'::text) ->> 'capsule_digest'::text))) AND (idempotency_record.operation_id = w.operation_id) AND (NOT (EXISTS ( SELECT 1
