                                   FROM ( SELECT continuation_enrollment.enrollment_id
   FROM jsonb_to_recordset(( SELECT openpc.read_workload_credential_continuation_scope() AS read_workload_credential_continuation_scope)) continuation_enrollment(enrollment_id uuid)) current_custody) -> (enrollment.enrollment_id)::text)))::uuid AS jsonb_array_elements_text)))) decision)))))));


