                  WHERE ((decision_1.participant_id = enrollment.participant_id) AND (decision_1.privacy_domain_id = enrollment.privacy_domain_id) AND (decision_1.decision = 'APPROVE'::control.approval_decision) AND (decision_1.approval_request_id IN ( SELECT (jsonb_array_elements_text((( SELECT jsonb_object_agg((current_custody.enrollment_id)::text, to_jsonb(openpc.read_workload_credential_continuation_ids(current_custody.enrollment_id, 'APPROVAL'::text))) AS jsonb_object_agg
