          WHERE ((decision.approver_principal_id = mutation_evidence.principal_id) AND (decision.signer_credential_id = mutation_evidence.signer_credential_id) AND (decision.evidence_cbor = mutation_evidence.evidence_cbor) AND (decision.cose_sign1 = mutation_evidence.cose_sign1) AND (decision.mfa_challenge_id = mutation_evidence.mfa_challenge_id)))))))))));


