     CROSS JOIN LATERAL ( SELECT enrollment.workload_credential_id) source_key)
  WHERE ((enrollment.participant_id = outbox_event.participant_id) AND openpc.matches_privacy(enrollment.privacy_domain_id) AND (enrollment.privacy_domain_id = outbox_event.privacy_domain_id) AND (EXISTS ( SELECT 1
           FROM ( SELECT history_1.operation_id,
                    history_1.aggregate_type,
                    history_1.aggregate_id,
                    history_1.evidence_cbor,
                    history_1.evidence_digest,
                    history_1.cose_sign1
                   FROM jsonb_to_recordset((( SELECT jsonb_object_agg((current_custody.enrollment_id)::text, openpc.read_workload_credential_continuation_evidence(current_custody.enrollment_id)) AS jsonb_object_agg
